window.__TOEFL_DATA__=window.__TOEFL_DATA__||{};
window.__TOEFL_DATA__["data-origins"]=JSON.parse("{\"esteem\":\"来自拉丁语 aestimare「估价、估量」，经古法语 estimer 进入英语。先是「给人定价」，再变成「在心里给人打高分」——尊重本质上是一种高估值；self-esteem「自尊」就是给自己的估价。\",\"estrangement\":\"estrange 来自拉丁语 extraneus「外来的、外人的」（extra「在外」），它和 strange（陌生的）本是同一个词。把亲近的人变成「外人」，就是疏远；estranged 夫妻就是形同陌路的那一对。\",\"estuary\":\"来自拉丁语 aestuarium，与 aestus「潮汐、涌动」同源。河口湾的形状由潮汐冲刷而成：涨潮时海水倒灌、退潮时河水冲出，喇叭口就是这样被潮汐雕出来的。\",\"etching\":\"etch 来自荷兰语 etsen，源头是德语 ätzen「腐蚀」，而它又是 essen「吃」的使动形式——让酸去「吃」金属。酸液在铜版上咬出线条，印出来就是蚀刻版画。\",\"eternity\":\"来自拉丁语 aeternitas，词根 aevum 是「年代、永恒的时间」。希腊语对应的 aiōn 也是「时代」：eternity 不是一段很长的时间，而是跳出时间本身的「永远」。\",\"ethnicity\":\"来自希腊语 ethnos「民族、族群」+ -icity。ethnos 在希腊语里指「同族同俗的一群人」；ethnicity 是这份族群身份的属性。\",\"ethos\":\"直接借自希腊语 ēthos「性格、习惯、风气」。亚里士多德用它讲演说者的品格说服力；现在指一个机构、群体默认遵守的气质与信条。\",\"etiquette\":\"来自法语 étiquette，本义是「小标签、小牌子」。相传凡尔赛宫廷把规矩写在小卡片上发给臣仆——照着标签做就是礼仪；词义从「标签」变成了「成套规矩」。\",\"etymology\":\"来自希腊语 etymon「（词的）真实含义」+ -logia「学问」。etymon 源于 etymos「真实的」——词源学就是追查每个词真正的出身。\",\"eulogy\":\"来自希腊语 eulogia：eu-「好」+ logos「言辞」——「说好话」。本是祝福与赞美之词，后来专指葬礼、纪念场合上对逝者的颂词；它与 elegy（挽歌）拼写相近，但不是一回事。\",\"euphemism\":\"来自希腊语 euphēmismos：eu-「好」+ phēmē「说话」——「说好听的话」。把难听、犯忌的说法换成温和版就是委婉语；pass away 代替 die 是最经典的例子。\",\"euthanasia\":\"来自希腊语 euthanasia：eu-「好」+ thanatos「死亡」——「安详的死亡」。thanatos 是希腊神话里的死神；这个词在 17 世纪被用来专指无痛苦的死亡方式。\",\"evacuation\":\"来自拉丁语 evacuare：e-「出」+ vacuus「空的」——「把（地方）腾空」。vac「空」也在 vacuum（真空）、vacant（空缺的）里；疏散就是把建筑里的人清空。\",\"eventuality\":\"来自 eventual，而 event 源于拉丁语 eventus「发生的事」，词根是 venire「来」。eventuality 就是「将来可能来到你面前的那种情况」——一种先备着的可能性。\",\"evil\":\"来自古英语 yfel，日耳曼语固有词，词源细节有争议；它没有拉丁词根可拆，靠整体认读。两千年来它一直是 good 的头号反义词，词义从「恶劣」收窄到「邪恶」。\",\"exactness\":\"exact 来自拉丁语 exactus，是 exigere「彻底称量、逐项核验」的完成形态（ex- + agere「驱动、称量」）。古罗马人把东西逐项过秤核过才叫 exact——精确的本义是「称到位」。\",\"exaggeration\":\"来自拉丁语 exaggerare：ex- + agger「土堆、堤坝」——「往上堆、越堆越高」。把事实像堆土一样层层加高，就是夸张。\",\"exaltation\":\"来自拉丁语 exaltare：ex- + altus「高」——「举高、抬升」。地位被抬高是晋升与赞誉，情绪被抬高就是兴高采烈；altus 也在 altitude（海拔）里。\",\"exam\":\"examination 的缩略。examen 在拉丁语里一头是「天平的指针、称量」，一头是「蜂群」——考试取的是「称量」那头：把知识放上天平称一称。19 世纪学生俚语把它缩成了 exam。\",\"examination\":\"来自拉丁语 examinare「称量、逐项检验」，源头 examen「天平指针」。医生检查身体、考官检查试卷，都是同一台「天平」在逐项过秤。\",\"excavate\":\"来自拉丁语 excavare：ex- + cavus「空洞的」——「把里面掏空」。cavus 也在 cave（洞穴）里；考古挖掘就是把埋住的遗存一点点掏出来见光。\",\"excavation\":\"同 excavate：拉丁语 excavare「掏空」。名词形式既指挖掘工程本身，也指挖出来的遗址现场——特洛伊、兵马俑的发掘现场都叫 excavation site。\",\"excellence\":\"来自拉丁语 excellere「高出、胜过」，后半与 celsus「高耸」同源——在一群人里冒尖到最高就是卓越。注意它和 cell（细胞）只是拼写相近，没有关系。\",\"except\":\"来自拉丁语 exceptus，是 excipere「取出来、拿掉」的完成形态（ex- + capere「抓取」）。把某一个从整体里单独抓出来，就是「除外」。\",\"exception\":\"同 except：拉丁语 exceptio「取出、例外」。规则把大多数情况管住，个别被「取出来」另行处理，那就是 exception。\",\"excess\":\"来自拉丁语 excessus，是 excedere「走出去、越界」的名词（ex- + cedere「走」）。走出正常范围的那一截，就是「过剩、过度」；excess baggage 是超重行李。\",\"excitement\":\"excite 来自拉丁语 excitare「唤起、催动」，源头 ciere 是「使…动起来」。情绪被外力催起来、搅动起来，就是兴奋；同根的 cite 是「传唤、引用」。\",\"exclusion\":\"来自拉丁语 excludere：ex- + claudere「关闭」——「关在门外」。clud/clus「关」也在 include（关进来）、seclude（关起来隔离）里；排斥就是反着关。\",\"excrement\":\"来自拉丁语 excrementum，是 excernere「筛出、分拣出」的产物（ex- + cernere「筛、分」）。身体留下有用成分、把筛剩的废物排出去，就是排泄物。\",\"excuse\":\"来自拉丁语 excusare：ex- + causa「理由、案由」——「拿出理由把自己摘出去」。causa 也是 cause（原因）的祖先；名词作「借口」讲时重音前移。\",\"execution\":\"来自拉丁语 exsecutio，是 exsequi「跟到底、执行到底」的名词（ex- + sequi「跟随」）。先泛指把命令执行完，后来专指执行法院判决，最终收窄到「执行死刑」。\",\"executive\":\"同 execution 的词根 exsequi「执行到底」：executive 是「负责把决策执行到底的人」——公司高管；美国的 executive branch（行政分支）也是同一逻辑。\",\"exemplar\":\"来自拉丁语 exemplar「样本、模型」，源头 exemplum 是 eximere「从一堆里取出一件（作样品）」（ex- + emere「拿」）。被特意挑出来给大家看的那件，就是典范；sample（样品）也是 exemplum 的后代。\",\"exemption\":\"来自拉丁语 exemptio，是 eximere「取出、拿掉」的名词（ex- + emere「拿」）。义务人人有份，把你单独「取出来」不用承担，就是豁免；tax exemption 是免税。\",\"exercise\":\"来自拉丁语 exercere：ex- + arcere「圈住、关住」——本义是把牲口「赶出圈去使唤、操练」。从操练牲口到操练身体和头脑：练习、运动都是这一个词。\",\"exertion\":\"来自拉丁语 exserere：ex- + serere「连接、伸出」——「把（力气）使出来、伸出去」。exert oneself 是使出全身力气；exertion 就是这份使出来的劲。\",\"exhalation\":\"来自拉丁语 exhalare：ex- + halare「呼吸、吐气」——「把气呼出去」。halare 也在 inhale（吸入）里：一呼一吸，方向全在前缀上。\",\"exhaustion\":\"来自拉丁语 exhaurire：ex- + haurire「汲水、掏」——「把水一瓢瓢舀干」。力气像井水被舀空，就是精疲力竭；exhaust 也指发动机「排空」的尾气。\",\"exhilaration\":\"来自拉丁语 exhilarare「使高兴」，词根 hilaris「欢快的」（源于希腊语 hilaros）。把人逗到情绪起飞就是 exhilaration；hilarious（爆笑的）是它的近亲。\",\"exhortation\":\"来自拉丁语 exhortari：ex- + hortari「鼓励、敦促」——「使劲给人打气」。牧师的劝勉、教练的喊话都是 exhortation：用话把人往前推。\",\"exile\":\"来自拉丁语 exilium「流放」，exsul 是「被放逐的人」；词的后半来源学界尚无定论（有说法与「土地」或「流浪」有关，不宜当定论）。拿破仑两度被 exile，是这个词最有名的注脚。\",\"existence\":\"来自拉丁语 exsistere：ex- + sistere「站立」——「站出来、显现出来」，进而「存在」。sist「站」也在 resist（站回去对抗）、insist（站稳了坚持）里。\",\"exit\":\"来自拉丁语 exitus，是 exire「出去」的名词（ex- + ire「走」）。莎士比亚的剧本里 Exit 是舞台指示「（演员）下场」；今天的 exit 既是出口，也是「退出」。\",\"exodus\":\"来自希腊语 exodos：ex-「出」+ hodos「路」——「走出去的那条路」。因《圣经·出埃及记》得名，后来泛指人群大批离开；hodos 也在 method（沿路而行）里。\",\"expansion\":\"来自拉丁语 expandere：ex- + pandere「展开、铺开」——「向外铺开」。气体受热向外铺是膨胀，版图向外铺是扩张；expand 的名词形式就是 expansion。\",\"expectancy\":\"来自拉丁语 exspectare：ex- + spectare「看」——「伸着脖子往外看（等）」。等东西时眼睛盯着门外看：预期、期望都在这一眼里；life expectancy 是预期寿命。\",\"expectation\":\"同 expectancy：exspectare「向外张望、等待」。盼着看的东西还没到，心里先有了画面，就是 expectation；manage expectations 就是管理「预期」。\",\"expedience\":\"来自拉丁语 expedire：ex- + pes「脚」——「把脚从绳套里抽出来」，引申为「利索、权宜」。expedient 是当下管用的办法，对错另说，先脱身再说。\",\"expedition\":\"同 expedire「把脚抽出来（轻装上路）」：脚下没绊子，队伍走得快——远征、考察队都是轻装疾行；expedite（加速办理）也是这一家。\",\"expense\":\"来自拉丁语 expensa，是 expendere「称出（钱）付出去」的名词（ex- + pendere「称量、支付」）。古代付钱先上秤称银子的重量——称出去的，就是开支。\",\"experience\":\"来自拉丁语 experientia，是 experiri「尝试、亲历」的名词，词根 per-「试」与 peril（危险）、expert（行家）同源。亲身试过、趟过，才配叫经验。\",\"expertise\":\"expert 来自拉丁语 expertus「试用过的、经检验的」，与 experience 同根 per-「试」。在某个行当里反复试错试出来的本事，就是 expertise（专长）。\",\"expiration\":\"来自拉丁语 exspirare：ex- + spirare「呼吸」——「呼出最后一口气」。先指死亡（咽气），再引申为期限「气数已尽」：护照的 expiration date 是到期日。\",\"explanation\":\"来自拉丁语 explanare：ex- + planus「平的」——「把皱着的东西摊平」。把道理摊平摆出来，人人看得明白，就是解释；planus 也在 plane（平面）里。\",\"exploitation\":\"经法语 exploit 进入英语，源头是拉丁语 explicare「展开」的派生词——先指「开发利用（一块地、一个机会）」，19 世纪后染上「榨取」义：开发过了头就是剥削。\",\"exploration\":\"来自拉丁语 explorare「探查」；一说最早是猎人高声呼喊把野兽从林子里轰出来再细看（源头细节有争议）。从探地到探月，explore 的名词就是 exploration。\",\"explorer\":\"exploration 的「人」版：拉丁语 explorare「探查」+ -er。从马可·波罗到深海潜航员，explorer 指以探查未知为业的人。\",\"explosive\":\"来自拉丁语 explodere：ex- + plaudere「鼓掌、拍手」——本义是把烂演员「哄下台」（鼓掌喝倒彩）。那声「哄」后来转成爆炸声，名词便指炸药；与 explosion 同根。\",\"exposure\":\"来自拉丁语 exponere：ex- + ponere「放置」——「把东西摆到外面」。摆出去晒是暴露，摆给胶片是曝光，摆在风险面前就是风险敞口（financial exposure）。\",\"expression\":\"来自拉丁语 exprimere：ex- + premere「压」——「把里面的东西压出来」。想法被压成话是表达，情感被压到脸上是表情；espresso（意式浓缩）也是「压出来的」。\",\"expropriation\":\"来自拉丁语 expropriare：ex- + proprius「自己的、私有的」——「把私人的变成（公家的）」。政府依法征用民产叫 expropriation，与罚没性的 confiscation 相对。\",\"extension\":\"来自拉丁语 extendere：ex- + tendere「拉伸」——「向外拉长」。拉长空间是扩展，拉长时间是延期；电话分机是主线「拉出去的一截」，也叫 extension。\",\"extent\":\"来自拉丁语 extentus，是 extendere「向外拉伸」的完成形态。拉出去能到多远，就是程度与范围；to a large extent 字面就是「拉得很远」＝在很大程度上。\",\"exterior\":\"来自拉丁语 exterior，是 exter「在外面的」的比较级——「更靠外的」。建筑的外立面、行星的外层都用它；它的最高级 extremus 生出了 extreme（极端）。\",\"externality\":\"external 来自拉丁语 externus「外部的」（exter「外面」）。经济学把「交易双方之外的人承担的后果」叫 externality：工厂排污、邻里噪音都是外部性。\",\"extinction\":\"来自拉丁语 exstinguere：ex- + stinguere「刺灭、熄灭」——「彻底弄灭」。火灭了是熄灭，物种没了是灭绝，行为学里反应消失叫消退；distinguish 的 stingu 是同根的「刺出标记」。\",\"extinguisher\":\"extinguish + -er：「灭火的东西」。fire extinguisher（灭火器）是固定搭配；extinguish 的祖先是拉丁语 exstinguere「彻底熄灭」。\",\"extraction\":\"来自拉丁语 extrahere：ex- + trahere「拉」——「往外拉出来」。拔牙是 extraction，萃取咖啡精华也是 extraction；tract「拉」也在 tractor（拖拉机）里。\",\"extravagance\":\"来自拉丁语 extravagari：extra-「在外」+ vagari「游荡」——「游荡到正轨之外」。花钱游荡出预算的边界，就是奢侈挥霍；vagabond（流浪者）与它同根。\",\"extremity\":\"来自拉丁语 extremitas，源头 extremus「最外边的、最后的」。肢体的末端（手脚）叫 extremities，事态的最尽头叫 extremity（极端境地）。\",\"extremum\":\"直接借自拉丁语 extremum「最外端、极值点」，是 extremus 的中性名词形式。数学里函数取到的最大值、最小值统称 extremum（极值）。\",\"extrication\":\"来自拉丁语 extricare：ex- + tricae「纠缠、麻烦事」——「从纠缠里解出来」。把伤员从变形的车体里解救出来就是 extrication，比普通 rescue 更强调「解缠」。\",\"exuberance\":\"来自拉丁语 exuberare：ex- + uber「肥沃的、果实累累的」——「丰产到往外溢」。uber 本指丰产；热情多到溢出来，就是 exuberance。\",\"exultation\":\"来自拉丁语 exsultare：ex- + salire「跳」——「高兴得跳起来」。salire「跳」也在 assault（扑上去打）里；exult 是乐到蹦起来，还带着点得意。\",\"eyeball\":\"eye（眼，古英语 ēage）+ ball（球）的复合词。眼球圆如球，老老实实叫 eyeball；俚语 eyeball it 是「目测」。\",\"eyebrow\":\"古英语复合词 ēag-brū：「眼睛上方的眉脊」。brū 本指眉毛兼额脊；眉毛长在眼睛上方如一道梁，就是 eyebrow。\",\"eyelash\":\"eye + lash。lash 的老义是「鞭梢、抽打」（词源细节有争议），睫毛一根根像细鞭梢排在眼睑边，就是 eyelash；lash 作动词「抽打」是同一个词。\",\"eyelid\":\"eye + lid。lid 是古英语 hlid「盖子」——眼皮就是眼睛自带的盖子，眨眼就是开盖合盖。\",\"eyesight\":\"eye + sight。sight 是古英语 sihþ，与 see（看）同根：「看的能力」就是视力；eyesight 变差，就是这项能力在掉。\",\"eyewitness\":\"eye + witness（作证者）。witness 源于古英语 witnes「知道、见证」，与 wit「心智」同根——亲眼见过、能出庭作证的人是 eyewitness，与听来的 hearsay 相对。\",\"fable\":\"来自拉丁语 fabula「故事、谈话」，词根 fari「说」——「说出来的故事」。伊索寓言是 fable 的标杆：短、带动物、结尾一句教训；fabulous（极好的）源于「传说中的」。\",\"factory\":\"来自拉丁语 factor「制作者、经手人」（facere「做」）的名词形式：先是商行在海外的「代理处」，工业革命后变成集中生产的工厂。\",\"fantasy\":\"来自希腊语 phantasia「想象、显现」，词根 phainein「使显现」——「只在脑子里显现的东西」。phenomenon（现象）与它同根：一个显现在外，一个显现在心。\",\"farm\":\"经古法语 ferme 来自中世纪拉丁语 firma「固定付款、租约」：早年农场是按固定租金租来的地。后来 farm 从「租约」变成了「农场」本身。\",\"farmer\":\"farm + -er。词源上 farm 是「租地契约」（拉丁语 firma「固定付款」）：交租种地的人就是 farmer；后来地归农民所有，词义跟着留了下来。\",\"fatal\":\"来自拉丁语 fatalis，源头 fatum「命运、天命」，而 fatum 是 fari「说」的产物——「（神）说出口的定数」。命里注定的结局多半要命，于是 fatal 成了「致命的」。\",\"faucet\":\"来自中古法语 fausset，原指管口的「小塞子」：关上时把水塞住，拧开就放水。美式英语用它专指这种带开关的水龙头，英式多说 tap。\",\"fear\":\"古英语 fǣr，本义是「突如其来的危险、伏击」，后来才变成「害怕（的情绪）」。词义从外在的危险挪进了心里；德语 Gefahr（危险）与它同源。\",\"feedback\":\"feed（喂入）+ back（返回）的复合词，20 世纪电子工程的造词：把输出信号「喂回去」修正系统。后来泛化到意见反馈：把反应喂回给做事的人。\",\"fence\":\"defence 的缩略：中古英语把 defence 的头砍掉，剩下的 fens 成了 fence。栅栏的本职是「防御」；击剑 fencing 也从「攻防之术」来，同一词根 fendere「击打、抵挡」。\",\"fencing\":\"fence（防御、击剑术）+ -ing。源头拉丁语 fendere「击打、抵挡」：击剑就是攻防格挡之术；作「栅栏」讲时是 fence 的另一路用法，本卡取击剑义。\",\"ferris\":\"Ferris wheel 的简称，以美国工程师 George W. G. Ferris 命名——他为 1893 年芝加哥世博会造了第一座 80 多米高的巨型摩天轮。人名进词典，全靠这一座轮。\",\"festival\":\"来自拉丁语 festivalis，词根 festum「节日、宴席」——「大吃大喝庆祝的日子」。festum 也在 feast（盛宴）里；festival 先是宗教节庆，后来电影节、音乐节都用它。\",\"feudal\":\"来自中世纪拉丁语 feudum「封地、采邑」，源头是日耳曼语「牲畜＋财产」——最早的财产就是牛羊。领主以封地换效忠，就是封建制。\",\"field\":\"古英语 feld「开阔地」，日耳曼语老词。先是田野，后来一切「专门场地」都是 field：球场、磁场、研究领域。\",\"fig\":\"经法语来自拉丁语 ficus「无花果（树）」。地中海的老果树；习语 not care a fig 是「毫不在乎」——无花果曾经便宜得不值钱。\",\"film\":\"古英语 filmen「薄膜、皮膜」，本指动物身上的一层膜。19 世纪摄影术把涂了感光药膜的胶片叫 film，放映的影像沿用至今：film 先是「膜」，再是「电影」。\",\"finch\":\"古英语 finc，日耳曼语词，多认为是模仿这类小鸟叫声的拟声词。燕雀、朱顶雀都归 finch；达尔文在加拉帕戈斯群岛观察的就是 Darwin's finches。\",\"fine\":\"本卡指「罚款」：来自拉丁语 finis「终点、了结」——罚款是把案子「了结」要付的钱（经法语 fin「终了、结算」）。形容词 fine「精细的」是另一条线：做到位就是精致。\",\"finger\":\"古英语 finger，日耳曼语固有词（一种说法与 five 有关，但未成定论）。五根指头里它是最踏实的老词，没有拉丁词根可拆，整体认读。\",\"firefighter\":\"fire + fight + -er 的复合词，19 世纪出现——「与火搏斗的人」，直白命名。职业消防体系成形后，这个词成了消防员的正式称呼。\",\"firefly\":\"fire + fly 的复合词：屁股上带着「火」的飞虫。它发的光是荧光素氧化的冷光，不烫手；古人叫它 firefly，字面就是「火飞虫」。\",\"fireworks\":\"fire + works 的复合词。works 在这里是「制品、装置」：用火做的装置就是烟花；火药术从中国经阿拉伯传入欧洲后，这个词才出现。\",\"fisherman\":\"fisher（古英语 fiscere「渔者」）+ man 的复合。fish 本身是古英语 fisc，日耳曼语老词；靠打鱼为生的人，英语用最直白的拼法命名。\",\"fishing\":\"fish + -ing。古英语 fisc 是日耳曼语固有词，与拉丁语 piscis（鱼）是印欧语远亲——双鱼座 Pisces 就是那位远亲；钓鱼、渔业都从 fish 长出来。\",\"fist\":\"古英语 fȳst，日耳曼语词，常与 five 联系：五指攥紧成一团就是拳头（是否同源，学界有争议）。握紧的手形本身就是词义。\",\"flamingo\":\"经西班牙语、葡萄牙语 flamengo 进入英语，源头是拉丁语 flamma「火焰」——「火焰色的（鸟）」。它羽毛的粉红来自食物中的类胡萝卜素，与词源的「火色」正好呼应。\",\"flashlight\":\"flash（闪光）+ light（光）的复合词，19 世纪末随干电池发明而造：按一下就闪出光的手持灯。英式英语叫 torch（火炬），词源各表一枝。\",\"flea\":\"古英语 flēah，多认为与 flee「逃跑」同族——跳蚤是「一碰就逃没影的家伙」。它能跳体长上百倍的距离，名字先夸了它的逃技。\",\"flee\":\"古英语 flēon，日耳曼语词，与 fly（飞）同源——逃跑就是「飞一样地离开」。flee 是不规则动词（flee–fled–fled），常与 flee from 连用。\",\"floor\":\"古英语 flōr「地面」，日耳曼语词。先是屋里的地面，后来一层楼也叫 floor——你站的那层地面，就是那一层楼。\",\"flour\":\"与 flower 是同一个词！中古英语里 flour 是 flower 的变体，本义「谷物之花（筛出的最精细部分）」。后来拼写分家：flower 管花，flour 专管面粉——两词同音又同源。\",\"fluctuation\":\"来自拉丁语 fluctuare「起伏如波浪」，词根 fluctus「波浪」源于 fluere「流」。价格、体温像水面一样上下晃，就是 fluctuation；它是 flu「流」家族的一员。\",\"flute\":\"经古法语 flaute 进入英语，更早来源不确定（可能与拉丁语 flare「吹」有关，学界无定论）。长笛靠吹气过孔发声，词源虽模糊，「吹奏」的大方向没错。\",\"fly\":\"作名词「苍蝇」讲时，是古英语 flēoge——「会飞的（那个东西）」，与 fly「飞」同源。英语把最常见的飞虫直接命名为「飞者」，苍蝇就这样得了名。\",\"fold\":\"古英语 fealdan「折叠」，日耳曼语老词。动词的折叠与表示倍数的 -fold（twofold「两倍」）都从「叠起来」长出来；名词 fold「羊圈」是另一条线，指围拢牲口的地方。\",\"folder\":\"fold + -er：「把纸折起来（夹住）的东西」。先指对折的硬纸夹，后来电脑里的文件夹借用了同一个比喻——都是把文件收拢归置的容器。\",\"folklore\":\"1846 年由英国学者 William Thoms 造的词：folk「民众」+ lore「口传知识、学问」，专门用来替代冗长的 popular antiquities。lore 与 learn 同源：民间口口相传的学问就是民俗。\",\"forehead\":\"古英语复合词 forhēafod：fore-「前面」+ hēafod「头」——「头的前面」。它的传统读音把后半弱化成 /ˈfɒrɪd/，是拼写与发音分家的老例子。\",\"forestry\":\"forest 经法语来自中世纪拉丁语 forestis（silva）「（王室的）围墙外林地」，源头 foris「门外」——王室把城墙外的大片林地圈作猎场，forest 由此而来；forestry 是经营这片林子的学问。注意 forest 不是 fore- 前缀，别拆错。\",\"forgetting\":\"forget 来自古英语 forgetan：for-「偏离、失去」+ getan「抓、得」——「抓不住、从手里滑走」就是遗忘。forget 是「得而复失」，与 forgive 里的 for- 是同一种手法。\",\"fork\":\"经古英语 forca 来自拉丁语 furca「（两股的）叉、耙」。先是农具草叉，后来餐叉、路的岔口、代码的分支（GitHub 上的 fork）全用它——形状都是「一股分两股」。\",\"fortress\":\"经古法语 forteresse 来自拉丁语 fortis「强壮的」——「强固之地」。fort「堡垒」、fortify「加固」与它同源；fortress 专指大型要塞。\",\"founder\":\"本卡指「创始人」：来自拉丁语 fundare「打地基、建立」，词根 fundus「底部」——先打地基，才能立起事业。注意另有动词 founder「（船）沉没、失败」，经古法语 fondrer「沉到底」而来，追到底同样回到 fundus，算殊途同归。\",\"fox\":\"古英语 fox，日耳曼语固有词，更深来源未定（可能与「尾巴、毛」有关）。英语里 fox 引申「狡猾的人」已有上千年；雌狐 vixen 是少见的古英语阴性词尾遗存。\",\"framework\":\"frame（框架，源于古英语 framian「构成、起作用」）+ work 的复合词。先指木器的骨架结构，后来抽象成理论框架、软件框架：先有骨架，再往里填东西。\",\"franchise\":\"来自古法语 franchise「自由、特权」，源头 franc 是「法兰克人；自由民」——法兰克人是高卢的自由统治者。特许经营权本质上是「被官方授予的自由经营权」。\",\"franchisee\":\"franchise + -ee「被…的人」：被授予特许权的一方就是加盟商。-ee 是经法语借来的被动后缀，与 employee（被雇者）、trainee（受训者）同一套路。\",\"fraud\":\"来自拉丁语 fraus「欺骗、损害」（属格 fraudis）。词义两千年没漂移：fraud 一直是「以欺骗手段谋利」；fraudulent 是它的形容词。\",\"freeway\":\"free（免收费）+ way（路）的美国造词（20 世纪）：不收费的汽车专用快速路，与收费的 tollway 相对。这里的 free 是「免费」，不是「自由」。\",\"freezer\":\"freeze + -er。freeze 是古英语 frēosan「结冰」，日耳曼语老词，与 frost 同根。能把东西冻住的柜子就是 freezer，冰箱的冷冻室也用它。\",\"fresco\":\"来自意大利语 fresco「新鲜的」：趁石灰灰泥还没干（新鲜湿润时）把颜料画上去，颜料与墙面长在一起，就是湿壁画。fresco 的源头是日耳曼语「新鲜」，是 fresh 的意大利亲戚。\",\"fridge\":\"refrigerator 的口语缩略（20 世纪初），为了贴合发音硬加了一个 d。refrigerator 源于拉丁语 refrigerare「使冷却」，词根 frigus「寒冷」也在 frigid（严寒的）里。\",\"fruit\":\"经法语来自拉丁语 fructus「果实、收成」，源头 frui「享用」——「土地供人享用的出产」。先泛指一切农产，后收窄到水果；fruct 还在 fructose（果糖）里活着。\",\"furniture\":\"来自法语 fourniture「配备、供给」，源头 fournir「供应」（日耳曼语出身）。家具就是「给房子配齐的东西」；英语里它是不可数名词，一件家具要说 a piece of furniture。\",\"furthermore\":\"further（更进一步）+ more（更）的叠合副词，字面「再往前添一点」：论证里追加新论据时用它，与 moreover 几乎同义，语气更正式。\",\"gallbladder\":\"gall（胆汁，古英语 gealla，与「黄」同源——胆汁是黄的）+ bladder（囊，古英语 blǣdre）的复合词。装胆汁的囊就是胆囊；gall 也引申「苦胆、厚脸皮」。\",\"gallery\":\"经法语来自中世纪拉丁语 galeria「长廊、画廊」，更早来源有争议。回廊里挂画展出，就是画廊；剧场观众席的顶层也叫 gallery。\",\"game\":\"古英语 gamen「欢乐、游戏」，日耳曼语词（一种分析认为是「大家一起」+「人」，细节有争议）。猎物也叫 game：打猎曾经是头号游戏。\",\"garage\":\"来自法语 garage，动词 garer 是「（把车）停放、庇护」，源头为日耳曼语「看管」——与 guard、guarantee 是远房亲戚。先指车库，后也指修车行。\",\"garbage\":\"来源不完全确定：多认为经盎格鲁-法语而来，原指筛剩的杂物、下水与禽类内脏等厨余。词义从「厨余」扩大到一切垃圾（此说流传最广，但未成定论）。\",\"garden\":\"经法语 jardin 来自日耳曼语「围起来的地方」，与 yard 同根。先有篱笆围地，才有花园；《圣经》里的 Garden of Eden 也是「围起来的园子」。\",\"garlic\":\"古英语复合词 gārlēac：gār「矛」+ lēac「韭葱」——「矛一样的韭葱」：蒜叶尖尖如矛。leek 是它的后半，至今单指韭葱。\",\"gate\":\"古英语 geat「开口、门洞」，日耳曼语词，与 gap（缺口）同源。gate 先是城墙、院落的出入口，后来机场登机口、逻辑门电路都借它——都是「受控的通道口」。\",\"generalization\":\"general 来自拉丁语 generalis，词根 genus「种类、出身」——「属于整个种类的」。generalize 是从个别跳到「全类」；名词化就是 generalization（泛化、概括）。\",\"gerbil\":\"来自法语 gerbille，是 gerboise（跳鼠）的指小形式，最终源于阿拉伯语 yarbūʿ「跳鼠」。沙鼠的名字一路经阿拉伯语、法语才到英语。\",\"ginger\":\"经拉丁语 zingiber、希腊语 zingiberis，最终来自南亚语言（与梵语的姜名有关，一说源于泰米尔语）——姜顺着香料贸易路线西行，名字也一路被转手改写。\",\"gladiator\":\"来自拉丁语 gladiator，词根 gladius「短剑」——「持剑者」。罗马角斗士的主武器是短剑 gladius；剑兰（gladiolus）也因叶子像剑得名。\",\"glance\":\"来源有争议：多认为与古法语 glacier「滑行」、glace「冰」有关——目光像在冰面上滑过去一样一扫而过。词义核心是「快而斜的一眼」。\",\"gland\":\"来自拉丁语 glans「橡子」（属格 glandis）：早期解剖学家觉得某些腺体的形状像橡子，就借了这个名字。橡子与腺体，是靠形状认的亲。\",\"glare\":\"中古英语 glaren「耀眼地闪、瞪视」，与 glass、glow 同属日耳曼语「发亮」家族（具体来源有争议）。强光刺眼是 glare，怒目而视也是 glare——都是「瞪着发亮」。\",\"glass\":\"古英语 glæs，日耳曼语词，与一批「发亮」的词同族：玻璃因透亮得名。本卡指玻璃杯：英语常用材料名代容器，a glass of water 是「一杯水」。\",\"glasses\":\"glass 的复数转义：两片玻璃镜片组成的器物叫 glasses。这类「双件」名词在英语里都用复数：scissors、trousers 同理；「一副眼镜」要说 a pair of glasses。\",\"glove\":\"古英语 glōf，日耳曼语词，可能含「手掌」成分（构词细节有争议）。手套是手的「外套」；习语 fit like a glove 是「严丝合缝」。\",\"goat\":\"古英语 gāt（本指母山羊），日耳曼语老词，与拉丁语 haedus「小山羊」是印欧语远亲。scapegoat（替罪羊）是 goat 家族最有名的习语。\",\"god\":\"古英语 god，日耳曼语老词，来源有争议（一说与「被呼唤、被祭祀者」有关）。基督教传入后，god 从「泛指神祇」升格为专指唯一神，首字母随之大写。\",\"goddess\":\"god + -ess（阴性后缀，来自希腊语 -issa，经拉丁语、法语传入）。14 世纪才出现的词：先有 god，后配阴性；actress、waitress 的 -ess 是同一后缀。\",\"golf\":\"来源未定论：最常被提的是荷兰语 kolf「球杆」（流传最广但无确证）；15 世纪苏格兰文献里已有 golfe 的身影。牧羊人赶石子入洞是传说，不能当词源讲。\",\"goose\":\"古英语 gōs，日耳曼语词，与拉丁语 anser、希腊语 chēn 同出印欧语「鹅」的老词根——鹅叫声跨欧亚都差不多。复数 geese 是古英语元音屈折的遗存。\",\"gorilla\":\"来自希腊语 Gorillai——公元前 5 世纪迦太基航海家汉诺记载的非洲「毛人部落」之名。1847 年科学家给新发现的大猿借了这个古名，gorilla 由此复活。\",\"government\":\"govern 来自拉丁语 gubernare「掌舵、驾驶」，源头是希腊语 kybernaō「掌舵」——治理国家如掌舵行船。控制论 cybernetics 与它同根：都是「掌舵术」。\",\"governor\":\"同 govern：拉丁语 gubernator 本义就是「舵手」。州长是「掌舵一州的人」；发动机上的 governor（调速器）也是给机器转速「掌舵」的装置。\",\"gps\":\"Global Positioning System（全球定位系统）的首字母缩略。20 世纪 70 年代由美国军方建成：卫星在头顶组网，接收器靠信号时间差算出位置——名字就是系统全称的缩写。\",\"grab\":\"来自中古低地德语、荷兰语 grabben「抓」，与 grasp、grope 同属日耳曼语「抓握」家族。动作快而粗；grab a bite 是「抓紧吃一口」。\",\"grade\":\"来自拉丁语 gradus「步子、台阶、等级」，词根是 gradi「行走」——知识像台阶一级一级往上：年级、等级、坡度都是 gradus。graduate 的「毕业」是走完台阶。\",\"graduation\":\"graduate 来自中世纪拉丁语 graduari「取得学位」，源头 gradus「台阶」。毕业典礼是「走完学业台阶、被授予学位」的那一刻。\",\"grain\":\"来自拉丁语 granum「谷粒、种子」。一粒谷是一 grain，一粒沙、一粒盐都借它；木材的纹理 grain 是「粒状走向」的引申。granary（粮仓）、granite（花岗岩）与它同根。\",\"granary\":\"来自拉丁语 granarium「粮仓」，词根 granum「谷粒」——「存谷粒的地方」。罗马时代的大粮仓是城市的命脉。\",\"grape\":\"来自古法语 grape「一串葡萄；钩子」，源头是日耳曼语的「钩」——采葡萄先用钩子把藤串钩下来。grape 先指「一串」，后指单颗；grapevine 是葡萄藤，也是「小道消息」。\",\"grapefruit\":\"grape + fruit 的复合词，18 世纪在巴巴多斯得名：果子像葡萄一样成串挂在树上，所以叫「葡萄（串）果」。它与 grape 本身没有亲缘，是柚子与甜橙的杂交后代。\",\"grasp\":\"中古英语 graspen，来源有争议，可能与 grab、grope 同族（日耳曼语「摸索着抓」）。抓牢实物是 grasp，抓牢要领是 grasp the point——手与脑用同一个词。\",\"grasshopper\":\"grass（草）+ hopper（跳者）的复合词，古英语就有了——「在草里跳的」。蚱蜢靠后腿弹跳，老家就在草丛，名字直白到透明。\",\"greenhouse\":\"green（绿）+ house（房）的复合词，17 世纪出现：种满绿色植物的玻璃房。20 世纪 greenhouse effect（温室效应）让它成了气候词：气体如玻璃罩，让地球留热。\",\"grip\":\"古英语 gripe「抓握」，与 grasp、grope 同属日耳曼语「抓」家族。名词是「握力、把手」，动词是「紧紧抓住」；故事的情节 grip 住读者，也是这个「抓」。\",\"grizzly\":\"来自 grizzle「花白、灰白」（古法语 grisel，与「灰」有关）：灰熊的毛梢灰白，像花了的头发。它与 grisly「可怕的」拼写相近，但不是一回事。\",\"grocery\":\"源于中古英语 grosser「批发商」（法语 grossier），卖的是 gross「整批、大宗」的货。批发转零售后，grocery 成了杂货店；groceries 是店里日杂食品的总称。\",\"grove\":\"古英语 grāf「小树林」，日耳曼语词。grove 多指小而整齐的林子（orange grove 是橙园）；比 forest 小，是英语风景诗的常客。\",\"growth\":\"grow（古英语 grōwan「生长」，与 grass、green 同根，都是「发绿芽」）+ -th 名词后缀。经济增长、作物生长都用 growth——凡是「长大」的过程都算。\",\"guarantee\":\"经法语 garantie 来自日耳曼语 *warant「保证人、凭证」（与 warrant 同源）：有人出面作保，交易才敢做。guarantee 先是「担保人」，后指担保本身。\",\"guard\":\"经古法语 garde 来自日耳曼语 *wardōn「看守、留神」——英语本土的同源词是 ward（看守；病房）。守夜、站岗、警卫，核心动作是「盯着看，护住」。\",\"guest\":\"古英语 giest「客人、陌生人」，与拉丁语 hostis「外人、敌人」、host「主人」同出印欧语 *ghosti-「外来者」：同一个外来者，被招待是 guest，起了冲突就是敌人。\",\"guitar\":\"经西班牙语 guitarra、阿拉伯语一路传自希腊语 kithara「基萨拉琴」（古代的一种竖琴）。琴名从希腊出发，绕地中海一圈传遍世界。\",\"gum\":\"本卡指牙龈：古英语 gōma「上颚、口腔顶部」，日耳曼语词。注意另一个 gum「树胶」来自拉丁语 gummi，两词同形不同源——牙龈的 gum 是土生土长的。\",\"gunpowder\":\"gun（枪炮，来源有争议）+ powder（粉末，来自拉丁语 pulvis「尘土」）的复合词。火药 9 世纪源于中国炼丹术，经阿拉伯传入欧洲；powder 至今还管一切「粉」。\",\"gustatory\":\"来自拉丁语 gustare「品尝、尝味」+ -atory。gustus 是「味觉」；disgust（厌恶）本义是「口味不对」——难吃到心里，就是恶心。gustatory 是「味觉的」的学术说法。\",\"gym\":\"gymnasium 的缩略：希腊语 gymnasion「锻炼场所」，源头 gymnos「裸体的」——古希腊运动员裸身训练。gymnasium 先指训练场，后指体育馆；gym 是 19 世纪末的口语缩略。\",\"gymnastics\":\"同 gym：希腊语 gymnastikē「裸身训练之术」（gymnos「裸体」）。古希腊人把跑跳摔跤的裸身操练发展成体系，就是今天体操的前身。\",\"hacker\":\"hack（砍、劈，古英语 haccian）+ -er。先指「乱砍的人」；1960 年代 MIT 学生把「钻研系统、玩出花样」叫 hack，hacker 成了技术高手；1980 年代媒体又给它加上「入侵者」义。\",\"hairdresser\":\"hair（头发，古英语 hǣr）+ dresser（装扮者）的复合词。dress 在这里是「整理、装扮」：给头发做造型的人；偏造型的 hairdresser 与偏剪发的 barber（理发师）分工不同。\",\"hallucination\":\"来自拉丁语 alucinari「神志恍惚、像做梦一样胡说」，更深来源不确定。大脑把不存在的信号当真，就是幻觉；AI 圈借这个词说模型「一本正经地胡编」，也是同一画面。\",\"ham\":\"古英语 hamm「腿弯、腘窝」：猪后腿连腿弯的那块肉就是 ham（火腿）。它与 hamlet「小村庄」里的 ham（家园）同形不同源，别串门。\",\"hamlet\":\"经法语 hamelet 而来，是「小村庄」的指小形式，源头是日耳曼语 *haim「家园、村庄」（与 home 同根）。莎士比亚借同形的人名 Hamlet 写了王子，村庄与王子各走各的。\",\"hammer\":\"古英语 hamor「锤子」，日耳曼语词，可能与「石头」有关（最早的锤子是石锤，此说有争议）。拍卖师的落槌、法官的法槌都叫 hammer。\",\"hamster\":\"来自德语 Hamster，源头是古高地德语 hamustro，更远的来源可能与斯拉夫语有关（细节未定）。仓鼠颊囊塞满食物的样子太出名，德语词被英语直接借走，没翻译。\",\"hang\":\"由古英语 hōn（及物「悬挂」）与 hangian（不及物「垂着」）两条线在中古英语合并而来——少见的双源动词。悬挂、绞刑、hang out（闲逛）都从「吊着」长出来；hanged 专指绞刑，hung 是常态。\",\"harbor\":\"古英语 herebeorg「军队营地、庇护所」：here「军队」+ beorg「庇护」。先庇护人，后庇护船：给船挡风浪的港湾就是 harbor；harbour 是英式拼写。\",\"hardware\":\"hard（硬）+ ware（器物、货品）的复合词。先指铁器五金（钉子、锁、工具），20 世纪计算机借它指「硬」的那部分设备，与 software（软件）成对。\",\"hare\":\"古英语 hara，日耳曼语词，一说与「灰」有关（野兔毛色灰褐，此说未定）。hare 比 rabbit 大、腿更长；龟兔赛跑里的就是 hare，它输在打盹。\",\"harmonica\":\"由 harmony 派生：19 世纪，人们以希腊语 harmonia「和声」给这类簧片乐器命名（富兰克林的玻璃 harmonica 在先）。口琴靠簧片发声，名字取的就是「和声」。\",\"harmony\":\"来自希腊语 harmonia「接合、契合、和声」，源头 harmozein「拼合、装配」——木匠把木板严丝合缝拼好，就是 harmonia。音与音拼得合是和声，人与人拼得合是和谐。\",\"harp\":\"古英语 hearpe，日耳曼语老词，更深来源未定（可能与「抓、拨」有关）。竖琴是欧洲最古老的乐器之一；爱尔兰把 harp 奉为国家象征，硬币上印的就是它。\",\"harvest\":\"古英语 hærfest 本义就是「秋天」（一说与拉丁语 carpere「摘取」印欧同源）。先指季节，后专指秋天的收割：季节名变成了农事名，autumn 后来才接管「秋天」。\",\"hat\":\"古英语 hætt，日耳曼语词，与 hood 同族（都是「盖头的东西」）。hat 有帽檐，cap 偏软无檐，hood 连着衣服——英语按「盖法」分帽子。\",\"hazelnut\":\"hazel（榛树，古英语 hæsel）+ nut（坚果）的复合词。榛子是榛树的果；hazel 也形容「淡褐色」，hazel eyes 是榛色眼睛。\",\"heart\":\"古英语 heorte，日耳曼语词，与拉丁语 cor、希腊语 kardia 同出印欧语的老词根「心」——cardiac（心脏的）就是那位希腊亲戚。heart 既是器官，也是情感与核心。\",\"hedgehog\":\"hedge（树篱）+ hog（猪）的复合词，15 世纪得名：常在树篱下出没、鼻子像猪一样拱来拱去的小兽。名字说的是它的出没地和长相。\",\"heel\":\"古英语 hēla，是 hōh「脚跟」的派生词。神话里的 Achilles' heel（阿喀琉斯之踵）让 heel 兼指「致命弱点」；鞋跟也是它。\",\"hen\":\"古英语 henn，是 hana「公鸡」的阴性形式。hana 与拉丁语 canere「歌唱」同源——公鸡是「唱歌的」，母鸡是它的阴性版；鸡鸣报晓，名从嗓门来。\",\"hence\":\"来自古英语 heonan「从这里、从此」的中古形式再加状语词尾。先指空间「从此地」，转时间「从今」，再转逻辑「因此」——从地点一路走到结论。\",\"herb\":\"经法语来自拉丁语 herba「草、青苗」。先泛指一切草本，后专指入药、调味的草：草药、香草都算 herb；美式发音常把 h 吞掉，读 /ɜːrb/。\",\"hereditary\":\"来自拉丁语 hereditarius，源头 heres「继承人」——「随继承传下去的」。王位、爵位是世袭的，基因性状也是「继承」来的：heredity 是遗传。\",\"heroine\":\"hero 的阴性形式：希腊语 hērōs「英雄、半神」经拉丁语、法语传入，再加阴性后缀 -ine。注意与毒品 heroin 只差一个 e：heroin 是德国拜耳公司当年的商标名，两词无关。\",\"heuristic\":\"来自希腊语 heuriskein「发现、找到」——阿基米德跳出浴缸喊的 Eureka（我发现了！）就是它的第一人称完成时。启发式就是「帮你快速找到答案」的方法。\",\"hide\":\"本卡指「躲藏」：古英语 hȳdan，日耳曼语词。注意另一个 hide「兽皮」（古英语 hȳd）与它同形：skin 偏指人皮，hide 专指厚兽皮；躲藏与兽皮来源不同，别混。\",\"hieroglyph\":\"来自希腊语 hieroglyphos：hieros「神圣的」+ glyphē「雕刻」——「神圣的刻字」。古埃及文字多刻在神庙石壁上，希腊人这样命名；罗塞塔石碑帮助后人破译了它。\",\"highway\":\"high（主要的、干线）+ way（路）：high 在这里是古义「首要的」，highway 是「大道、干道」，与乡间小路相对。旧时专在大道上拦路抢劫的强盗就叫 highwayman。\",\"hiking\":\"hike 来源不确定，18 世纪才出现，可能与方言里「猛拉、攀行」的词有关。徒步远足是 20 世纪兴起的大众运动；hike 兼指「（价格）猛涨」，步子都迈得大。\",\"hip\":\"古英语 hype，日耳曼语词（与 hop 的关系未定论）。hip 既是臀部也是髋关节；俚语 hip「时髦」是另一个来路的词，别混。\",\"hippo\":\"hippopotamus 的缩略：希腊语 hippopotamos = hippos「马」+ potamos「河」——「河里的马」。古希腊人没见过这种动物，只好拿最熟的马加河拼名；河马与马并无亲缘。\",\"historian\":\"history 来自希腊语 historia「调查、求知」，源头 histōr 是「查明真相的人、裁判」。历史学家先是「调查者」：希罗多德的《历史》原名 Historiai，就是「调查录」。\",\"hit\":\"古英语 hittan「遇上、碰上」，多认为借自古诺尔斯语 hitta「找到、碰上」。从「碰上目标」到「击打」，再到「爆款热歌」（a hit），都靠「正中目标」这一条线。\",\"hockey\":\"来源不确定：常与古法语 hoquet「牧羊人的弯杖」联系——球杆顶端带弯，正像牧杖（此说未定论）。冰球 hockey 是它在冰上的版本，19 世纪定型于加拿大。\",\"hoe\":\"经法语 houe 来自日耳曼语「砍削的工具」，与 hew「砍」同根。锄头干的活就是砍土、松土，名字跟着动作走。\",\"homework\":\"home（家）+ work（作业）的复合词，19 世纪学校教育普及后定型。把功课带回家做，在普及教育之前并不常见；homework 也引申为「事先做的功课」（do your homework）。\",\"honey\":\"古英语 hunig，日耳曼语词，可能与「金黄色」有关（未定论）。蜜蜂酿的甜浆；honey 也是亲昵称呼——甜的东西总被借去叫人。\",\"honeydew\":\"honey（蜜）+ dew（露水）：本义是昆虫分泌在叶面上的「蜜露」；蜜瓜（honeydew melon）因果肉甜润如蜜露得名。\",\"hornet\":\"古英语 hyrnet，更深来源未定论（与 horn 的关系只是猜测）。大黄蜂体长可达 5 厘米，是 wasp 家族的大块头；名字先放一边，词源上诚实标注存疑。\",\"horse\":\"古英语 hors，日耳曼语词，来源有争议（一说与「跑」有关，未定论）。horsepower（马力）是瓦特定下的单位：一匹马一分钟能做的功，用来给蒸汽机打比方。\",\"hospital\":\"来自拉丁语 hospes「主人；客人」派生的 hospitale「客房、收容所」——先收留朝圣者与穷人，后专收病人。hospital、hotel、hostel、host 是同一位祖先的后代。\",\"host\":\"来自拉丁语 hospes「主人；客人」——一个词管两头：招待人的和上门的人。hospes 与 guest（客人）印欧同源；主人摆席叫 host，节目主持人也叫 host。\",\"hostel\":\"来自古法语 hostel「住所、客栈」，源头同拉丁语 hospitale。它与 hotel 是同一个词的两种拼写分化：hostel 偏平价旅舍（青年旅馆），hotel 偏正式酒店。\",\"hotel\":\"来自法语 hôtel「宅邸、旅馆」，源头拉丁语 hospitale「客房」。法语里 hôtel de ville 是市政厅——本义是「大房子」；英语借它专指收费的旅客之家。\",\"hue\":\"古英语 hīw「外貌、颜色」，日耳曼语词。先指一切外观，后收窄到「色调」；习语 hue and cry（大声追捕）里的 hue 是「喊叫」，另一个词，别混。\",\"hug\":\"来源不确定：可能来自古诺尔斯语 hugga「安慰」，16 世纪才出现。拥抱这个词本身很年轻，但动作很老。\",\"hummingbird\":\"humming（嗡嗡声）+ bird 的复合词：蜂鸟翅膀每秒扇动数十次，嗡嗡作响，像会飞的蜜蜂。它是唯一能倒飞的鸟，名字记住的是它的声音。\",\"hunter\":\"hunt（打猎，古英语 huntian，来源有争议）+ -er。猎人是英语最老的职业词之一；猎户座 Orion 的英文别名就是 the Hunter。\",\"hunting\":\"hunt + -ing。hunt 的古英语形式 huntian 可能与「抓捕」有关（未定论）；狩猎在英语文化里从生存手段变成运动，词义一路跟随。\",\"hurdle\":\"古英语 hyrdel，是 hurd「编枝条的框架」的指小形式——早期跨栏就是编条栅栏，牧羊时用来圈羊。田径跨栏沿用了农具；hurdle 也比喻「难关」。\",\"husk\":\"中古英语 huske，来源有争议（一种说法与日耳曼语「小房子」有关：壳是种子的外衣，此说未定）。玉米苞皮、稻壳都是 husk；动词是「剥壳」。\",\"hybrid\":\"来自拉丁语 hybrida「杂种、混血儿」（更深来源可能与希腊语 hybris 有关，未定论）。先指动植物杂交种，后指油电混合车、混合办公——凡是「两种血统合一」都用它。\",\"hyena\":\"经拉丁语来自希腊语 hyaina，是 hys「猪」的阴性形式——「母猪（样的兽）」：古希腊人觉得鬣狗背上的鬃毛像猪鬃。鬣狗出名的「笑声」与名字无关。\",\"hypnosis\":\"来自希腊语 hypnos「睡眠」+ -osis，19 世纪成为「催眠状态」的术语（Braid 先造了 hypnotism）。后来发现催眠并非睡眠，但名字留了下来；睡神 Hypnos 就是词源本人。\",\"current\":\"来自拉丁语 currere「跑」的现在分词 currens——「正在跑的」。水跑起来是洋流，电跑起来是电流，时间跑到当下就是「当前的」。注意：它和 curare「照料」（cure 的祖先）只是拼写相近，并非同源——这是最容易混的一对。\",\"occur\":\"来自拉丁语 occurrere：ob-「迎着」+ currere「跑」——「迎面跑来」。事情迎面跑到你面前，就是「发生」；跑进脑子里，就是「被想起」（It occurred to me）。\",\"currency\":\"来自拉丁语 currere「跑、流动」：货币的本性是在人与人之间「流转」。它先指「流通的状态」，18 世纪后才专指一国流通的钱。\",\"course\":\"来自拉丁语 cursus「奔跑（的路线）」，源头是 currere「跑」。跑出来的路线是「航线、进程」，按路线一节节跑完的学业就是「课程」。\",\"excursion\":\"来自拉丁语 excursio：ex-「出」+ currere「跑」——「跑出去（一趟）」。远足、短途游就是暂时从日常里跑出去、再跑回来。\",\"curriculum\":\"拉丁语 curriculum 本义是「奔跑；跑道」，来自 currere「跑」。学业就像一条跑道：一门门课排成赛程，学生沿着它一路跑到毕业。\",\"cure\":\"来自拉丁语 cura「照料、操心」，动词 curare 是「照料（病人）」。治病的核心先是「照管」：把病人照料到康复。和 current 的 curr「跑」只是拼写相近，不是一家。\",\"accurate\":\"来自拉丁语 accuratus：ad-「朝向」+ cura「照料、用心」——「用心做到位」。把心思和照料都倾注到细节上，结果就是「精确」。\",\"security\":\"来自拉丁语 securus：se-「没有」+ cura「忧虑」——「没有忧虑的（状态）」。操心的事都排除了才叫安全；它兼指「证券」，也是取「让人无忧的资产」之义。\",\"captain\":\"来自拉丁语 capitaneus「首要的」，源头是 caput「头」。一支队伍的「头」就是队长；caput 还生出了 capital（首都、资本）与 chapter（章节的头）。\",\"capital\":\"来自拉丁语 capitalis，源头 caput「头」。「头」引申出一串词义：城市的头是「首都」，账目的头一笔是「资本」，句首的头字母要「大写」。\",\"vaccine\":\"来自拉丁语 vacca「母牛」。1796 年詹纳用牛痘（拉丁名 variolae vaccinae，「牛的天花」）预防天花，vaccine 因此得名——疫苗一词里真的藏着一头牛，后来才泛指一切疫苗。\",\"mortgage\":\"来自古法语 mort gage：「死亡质押」。mort 是「死」（拉丁语 mors），gage 是「抵押物」：债还清，质押就「死」了；还不上，房子就「死」在债主手里。读音 /ˈmɔːɡɪdʒ/，t 不发音。\",\"salary\":\"来自拉丁语 salarium——发给罗马士兵买盐的钱（sal 就是「盐」）。盐在古代是硬通货，所以「工资」至今带着咸味；worth his salt（称职）也由此而来。\",\"salad\":\"来自拉丁语 salata「加了盐的（菜）」，源头 sal「盐」。古罗马人吃生菜要撒盐调味，沙拉就是「撒了盐的凉拌菜」，和 salary 是同一个「盐」家族。\",\"sausage\":\"经古法语来自拉丁语 salsus「盐腌的」，源头 sal「盐」。香肠最初靠盐腌防腐，与 salary、salad 同属「盐」家族。\",\"muscle\":\"来自拉丁语 musculus「小老鼠」，是 mus「老鼠」的指小词。古人看肱二头肌一收缩，像只小老鼠在皮下窜动，便给肌肉起了这个名字。\",\"disaster\":\"来自意大利语 disastro：dis-「坏」+ astro「星星」（希腊语 astron）。占星时代，灾祸被归咎于「星象不利」——灾难是星星排错了位置。\",\"focus\":\"拉丁语 focus 本义是「灶台、火炉」。开普勒在 1604 年借它指透镜汇聚光线的「焦点」：光像柴火一样在此汇聚，后来它引申为一切注意力的汇聚点。\",\"candidate\":\"来自拉丁语 candidatus「穿白袍的人」，源头 candidus「洁白的」。古罗马的竞选者穿一身洁白长袍示人以示清廉，候选人一词因此带着一身白。\",\"campus\":\"拉丁语 campus 是「平原、旷野」。18 世纪普林斯顿用它称校园里的开阔草地，后来泛指整个校园——大学最初的形象是一片开阔的原野。\",\"camera\":\"来自拉丁语 camera obscura「暗室」：最早的成像装置就是一间带小孔的暗屋。camera 在拉丁语里本是「拱顶的房间」，照相机就是随身版的暗室。\",\"planet\":\"来自希腊语 planētēs「漫游者」。古人见这几颗星不像恒星那样钉在天幕上，而是在星座间游走，于是称它们「漫游者」——行星。\",\"clinic\":\"来自希腊语 klinikē，源头 klinē「床」。clinic 本是「病床边的（诊疗）」：医生俯身床边看病的地方，就是诊所。\",\"window\":\"来自古诺尔斯语 vindauga：vindr「风」+ auga「眼」——「风之眼」。北欧人管墙上透风透光的洞叫风的眼睛，英语借走了这个词，它和拉丁语无关。\",\"kindergarten\":\"德语 Kindergarten：「儿童花园」（Kinder 儿童 + Garten 花园）。19 世纪教育家福禄贝尔造这个词时，把孩子比作花、幼儿园比作园丁照料的花园。\",\"holiday\":\"holy（神圣的）+ day（日子）：原指宗教节日，后来一切不用工作的日子都成了 holiday。它是英语本土的复合词。\",\"island\":\"来自古英语 īegland：īeg「（水中的）陆地」+ land。中间的 s 是文艺复兴时期的学者误以为它与拉丁语 insula 同源硬加上的，所以至今不发音。\",\"volcano\":\"来自意大利语 vulcano，源头是罗马火神 Vulcan（伏尔甘）。罗马人相信埃特纳等火山是火神的锻炉，火山之名便源于神名。\",\"peninsula\":\"拉丁语 paeninsula：paene「几乎」+ insula「岛」——「几乎是岛的陆地」。半岛就差那么一点，便是一个岛。\",\"desert\":\"来自拉丁语 desertum「被抛弃之地」，源头 deserere「离开、遗弃」。沙漠在词源里说的不是沙，而是「空无一人」：被遗弃的土地。\",\"oasis\":\"经希腊语借自古埃及语：绿洲一词跟着商队从埃及传遍地中海世界。词本身就是一件旅途舶来品。\",\"fossil\":\"来自拉丁语 fossilis「挖出来的」，源头 fodere「挖」。化石最初泛指一切从地里挖出的东西，19 世纪才收窄到古生物遗骸。\",\"crystal\":\"来自希腊语 krystallos「冰」。古人以为水晶是冻得永不融化的冰：透明石英太像冰，名字里便冻着一块远古的冰。\",\"amber\":\"经阿拉伯语 ʿanbar 传入欧洲。琥珀一词走的是贸易路线，本义指龙涎香，后来转指这种金黄色的树脂化石。\",\"marble\":\"来自希腊语 marmaros「闪光的石头」，源头 marmairein「闪烁」。大理石因剖面的光泽得名，和大海（mar）毫无关系。\",\"granite\":\"来自意大利语 granito「颗粒状的」，源头 grano「颗粒」（拉丁语 granum「谷粒」）。花岗岩满是矿物颗粒，名字就是它的质地。\",\"canyon\":\"来自西班牙语 cañón「大管子、水道」，源头 canna「芦苇、管子」。峡谷像大地上一条巨管，河流从中穿过。\",\"ocean\":\"来自希腊语 Ōkeanos——神话中环绕大地的巨河与海神之名。古希腊人以为世界尽头有一条环流的大河，ocean 就是它。\",\"glacier\":\"来自法语 glacier，源头 glace「冰」（拉丁语 glacies）。冰川是阿尔卑斯山民法语里的词：山上那条不会化的「大冰」。\",\"theory\":\"来自希腊语 theōria「观看、沉思」，源头 theōros「观礼的使者」。理论的起点是「站在一旁看清楚」：先观察，再解释。\",\"theater\":\"来自希腊语 theatron「观看的场所」，源头 theasthai「看」。剧场是专为「看」而建的建筑；它与 theory（理论）同源，都是「看」。\",\"analysis\":\"来自希腊语 analysis：ana-「向上、回溯」+ lysis「松开」——「层层解开」。把整体拆散解开就是分析；透析 dialysis 里也有这个 lysis。\",\"thesis\":\"来自希腊语 thesis「放置；主张」：把一个观点「放」到桌面上接受检验，就是论点；放在学位申请里，就是学位论文。\",\"antithesis\":\"希腊语 antithesis：anti-「反对」+ thesis「放置」——把观点「对着放」。正题的对立面，就是反题。\",\"economy\":\"来自希腊语 oikonomia：oikos「家」+ nemein「管理」——「持家」。它原指家政管理，后来词义从「管家」放大到「管理一国之财」。\",\"ecology\":\"希腊语 oikos「家、住所」+ -logia「学说」拼成的词，1866 年由海克尔提出：研究生物与它们的「家」（环境）关系的学问。它与 economy 同出 oikos 一家。\",\"atom\":\"来自希腊语 atomos：a-「不」+ temnein「切」——「切不开的」。这是德谟克利特猜想的终极微粒；颇具讽刺的是，20 世纪的物理学家真的把它「切」开了。\",\"character\":\"来自希腊语 kharaktēr「刻印的标记」，源头 kharassein「刻」。它先指印章刻下的记号，再指刻在人身上的印记——性格与品格。\",\"criterion\":\"来自希腊语 kritērion「判断的标准」，与 crisis 同源（krinein「分辨」）。标准就是用来分辨合格与不合格的那把尺子。\",\"critique\":\"来自希腊语 kritikē「评判的艺术」，与 crisis、criterion 同源：批评的本职是「分辨好坏」，不是挑刺。\",\"philosophy\":\"希腊语 philosophia：philos「爱」+ sophia「智慧」——「爱智慧」。相传毕达哥拉斯说自己不是「智者」，只是智慧的爱慕者，哲学之名由此而来。\",\"psychology\":\"希腊语 psychē「灵魂、心灵」+ -logia「学说」：研究心灵的学问。psychē 在神话里与蝴蝶相连——灵魂如蝶，所以蝴蝶的学名也是 psyche。\",\"mathematics\":\"来自希腊语 mathēma「学到的东西」，源头 manthanein「学习」。数学原义就是「学问本身」：在古希腊，不学数学不算受过教育。\",\"museum\":\"来自希腊语 mouseion「缪斯的圣殿」。缪斯是九位掌管文艺的女神，博物馆最初是供奉缪斯、陈列文艺之物的地方；music（音乐）与它同源。\",\"library\":\"来自拉丁语 liber「书」：藏书之所。liber 的本义其实是「树皮」——古罗马人曾把文字写在树皮上，书与树皮因此同名。\",\"school\":\"来自希腊语 skholē「闲暇」。古希腊人认为有了闲暇才能坐而论道——学校是「用闲暇治学」的地方。\",\"calendar\":\"来自拉丁语 calendarium「账本」，源头 calendae「每月第一天」——罗马人在朔日结账催债。日历最初是一张还款日程表。\",\"journal\":\"来自拉丁语 diurnalis「每日的」，经法语 jour「日」。journal 是每天记一点的东西：期刊、日记、新闻业都由此而来；journey（旅程）原义是「一天的路程」。\",\"legend\":\"来自拉丁语 legenda「（圣徒的）必读之事」，源头 legere「读、搜集」。中世纪修道院里必读的圣徒故事，成了今天的「传说」；lecture、legible 与它同源。\",\"novel\":\"来自意大利语 novella「新故事」，源头拉丁语 novus「新的」。小说在诞生时的卖点就是「新」：与旧史诗相对的新式叙事。\",\"drama\":\"来自希腊语 drama「行为、演出」，源头 dran「做、行动」。戏剧就是把事情「做」出来给你看，而不是说给你听。\",\"comedy\":\"来自希腊语 kōmōidia：kōmos「狂欢巡游」+ aeidein「唱」。喜剧源于酒神节后村民醉醺醺地唱着歌穿村而过——笑闹本是它的底色。\",\"tragedy\":\"来自希腊语 tragōidia：「山羊之歌」（tragos 山羊 + ōidē 歌）。祭祀酒神时献上山羊、合唱队装扮成半羊而歌，悲剧之名由此而来；一说当时的奖品就是一只山羊。\",\"poem\":\"来自希腊语 poiēma「做成的作品」，源头 poiein「制作」。诗人首先是「匠人」：诗是动手做出来的作品。\",\"metaphor\":\"希腊语 metaphora：meta-「跨越」+ pherein「搬运」——把意义从一个词「搬」到另一个词上，就是隐喻。transfer 与它结构相同（trans- + fer，都是「跨越+搬运」）。\",\"atlas\":\"来自希腊神话巨人 Atlas（阿特拉斯），他被罚用肩扛起天穹。16 世纪的地图集封面常画着他扛地球，atlas 从此成了地图册之名；颈部最上方的「寰椎」也叫 atlas。\",\"chronology\":\"希腊语 khronos「时间」+ -logia「学说」：按时间排队的学问。khronos 与吞噬子女的时间之神克洛诺斯同名——时间确实吃掉一切。\",\"photograph\":\"希腊语 phōs「光」+ graphein「写画」：摄影是「用光作画」。1839 年这个新词诞生时，精准概括了这门技术的本质。\",\"telescope\":\"希腊语 tēle「远」+ skopein「看」：能看远的工具。skopein 还生出了 microscope（看小）等一串「看」的仪器名。\",\"microscope\":\"希腊语 mikros「小」+ skopein「看」：把小东西看大的工具。mikros 还在 microwave（微波）、microbe（微生物）里。\",\"antibiotic\":\"希腊语 anti-「对抗」+ bios「生命」：字面是「对抗生命之物」，专杀细菌的药物得了这个有点黑色幽默的名字。bios 还在 biology、symbiosis 里。\",\"protein\":\"来自希腊语 prōteios「第一位的」，源头 prōtos「第一」。命名者认为这种物质在生命中居于首位：蛋白质是「第一等重要」的营养素。\",\"chromosome\":\"希腊语 khrōma「颜色」+ sōma「身体」：这种小体在显微镜下容易被染料着色，故名「染色体」——名字来自染色实验的直观印象。\",\"gene\":\"来自希腊语 genos「出生、种族」，经德语 Gen。1909 年约翰森提出这个词：gene 是管「出生时带来什么」的单位；genesis（起源）、generate 与它同源。\",\"vitamin\":\"拉丁语 vita「生命」+ amine「胺」拼成的造词（1912 年）：「维持生命的胺」。后来发现它们并非都是胺类，词尾的 e 被去掉成了 vitamin，但「生命」之义还在。\",\"hormone\":\"来自希腊语 hormān「激发、催促」。1905 年被命名：激素是身体里的「催促信使」——量极微，却能催动全身。\",\"enzyme\":\"希腊语 en-「在内」+ zymē「酵母、发酵」：字面是「在酵母里的东西」。酶最早是在发酵现象中被认识的。\",\"virus\":\"拉丁语 virus 本义是「毒液、黏液」。古人不知道微生物为何物，只看到「毒」在致病：病毒之名来自毒液说。后来的计算机病毒借的也是它的「传染」之性。\",\"bacterium\":\"来自希腊语 baktērion「小棍子」，是 baktēria「手杖」的指小词。显微镜下最早看到的细菌多是杆状的——细菌字面就是「小棍子」。\",\"cell\":\"来自拉丁语 cella「小房间」。1665 年胡克用显微镜看软木，见格子像修道院的小房间，便以 cell 名之；牢房、电池后来都借了这个「小格子」。\",\"organ\":\"来自希腊语 organon「工具、乐器」。身体的器官是干活的工具，管风琴也是发声的工具——两者同源同名，并非巧合。\",\"skeleton\":\"来自希腊语 skeletos「干枯的（身体）」，源头 skellein「使干燥」。骨骼是血肉风干后剩下的框架，所以它字面是「干架子」。\",\"artery\":\"来自希腊语 artēria。古人解剖时见动脉中空，一度以为它是输送空气的管道——死后动脉中的血液流空，这个误会便写进了名字。\",\"diagnosis\":\"希腊语 diagnōsis：dia-「贯通」+ gignōskein「认识」——「看穿而知」。诊断是把症状看透、认出病名；prognosis（预后）是预先知道。\",\"symptom\":\"希腊语 symptōma「偶然同时发生之事」：症状是「恰好一起落下来的迹象」。词源上症状只是线索，疾病是藏在背后的主角。\",\"therapy\":\"来自希腊语 therapeia「侍奉、照料」。治疗者 therapeutes 的原义是「侍奉者」：治疗始于照料，而不是始于药。\",\"quarantine\":\"来自意大利语 quarantina「四十天」，源头 quaranta「四十」。14 世纪威尼斯规定来自疫区的船只须隔离 40 天——quarantine 的词源是地中海上的一道命令。\",\"epidemic\":\"来自希腊语 epidēmia：epi-「在…之上」+ dēmos「人民」——「落到人民头上的（病）」。希波克拉底的著作就叫《流行病论》。\",\"pandemic\":\"希腊语 pan-「全部」+ dēmos「人民」：「波及全部人民」。这个词 19 世纪才被造出来，构词一目了然：比 epidemic 大一号，覆盖所有人。\",\"asthma\":\"来自希腊语 asthma「喘息」，源头 aein「吹、喘」。哮喘的词源就是喘气这件事本身。\",\"cancer\":\"来自拉丁语 cancer「螃蟹」，是希腊语 karkinos 的翻译。希波克拉底见肿瘤周围血管伸张如蟹足，便以蟹名之；巨蟹座与它同名同源。\",\"hygiene\":\"来自希腊语 hygieia「健康」，也是健康女神 Hygieia 的名字。卫生学供奉的女神，至今站在这个词里。\",\"equator\":\"来自拉丁语 aequator「使相等者」：赤道使昼夜长短、南北两半球「均分」，所以叫「等分线」；equal（相等）与它同源。\",\"horizon\":\"来自希腊语 horizōn「划界的（圆）」，源头 horizein「设限」。地平线就是视野的边界线：再远，就看不见了。\",\"geology\":\"希腊语 gē「大地」+ -logia「学说」：研究大地的学问。gē 还在 geometry 里——几何学最初源于丈量土地。\",\"geometry\":\"来自希腊语 geōmetria：gē「大地」+ metron「测量」——「测地术」。尼罗河年年泛滥冲毁田界，埃及人量地，量出了几何学。\",\"arithmetic\":\"来自希腊语 arithmos「数字」：算术就是「数字之学」。arithmos 还藏在 logarithm（对数）里。\",\"algebra\":\"来自阿拉伯语 al-jabr「复原、接合」，出自 9 世纪花拉子米的书名《复原与化简之书》。在他看来，方程移项像把断骨接回去——代数之名本是「接骨术」。\",\"algorithm\":\"来自数学家花拉子米（al-Khwārizmī）姓氏的拉丁化拼写 Algoritmi。算法之名纪念的不是概念，而是一个人——这位代数学之父的名字。\",\"agenda\":\"拉丁语 agenda 是「要做的事（们）」，来自 agere「做、行动」。议程天生就是一张待办清单：词源上，它是动词变来的名词。\",\"decade\":\"来自希腊语 dekas「十（个一组）」。decade 的整词就是「十个一组」，十年只是它的时间版本；deca- 还在 decathlon（十项全能）里。\",\"senate\":\"来自拉丁语 senatus「元老院」，源头 senex「老人」。参议院就是「长老们的会议」；senex 还在 senior（年长者）里。\",\"president\":\"来自拉丁语 praesidens：prae-「在前」+ sedere「坐」——「坐在前面的人」。总统就是坐在主位上的那位；resident（居民）与它同根，都是「坐」。\",\"vote\":\"来自拉丁语 votum「誓言、许愿」。投票源于向神许愿的仪式：选票是世俗化了的「愿」。\",\"election\":\"来自拉丁语 eligere：e-「出」+ legere「挑选」——把人从人群里「挑出来」。legere 还是 legend（读物）、collect（收集）的祖先。\",\"democracy\":\"希腊语 dēmokratia：dēmos「人民」+ kratos「权力」——「人民掌权」。kratos 还在 aristocracy（贵族掌权）、bureaucracy（官僚掌权）里。\",\"republic\":\"来自拉丁语 res publica「公共之事」：共和国就是「大家的事」。public（公共的）与它同源。\",\"monarchy\":\"希腊语 monos「单一」+ arkhein「统治」：「一个人统治」。arkhein 还在 anarchy（无统治→无政府状态）里。\",\"empire\":\"来自拉丁语 imperium「命令权、统治权」，源头 imperare「下令」。帝国是命令所及之地；emperor（皇帝）就是握有 imperium 的人。\",\"colony\":\"来自拉丁语 colonia，源头 colonus「农夫、定居者」。罗马把退伍军人安置到新土地上耕种：殖民地最初是「农夫的新家园」。\",\"citizen\":\"经古法语来自拉丁语 civis「市民」。公民的根在「城」里：civis 还生出了 city、civil、civilization 一整家人。\",\"civil\":\"来自拉丁语 civis「市民」。civil 的一切义项——公民的、国内的、文明有礼的——都绕着「城里的市民」转。\",\"civilization\":\"在拉丁语 civilis「市民的」基础上于 18 世纪造出的新词，原指「市民社会的教养状态」。它是启蒙时代的造词，不是古代旧词。\",\"jury\":\"经古法语来自拉丁语 jurare「宣誓」。陪审团首先是「宣过誓的人」：先宣誓，后审案。jurare 还在 perjury（伪证）里。\",\"judge\":\"来自拉丁语 judex：jus「法律」+ dicere「说」——「说出法律的人」。法官的本职是宣示法律；justice、judicial 与它同源。\",\"verdict\":\"来自拉丁语 vere dictum「如实所说」：vere「真实地」+ dictum「所说的话」。裁决就是陪审团「说出真相」；dict 还在 dictionary 里。\",\"crime\":\"来自拉丁语 crimen「指控、罪行」，与 cernere「分辨、判定」有关：罪是经法庭「判定」成立的行为。\",\"prison\":\"经古法语来自拉丁语 prehendere「抓住」的名词形式：监狱在词源上是「被抓获」的状态，后来才转指关押之地。\",\"police\":\"来自希腊语 polis「城邦」，经拉丁语 politia「城邦的治理」。警察、政策（policy）、政治（politics）同出一源：都是「管城」的事。\",\"policy\":\"它有两个来源：指「政策」时来自希腊语 polis「城邦」（与 police 同源）；指「保险单」时来自希腊语 apodeixis「证明」，经意大利语 polizza。同形而不同祖。\",\"diplomacy\":\"来自希腊语 diplōma「对折的文书」——古代委任状都是对折封好的。外交官凭一纸折起来的国书行走各国，外交之名由此而来。\",\"treaty\":\"经古法语来自拉丁语 tractare「处理、谈判」，源头 trahere「拉」。条约是长时间拉锯谈判的成果；tract 还在 abstract、contract 里。\",\"tax\":\"来自拉丁语 taxare「估量、征税」。税是「估量着收的」；计程车 taxi 的表也是估价，与它同源——这大概是最令人意外的亲戚。\",\"tariff\":\"经意大利语借自阿拉伯语 taʿrīf「通知、定价表」：关税的名字来自阿拉伯贸易文书，由地中海商人带进欧洲。\",\"budget\":\"来自法语 bougette「小皮包」，源头拉丁语 bulga「皮袋」。英国财政大臣曾提着皮包公布收支，budget 就从「提包」变成了「预算」。\",\"bankrupt\":\"来自意大利语 banca rotta「砸碎的长凳」：钱商在市集的长凳上营业，无力偿付时长凳被当众砸碎——破产在词源里是物理意义上的「凳碎」。\",\"market\":\"来自拉丁语 mercatus「市集、买卖」，源头 merx「货物」。集市是货物聚会的地方；merchant（商人）、commerce（商业）都是 merx 的后代。\",\"merchant\":\"经古法语来自拉丁语 mercari「做买卖」，源头 merx「货物」。商人就是与货物打交道的人，与 market（市集）同源。\",\"trade\":\"来自中古低地德语 trade「足迹、常走的路」，与 tread（踩踏）同源：贸易就是商人「常走的那条路」。它是日耳曼语词，不是拉丁语词。\",\"monopoly\":\"希腊语 monos「单一」+ pōlein「出售」：「独家出售」。垄断的词源干脆利落——市场上只有一个卖家。\",\"patent\":\"来自拉丁语 patere「敞开」：专利证书原是君主颁发的「公开文书」（letters patent）。以公开换独占，正是专利制度的词源逻辑。\",\"abstract\":\"来自拉丁语 abstrahere：abs-「离开」+ trahere「拉」——「从具体中拉出来」。抽象就是把性质从实物上抽离；extract（提取）与它同根。\",\"concept\":\"来自拉丁语 concipere「怀住、抓取」，与 conceive 同源：概念是心智「抓住」的东西。capere「抓」还生出了 capture、capable。\",\"evidence\":\"来自拉丁语 evidentia：e-「出」+ videre「看」——「看得见的东西」。证据的使命是让真相被看见；video、vision 都源于 videre。\",\"example\":\"来自拉丁语 exemplum「取出的样本」，源头 eximere「取出」。例子是从一堆里挑出来展示的那一个；sample 与它其实同源。\",\"data\":\"拉丁语 data 是 dare「给予」的过去分词复数：「被给定的东西」。数据在词源里不是「算出来的」，而是「先行给定、作为起点」的。\",\"method\":\"来自希腊语 methodos：meta-「沿着」+ hodos「路」——「沿路而行」。方法就是走通问题的那条路；hodos 还在 period（绕行之路→周期）里。\",\"system\":\"来自希腊语 systēma「组织起来的整体」：syn-「一起」+ histanai「站立」——各部分站到一起成的体系。\",\"structure\":\"来自拉丁语 structura，源头 struere「堆叠、建造」。结构讲的是「怎么堆起来的」；construct、instruct 与它同源——教育也是一种建造。\",\"function\":\"来自拉丁语 functio「执行、履行」，源头 fungi「履行职责」。功能问的是「它负责做什么」；函数是数学里各司其职的对应关系。\",\"phase\":\"来自希腊语 phasis「显现」，最初指月亮盈亏的显现。阶段、相位都承袭「显现出来的样子」之义：月相是它最老的用法。\",\"element\":\"拉丁语 elementum 本指「基本要素、字母」，确切来源众说纷纭，有一说取自字母 L、M、N 的序列。元素与字母都是各自学科里最小的构件。\",\"molecule\":\"拉丁语 moles「大团块」的指小词 molecula「小团块」：分子就是物质的「小团」。moles 还在 demolish（拆毁）里。\",\"species\":\"来自拉丁语 species「外观、种类」，源头 specere「看」。物种是「看上去」归为一类的生物；inspect、spectacle 与它同根——都靠眼睛分辨。\",\"evolution\":\"来自拉丁语 evolvere：e-「出」+ volvere「滚动」——「展开卷轴」。它先用于胚胎发育，后来才成为生物演化的名字。\",\"revolution\":\"拉丁语 revolvere「滚回、旋转」：天文学先用它指天体绕行——哥白尼名著的原名里就有这个词。政治「革命」是后起之义：把秩序转个底朝天。\",\"adapt\":\"来自拉丁语 adaptare：ad-「向」+ aptare「使合适」。适应就是把自己调到「合身」；apt（恰当的）与它同源。\",\"environment\":\"来自法语 environ「周围」：环境字面就是「围着我们的那一圈」。这个词 17 世纪才流行，它的生态学含义更是 20 世纪才有的。\",\"resource\":\"来自法语 ressource，源头拉丁语 resurgere「再次涌起」：资源原是「能重新涌出的泉源」——补给不绝的来路，才配叫资源。\",\"significant\":\"来自拉丁语 significare「表明」，源头 signum「记号」：重要的，是「明明白白做出记号」的；sign、signal 与它同源。\",\"indicate\":\"来自拉丁语 indicare「指出」，源头 index「指路者、食指」。指示就是伸出手指：index finger（食指）与它同根。\",\"demonstrate\":\"来自拉丁语 demonstrare：de-「完全」+ monstrare「指给看」。论证是把道理指给人看，游行示威（demonstration）是把诉求亮给人看。\",\"illustrate\":\"来自拉丁语 illustrare「照亮、阐明」。插图与例证都是给文字「打光」：让它亮起来、看得清。\",\"emphasis\":\"来自希腊语 emphasis「显现、强调」，源头 phainein「显露」。强调，就是把重点「显」出来。\",\"perspective\":\"来自拉丁语 perspicere「看透」：per-「穿透」+ specere「看」。视角原是绘画术语：透过画面看空间的法则。\",\"dimension\":\"来自拉丁语 dimetiri「量尽」：di-「分开」+ metiri「测量」。维度是从各个方向「量」出来的尺度；measure 与它同源。\",\"proportion\":\"来自拉丁语 proportio：pro「按」+ portio「份额」——「按份额（分配）」。比例讲的是各份之间的对应；portion（部分）与它同源。\",\"capacity\":\"来自拉丁语 capacitas，源头 capere「容纳、抓取」。容量是「能装下多少」，能力是「能承接多少」，都源于 capere。\",\"velocity\":\"来自拉丁语 velocitas，源头 velox「迅速的」。velocity 的名字很直白；velox 还出现在自行车旧称 velocipede（快脚车）里。\",\"gravity\":\"来自拉丁语 gravitas「沉重」，源头 gravis「重的」。它先指「沉甸甸的性质」，牛顿之后才成为万有引力的名字；grave（严肃的）与它同源。\",\"momentum\":\"来自拉丁语 momentum「推动之力；片刻」，源头 movere「移动」。天平被推动的那一瞬既是「时刻」也是「势头」：moment（时刻）与它同源。\",\"inertia\":\"来自拉丁语 inertia「懒散、不活动」，源头 iners「迟钝的」。惯性在词源里是「懒」：物体懒得改变自己的状态。\",\"friction\":\"来自拉丁语 fricare「摩擦」。摩擦的名字就是动作本身；fricare 还在 dentifrice（洁牙粉）里。\",\"pressure\":\"来自拉丁语 pressura，源头 premere「压」。压力就是「压」这件事；press（印刷机、报界）与它同源——印刷靠的正是压。\",\"temperature\":\"来自拉丁语 temperatura「调和、适中状态」，源头 temperare「调和」。古人谈温度，说的是冷热「调和」的比例：热水掺凉水，得到的就是 temperature。\",\"capsule\":\"来自拉丁语 capsula「小盒子」，是 capsa「箱子」的指小词。胶囊就是装药的小盒子；太空舱 capsule 是这个小盒子放大后的版本。\",\"mercury\":\"得名于罗马信使之神 Mercury（墨丘利）：这种金属流动如活物，快得像神使的脚步。它的元素符号 Hg 却来自希腊语 hydrargyros「水银」，两套名字并存。\",\"nitrogen\":\"来自希腊语 nitron「硝石」+ -genēs「生成」：「生成硝石之气」。18 世纪的化学家按来源给它命名。\",\"oxygen\":\"希腊语 oxys「酸的」+ -genēs「生成」：「生成酸的东西」。拉瓦锡以为氧是一切酸的来源——后来发现盐酸并不含氧，名字将错就错留了下来。\",\"hydrogen\":\"希腊语 hydōr「水」+ -genēs「生成」：「生成水的东西」。氢气一燃烧就生成水，名字说的就是它的招牌实验。\",\"carbon\":\"来自拉丁语 carbo「木炭」：碳元素之名直截了当——木炭的主要成分就是它。charcoal（木炭）与它同源。\",\"helium\":\"来自希腊语 hēlios「太阳」。1868 年科学家先在太阳光谱中发现了它，近三十年后才在地球上找到：它是先在太阳上被命名的元素。\",\"copper\":\"来自拉丁语 cuprum，是 Cyprus（塞浦路斯）的缩写：罗马人的铜主要产自塞浦路斯，铜的名字就是它的产地名。\",\"bronze\":\"经意大利语 bronzo 进入英语，来源说法不一，一说源于波斯语 birinj「铜」。青铜是个贸易词：它跟着金属商路走遍了欧洲。\",\"iron\":\"来自古英语 īren，是日耳曼语的老词，与拉丁语无关。铁器时代足够古老，各语言都留下了自己的「铁」字。\",\"gold\":\"来自古英语 gold，与拉丁语无关：它源于表示「黄、发光」的古老词根——金子以颜色得名，yellow（黄色）与它是远亲。\",\"elephant\":\"经拉丁语借自希腊语 elephas「大象、象牙」，其更深来源可能在东方语言中。大象本是沿贸易路来到欧洲的外来客，名字也是。\",\"tiger\":\"经希腊语 tigris 而来，据说源于表示「箭」的古波斯语词：老虎以疾如箭得名。底格里斯河（Tigris）与它同名。\",\"camel\":\"经希腊语、拉丁语借自闪语族的 gamal：骆驼的名字跟着骆驼本身，从沙漠商路一路走进欧洲各语言。\",\"giraffe\":\"经意大利语借自阿拉伯语 zarāfa：长颈鹿的名字是阿拉伯商旅带进欧洲的舶来品，16 世纪才在英语里定型。\",\"octopus\":\"来自希腊语 oktōpous：oktō「八」+ pous「脚」——「八只脚的东西」。所以它规范的复数是 octopuses，不是 octopi：词尾是希腊语，不是拉丁语。\",\"mammal\":\"来自拉丁语 mamma「乳房」。林奈在 1758 年以「哺乳」为这一纲定名：用乳汁喂养后代，是哺乳动物的身份证。\",\"insect\":\"来自拉丁语 insectum「被切入的（身体）」，是希腊语 entomon 的翻译：昆虫的身体像被切成一节一节的。entomon 还活在 entomology（昆虫学）里。\",\"butterfly\":\"古英语 buttorflēoge「黄油飞虫」：一说这种蝶黄如黄油，一说指它爱偷食黄油。「黄油」成分确定无疑，具体由来至今有争议。\",\"mosquito\":\"西班牙语 mosquito 是 mosca「苍蝇」的指小词：「小苍蝇」。蚊子的名字来自西班牙语，随着殖民与贸易传遍世界。\",\"salmon\":\"来自拉丁语 salmo，据说源于 salire「跳跃」：鲑鱼洄游时跃过瀑布，它的名字里藏着那一跳。\",\"turkey\":\"得名于 Turkey（土耳其）：欧洲人误以为这种美洲禽鸟经土耳其商路而来。火鸡是地理误会的产物，就像美洲原住民被误称 Indian 一样。\",\"bamboo\":\"经马来语 mambu 借入英语：竹子的名字随东南亚贸易而来，是英语里的热带舶来品。\",\"coffee\":\"经土耳其语 kahve 借自阿拉伯语 qahwa：咖啡的名字跟着豆子，从埃塞俄比亚经阿拉伯、土耳其一路传到欧洲。\",\"tea\":\"来自闽南语中「茶」的读音（tê），经荷兰商人由海路传入欧洲，写作 tea。而经陆路、俄语传去的读作 chai——同一个词，两条贸易路线，两种读法。\",\"chocolate\":\"来自纳瓦特尔语（阿兹特克语）chocolatl，经西班牙语进入欧洲：巧克力连名字都是美洲原住民给世界的礼物。\",\"tomato\":\"来自纳瓦特尔语 tomatl，经西班牙语 tomate 传入：番茄和它的名字都来自墨西哥。\",\"potato\":\"来自西班牙语 patata，是泰诺语 batata（甘薯）与克丘亚语 papa（马铃薯）的混合：两种美洲薯在欧洲人的嘴里合成了一个词。\",\"banana\":\"经葡萄牙语、西班牙语借自西非语言：香蕉的名字随着种植园与贸易，从西非来到美洲，再传遍世界。\",\"orange\":\"经法语、阿拉伯语 nāranj 溯源至波斯语乃至梵语 nāraṅga：橙子的名字沿贸易路线西行，最前面的 n 在法语里被听丢了（une norange 变成了 une orange）。\",\"lemon\":\"经阿拉伯语 laymūn 借自波斯语：柠檬的名字走的是阿拉伯贸易路线，它与 lime（酸橙）是近亲。\",\"peach\":\"经法语来自拉丁语 persicum「波斯的（果子）」。桃子原产中国，却因经波斯传入罗马得了「波斯果」之名——产地在传播中被标错了位。\",\"cherry\":\"经法语 cherise 来自拉丁语 cerasus，源头是小亚细亚的凯拉索斯城：樱桃以产地为名。英语又把法语的复数形式误当单数，留下了今天的 cherry。\",\"wheat\":\"来自古英语 hwǣte，与 hwīt「白」同源：小麦因能磨出白面得名，是日耳曼语的本土农业词，与拉丁语无关。\",\"scissors\":\"经古法语来自拉丁语 cisoria「切割器具」，源头 caedere「切」。剪刀与 incision（切口）、decide（切断犹豫→决定）同属一个「切」家族。\",\"concert\":\"经意大利语 concerto 进入英语，来源有争议：一说拉丁语 concertare「协作、商议」，一说 conserere「连结」。音乐会是众人协力之声——连它的词源都众说纷纭。\",\"accordion\":\"来自德语 Akkordion，源头 Akkord「和弦」（来自法语 accord）。19 世纪维也纳的制琴者以「和弦」命名这种一按就出和弦的乐器。\",\"saxophone\":\"以发明者、比利时人阿道夫·萨克斯（Adolphe Sax）的姓氏 + 希腊语 phōnē「声音」拼成，1846 年取得专利。它是乐器史上少有的「人名乐器」。\",\"xylophone\":\"希腊语 xylon「木头」+ phōnē「声音」：「木头的声音」。木琴的琴键真是木头做的，名字直白。\",\"logo\":\"是 logotype 的缩略，源头希腊语 logos「词语、理性」。商标 logo 的祖先是印刷工人的「连字字模」：先有词，后有图。\",\"spectrum\":\"来自拉丁语 spectrum「影像、显现」，源头 specere「看」。牛顿借它指光经棱镜分出的彩带：光谱原义是「显现出来的影像」。\",\"vacuum\":\"来自拉丁语 vacuus「空的」。真空就是「空无一物」；vacant（空缺的）、vacation（空出来的时间→假期）与它同源。\",\"terrain\":\"来自拉丁语 terra「土地」。地形就是土地的样貌；terrace（梯田）、territory（领土）都是 terra 的后代。\",\"vendor\":\"来自拉丁语 vendere「出售」。摊贩就是卖东西的人；vend 还在 vending machine（自动售货机）里。\",\"victim\":\"来自拉丁语 victima「祭品、牺牲」。受害者在词源上是被献祭者——这个词自带悲剧色彩，后来泛指一切受难者。\",\"deposit\":\"来自拉丁语 deponere：de-「下」+ ponere「放」——「放下来存着」。存款、沉积物、矿床都是「放下后积起来的东西」；position 与它同根。\",\"appendix\":\"来自拉丁语 appendere「悬挂在…上」。附录像挂在书尾的坠子；阑尾是挂在盲肠上的小坠子——同一个词，两处悬挂。\",\"credit\":\"来自拉丁语 credere「相信」。信用、信贷都建立在「信」之上：银行敢借钱，是因为它信你；credible（可信的）与它同源。\",\"deficit\":\"拉丁语 deficit 是 deficere「缺少」的第三人称单数，直译是「它缺了」。赤字的名字就是账本上的一句叹气：不够。\",\"classification\":\"来自拉丁语 classis「等级」+ facere「做」：把事物「按等级做归类」。classis 原指罗马按财产划分的征召等级，分类借了编制之名。\",\"artificial\":\"来自拉丁语 artificium「技艺、工艺」：ars「技艺」+ facere「做」。人工的，就是「靠手艺做出来的」——褒贬不在词源，在语境。\",\"facility\":\"来自拉丁语 facilis「容易做的」，源头 facere「做」。facility 是「让事情变得好做的东西」：设施、设备都由此而来。\",\"format\":\"来自拉丁语 formatus「已成形的」，源头 formare「塑造」。格式就是给内容定的那个「形」；form（形状）与它一家。\",\"hemisphere\":\"希腊语 hēmi-「半」+ sphaira「球体」：「半个球」。大脑半球、地球半球都出自这个几何词；sphere（球体）与它同根。\",\"hemoglobin\":\"希腊语 haima「血」+ 拉丁语 globus「球」拼成的混血词：血红蛋白是血液里负责携氧的「球」状蛋白。haima 还在 hemorrhage（出血）里。\",\"heredity\":\"来自拉丁语 heres「继承人」。遗传就是从先人那里「继承」来的性状；heir（继承人）与它同源。\",\"hero\":\"来自希腊语 hērōs「半神、勇士」。荷马史诗里的英雄半人半神；heroine 是它后来造出的阴性形式。\",\"temple\":\"指神庙时来自拉丁语 templum「划定的神圣空间」，原指占卜时在天空中划出的区域。神庙就是在地上划出的同一片「圣域」。（指太阳穴的 temple 是另一个同形词。）\",\"discipline\":\"来自拉丁语 disciplina「教学、训练」，源头 discipulus「学生」（disciple 门徒）。纪律的本义是弟子所受的训练：自律，就是自己做自己的老师。\",\"medicine\":\"来自拉丁语 medicina，源头 medicus「医生」、mederi「治疗」。医学与医生同根；mederi 还在 remedy（补救、疗法）里。\",\"audit\":\"来自拉丁语 audire「听」。审计最初是「听账」：古代账目要当众念出来核对，auditor 就是听账人；audio（音频）与它同源。\",\"audacious\":\"经法语来自拉丁语 audax「大胆的」，源头 audere「敢」。敢字当头：大胆与鲁莽共用这个词源，褒贬全看语境。\",\"attempt\":\"来自拉丁语 attemptare：ad- + temptare「试探、尝试」。尝试就是「去探一探」；tempt（诱惑）与它同源——诱惑也是一种试探。\",\"aggregate\":\"来自拉丁语 aggregare：ad- + grex「群、兽群」——「聚集成群」。总计是把散数聚成一群；gregarious（爱社交的）与它同根。\",\"fluctuate\":\"来自拉丁语 fluctuare，源头 fluctus「波浪」。波动的词源就是水波：数值像浪一样起起伏伏。\",\"margin\":\"来自拉丁语 margo「边缘」。页边、余量、利润率都是「留出的那条边」：margin 是给自己留的回旋空间。\",\"ascertain\":\"经古法语来自拉丁语 ad- + certus「确定的」：查明就是「弄到确定为止」。certus 还在 certain（确定的）里。\",\"calligraphy\":\"希腊语 kallos「美」+ graphein「写」：「把字写美」。书法在希腊语里直截了当，就是美字之术；kallos 还在 kaleidoscope（万花筒，「看美丽图形之器」）里。\",\"choreography\":\"希腊语 khoreia「合唱舞蹈」+ graphein「写」：编舞就是「把舞写下来」。舞者用身体写字，编舞家是它的记录者。\",\"olfactory\":\"来自拉丁语 olfacere：olere「闻到气味」+ facere「做」。嗅觉就是「完成闻味这件事」的那套系统，词源平实而准确。\",\"rosemary\":\"来自拉丁语 ros marinus「海之露」：ros「露水」+ marinus「海的」。这种香草爱长在地中海海边，叶片如承海露，故名——与人名 Rose、Mary 并无关系。\",\"soccer\":\"是 association football「协会足球」的校园俚语缩略：取 assoc. 中的 soc，再加口语后缀 -er，19 世纪在牛津一带造出 soccer 一词。\",\"smartphone\":\"smart「智能」+ phone 的现代拼词，1990 年代才定型。它的词源就是一句营销话术：一部「聪明」的电话。\",\"encryption\":\"来自希腊语 kryptos「隐藏的」。加密就是把文字藏起来；crypt 的本义是地下墓室——文字被埋进地窖，只有有钥匙的人能取出。\",\"zoo\":\"是 zoological garden「动物学公园」的缩略，源头希腊语 zōion「动物」。1828 年伦敦动物园开园，先有了全称的科学名，后有了顺口的 zoo。\",\"volunteer\":\"来自拉丁语 voluntarius「自愿的」，源头 volo「我愿意」。志愿者的词源是一句表态：我愿意。voluntary 与它同根。\",\"allegory\":\"来自希腊语 allēgoria：allos「别的」+ agoreuein「公开演说」——「说的是这个，指的是那个」。寓言天生有两层皮。\",\"delegate\":\"来自拉丁语 delegare：de-「下」+ legare「派遣、委任」。代表就是被「派下去办事」的人；legacy（遗产）与 legare 同源，都是托付。\",\"allegiance\":\"经古法语来自中世纪的效忠关系：它本指臣民对领主（liege）的效忠义务。忠诚一词带着封建印记：先有效忠的对象，才有 allegiance。\",\"fiction\":\"来自拉丁语 fictio「塑造、虚构」，源头 fingere「捏塑、编造」。小说是「捏出来的故事」；fingere 还在 figure（捏出的形状）里。\",\"nonfiction\":\"non-「非」+ fiction「虚构」组成的词，20 世纪才随图书馆分类流行：非虚构就是「不是捏出来的」。它的年龄比大多数人以为的要年轻。\",\"empress\":\"经古法语来自拉丁语 imperatrix，是 imperator「统帅、皇帝」的阴性形式。女皇与 empire、emperor 同出一门：都是「发号施令者」。\",\"expressway\":\"express + way 的 20 世纪造词：express 本有「快速直达」之义（源于「压出、挤出」），高速公路就是给汽车的直达专线。\",\"socket\":\"来自古法语 soket「小犁铧」，是 soc「犁铧」的指小词。插座像墙里嵌着的小犁头：形状的联想成就了这个词，电学义是后起的。\",\"terrorism\":\"来自法语 terreur「恐怖（统治）」，源头拉丁语 terrere「使惊吓」。terrorism 诞生于法国大革命的恐怖统治时期——最初指国家恐怖，后来才转指非国家的暴力。\",\"invasion\":\"来自拉丁语 invadere：in-「入」+ vadere「行进」——「走进去」。入侵的词源很简洁：迈步进来，就是占领的开始。\",\"evasion\":\"来自拉丁语 evadere：e-「出」+ vadere「走」——「走脱」。逃避是把自己「走」没了；它与 invasion 的 vadere 同根：一进一出。\",\"investigate\":\"来自拉丁语 investigare：in- + vestigare「循迹追踪」。调查的本义是循着脚印找人：vestigium 就是足迹。\",\"adopt\":\"来自拉丁语 adoptare：ad- + optare「选择」——「选来作为自己的（孩子）」。收养子女与 adopt 一项政策同源：都是主动选择、予以接纳。\",\"option\":\"来自拉丁语 optio「选择的自由」，源头 optare「挑选、希望」。选项，就是留给你的那份选择权。\",\"port\":\"指港口时来自拉丁语 portus「港口、避风港」。它与 portare「搬运」长得像却是两家：port 是货物停靠之地；transport 等词里的 -port 才是搬运。\",\"airport\":\"air + port 的 20 世纪造词：机场是「空中的港口」。port 本指海港，飞机上天之后，港口也跟着上了天。\",\"isolate\":\"来自意大利语 isolato，源头拉丁语 insula「岛」：把人或物「变成孤岛」，就是隔离。insular（孤立的、海岛的）与它同源。\",\"solo\":\"来自意大利语 solo「独自的」，源头拉丁语 solus「单独的」。独奏，就是一个人撑完全场。\",\"consolidate\":\"来自拉丁语 consolidare：con-「一起」+ solidus「坚实的」——「合并成坚实的一体」。solid（固体、坚实的）与它一家：巩固就是变结实。\",\"agency\":\"来自拉丁语 agere「做、推动」。机构是「替人做事」的组织；agent（代理人）是 agere 的现在分词——都是「行动者」。\",\"amiable\":\"来自拉丁语 amicus「朋友」，经法语 amiable。和蔼可亲的词源是「像朋友一样」；西班牙语的 amigo（朋友）也是 amicus 的后代。\",\"amateur\":\"来自法语 amateur，源头拉丁语 amator「爱者」。业余者词源上是「出于热爱而做的人」——「不专业」是后来的引申义，它起初是个褒义词。\",\"mental\":\"来自拉丁语 mens「心智」。精神的、心理的都源于 mens；mention（提及）也是它的后代：提及，就是让事情在心里过一遍。\",\"comment\":\"来自拉丁语 commentum「构想、评注」，源头 comminisci「想出、构思」，与 mens「心智」同出一源。评论，就是把想出来的看法写下来。\",\"path\":\"作「小路」讲的 path 是日耳曼语本土词（古英语 pæth），与拉丁语无关。但它和希腊语词根 path「感受」（pathos）同形不同源：sympathy 同感、apathy 无感里的 path 才是希腊语那一家，不要混淆。\",\"decision\":\"来自拉丁语 decisio，是 decidere「一刀切断」的名词形式（de- + caedere「切」）。决定，就是把犹豫斩断的那一刀落下的结果。\",\"ascent\":\"来自拉丁语 ascendere：ad- + scandere「攀登」——「向上爬」。它的反义 descent 是「向下爬」（de-）；scandere 还在 scan（逐行扫描，原义逐行爬过）里。\",\"descent\":\"来自拉丁语 descendere：de-「向下」+ scandere「攀登」——「向下爬」。血统义由此而来：一代代「向下」传，就是后裔的谱系。\",\"anticipate\":\"来自拉丁语 anticipare：anti-（即 ante-）「预先」+ capere「抓」——「提前抓住」。预料，就是把还没到的事先抓在手里。\",\"principle\":\"来自拉丁语 principium「开端、根基」，源头 princeps「第一的、首位的」。原则是万事的「第一条」；principal（主要的、校长）与它同源，都是「排第一」。\",\"principal\":\"来自拉丁语 principalis「第一的、首要的」，与 principle（原则）同源于 princeps「第一位」。校长是学校里的第一位，本金是钱款的第一笔。\",\"medium\":\"来自拉丁语 medius「中间的」。媒介是居中的传话者，介质是居中的承载物；作「媒体」讲的 media 正是它的复数形式。\",\"meditation\":\"来自拉丁语 meditari「沉思、反复练习」，与 mens「心智」相关：冥想是让心智反复练习安静。meditari 与 medicine 的祖先 mederi 也是同族。\",\"ardent\":\"来自拉丁语 ardere「燃烧」。热情在词源里是「烧起来的」：ardent 的人心里有团火；arson（纵火）与它同源。\",\"acid\":\"来自拉丁语 acidus「酸的、尖锐的」，源头 acer「锋利」。酸在拉丁语里带着尖感：醋的尖、柠檬的尖都是它；acrid（辛辣的）与它同源。\",\"cascade\":\"经意大利语 cascata 来自拉丁语 cascare「落下」（cadere「落」的反复形式）。瀑布就是「一落再落的水」；cadere 还在 cadence（节奏，本是语句的起伏下落）里。\",\"detention\":\"来自拉丁语 detinere：de- + tenere「握住」——「被握住不放」。拘留与留校共用这个词：都是被制度握在手里。\",\"identity\":\"来自拉丁语 identitas，源头 idem「同一」。身份就是「你始终是同一个人」的证明；identical（完全相同的）与它同源。\",\"encyclopedia\":\"来自希腊语 enkyklios paideia「全面的教育」：en-「在内」+ kyklos「圆圈」+ paideia「教育」。百科全书是「围成一圈的全部学问」；kyklos 还在 cycle（循环）里。\",\"legislation\":\"来自拉丁语 legis lator：lex「法律」+ lator「提出者」——「把法律提出来（的人或机构）」。立法就是造法；legal 与它同源。\",\"epidermis\":\"希腊语 epi-「在…之上」+ derma「皮肤」：「皮肤上面那一层」。表皮得名直白；derma 还在 dermatology（皮肤科）里。\",\"genre\":\"来自法语 genre「种类」，源头拉丁语 genus「出生、种族、类别」。体裁就是作品的「种属」；gender（性别）与它同源——都是分类之名。\",\"intelligence\":\"来自拉丁语 intelligere：inter-「在…之间」+ legere「挑选、读」——「在信息之间挑出要领」。智力在词源上是一种分辨力。\",\"contemplate\":\"来自拉丁语 contemplari：con- + templum「划定的观兆圣域」。沉思原是占卜者在圣域里凝神观察征兆——思考，起于凝视。\",\"decline\":\"来自拉丁语 declinare：de-「向下」+ clinare「倾斜」。衰落是「斜着滑下去」；incline（倾斜）、recline（斜躺）与它同根。\",\"accelerate\":\"来自拉丁语 accelerare：ad- + celer「快的」——「使（之）变快」。celer 还在 celerity（迅速）里；decelerate 就是给它装上反向的 de-。\",\"fertile\":\"来自拉丁语 fertilis，源头 ferre「生育、产出」。肥沃就是「能生能产」；ferre 还在 transfer（搬运）、conference（带来→商议）里。\",\"financial\":\"经中世纪拉丁语的「结清（款项）」义发展而来，源头 finis「终结、了结」：finance 本指把账目「了结」，后泛指钱财运作。fine（罚款）与它同源。\",\"potential\":\"来自拉丁语 potentia「力量、能力」，源头 potens「有能力的」。潜力就是「还没使出来的力量」；potent（强效的）与它同源。\",\"maintain\":\"经法语来自拉丁语 manu tenere「用手握住」：manu 是「手」，tenere 是「持有」。维持，就是一直用手扶着，不让它倒下。\",\"survive\":\"来自拉丁语 supervivere：super-「在…之上、超过」+ vivere「活」——「活得比（灾难）更久」。vivid（生动的）与它同根，都是「活」。\",\"interface\":\"inter-「之间」+ face「面」拼成的词，1960 年代在计算机领域定型：界面就是两个系统「面对面」的地方。词很年轻，构件却都来自拉丁语。\",\"portrait\":\"来自拉丁语 protrahere「描出、拖曳出来」。肖像画是把人的形象从本人身上「描」下来；portray（描绘）与它同源。\",\"manual\":\"来自拉丁语 manualis，源头 manus「手」。手册是「拿在手里的书」，手工劳动是「用手干的活」——都源于手。\",\"pedestrian\":\"来自拉丁语 pedester「步行的」，源头 pes「脚」。行人就是用脚走路的人；它「平淡无奇」的引申义，来自「步行不如骑马体面」的古老联想。\",\"export\":\"来自拉丁语 exportare：ex-「出」+ portare「搬」——「搬出去」。货物从港口搬出就是出口；它的反义 import 是把货物搬进来。\",\"extract\":\"来自拉丁语 extrahere：ex-「出」+ trahere「拉」——「拉出来」。拔牙、提取、摘录，都是把东西从里面拉出来。\",\"manuscript\":\"拉丁语 manu scriptus「手写的」：manu「手」+ scriptus「写」。印刷术出现之前的书全是手抄本，「手稿」之名便这样留了下来。\",\"predict\":\"来自拉丁语 praedicere：prae-「预先」+ dicere「说」——「提前说出」。预言就是先说出口；dictate、dictionary 与它同根。\",\"attract\":\"来自拉丁语 attrahere：ad-「向」+ trahere「拉」——「往自己这边拉」。磁铁与魅力都是拉力；tractor（拖拉机）与它同源。\",\"contract\":\"来自拉丁语 contrahere：con-「一起」+ trahere「拉」——双方被「拉到一起」达成约定，所以合同叫 contract；肌肉被拉紧而收缩，也是同一个词。\",\"progress\":\"来自拉丁语 progressus：pro-「向前」+ gradi「迈步」——「向前迈步」。进步就是一步步往前走；grade（台阶）与 gradi 同源。\",\"gradual\":\"来自拉丁语 gradus「台阶、步级」。逐步的，就是一级台阶一级台阶地来；grade、graduate（跨过学位台阶）与它同源。\",\"congress\":\"来自拉丁语 congressus「走到一起」：con-「一起」+ gradi「行走」。国会就是大家走到一处开会；progress 是向前走，congress 是聚拢来走。\",\"degree\":\"经古法语来自拉丁语 de- + gradus「台阶」：「从台阶（上划分）的等级」。学位、温度的度、程度，都是量出来的级差。\",\"notebook\":\"note + book 的英语本土复合词：记 note 的 book。它的词源没有传奇，就是字面本身——英语里有大量这样的透明复合词。\",\"politician\":\"来自希腊语 polis「城邦」，经 politics 而来。政治家就是「管城邦事务的人」；police、policy 与它同出一源。\",\"portfolio\":\"来自意大利语 portafoglio：portare「携带」+ foglio「纸页」——「装纸页的夹子」。公文包、作品集、投资组合，都是从「一夹子纸」长大的。\",\"psychoanalysis\":\"希腊语 psychē「心灵」+ analysis「解开」拼成的词，由弗洛伊德在 1896 年前后提出：精神分析，就是把心灵「解开来分析」。\",\"registration\":\"来自拉丁语 regesta「记录、登记册」，源头 regerere「带回、登记」。注册就是把名字「带回名单里」；register 与它同源。\",\"viscosity\":\"来自拉丁语 viscum「槲寄生；鸟胶」——古人用槲寄生浆果熬胶来粘鸟。黏度之名来自粘鸟的胶：viscous 的祖先真的黏过鸟。\",\"visualization\":\"来自拉丁语 visualis「看得见的」，源头 videre「看」。可视化就是「让数据被看见」；vision、video 与它同根。\",\"memoir\":\"来自法语 mémoire「记忆」，源头拉丁语 memoria。回忆录就是「把记忆交出来」；memory（记忆）与它同源，只是走了法语的路。\",\"aluminum\":\"来自拉丁语 alumen「明矾」：铝最早是从明矾类矿物中认识并提炼的，元素名便取自明矾。美式拼写 aluminum 是后来的简化。\",\"aluminium\":\"来自拉丁语 alumen「明矾」：铝因最早从明矾土中提炼而得名。英式拼写 aluminium 多一个 i，是命名者戴维后来改定的形式。\",\"crater\":\"来自希腊语 kratēr「调酒的大碗」：古希腊人调和酒与水的大碗，形状就是火山口的样子。它与 -crat（如 democracy 的「统治」）只是拼写相撞。\",\"apple\":\"古英语 æppel 的后代，是日耳曼语的本土老词，比拉丁语大规模进入英语要早得多。它词尾的 ple 不是「充满」：ap-ple 只是拼写巧合。\",\"couple\":\"来自拉丁语 copula「系带、连结」，经古法语进入英语：两个被一条带子系在一起，就是一对。它词尾的 ple 不是「充满」的词根。\",\"cluster\":\"古英语 clyster「一簇、一团」的后代，是日耳曼语本土词。它开头的 clus 不是「关闭」：与拉丁语 claudere 没有关系。\",\"displace\":\"dis-「移开」+ place「位置」：place 经法语来自拉丁语 platea「宽街、广场」（源头希腊语 plateia）。place 与 placere「取悦」（placid 那一家）不是同一个词根。\",\"annoy\":\"经古法语来自拉丁语 in odio「招人厌」（odium 是「厌恶」）。它的 ann 不是 annus「年」：annoy 与 annual 两家毫无关系。\",\"belly\":\"来自古英语 belig「皮囊、袋子」：肚子鼓起来像个皮口袋，这才是它的出身。它与 bell「战争」（拉丁语 bellum）无关。\",\"marsh\":\"来自古英语 mersc「低湿之地」，是日耳曼语专指湿草地的老词。它不是拉丁语 mare「海」的派生词。\",\"inevitable\":\"来自拉丁语 inevitabilis：in-「不」+ evitare「躲避」。这里的 vit 是 vitare「躲开」，不是 vita「生命」：躲不开的，就是不可避免的。\",\"avid\":\"来自拉丁语 avidus，源头 avere「渴望」。avid reader 就是如饥似渴的读者；它与 videre「看」（evidence 那一家）无关。\",\"endeavor\":\"en-「使进入」+ devoir「责任」（源于拉丁语 debere「欠、应当」）拼成的词，本义是「尽责、努力去做」。它词尾的 vor 不是「吃」，那是拼写巧合。\",\"esophagus\":\"来自希腊语 oisophagos「把（食物）带下去的（管子）」：食管的本职是搬运食物。它中间的 soph 不是 sophia「智慧」。\",\"deliberation\":\"来自拉丁语 deliberare：de-「彻底」+ librare「称量」（libra 是天平、秤）。审议是在心里「称一称」再决定——它与 liber「自由」拼写相近，来源却不同；equilibrium 里的 libr 也是这杆秤。\",\"incentive\":\"来自拉丁语 incentivum「进攻的号角声」：in- + canere「唱、奏」。把号角吹响，士兵就往前冲——激励的祖先是战场上的号声；这里的 cent 是「唱」的变体，不是「一百」。\",\"conceive\":\"来自拉丁语 concipere：con- + capere「抓取」，经法语词干演变为 -ceive。在心里「抓住」一个念头叫构想，怀住一个生命叫怀孕——它与 receive、concept 同源于 capere。\",\"transcript\":\"来自拉丁语 transcribere：trans-「转」+ scribere「写」——「转抄下来（的文本）」。成绩单、文字记录都是转抄件；manuscript、description 与它同根。\",\"statute\":\"来自拉丁语 statuere「设立、立定」。法令就是被「立」下来的规矩；state、statue 与它同源，都是「立住」的东西。\",\"exist\":\"来自拉丁语 existere：ex-「向外」+ sistere「站立」——「站出来」。从无到有、站到世界上来，就是存在。\",\"definite\":\"来自拉丁语 definire：de-「完全」+ finire「限定」（finis「边界」）。边界划得清清楚楚，就是「明确」；define、finite 与它同根。\",\"finite\":\"来自拉丁语 finitus，源头 finis「边界、终点」。有终点的就是有限的；它的反义 infinite 是后起的对词。\",\"fluid\":\"来自拉丁语 fluidus，源头 fluere「流」。流体的名字直白；fluere 还在 influence（流入→影响）、fluent（流利）里。\",\"influence\":\"来自拉丁语 influere：in-「向内」+ fluere「流」。它的本义带着占星色彩：星辰的力量「流」进人间、左右命运——影响就是这样「流」进来的。\",\"affluence\":\"来自拉丁语 affluere：ad-「朝向」+ fluere「流」——财富「流向」某人，就是富足。它与 influence 是同根的「流」。\",\"traditional\":\"来自拉丁语 tradere「亲手交付」：传统就是一代人亲手交给下一代人的东西。拼写相近的 trade（贸易）来源不同，不要混淆。\",\"radiation\":\"来自拉丁语 radius「车轮的辐条；射线」。辐条从轮心向外射出，光线亦然：辐射之名取的正是这个放射的形状。\",\"contingency\":\"来自拉丁语 contingere：con-「共同」+ tangere「接触」——「碰上了（的情况）」。偶然事件，就是没打招呼就碰上的事。\",\"controversy\":\"来自拉丁语 controversia：contra-「反对」+ vertere「转」——立场「转」向对立面。vers「转」还在 diverse、conversion 里。\",\"maintenance\":\"经法语，由拉丁语 manus「手」+ tenere「握持」构成：用手一直扶着、保持住，就是维护。它与 maintain 是同一组词根换了个拼法。\",\"entertainment\":\"enter-（inter-「之间」的变体）+ tain「握、留住」（拉丁语 tenere）：娱乐的本事是「把人留住」——把客人的注意力握住不放。\",\"explicit\":\"来自拉丁语 explicitus：ex-「向外」+ plicare「折叠」——把折起来的东西全部「展开」。明确的话，一折不剩地摊开说。\",\"implicit\":\"来自拉丁语 implicitus：im-「向内」+ plicare「折叠」——意思还「折」在里面，没有摊开。它与 explicit 正好是一合一开。\",\"implicate\":\"来自拉丁语 implicare：im-「向内」+ plicare「折叠、卷入」。牵连就是被「卷」进折子里：衣角被卷进门缝，就是这个画面。\",\"application\":\"来自拉丁语 applicare「贴上、附着」。申请是把自己「贴」到岗位上，应用是把方法「贴」到问题上；手机里的 app 正是它的缩略后代。\",\"apply\":\"来自拉丁语 applicare「贴上去」，经法语词干演变而成。它结尾的 -ly 不是副词后缀：整个词就是「贴上去」。\",\"employee\":\"employ「雇用」经法语来自拉丁语 implicare「卷入」：employee 是「被卷进一份工作里的人」，与 implicate（牵连）同根。\",\"supply\":\"来自拉丁语 supplere：sub-「补上」+ plere「充满」——把见底的库存重新「补满」。它的 ply 是 plere「满」，不是 apply 的 plicare「折」，两个 ply 拼写相同、祖先不同。\",\"plastic\":\"来自希腊语 plastikos，源头 plassein「塑造、捏制」：plastic 的本义是「可塑的」。能捏成任何形状的材料才配叫塑料——名字先于材料出现。\",\"plasma\":\"来自希腊语 plasma「被塑造出来的东西」。血浆是血液里「成形」的那部分液体；物理学的等离子体是后来借用的名字。\",\"diploma\":\"来自希腊语 diplōma「对折的官方文书」（diploos「双的」）：两折一合、盖上印，就是凭证。外交 diplomacy 的文书传统也源于此。\",\"anthology\":\"希腊语 anthos「花」+ logos「辑录、言语」：「采花」。把最好的诗文像采花一样编成一束，就是选集。\",\"assess\":\"来自拉丁语 assidēre：ad-「挨着」+ sedēre「坐」——「挨着坐」。古罗马负责征税的官员就坐在纳税人旁边，当场估算他该交多少：assess 的「评估」就是这么「坐」出来的。它和 resident、president 的 sid / sed 是同一个「坐」。\",\"assume\":\"来自拉丁语 assūmere：ad- + sūmere「拿、取」——「拿过来」。把一个说法拿过来当真的，是「假设」；把责任拿过来扛，是「承担」。它和 consume 同根于 sūmere「拿」。\",\"assumption\":\"与 assume 同源：拉丁语 assūmere「拿过来」+ -tion。把未经证实的东西先「拿」来当前提，就是假设。\",\"consume\":\"来自拉丁语 cōnsūmere：con-「全部」+ sūmere「拿」——「全部拿走、用光」。吃光、耗尽、消费都是「拿光」。\",\"consumer\":\"与 consume 同源：cōnsūmere「全部拿走」+ -er——不停把东西拿走、用掉的人，就是消费者。\",\"select\":\"来自拉丁语 sēligere：sē-「分开」+ legere「挑选、采集」——「分开来挑」。legere 还留下 lecture（读出来的内容）和 collect（采到一起）。\",\"evolve\":\"来自拉丁语 ēvolvere：ē-「向外」+ volvere「滚动」——「滚展开来」。卷轴一点点展开、新样子一点点显露，就是演化；involve 是反方向的「卷进去」。\",\"involve\":\"来自拉丁语 involvere：in-「向里」+ volvere「卷」——「卷进去」。被卷进一件事，就是牵涉、参与。\",\"dynamic\":\"来自希腊语 dynamis「力量」（dynasthai「能够」）。有力量在推动，就是动态的、有活力的；dynamite（炸药）也是这个词根。\",\"fusion\":\"来自拉丁语 fundere「倒、熔化」的完成体 fūsus：把金属熔成一锅汤再浇铸——fusion 的「融合、聚变」，都是液体熔在一起的样子。\",\"diffusion\":\"来自拉丁语 diffundere：dis-「四散」+ fundere「倒」——「倒得四处都是」。墨水滴进水里散开，就是扩散。\",\"transfusion\":\"来自拉丁语 trānsfundere：trans-「跨过去」+ fundere「倒」——把血从一个人「倒」进另一个人身体里，就是输血。\",\"intact\":\"来自拉丁语 intactus：in-「未」+ tactus（tangere「触摸」的完成体）——「没被碰过的」。原封不动就是 intact；contact 是它的反面：碰上了。\",\"contact\":\"来自拉丁语 contactus：con-「一起」+ tangere「触摸」——「碰到一起」。接触的第一义是身体挨上，后来才引申为联系、联络。\",\"tactile\":\"来自拉丁语 tactilis，源头 tangere「触摸」：能用手摸出来的，就是触觉的。\",\"lecture\":\"来自拉丁语 lēctūra，源头 legere「读、挑选」：中世纪大学里，教授把书「读」给学生听就是讲座——lecture 最初真的是一场朗读。\",\"collection\":\"来自拉丁语 colligere：con-「一起」+ legere「采集、挑选」——「采到一起」。收藏，就是把挑好的东西聚成一堆。\",\"dialect\":\"来自希腊语 dialektos：dia-「相互」+ legein「说」——「相互交谈（的方式）」。一个地方的人互相说话说出的腔调，就是方言。\",\"collaborate\":\"来自拉丁语 con-「一起」+ labōrāre「劳动」——「一起干活」。合作的本义毫不浪漫：就是几个人一块儿出力。\",\"elaboration\":\"来自拉丁语 ēlabōrāre：ē-「做出来」+ labōrāre「劳动」——「下苦功做出来」。精心、详尽，都是一锹一锹 labor 出来的。\",\"cooperate\":\"来自拉丁语 co-「一起」+ operārī「工作」（opus「工作」）——「一起做事」。operation、operator 里的 oper 都是它。\",\"operation\":\"来自拉丁语 operātiō，源头 opus「工作、工程」：动手做的「作业」——手术是一场作业，军事行动、数学运算也都是「做」出来的事。\",\"operator\":\"operate（操作）+ -ator（做…的人）：在机器、系统前面「做事」的人，就是操作员。\",\"devote\":\"来自拉丁语 dēvōvere：dē-「完全」+ vōvere「发誓、许愿」（vōtum「誓言」）——「发了誓地交出去」。把时间、生命许给一件事，就是奉献；vote 是同一支誓言：投下的是一张郑重的票。\",\"devotion\":\"与 devote 同源：vōtum「誓言」+ -ion。忠诚与热爱，都来自那句发下的誓。\",\"flexible\":\"来自拉丁语 flectere「弯曲、折转」的词干 flex-：能弯的，就是灵活的。\",\"reflex\":\"re-「回」+ flectere「弯曲」：刺激传过去又「弯回来」，就是反射。\",\"reflection\":\"来自拉丁语 reflectere「弯回去」：光撞上镜面弯回来，照出影像；脑子把念头弯回来看，就是反思。\",\"acquire\":\"来自拉丁语 acquīrere：ad-「朝向」+ quaerere「寻求、追求」——「追到手」。inquire（追问）、acquisition 都是这个 quaerere 在追东西。\",\"acquisition\":\"与 acquire 同源：acquīrere「追到手」+ -tion。获得物、收购，都是追到手的东西。\",\"inquire\":\"来自拉丁语 inquīrere：in- + quaerere「寻求」——「追着问」。提问，就是一种寻求。\",\"adjacent\":\"来自拉丁语 adjacēre：ad-「挨着」+ jacēre「躺」——「躺在旁边」。紧挨着躺在一起，就是相邻。\",\"error\":\"来自拉丁语 errāre「走偏、游荡」：error 是「走偏了」的名词。犯错在词源里是一次走失——偏离了正路。\",\"resonance\":\"来自拉丁语 resonāre：re-「回」+ sonāre「发声」（sonus「声音」）——「回声」。声音撞回来叠在一起，就是共振、共鸣。\",\"obsession\":\"来自拉丁语 obsidēre：ob-「对着」+ sedēre「坐」——「坐在对面围困」。罗马军队围城就是这么「坐」在城外；一个念头在脑子里安营扎寨不走，就是困扰、着魔。\",\"abundance\":\"来自拉丁语 abundāre：ab- + unda「波浪」——「像波浪一样溢出来」。多到往外溢，就是丰富。\",\"abundant\":\"与 abundance 同源：unda「波浪」——多得像潮水一样往外溢。\",\"labor\":\"来自拉丁语 labor「辛劳、苦工」：这个词从一开始就带着汗味；laboratory 是「干活的地方」，collaborate 是「一起干活」。\",\"ascend\":\"来自拉丁语 ascendere：ad- + scandere「爬」——「向上爬」。descend 是往下爬：同一架梯子，两个方向。\",\"simulation\":\"来自拉丁语 simulāre「模仿、装作」，源头 similis「相像」：造一个「像真的一样」的东西来练习、来推演，就是模拟。\",\"research\":\"经古法语 recerchier，源头是拉丁语 circāre「绕着圈到处走」（circus「圈」）——「一圈圈地找遍」。研究，就是把每个角落都走遍；它和 arch「统治」毫无关系，只是拼写相近。\",\"absorb\":\"来自拉丁语 absorbēre：ab- + sorbēre「吸、吞」——一口吸进去。海绵、纸巾的本事就是 absorb；它和 orb「圆环」无关，别被拼写骗了。\",\"archive\":\"来自希腊语 arkheion「官府大楼」（arkhē「统治、官府」）：最早的档案就锁在官府大楼里——档案馆先是建筑，后是文件。\",\"archer\":\"经古法语 archier，源头是拉丁语 arcus「弓」：拿弓的人就是弓箭手。它和表示「首要」的 arch- 不是一回事。\",\"arch\":\"来自拉丁语 arcus「弓」：拱的弧线正像一张拉开的弓——先有弓，后有拱门、拱桥。\",\"archery\":\"arch（弓，源于拉丁语 arcus）+ -ery（技艺）：射箭这门手艺。\",\"electron\":\"来自希腊语 ēlektron「琥珀」：古希腊人发现摩擦过的琥珀能吸起轻小物体，电（electricity）因此得名；19 世纪末，电子被命名为「琥珀粒」。\",\"electric\":\"与 electron 同源：ēlektron「琥珀」+ -ic。17 世纪造这个词时，人们唯一熟悉的「电」，就是琥珀摩擦后吸纸屑的那股劲。\",\"personality\":\"由 person 派生。person 源于拉丁语 persōna「演员的面具、扮演的角色」：面具一换，角色就是另一个人——人格，是你向世界出演的那个「角色」的总和。（persōna 的更早来源有争议，一说来自伊特鲁里亚语。）\",\"reasoning\":\"由 reason 派生。reason 经法语 raison，源头是拉丁语 ratiō「计算、推论、理性」（rērī「计算、思考」）：讲道理，就是一步步算给人听。\",\"sonar\":\"20 世纪造的首字母缩略词：SOund NAvigation and Ranging「声导航与测距」——用声波在水里看路、量距离，和 radar 是同一批造词法。\",\"arson\":\"经法语，源头是拉丁语 ardēre「燃烧」（完成体 ārsus）：纵火，就是「烧」这个动作的罪名。\",\"aviation\":\"19 世纪由法语造出：拉丁语 avis「鸟」+ -ation——「像鸟一样飞这件事」。人类飞行的词根里，藏着一只鸟。\",\"jacket\":\"经法语 jaquette（短外套 jaque 的小称）。jaque 一说得名于法国农民的常用名 Jacques——「雅克们穿的短袄」，后来成了所有人的夹克。\",\"jackal\":\"经土耳其语 çakal，源头可追到波斯语 shaghāl：豺这个词沿着贸易与殖民的路，从西亚一路传进了英语。\",\"bison\":\"来自拉丁语 bisōn，借自日耳曼语（古高地德语 wisunt）：欧洲人还没见过美洲野牛之前，这个词先指欧洲的野牛。\",\"tangerine\":\"19 世纪，从摩洛哥港口丹吉尔（Tangier）运到英国的柑橘，被叫作「丹吉尔（的果子）」。地名先进了港，水果随后得名。\",\"consummate\":\"来自拉丁语 cōnsummāre：con-「完全」+ summa「最高点、总和」——「做到最高点」。圆满、完成都是登顶；注意这里是 summa「总和」，不是 assume 里 sūmere「拿」。\",\"anonymous\":\"来自希腊语 anōnymos：an-「无」+ onyma「名字」——「没有名字的」。匿名，就是把名字摘掉。\",\"archaic\":\"来自希腊语 arkhaikos，源头 arkhē「开端、最初」（这个词兼有「统治」的义项）：古老的，就是「开端那个时代的」。\",\"orbit\":\"来自拉丁语 orbita「车辙、轨道」，源头 orbis「圆环」：车轮在泥路上压出的那道环形辙印，就是行星该走的路。\",\"atmosphere\":\"17 世纪造的科学词：希腊语 atmos「蒸汽」+ sphaira「球」——「包着地球的蒸汽球」。大气层在词里，是一颗汽球。\",\"liquid\":\"来自拉丁语 liquidus，源头 liquēre「流动、清澈」：能流、又透明——liquid 的两层意思，都从「水」来。\",\"energy\":\"来自希腊语 energeia：en-「在…中」+ ergon「工作」——「正在做功的状态」。亚里士多德用它表示「实现中的活动」，物理学后来借去专指能量。\",\"previous\":\"来自拉丁语 praevius：prae-「在前」+ via「路」——「走在前面那条路上的」。先前的事，是先一步上路的。\",\"obvious\":\"来自拉丁语 obvius：ob-「迎着」+ via「路」——「正好在路上迎面碰到的」。明显的东西躲不开：它就站在你必经之路的中间。\",\"hierarchy\":\"来自希腊语 hierarkhia：hieros「神圣」+ arkhē「统治」——「祭司的统治」。它最早指教会里天使与神职的等级，后来一切等级制度都借了这个词。\",\"tide\":\"来自古英语 tīd「时间、时节」——和 time 是远亲。潮汐最守时：按点涨、按点落，所以「时间」的名字落到了潮水头上；Yuletide（圣诞季）里的 tide，至今还是「时节」。\",\"eclipse\":\"来自希腊语 ekleipsis「消失、被遗弃」：ek-「离开」+ leipein「离开、缺席」——日食、月食，就是太阳、月亮「缺席」了。\",\"earthquake\":\"复合词：earth（大地）+ quake（震动，古英语 cwacian「发抖」）——大地发抖，名字直白。\",\"waterfall\":\"复合词：water（水）+ fall（落下）——水往下掉的地方。英语里大量自然词，都是这样两个现成词一拼。\",\"iceberg\":\"借自荷兰语 ijsberg：ijs「冰」+ berg「山」——「冰山」。水手在北大西洋看见的，是一座漂着的山。\",\"landscape\":\"借自荷兰语 landschap：land「土地」+ -schap「构成、状态」（同 -ship）。一片土地构成的样子：先指风景画，后指风景本身。\",\"rainbow\":\"来自古英语 regnboga：regn「雨」+ boga「弓」——雨后挂在天上的一张弓。\",\"sediment\":\"来自拉丁语 sedimentum，源头 sedēre「坐、沉降」——「坐下去的东西」。泥沙在水底「坐」稳成层，就是沉积物；它和 resident 的 sid 是同一个「坐」。\",\"circumstance\":\"来自拉丁语 circumstantia：circum-「环绕」+ stāre「站立」——「站在周围的（那些事）」。处境、情形，就是环绕着你站成一圈的外部条件。\",\"analyze\":\"经法语 analyse 来自希腊语 analyein：ana-「向上、回溯」+ lyein「松开」——把缠在一起的东西层层解开。它和名词 analysis 是同一条「解开」的路。\",\"approach\":\"来自晚期拉丁语 appropiare：ad-「朝向」+ propius「更近」（prope「近」的比较级）——一步步走近。走近一个问题去处理它，就是 approach 作「方法」讲的由来。\",\"area\":\"拉丁语 area 本义是「平坦的空地、打谷场」。它的更上游来源学界尚无定论，但「一片平地」的画面一路沿用下来：面积、地区、领域都是圈出来的一片地。\",\"authority\":\"来自拉丁语 auctoritas，源头 auctor 是「创始者、著作人」，再往上是 augere「增大、创造」。能凭空「创生」出规则和作品的人，才有 authority；author（作者）与它是同根。\",\"available\":\"avail 来自古法语，核心是拉丁语 valere「有力气、有价值」（valid、value 同源）。available 就是「能派上用场、够得着」的——有价值且够得到，才叫可获得。\",\"benefit\":\"来自拉丁语 bene「好」+ facere「做」的组合：benefactum 本义是「做的一件好事」。好处就是被「做好」的那件事；benefactor（恩人）就是做这件好事的人。\",\"consistent\":\"来自拉丁语 consistere：con-「一起」+ sistere「站定」（stare「站」）——站到一起、立得住。言行前后都立得住、不互相打架，就是 consistent。\",\"context\":\"来自拉丁语 contextus，源头 texere 是「编织」。con-「一起」+「织」= 把话和周围线索织成一片布——单独抽出一根线（孤立的一句话）就没了意义。text（文本）与它同根。\",\"create\":\"来自拉丁语 creare「造出、使生长」，与 crescere「生长」（crescent 新月同源）是亲戚。创造在词源里不是无中生有，而是让东西「长出来」。\",\"definition\":\"来自拉丁语 definire：de- + finire「划定边界」（finis 是「界限、终点」）——定义就是给一个概念划清界。finite（有限的）与它同根：有界，才说得清。\",\"derived\":\"derive 来自拉丁语 derivare：de-「从…引出」+ rivus「小溪」——像把溪水从源头引出一条支流。词义由源头一路流出来，就是「源自、衍生」。\",\"distribution\":\"来自拉丁语 distribuere：dis-「分开」+ tribuere「分配」。tribuere 原与 tribus「部落」有关——古罗马按部落分粮分地；分到各处去，就是 distribution。\",\"economic\":\"经拉丁语来自希腊语 oikonomikos，源头 oikos 是「家」、nemein 是「管理」。它和 economy 同出一门：先是「持家有道」，后来放大到一国之财。与 ecology 同享 oikos 这个「家」。\",\"estimate\":\"来自拉丁语 aestimare「估价、评定」。它和 esteem（尊敬）是同一个词根：一件东西值多少钱、一个人值多少尊重，都要「估」——估价与敬重本是一回事。\",\"factor\":\"来自拉丁语 factor「做事的人、制造者」，源头 facere「做、造」。商业里它是「代办人」，数学里它是「相乘造出积的数」——都是把结果「做」出来的那个角色。\",\"formula\":\"拉丁语 formula 是 forma「形状、规范」的指小词——「小规范」。先指法庭上的固定格式，后来化学式、数学公式都沿用它：一套必须照着填的小框框。\",\"income\":\"英语本土复合词：in「进来」+ come「来」。钱进来了就是 income，不必借拉丁语——它和 outcome（出来的结果）正好是一对镜像。\",\"individual\":\"来自中世纪拉丁语 individualis：in-「不」+ dividuus「可分开的」——「不可再分的（单个）」。哲学里先指不可分的单位，后来落到每一个独立的人身上。\",\"interpretation\":\"interpret 来自拉丁语 interpretari，interpret- 的本义是「居间人、译者」（interpres）。解释，就是站在两种语言、两种意思之间做居间人，把那边的意带到这边来。\",\"issue\":\"经古法语 issue「出口」来自拉丁语 exire：ex-「出」+ ire「走」。从出口流出来的东西：刊物一期期「流出」是发行；从问题里「冒出」的争点就是议题。\",\"legal\":\"来自拉丁语 legalis，源头 lex（属格 legis）就是「法律」。legal 的一切义项都围着 lex 转；legislation（立法）是把 lex「立」起来的动作。\",\"major\":\"拉丁语 major 是 magnus「大」的比较级——「更大的」。军队里更大的官是 major（少校），学业里更大的那一块是 major（专业），都源于「更大」。\",\"percent\":\"来自拉丁语 per centum：「每一百（里）」。百分号 % 就是 centum 的草书缩写一路变形的结果——每一个百分点，都是从一百里数出来的一份。\",\"procedure\":\"来自拉丁语 procedere：pro-「向前」+ cedere「走」。一步步向前走的固定走法，就是 procedure（程序）；process（过程）与它同源，都是「向前走」。\",\"process\":\"来自拉丁语 processus「前进」，源头 procedere「向前走」。过程就是事情向前推进的路；它与 procedure 同根，一个看路本身，一个看走法。\",\"response\":\"来自拉丁语 respondere：re-「回」+ spondere「许诺」。应答在词源里近乎「回以承诺」——对方把话抛过来，你郑重接回去。sponsor（赞助人）与它同根，也是「承诺」的人。\",\"role\":\"经法语 rôle 来自拉丁语 rotulus「小卷轴」（rota「轮」的指小）。旧时演员的台词写在卷轴上发给各人——拿到哪卷，就演哪个 role（角色）。\",\"section\":\"来自拉丁语 sectio「切割」，源头 secare「切」。section 是从整体上切下来的一段；sector（部门）与它同根，也是切出来的一块。\",\"sector\":\"来自拉丁语 sector「切割者」，源头 secare「切」。像切蛋糕一样从圆里切出一块扇形、从经济里切出一块行业，都是 sector。\",\"similar\":\"来自拉丁语 similis「相像的」。它的亲戚 simultaneous（同时的）里藏着同一副面孔：simul 是「一起、同样」，像与同时，本出于「一个样」。\",\"source\":\"经古法语 sourse 来自拉丁语 surgere「涌起、升起」（surge 浪涌同源）。源头的原画是泉眼：水从地下涌出来的地方，就是一切来源的 source。\",\"specific\":\"来自拉丁语 specificus：species「种类」+ facere「做」——具体到「哪一种」才造得出来。它与 species（物种）同根：说清种类，就是 specific。\",\"variable\":\"来自拉丁语 variabilis，源头 variare「使多样、变化」，varius 是「形形色色的」。能变、且变出多种样子的量，就是 variable。\",\"achieve\":\"经古法语 achever 来自通俗拉丁语 ad caput：「到头」（caput 是「头」）。把一件事做到头、做到顶，就是 achieve。和 chief（首领）同出一个「头」。\",\"administration\":\"来自拉丁语 administrare：ad-「朝向」+ ministrare「侍奉、服务」（minister 是「仆人、大臣」）。管理一词的底色是「服务」：minister 今天既是部长也是牧师，都是侍奉者。\",\"affect\":\"来自拉丁语 afficere：ad-「朝向」+ facere「做」——对某物「下手去做」，作用于它。情感义的 affect 也是被外物「做」动了心。effect 与它只有一线之隔：efficere 是「做出来」。\",\"appropriate\":\"来自拉丁语 appropriare：ad-「使归于」+ proprius「自己的」。把东西划归自己是「占用」，划得正合分寸就是「恰当」——proper（合适的）与它同根。\",\"aspect\":\"来自拉丁语 aspectus「看的样子」，源头 aspicere：ad- + specere「看」。aspect 是从某个角度「看过去」的面貌；inspect、respect 里的 spect 都是这只「看」的眼。\",\"assistance\":\"assist 来自拉丁语 assistere：ad-「到近旁」+ sistere「站定」——站到对方身边去。帮助的第一步是到场：人站到了，assistance 就成立了。\",\"category\":\"来自希腊语 katēgoria，本义是「当众指控、陈述」。亚里士多德借它给世间万物分类陈述，category 从此成了「范畴」：把一样东西安放进它该在的那一类陈述里。\",\"commission\":\"来自拉丁语 committere：com-「一起」+ mittere「送、托付」。把事托付出去是「委托」，受托办事的一群人是「委员会」，按托付抽成的钱就是「佣金」。\",\"community\":\"来自拉丁语 communitas，源头 communis：com-「共同」+ munis「负有义务的」。一群彼此负有义务、共同承担的人，就是 community（社区）。\",\"design\":\"来自拉丁语 designare：de- + signare「做标记」（signum「记号」）。设计先是在纸上把图样「标出来」，sign（标记）与它同根：先做记号，才有图纸。\",\"distinction\":\"distinct 家族来自拉丁语 distinguere：dis-「分开」+ stinguere「戳、刺」。用尖笔把两样东西戳出记号分开，就是区别；distinguish、distinct 与它同出一手。\",\"document\":\"来自拉丁语 documentum「凭证、教训」，源头 docere「教」。文件生来有两种本事：证明事实，和教人知道——doctor（博士）与它同根，都是「教」出来的人与物。\",\"domestic\":\"来自拉丁语 domesticus，源头 domus「家」。围着 domus 的一切都是 domestic：家里的、国内的（国家如大家）、驯养的（住进家里的动物）。\",\"ensure\":\"经古法语 enseurer 来自 securus 家族：en-「使」+ sure「确定」（拉丁语 securus「无忧的」）。ensure 就是「使之板上钉钉」；insure（投保）是它的同源分工兄弟。\",\"equation\":\"来自拉丁语 aequatio，源头 aequare「使相等」，aequus 是「平的、相等的」。天平两端摆平就是 equation；equal、equilibrium 里都是这杆 aequ- 的秤。\",\"evaluation\":\"evaluate 是 e-「出」+ value「价值」：value 来自拉丁语 valere「有力、有价值」。评估就是把藏在里面的价值「估出来」——和 estimate 的 aestimare 异曲同工。\",\"feature\":\"经古法语 faiture 来自拉丁语 factura「制作、做工」，源头 facere「做」。feature 先指一个人面容的「做工长相」，后来泛指任何被做出来的显著特点。\",\"impact\":\"来自拉丁语 impactus，源头 impingere：in-「进去」+ pangere「打、钉」。一头撞进去的力道就是 impact；比喻的「影响」，也是这股撞击在后果里的延长。\",\"injury\":\"来自拉丁语 iniuria：in-「不」+ ius「权利、法律」——本义是「不法之害」。身体受的伤是 injury，心里受的冤也是它：源头都是一次对「正当」的侵犯。\",\"institute\":\"来自拉丁语 instituere：in- + statuere「设立」（stare「站」）——把一件新事物「立」起来。机构、制度、研究所，都是被立稳的组织。\",\"investment\":\"invest 来自拉丁语 investire：in- + vestis「衣服」——本义「穿上（官服）就职」。钱被「穿戴」进一门生意里周转，就是 investment；vest（背心）与它同根，都是衣。\",\"item\":\"拉丁语 item 本是副词「同样地、亦」：旧清单逐条都以 item 开头罗列（「其一…亦有…」）。读的人读顺了口，item 就从连接词变成了「一条、一个项目」本身。\",\"normal\":\"来自拉丁语 normalis，源头 norma 是木匠手里的「角尺」。合尺、成方圆的才叫 normal；norm（规范）与它同器：都是先有尺，后有「正常」。\",\"participation\":\"participate 来自拉丁语 participare：pars「部分」+ capere「取」——在一件事里「取走自己的一份」。参与的本义是分一份、出也分一份力。\",\"positive\":\"来自拉丁语 positivus「经约定确立的」，源头 ponere「放置」。摆定了的事实是「确定的」，确定的态度再引申出「积极的」；position 与它同根，都是「放」。\",\"primary\":\"来自拉丁语 primarius，源头 primus「第一」。排第一的、起头的、最要紧的，都是 primus 的后代：prime（首要的）、primitive（原始的）同出此门。\",\"range\":\"经古法语 rangier「排列」来自 rang「行列」（日耳曼语源）。一排排展开，于是有山脉的一列、数值的一列（范围）；猎物在列阵间走动，又生出「漫游」义。\",\"region\":\"来自拉丁语 regio「方向、疆界」，源头 regere「划直线、统治」（rex「国王」同源）。先有王权划下的界，才有 region 这片辖域。\",\"regulation\":\"regulate 来自拉丁语 regulare，源头 regula「直尺、规则」，再上溯 regere「引直、统治」。规矩就是一把尺：regulation 是拿尺量出来的条文。\",\"relevant\":\"来自中世纪法律拉丁语 relevans，relevare 本义「举起、减轻」（levare「举」）。在法庭上「举得起来、与案情相干」的证据才算数，于是「相关」义胜出——relevant 的根里举着案卷。\",\"resident\":\"reside 来自拉丁语 residere：re-「留在」+ sedere「坐」。在一处坐定不走，就是居住；resident 是坐稳了的人。seat、session 里的 sed 都是这把椅子。\",\"restricted\":\"restrict 来自拉丁语 restringere：re-「往回」+ stringere「拉紧、捆」。把绳子往回拉紧，就是 restrict；string（绳）与它同根，restricted 是被绳勒住的状态。\",\"site\":\"来自拉丁语 situs「位置、处所」。建筑落在 situs 上是工地，网站落在服务器上是站点——site 永远是「某样东西所在的那块地」。\",\"strategy\":\"来自希腊语 stratēgia「将军之术」：stratos「军队」+ agein「带领」。strategy 原是领兵打仗的调度学，进入会议室后，战场换成了市场，内核仍是「调兵遣将」。\",\"survey\":\"经盎格鲁-法语来自 sur-「在上」+ videre「看」（古法语 veoir）：站在高处把全景看一遍。测量是拿仪器看，问卷是拿问题看——survey 是两种「俯瞰」。\",\"text\":\"来自拉丁语 textus「织物」，源头 texere「编织」。文章是把句子一针一线织成的布：context（上下文）是与它织在一起的部分，textile（纺织品）是它字面意义上的本行。\",\"transfer\":\"来自拉丁语 transferre：trans-「横过」+ ferre「携带」。把东西、人或权利从这边「搬」到那边，就是 transfer；fer- 还生出了 ferry（渡船）：专门搬运过河的船。\",\"bacteria\":\"bacterium 的复数，来自希腊语 baktērion「小手杖」，是 baktron「杖」的指小词。19 世纪显微镜下见到的多是杆状菌，形状像小棍，于是整类微生物都姓了「棍」。\",\"barrier\":\"经古法语 barriere 来自 barre「横木、闩」（高卢语源）。最早的屏障就是横在路口的一根木头；bar（酒吧柜台、律师栏）与它同根，都是那根横木。\",\"climate\":\"来自希腊语 klima「倾斜」，源头 klinein「倾斜」。古希腊人按太阳光线倾斜的程度把大地分成寒、温、热带——climate 说的先是纬度，后才是天气。clinic（诊所）里也有这个「倾斜」：病床是斜靠的床。\",\"component\":\"来自拉丁语 componere：com-「一起」+ ponere「放置」——被放进来组成整体的那一件。compose、composition 与它同根：都是把部件「放」成一个整体。\",\"compound\":\"混合义来自拉丁语 componere「放在一起」（com- + ponere），把多种成分放成一物。有意思的是「围起的院落」义另有来源：经印度英语借自马来语 kampung「村落、营地」——同一个拼写，两条来路。\",\"concentrate\":\"近代拉丁语风格的构词：con-「一起」+ centrum「中心」（希腊语 kentron「尖点」）。把散在四周的东西和注意力一同往「圆心」收，就是 concentrate。\",\"consequence\":\"来自拉丁语 consequi：con-「紧贴」+ sequi「跟随」。后果就是紧贴着前因跟上来的东西；sequence（序列）与它同根，全家族都在「跟」着走。\",\"conserve\":\"来自拉丁语 conservare：con- + servare「看守、保存」。serve 的祖先本就是「守」：preserve（预先守）、conserve（一起守）、observe（对着守）是一串看守者。\",\"constant\":\"来自拉丁语 constans，源头 constare：con-「一起」+ stare「站」——稳稳站住不动。恒量、常量、始终如一，靠的都是「站得住」；consistent 与它同根。\",\"creature\":\"来自拉丁语 creatura，源头 creare「创造」——「被造出来的东西」。create 的一切产物都是 creature，人也是造物中的一员时，才称 creature。\",\"density\":\"来自拉丁语 densitas，源头 densus「稠密的、厚的」。dense 是「挤得密」：人群挤是 dense，物质每单位体积挤了多少，就是 density。\",\"dissolve\":\"来自拉丁语 dissolvere：dis-「分开」+ solvere「松开」。盐在水里松散开是溶解，议会散掉也是 dissolve；solve（解题）与它同根：解，就是把结松开。\",\"distinct\":\"来自拉丁语 distinguere「戳开区分」的完成形态，与 distinction 同根：两样东西被分得清清楚楚，各自站出轮廓，就是 distinct。\",\"emit\":\"来自拉丁语 emittere：e-「出」+ mittere「送」。烟囱送烟、灯送光、广播送信号，都是把东西「送出去」。mission、submit 里的 mit 都是这只「送」的手。\",\"erosion\":\"来自拉丁语 erodere：e- + rodere「啃咬」——大地被水和风一点点「啃」掉。rodent（啮齿动物）与它同根：老鼠的门牙和河流，用的是同一种吃法。\",\"evaporate\":\"来自拉丁语 evaporare：e-「出」+ vapor「蒸气」。水变成 vapor 散出去就是 evaporate；vapor 本人也是这条词源里的正主。\",\"expand\":\"来自拉丁语 expandere：ex-「向外」+ pandere「铺开、张开」。像打开一把折扇：pandere 的「张」还藏在 span（跨度）里，只不过走的是日耳曼语的远亲路。\",\"experiment\":\"来自拉丁语 experimentum「试验」，源头 experiri「尝试、经历」（periri 与 periculum「危险」同根）。经验与实验本是一家：experience 是试过之后留下的，experiment 是主动去试。\",\"extinct\":\"来自拉丁语 exstinguere：ex- + stinguere「掐灭」——像掐灭一根蜡烛。物种的火熄了就是 extinct；灭火器 extinguisher 是字面意义上的「掐灭者」。\",\"habitat\":\"就是拉丁语 habitat 本人：「它栖息（于）」。旧时动植物志在学名下写「Habitat in…」（它住在…），写着写着，habitat 就成了「栖息地」的专名；habit、inhabit 与它同根，都是 habitare「住」。\",\"hazardous\":\"hazard 经古法语 hasard 来自阿拉伯语 az-zahr「骰子」。十字军把掷骰赌博带回欧洲，「运气局」引申为一切碰运气的事——hazard 从赌桌走出来，成了「危险」。\",\"humid\":\"来自拉丁语 humidus，近亲 humor 本义是「液体、体液」。空气里液体（水汽）多了就是 humid；humor 后来专指体液决定的性情，才有了「幽默」义。\",\"immune\":\"来自拉丁语 immunis：im-「免于」+ munis「义务、赋役」——本指免除徭役税负的人。义务免了，疾病这项「赋税」也免了：immunis 从财政词变成了医学词。\",\"inhabit\":\"来自拉丁语 inhabitare：in-「在内」+ habitare「居住」（habitare 是 habere「持有」的频繁体）。住进去、住下来；habitat 是它写在图鉴上的亲兄弟。\",\"magnet\":\"来自希腊语 magnētis lithos：「马格尼西亚（Magnesia）的石头」。小亚细亚这座城一带产天然磁石，地名就此成了磁的学名；magnetic、magnesium 与它同城出身。\",\"mechanism\":\"来自希腊语 mēkhanē「机械、巧妙的装置」（据说与「手段、权谋」同根）+ -ism。先指机器的构造法，后来任何「运作机理」都叫 mechanism——社会机制也是台看不见的机器。\",\"moisture\":\"经古法语 moiste「潮湿的」而来，再上溯与拉丁语 mucidus「发黏发霉的」有关（学界对其间细节尚有讨论）。moist 是那股潮气本身，moisture 是潮气里的水分含量。\",\"nutrient\":\"来自拉丁语 nutrire「喂养、哺育」（nutrix 是「乳母」）。nutrient 是喂养身体的东西；nurse（护士）与它同根，最初也是「哺育者」。\",\"organism\":\"来自希腊语 organon「工具、器官」（organ 本人）+ -ism：由各司其职的器官拼成的整体，才叫 organism。一个器官是工具，一整套工具协同，就是生命。\",\"particle\":\"拉丁语 particula 是 pars「部分」的指小词——「一小部分」。物理学的粒子、语法的虚词（小品词），都是大整体上拆下来的「小份儿」；part 与它同根。\",\"phenomenon\":\"来自希腊语 phainomenon「显现出来的东西」，源头 phainesthai「显现」（phanein「使显现」）。现象就是「自己显形给你看」的事物；fantasy、phantom 里的 phan 都是这道显形的光。\",\"pollute\":\"来自拉丁语 polluere「弄脏、玷污」，最初多用于宗教语境的「渎污」。污染词源里先有神圣被玷污的沉重，后来才轮到河流与空气。\",\"preserve\":\"来自拉丁语 praeservare：prae-「预先」+ servare「守护」。在坏掉之前先守住它：果酱是守住的水果，保护区是守住的荒野；conserve 与它同为 servare 的看守队。\",\"stable\":\"形容词来自拉丁语 stabilis「站得稳的」（stare「站」）；名词「马厩」来自 stabulum「牲口站立之处」——同根两兄弟：一个讲站得稳，一个讲站的地方。\",\"substance\":\"来自拉丁语 substantia：sub-「在下」+ stantia（stare「站」）——「站在底下的东西」。表象之下撑着的实体，就是 substance；本质、物质、实质三义都从这根柱子长出来。\",\"transform\":\"来自拉丁语 transformare：trans-「横越、改变」+ forma「形状」。越过原来的形状到新形状，就是 transform；form（形状）是全家族的模子。\",\"vapor\":\"就是拉丁语 vapor 本人：「蒸气、水汽、热气」。水受热升起的那缕气，从罗马厨房到物理实验室，一直叫这个名字；evaporate 是让它散出去。\",\"visible\":\"来自拉丁语 visibilis，源头 videre「看」——「看得见的」。video、vision、visit 里的 vid/vis 都是这双眼；invisible 只是加了「不」。\",\"collapse\":\"来自拉丁语 collapsus，源头 collabi：com-「一起」+ labi「滑、坠」。整座东西一起滑塌下去就是 collapse；lapse（ lapse 失误、 lapse 流逝）里的 lab 也是这只打滑的脚。\",\"detect\":\"来自拉丁语 detegere：de-「揭去」+ tegere「遮盖」（tectum 是「屋顶」）。把盖子揭开，藏着的东西就露了出来——detect 是侦探的第一课；protect（在前面盖护）与它同根。\",\"discharge\":\"来自晚期拉丁语 discarricare：dis-「卸下」+ carrus「大车」（car 的祖先）——把车上的货卸空。卸货引申出排放、释放、出院、退役：都是把「载着的东西」放出去。\",\"duration\":\"来自拉丁语 durare「变硬、撑下去」，源头 durus「硬的」。时间靠「硬撑」熬出长度就是 duration；durable（耐用的）与它同根：够硬，才撑得久。\",\"eliminate\":\"来自拉丁语 eliminare：e-「出」+ limen「门槛」——把人或事「赶出门槛之外」。eliminate 的原画是逐客令：跨出这道门槛，就不在局内了。\",\"emission\":\"来自拉丁语 emissio，源头 emittere：e-「出」+ mittere「送」。emit 是动作，emission 是送出去的那批东西（废气、射线、信号）——送与被送，一对名词动词。\",\"empirical\":\"来自希腊语 empeirikos，源头 empeiria「经验」，再往里是 peira「尝试」。靠亲手试出来的知识才叫 empirical；experiment 里的 peri 也是这只「试」的手——经验与实验在希腊语里本是近亲。\",\"enormous\":\"来自拉丁语 enormis：e-「出」+ norma「角尺、规矩」——大出规矩之外。enormous 的「巨大」是量出来的：超尺三寸，方为巨大；norm 与它同尺。\",\"equilibrium\":\"来自拉丁语 aequilibrium：aequus「平的」+ libra「秤、天平」。秤两端一样沉、静止不动，就是 equilibrium——物理与经济里的平衡，都源于这杆罗马秤。\",\"exceed\":\"来自拉丁语 excedere：ex-「出」+ cedere「走」——走出了界。超出限额、超过前人，都是脚跨过了那条线；proceed、succeed 里的 ceed 都是这双「走」的脚。\",\"expose\":\"经古法语 exposer（poser「放置」受拉丁语 exponere 影响）而来：ex-「出」+ ponere「放」——把东西摆到外面来。曝光、揭露、展出，都是「摆出来给人看」。\",\"fragment\":\"来自拉丁语 fragmentum，源头 frangere「打碎」。碎下来的那一片是 fragment；fraction（分数、碎片）与它同根，都是整体被「打」开后的小份。\",\"frequency\":\"来自拉丁语 frequentia「拥挤；频繁」，源头 frequens「挤满的、常来的」。先是人挤人地常来，后来物理学家借它数振动的「常来程度」——频率就是单位时间里来的次数。\",\"genetic\":\"来自希腊语 genesis「起源、产生」（gen 本义「生」）。genetic 管的是「生」的学问：基因如何生、性状如何传；generate、genius 里的 gen 都是这个「生」。\",\"global\":\"来自拉丁语 globus「球」+ -al。globe 先是地球仪那个球，global 再把「整个球」放大成「全世界、整体」——全球化就是把事做到整个球面上。\",\"inherent\":\"来自拉丁语 inhaerere：in-「在内」+ haerere「黏着」。天生黏在事物内部、剥不下来的属性，就是 inherent；adhesive（黏合剂）里的 hes 也是这股黏劲。\",\"input\":\"英语本土复合：in「进」+ put「放」。放进去的东西（数据、投入）就叫 input；output 是它的镜像。put 的来历朴素，作用不小。\",\"insert\":\"来自拉丁语 inserere：in-「进」+ serere「连接、成串（另一义为播种）」。把一物串进、插进另一物之间，就是 insert；series（系列）与它同根，都是「串成一串」。\",\"inspect\":\"来自拉丁语 inspicere：in-「往里」+ specere「看」。往里看仔细了，就是 inspect；aspect、respect、suspect 里的 spect 家族，全是「看」的各种角度。\",\"integrate\":\"来自拉丁语 integrare「使完整」，源头 integer「完整的、未受触碰的」（in- + tangere「触碰」）。把散件拼回完整整体是 integrate；integrity（正直）是人格上的同一种完整。\",\"intense\":\"来自拉丁语 intensus，源头 intendere「拉紧、张满」（tendere「张拉」）。弦拉得越紧，强度越大：intense 是张力拉满的状态；intend（打算）是心弦朝目标拉紧。\",\"interact\":\"现代构词：inter-「相互」+ act「行动」，act 再上溯拉丁语 agere「做、驱动」。两个主体互相「做」到对方身上，就是 interact——词很新，根很老。\",\"internal\":\"来自中世纪拉丁语 internalis，源头 internus「在里面的」，再往上是 intra「在内」。门以内的事都是 internal；interior（内饰）与它同门。\",\"interpret\":\"来自拉丁语 interpretari，与 interpretation 同源：interpres 是站在双方之间的「居间译者」。interpret 就是做这个居间人——演奏者诠释乐曲，也是在乐谱与听众之间做译者。\",\"interval\":\"来自拉丁语 intervallum：inter-「之间」+ vallum「木栅营墙」。罗马军营两道栅墙之间的空地，就是 interval 的原画；后世的时间间隔、音程，都住在这片空地上。\",\"invisible\":\"in-「不」+ visible「看得见的」（拉丁语 visibilis，videre「看」）。眼力到不了的地方，就是 invisible——它和 visible 共用同一双眼睛，只差一个否定。\",\"layer\":\"出自 lay（铺放，古英语 lecgan）的派生，本义近于「铺放（的动作/铺出的东西）」。一层就是被铺开摊平的一摊；layer 与 lie（躺）同属「平放」这一古老家族。\",\"magnetic\":\"magnet（磁石）+ -ic：magnet 来自希腊语「马格尼西亚的石头」。地名生词根，词根再派生形容词——magnetic 的磁性，一半在物理，一半在地名里。\",\"advocate\":\"来自拉丁语 advocatus：ad-「到…跟前」+ vocatus「被召唤的」（vocare「叫」）——被叫到法庭上替人说话的人。voice 里的 voc 是同一副嗓子：advocate 用嗓子替人发声。\",\"allocate\":\"来自中世纪拉丁语 allocare：ad-「向」+ locare「放置」（locus「地方」）。把资源一份份放到各自的地方去，就是 allocate；location 与它同根，先有「地」，才有分配。\",\"bias\":\"经古法语 biais「斜的、倾角」而来（更上游来源尚有争议）。直线斜了就是 bias：滚地球斜着走，判断斜着偏——偏见是思想里的斜线。\",\"campaign\":\"经法语 campagne 来自意大利语 campagna「平原、原野」，源头拉丁语 campus「旷野」。军队在平原上扎营作战的一季叫 campaign；竞选与营销借走了这套「系列作战」的打法。\",\"cease\":\"来自拉丁语 cessare「停下、歇息」，是 cedere「让开、走开」的频繁体。ceasefire 的 cease 就是这只停下来的手；process、exceed 里的 cess/ceed 同出一门「走」。\",\"challenge\":\"经古法语来自拉丁语 calumniari「诬告、中伤」（calumnia「诽谤」）。它先指「指控、责难」，再到「向人叫板质疑」，最后才是「挑战」——词义从中伤一路打到了竞技场。\",\"clarify\":\"来自晚期拉丁语 clarificare：clarus「明亮、清楚」+ facere「使」。把浑的讲亮、把暗的照透，就是 clarify；clear 本人就是 clarus 经法语走来的后代。\",\"colleague\":\"来自拉丁语 collega：col-「共同」+ legare「选派、委任」（lex 家族的亲戚）——一同被选任办事的人。league（联盟）与它同源：同事先是「同盟」。\",\"compensate\":\"来自拉丁语 compensare：com-「一起」+ pensare「称量」（pendere「称、挂」的频繁体）。两边一起上秤、称到一样平，就是 compensate；pension（养老金）里也藏着这杆秤。\",\"conflict\":\"来自拉丁语 confligere：con-「一起」+ fligere「撞击、打击」。两股力量撞到一处就是 conflict；afflict（折磨）里的 flict 也是这记「击」。\",\"consent\":\"来自拉丁语 consentire：con-「一起」+ sentire「感觉」——感觉一致、心往一处想，就是 consent（同意）。sense、sentiment 里的 sent 都是这颗「感」的心。\",\"considerable\":\"consider 来自拉丁语 considerare：con- + sidus（属格 sideris）「星辰」——原指占星家凝神观星，后转「深思熟虑」。值得如此细看的东西，分量自然不小：considerable 是「值得盯着看那么久」的大小。\",\"contemporary\":\"来自中世纪拉丁语 contemporarius：con-「共同」+ tempus「时间」。活在同一段时间里的人与物，就是 contemporary；tempo（节奏）与它同根，都是时间的刻度。\",\"convention\":\"来自拉丁语 conventio，源头 convenire：con-「一起」+ venire「来」——人来到一起是「大会」，大家约定俗成来到一起的做法就是「惯例」。convene 与它同门。\",\"convince\":\"来自拉丁语 convincere：con- + vincere「征服、胜诉」。原义是用法理把人「辩服、证服」：convince 不是说服，是拿证据打赢。victory 里的 vinc 是同一面凯旗。\",\"core\":\"词源存疑：中古英语 core 的确切来历学界没有定论，流传最广的说法是经古法语 cuer 与拉丁语 cor「心」有关，也有学者另有推测。可以先记成「心」——但请知道，这一条连词源词典都标注着不确定。\",\"corporate\":\"来自拉丁语 corporatus，源头 corpus「身体」。一群人结成一个法律上的「身体」，就是 corporation；corporate 是属于这个身体的。corpse（尸体）与它同根，也是 corpus。\",\"criteria\":\"希腊语 kritērion「判断标准」的复数形式（单数 criterion）。希腊语 -on 结尾的词复数变 -a：phenomenon/phenomena 是同一套变形——criteria 天生就是「一堆标准」。\",\"culture\":\"来自拉丁语 cultura「耕作」，源头 colere「耕种、照料、崇奉」。西塞罗把 colere 用到心灵上：cultura animi「耕耘心田」。种田的词长成了文化；cult（崇拜）与它同根，都是「照料」。\",\"debate\":\"经古法语 debatre 来自拉丁语系的 battuere「打」（de- 加强语气）：言语上互相「打」。battle（战斗）与它同根：辩论是文明化了的对打。\",\"dedicate\":\"来自拉丁语 dedicare：de- + dicare「宣告、奉为神圣」（dicere「说」的亲戚）。在神前宣告奉献出去，就是 dedicate；dictate（口述）里的 dic 也是这张「说」的嘴。\",\"deny\":\"经古法语 denier 来自拉丁语 denegare：de- + negare「说不、否认」（neg 本义「不」）。把话头一口说死就是 deny；negative 与它同根，neg 是否定的拉丁招牌。\",\"despite\":\"经古法语 despit 来自拉丁语 despectus「轻蔑」，源头 despicere：de-「向下」+ specere「看」——往下看人。在对方的轻蔑之下仍然去做，就是 despite（尽管）。\",\"dilemma\":\"来自希腊语 dilēmma：di-「二」+ lēmma「前提、论题」。修辞学里指「两个前提都成立、却把人逼到墙角」的论式——选哪边都难，进退两难由此得名。\",\"discriminate\":\"来自拉丁语 discriminare，源头 discrimen「分界、区别」（cernere「筛分」的家族）。词根只是「分得开」：中性的辨别与贬义的歧视，共用同一条分界线，褒贬在用法里分家。\",\"diverse\":\"来自拉丁语 diversus，源头 divertere：di-「分开」+ vertere「转」。朝不同方向转开，就是 diverse；universe（朝着一个整体转）、version（转出的版本）里的 vert 都是这圈「转」。\",\"dominate\":\"来自拉丁语 dominari「做主人」，源头 dominus「主人」，再往上是 domus「家」。一家的主人放大成一方的统治者：dominate 是「当家作主」的外扩；dominion、dominant 同门。\",\"encounter\":\"经古法语 encontrer 来自晚期拉丁语 incontrare：in- + contra「相对」——迎面相对而行。偶遇与交锋同是一个 encounter：迎面撞上，是人是敌看情境。\",\"enforce\":\"经古法语 enforcer 而来：en-「使」+ force「力量」（拉丁语 fortis「强壮」）。把规则配上力量去执行，就是 enforce；fort（堡垒）与它同根，都是「强」。\",\"enhance\":\"经盎格鲁-法语 enhauncer 而来：en- + hault「高」（与拉丁语 altus「高」有关，中途受 al- 词影响）。本义是「抬高」：价格抬高是市价，品质抬高就是 enhance（提升）。altitude 里的 alt 是这座「高」。\",\"ethic\":\"来自希腊语 ēthos「习俗、品格」（经拉丁语 ethica 进入英语）。ēthos 先是一个人或一群人惯常的样子，后来沉淀成「什么该做」的学问：ethics。\",\"evaluate\":\"经法语 évaluer 构词而来：é-「出」+ value（拉丁语 valere「有价值」）。与 evaluation 同一条路：把价值从里面估出来、亮到明处。\",\"eventually\":\"event 来自拉丁语 eventus「结果、发生的事」，源头 evenire：e-「出」+ venire「来」——事情「走出来」落定的样子。eventually 就是「等一切走到落定之时」。\",\"exclude\":\"来自拉丁语 excludere：ex-「外」+ claudere「关、闭」。把人关在门外就是 exclude；include 是把人关进门内，close 与两者同根，都是这扇「关」的门。\",\"exploit\":\"经古法语 esploit 来自拉丁语 explicitum「展开的东西」，源头 explicare：ex- + plicare「折叠」——把折着的展开做成事。它先指「功绩、成就」（褒义），近代才滑向「利用、剥削」；explain 与它同根。\",\"external\":\"来自拉丁语 externus「在外面的」，源头 exter「在外的」（ex 的比较级形态）。墙以外、体以外、国外，都是 externus 的领地；exterior 与它同门。\",\"facilitate\":\"经法语 faciliter 来自拉丁语 facilis「容易做的」，源头 facere「做」。facilitate 就是「让做起来更容易」；facility（设施）是为同样的事备下的便利。\",\"federal\":\"来自拉丁语 foedus（属格 foederis）「盟约、条约」。州与州立约结盟而成的体制，就是 federal；confederation（邦联）与它同盟同约。\",\"fee\":\"来自古英语 feoh「牲畜、动产、钱财」。在以牛羊计富的年代，财产就是牲口：fee 从「家当」一路变成「费用、酬金」。德语 Vieh（牲畜）是它的日耳曼亲兄弟。\",\"foundation\":\"来自拉丁语 fundatio，源头 fundus「底部、地基」。一切建筑先打 fundus：foundation 既是地基，也是奠基的基金会——fund（基金）与它同根，都是沉在底下的那笔根基。\",\"gender\":\"经古法语 gendre 来自拉丁语 genus「种类、出生」。它先在语法里指名词的「类」（阳/阴性），20 世纪才被借去指社会性别；genus 本人至今还在生物分类里当「属」。\",\"generate\":\"来自拉丁语 generare「生育、产生」，源头 genus「出生、种族」。gen- 是英语里最大的「生」家族之一：generation、gene、genius、general（生而统属）都从这条根上发芽。\",\"generation\":\"来自拉丁语 generatio，与 generate 同根（genus「出生」）。一代人是「同被生出的那一批」，发电是「生出电」——generation 的两大义项，共用一个「生」。\",\"goal\":\"来源不完全确定：中古英语 gol 指「界限、终点」，学界多推测它与古英语 gāl「障碍」一类词有关，但没有定论。可以确定的是它很早就指比赛的终点线——先有终点，才有目标。\",\"grant\":\"经盎格鲁-法语 granter 而来，再上溯与拉丁语 credere「相信、托付」有关（古法语 creanter「承诺给予」）。grant 的底色是「应允」：先准了，才给。credit 里的 cred 是这份「信」。\",\"guideline\":\"英语近代复合词：guide（向导，经古法语来自日耳曼语「看守、引领」的词根）+ line（线）。沿着线走不迷路的指示，就是 guideline——它生于现代管理文书，没有更古的词源。\",\"highlight\":\"英语近代复合词：high + light，源于绘画用语——画面上打得最亮的那块「高光」。后来修容、标重点、精彩集锦都借了这束光；词很新，画面很直。\",\"ignore\":\"来自拉丁语 ignorare「不知道」，源头是 in-「不」+ gnarus「知晓的」（gnoscere「认识」）。本义是真的不知，后来变成「明知而不理」；ignorant（无知的）是它尚未变心时的样子。\",\"immigrant\":\"来自拉丁语 immigrare 现在分词：in-「进入」+ migrare「迁徙」。迁进来的人是 immigrant，迁出去的是 emigrant——同一 migrare，方向不同，立场不同。\",\"imply\":\"来自拉丁语 implicare：in-「进」+ plicare「折叠」——把意思折在话里面。明说的是字句，折着藏的是 imply；explicit（展开说明的）是它的反面：把折页摊开。\",\"impose\":\"经法语 imposer（受拉丁语 imponere 影响）而来：in-「上」+ ponere「放」。把税、把规则「放」到别人头上就是 impose；position 里的 pos 也是这只「放」的手。\",\"incident\":\"来自拉丁语 incidere 现在分词：in-「到…上」+ cadere「落下」——正落在头上的事。incident 与 accident 是亲兄弟：一个是「落上的事」，一个是「偶然落上的事」，cad 都是「落」。\",\"index\":\"就是拉丁语 index 本人：「食指；指点者；告发者」，源头 indicare「指出」（dicere 家族）。食指天生是用来指的：目录、指数、指标，都是社会里的食指。\",\"industry\":\"来自拉丁语 industria「勤勉、不懈」，结构或为 indu-「在内」+ struere「建造」一系（细节有争议）。它在英语里先指「勤奋」，工业革命之后才专指「工业」——先有勤勉，后有工厂。\",\"initial\":\"来自拉丁语 initialis，源头 initium「开端」，再往上是 inire：in- + ire「走进去」——走进门的那一步，就是 initial。initiate（发起）与它同门。\",\"innovation\":\"innovate 来自拉丁语 innovare：in-「引入」+ novus「新的」。把新东西引进来就是 innovation；novel（新奇的、小说）与它同根，novus 是拉丁语的「新」招牌。\",\"insight\":\"英语本土复合：in「内」+ sight「看（sight 来自古英语 gesiht，与 see 同根）」。往里看穿一层，就是 insight——洞察是内向的看，不必远借拉丁。\",\"insist\":\"来自拉丁语 insistere：in-「在…上」+ sistere「站定」——在一点上站稳不退，就是 insist。consistent、assist 里的 sist 都是这双站定的脚。\",\"integrity\":\"来自拉丁语 integritas，源头 integer「完整无损的」（in-「未」+ tangere「触碰」）。未被碰坏的完整是 integrity 的肉身义，人格的完整无缺是它的道德义——integrate 与它同根。\",\"intervene\":\"来自拉丁语 intervenire：inter-「在中间」+ venire「来」。事情正进行时走到中间去，就是 intervene；event、convention 里的 ven 都是这双「来」的脚。\",\"invest\":\"与 investment 同源：拉丁语 investire 是 in- + vestis「衣服」，本义「穿上礼服就职」。把钱给一个项目「穿戴整齐送上场」，就是 invest。\",\"justify\":\"来自拉丁语 iustificare：iustus「公正的」（ius「法」）+ facere「使」。把一件事「做」得在法与理上立得住，就是 justify；justice 与它同根，ius 是罗马法的根。\",\"label\":\"经古法语 label「布条、饰带」而来（日耳曼语源，本义是垂下的一小条布）。系在行李和瓶身上的那条布，变成了 label；词源很朴素：一块布条。\",\"levy\":\"经法语 levée 来自拉丁语 levare「举起、抬起」（levis「轻」的亲戚）。官方「举手」征收款项就是 levy：levare 还生了 lever（杠杆）和 elevate（升起），都是往上抬。\",\"liberal\":\"来自拉丁语 liberalis「属于自由人的、慷慨的」，源头 liber「自由」。自由人当有的教养与大方，就是 liberal 的底；liberty 与它同根，liber 是「自由」的拉丁名。\",\"license\":\"来自拉丁语 licentia「许可、放任」，源头 licere「被允许」。纸面上的 licentia 是 licence（执照）；道德上的放任也是它——一词两面，靠语境分。\",\"likewise\":\"英语本土复合：like「同样」+ wise「方式」（wise 在此是古义「样子、方式」，非「聪明」）。用同样的方式，就是 likewise；otherwise 里的 wise 是同一个古义残留。\",\"link\":\"来自古诺尔斯语 hlekkr「链条的一环」。维京人带来的词：一环扣一环是 link，网页与人际的「链接」都是后代——先有铁链，后有超链接。\",\"locate\":\"来自拉丁语 locare「放置、安置」的分词形态，源头 locus「地方」。把东西放对地方是 locate，找到它所在的地方也是 locate；local 与它同根。\",\"logic\":\"来自希腊语 logikē（tekhnē）「推理的（技艺）」，源头 logos「言辞、理性、规律」。logos 是希腊思想的总根：logic 管它推理的一面，-ology（学科）管它成学的一面。\",\"mature\":\"来自拉丁语 maturus「成熟的、恰逢其时的」（本义「熟透了的果子」）。果子熟是时间给的，人熟是阅历给的；mature 两义都靠「到时候」。\",\"media\":\"medium 的拉丁复数：medium 来自拉丁语 medius「中间的」。夹在传者与受者「中间」的，就是 media；报纸广播是中间人，大众媒体义是 20 世纪才定型的。\",\"migrate\":\"来自拉丁语 migrare「迁徙、搬家」。候鸟、人群、数据都在 migrare：immigrant 是迁入者，emigrant 是迁出者，方向由前缀说了算。\",\"military\":\"来自拉丁语 militaris，源头 miles（属格 militis）「士兵」。miles 的兵穿上制服成了 military；militia（民兵）与它同营出身。\",\"minimal\":\"近代构词：拉丁语 minimus「最小的」+ -al。minimus 是 parvus「小」的最高级：「小到不能再小」就是 minimal 的出发点；minimum 是它的名词版。\",\"minimize\":\"minimus「最小」+ -ize「使…化」：把一样东西一路缩到最小，就是 minimize。构词是近代的，根是罗马的 minimus。\",\"minor\":\"就是拉丁语 minor 本人：magnus 家族的反面——「更小的」（比较级）。未成年是「更小的人」，小调是「更小的调式」，minor 一切义项都从「小」排起。\",\"mode\":\"来自拉丁语 modus「尺度、方式、限度」。音乐的调式、统计的众数、生活的模式，都是「以某种方式呈现」：modus 还生了 model、modern（正合时宜的）。\",\"modify\":\"来自拉丁语 modificare：modus「尺度」+ facere「做」——按尺度动手调整。modest（适度的）与它同根：都是把分寸拿捏在 modus 之内。\",\"monitor\":\"来自拉丁语 monitor「提醒者、告诫者」，源头 monere「提醒、警告」。先有站在身后提醒的人，后有盯着屏幕的显示器与班长；monument（纪念碑）也是 monere 的提醒：提醒后人别忘。\",\"motive\":\"来自中世纪拉丁语 motivus「能推动的」，源头 movere「移动」。能把人推动起来的那个因，就是 motive；motor、motion、emotion 里的 mov/mot 都是这台「动」的发动机。\",\"network\":\"英语本土复合：net（网，古英语 net）+ work（织作）。原指网状的织物，后来电线、铁路、人脉都织成了 net——因特网只是它最大的一张网。\",\"neutral\":\"来自拉丁语 neutralis，源头 neuter「两者都不」：ne-「不」+ uter「两者之一」。两边都不站，就是 neutral；neuter 至今还是语法的「中性」。\",\"nevertheless\":\"英语本土复合：never + the + less（古义结构近于「毫不因此而减少」）。让步再多，分量不减——nevertheless 是用三块古英语积木搭出的硬气。\",\"norm\":\"来自拉丁语 norma「木匠角尺」。与 normal 同器：先有量方的尺，后有「合乎规范」的 norm。社会规范这把尺，看不见，却人人被量。\",\"notion\":\"来自拉丁语 notio「概念、认识」，源头 noscere「认识、知道」。脑子里「认识成形」的那个想法就是 notion；note（记下以便认识）与它同根。\",\"objective\":\"来自中世纪拉丁语 obiectivus，源头 obicere：ob-「对着」+ iacere「抛」——被抛在面前的东西。摆在面前的「对象」引出「客观」，要抵达的对象引出「目标」——一词扛起两副担子。\",\"obtain\":\"来自拉丁语 obtinere：ob- + tenere「握住、持有」。握在手里不放，就是获得；retain（留住）、contain（容纳）里的 tain/ten 都是这只握紧的手。\",\"occupy\":\"来自拉丁语 occupare：ob- + capere「抓取」（经通俗形态进入法语再转英语）。先抓住、先占住：occupy 的军事义与日常「占用」义同是一只抢先的手。\",\"odd\":\"来自古诺尔斯语 oddi「角、尖端；奇数中多出的一」。数到成双后多出的那一个，天生有点「怪」：odd 从北欧语的算术里走来，奇数、零头、古怪都源于「多出来的一个」。\",\"offset\":\"英语复合：off + set，本义「分岔出去的一支」（植物的侧枝、印刷的转印），后引申为账目上「以此抵彼」。近代词，画面是分出去又抵回来。\",\"ongoing\":\"英语复合：on「继续」+ going「行进」，19 世纪成词。正在路上、还没停的，就是 ongoing——进行时语法里走出来的日常词。\",\"origin\":\"来自拉丁语 origo（属格 originis）「起源、出身」，源头 oriri「升起、诞生」。太阳升起处是东（orient 与它同根），事物诞生处就是 origin。\",\"outcome\":\"英语本土复合：out「出来」+ come「来到」。事情走到最后「出来」的结果，就是 outcome；income 是镜像：一个进来，一个出来。\",\"overall\":\"英语本土复合：over「遍布其上」+ all「全部」。罩住全部的总外套（它先指工装连体服）引申为「总体的」——先有衣服，后有概括。\",\"overlap\":\"英语本土复合：over「在上」+ lap「折叠、覆盖」（古英语 læppa「下摆、折边」）。一片盖住另一片就是 overlap；时间与职责的重叠，都是衣摆相压的画面。\",\"overseas\":\"英语本土复合：over「越过」+ sea「海」+ -s。海的那一头就是 overseas。英国是岛国，这个词带着岛民望海的方位感。\",\"accumulate\":\"来自拉丁语 accumulare：ad-「向」+ cumulus「土堆、堆」——往堆上再加一把。云里的积云 cumulus 与它同根：财富与云，都是堆出来的。\",\"acknowledge\":\"英语本土复合：a-（加强）+ knowledge（know 的名词形，know 来自古英语 cnāwan「认识」）。把心里知道的公开认下来，就是 acknowledge：知道是私事，认账是公事。\",\"adjust\":\"经古法语 adjuster 来自晚期拉丁语 adiustare：ad-「向」+ iustus「正当的」（旁系说法亦与 iuxta「靠近」有关）。把偏的拨向「正」，就是 adjust；just 本人就是 iustus 的后代。\",\"alter\":\"就是拉丁语 alter 本人：「（两者中的）另一个」。把一样东西改成「另一个样子」，就是 alter；alternative（另一个选择）是它最直系的后代。\",\"alternative\":\"alter（另一个）+ -ative 的中世纪拉丁构词：alter 本义「两者中的另一个」。正选之外永远站着的那一个，就是 alternative。\",\"amend\":\"来自拉丁语 emendare：e-「去」+ menda「缺点、错误」——把文本里的错抠掉。修正案 amendment 是议会版的 emendare；mend（修补）是它在英语里的短打亲戚。\",\"analogous\":\"来自希腊语 analogos：ana-「按照」+ logos「比例、道理」——「按同一比例相应」。analogy 是两个比例式站成一排：A 之于 B，如 C 之于 D。\",\"apparent\":\"来自拉丁语 apparere：ad-「向」+ parere「显现、出现」——显到眼前来。看得见的是「明显的」，看上去像的引申为「表面上的」；appear 与它同根。\",\"appreciate\":\"来自晚期拉丁语 appretiare：ad-「向」+ pretium「价格」。先是「给…定出价格」：价定得高是「欣赏、重视」，价自己涨上去就是「增值」——一个词管完审美与金融。\",\"arbitrary\":\"来自拉丁语 arbitrarius，源头 arbiter「裁判、仲裁人」。裁判一个人说了算，就是 arbitrary 的原罪：规则不在条文里，在某个人的裁量里。\",\"assemble\":\"经古法语 assembler 来自晚期拉丁语 assimulare：ad-「向」+ simul「一起」（similis 家族）。把人和零件都拢到「一起」，就是 assemble；assembly 是拢成的那一摊。\",\"assign\":\"来自拉丁语 assignare：ad-「向」+ signare「做标记」（signum「记号」）。在名册上给每人划一道标记分派任务，就是 assign；sign 与它同根。\",\"assist\":\"来自拉丁语 assistere：ad- + sistere「站到旁边」——与 assistance 同源：站到近旁，就是帮忙的开始。\",\"attain\":\"经古法语 ataindre 来自拉丁语 attingere：ad-「到」+ tangere「触碰」。手终于触到目标，就是 attain；tangent（相切）里的 tang 也是这只伸出去的手。\",\"attitude\":\"经法语 attitude 来自意大利语 attitudine「姿势」，再上溯拉丁语 aptitudo「合宜」（aptus「适合的」）。画家先说人体的姿势，世人再说心里的姿势——aptitude（才能）与它同根。\",\"attribute\":\"来自拉丁语 attribuere：ad-「向」+ tribuere「分配、归给」。把功劳、过错或性质「归派」给某人某物，就是 attribute；distribute 里的 tribute 是同一只分派的手。\",\"automatic\":\"来自希腊语 automatos：autos「自己」+ matos「有意愿的、动着的」（词根含「急切、努力」义）——自己愿意动起来的。automaton（自动人偶）是希腊人给会自己动的东西起的名。\",\"bulk\":\"来自古诺尔斯语 bulki「船舱里的货堆、货物」。北欧商船舱里堆起来的那一大摊，就是 bulk：体积、主体、大批，都源于「一大堆」。\",\"capable\":\"来自晚期拉丁语 capabilis「能容纳的」，源头 capere「抓住、容纳」。手里容得下、抓得住的本事，就是 capable；capacity（容量）与它同根：先有容，才有能。\",\"channel\":\"来自拉丁语 canalis「水管、沟渠」，源头 canna「芦苇、管子」（cane 同源）。水走的管是海峡与渠道，信息走的管是频道——channel 永远是「让流通过去的槽」。\",\"chart\":\"来自拉丁语 charta「纸、纸莎草纸」（希腊语 chartēs）。写在纸上的海图先叫 chart，后来一切表格图都姓 chart；card（卡片）与它同纸出身。\",\"classic\":\"来自拉丁语 classicus「属于第一等级的」，源头 classis「（按财产分的）等级、舰队」。罗马人把公民分等，最高一等的作品就是 classic；class（班级）与它同根：都是「分等」。\",\"clause\":\"来自中世纪拉丁语 clausa「收束的部分」，源头 claudere「关闭」。一句里自成段落收得住的，是从句；合同里一条条关严的，是条款——close 与它同根。\",\"coherent\":\"来自拉丁语 cohaerere：co-「一起」+ haerere「黏着」。前后黏得严丝合缝、不断裂，就是 coherent；inherent（黏在里面的）与它同根，hes 都是黏劲。\",\"coincide\":\"来自中世纪拉丁语 coincidere：co-「一起」+ incidere「落到」（in + cadere「落」）。两件事在同一时刻「落到一起」，就是 coincide——巧合是一次精准的双落。\",\"commence\":\"经古法语 comencier 来自通俗拉丁语 cominitiare：com- + initiare「开始」（initium「开端」）。比 begin 更正式的「开始」，骨子里仍是 initium 那一步：走进门去。\",\"commodity\":\"来自拉丁语 commoditas「便利、合宜」，源头 commodus：com- + modus「合尺度的」。合用、称手的货物才拿去交易：commodity 先是「有用之物」，后是「大宗商品」。\",\"communicate\":\"来自拉丁语 communicare「使共享」，源头 communis「共同的」。把私有的变共同的——消息、疾病、房间（相通）都算：communication 是「共享」的动词版。\",\"compatible\":\"来自中世纪拉丁语 compatibilis，源头 compati：com-「一起」+ pati「承受、受苦」——能一起「熬」下去的，就合得来。passion（激情、受难）里的 pat 也是这份「受」。\",\"compile\":\"来自拉丁语 compilare「搜罗、掠夺汇集」（原带贬义）。罗马作家用它骂人「东抄西凑」，现代人用它做正经事：汇编资料、编译代码——抄与编，只隔一个时代。\",\"complement\":\"来自拉丁语 complementum「补满之物」，源头 complere：com- + plere「填满」。缺的那一块补上，整体就满了；compliment（恭维）与它同根：把礼数「补满」的话。\",\"comprehensive\":\"来自拉丁语 comprehendere：com-「尽」+ prehendere「抓住」——一把全抓在手里。理解是心智的全抓，覆盖是范围的全抓：comprehensive 两头都是「不漏」。\",\"comprise\":\"经法语 compris（comprendre 的分词）回到拉丁语 comprehendere「抓全」。与 comprehensive 同根：一个整体把成员「抓」在怀里，就是 comprise（包括）。\",\"compute\":\"来自拉丁语 computare：com-「一起」+ putare「清点、思考」（putare 本义「修剪、清理」）。把账目一笔笔清点齐，就是 compute；computer 是替人清点的机器。\",\"conclude\":\"来自拉丁语 concludere：con-「严密」+ claudere「关闭」。把讨论关严收口是「结束」，把证据关严锁死是「断定」——一扇门，关出两个义项。\",\"concurrent\":\"来自拉丁语 concurrere：con-「一起」+ currere「跑」。与 current 同根：多件事、多条线同时跑到一处，就是 concurrent——「跑」家族的时间版。\",\"confer\":\"来自拉丁语 conferre：con-「一起」+ ferre「携带」。把意见带到一起是「商议」，把荣誉带给某人是「授予」；conference 就是众人带着话来的会。\",\"confine\":\"来自拉丁语 confinis「接界的、相邻的」，源头 finis「边界」+ 形容词化用法。把活动收进边界之内，就是 confine；finite（有限的）与它同界。\",\"confirm\":\"来自拉丁语 confirmare：con-（加强）+ firmare「使坚固」，firmus「结实的」。本来摇晃的，加上确认就 firm 了；firm（公司、坚实的）与它同根。\",\"conform\":\"来自拉丁语 conformare：con- + formare「按形状塑造」（forma「模子」）。照着共同的模子塑，就是 conform（遵从）；uniform（制服）是「一个模子」的极端版。\",\"constitute\":\"来自拉丁语 constituere：con- + statuere「设立」（stare「站」）。把部件立成整体是「构成」，把机构立起来是「设立」；constitution（宪法）是立国的那一次「设立」。\",\"constrain\":\"来自拉丁语 constringere：con-「紧」+ stringere「拉紧、捆绑」。绳子勒紧，行动就没了余地；restrict 与它同为 stringere 的绳索，只是方向一收一回。\",\"construct\":\"来自拉丁语 construere：con-「一起」+ struere「堆放、建造」。一层层把材料堆成结构，就是 construct；structure 本人就是 struere 堆出的成品。\",\"consult\":\"来自拉丁语 consultare（consulere「商议」的频繁体）。罗马元老「议事」用的就是这个词：consult 是带着问题去共商，consultant 是被请来共商的人。\",\"contradict\":\"来自拉丁语 contradicere：contra-「反着」+ dicere「说」。你说东、他说西，正面顶回去就是 contradict；dictate 里的 dic 是同一张嘴，这里用来「反着说」。\",\"contrary\":\"来自拉丁语 contrarius，源头 contra「相对、对着」。正对着站的，就是 contrary：意见相左、风向相逆，都源于「面对面」。\",\"contrast\":\"经法语来自意大利语 contrasto，源头是拉丁语 contra「相对」+ stare「站」——对着站。对着站，两边的差别自己跳出来：contrast 先是对峙，后是对比。\",\"contribute\":\"来自拉丁语 contribuere：con-「共同」+ tribuere「分派、给出」。大家一起往外给，就是 contribute；tribute（贡品）与它同根：给，是这条根的招牌动作。\",\"convene\":\"来自拉丁语 convenire：con-「一起」+ venire「来」——把人召到一起来。convention（大会）是它开成的会，convenient（方便的）是它「合到一起」的另一面。\",\"convert\":\"来自拉丁语 convertere：con-（加强）+ vertere「转」。彻底转个向：信仰转、币种转、格式转，都是 vertere 的转身；version 是转出来的一个版本。\",\"coordinate\":\"来自中世纪拉丁语 coordinare：co-「共同」+ ordinare「排成秩序」（ordo「行列、次序」）。把各方排进同一秩序里协同，就是 coordinate；坐标是数学里排好的那套秩序。\",\"correspond\":\"来自中世纪拉丁语 correspondere：cor-「相互」+ respondere「回答」。你来一封、我回一封是「通信」，两组数据彼此对上是「相符」——都是 respondere 的一唱一和。\",\"crucial\":\"近代词：拉丁语 crux「十字架、十字形」+ -ial。培根用 instantia crucis「十字路口的实例」指能一锤定音的判例（路口竖着十字标）——crucial 的「决定性」，是十字路口上必须选的那一下。\",\"cycle\":\"来自希腊语 kyklos「圆、环、轮」。轮子转回原点就是一个 cycle；bicycle（两个轮）、encyclopedia（环绕全部学问的「圆」）都出自这个圆。\",\"deduce\":\"来自拉丁语 deducere：de-「向下」+ ducere「引导」——顺着前提把结论一步步「引下来」。conduct、introduce 里的 duc/duct 都是这只引路的手。\",\"define\":\"来自拉丁语 definire：de- + finire「划定边界」。definition 是把界划出的动作，define 是动词本人：给词义圈地，就是定义。\",\"degrade\":\"来自晚期拉丁语 degradare：de-「向下」+ gradus「台阶、等级」。一级台阶一级台阶地往下走：品格、质量、地位都是这样 degrade 的；grade（等级）就是那级台阶。\",\"delay\":\"经古法语 delaier 而来，其构成学界一般解作 de- + laier「留下、推迟」（更深来源有争议）。大意是把事「留到后面」：delay 是时间被人为往后挪了一格。\",\"delete\":\"来自拉丁语 delere「抹去、销毁」（据说原指抹平蜡板上的字）。罗马人擦蜡板，今人按删除键：delete 的动作两千年没变，都是让字迹不复存在。\",\"denote\":\"来自拉丁语 denotare：de- + notare「做记号」，nota 是「记号」（希腊语 gnō- 家族在拉丁的远亲说法不一，此处只取 notare 面）。词在纸上指着它所记的那个意义，就是 denote；note 与它同根。\",\"depress\":\"来自拉丁语 depressus，源头 deprimere：de-「向下」+ premere「压」。往下压：经济被压低、心情被压低、按钮被压下——press 家族里最沉的一支。\",\"derive\":\"来自拉丁语 derivare：de- + rivus「小溪」——把水从源头引出支流。与 derived 同源：词与义，都是从源头之河引出来的水。\",\"deviate\":\"来自晚期拉丁语 deviare：de-「离开」+ via「道路」。离开正道拐出去，就是 deviate；via 至今还是「经由」的学名，deviation 是偏离的里程。\",\"device\":\"经古法语 devis「划分、计划」与拉丁语 divisus（dividere「分」）一系有关，本义是「设想、筹划出的东西」。先有心里的设计，才有手里的 device；devise（设计）是它的动词孪生。\",\"diagnose\":\"来自希腊语 diagnōsis：dia-「贯穿、彻底」+ gignōskein「认识」。把病情看穿认透，就是 diagnose；prognosis（预后）是它朝前看的兄弟：pro-「预先」认透未来。\",\"diagram\":\"来自希腊语 diagramma：dia- + graphein「写、画」——用线条画出来的说明图。grammar（语法）里的 gram 也是 graphein 的字：一个画形，一个写字。\",\"dictate\":\"来自拉丁语 dictare，是 dicere「说」的频繁体：「一遍遍说给人记」。口述是它，命令也是它——独裁者 dictator，就是那个只许自己「说」的人。\",\"differentiate\":\"来自中世纪拉丁语 differentiare，源头 differentia「差别」，再上溯 differre：dis-「分开」+ ferre「携带」——被带向两边，就是差别。different 是它分好的样子。\",\"diminish\":\"来自拉丁语 diminuere：de-（加强）+ minuere「使变小」，源头 minus「更少」。一点一点变小到几乎没有，就是 diminish；minute（微小的）与它同根。\",\"display\":\"经古法语 desploier 来自拉丁语 displicare：dis-「散开」+ plicare「折叠」——把折着的摊开来示人。dis- 在这里是「反着折」：展开即 display，陈列、显示皆然。\",\"dispose\":\"经法语 disposer（受拉丁语 disponere 影响）而来：dis-「分别」+ ponere「放置」——把东西各就各位地摆好。摆好了是「安排」，摆脱了是「处置」，摆出姿态是「倾向」。\",\"distort\":\"来自拉丁语 distortus，源头 distorquere：dis-「歪」+ torquere「扭转」。把直的扭歪：图像、声音、事实都能被 torquere 拧变样；torture（拷问）与它同根，也是「拧」。\",\"distribute\":\"来自拉丁语 distribuere：dis-「分开」+ tribuere「分配」——与 distribution 同源：把总量拆开，一份份分到各处。\",\"domain\":\"经古法语 demaine 来自拉丁语 dominium「所有权、领地」，源头 dominus「主人」。主人的地盘是 domain：庄园、领地、知识领域、互联网域名，都是「归谁管」的那片地。\",\"draft\":\"与 draw 同源：draft 是古英语 dragan「拉、拖」在书写与征兵语境里的变体拼写。草稿是「拉出来的初稿」，征兵是「抽拉出来的人」，汇票是「拉出的一笔款」——都从一只拖拽的手长出来。\",\"edit\":\"由 editor 回构而来的动词：editor 来自拉丁语 edere「出版」，即 e-「出」+ dare「给」——把书稿「给出去见世面」。先有出版人，后有编辑的动作。\",\"emerge\":\"来自拉丁语 emergere：e-「出」+ mergere「浸、沉」。从水里浮出水面就是 emerge；潜水艇浮上来、新星冒出来，都是 mergere 的出水一刻。merge（合并）是反方向的同一动作。\",\"enable\":\"英语近代复合：en-「使」+ able「能够的」（able 经法语来自拉丁语 habilis「得心应手的」）。使本来不能的变得能，就是 enable——构词年轻，根却落在「顺手」上。\",\"entity\":\"来自中世纪拉丁语 entitas，源头 ens「存在着的东西」，是 esse「是、存在」的分词。哲学先用它指一切「存在者」，后来法律与数据都借它装「独立的一摊事物」。\",\"equate\":\"来自拉丁语 aequare「使相等」，源头 aequus「平的、相等的」。把两个东西摆到等号两边，就是 equate；equation 是它写成的式子。\",\"equip\":\"经法语 équiper 来自古诺尔斯语 skipa「给船配备、编组船员」（skip 是「船」）。给船配齐人货的词，被陆地借了去：equipment 是现代版的「配齐」。\",\"equivalent\":\"来自晚期拉丁语 aequivalens：aequus「相等」+ valens（valere「有价值」）。值当得一样多，就是 equivalent——等式之外，它是「等值」的通用章。\",\"erode\":\"来自拉丁语 erodere：e- + rodere「啃咬」——与 erosion 同根：水和风是耐心的啮齿动物，erode 是它们一口一口的慢工。\",\"estate\":\"经古法语 estat 来自拉丁语 status「状态、地位」（stare「站」）。一个人的「地位」沉淀成他的「财产」，地产是地位最有形的部分；state 与它同根，都是「站出来的局面」。\",\"compel\":\"来自拉丁语 compellere：com-「一起」+ pellere「推、驱赶」——把人往一个方向合力推。推到无法拒绝，就是「迫使」；同根的 pulse 是「推得跳起来」。\",\"pulse\":\"来自拉丁语 pulsus「推、搏动」，源头 pellere「推」。心脏每推一下，动脉就跳一下——pulse 的词义里藏着一只推血的手。\",\"compulsion\":\"来自拉丁语 compulsio「强迫」，源头 compellere「合力驱赶」（pellere「推」）。心里像被一只手推着非做不可，就是强迫与强迫行为。\",\"expulsion\":\"来自拉丁语 expulsio「赶出」，源头 expellere：ex-「出」+ pellere「推」。把人或物推出门外，就是驱逐、开除。\",\"refugee\":\"经法语 réfugié 进入英语，源头是拉丁语 refugium「避难处」：re-「回」+ fugere「逃」。逃回安全地带的人，就是难民。\",\"mutation\":\"来自拉丁语 mutatio「改变」，源头 mutare「移动、变更」。基因序列被「搬动」一处，就是突变；mutare 还生出了 mutual——相互的，本义是「交换的」。\",\"nature\":\"来自拉丁语 natura「出生、本性」，源头 nasci「出生」的分词 natus。生下来就带着的样子先指「天性」，再扩到整个「自然界」。\",\"nation\":\"来自拉丁语 natio：本义「出生」，后指「同地出生的一群人、部族」，源头 nasci「出生」。国家一词，是从「共同的出生」长出来的。\",\"latency\":\"来自拉丁语 latens「藏着的」，源头 latere「潜伏、躲藏」。病毒、延迟都一样：东西一直在，只是藏着没显形——latency 就是藏着的那段时间。\",\"assault\":\"经古法语 assaut，源头是俗拉丁语 adsaltus「跳向（某人）」，再溯到 salire「跳」。扑上去的那一下，就是袭击。\",\"acclaim\":\"来自拉丁语 acclamare：ad-「朝向」+ clamare「喊叫」——朝着某人喊好。众人的喊声变成名望，就是喝彩与赞誉；exclamation 是把话喊出声。\",\"exclamation\":\"来自拉丁语 exclamatio，源头 exclamare：ex-「出」+ clamare「喊」。感叹号 exclamation mark，就是句子里那一声喊的标记。\",\"conquer\":\"经古法语 conquerre，源头是拉丁语 quaerere「寻求、获取」的俗拉丁形式 conquirere「追取」。一路追索拿下，就是征服——和 inquire「追问」同根。\",\"conquest\":\"经古法语 conqueste，源头是拉丁语 conquisita「追取所得」：conquer（征服）的名词形——打下来并占有的那一片，就是征服的成果。\",\"habit\":\"来自拉丁语 habitus「状态、样子」，源头 habere「持有、保持」。长期保持的样子分化为两义：保持的行为是「习惯」，它的老义「衣着」也是保持在身上的样子。\",\"rehabilitation\":\"来自中世纪拉丁语 rehabilitare：re-「再次」+ habilitare「使胜任」（habilis 源于 habere「持有」）。让伤者、罪犯重新「胜任生活」，就是康复与改造。\",\"exhibit\":\"来自拉丁语 exhibere：ex-「出」+ habere「持有」——把持有的东西拿到外面来。展览品和法庭证据，都是被「亮出来」的东西。\",\"exhibition\":\"来自拉丁语 exhibitio「拿出展示」，源头 exhibere（ex- + habere「持有」）。把东西成批亮出来给人看的场合，就是展览会。\",\"inhibit\":\"来自拉丁语 inhibere：in-「向内」+ habere「持有」——原意是勒住缰绳、往回拽。把冲动和反应拽住，就是抑制。\",\"invoke\":\"来自拉丁语 invocare：in-「对着」+ vocare「呼叫」——对着神明呼求。后来引申为援引法条、唤起记忆：都是把某个力量「叫出来帮忙」。\",\"applaud\":\"来自拉丁语 applaudere：ad-「朝向」+ plaudere「拍手」。冲着台上拍手叫好，就是鼓掌喝彩。\",\"explosion\":\"来自拉丁语 explosio，原义是「用拍手跺脚把演员哄下台」：ex-「赶出」+ plaudere「拍手」。后来才转指火药向外爆开——词里还留着剧场的嘘声。\",\"apparatus\":\"来自拉丁语 apparatus「准备、装备」，源头 apparare：ad- + parare「备好」。为一件事备齐的一整套东西，先指器械，后指机构、系统。\",\"apparel\":\"经古法语 apareil「装备、装扮」，源头是拉丁语 parare「准备」。把人装扮齐整要穿的那一身，就是服装；它和 apparatus 同出 parare 一家。\",\"parade\":\"经法语 parade，源于西班牙语 parada「停下来（展示）」，再溯到拉丁语 parare「准备」。本是骑兵停队列队备检的展示，后来成了游行、阅兵。\",\"compass\":\"经古法语 compas，源头是拉丁语 com-「一起」+ passus「步」：用步距量圆。两脚张开的圆规和指方向的罗盘，都从「量步」来。\",\"passenger\":\"经古法语 passager「过路的（人）」，源头 passus「步、通路」。在通路上搭程的人就是乘客；词尾的 n 是仿 messenger 一类词后来添的。\",\"password\":\"英语本土复合词：pass「通过」+ word「词」。守夜人口令制度的遗产——说对这句词，关卡就放你通过。\",\"abandon\":\"源于古法语短语 à bandon「任凭处置」：bandon 是「支配、许可」（日耳曼语源，和 ban「禁令」同族）。把某物交出去再不管，就是抛弃。\",\"refund\":\"来自拉丁语 refundere：re-「回」+ fundere「倒」——把（钱）原路倒回去。它和 fund「基金」（源于 fundus「底部」）形近而源异，别混。\",\"arrogant\":\"来自拉丁语 arrogans，源头 arrogare：ad- + rogare「提出、要求」——替自己提出过分的主张。要求得太多太满，就是傲慢。\",\"relativity\":\"relative 的名词化：relative 源于拉丁语 relativus，源头 referre 的分词 relatus（re-「回」+ latum「被带来」）。一切都要「参照着比较」，就是相对性；爱因斯坦的 relativity 由此得名。\",\"correlation\":\"来自中世纪拉丁语 correlatio：com-「共」+ relatio「关系」（源于 referre「带回、参照」）。两个量被带到一起互相参照，就是相关。\",\"correlate\":\"由 correlation 逆构而成，源头是拉丁语 com-「共」+ relatus「被参照的」（referre 的分词）。先有「相关关系」，再有「使相关、互相关联」的动词。\",\"collate\":\"来自拉丁语 collatus「被带到一起」，是 conferre 的分词（con- + ferre「带」）。把文稿逐页带到一起对照，就是核对、校勘。\",\"donation\":\"来自拉丁语 donatio，源头 donare「给予」，再溯到 donum「礼物」。把礼物给出去的正式说法，就是捐赠。\",\"donor\":\"经古法语 doneur，源头是拉丁语 donator「给予者」（donare「给」）。给血、给器官、给钱的人，都是 donor。\",\"condone\":\"来自拉丁语 condonare：con-「全然」+ donare「给予」——原意是「把（罪责）一笔赠掉」。赠掉对方的过错，就是宽恕、纵容。\",\"computer\":\"来自 compute（拉丁语 computare：com- + putare「清点」）+ -er。17 世纪的 computer 是「算账的人」，20 世纪才轮到机器接过这个名字。\",\"computation\":\"来自拉丁语 computatio，源头 computare「一起清点」（com- + putare「清点」）。把数字逐项点清的过程，就是计算。\",\"dispute\":\"来自拉丁语 disputare：dis-「分开」+ putare「清点、考量」——把账目一条条分开来算。算不清就吵起来，争论由此而来。\",\"determination\":\"来自拉丁语 determinatio「划界、限定」，源头 determinare：de- + terminus「边界」。给事划出边界是「测定」，给自己划界不动摇就是「决心」。\",\"extermination\":\"来自拉丁语 exterminare：ex-「出」+ terminus「边界」——原意是「驱逐出境」。后来词义加重：从赶出边界变成彻底消灭、根除。\",\"fund\":\"经法语 fond，源头是拉丁语 fundus「底部、地基」。钱的「底仓」沉在最下面供周转，就是基金、资金；同根的 foundation 是建筑的地基。\",\"fundamental\":\"来自拉丁语 fundamentalis，源头 fundamentum「地基」（fundus「底部」）。在最底下托住整座楼的，就是「根本的」。\",\"immigrate\":\"来自拉丁语 immigrare：in-「进入」+ migrare「迁徙」。迁进去定居就是移入；迁出去是 emigrate，方向全在前缀里。\",\"emigration\":\"来自拉丁语 emigratio 一系：e-「出」+ migrare「迁徙」。迁出原居地去别处定居，就是移居（国外）。\",\"expert\":\"来自拉丁语 expertus「试过、练过的」，源头 experiri「尝试、试验」。专家，就是同一件事试过无数遍的人；experiment（实验）是他的日常工作。\",\"predator\":\"来自拉丁语 praedator「掠夺者」，源头 praeda「猎物、战利品」。靠抢猎物过活的动物，就是捕食者。\",\"prey\":\"经古法语 preie，源头是拉丁语 praeda「抢来的东西、猎物」。predator 抢的，就是 prey——食物链的下端。\",\"amphibian\":\"来自希腊语 amphibios：amphi「两者」+ bios「生命」——「过双重生活的」。蝌蚪在水里、成蛙在岸上，名字就是它的履历。\",\"nocturnal\":\"来自拉丁语 nocturnus「夜间的」，源头 nox「夜」（属格 noctis）。夜里活动的动物叫 nocturnal；昼夜平分点 equinox 里的 nox 也是它。\",\"metabolism\":\"来自希腊语 metabolē「变换、更替」：meta「变」+ ballein「投掷」。身体把吃进来的物质拆开重组、投来换去，就是新陈代谢。\",\"parasite\":\"来自希腊语 parasitos：para「在旁」+ sitos「食物」——本指在神庙祭祀中「陪吃的人」，后指蹭饭的食客，再指生物学的寄生者：坐在别人饭桌旁的，就是它。\",\"symbiosis\":\"来自希腊语 symbiōsis「共同生活」：syn「一起」+ bios「生命」。19 世纪成为生物学术语：两个物种住在一起过日子，就是共生。\",\"herbivore\":\"19 世纪造的学术词：拉丁语 herba「草」+ vorare「吞吃」。吃草的动物叫 herbivore；构造法和 carnivore（吃肉）、omnivore（什么都吃）完全平行。\",\"carnivore\":\"源于拉丁语 carnivorus：caro「肉」+ vorare「吞吃」，19 世纪被正式用作食肉动物的学名；vorare 还生出了 devour（狼吞虎咽）。\",\"omnivore\":\"19 世纪造的学术词：omni「全部」+ vorare「吞吃」。草也吃肉也吃的杂食者就是 omnivore——vor「吞」是三兄弟（herbivore / carnivore / omnivore）的共同词根。\",\"rotation\":\"来自拉丁语 rotatio，源头 rota「轮子」。像轮子一样转是 rotation；轮班、轮作也是「轮」着来，都源于车轮的意象。\",\"constellation\":\"来自拉丁语 constellatio：con-「一起」+ stella「星」——一群星连成的图案。古人把星星连线成神话形象，星座由此得名。\",\"astronaut\":\"20 世纪造的新词：希腊语 astron「星」+ nautēs「水手」——「在星海里航行的人」。和 cosmonaut（苏联版，取 cosmos 宇宙）是一对冷战双胞胎。\",\"lunar\":\"来自拉丁语 lunaris「月的」，源头 luna「月亮」。月亮的盈亏管着历法，所以农历叫 lunar calendar。\",\"solar\":\"来自拉丁语 solaris「太阳的」，源头 sol「太阳」。太阳能、太阳系都姓 sol；它和希腊语 helios 分管拉丁、希腊两大家族。\",\"evident\":\"来自拉丁语 evidens：e-「出」+ videre「看」——「看得清清楚楚的」。证据 evidence 是它的同胞：能被看见的，才算数。\",\"ideology\":\"法语 idéologie 的借词，1796 年由哲学家德斯蒂·德·特拉西造出：希腊语 idea「观念」+ -logia「学问」，本义「观念学」，后指成套的政治信念。\",\"incompatible\":\"in-「不」+ compatible：compatible 源于拉丁语 compati「共同承受」（com- + pati「忍受」）。连「一起忍受」都做不到的，就是互不相容的。\",\"indifferent\":\"来自拉丁语 indifferens：in-「不」+ differre「相异」（dis- + ferre「带」）。怎么带都带不出差别，人就无所谓了——indifferent 是「看不出差别所以不在乎」。\",\"exchange\":\"经古法语 eschange，源头可溯到晚期拉丁语 cambire「交换」（高卢语来源）。以物易物的核心是「换」：change、exchange 都是它的后代。\",\"image\":\"来自拉丁语 imago「肖像、影像」，与 imitari「模仿」同源。脑子里的、镜子里的、屏幕上的，都是现实的一幅 imago。\",\"implement\":\"名词先行：晚期拉丁语 implementum「填充物、用具」，源头 implere「填满」（in- + plere「满」）。先有「干活的家什」，后有「把计划填实、落实」的动词义。\",\"incidence\":\"来自拉丁语 incidere：in-「到…上」+ cadere「落」——落在某事上。事件「落」到人群里有多密，就是发生率、发病率。\",\"initiate\":\"来自拉丁语 initiare，源头 initium「开端」：in-「入」+ ire「去」——走进门内。入会仪式和「发起」，都从跨进门槛开始。\",\"intrinsic\":\"来自拉丁语 intrinsecus「在内里的」：intra「内」+ secus「沿着」。价值从内部长出来的，就是内在的、本质的。\",\"feather\":\"来自古英语 feþer，与希腊语 pteron「翅膀」同出印欧语源 *pet-「飞」。鸟靠羽毛飞，词根里就藏着「飞」。\",\"whale\":\"来自古英语 hwæl，日耳曼语的老词。古人眼里最大的海兽就是它；古英语的拼写 hw- 后来调了个儿，成了 wh-。\",\"spider\":\"来自古英语 spīþra，字面是「纺织者」（源于 spinnan「纺」）。织网的纺织者——spider 的名字就是它的职业，和 spin 同族。\",\"offspring\":\"英语本土复合词：off「离」+ spring「涌出、生长」。从父母身上「生发出去」的，就是后代；spring 的生长义在这里留得最清楚。\",\"breed\":\"来自古英语 bredan「孵育、养出幼崽」。先有动词「繁殖」，后有它作名词指「品种」——马的 breed、狗的 breed，都是被一代代养出来的谱系。\",\"caterpillar\":\"经古法语 catepelose，字面是「毛猫」（cate 猫 + pelose 多毛的，源于拉丁语 pilus「毛」）。毛茸茸爬着的「小猫」，就是毛毛虫。\",\"trunk\":\"来自拉丁语 truncus「树干、被砍去枝叶的主干」。大象的长鼻像垂下的树干，行李箱最早是截段的圆木箱——两个义项都从树干来。\",\"nest\":\"来自古英语 nest，可溯到印欧语 *ni-sd-「往下坐的地方」（ni「下」+ sed「坐」）。鸟落下来坐稳的窝就是 nest——sed 和 president 的「坐」还是远亲。\",\"forest\":\"来自中世纪拉丁语 forestis（silva）「（城墙）外的林地」，源头 foris「门外」。王室把城外的林子划为猎场，forest 先是法律概念，后才是树木的集合。\",\"meadow\":\"来自古英语 mǣd「割过的草地」，与 mow「割草」同源。本是定期收割干草的田，后泛指一切开花的草甸。\",\"coast\":\"经古法语 coste，源头是拉丁语 costa「肋骨、侧面」。陆地伸向海的那条「侧边」，就是海岸；costa 还生出了 cutlet（肋排）。\",\"gulf\":\"经意大利语 golfo，源头是希腊语 kolpos「怀抱、衣褶、海湾」。海伸进陆地的怀抱状凹口，就是海湾。\",\"plateau\":\"法语 plateau「平盘子」的借词，源头 plat「平的」（希腊语 platys「宽阔」）。高高托起的一块平地，就是高原；plate（盘子）是它的小兄弟。\",\"plain\":\"来自拉丁语 planus「平坦的」。作名词指平原，作形容词指清楚、朴素——平的东西一眼见底，义项就是这样连起来的。\",\"valley\":\"经古法语 valée，源头是拉丁语 vallis「山谷」。两山之间低下去的那道，就是 valley。\",\"ridge\":\"来自古英语 hrycg「背、脊背」。山脊是山的背，屋脊是房的背——英语用身体部位给地形命名，ridge 是最典型的一个。\",\"basin\":\"经古法语 bassin「大盆」，源头可能是晚期拉丁语 baccinum「木盆」。盆的形状放大到地理尺度，就是盆地和流域。\",\"dune\":\"借自荷兰语 duin「沙丘」，可能再溯到凯尔特语的「小山丘」。低地国家靠它挡海，英语就把词一起借了过来。\",\"slate\":\"经古法语 esclat「碎片、裂片」。这种岩石天生爱裂成薄片，做屋顶瓦再合适不过——名字记着它的脾气。\",\"ore\":\"来自古英语 ōra / ār「黄铜、金属原块」。还没提炼的金属原料就是 ore，是纯粹的矿工老词。\",\"magma\":\"来自希腊语 magma「稠厚的膏泥」，源头 massein「揉捏」。地下揉成一团待发的稠浆，就是岩浆；喷出地表后改名 lava。\",\"lava\":\"意大利语 lava 的借词，本指那不勒斯一带「滑下山坡的洪流」，源头可溯到拉丁语 labi「滑落」。维苏威的熔岩流进英语，名字里还带着「往下滑」的动作。\",\"comet\":\"来自希腊语 komētēs「长头发的」，源头 komē「头发」。拖着长尾的星星在古人眼里是披头散发的异象——彗星的「彗」和它的「长发」是同一个观察。\",\"axis\":\"来自拉丁语 axis「车轴、轴线」。车轮绕轴转，地球绕地轴转，坐标系也绕轴展开——axis 始终是那个不动的中心线。\",\"tsunami\":\"日语借词：tsu「港」+ nami「浪」——「港里的浪」。海啸在外海不起眼，进了港才掀巨浪，名字精准地记着它的发作地点。\",\"hurricane\":\"经西班牙语 huracán，源头是加勒比泰诺语 Juracán——当地原住民的风暴之神。16 世纪随殖民航线进入欧洲语言，神名变成了天气名。\",\"typhoon\":\"来源是多股拧成的绳：希腊语 Typhōn（巨怪堤丰）、阿拉伯语 ṭūfān「大风」，与粤语「大風」在贸易港口汇合。词源学界一般认为 typhoon 是多源汇合的结果。\",\"tornado\":\"经西班牙语 tornado，源头 tronada「雷暴」（tronar「打雷」，源于拉丁语 tonare）。在美洲改拼后专指龙卷风——名字里先打雷，后起风。\",\"monsoon\":\"经葡萄牙语 monção、荷兰语 monssoen，源头是阿拉伯语 mawsim「季节」。跟着季节准时换向的风，就是季风。\",\"thunder\":\"来自古英语 þunor，与北欧雷神 Thor（托尔）同名同源。打雷就是雷神在敲——英语把神的名字留给了天气。\",\"lightning\":\"来自中古英语 lightening「发亮、闪光」，源于 light「光」。闪电的本质被古人记成「一道亮光」，和「减轻」无关。\",\"frost\":\"来自古英语 frost / forst，与 freeze 同源。冻出来的白霜，和「冻」本身同姓。\",\"hail\":\"来自古英语 hagol，日耳曼语老词，可能与希腊语 kakhlēx「小石子」同源——天下冰雹，如撒石子。此为学界常见推测。\",\"gust\":\"借自古诺尔斯语 gustr「一阵风」。维京人的词随海风吹进英语：一阵突起的风，就是 gust。\",\"storm\":\"来自古英语 storm，日耳曼语里专指狂风暴雨的老词，一千多年词形几乎没变。\",\"blizzard\":\"19 世纪美国新词，最早见于爱荷华州的报纸，具体来源未定。可以确定的是：它是大平原暴风雪给英语的新贡献，词源至今无定论。\",\"fog\":\"来自中古英语 fog，可能与斯堪的纳维亚语的湿气、雾气词有关，确切源头未定。这个词先在农人嘴里指田野湿气，后因伦敦雾名扬天下。\",\"mist\":\"来自古英语 mist「薄雾、昏暗」，日耳曼语老词，与荷兰语 mist 同源。比 fog 薄、比雨干的，就是 mist。\",\"dew\":\"来自古英语 dēaw，日耳曼语老词。夜里悄悄凝在草叶上的水，就是 dew；词形两千年来几乎未动。\",\"turtle\":\"经法语 tortue 变来（拼写受了斑鸠 turtle 一词的影响），更深的源头一般溯到晚期拉丁语 tartarucha「（来自冥界的）爬虫」，带点迷信色彩，说法未完全定死。\",\"penguin\":\"来源未定：流传最广的一说是威尔士语 pen「头」+ gwyn「白」——原指北大西洋的大海雀，后来被南半球这群不会飞的鸟借了名；另一说源于拉丁语 pinguis「肥胖」。学界尚无定论。\",\"shark\":\"16 世纪进入英语，来源不明：可能与德语 Schurke「恶棍」有关，也可能源于玛雅语的鱼名。可以确定的是，它是航海时代硬闯进英语的新词，确切出身至今是谜。\",\"aftermath\":\"英语本土复合词：after + math——math 是古英语 mæð「收割」！第一茬割完后长出的第二茬草叫 aftermath，后来专指事情（多指灾祸）的后续与余波。\",\"termite\":\"来自晚期拉丁语 termitem（主格 termes）「蛀木虫」，与 terere「磨损、蛀蚀」同族。白蚁不是蚁，却把「蛀木头」写进了名字里。\",\"district\":\"源于中世纪拉丁语 districtus「管辖区」，本义是领主收紧管辖（distringere「拉紧」）的范围。区先是权力圈出的地盘，后才是行政地图上的格子。\",\"strait\":\"经古法语 estroit，源于拉丁语 strictus「狭窄的、拉紧的」。海面被两岸夹紧的窄道叫 strait；它与 strict 同根。\",\"consulate\":\"来自 consul（古罗马执政官、后为外交领事）+ -ate（职位、机构）：领事办公与居住的馆舍，就是领事馆。consul 一词源于 consulere「商议」。\",\"meticulous\":\"来自拉丁语 meticulosus「胆怯的、提心吊胆的」，源头 metus「恐惧」。一丝不苟的词源是「怕」：因为怕出错，才处处小心——meticulous 最早在英语里就是「战战兢兢」的意思，后来才转成褒义的细致。\",\"ambiguous\":\"来自拉丁语 ambiguus「两可的、动摇的」，拆开是 ambi-「向两边」+ agere「驱使」：被往两个方向推，站不稳。模棱两可的词源画面，就是左右摇摆。\",\"proliferate\":\"由拉丁语 proles「子孙、后代」+ ferre「生育、携带」拼成（prolifer「多产的」），19 世纪进入英语。激增的词源是「生孩子般地繁衍」：数量不是加上去的，是生出来的。\",\"resilient\":\"来自拉丁语 resilire「跳回」，拆开是 re-「回」+ salire「跳」。弹性、韧性的词源就是弹跳本身：被压下去，还能跳回原形；result（结果是「跳出来」的）、insult（「跳到人身上」）都是 salire 的亲戚。\",\"ubiquitous\":\"来自拉丁语 ubique「到处」，拆开是 ubi「哪里」+ -que「任何」：任何地方。无处不在的词源不绕弯，就是「哪里都有」。\",\"pragmatic\":\"来自希腊语 pragmatikos「与做事有关的」，源头 pragma「所做的事、事务」，动词是 prassein「做、实行」。务实的词源站在理论对面：先把事做了再说。\",\"hypothesis\":\"来自希腊语 hypothesis「根基、设想」，拆开是 hypo-「在下面」+ tithenai「放置」：先在下面垫一块基础，再往上盖论证。thesis（论点）是它的同根兄弟，假说就是「垫底的那块砖」。\",\"intricate\":\"来自拉丁语 intricare「缠住、使纠结」，源头 tricae「纠缠不清的琐事、麻烦」（更深来源不确定）。错综复杂的词源画面很具体：一团解不开的线。\",\"alleviate\":\"来自晚期拉丁语 alleviare「使变轻」，拆开是 ad-「向」+ levis「轻」。缓解的词源是减负：把痛苦的重担拿轻一点；levity（轻浮）、lever（杠杆，抬起之物）都出自这个「轻」。\",\"ephemeral\":\"来自希腊语 ephēmeros「只活一天的」，拆开是 epi-「在…上」+ hēmera「一天」。短暂的词源拿蜉蝣打比方：朝生夕死，寿命以天计；ephemeris（天文历）记的也是逐日的位置。\",\"deteriorate\":\"来自拉丁语 deteriorare「使变得更糟」，源头 deterior「更坏的」（比较级，与 de-「向下」同族）。恶化的词源自带方向：往下坡走，就是变坏。\",\"eloquent\":\"来自拉丁语 eloquens，拆开是 e-「向外」+ loqui「说」：把话说出口、说流畅。雄辩的词源朴素得很——loqu 一家（colloquial 口语的、soliloquy 独白）全是「说」。\",\"adaptation\":\"来自拉丁语 adaptare「使适合」，拆开是 ad-「向」+ aptare「配合」，源头 aptus「合适的」。适应的词源是「对上榫卯」：aptitude（天资）说的是「天生合得来」。\",\"camouflage\":\"来自法语 camoufler「伪装」，一说源头是意大利语 camuffare「蒙骗、伪装」，确切来源学界尚有争议。一战时这个词从法军流行开来，词源细节却恰好也藏着迷彩：看不清。\",\"hibernate\":\"来自拉丁语 hibernare「过冬」，源头 hiems「冬天」。冬眠的词源干脆利落：hibernate 就是动词版的冬天——用睡觉熬过整个冬季。\",\"membrane\":\"来自拉丁语 membrana「蒙在肢体上的皮」，源头 membrum「肢体」。膜的词源是「肢体外面那层皮」：薄薄一层，包着重要的东西。\",\"tissue\":\"来自古法语 tissu「织物」，源头拉丁语 texere「编织」。生物学借用是 19 世纪的事：显微镜下细胞组织像织出来的布。text（文本）与它同根——文本原也是「编织」出来的话语。\",\"stem\":\"古英语 stemn「树干、茎」，日耳曼语老词，与 stand（站立）同族：茎就是植物直立的那根主干。船首的 stem 也是同一词源——船头劈浪的主干。\",\"root\":\"经古诺尔斯语 rót 进入英语的日耳曼语老词，与拉丁语 radix「根」同源（radish 萝卜、radical 根本的都是它）；wort（麦芽）也是远亲。根的词源一路扎进印欧语的最底层。\",\"leaf\":\"古英语 lēaf，日耳曼语老词，与德语 Laub（树叶）同源。页（书页）叫 leaf 是后来的比喻：薄薄的一片，和叶子一个样。\",\"seed\":\"古英语 sǣd，源头是印欧语 *sē-「播撒」，与 sow（播种）、拉丁语 semen（种子，seminar 研讨会原为「播种思想的苗圃」）同源。种子的词源里藏着农耕文明的起点动作：撒种。\",\"pollination\":\"源头 pollen 来自拉丁语 pollen「细粉、面粉」。授粉的词源很家常：花粉在拉丁人眼里就是一把细面，撒到柱头上，就是 pollination。\",\"photosynthesis\":\"希腊语拼词：phōs「光」+ synthesis「合成」（syn-「一起」+ tithenai「放」）。这个词 1893 年才被造出来，可词根全是古希腊的：光合作用就是「用光把东西拼到一起」。\",\"respiration\":\"来自拉丁语 respirare「呼出、喘息」，拆开是 re-「再、反复」+ spirare「呼吸」。spirit（精神）与它同根：古人眼里呼吸就是生命气息，spirit 的本义正是「一口气」。\",\"mineral\":\"来自中世纪拉丁语 minerale，源头 minera「矿、矿山」（晚期拉丁语 mina）。矿物的词源绕不开矿井：mineral 就是「从矿里来的东西」，mine（矿山）是它的同族。\",\"calcium\":\"由拉丁语 calx「石灰」+ 金属后缀 -ium 拼成，1808 年戴维分离出钙时命名。同族的 calculus（微积分）原义是「小石子」——古人拿石子计数，算出了微积分的名字。\",\"spawn\":\"经盎格鲁-法语来自拉丁语 expandere「展开、铺开」（ex- + pandere）。产卵的词源是「铺撒」：鱼把卵大片大片铺在水里，像摊开一张网；expand（展开）是它的直系亲戚。\",\"larva\":\"拉丁语 larva 本义是「鬼魂、面具」，林奈把它借给昆虫学：幼虫是成虫戴的「面具」，真身藏在里面，要蜕几次皮才肯露面。词源里带着一点万圣节气氛。\",\"bee\":\"古英语 bēo，日耳曼语老词，一说为拟声——模仿蜜蜂嗡嗡的振翅声，确切来源未定。今德语 Biene 与它同源。\",\"ant\":\"古英语 æmette（今德语 Ameise 的亲戚），一说源头与「切下」有关——蚂蚁搬运时会把食粮切成小块，确切来源未定。emmet 是 ant 在方言里的旧名。\",\"worm\":\"古英语 wyrm，日耳曼语里它不只是虫：龙和巨蛇也叫 wyrm（贝奥武夫里的龙就是 wyrm）。与拉丁语 vermis（蠕虫，vermicelli 意面细得像虫）同源。蠕虫的词源曾经很威风。\",\"snail\":\"古英语 snægl，日耳曼语，与 snake（蛇）、sneak（潜行）同族：都是贴着地面爬行的主。蜗牛的词源是「爬行者」。\",\"frog\":\"古英语 frogga，日耳曼语老词，或许与「跳跃」有关，确切来源未定。青蛙在词源里留下的最稳线索，就是蹦蹦跳跳的身影。\",\"toad\":\"古英语 tādige，来源不明——词源词典对蟾蜍只能摊手。有些词的历史比文字还老，toad 就是：人类叫了它上千年，却没留下它名字的出生证。\",\"snake\":\"古英语 snaca，源头 *snak-「爬行」，与 snail（蜗牛）、sneak（潜行）是同一族「贴地爬行者」。蛇的词源不靠毒牙靠身段：无声地滑过去。\",\"lizard\":\"经古法语 lesard 来自拉丁语 lacerta「蜥蜴」。法语里词尾被误读，英语又照单全收——蜥蜴的名字在过海关时被改了一点拼法，词源本体还是拉丁的 lacerta（同词也指上臂肌肉，一说因形状像蜥蜴）。\",\"dolphin\":\"来自希腊语 delphis「海豚」，与 delphys「子宫」同根：古希腊人发现海豚胎生，叫它「有子宫的鱼」——哺乳动物的身份，早写在名字里了。\",\"seal\":\"古英语 seolh，日耳曼语老词，专指这种鳍脚动物。注意它与 seal「印章」是同名异源：印章来自拉丁语 sigillum，两词只是拼写撞车。\",\"eagle\":\"经古法语 aigle 来自拉丁语 aquila「鹰」，或许与 aquilus「暗色的」有关（一说因羽毛颜色深）。鹰的词源可能是一句羽毛鉴定：那只深色的大鸟。\",\"owl\":\"古英语 ūle，日耳曼语拟声词——模仿猫头鹰「呜—呜—」的叫声，与 howl（嚎叫）同族。听声起名的词源，最容易记。\",\"hawk\":\"古英语 hafoc，日耳曼语，或与印欧语 *kap-「抓取」同源——鹰隼的看家本领就是俯冲抓取，确切来源未有定论。德语 Habicht 是它的亲戚。\",\"crow\":\"古英语 crāwe，拟声词：乌鸦的叫声「caw」就是它的名字。日耳曼人给鸟起名，耳朵比眼睛先行。\",\"sparrow\":\"古英语 spearwa，日耳曼语老词，更早的来源未定。这种小鸟在英语世界住了一千多年，名字的根却早已埋进史前日耳曼语里。\",\"pigeon\":\"经法语来自拉丁语 pipio「啾啾叫的雏鸟」，是拟声词 pipire「啾啾」的后代。鸽子的词源是雏鸟的叫声：先有啾啾，后有鸽子。\",\"wing\":\"来自古诺尔斯语的 vængir（复数），维京人带来的词，顶替了古英语本族的 feðere（今 feather 系）。英语的「翅膀」是斯堪的纳维亚移民留下的行李。\",\"claw\":\"古英语 clawu，日耳曼语，与「抓挠、撕扯」同族。爪子的词源是动作本身：抓下去，挠开。\",\"beak\":\"经古法语 bec 来自拉丁语 beccus「鸟喙」，源头是高卢语（凯尔特语）——罗马人从高卢人那里学来的词。鸟喙的名字，是凯尔特人留给欧洲的遗产。\",\"horn\":\"古英语 horn，日耳曼语，与拉丁语 cornu「角」同源（cornucopia 丰饶角、unicorn 独角兽的 corn 都是它）。角是印欧语 *ker-「头顶突出物」的后代。\",\"tail\":\"古英语 tægel，日耳曼语，本义包括「一束毛发」。尾巴在词源里是垂在身后的那一束；fairy tale 的 tale 是另一个词（讲），别混。\",\"fur\":\"经古法语 forre「套子、鞘」而来（日耳曼来源）：毛皮最初是衣服内衬的「套子」，穿上动物皮当衬里，fur 的意思才慢慢长到皮毛本身。\",\"shell\":\"古英语 scell，日耳曼语，与 scale「鳞片」同源，本义都是「外面的皮、壳」。贝壳的词源是「覆盖层」：动物随身穿的那层硬外衣。\",\"scale\":\"（鳞片义）经古法语 escale 来自日耳曼语，本义「外皮、硬壳」，与 shell 同源。注意天平义的 scale 来自古诺尔斯语 skál「碗」，是另一个词，别混。\",\"fin\":\"古英语 finn，日耳曼语老词。鳍的词源没有传奇：日耳曼渔民怎么叫，英语就怎么记，已经一千多年。\",\"gill\":\"中古英语 gile，一说来自古诺尔斯语 gjǫlnar「鱼鳃」，与「张口、打哈欠」同族——鳃是鱼用来「张口呼吸」的器官，来源尚有争议。\",\"herd\":\"古英语 heord，日耳曼语，与德语 Herde 同源。兽群的词源自带放牧画面：一群牲口，一个牧人。\",\"flock\":\"古英语 flocc，本义是「一队人、一群人」，来源未定；后来才专指鸟群羊群。人群先借来的词，动物群落接着用。\",\"swarm\":\"古英语 swearm，日耳曼语，或为拟声——一团昆虫飞起时的嗡嗡声，就是它的出生证明，一说未定。蜂群的词源先闻其声。\",\"burrow\":\"是 borough（城镇、自治市镇）的变体，本义「设防的居所、避难所」：动物挖的洞，本质上是它的城堡。兔子窝和城镇，在词源里是同一座要塞。\",\"den\":\"古英语 denn「兽穴、窝」，与 dene「山谷」同族：兽穴多在低洼隐蔽处。词源画面是山谷里的一处凹地，藏着一窝野兽。\",\"cave\":\"经古法语来自拉丁语 cavus「中空的、凹陷的」。洞穴的词源只有一个要点：空。cavity（腔、蛀洞）、concave（凹）都是 cavus 的后代。\",\"prairie\":\"法语 prairie「草甸」，源头拉丁语 pratum「草地」。北美大草原的名字是法国探险者带来的：他们用老家的词，命名了新大陆的草海。\",\"savanna\":\"经西班牙语 zavana 来自泰诺语（加勒比原住民语言）zabana「草原」。热带草原的名字是原住民给的，殖民者的语言只是把它带向了全世界。\",\"tundra\":\"经俄语 тундра 来自萨米语 tūndâr「无树的山地、平原」。苔原一词从北极原住民的语言出发，一路向南传遍地理学——最冷的词，出自最懂寒冷的人。\",\"wetland\":\"wet + land 的现代复合词，20 世纪生态学与环保立法才把它用成术语。湿地的词源没有古代传奇，它是环保时代给「水汪汪的土地」立的正式户口。\",\"swamp\":\"日耳曼语老词，一说与「海绵」同源（德语 Schwamm 是海绵、真菌）：沼泽地踩上去像海绵，吸饱了水。确切来源未定，这条「海绵说」流传最广。\",\"pond\":\"中古英语 ponde，是 pound「围栏、蓄水处」的变体：池塘的词源是「被圈起来的水」——人工蓄水池先叫 pond，自然小水塘跟着沾光。\",\"stream\":\"古英语 strēam，日耳曼语，源头印欧语 *sreu-「流动」，与希腊语 rheuma（流动，rheumatism 风湿）同源。溪流的词源就是「流」这个动作本身。\",\"coral\":\"经拉丁语 corallium 来自希腊语 korallion「珊瑚」，更早来源有争议（或为闪语借词）。珊瑚的名字在地中海贸易里几经转手，出生地已经难以考实。\",\"reef\":\"来自古诺尔斯语 rif「肋骨；暗礁」，与 rib（肋骨）同源：礁石在海面下像一排肋骨横在那里——维京水手用身体给礁石起的名。\",\"algae\":\"拉丁语 alga「海藻」的复数形式（单数少用，复数当了正名）。藻类的词源就是拉丁渔民对海草的统称，没有更深的玄机。\",\"plankton\":\"来自希腊语 planktos「漂流的、 wander 的」，1887 年德国生物学家亨森造词。浮游生物的词源是一句生活方式宣言：不游泳，只漂流。\",\"fungus\":\"拉丁语 fungus「蘑菇、真菌」，一说与希腊语 sphongos「海绵」同源——菌类吸水膨胀的质地像海绵，这条联系流传很广但未完全坐实。\",\"moss\":\"古英语 mos，本义是「沼泽」，后来才兼指沼泽边最常见的居民——苔藓。先有地貌，后有植物：苔藓的名字是它老家的门牌号。\",\"fern\":\"古英语 fearn，日耳曼语，一说与 feather（羽毛）同源：蕨叶裂成羽毛状，名字记的是形状。确切来源未定，羽叶说最深入人心。\",\"pine\":\"经古英语 pīn 来自拉丁语 pinus「松树」。松树的名字是罗马人种下的：帝国走到哪里，pinus 的后代就长到哪里。\",\"oak\":\"古英语 āc，日耳曼语老词，与德语 Eiche 同源。橡树是日耳曼森林的图腾树，名字和它一样经年不朽。\",\"maple\":\"古英语 mapultreow，直译「枫树」（mapul + treow）。英语把话说得明明白白：这棵树就叫 maple，词源就是它本人的名字加个「树」字。\",\"vine\":\"经古法语 vigne 来自拉丁语 vinea「葡萄园、藤」，源头 vinum「酒」。藤蔓的词源绕不开葡萄酒：vineyard 是「种 vine 制 vinum」的地方。\",\"shrub\":\"古英语 scrybb「矮树丛、灌木」，与 scrub（灌木丛；擦洗）同族。灌木在英语里的出身不高：就是荒地边那片杂木丛。\",\"branch\":\"经古法语 branche 来自晚期拉丁语 branca「爪子、兽足」。树枝的词源是「树的爪子」：从主干伸出去抓向空中的那只手——先有动物的足，后有树的枝。\",\"bark\":\"（树皮义）来自古诺尔斯语 bǫrkr「树皮」，维京人带来的词。注意它与 bark「犬吠」是同名异源：狗叫是古英语本土的拟声词。\",\"petal\":\"来自希腊语 petalon「叶子、叶片」，源头 petalos「展开的」。花瓣的词源是「花的那片叶」：古希腊人看花，看见的是一圈展开的叶片。\",\"pollen\":\"拉丁语 pollen「细面粉、细粉末」。花粉的名字来自磨坊：古罗马人看花粉，就像看一把扬起来的细面——pollination（授粉）就是「撒面」。\",\"nectar\":\"希腊语 nektar，众神的饮料；一说拆成 nek-「死」+ -tar「越过」——喝了能越过死亡的神饮，此说流传极广但未完全坐实。花蜜借了神的酒杯：甜到不朽。\",\"bud\":\"中古英语 budde，来源不明——芽的名字找不到出生证。春天年年来，bud 却只留下一句：它就这么叫了六百年。\",\"bloom\":\"来自古诺尔斯语 blóm「花」与古英语 blōma「花朵」，源头印欧语 *bhlē-「开花」，与拉丁语 flos（花，flora 植物群）同源。开花的词源从印欧时代就香。\",\"wither\":\"是 weather（天气）作动词时的变体：wither 就是「被风吹日晒打蔫」。枯萎的词源里站着天气：植物不是自己枯的，是被 weather 收拾的。\",\"decay\":\"经古法语 decair 来自通俗拉丁语 *decadere「倒下、坠落」，拆开是 de-「下」+ cadere「落」。腐朽的词源是「往下掉」：cadere 家族（accident 意外、cadence 节奏）全是各种「落」法。\",\"rotten\":\"来自古诺尔斯语 rotinn「腐烂的」，与 rot 同源。腐烂的词源是维京人带来的：北欧的气候里，东西烂得快，词也记得牢。\",\"barren\":\"来自古法语 baraigne「不育的、荒瘠的」，更早来源不确定（或为凯尔特语）。贫瘠的词源停在中世纪：土地生不出庄稼，女人生不出孩子，法语里是同一句叹息。\",\"drought\":\"古英语 drūgaþ，是 dry（干）的名词亲戚——drought 就是「干」的状态本身。干旱的词源没有水，只有一个干字顶到底。\",\"flood\":\"古英语 flōd，日耳曼语，源头印欧语 *pleu-「流动」，与 float（漂浮）、fly（飞，古义浮动）同源。洪水的词源是「水多得开始流动成灾」。\",\"soil\":\"经盎格鲁-法语来自拉丁语 solum「地面、基底」。土壤的词源站在脚下：solum 就是脚底板踩着的那层地（sole 鞋底同源）。注意 soil「弄脏」是另一词源。\",\"clay\":\"古英语 clǣg，源头印欧语 *glei-「黏住」，与 glue（胶水）、gluten（面筋）同源。黏土的词源就写在手感里：黏，才是它当陶土的资格。\",\"silt\":\"中古英语 silt，或为斯堪的纳维亚来源，与「盐沼、细沙」有关，确切来源未定。淤泥是河口最常见的沉积，它的名字也沉在历史的泥沙里。\",\"gravel\":\"经古法语 gravele（grave「沙滩、砾石」的指小形式）而来，源头高卢语 *grava「沙、砾」。砾石的词源是凯尔特人河滩上的沙子，一层层传进英语。\",\"continent\":\"来自拉丁语 continens (terra)「连成一片的陆地」，拆开是 con-「共同」+ tenere「握住」：大陆的词源是「抱成一团的陆地」，与海洋里的岛屿（被水切断的）正相反。\",\"shore\":\"中古英语 shore，或来自中古荷兰语/低地德语 schore「海岸、水边地」，更早来源未定。海岸的词源停在北海边：陆与水交界的那条线，日耳曼水手最熟。\",\"beach\":\"16 世纪才见于记载的方言词，本义「卵石、卵石滩」，来源不明。海滩的名字很年轻：莎士比亚的时代，它才刚刚从地方话里走上台面。\",\"bay\":\"（海湾义）经古法语 baie 来自晚期拉丁语 baia，更早来源未定（或为伊比利亚半岛的土语）。海湾的名字在地中海西岸失了踪，词源词典只能标一句：来历不明。\",\"sea\":\"古英语 sǣ，日耳曼语老词，与德语 See 同源。海的词源和海一样老：日耳曼人还没分家时，就用这个词指脚下这片水。\",\"lake\":\"古英语 lacu「池塘、水坑」与拉丁语 lacus「湖、水槽」汇合的结果（希腊语 lakkos「水池」是远亲）。湖的词源是「一洼水」：从池塘到大湖，共用一个户口。\",\"river\":\"经古法语 riviere 来自拉丁语 ripa「河岸」：riviere 本义是「河岸地带」，后来整条河都归它管。河流的词源是岸——古人先站在岸上，才给河起的名；riparian（河岸的）仍守着本义。\",\"polar\":\"来自拉丁语 polaris，源头希腊语 polos「轴、枢轴」：地轴的两端就是两极。极地的词源站在地球的转轴上——polos 还是天球转动的那根轴心。\",\"latitude\":\"来自拉丁语 latitudo「宽度」，源头 latus「宽的」。纬度的词源是「宽」：地球仪上横着量的那把尺；attitude 里的 lat 没关系，那是另一回事。\",\"longitude\":\"来自拉丁语 longitudo「长度」，源头 longus「长」。经度的词源与纬度成对：一横量宽（latitude），一纵量长（longitude），都是拉丁人量地球的原话。\",\"altitude\":\"来自拉丁语 altitudo「高、深」，源头 altus「高的」。海拔的词源就是 altus 本人：altus 既可指高也可指深（海），量的是离海平面的那段距离。\",\"elevation\":\"来自拉丁语 elevare「举起、抬高」，拆开是 e-「出」+ levare「举起」，源头 levis「轻」。高程的词源是「把东西举起来」：举得越费劲，海拔越高；elevator（电梯）干的是同一件事。\",\"peak\":\"是 pike「尖顶、长矛」的拼写变体，先指山尖，再泛指最高点。山峰的词源是一杆矛：尖，才够格叫 peak。\",\"cliff\":\"古英语 clif，日耳曼语老词，与德语 Klippe 同源。悬崖的词源没有修饰：北海边的峭壁怎么叫，它就怎么记。\",\"eruption\":\"来自拉丁语 eruptio「爆出」，拆开是 e-「出」+ rumpere「冲破」。喷发的词源是「破壳而出」：与 rupture（破裂）同族，火山和血管破的都是同一种「破」。\",\"seismic\":\"来自希腊语 seismos「地震」，源头 seiein「摇晃」。地震的词源是动词「摇」：seismograph（地震仪）就是「把摇晃写下来」的机器。\",\"fault\":\"经古法语 faute「缺陷、过失」来自拉丁语 fallere「欺骗、失手」。断层的词源是「地层失手错位」：与 false（假的）同族——地壳在这里「犯了个错」。\",\"crust\":\"来自拉丁语 crusta「外壳、硬皮」。地壳的词源和面包皮是同一个词：一层硬壳包着软心，地球和面包共用一张户口。\",\"mantle\":\"来自拉丁语 mantellum「斗篷、披风」（地幔义经德语 Mantel 转入地质学）。地幔的词源是件衣服：地核外面裹着的那层「斗篷」——地质学家给地球穿衣服时，顺手借了裁缝的词。\",\"weathering\":\"由 weather（天气，古英语 weder）加 -ing 构成：风化的词源透明得很——岩石是被 weather 一天天磨掉的。中文叫「风化」，英语叫「天气化」，两个词想到了一块儿。\",\"limestone\":\"lime + stone 的复合词：lime（石灰）来自古英语 līm「黏性物质、石灰」，本义「黏糊糊的东西」。石灰岩的词源站在窑边：烧出来能当黏合剂的那种石头。\",\"sandstone\":\"sand + stone 的复合词，古英语 sand 与 stān 的直系后代。砂岩的词源就是成分表：沙粒压成的石头，名字不玩一点虚的。\",\"star\":\"古英语 steorra，日耳曼语，源头印欧语 *ster-「星」，与拉丁语 stella、希腊语 astēr（asteroid 小行星的词根）同源。恒星的名字，从印欧时代就挂在天上。\",\"asteroid\":\"来自希腊语 asteroeidēs「星形的」，拆开是 astēr「星」+ eidos「形状」。小行星的词源是望远镜里的第一印象：看着像星星的小点——其实是个石块。\",\"meteor\":\"来自希腊语 meteōros「高悬空中的」，源头 aeirein「举起」：古希腊把天上的一切异象（流星、彩虹、风）统称 meteōra「空中之物」。流星的词源站在气象学隔壁：meteorology（气象学）至今守着这个大家庭。\",\"wave\":\"来自古英语 wafian「摇摆、飘动」一族（与 waver 同源）。波浪的词源是「晃」：水面晃起来，就成了 wave；旗帜晃起来，也是同一个词。\",\"precipitation\":\"来自拉丁语 praecipitare「头朝下扔」，拆开是 prae-「在前」+ caput「头」。降水的词源很生猛：雨雪是天空「头朝下摔下来」的水；化学里的沉淀义也是这同一个「摔」。\",\"rainfall\":\"rain + fall 的复合词：rain 来自古英语 regn，日耳曼语老词。降雨量的词源是小学生造句：雨，落下来，量一量——学术名词也可以这么朴素。\",\"snowfall\":\"snow + fall 的复合词：snow 来自古英语 snāw，源头印欧语 *sneigwh-「雪」（拉丁语 nix、希腊语 nipha 是亲戚）。降雪量的词源和 rainfall 一样直白：雪落下来，量一量。\",\"breeze\":\"经西班牙语 briza / 葡萄牙语 brisa「东北风」而来，更早来源未定。这个词进英语前一度指牛虻（brize），后来被海风顶了班：微风的词源带着伊比利亚半岛的海味。\",\"avalanche\":\"来自法语 avalanche，源头是萨瓦方言的 avalantse，与 avaler「下降」（拉丁语 ad vallem「往山谷去」）同族。雪崩的词源就是它的轨迹：从山上往谷底去。\",\"landslide\":\"land + slide 的复合词：slide 来自古英语 slīdan「滑动」。山体滑坡的词源是成分表式的诚实：一片土地，滑下去了。\",\"zenith\":\"经中世纪拉丁语来自阿拉伯语 samt (ar-ra's)「头顶之路」；抄写时 samt 的 m 被误读成 ni，成了 cenith/zenith——天顶的名字是一次著名的抄写事故，错得将错就错了八百年。\",\"meridian\":\"来自拉丁语 meridianus「正午的」，拆开是 medius「中间」+ dies「日」。子午线的词源是正午：太阳在头顶正中时划过的那条线；meridian 曾用名 meridies 就是「中午」。\",\"tropic\":\"来自希腊语 tropikos「（太阳）转弯的」，源头 tropē「转弯」。热带（回归线）的词源是太阳的折返点：走到这里，太阳就掉头——trope（转义）是同族，意思也「转弯」。\",\"temperate\":\"来自拉丁语 temperare「调和、使适度」。温带的词源是「调和得刚刚好」：不冷不热，是 temper（脾气、调和）的同族——气候的脾气，被调顺了。\",\"arctic\":\"来自希腊语 arktikos「熊的、北方的」，源头 arktos「熊」：北极头顶悬着大熊座（Ursa Major）。北极的词源是星座：熊在的地方，就是北方。\",\"antarctic\":\"来自希腊语 antarktikos「与熊相对的」：anti-「相对」+ arktikos「北极的」。南极的词源是北极的镜像：大熊座对面的那片天底下，就是 antarctic。\",\"aurora\":\"拉丁语 aurora「黎明」，也是罗马黎明女神的名字，源头印欧语 *aus-「晨光」（east 东方、Easter 复活节是远亲）。极光的词源是黎明：夜里升起的假黎明，难怪叫它「黎明的光」。\",\"galaxy\":\"来自希腊语 galaxias (kyklos)「乳白色的环」，源头 gala「乳汁」：银河在古希腊人眼里是天上洒出的一道奶。星系的词源带着神话：赫拉的乳汁溅成了银河（Milky Way 是它的直译）。\",\"nebula\":\"拉丁语 nebula「薄雾、云气」，与德语 Nebel（雾）、希腊语 nephos（云）同源。星云的词源是一团雾：望远镜里看不清的，都先叫 nebula。\",\"satellite\":\"来自拉丁语 satelles「随从、卫兵」：开普勒用它称木星的月亮——行星身边的「带刀侍卫」。卫星的词源画面很宫廷：主子走一步，侍卫跟一步。\",\"probe\":\"来自拉丁语 probare「检验、证明」，原是外科医生的探针（检查伤口深浅的细棒），后来宇航器也用它。探测器的词源出身医学：先探伤口，再探太空。\",\"crustal\":\"crust（拉丁语 crusta「硬皮」）+ 形容词后缀 -al。地壳的（crustal）是 crust 的派生词：词源在 crust 那里——地球的那层硬皮。\",\"tectonic\":\"来自希腊语 tektonikos「与建造有关的」，源头 tektōn「木匠、建造者」。板块构造的词源出自工地：地球在搞「建造」；architect（建筑师）拆开就是「首席木匠」archi- + tektōn。\",\"drift\":\"来自 drive（古英语 drīfan「驱动、赶」）的名词形式：drift 是「被推着走」的那段位移。大陆漂移的词源站在牛顿之前：不是大陆自己想走，是被推着走。\",\"nucleus\":\"拉丁语 nucleus「小坚果仁」，是 nux「坚果」的指小形式。原子核、细胞核的词源都是一颗果仁：硬壳里面最要紧的那一小粒。\",\"proton\":\"来自希腊语 prōton「第一的」（prōtos 的中性形式），1920 年卢瑟福命名：氢原子核是排第一的基本粒子。质子的词源是名次表：第一名。\",\"neutron\":\"由拉丁语 neuter「两者都不（不带电）」+ 粒子后缀 -on 拼成：中子的词源是它的电荷立场——正负都不站，中间派。\",\"ion\":\"来自希腊语 ion「正在走的」（ienai「走」的现在分词），法拉第时代经惠威尔定名：离子是在电场里「走向电极」的粒子。词源就是它的行军路线。\",\"isotope\":\"希腊语拼词：isos「相同」+ topos「位置」，1913 年经索迪采用（玛格丽特·托德建议）：同位素是元素周期表上「占同一个位置」的兄弟。词源就是座位表：同桌，不同体重。\",\"mixture\":\"来自拉丁语 mixtura，源头 miscere「混合」。混合物的词源是动作本身：mix 一家（mix、miscellaneous 混杂的）全靠这一个「拌」字。\",\"solution\":\"来自拉丁语 solutio「松开、溶解」，源头 solvere「松开」。溶液的词源是「松绑」：固体被液体松开、散开，就是 solution；它「解决办法」的义项也是这同一条线：把难题松开。\",\"solvent\":\"来自拉丁语 solvens「正在松开的」（solvere 的分词）。溶剂的词源是溶质的对手戏：一个负责松绑（solvent），一个被松开（solute）。\",\"solute\":\"来自拉丁语 solutus「被松开的」（solvere 的过去分词）。溶质的词源简单：它是 solution 里被溶剂松开、散布开的那部分。\",\"base\":\"（碱义）base 本词经古法语来自希腊语 basis「基底、台阶」；化学义是 18 世纪化学家鲁埃勒定的：碱是能与酸化合的「基底物质」。碱的词源站在酸对面：一个提供底座，酸在上面反应。\",\"alkaline\":\"源头 alkali 来自阿拉伯语 al-qalī「煅烧过的灰烬（盐生植物的灰）」，al- 是阿拉伯语定冠词。碱性的词源在沙漠植物的灰里：古人烧海蓬子取灰制碱，al- 这个冠词一路跟到了英语。\",\"oxide\":\"法语 oxyde 的回译：oxy- 来自希腊语 oxys「尖锐的、酸的」+ 后缀 -ide，拉瓦锡时代的造词。氧化物的词源带着旧理论：当时以为氧是「成酸者」，名字就这么定下了。\",\"sulfate\":\"由 sulfur（硫，拉丁语 sulfur）+ 盐类后缀 -ate 拼成。硫酸盐的词源是配方表：含硫的这一类盐，名字按成分站队。\",\"nitrate\":\"由 nitre（硝石）+ -ate 组成；nitre 经希腊语 nitron 上溯至埃及语 ntry（天然碱、泡碱）。硝酸盐的词源从尼罗河畔的天然碱矿出发，绕了三千年才进实验室。\",\"chloride\":\"由 chlorine + -ide 组成；chlorine 来自希腊语 chlōros「黄绿色的」——氯气就是那个颜色。氯化物的词源先过眼睛：先有黄绿色的气，后有它的盐。\",\"sodium\":\"由 soda（碳酸钠）+ 金属后缀 -ium 拼成，1807 年戴维命名；soda 一词来自意大利语，或与阿拉伯语盐生植物有关，来源尚有争议。钠的词源停在 soda 身上：它是「从苏打里电解出来的金属」。\",\"potassium\":\"由 potash（钾碱）+ -ium 拼成，1807 年戴维命名；potash 是 pot（锅）+ ash（灰）的直白复合词——把植物灰泡在锅里熬出的碱。钾的词源在厨房的锅灰里。\",\"zinc\":\"来自德语 Zink，来源未定，一说与 Zinke「尖齿、尖角」有关（锌结晶呈齿状），一说为帕拉塞尔苏斯的造词。锌的名字在德语里就没交代清楚来历，词源词典多标「不确定」。\",\"lead\":\"古英语 lēad，西日耳曼语老词，与荷兰语 lood 同源。铅的词源很沉很旧：从日耳曼人冶炼时代起，它就叫这个名字，更早的来源已不可考。\",\"tin\":\"古英语 tin，日耳曼语老词。锡是青铜时代的主角金属之一（青铜就是铜锡合金），名字和它的历史一样古老，更早来源未定。\",\"silver\":\"古英语 seolfor，日耳曼语，与立陶宛语 sidãbras、俄语 serebro 是亲戚，更早来源未定（或为前印欧语借词）。银的名字横跨北欧到东欧，却找不到唯一的出生地。\",\"neon\":\"来自希腊语 neon「新的」（neos 的中性形式），1898 年拉姆齐发现这种惰性气体时命名：周期表上的「新来的」。氖的词源就一个字：新。\",\"silicon\":\"由拉丁语 silex「燧石、硬石」+ 元素后缀 -on（仿 carbon、boron 的构词）拼成。硅的词源是燧石：这种元素藏身于最常见的硬石头里，名字就地取材。\",\"sulfur\":\"拉丁语 sulfur（亦作 sulpur），更早来源未定。硫的词源停在拉丁：炼金术士的「燃烧石」在圣经里译作 brimstone，sulfur 本人的出生证却已遗失。\",\"phosphorus\":\"来自希腊语 phōsphoros「带光者」，拆开是 phōs「光」+ pherein「携带」：晨星（金星）古称 Phosphoros。1669 年布兰德炼出白磷，暗夜发光，晨星的名字就此转行做元素。\",\"iodine\":\"来自希腊语 iōdēs「紫罗兰色的」，拆开是 ion「紫罗兰」+ eidos「形状」，1813 年盖-吕萨克命名：碘一加热就升起紫色蒸气。碘的词源先过眼睛——紫色就是它的身份证。\",\"bromine\":\"来自希腊语 brōmos「恶臭」，1826 年定名。溴的词源先过鼻子：这种红棕色液体臭得理直气壮，名字干脆就叫「臭」。\",\"reaction\":\"由 re-「回」+ action「作用」组成（action 源头拉丁语 agere「做、驱动」）。化学反应的词源是牛顿第三定律的口气：有作用，就有反作用——物质碰面，互相「回手」。\",\"catalyst\":\"源头是希腊语 katalysis「瓦解、松解」，拆开是 kata-「向下」+ lyein「松开」；1835 年贝采利乌斯据此造出 catalysis（催化）。催化剂的词源有点反直觉：它干的是「松开」旧键的活，新键才得以成形。\",\"oxidation\":\"由 oxide + -ation 构成；oxide 的 oxy- 来自希腊语 oxys「酸的、尖锐的」——拉瓦锡以为氧是一切酸的来源，「氧化」的名字就是这场美丽误会留下的纪念。\",\"reduction\":\"（化学义）来自拉丁语 reducere「带回、领回」：冶炼时把金属从矿石里「领回来」，就是还原。化学的 reduction 和数学的「约简」同源：都是把东西带回更基本的状态。\",\"combustion\":\"来自拉丁语 comburere「烧尽」，拆开是 com-「完全」+ urere「燃烧」。燃烧的词源自带强度：不是点着，是彻底烧光；caustic（腐蚀性的）的 -caust 与希腊语「烧」是另一条线，别混。\",\"evaporation\":\"来自拉丁语 evaporare「化作蒸气散去」，拆开是 e-「出」+ vapor「蒸气」。蒸发的词源画面很清楚：水变成 vapor，从液面出走；vapor 本人也是这条词源链上的正主。\",\"condensation\":\"来自拉丁语 condensare「使变密」，拆开是 con-「共同」+ densus「稠密的」。凝结的词源与蒸发正相反：散开的分子重新挤到一起——dense（稠密）就是它的同根兄弟。\",\"fission\":\"来自拉丁语 fissio「劈开」，源头 findere「劈、裂」。核裂变的词源是生物学借来的：细胞分裂叫 fission，原子核的大分裂 1939 年沿用了这个名字——劈开，就是它的全部剧情。\",\"radioactive\":\"radio-（源头拉丁语 radius「射线」）+ active 的拼词，1898 年由玛丽·居里造出（法语 radioactivité）。放射性的词源站在实验室里：一种主动往外放「线」的性质，名字是居里夫妇给的。\",\"wavelength\":\"wave + length 的复合词。波长的词源是量波的尺子：一个波峰到下一个波峰，量出来就是它——物理名词也可以朴实到像句说明书。\",\"amplitude\":\"来自拉丁语 amplitudo「宽广、宏大」，源头 amplus「宽大的」。振幅的词源是「宽」：摆动张开的宽度有多大，amplitude 就有多大；ample（充裕的）是它的同族。\",\"refraction\":\"来自拉丁语 refringere「折回、打断」，拆开是 re-「回」+ frangere「打破」。折射的词源是「光被折了一下」：光线过界时像被打断再接上；fraction（分数，打破整体）是同族。\",\"diffraction\":\"来自拉丁语 diffringere「打碎、使分散」，拆开是 dis-「散开」+ frangere「打破」。衍射的词源是「光被打散」：波遇到边缘，碎成一片扇形散开——与 refraction 的「折」只差一个方向。\",\"lens\":\"拉丁语 lens「小扁豆」：透镜的形状就是一颗扁豆——双凸、圆鼓鼓。古罗马人用日常食材给光学元件命了名，两千年没改。\",\"prism\":\"来自希腊语 prisma「锯下来的东西」，源头 prizein「锯」：几何学里棱柱是「锯下的一段」，光学借它分光。棱镜的词源在木匠铺：一块被锯整齐的块儿。\",\"laser\":\"是首字母缩略词：Light Amplification by Stimulated Emission of Radiation（受激辐射光放大），1960 年随实物一起诞生。激光的词源是一张说明书的首字母——它没有词根，只有一串大写字母。\",\"circuit\":\"来自拉丁语 circuitus「绕行一周」，拆开是 circum-「环绕」+ ire「走」。电路的词源是「走一圈」：电流从电源出发，必须走回原点才算 circuit；没闭合的环，古罗马人也不认。\",\"voltage\":\"由 volt + -age 组成，1880 年代定名；volt 纪念意大利物理学家伏打（Alessandro Volta），伏打电堆的发明人。电压的词源是一位科学家的姓氏，带上了单位的户口本。\",\"resistance\":\"来自拉丁语 resistere「顶住、抵抗」，拆开是 re-「回、反」+ sistere「站立」。电阻的词源是「站住不让过」：与 insist（站定主张）、exist（站出来）同出 sist「站」一家。\",\"conductor\":\"来自拉丁语 conducere「汇集、引导」，拆开是 con-「共同」+ ducere「引导」；电学义是 18 世纪借用的。导体的词源是「引路者」：它把电流领着走——乐队指挥 conductor 是同一个词，同一种「带队」。\",\"insulator\":\"由 insulate 派生；insulate 源头是拉丁语 insula「岛」：使成孤岛，就是绝缘、隔热。绝缘体的词源是地理：把电流关在岛外，谁也别想上岸。\",\"semiconductor\":\"semi-「半」（拉丁语 semi-）+ conductor 的 20 世纪拼词。半导体的词源直白：导电只导一半——性质介于导体与绝缘体之间，名字把立场写在了脸上。\",\"battery\":\"经古法语 batterie「击打、炮组」来自 battre「打」（拉丁语 battuere）。电学义是 1748 年富兰克林借的比喻：一组莱顿瓶并联，像一排大炮成「组」。电池的词源在炮兵阵地：成组，才有火力。\",\"generator\":\"来自拉丁语 generare「生产、繁衍」，源头 genus「种类、出生」。发电机的词源是「生」：generate 一家（generation 世代、generate 生成）都在生东西，发电机生的是电。\",\"motor\":\"拉丁语 motor「推动者」，源头 movere「移动」。电动机的词源是它的工种：专门负责「动」的那台机器；motion、mobile 都是 movere 的后代。\",\"turbine\":\"经法语 turbine 来自拉丁语 turbo「旋风、陀螺」，1820 年代由法国工程师比尔丹造词。涡轮机的词源是「转」：turbo 一转，水力、蒸汽都得跟着干活。\",\"lever\":\"经古法语 levier 来自拉丁语 levare「举起」，源头 levis「轻」。杠杆的词源是「把重物变轻的工具」：阿基米德要的那根撬棍，名字里就写着用途。\",\"pulley\":\"经古法语 polie 而来，来源未定，一说与希腊语 polos「枢轴、转轴」有关。滑轮的名字可能是「轴」的后代，但这一步学界没有坐实——轮子先转起来了，词源还在路上。\",\"gear\":\"来自古诺尔斯语 gervi「装备、器具」：gear 起初泛指一切装备（行军装备、马具），机械义后来者居上。齿轮的词源是「家伙什儿」：一台机器的全部装备，慢慢缩小成咬合的那圈齿。\",\"piston\":\"经法语 piston 来自意大利语 pistone，源头 pistare「捣、压」（拉丁语 pinsere「捣碎」）。活塞的词源是厨房的捣杵：一下一下捣下去——pestle（杵）是它的同族。\",\"spring\":\"（弹簧义）来自古英语 springan「跳、跃起」的日耳曼语老词。弹簧的词源就是它的脾气：压下去，还要跳回来；季节义的 spring 也是同源——万物「跃」出地面的时节。\",\"pendulum\":\"来自拉丁语 pendulus「悬挂着的」，源头 pendere「悬挂」。摆的词源是状态本身：挂着，来回晃；pendant（垂饰）、pending（悬而未决）都是 pendere 一家。\",\"acceleration\":\"来自拉丁语 accelerare「催快」，拆开是 ad-「向」+ celer「快的」。加速度的词源是「往快里催」：celer 至今还活在 celerity（敏捷，书面词）里 低调地快着。\",\"deceleration\":\"de-「减」+ acceleration 的拼词，20 世纪随汽车与航空工程流行。减速的词源是加速度的镜像：把 celer「快」往下调一档。\",\"centrifugal\":\"由拉丁语 centrum「中心」+ fugere「逃跑」拼成，牛顿时代的造词（惠更斯先用的词形）。离心的词源是逃逸现场：质点一心想从中心「逃」出去——fugitive（逃亡者）是它的同族。\",\"elastic\":\"源头是希腊语 elaunein「驱动、锻打」派生的 elatos「可锻打的」：金属被锤打后能回弹——elastic 最早形容的是这种「打不坏」的脾气，后来才轮到橡皮筋。\",\"rigid\":\"来自拉丁语 rigidus「僵硬的」，源头 rigere「僵直」。刚性的词源是身体感受：rigere 形容冻僵、吓呆的僵——rigid 的东西不会弯，只会断。\",\"malleable\":\"经古法语来自拉丁语 malleus「锤子」：malleable 是「经得起锤子打的」。可锻的词源在铁匠铺：锤子说了算，能锤成薄片的才配这个名；mallet（木槌）是同族。\",\"brittle\":\"来自古英语 breotan「打碎、断裂」+ 形容词后缀，与 break 同族。易碎的词源是结果预告：brittle 的东西还没碰，名字里已经在「碎」了。\",\"buoyancy\":\"由 buoyant 派生；buoyant 经西班牙语 boyante 来自 boya「浮标」，浮标一词的更早来源（或经法语、源于日耳曼语）尚有争议。浮力的词源挂在海面上：先有那颗漂着的浮标，后有整套阿基米德原理的名字。\",\"vector\":\"拉丁语 vector「搬运者、携带者」，源头 vehere「运载」。矢量的词源是它的工作方式：带着大小，朝一个方向「运」过去——vehicle（车辆）是同族，运的是人，vector 运的是量。\",\"scalar\":\"来自拉丁语 scalaris「梯子的」，源头 scala「梯子、阶梯」。标量的词源是爬台阶：只有大小、按刻度一级一级增减——scale（刻度、音阶）正是它的同族。\",\"quantum\":\"拉丁语 quantum「多少」（quantus「多大的」的中性形式），普朗克 1900 年后随量子论流行。量子的词源是一句拉丁问句：能量不是连绵的河，而是「一份有多少」的包裹。\",\"thermometer\":\"希腊语拼词：thermē「热」+ metron「尺度、测量」，17 世纪初造出。温度计的词源是成分表：量热的尺子——thermos（热水瓶）至今还借着 therm 的热气。\",\"calorie\":\"经法语 calorie 来自拉丁语 calor「热」+ 单位后缀，19 世纪定名。卡路里的词源就是「热」：一卡是一份能把水烧热的量，calor 还藏在 cauldron（大锅）的亲戚里。\",\"kilogram\":\"法语 kilogramme：kilo- 来自希腊语 chilioi「一千」+ gramme（见 gram 的希腊语 gramma「小重量」）。千克的词源是算术：一千个 gram——革命年代法国人造单位，连词根都要十进制。\",\"meter\":\"经法语 mètre 来自希腊语 metron「测量、尺度」，1790 年代法国大革命时定为基本单位（取地球子午线长度的千万分之一）。米的词源是「量」本身：measure、metric 都是 metron 的后代。\",\"liter\":\"经法语 litre 来自中世纪拉丁语 litra，源头希腊语 litra「一磅（量）」。升的词源是古希腊的秤：先是重量单位，漂洋过海成了容量单位。\",\"watt\":\"纪念苏格兰工程师詹姆斯·瓦特（James Watt），1882 年被定为功率单位。瓦特的词源是一个人的姓氏：改良蒸汽机的那位，名字永远留在了电灯泡的包装上。\",\"joule\":\"纪念英国物理学家詹姆斯·普雷斯科特·焦耳（James Prescott Joule），1882 年前后定为能量单位。焦耳的词源是一个人的姓氏：测出热功当量的那位，把名字留给了每一份能量。\",\"newton\":\"纪念艾萨克·牛顿（Isaac Newton），20 世纪（1946 年正式定名）成为力的单位。牛顿的词源是一个人的姓氏：定义了 F=ma 的人，单位就用他的名字称 F。\",\"hertz\":\"纪念德国物理学家海因里希·赫兹（Heinrich Hertz），1930 年定为频率单位。赫兹的词源是一个人的姓氏：证明电磁波存在的那位，名字从此按秒计数。\",\"ampere\":\"纪念法国物理学家安德烈-马里·安培（André-Marie Ampère），1881 年定为电流单位。安培的词源是一个人的姓氏：电动力学的奠基人，把名字留给了每一股电流。\",\"volt\":\"纪念意大利物理学家亚历山德罗·伏打（Alessandro Volta），1880 年代定为电压单位。伏特的词源是一个人的姓氏：发明伏打电堆的那位，名字压在每一个电池上。\",\"ohm\":\"纪念德国物理学家格奥尔格·欧姆（Georg Ohm），1860 年代定为电阻单位。欧姆的词源是一个人的姓氏：写出 V=IR 的那位，从此站在每条电路里「抵抗」电流。\",\"alloy\":\"经古法语 alier「结合」来自拉丁语 alligare「绑到一起」，拆开是 ad-「向」+ ligare「捆绑」。合金的词源是冶金现场的操作：把几种金属「绑」成一体——ligament（韧带，绑骨头的）是同族。\",\"steel\":\"古英语 stȳle（亦作 stēle），日耳曼语老词。钢的词源和钢的地位一样老：日耳曼铁匠的看家材料，名字在冶炼炉边叫了上千年，更早来源未定。\",\"brass\":\"古英语 bræs，来源不明——黄铜在青铜时代晚期就是大宗商品，名字却没留下出生证。词源词典对 brass 只能标：古英语已有，更早不可考。\",\"ceramic\":\"来自希腊语 keramikos「陶器的」，源头 keramos「陶土、陶器」。陶瓷的词源在窑口：keramos 还指屋瓦——古希腊的屋顶和饭碗，是同一种烧出来的东西。\",\"polymer\":\"希腊语拼词：polys「多」+ meros「部分」，1830 年代贝采利乌斯造词。聚合物的词源是结构本身：许多小部件连成一条长链——monomer（单体）是它的单数搭档。\",\"fiber\":\"来自拉丁语 fibra「丝、纤维」。纤维的词源是拉丁人手里的线头：fibra 既指植物的丝，也指动物的筋——能抽成丝的，都归它管。\",\"synthetic\":\"来自希腊语 synthetos「拼合而成的」，拆开是 syn-「一起」+ tithenai「放置」。合成的词源与 hypothesis（垫在下面）同出 tithenai 一族：一个往上拼，一个往下垫，都是「放」。\",\"organic\":\"来自希腊语 organikos「与器官（工具）有关的」，源头 organon「工具、器官」。有机的词源是「有器官的」：化学借它指含碳化合物前，它先在生物学里指「长着器官的活物」。\",\"inorganic\":\"in-「不」+ organic 的 19 世纪化学拼词。无机的词源是排除法：不是「有器官的活物」那一派的化合物，统统请到这一桌——名字是 organic 的反面教材。\",\"treatment\":\"由 treat + -ment 组成；treat 经古法语来自拉丁语 tractare「处理、拖拽」，源头 trahere「拉」。治疗的词源是「经手处理」：医生「处理」病情，如同拉扯一件棘手的活计；tractor（拖拉机）是同族，拉的是地。\",\"remedy\":\"来自拉丁语 remedium「解药、补救」，拆开是 re-「回」+ mederi「医治」。药物的词源是医学最核心的动作：mederi 一家（medicine 医学、medical 医疗的）都在「治」，remedy 干的是把健康「治回来」。\",\"antibody\":\"由 anti-「对抗」+ body 组成，是德语 Antikörper 的直译，1890 年代免疫学草创时造词。抗体的词源是翻译件：身体里负责「对抗」入侵者的那一类物质，名字和概念一起从德国实验室进口。\",\"antigen\":\"anti- + 希腊语 -genēs「产生…的」（gen「出生」一族）拼成，1899 年定名。抗原的词源是它的职能：能「生出抗体」的物质——名字里一半是它自己，一半是它的对手。\",\"infection\":\"来自拉丁语 inficere「浸入、玷污」，拆开是 in-「入」+ facere「做」；inficere 本指染色、浸透。感染的词源是「脏东西渗了进来」：古人看不见细菌，先看见的是「玷污」。\",\"inflammation\":\"来自拉丁语 inflammare「点燃、使燃烧」，拆开是 in-「入」+ flamma「火焰」。炎症的词源自带体温：红肿热痛，就是身体局部「着了火」——flame 是它的同根兄弟。\",\"fever\":\"经古英语 fefer 来自拉丁语 febris「发烧」。发烧的词源是拉丁病历本上的老字：febris 还活在 February（二月，罗马的净化祭热病季一说有关）里，只是那条线学界有争议，稳妥记 febris 本人。\",\"chill\":\"古英语 cele「寒冷」，日耳曼语，源头印欧语 *gel-「冷」，与拉丁语 gelu「霜」同源（gelato 冰淇淋、congeal 凝结是远亲）。寒战的词源是「冷」本身：冷风先行，发烧随后。\",\"cough\":\"古英语 cohhetan，日耳曼语拟声词——咳出声来就是它的词源。咳嗽的名字和咳嗽的动作一样直接，模仿喉咙里那一声「koh」。\",\"sneeze\":\"源头是古英语 fnēosan「打喷嚏」，中古英语里词首的 f 被误读成 s（fn- 也被误拆），sneeze 就此将错就错。喷嚏的词源是英语拼写史最著名的误读事故之一：一个字母看错，全民改口。\",\"headache\":\"head + ache 的复合词：ache 来自古英语 æce（源头动词 acan「疼痛」）。头痛的词源是小学生造句：头，痛——日耳曼语把病历写成了直白的话。\",\"nausea\":\"来自希腊语 nausia「晕船」，源头 naus「船」。恶心的词源在船上：先是晕船想吐，后来陆地上的一切反胃都归它管；nautical（航海的）、astronaut（宇航员，「星船水手」）里的 nau-/naut 都是这条船。\",\"dizzy\":\"古英语 dysig 本义是「愚蠢的、迟钝的」，后来才转「头晕」。头晕的词源拐了个弯：古人看头晕的人脚步踉跄、先当他是「犯傻」——词义从脑子转到步子，只用了一步。\",\"fatigue\":\"经法语来自拉丁语 fatigare「使疲惫、催逼」。疲劳的词源带着催促感：fatigare 是把人（或牲口）赶到没劲为止——现代英语的 fatigue 还兼任「军装、杂役」，累的都是同一回事。\",\"bloodstream\":\"blood + stream 的复合词：blood 是古英语 blōd，stream 是古英语 strēam「流动」。血流的词源是解剖图上的标注：血液的那条「河」——造词的人把循环系统看成了水利系统。\",\"vein\":\"经古法语 veine 来自拉丁语 vena「血管、脉络」。静脉的词源里 vena 还兼指矿脉、水脉：拉丁人看血管和矿脉是同一种「地下的通道」——地质学的 vein（矿脉）至今同名。\",\"capillary\":\"来自拉丁语 capillus「头发」+ 形容词后缀 -ary：毛细血管细得像头发丝，名字就是它的直径说明书。注意别被 cap- 误导：它与「抓」（capt）无关，是「发」不是「爪」。\",\"identical\":\"来自中世纪拉丁语 identicus，核心是拉丁语 idem「同一个」。拆开看：idem（同一）+ -ical（形容词后缀）——两个事物像从一个模子里出来的，就是 identical；identity（身份）也是这个词根：让一个人成其为「同一个自己」的东西。\",\"incline\":\"来自拉丁语 inclinare：in-（向内、朝向）+ clinare「倾斜、倚靠」，与希腊语 klinein「斜靠」同源。clinic（诊所）原指病人斜靠的床，recline 是往后斜靠——incline 的「斜」，全家共用。\",\"inconsistent\":\"in-（不）+ consistent（一致的）：consistent 来自拉丁语 consistere「站在一起」（con- 一起 + sistere 站立）。几条说法站不到一块儿、互相打架，就是 inconsistent；consist（由……构成）是同一个「站」。\",\"induce\":\"来自拉丁语 inducere：in-（向内）+ ducere「引导、带领」。把人「领着走」到某个决定，就是引诱、促使；物理学的「感应」也是被领出来的电流。duct（管道）同根，都是「引导」。\",\"infect\":\"来自拉丁语 inficere：in-（进入）+ facere（做、制），本义是「把东西浸进去、染上」——古罗马人用它说给布料染色。病菌像染料一样浸进身体，就成了传染；infect 与 dye（染料）的意象在源头相通。\",\"infer\":\"来自拉丁语 inferre：in-（带入）+ ferre「携带、带来」。推理就是把已有信息「带进」结论里；注意别和 imply 混：说话人 imply（暗示），听话人 infer（推断），一个送出、一个带回。\",\"injure\":\"来自拉丁语 iniuria「不法、冤屈」：in-（不）+ ius「法律、权利」。受伤的源头是「权利被侵害」这个法律概念，后来才专指身体受伤；jury（陪审团）、justice（正义）里的 ius/jur 都是这条「法」的血脉。\",\"innovate\":\"来自拉丁语 innovare：in-（进入）+ novus「新的」。把「新」引进旧事物里就是改革；novel（新奇的；小说）、novice（新手）、renovate（翻新）全是 novus 一家，新得程度不同而已。\",\"platelet\":\"plate（薄片）+ -let（表小的后缀）的复合词。plate 经古法语源于拉丁语 platta「扁平的片」；血小板是血液里扁平的微小圆片，名字就是按形状起的——显微镜下它们像一摞小碟子。\",\"liver\":\"英语固有词，古英语 lifer，日耳曼语同族词见于德语 Leber。更远的来源无定论：一种说法把它和 life（生命）联系起来，因为古人曾视肝为生命与情感的居所；另一说与「油脂」有关。此处标注存疑，不当定论讲。\",\"lung\":\"古英语 lungen，日耳曼语固有词，与 light（轻的）同源——肺是人体里最「轻」的内脏，宰牲验尸时它能浮在水面上，古人便以「轻」称之。德语 Lunge 同源；轻，所以能呼吸浮沉，这个词源自带物理感。\",\"kidney\":\"中古英语写作 kidenei，构成说法不一、词源未有定论：或以为前半是古英语 cwið「腹、子宫」一类的词，后半 -ei 是「蛋」——因其形似豆、似蛋而得名只是推测之一。此词诚实标注：来源不明。\",\"brain\":\"古英语 brægen，日耳曼语固有词，德语作 Bregen（方言）。它在印欧语里更远的亲属关系不明确，词源学上只能追溯到原始日耳曼语；英语没有从拉丁、希腊借词，自己土生土长的「脑」就是这一个词。\",\"nerve\":\"来自拉丁语 nervus，本义是「筋腱、肌腱」，古希腊、古罗马解剖学把筋和神经混作一类白色索状物，nervus 便一路兼指两者。后来神经被单独认出，词留了下来；「胆量」义（have the nerve）是「筋」的坚韧感转的。\",\"neuron\":\"来自希腊语 neuron，本义「筋、弦、神经索」。19 世纪末德国解剖学家 Waldeyer 用它命名「神经元」这个细胞单位——把古希腊的「筋索」一词，装进了显微镜时代的新发现。\",\"skull\":\"中古英语 sculle，很可能来自斯堪的纳维亚语源（古诺尔斯语一带），与 skalli「秃头」有关的说法常被引用，也有人联系到「碗」——但都未成定论。此词标注：北欧借词嫌疑大，具体源头存疑。\",\"rib\":\"古英语 ribb，日耳曼语固有词，德语 Rippe 同源，本义就是「肋骨、肋材」。它后来兼指船的肋材、伞骨——一切弧形支撑条都借了肋骨的名字，因为形状和功能都像。\",\"spine\":\"来自拉丁语 spina，本义是「荆棘、刺」。脊柱是一排带棘突的椎骨，摸上去像一列刺，拉丁人直接拿「刺」命名；书脊（spine of a book）和仙人掌的刺至今共用这个词。\",\"joint\":\"来自古法语 joint，是拉丁语 iunctus「被连接的」的变形，动词是 iungere「连接」，与 iugum「轭」同源——两头牛套在同一副轭上。骨与骨「套接」之处就是关节；join（加入）是同一个词。\",\"cartilage\":\"来自拉丁语 cartilago，在拉丁语里就专指软骨、脆骨，经法语进入英语。拉丁语之前的来源不详，词源到此为止；记住它的日常对应物是 gristle（脆骨），餐桌和解剖台说的是同一样东西。\",\"ligament\":\"来自拉丁语 ligamentum「绑带、系绳」，动词 ligare 是「捆、绑」。韧带就是把骨头绑在一起的带子；league（联盟）、ally（盟友）里的 lig 也是「绑在一起」，一个绑骨头，一个绑国家。\",\"skin\":\"来自古诺尔斯语 skinn「兽皮、皮」，维京时代借入英语，挤掉了部分古英语 hyd（hide）的地盘。如今 skin 多指人或果蔬的表皮，hide 偏兽皮——两个词在英语里分工，是借词改朝换代的痕迹。\",\"tendon\":\"经法语，来自中世纪拉丁语 tendo，源头是拉丁语 tendere「拉伸、绷紧」。肌腱是连接肌肉与骨、被拉紧传力的索；tend（趋向；照料的另一词源）、extend（伸展）、tension（张力）都是这条「拉伸」的线。\",\"insulin\":\"由拉丁语 insula「岛屿」+ 化学名词后缀 -in 构成，20 世纪初命名。分泌它的细胞聚成胰腺里的「小岛」——朗格汉斯岛（islets of Langerhans）；island 的亲戚 isolate、insulate（使孤立如岛）同源。\",\"digestion\":\"来自拉丁语 digerere：di-（分开）+ gerere「携带、搬运」，本义「搬开、分配、整理」。食物在体内被「分搬处理」就是消化；digest（文摘）同理——把长文分拣整理成短的。\",\"absorption\":\"来自拉丁语 absorbere：ab-（离去）+ sorbere「吸入、吞咽」。海绵把水「吞」没，就是吸收；sorb 这条词根还藏在 adsorb（吸附）里，一个吞进内部，一个粘在表面，只差一字。\",\"nutrition\":\"来自拉丁语 nutrire「哺育、喂奶」，营养的源头是「哺乳」这个动作：营养就是身体被「喂养」的过程。nurse（护士、乳母）和 nurture（养育）都出自这一词根，全家都管「喂」。\",\"obesity\":\"来自拉丁语 obesus「肥胖的」，字面拆开是 ob-（充分）+ edere「吃」——「吃出来的胖」，过去分词的样子。词源一点不留情面；同根的 edible（可食用的）里藏着同一个 edere。\",\"diabetes\":\"来自希腊语 diabetes，本义「虹吸管、过路」，由 dia-（穿过）+ bainein「行走」构成。古希腊医生 Aretaeus 用它命名这种病：喝进去的水像穿过虹吸管一样直排出去，多尿正是当时的诊断标志。\",\"tumor\":\"来自拉丁语 tumor「肿胀、隆起」，动词 tumere 是「肿、胀」。肿瘤在源头上只描述形态——一团肿起来的东西，不预设良恶；tumult（喧闹骚动）的「胀」是情绪版的同源词。\",\"benign\":\"来自拉丁语 benignus「仁慈的、善良的」：bene（好、善）+ genus（出生、种属），字面是「生性良善」。医学借它说肿瘤「性情温和、不惹事」；它的反义词 malignant 出身正好相反，是一对镜像词。\",\"malignant\":\"来自拉丁语 malignus「心怀恶意的」：male（坏、恶）+ genus（出生），字面「生性不良」，在教会拉丁语里指魔鬼。医学用它形容肿瘤「天生带恶」——会扩散、会夺命；和 benign 是同构的一对反义词。\",\"stroke\":\"古英语 strāc，本义「一击、打击」，与 strike 同族。中风的医学义来自「突如一击」的意象：旧称 apoplexy 说的是「被击倒」，民间则说是「上帝之手的一击」（stroke of God's hand）——病发如挨了一棍。\",\"allergy\":\"德语 Allergie，1906 年由奥地利儿科医生 von Pirquet 造出：希腊语 allos「其他的」+ ergon「作用、反应」。他想表达的是身体「换了一种方式反应」——免疫系统对无害物质反应过头，就是过敏。\",\"sanitation\":\"来自拉丁语 sanitas「健康」，词根 sanus 是「健康的、健全的」。卫生设施的词源直指目的：19 世纪的公共卫生运动（sanitary movement）正是靠下水道和清洁供水把城市死亡率压下来的；sane（神志健全的）是同一个 sanus。\",\"contagious\":\"来自拉丁语 contagiosus，名词 contagio 是「接触、沾染」：con-（一起）+ tangere「触摸」。传染在源头上就是「碰出来的」——contact（接触）、tact（触感）同根；古人不知病菌，却把传播方式说对了。\",\"incubation\":\"来自拉丁语 incubare：in-（在……上）+ cubare「躺」，本义是母鸡「趴在蛋上孵」。病原体在体内无声地「趴着」直到发病，那段潜伏期便借了孵化的名字；incubator（恒温箱、早产儿保育箱）是同一画面。\",\"recovery\":\"经古法语 recoverer，来自拉丁语 recuperare「重新取回」：re-（再）+ capere「抓取、取得」的复合形式。康复就是把健康「夺回来」；recover 还兼任「追偿、收回（欠款）」，取回的东西不同，动作是同一个。\",\"relapse\":\"来自拉丁语 relabi：re-（向后）+ labi「滑落」。病情好转后又「滑回去」就是复发；lapse（疏忽、时间流逝）是同一条「滑」的词根——时间会滑走，防线也会滑落。\",\"chronic\":\"来自希腊语 khronos「时间」，经拉丁语 chronicus 进入英语。慢性病的定义就写在词源里：拖得久、以年计；chronicle（编年史）、chronology（年表）都是 khronos 的子孙，全家都和时间打交道。\",\"acute\":\"来自拉丁语 acutus「磨尖的、锋利的」，词根 acus 是「针」。急性病像针扎：起病尖锐、来势快；几何里的 acute angle（锐角）是同一把「尖」——医学和数学共用一个词源意象。\",\"severe\":\"来自拉丁语 severus「严峻的、苛严的」，指人不苟言笑、执法如山。它在拉丁语之前的来源不明确，词源追溯到此为止；英语里它先形容人「严厉」，后形容病情、天气「严重」。\",\"mild\":\"古英语 milde，本义「温和的、宽厚的」，日耳曼语固有词，最早形容人的性情与君主的仁慈，后来转去形容天气、口味、病情的「轻」。从「人温和」到「病轻微」，词义一路放软。\",\"mortality\":\"来自拉丁语 mortalitas，核心是 mors「死亡」。mortal 是「终有一死的、致命的」；死亡率的词源提醒人：mortality 的统计对象是「必死性」本身。immortal（不朽的）是它的反面，mortgage（按揭）里也藏着这个 mort。\",\"longevity\":\"来自拉丁语 longaevitas：longus（长）+ aevum（年岁、时代）。长寿的字面就是「年岁长」；aevum 还在 medieval（中世纪的：medi- 中间 + aevum）里露过脸，是拉丁语里管「年代」的大词根。\",\"physician\":\"经古法语 fisicien，来自拉丁语 physica「自然之学」，源头是希腊语 physis「自然」。physician 的本义是「研究自然的人」——中世纪它先指自然哲学家，后来才专指医生；physics（物理学）是它的同胞兄弟。\",\"surgeon\":\"经古法语 cirurgien，来自拉丁语 chirurgia，源头是希腊语 kheirourgia：kheir（手）+ ergon（工作）——「用手工作的人」。内科靠药、外科靠手，词源把分工写得清清楚楚；surgery 同源。\",\"nurse\":\"经古法语 norrice「乳母」，来自拉丁语 nutrire「哺育、喂奶」。nurse 的起点是「喂奶的人」，后扩展为照护病弱的人；nutrition（营养）、nurture（养育）同根——照护的本质，词源说是先让人吃饱、活下来。\",\"patient\":\"来自拉丁语 patiens「正在忍受、承受的」，动词 pati 是「受苦、忍耐」。病人就是「承受病痛的人」；同一个 pati 还生出 passion（激情，原义受难）和 patience（耐心）——受苦、忍耐、激情本是一家。\",\"ward\":\"古英语 weard「看守、守卫」，日耳曼语固有词，与德语 Warte（瞭望）同源。病房原是医院里「被看护的一区」；它还兼任「被监护人」和城市的「选区」——凡需要专人守着的单位，都叫 ward。warden（看守人）同族。\",\"emergency\":\"来自拉丁语 emergere：e-（出来）+ mergere「沉没、浸」，本义「浮出水面、冒出来」。紧急情况就是突然「冒出来」的事；merge（合并）是往里沉，emerge 是往外出，正好反着来。\",\"incision\":\"来自拉丁语 incidere：in-（进入）+ caedere「切、砍」。手术刀「切进去」的口子就是 incision；caedere 家族庞大：decide（决断，「切断」犹豫）、precise（精确，「预先切齐」）、scissors（剪刀）都带着这把刀。\",\"stitch\":\"古英语 stice「刺、扎、刺痛」，与 stick（刺、棍）同源。缝合的词源是动作本身：一针一针「扎」过去；它至今还兼指运动时岔气的「肋部刺痛」——老词义在口语里活了下来。\",\"bandage\":\"来自法语 bandage：bande「布带、条带」+ -age（名词后缀）。bande 本是日耳曼语借进法语的词，与 band（带子；乐队）同源。绷带的字面就是「一条带子」，功能全在形状里。\",\"ointment\":\"经古法语 oignement，来自拉丁语 unguentum「膏油」，动词 unguere 是「涂抹、傅油」。古代的膏是拿油脂做底的，抹膏和宗教涂油礼（anoint）同根——药膏的词源带着油光；anoint 的 -oint 正是这条线。\",\"pill\":\"来自拉丁语 pilula「小球」，是 pila「球」的指小形式。药丸的词源只管形状：做成小球好吞服；同源的 pellet（小颗粒）、台球里的 ball 意象相通，只是 pila 走的是拉丁一脉。\",\"dose\":\"经拉丁语、法语，源头是希腊语 dosis「给予之量」，动词 didonai 是「给」。剂量就是医生「给定的那一份」；donor（捐献者）、donate（捐赠）里的 don/dos 与希腊语这条「给」的线索遥相呼应（拉丁语 donare 同源）。\",\"prescription\":\"来自拉丁语 praescribere：prae-（预先）+ scribere「写」。处方是医生「预先写下」的指令——先写，后照办；prescribe 还兼任「规定」，scribe（抄写员）、describe（描述）都是 scribere 的家族成员。\",\"pharmacy\":\"经拉丁语，源头是希腊语 pharmakon——一个著名的双面词：既指「药」，也指「毒」，还指「魔咒」。药与毒同源异流，全看剂量和使用；药房 pharmakeia 是「调制 pharmakon 的地方」。\",\"side-effect\":\"side（旁边）+ effect（效果）的英语复合词。effect 来自拉丁语 efficere：ex-（出）+ facere「做」，效果是「做出来的结果」。正作用之外「旁边」冒出来的结果，就是副作用——构词本身把主次分得很清楚。\",\"addiction\":\"来自拉丁语 addictio「交付、判给」，动词 addicere 在罗马法里指法官把债务人「判给」债主抵债。成瘾的字面处境是「被交付出去、身不由己」——古罗马的法律词，恰好说中了瘾的本质。\",\"withdrawal\":\"withdraw（撤回：with- 表示「向后、离开」的日耳曼语前缀 + draw 拉）+ -al（名词后缀）。戒断义是 20 世纪才固定的：停药后身体把依赖「撤回」时的反扑。withdraw 本义把钱从账户「拉回来」，withdrawal 也兼任「提款」。\",\"physiotherapy\":\"希腊语复合词：physis（自然）+ therapeia（治疗、侍奉）。物理治疗早期称「自然疗法」——靠冷热、按摩、运动这些自然手段治病；therapy 的 therapeia 本义是「侍奉、照料」，治疗一词带着服侍人的温度。\",\"anxiety\":\"来自拉丁语 anxietas，动词 angere 是「掐紧、使窒息、使苦恼」。焦虑的身体感就写在词源里：喉咙被「掐住」的窒闷。angina（心绞痛）同根——胸口被掐紧的那种痛，古人用的是同一个动词。\",\"depression\":\"来自拉丁语 deprimere：de-（向下）+ premere「压」。情绪被「往下压」就是抑郁；经济学的大萧条（the Great Depression）借的是同一意象——整个经济被压到谷底。press（压；新闻界）是 premere 的近亲。\",\"insomnia\":\"来自拉丁语 insomnis：in-（不）+ somnus「睡眠」——直译「无眠的」。somnus 是罗马的睡神之名；somber 一类词无关，但 somnambulist（梦游者：somnus + ambulare 行走）是亲兄弟，睡着睡着走了出去。\",\"stress\":\"经古法语 estresse「狭窄、困顿」，来自拉丁语 strictus「被拉紧的」，是 distress 的缩略形。压力的词源画面是「被绷紧、被挤压」；stringent（严苛的）、restrict（限制）同根，stringere 这根「绳」把全家勒在一起。\",\"trauma\":\"直接借自希腊语 trauma「伤口、创伤」。它原是外科词，指身体的伤；20 世纪心理学把它借去指心灵的伤——创伤后应激（PTSD）里的 trauma，已是心理义为主力。词没变，伤的位置变了。\",\"disorder\":\"dis-（分开、否定）+ order（秩序）：order 经古法语 ordre，来自拉丁语 ordo「行列、等级」。秩序本是「排成行列」，disorder 就是行列散了套——医学的「紊乱」、社会的「骚乱」共用一个画面。\",\"syndrome\":\"来自希腊语 syndromē：syn-（一起）+ dramein「跑」，字面「一起跑、汇合」。一组症状总是结伴出现、像约好了一起跑来，就是综合征；同根的 drome 在 hippodrome（赛马场）里——「跑的地方」。\",\"congenital\":\"来自拉丁语 congenitus：con-（共同）+ genitus「出生的」（gignere 生育）。与生俱来的，就是 congenital；gen 这条「出生」词根家族很大：gene（基因）、generate（产生）、genius（天赋）都是同门。\",\"deficiency\":\"来自拉丁语 deficere：de-（向下、缺离）+ facere「做」，在拉丁语里整体义是「不够、失败、衰竭」。缺乏的本质是「做不到量」；deficit（赤字）、defect（缺陷）同根，账上的、身体上的短少都是它。\",\"surplus\":\"经古法语，来自中世纪拉丁语 superplus：super-（在上、超出）+ plus「更多」。多出来的那一截就叫 surplus；plus 本身就是拉丁语的「更多」，超市促销的「plus」和财政盈余用的是同一个词。\",\"perception\":\"来自拉丁语 percipere：per-（彻底）+ capere「抓取」。感知是感官与大脑把外界「抓全、抓牢」的过程；capere 家族显赫：capture（捕获）、receive（接收，抓回来）、concept（概念，抓在一起的想法）。\",\"cognition\":\"来自拉丁语 cognoscere：con-（一起、完全）+ gnoscere「知道、认识」，与希腊语 gignōskein 同源。认知就是「把信息认全」；recognize（认出）是「再认一次」，ignore（忽视）的源头是「不知道」——正反两面都在这条线。\",\"sensation\":\"来自中世纪拉丁语 sensatio，根是拉丁语 sensus「感觉」，动词 sentire「感受」。感觉是感官被世界碰到后的回响；sense（感觉；理智）、sensitive（敏感）、sentence（句子，原义「想表达的」）都从 sentire 出发。\",\"stimulus\":\"拉丁语 stimulus 本义是「赶牛的尖棒、刺棒」，牧人扎牛让它往前走。心理学借来指一切能「扎」出反应的东西；stimulate（刺激、激励）同词——被轻轻扎一下，动起来。\",\"behavior\":\"由 behave（举止）+ -ior 构成：behave 是 be-（加强）+ have（持有），旧义「持守自己、约束言行」。行为在词源里偏「自持」：一个人怎么「拿住自己」，就是他的 behavior；misbehave 是「没拿住」。\",\"instinct\":\"来自拉丁语 instinctus「激励、冲动」，动词 instinguere：in- + stinguere「刺」，字面「被刺而动」。本能是刻在身体里的那一刺，不用学就动；sting（刺痛）与它同源，distinction（区别）里的 stinct 也是「刺出标记」。\",\"learning\":\"古英语 leornian「学习、研读」，日耳曼语固有词，德语 lernen 同源。它的印欧远亲有争议，但英语这一支清楚：learn 先是「读书习艺」，后泛指一切习得；learned（博学的）里的读音变化是它留下的小脚印。\",\"memory\":\"经古法语，来自拉丁语 memoria，词根 memor 是「记着的、留心的」。记忆的词源强调主动「留心」而非被动存档；memorial（纪念碑）、remember（记得）、memoir（回忆录）同根，全家都在对抗遗忘。\",\"recall\":\"re-（再、回来）+ call（呼唤）：call 经古诺尔斯语 kalla「呼喊」进入英语。回忆就是把散落在脑中的信息「再喊回来」；recall 也兼任「召回（产品）」——喊回来的可以是记忆，也可以是一批汽车。\",\"recognition\":\"来自拉丁语 recognoscere：re-（再）+ cognoscere「认识」，字面「再认一次」。识别是旧知识被重新唤醒的瞬间；recognize 在法律上还有「正式承认」义——认出了，还要认账。\",\"attention\":\"来自拉丁语 attendere：ad-（朝向）+ tendere「伸展」——把心智「伸向」某物，就是注意。tendere 家族很忙：extend（伸出去）、intend（打算，心伸向未来）、tension（伸紧的状态）。\",\"concentration\":\"con-（一起）+ center（中心）：center 经拉丁语 centrum，源头希腊语 kentron「圆心、尖点」。专注就是把散开的注意力「收拢到一个中心点」；化学的「浓度」同理——溶质向一处聚集。\",\"distraction\":\"来自拉丁语 distrahere：dis-（向各方）+ trahere「拖、拉」。分心就是注意力被「往四处拖走」；trahere 家族：tractor（拖拉机）、abstract（抽象，把共性抽拉出来）、attract（吸引，拉向自己）。\",\"motivation\":\"由 motive（动机）+ -ation 构成：motive 来自拉丁语 movere「移动」的衍生形式 motivus「使动的」。动机就是心里那台「发动机」——move 家族：motion（运动）、motor（马达）、emotion（情绪，被搅动出来的）全是它。\",\"emotion\":\"经法语 émotion，来自拉丁语 emovere：e-（向外）+ movere「移动」，字面「搅动出来」。情绪是内心被事件「搅动」的外显；它和 motivation、motion 同根——心理学的两大词，共享一台「移动」的发动机。\",\"mood\":\"古英语 mōd，本义「心智、精神、勇气」，日耳曼语固有词，德语 Mut（勇气）同源。注意：语法里的 mood（语气）来自拉丁语 modus，是另一个词，只是拼写撞车。心情这个 mood，老家在日耳曼人的「心气」。\",\"anger\":\"来自古诺尔斯语 angr，本义「悲痛、忧伤」，与拉丁语 angere「掐紧」同出印欧语「狭窄、窒息」一系。愤怒的源头竟是「悲伤与被掐紧」——维京人带来的词，先指心里堵，后指火冒三丈。\",\"joy\":\"经古法语 joie，来自拉丁语 gaudium「喜悦」，动词 gaudere「欢喜」。joy 的血脉是拉丁式的明亮快乐；它挤掉了古英语表达喜悦的 wynn——法语词在诺曼征服后接管了英语的情感词汇，joy 是代表之一。\",\"sorrow\":\"古英语 sorg「忧虑、悲伤」，日耳曼语固有词，德语 Sorge（操心）同源。它先是「揪心的忧虑」，后专指悲伤；sorry（抱歉的）与它同根——抱歉，本就是心里带着一点 sorg。\",\"disgust\":\"经法语、意大利语，来自 dis-（否定）+ 拉丁语 gustus「味觉、品尝」。厌恶的源头是「尝到坏味」：从舌头的反胃，到对人事的反感；gust 在 gusto（兴致勃勃，原义「好胃口」）里是它的阳光面。\",\"surprise\":\"来自古法语 surprise，是 surprendre「出其不意地抓住」：sur-（在上，源于拉丁 super）+ prendre「抓取」（拉丁 prehendere）。惊讶是被现实「一把抓住」的瞬间；apprehend（逮捕；理解）也是这只「抓」手。\",\"empathy\":\"1909 年由心理学家 Titchener 仿德语 Einfühlung「感同身受」译造：希腊语 em-（进入）+ pathos（感受、苦难）。同理心是「走进」他人的感受里；比 sympathy（站在旁边同情）多走了一步，词源上正是 em- 与 syn- 的区别。\",\"sympathy\":\"来自希腊语 sympatheia：syn-（共同）+ pathos「感受、苦难」，经拉丁语进入英语。同情是「与他一起感受」；医学上 sympathetic nervous system（交感神经）借的也是「器官互相感应」的旧义。\",\"temperament\":\"来自拉丁语 temperamentum「恰当的混合比例」，动词 temperare「调和、节制」。古希腊罗马体液说认为性情由四种体液配比决定——气质就是一个人的「配比」；temper（脾气；节制）、temperature（温度，混合的冷热）同根。\",\"trait\":\"来自法语 trait「一笔、线条」，源头是拉丁语 tractus「拉、拖的痕迹」（trahere 拖）。特质是画在性格上的一笔；portrait（肖像）里的 trait 也是「笔法线条」——画家用线条留人，心理学家用 trait 描人。\",\"aptitude\":\"经法语，来自拉丁语 aptitudo，词根 aptus「合适的、胜任的」。天赋在词源里不是「天上掉的」，而是「与某事严丝合缝的适配」；apt（恰当的；易于……的）是同一个词——合适，所以擅长。\",\"talent\":\"经拉丁语 talentum，源头是希腊语 talanton，本义「天平、秤」，后指一大笔钱（塔兰同重量单位）。《圣经》「才干的比喻」里仆人拿银子去经营，天赋义由此而来：才能是托付给你去「经营增值」的本钱。\",\"creativity\":\"create（创造）+ -ivity：create 来自拉丁语 creare「产生、造出」，与 crescere「生长」同族。创造力在词源里带着「生长」的底子——不是无中生有，而是让新东西长出来；creature（生物、造物）同根。\",\"imagination\":\"来自拉丁语 imaginatio，词根 imago 是「图像、肖像、映像」。想象力就是在脑子里「成像」的能力；image（图像）是它的直系，imitate（模仿）的关系稍远——脑中的画先成型，创造随后。\",\"dream\":\"古英语 drēam 本义竟是「欢乐、乐声」，睡梦义在中古英语受古诺尔斯语 draumr 影响才固定下来——两个日耳曼词撞在一起，合流成今天的 dream。这段词源本身像个小谜：一个词的白天和夜晚，来自两条线。\",\"unconscious\":\"un-（不）+ conscious（有意识的）：conscious 来自拉丁语 conscius「自己知道的」（con- 一起 + scire 知道）。无意识就是「自己不知道的那部分心」；弗洛伊德让它成了心理学的头号关键词，构词却朴素得很。\",\"subconscious\":\"sub-（在下）+ conscious（有意识的），19 世纪心理学造的词：意识「水面之下」的那一层。注意词源分工：unconscious 是「完全不知」，subconscious 是「在意识门槛下」——前缀 sub- 把层次标得很精确。\",\"conscious\":\"来自拉丁语 conscius：con-（与、一起）+ scire「知道」，字面「与自己一起知道的」。意识的核心是「自知」；science（科学）同根 scire——一个是向内知道自己，一个是向外知道世界。\",\"awareness\":\"由 aware + -ness 构成：aware 来自古英语 gewær「警觉的、留意的」，与 ward（看守）、wary（警惕的）同族。意识在词源里带着「警戒」色：对外界保持警觉，信息才进得来。\",\"intuition\":\"来自拉丁语 intueri：in-（向内）+ tueri「注视、守护」，字面「凝视、看透」。直觉是未经推理的一眼看穿；tutor（导师，守护者）、tuition（学费，原义监护）都是 tueri 这只「看顾之眼」的家族成员。\",\"deduction\":\"来自拉丁语 deducere：de-（向下）+ ducere「引导」——从普遍原理「一路领下来」到具体结论，就是演绎。它和 induction（归纳）是镜像：一个往下推导，一个往上汇总，共用 ducere 这位「向导」。\",\"induction\":\"来自拉丁语 inducere：in-（向内、进入）+ ducere「引导」。归纳是把一个个实例「领进来」凑成规律；电磁感应也是 inducere——磁场把电流「领」出来。一条词根，管逻辑也管物理。\",\"analogy\":\"来自希腊语 analogia「比例相符」：ana-（依照）+ logos「比例、道理」。类比的骨架是比例——A 之于 B，正如 C 之于 D；logos 家族庞大（logic 逻辑、dialogue 对话），analogy 是其中最讲「对应」的一位。\",\"inference\":\"来自拉丁语 inferre「带入、带来」（in- + ferre 携带）的名词形式，与 infer（推断）同源：把证据「带进来」，结论随之而生。transfer（转移）、fertile（肥沃的，能产出的）里的 fer 都是这位「搬运工」。\",\"judgment\":\"经古法语 jugement，核心是拉丁语 iudicare「裁决」：ius（法律）+ dicare「宣示、讲述」。判断的源头是法庭动作——把法说出来；judge（法官）、justice（正义）、prejudice（偏见，先行裁决）全家都在这座法庭里。\",\"problem-solving\":\"复合词：problem 来自希腊语 problēma「抛到前面的东西」（pro- 向前 + ballein 投掷），原指横在路上的障碍、待解的题；solve 来自拉丁语 solvere「松开、解开」。解决问题，就是把「抛在面前的结」松开。\",\"stereotype\":\"原是印刷术语：希腊语 stereos（坚固的、立体的）+ typos（印痕、模型），指浇铸成型的铅版——印什么都一样。1922 年李普曼把它借进社会心理学：脑子里的固定印象，就像铅版，一印一个样。\",\"prejudice\":\"来自拉丁语 praeiudicium：prae-（在前）+ iudicium「裁决」，字面「预先的裁决」。偏见是在证据到场之前就下好的判决；它和 judgment 同属 iudicare 法庭家族，一个是先判，一个是后判。\",\"belief\":\"古英语 gelēafa 的现代形式，与 lief（乐意的、亲爱的）和 love 同出日耳曼语「珍视、信任」一系。信念的词源不是「断定为真」，而是「珍视而信靠」——德语 Glaube 同根，信仰先有情感，后有命题。\",\"value\":\"经古法语 value，来自拉丁语 valere「强壮、有力、有价值」。价值观是「值得看重」的东西清单；valere 家族：valid（有效的，有力的）、valor（勇气）、available（可用的）——价值的源头是「力量」。\",\"conformity\":\"来自拉丁语 conformare：con-（一起）+ forma「形状」，字面「塑成同样的形状」。从众就是被群体这只模具「压成同形」；form（形式）、uniform（制服，同一形状）、reform（重塑）同根。\",\"obedience\":\"来自拉丁语 oboedire：ob-（朝向）+ audire「听」。服从的源头是「听」——听清指令并照做；audience（听众）、audio（音频）同根，obedience 只是把「听」执行到了行动层。\",\"leadership\":\"leader + -ship：lead 来自古英语 lædan「带领、引路」，日耳曼语固有词；-ship 表示「身份、状态」（古英语 -scipe）。领导力就是「身为引路人的状态」——词源里没有发号施令，只有走在前面带路。\",\"cooperation\":\"来自拉丁语 cooperari：co-（共同）+ operari「工作」，词根 opus 是「作品、劳作」。合作就是「一起干活」；opera（歌剧，原义作品）、operation（手术；运作）同根——都是 opus 的不同工种。\",\"competition\":\"来自拉丁语 competere：com-（一起）+ petere「追求、奔向」，本义是「汇聚、相遇、共同争取」，并无敌对味。竞争的源头画面是众人奔向同一目标；petition（请愿，求）、appetite（食欲，求）里的 pet 都是「奔向」。\",\"aggression\":\"来自拉丁语 aggredi：ad-（朝向）+ gradi「迈步、行走」，字面「朝人走过去」——走过去可以谈判，也可以动手。攻击性取的是后一种走向；grade（等级，台阶）、progress（向前迈步）同根 gradi。\",\"altruism\":\"法语 altruisme，19 世纪由哲学家孔德（Auguste Comte）造出，基于 altrui「他人」（源头拉丁语 alter「另一个」）。利他主义是与 egoism（利己）对造的新词：把「他人」放进词根，主义就立住了。\",\"reinforcement\":\"re-（再）+ enforce（强制执行）+ -ment：enforce 经古法语 enforcer，远源拉丁语 fortis「强壮的」一系，字面「使之强」。强化就是「再使之强」；心理学借它指让行为更「强固」的奖励，fort（堡垒）是同根的力量派。\",\"punishment\":\"punish 来自拉丁语 punire，词根 poena 是「惩罚、罚金」，再往上是希腊语 poinē「赎罪金、血债的赔偿」。惩罚的源头是「偿付」：古人犯了事，先拿钱粮把账平了；penalty（罚款；点球）同根。\",\"reward\":\"来自盎格鲁-诺曼法语 rewarder「注视、考虑」，与古法语 regarder 同源，日耳曼语词根 ward 是「看守、留意」。奖励的原义是「被看在眼里、被计较」的那份回报——干了活被人「看上」，才有赏；它和 ward（病房）竟是远亲。\",\"conditioning\":\"condition 经古法语，来自拉丁语 condicio「约定、条件」，由 con-（一起）+ dicere「说」构成——双方「说到一起」的条款。巴甫洛夫的条件反射借了这个词：刺激与反应之间，也像签了一份「一说就灵」的约定。\",\"association\":\"来自拉丁语 associare：ad-（朝向）+ socius「伙伴、同伴」。联想就是把两个心理表象「结成伙伴」；society（社会）、social（社交的）同根——脑中的概念和人群里的伙伴，靠的是同一种「结伴」。\",\"discrimination\":\"来自拉丁语 discriminare，名词 discrimen 是「分界、区别」，远源 discernere「筛分、分辨」（cernere 筛）。本义是中性的「辨别」——心理学讲辨别刺激，社会学讲歧视：同一个「分」，分得公不公道决定了词的褒贬。\",\"threshold\":\"古英语 þrescold：前半 thresh 与「踩踏、打谷（脱粒）」有关，后半的来源至今不明确。门槛是「进门时踩着的那块板」之说流传最广；心理学的「阈限」借它指感知被「踩」过的那道界线——刺激跨过门，才被察觉。此词后半存疑，标注在此。\",\"sensory\":\"由 sense（感觉）+ -ory 构成：sense 来自拉丁语 sensus，动词 sentire「感受」。感觉系统的词源朴素：被世界碰到并有所感；同根 sensation（感觉）在心理学课本里与它搭档出现，一个作名词，一个作形容词。\",\"visual\":\"来自拉丁语 visualis，词根 visus 是「视觉」，动词 videre「看」。视觉的词源就是「看」本身；video（视频，「我看见」）、vision（视力；愿景）、evident（明显的，看得见的）都是 videre 家族。\",\"auditory\":\"来自拉丁语 audire「听」的衍生形式。听觉的词源是「听」：audire 家族有 audience（听众）、audition（试镜，原义试听）、obedience（服从，听而从之）——耳朵这条线，从教室通到法庭再通到舞台。\",\"illusion\":\"来自拉丁语 illudere：in-（对着）+ ludere「玩耍、戏弄」，字面「拿人开玩笑」。错觉是大脑被感官「戏弄」了一把；ludere 家族爱玩：prelude（前奏）、interlude（插曲）都是「玩」出来的词。\",\"delusion\":\"来自拉丁语 deludere：de-（偏离）+ ludere「玩耍、欺骗」，字面「耍弄、使上当」。妄想是信念被「耍」偏了轨；它和 illusion 同出 ludere——一个骗眼睛（错觉），一个骗信念（妄想），分工由前缀划定。\",\"phobia\":\"来自希腊语 phobos「恐惧、逃跑」，恐惧之神 Phobos 之名。-phobia 先作后缀缀在各种对象后（hydrophobia 恐水症），19 世纪才析出单独成词；火星的卫星 Phobos（火卫一）与它同名——恐惧在天上也有户口。\",\"counseling\":\"counsel 经古法语 conseil，来自拉丁语 consilium「商议、忠告、计谋」。咨询的词源是「坐下来一起商量」；注意别和 council（委员会，源于 concilium 集会）混同——拼写相近，consilium 这条「忠告」线才是 counseling 的本家。\",\"relaxation\":\"来自拉丁语 relaxare：re-（回、开）+ laxare「放松」，词根 laxus 是「松弛的」。放松就是把绷紧的「松回去」；lax（松懈的）是它的形容词本家，laxative（泻药）是医学支线——都是让某处「松」下来。\",\"coping\":\"cope 的本义是「交锋、对抗」，经古法语 coper「打击」而来，远源与「一击」（coup）有关。心理学的 coping 把战场搬进内心：应对，就是和压力「过招」并站稳；不是躲开，而是接得住。\",\"resilience\":\"来自拉丁语 resilire：re-（回）+ salire「跳跃」——被压下去还能「跳回来」，和 resilient（有韧性的）同源。心理韧性的画面词源自带弹簧：salire 还在 salient（显著的，跳出来的）里露脸。\",\"self-esteem\":\"self（自己）+ esteem（尊重、评价）的复合词：esteem 来自拉丁语 aestimare「估价」。自尊的字面是「给自己的估价」——心理学定义（对自我价值的整体评价）几乎就是词源的直译；estimate（估计）同根。\",\"adolescence\":\"来自拉丁语 adolescere「成长、长大」：ad-（朝向）+ alescere「生长」，再往上 alere 是「滋养」。青春期是「正被养育着长大」的阶段；同根 alumnus（校友）是「被滋养者」，adult（成人）是「已长成的」——一条生长链。\",\"childhood\":\"child + -hood（状态、时期）：child 是古英语 cild，日耳曼语固有词；-hood 与德语 -heit 同源。童年就是「身为孩子的时期」；knighthood（骑士身份）同后缀——时期与身份，在构词上是同一回事。\",\"infancy\":\"来自拉丁语 infantia，词根 infans：in-（不）+ fans「说话的」（fari 说），字面「还不会说话的（人）」。婴儿的定义写在词源里——以语言为界，太残酷又太准确；infantry（步兵）另有一条「年轻随从」的支线，同源而分途。\",\"development\":\"经法语 développement，动词 develop 本义「展开、解开包裹」：des-（解除）+ veloper「包裹」，后半的来源有争议。发展在词源里是「把裹着的展开」——潜能本就在里面，长大的过程是层层打开；envelope（信封）是可能的远亲。此词标注：后半词源未定。\",\"maturation\":\"来自拉丁语 maturare「使成熟」，词根 maturus 是「熟透的、适时的」。成熟的意象是果子熟：时候到了，自然落地；mature（成熟的）、immature（不成熟的）同根，词源对「早熟晚熟」自带时间感。\",\"nurture\":\"经古法语 norriture，来自拉丁语 nutrire「哺育」。后天培养的字面就是「喂养」——nature vs. nurture 之争里，nurture 代表环境与教养这一极；它与 nurse、nutrition 同根：养大一个人，先靠喂，后靠育。\",\"university\":\"经古法语，来自拉丁语 universitas「整体、团体、行会」，词根 universus 是 uni-（一）+ versus「转向的」，字面「合而为一的全体」。中世纪它先指师生行会，后指学校；universe（宇宙）是同根的大哥——一个装知识，一个装万物。\",\"college\":\"来自拉丁语 collegium「同僚团体、行会」，由 con-（共同）+ legare「选派、委任」构成的 collega（同僚）而来。学院的起点是「一群被选在一起的人」；colleague（同事）保留着最原始的词义——同僚本身就是一所微型 college。\",\"seminar\":\"经德语 Seminar，来自拉丁语 seminarium「苗圃、育种地」，词根 semen 是「种子」。研讨会是学术的苗圃：思想当种子撒下，在讨论里发芽；seminary（神学院）同根，semen 这粒种子还藏在 disseminate（传播，撒种）里。\",\"workshop\":\"work（工作）+ shop（店铺）的复合词：shop 是古英语 sceoppa「摊位、小店铺」。工作坊原指手艺人的作坊，20 世纪被借去指围坐实操的培训——从打铁的铺子到头脑风暴的会议室，「动手做」是没丢的魂。\",\"syllabus\":\"这个词源于一次著名的误印：西塞罗书信里的希腊语 sittyba「羊皮纸标签、书名签」（指书卷上的题签），在文艺复兴的印刷本里被误读成 syllabus，就此将错就错成了「教学大纲」。词源史上少有的「错出来的词」。\",\"subject\":\"来自拉丁语 subiectus：sub-（在下）+ iacere「投掷」，字面「被置于其下的」。学科是「摆在研读之下的对象」，臣民是「被置于统治之下的」——subject 的几大义项，共用同一个「在下」的位置；object（对象）是「抛在对面的」，正好相对。\",\"bachelor\":\"经古法语 bacheler，本指「年轻骑士、见习者」。更早的来源未有定论：一说联系中世纪拉丁语 baccalarius（农庄佃户、帮工），另有凯尔特语来源说。学位义取其「入门阶」的位置。此词标注存疑：源头众说纷纭，无一坐实。\",\"master\":\"来自拉丁语 magister「师长、首领」，与 magis「更、更大」同族（magnus 大的一系），古英语已借入 mægester，又经古法语 maistre 加固。硕士的字面是「更有学问的人」——学位等级里，它的词源自带「更高一级」。\",\"doctorate\":\"doctor（博士）+ -ate（身份后缀）：doctor 来自拉丁语 docere「教导」，字面「教师」。博士学位的词源定位很明确：有资格「教」的人；document（文件）、doctrine（学说）同根——教人者留下的文字与道理。\",\"certificate\":\"来自中世纪拉丁语 certificatum，是 certificare「使确凿、作证」的结果：certus（确定的）+ facere（做）。证书就是把事实「做实」的那张纸；certain（确定的）是同一位 certus，certify（证明）是它的动词形态。\",\"scholarship\":\"scholar（学者）+ -ship（身份、资助）：scholar 经拉丁语 scholaris，源头是希腊语 skholē——本义竟是「闲暇」：有闲暇读书讨论，才有了「学校」和「学问」。奖学金是这条线的现代落点：资助一个人去拥有读书的闲暇。\",\"tuition\":\"来自拉丁语 tuitio「看护、监护」，动词 tueri 是「注视、守护」。学费的原义是付给「监护照看者」的钱——中世纪学生年幼，学校代行监护；后来监护淡去，只剩教学费。tutor（导师）同根，都是那只「看顾的眼睛」。\",\"enrollment\":\"enroll（登记）+ -ment：enroll 经古法语 enroller，是 en-（进入）+ rolle「卷轴、名册」——名字被「写进卷轴」就是注册。roll 的源头拉丁语 rotulus 是 rota（轮子）的指小形式：名册曾经真是一卷能「滚」开的羊皮纸。\",\"admission\":\"来自拉丁语 admittere：ad-（朝向）+ mittere「送、放」，字面「放进来」。入学是被「放行进门」；mittere 家族庞大：mission（使命，被派去的）、submit（提交，送到下面）、permit（许可，放行通过）。\",\"deadline\":\"美式英语，源于南北战争时期的战俘营：栅栏内侧划一条「死线」，越线即被守卫射杀。20 世纪它被新闻业借去指截稿时间——过线虽不要命，稿子是要命的。此词是英语里公认的「词义软化」名场面。\",\"semester\":\"经德语 Semester，来自拉丁语 semestris「六个月的」：sex（六）+ mensis「月」。学期在词源里是明码标价的「半年」；美国大学一年两学期正好对上。mensis 还在 menstruation 等医学词里——「月」这一单位，古人到处在用。\",\"quarter\":\"经古法语 quartier，来自拉丁语 quartus「第四」。学季制把学年「四等分」——quarter 的一切义项（四分之一、刻钟、街区）都从「四分」出发；它在美国校园指约十周的一季，与 semester（半年）形成两种历法。\",\"academic\":\"来自拉丁语 academia，源头是希腊语 Akadēmeia——雅典城外以英雄 Akademos 命名的园林，柏拉图在此讲学，「学园派」由此得名。学术一词的地籍很明确：一切 academic，都源于那片橄榄树林里的讨论。\",\"dean\":\"经古法语 deien，来自拉丁语 decanus「十人长」：decem 是「十」。罗马军团和中世纪修道院里，每十人设一小头目；大学借来作学院之长——从管十个人到管一个学院，dean 的辖区涨了，词没变。\",\"professor\":\"来自拉丁语 professor「公开宣讲者」，动词 profiteri：pro-（当众）+ fateri「承认、宣示」。教授的词源身份是「当众宣示学问的人」；confess（坦白）是私下宣示，profess（自称）是公开宣示——fateri 全家都靠「开口说」立足。\",\"instructor\":\"来自拉丁语 instruere：in- + struere「建造、排列、装备」，本义是「备齐、装备（军队、行装）」。讲师的词源起点不是「讲」，而是「装备」——把知识给学生装备上；structure（结构）、construct（建造）同根。\",\"mentor\":\"取自荷马史诗《奥德赛》中的人物名 Mentor——俄底修斯出征特洛伊时托付家事的老友，雅典娜常借他的形貌指点其子。人物名转为普通名词，是词源学里的「名人成词」；mentor 一词因此自带「可信赖的长者」底色。\",\"tutor\":\"来自拉丁语 tutor「监护人、保护者」，动词 tueri「注视、守护」。辅导老师的词源身份首先是「看护人」，其次才是教书的；它与 tuition（学费，原义监护费）同源——中世纪的 tutor 连人带学一起管。\",\"superintendent\":\"来自中世纪拉丁语 superintendens：super-（在上）+ intendere「伸心、致力」（in- + tendere 伸展）。学监的字面是「在上面盯着的人」；intend（打算）是心伸向目标，superintendent 是目光伸向全局——tendere 全家都在「伸」。\",\"preschool\":\"pre-（在前）+ school（学校）：school 经拉丁语 schola，源头希腊语 skholē「闲暇、闲暇中的讨论」。学前班是「学校之前」的阶段——而 school 本身源于「闲暇」，提醒人学习最初是奢侈品，不是义务。\",\"elementary\":\"来自拉丁语 elementarius，词根 elementum 是「元素、基本原理」。初等教育教的就是各科的「元素」；elementum 本身的更早来源有争议，一说与字母 l、m、n 在字母表中的位置有关——基础到字母表里去找，倒也贴切。标注：远源存疑。\",\"secondary\":\"来自拉丁语 secundarius「第二等的」，词根 secundus 是「第二的、跟随的」，动词 sequi「跟随」。中等教育是「跟在初等之后」的第二级；second（第二；秒）同根——秒是把分「再跟一刀」切出的第二级单位。\",\"literacy\":\"由 literate（能读写的）+ -cy 构成：literate 来自拉丁语 littera「字母」。读写能力的词源直白：认得「字母」并能用；literacy 一词 19 世纪才出现，是为对应先行的 illiteracy（文盲）而造——先有问题，后有名词。\",\"numeracy\":\"1959 年英国 Crowther 报告仿 literacy 造出：拉丁语 numerus「数字、数目」+ literacy 的词尾模式。计算能力被刻意造成「数字版的读写能力」——造词本身就是政策主张：算，和读、写一样是基本功。\",\"calculus\":\"拉丁语 calculus 本义「小石子」，是 calx（石头、石灰）的指小形式。古人用石子在算盘上计数演算，微积分便继承了这个名字；医用的 calculus（结石）是同一个词——身体里长出的「小石子」，词源一字不差。\",\"statistics\":\"经德语 Statistik，原是 18 世纪的「国情学」：拉丁语 status 是「国家、状态」，意大利语 statista 指「政治家」。统计学起初专为治国而设——数人口、量土地、算税收；从国家账本，长成现代数据科学。\",\"physics\":\"来自希腊语 physika「自然之物」，词根 physis 是「自然、生长」，亚里士多德的讲稿《物理学》（Ta Physika）定的名。physician（医生）同根：一个研究自然规律，一个调理自然之身（人体），分家前是一家人。\",\"chemistry\":\"经由 alchemy（炼金术）而来：阿拉伯语 al-kīmiyā 是确定的中转站，更远的来源有两说——希腊语 khymeia「熔铸、混合之术」，或古埃及语 kmt「黑土地」（指埃及）。此词标注存疑：两说并存，未有定论。\",\"biology\":\"19 世纪初由拉马克等人推广的造词：希腊语 bios（生命）+ logos（学说、道理）。在它之前，研究生命的学问叫 natural history（自然志）；biology 的诞生，标志着「生命」被单独拎出来成了一门学问。\",\"astronomy\":\"来自希腊语 astronomia：astron（星）+ nomos（法则、秩序）——「星辰的法则」。它与 astrology（占星）本是同根生，近代才分家：一个守法则，一个管命运。nomos 还在 economy（经济：oikos 家 + nomos 管理）里当家。\",\"botany\":\"经拉丁语，来自希腊语 botanē「草、牧草、植物」，与 boskein「喂养、放牧」同族——植物最初是按「牲口的口粮」被命名的。植物学的词源带着牧场气息：先有草喂牛，后有学问研究草。\",\"zoology\":\"希腊语复合词：zōion（动物）+ logos（学说）。zōion 与 zōos「活着的」同源，动物即「活物」；zoo（动物园）就是把词头截下来单用——全世界动物园的招牌，都是 zoology 的缩写。\",\"sociology\":\"1838 年由法国哲学家孔德（Auguste Comte）造出，是个「混血词」：拉丁语 socius（同伴）+ 希腊语 logos（学说）。词源学家曾嫌它血统不纯，孔德本人也知道——但社会学要横跨人群与学理，混血恰是它的命。\",\"anthropology\":\"希腊语复合词：anthrōpos（人、人类）+ logos（学说）。研究「人」的学问，词源毫无遮拦；anthrōpos 还在 misanthrope（厌世者）里——爱人、厌人，同一个 anthrōpos，只差前缀的心情。\",\"archaeology\":\"来自希腊语 arkhaiologia：arkhaios（古老的）+ logos（学说），arkhaios 的根 arkhē 是「开端、起源」。考古学挖的是「开端」：arch- 家族还有 archive（档案）、architect（建筑师，总字头是「首」）——一个挖开端，一个立开端。\",\"linguistics\":\"linguist（语言学家）+ -ics：linguist 来自拉丁语 lingua「舌头、语言」。语言的词源落在器官上——舌头能动，才有语言；bilingual（双语的）、lingual（舌的）同根。linguistics 一词 19 世纪成形，是语言学独立成科的门牌。\",\"theology\":\"来自希腊语 theologia：theos（神）+ logos（学说、言说）。柏拉图、亚里士多德都用过这个词指「论神之说」；theos 家族：theatre 无关，但 atheist（无神论者：a- 无 + theos）是它的正面对手。\",\"economics\":\"来自希腊语 oikonomia：oikos（家、家产）+ nemein「管理、分配」，原义「家政、持家之术」。亚里士多德用它讲家庭账本，近代才放大到国家；ecology（生态学）同出 oikos——一个管人之家，一个管自然之家。\",\"accounting\":\"account（账目）+ -ing：account 经古法语 aconte，来自拉丁语 computare「计算」：com-（一起）+ putare「清点、核算」。putare 家族是会计的祖师爷：compute（计算）、dispute（争论，清点各执一词）、reputation（名声，被人清点的评价）。\",\"marketing\":\"market（市场）+ -ing：market 经日耳曼语中转，源头是拉丁语 mercatus「贸易、市场」，词根 merx「货物」。营销的词源起点是「货物集散之地」；merchant（商人）、merchandise（商品）同根，20 世纪才长出「市场营销」这门现代学科义。\",\"management\":\"manage（处理、管理）+ -ment：manage 经意大利语 maneggiare「驾驭、调教（马匹）」，源头是拉丁语 manus「手」。管理的词源动作是「上手把控」——缰绳在手，马才听话；manual（手册；手动的）、manuscript（手稿）同根 manus。\",\"engineering\":\"engineer（工程师）+ -ing：engineer 来自拉丁语 ingenium「天赋、巧思、精巧装置」（in- + gen 生育一系）。engine（引擎）同源——工程师的词源身份是「有巧思、造装置的人」；ingenious（精巧的）是它的形容词本家。\",\"architecture\":\"经拉丁语 architectura，源头希腊语 arkhitektōn：arkhi-（首席的）+ tektōn「木匠、建造者」。建筑师是「总木匠、首席建造者」；tektōn 还在 tectonic（地壳构造的）里——大地也是被「建造」的；tech（技术）另出 tekhnē，别混。\",\"dentistry\":\"dentist（牙医）+ -ry（行业后缀）：dentist 是法语造词，来自拉丁语 dens（牙齿，属格 dent-）。牙科的字面就是「治牙的行当」；dent 一系：dental（牙齿的）、denture（假牙）、大象的象牙也曾称 dent——牙齿这词，古人按「齿」一以贯之。\",\"nursing\":\"nurse（护士）+ -ing：nurse 来自拉丁语 nutrire「哺育」，原指乳母。护理学的词源底色是「喂养与照护」——南丁格尔把它从家务变成专业，词根却没换：照护人的学问，先从让人活下来开始。\",\"veterinary\":\"来自拉丁语 veterinarius「（关乎）役畜的」，名词 veterinae 指驮载的牲口。它的更早构成有争议：一说与 vetus「老的」有关——牲口要「够年岁」才能驮载。此词标注：主流系于「役畜」，细节存疑；兽医起初只管耕田拉车的大牲口，不管宠物。\",\"agriculture\":\"来自拉丁语 agricultura：ager（田地）+ cultura「耕作、培育」（colere 耕作、居住）。农业就是「在田里耕作」；culture（文化）同根 cultura——耕作土地与耕作心灵，拉丁语用的是同一个词，这是词源学里最有名的跨界。\",\"journalism\":\"journal（日报；期刊）+ -ism：journal 经古法语 jurnal，源头拉丁语 diurnalis「每日的」，根是 dies「日」。新闻学的词源节奏是「按天」：diary（日记）同根——一个记天下事，一个记个人事，都是日子逼出来的文字。\",\"broadcasting\":\"broadcast 本是农业词：broad（宽）+ cast（撒播）——把种子「大把撒向田野」。1920 年代无线电借走了它：信号像种子一样撒向听众。cast 这位「投掷手」还管 cast（投掷；演员阵容）——节目阵容的「撒播」义由此更顺。\",\"photography\":\"1839 年前后定名，英国科学家 Herschel 推广：希腊语 phōs（光）+ graphein「书写、描绘」——「以光作画」。摄影的词源本身就是定义；graph 家族：geography（描地）、autograph（亲笔签）——一个用光写，一个用手写。\",\"pottery\":\"potter（陶工）+ -ery（行业、场所后缀）：pot 是古英语 pott「深口罐」，可能经由通俗拉丁语 pottus，远源不详。陶艺就是「做罐子的行当」；此词标注：pot 的远源未定，但「罐先于艺」——器物在先，手艺得名在后。\",\"sculpture\":\"来自拉丁语 sculptura，动词 sculpere 是「雕刻、刻出」，与 scalpere「刮、刻」同族。雕塑的动作词源是「刻」：从整块材料里刻出形体；同根的 sculptor（雕塑家）保留着工匠气，scalpel（手术刀）则是这把刻刀的医学版。\",\"dissertation\":\"来自拉丁语 dissertatio，动词 disserere 是「连缀论述、研讨」：dis-（分开、展开）+ serere「连接、编排」。学位论文的词源强调「把论点编排展开成系统」；series（系列）同根 serere——论点像珠子，要串起来才成篇。\",\"essay\":\"来自法语 essai「尝试、试验」，源头是拉丁语 exagium「称量、检验」（exigere 称量、要求）。蒙田把自己的短文集命名为 Essais——「试笔」：文章是思想的试称，称称看有多少分量；assay（化验）是它的实验室双胞胎。\",\"assignment\":\"assign（指派）+ -ment：assign 来自拉丁语 assignare：ad-（朝向）+ signare「做标记」（signum 记号）。作业就是老师「标记着分下去」的任务；sign（符号；签名）、design（设计，原义标记出图样）同根——任务的源头是一个记号。\",\"quiz\":\"词源无定论。最流行的说法是 18 世纪都柏林剧院经理 Daly 与人打赌，一夜之间让全城说一个新造的词 quiz——但这一故事不见于当时的可靠记载，多半是后世附会。此词诚实标注：来源不明，赌约说仅作趣闻，不作定论。\",\"score\":\"来自古诺尔斯语 skor「刻痕、计数」，本义是在木棒上刻道记数——刻满二十道为一组（score 还兼指「二十」）。分数的词源是「刻出来的账」；考试分数就是老师在你的表现上「刻」下的计数痕。\",\"attendance\":\"attend（出席；注意）+ -ance：attend 来自拉丁语 attendere「把心伸向」（ad- + tendere 伸展）。出勤的词源与注意力共用一个动词——人到了、心伸过去了，才算 attend；考勤点名，点的是「伸向课堂的心」是否到场。\",\"absence\":\"来自拉丁语 absentia，词根 absens「不在场的」：ab-（离开）+ esse「存在、是」——字面「存在不在此处」。缺勤的构词近乎哲学；present（出席的）是 esse 的另一面：人在场，存在即被确认。\",\"tardy\":\"经古法语 tardif，来自拉丁语 tardus「慢的、迟缓的」。迟到在词源里只是「慢」：没有恶意，只有速度；retard（延迟）同根 tardus。学校里的 tardy slip（迟到单）记的从来不是品行，是表走得比人快。\",\"suspension\":\"来自拉丁语 suspendere：sub-（在下）+ pendere「悬挂」，字面「吊着」。停学是学籍被「悬置」——没落地，也没取消；pendere 家族：pendulum（钟摆）、pending（待定的）、appendix（附录，挂在后面的）——全在「挂」上讨生活。\",\"commencement\":\"commence（开始）+ -ment：commence 经古法语 commencer，源头是通俗拉丁语 cominitiare「着手开始」（com- + initium 开端）。毕业典礼偏叫「开始」——词源的立场很鲜明：典礼不是终点，是新生活的 commencement。\",\"alumni\":\"拉丁语 alumnus 的复数：alumnus 是「被养育者、门生」，动词 alere「滋养、养育」。校友的字面包着师生关系——学校是「养大你」的地方；alma mater（母校）直译「慈母」，同一条 alere 的奶线。alumni 是复数，单数是 alumnus（男）/ alumna（女）。\",\"reunion\":\"来自法语 réunion：re-（再）+ union「合一」，union 的根是拉丁语 unus「一」。同学聚会的词源是「再合为一」；unit（单元）、universe（合而为一的万物）同族——散开的人重新凑成「一」，就是 reunion。\",\"orientation\":\"orient（方向；东方）+ -ation：orient 来自拉丁语 oriens「升起的（太阳）、东方」，动词 oriri「升起」。迎新的词源动作是「找准东方」——古人建教堂要朝东定方位，新生入校要先「定向」；origin（起源）同根 oriri，都是「升起、开端」。\",\"recommendation\":\"recommend（推荐）+ -ation：recommend 来自中世纪拉丁语 recommendare：re-（再）+ commendare「托付、称许」，commendare 是 com- + mandare「交付」（manus 手 + dare 给）。推荐信就是把人「交到」收信人手上并附言称许——一封信，一次交付。\",\"reference\":\"refer（转交、提及）+ -ence：refer 来自拉丁语 referre：re-（带回）+ ferre「携带」。推荐人是「可以回头去问的人」——雇主顺着信「带回」到他那里核实；reference 还兼任「参考、参考文献」，都是「回头查」的动作。\",\"interview\":\"来自法语 entrevue「会面」，动词 entrevoir：entre-（之间）+ voir「看」（拉丁语 videre）。面试的字面是「两个人互相看见」——inter- 的「之间」落在目光上；view（景色；观点）是 voir 的英语亲戚，先见面，后判断。\",\"internship\":\"intern（实习生；住院实习医生）+ -ship（身份、时期）：intern 来自拉丁语 internus「内部的」——住院医师原要「住在医院内部」。实习的词源带着「入住」的画面：先住进去，再学出来；internal（内部的）同根。\",\"apprenticeship\":\"apprentice（学徒）+ -ship：apprentice 经古法语 aprentiz，源头是拉丁语 apprehendere「抓住、领会」（ad- + prehendere 抓）。学徒就是「抓得住手艺的人」——先抓工具，后抓要领；comprehend（理解）同根，理解也是「抓全」。\",\"vocational\":\"vocation（职业、天职）+ -al：vocation 来自拉丁语 vocatio「召唤」，动词 vocare「呼唤」，根是 vox「声音」。职业的词源带着「被召唤」的庄重感——天职感；vocal（声音的）、vocabulary（词汇，说出的词）同根 vox。\",\"technical\":\"来自拉丁语 technicus，源头希腊语 tekhnē「技艺、手艺、本领」。技术的词源不分高低贵贱：木匠的榫卯和程序员的算法，在 tekhnē 眼里都是「手艺」；technique（技巧）同根，technology 是 tekhnē + logos 的后代。\",\"commerce\":\"来自拉丁语 commercium：com-（共同）+ merx「货物、商品」。商业的字面是「货来货往」；merx 家族：market（市场）、merchant（商人）、mercy 无关别混——mercy 出自 merces（报偿）是另一支，但同属「交易场」的气息可以想见。\",\"manufacturing\":\"manufacture（制造）+ -ing：manufacture 来自拉丁语 manufactura：manu（用手，manus 的形式）+ factura「制作」（facere 做）。制造业的词源带着反讽：本义「手工制作」，偏被用来命名机器大生产——手退场了，词留了下来。\",\"service\":\"经古法语 servise，来自拉丁语 servitium「服侍、差役」，词根 servus 是「仆人、奴隶」。服务业的词源起点不高：从「侍奉人」到「第三产业」，servus 的子孙完成了英语里最大的职业翻身之一；serve（服务；上菜）是它的动词面。\",\"retail\":\"经古法语 retaille「切下的一块、零头」，动词 retailler：re- + tailler「切」。零售就是把整批货「切小了卖」；tailor（裁缝）同根 tailler——裁缝切布，零售切货，都是「切」字当头。它与 wholesale 正好是一整一零的对子。\",\"wholesale\":\"whole（整）+ sale（出售）的英语复合词，15 世纪出现，指「成批整卖」。它和 retail 构成英语商业最古老的一对反义构词：一个卖整、一个卖零。sale 来自古诺尔斯语 sala，与 sell 同族——买卖的词根在北方。\",\"producer\":\"produce（生产）+ -er：produce 来自拉丁语 producere：pro-（向前）+ ducere「引导」，字面「领出来、带向前」。生产者是把产品「带到世间」的人；produce 还兼任「农产品」——被带出土地的东西，正好是菜市场那一摊。\",\"supplier\":\"supply（供应）+ -er：supply 经古法语，来自拉丁语 supplere：sub-（从下）+ plere「填满」——「从下面补满、补齐」。供应商是把库存「补满」的人；plere 家族：complete（填全的）、plenty（充满而多）、supply 与 supplement（补充剂）一脉。\",\"distributor\":\"distribute（分发）+ -or：distribute 来自拉丁语 distribuere：dis-（分开）+ tribuere「分配、授予」，tribuere 的根是 tribus「部落」——古罗马按部落「分东西」。分销商就是现代部落分配人，把货分到各家门店。\",\"customer\":\"custom（习惯；关税）+ -er：custom 经古法语 costume，来自拉丁语 consuetudo「习惯、惯例」。顾客是「习惯性光顾的人」——常客才叫 customer；商店门口的 customs（海关）同词：过关的「惯例」要缴税。一次性买卖，不配叫 custom。\",\"client\":\"来自拉丁语 cliens「门客、被庇护者」——古罗马平民依附贵族庇护人（patronus）求保护。主流说法把它联系到「倚靠、倾听从命」一系。客户的词源带着依附关系：从罗马的门客，到现代的甲方，client 始终是「有所求于专业者」的一方。\",\"demand\":\"经古法语 demander「要求、询问」，来自拉丁语 demandare：de- + mandare「托付、命令」（manus 手 + dare 给）。需求在词源里带着「理直气壮地要」：法语的 demander 只是「问、请求」，英语把它加压成了带命令味的 demand。\",\"shortage\":\"short（短、少）+ -age（状态、总量后缀），19 世纪美国英语的造词。短缺的词源不绕弯：不够长、不够量；short 本是古英语 sceort，日耳曼语固有词——用最本土的词，说物资最紧缺的事。\",\"scarcity\":\"scarce（稀缺的）+ -ity：scarce 经古诺曼法语 escars，主流说法上溯通俗拉丁语 excarpsus，源于拉丁语 excerpere「摘取、抽出」——东西被「摘得所剩无几」，就是稀缺。此远源属通说而非定论，标注在此；scarce 本身经法语进入英语则无异议。\",\"price\":\"经古法语 pris，来自拉丁语 pretium「价值、价钱、报偿」。price 与 praise（赞扬）是同源双生词：一个给物「定价」，一个给人「估值」——古人眼里，标价和夸奖是同一种动作：说出它值多少。\",\"cost\":\"经古法语 coster，来自拉丁语 constare：con- + stare「站立」，字面「站稳、定格于（某数目）」——价格「站」在那里，就是成本。stare 家族：state（状态；国家，站定的局势）、stable（稳定的）、statue（站着的像）。\",\"debt\":\"经古法语 dete，来自拉丁语 debitum「欠下的东西」，动词 debere「欠」由 de- + habere「持有」构成——欠债就是「拿着别人的东西」。拼写里的 b 是文艺复兴学者按拉丁语「复原」的，不发音，与 doubt 的 b 同一种命运。\",\"loan\":\"来自古诺尔斯语 lán「借出的东西」，日耳曼语固有词，古英语作 læn，与 lend（借出）同族，德语 Lehen（采邑）是远亲。贷款的词源朴素得只剩动作：东西暂时过户，到期须还——维京人带来的金融词，比银行还老。\",\"interest\":\"来自拉丁语 interesse：inter-（之间）+ esse「存在」，本义「介于其间、事关重大」。金融义成形于中世纪拉丁语：借贷中「差额、损失的补偿」叫 interesse——利息原是「占用他人钱财所付的代价」，与「重要」义同词不是巧合：钱的事，关乎重大。\",\"dividend\":\"来自拉丁语 dividendum「待分配的东西」，动词 dividere 是「分开、分配」。股息就是利润中「该分下去的那一份」；divide（划分）同根。股东大会说到底是个分账场面，dividendum 是罗马人留下的分账单。\",\"stock\":\"古英语 stocc「树干、木桩、原木」，日耳曼语固有词。股票的词源路径是：树干 → 储备、存货（树干般的主干存量）→ 资本金 → 股份。公司的「本」像树干，股份是从主干上分出的份额；livestock（牲畜）里的 stock 还是「存量」本义。\",\"share\":\"古英语 scearu「份额、分割」，与 sceran「剪切」（shear）同源——股份是整块东西上「剪下来的一份」。share 与 shear 在词源里是一把剪刀的两面：剪的动作叫 shear，剪下的部分叫 share；分享（share 快乐）也是把整份切开来分。\",\"bond\":\"bond 是 band 的变体，来自古诺尔斯语 band「捆索、束缚」。债券就是一张「把发行方绑住」的契据——到期必须还钱，绑得死死的；bandage（绷带）、husband（丈夫，绑进家的人）同族，金融与婚姻共用一根绳。\",\"profit\":\"经古法语 profit，来自拉丁语 profectus「进展、成就」，动词 proficere：pro-（向前）+ facere「做」——「做出了向前的一步」就是得利。利润的词源带着积极味：不是守财，是进取的余量；proficient（熟练的）同根。\",\"loss\":\"古英语 los「毁损、丧失、灭亡」，日耳曼语固有词，与 lose（丢失）、loose（松开）同族。亏损在词源里是「握不住、漏掉了」：钱从手里 los 出去，就是 loss。forlorn（孤苦的）里的 -lorn 也是这个「失落」的古词根。\",\"abdomen\":\"来自拉丁语 abdomen「腹部」，经法语进入英语。拉丁人自己也没完全搞清它的来历，一说与 abdere「藏起来」有关——腹部是把内脏「藏起来」的地方；这个词源在学界仍属推测，不要当成定论记。\",\"ability\":\"来自拉丁语 habilis「便于拿握的、灵巧的」（动词 habere「有、持有」），经古法语 able 进入英语。先指「拿得起、做得来」，再抽象成「能力」；它和 habit（习惯）同出一个「有」的老祖宗。\",\"abnormality\":\"ab-「离开」+ normal「正常的」+ -ity。normal 的老家是拉丁语 norma「木工的直角尺」：合乎尺子的是正常，偏离尺子的就是 abnormal——异常的本质是「离了规矩」。\",\"abolish\":\"来自拉丁语 abolere「使消亡、废除」，由 ab-「离开」+ olescere「生长」拼成，字面竟是「让它不再生长」。一个制度被 abolish，就是被连根断了生机。\",\"absurdity\":\"来自拉丁语 absurdus「刺耳的、不合调的」：ab-「偏离」+ surdus「聋的、闷声的」。本义是声音聋闷不和谐，后来转指道理上「听不下去」——荒谬就是理智上的不入耳。\",\"abuse\":\"来自拉丁语 abuti「用尽、用坏」：ab-「离开正轨」+ uti「使用」。把东西用到脱轨、用过头，就是滥用；它和 use 是同一个词根的正反面。\",\"abyss\":\"来自希腊语 abyssos「无底的」：a-「没有」+ byssos「深底」。深渊就是探不到底的深；圣经希腊译本里拿它指幽冥深处，词义从此带上黑暗色彩。\",\"academy\":\"来自希腊语 Akadēmeia——雅典城外一片纪念英雄 Akademos 的橄榄林，柏拉图在那里讲学，他这一派就叫 Academy。地名变成「学园」的通称，再转指科学院、专业院校。\",\"accent\":\"来自拉丁语 accentus「唱着添上去的调子」：ad-「添上」+ cantus「歌唱」（canere 唱）。古人觉得重音是给话音「配的歌」，后来才兼指口音和符号本身。\",\"accept\":\"来自拉丁语 acceptare「接过来、收下」：ad-「向」+ capere「抓、取」。手伸出去把东西取到自己这边，就是接受；它和 capture（捕获）是同一个「抓」字家族。\",\"acceptance\":\"accept 的名词形。accept 自拉丁 acceptare「接过来」：ad-「向」+ capere「抓、取」——把递来的东西接进手里，接纳、验收、认可都从这个动作长出来。\",\"access\":\"来自拉丁语 accessus「走近、通道」：ad-「向」+ cedere「走」。字面是「走得过去的那条路」，所以 access 先是通道、入口，后来才有「访问权限」的新义。\",\"accident\":\"来自拉丁语 accidere「恰好落到、发生」：ad-「向」+ cadere「落下」。事情像从天而降「落」在你头上，事先无从预料——意外就是这样落下来的事件。\",\"accommodation\":\"来自拉丁语 accommodare「使合身、调整合适」：ad- + commodus「合宜的」（modus 是尺度）。先是「调到合适」，住处是「调好给你住的地方」，才引申为住宿、膳宿。\",\"accompaniment\":\"accompany 的名词形。accompany 的核心是古法语 compaignon「同伴」——com-「一起」+ panis「面包」：同伴就是分吃同一块面包的人。伴奏就是陪主旋律「吃同一块面包」。\",\"accompany\":\"经古法语陪伴义进入英语，核心词是 companion「同伴」：拉丁语 com-「一起」+ panis「面包」。古人认交情的方式很实在——能坐下分食同一块面包的人，才叫同伴；陪伴、伴奏都由此而来。\",\"accomplish\":\"来自拉丁语 complere「填满、完成」的法语后代：com-「完全」+ plere「填」。把事情做到满格、不留空缺，就是 accomplish——完成本质上是「填满」。\",\"accord\":\"来自拉丁语 accordare「使心心相印」：ad-「向」+ cor/cord-「心」。两颗心走到一起就是协议、一致；它和 heart 的远亲 cordial（衷心的）同源。\",\"accountability\":\"account 出自拉丁语 computare「清点、计算」：com- + putare「清点」。账目先要算得清，accountability 问责就是要求你把账「说得清」——责任的底子是清算。\",\"accuracy\":\"来自拉丁语 accuratus「精心做成的」：ad- + cura「照料、用心」。注意这里的 cur 是 curare「照料」，和 current 里 currere「跑」的 curr 只是长得像，并非一家人。准确 = 用心照料到细节。\",\"accusation\":\"来自拉丁语 accusare「传唤到庭、指控」：ad- + causa「案由、诉讼」。字面是「把人叫来对案由」，指控从来就是法律动作；cause（原因）正是同一词的另一面。\",\"accuse\":\"来自拉丁语 accusare「传唤、控告」：ad- + causa「案由」。把人「按着案由」叫上法庭，就是 accuse；excuse「辩解」是把它反过来说：把案由从身上卸掉。\",\"achievement\":\"achieve 源于古法语短语 venir à chef「做到头、干到底」：chef 是「头」（拉丁语 caput）。把事情一路干到「头」，就是达成；chief（首领）也是同一个「头」。\",\"acquaintance\":\"acquaint 源于拉丁语 accognoscere「使知道」：ad- + cognoscere「认识」（co- + gnoscere 知道）。「使彼此知道」就是结识；熟人就是那个已经「知道」了的人。\",\"acre\":\"古英语 æcer「田地」，与拉丁语 ager「田地」同源（agriculture 的 agr- 就是它）。英亩最初的定义很朴素：一队牛一天能耕完的地。度量衡里藏着农耕时代的体力账。\",\"acrobat\":\"来自希腊语 akrobatos「在高处行走的人」：akros「最高、尖」+ bainein「行走」。走钢丝的人正是「在高处走」；acropolis（卫城）里的 acro- 也是这个「高」。\",\"act\":\"来自拉丁语 actus / agere「做、驱动」。agere 的词干 act- 给了英语一串词：act 做、action 行动、actor 做事（演戏）的人；agenda（议程）是它「要做的事」清单。\",\"action\":\"来自拉丁语 actio「行动、诉讼」，出自 agere「做、驱动」的词干 act-。先是泛指「做」，罗马法里 actio 还指一场诉讼——行动与打官司，在拉丁人那里共用一词。\",\"activist\":\"active 出自拉丁 agere「做、驱动」的词干 act-，加 -ist「…的人」。activist 就是不满足于想、而要「做」出改变的人——词尾决定立场，词干决定动作。\",\"activity\":\"active 的名词形，根子还是拉丁语 agere「做、驱动」的词干 act-。「做」得持续不断、成为常态，就是 activity——活动量本质上是动作量。\",\"actor\":\"来自拉丁语 actor「做事者、原告、演员」，出自 agere「做」。古罗马的 actor 先是「行动者、告人者」，再专指台上「扮演」的人——演戏在词源里就是做事。\",\"actress\":\"actor 加上法语阴性后缀 -ess。actor 本出拉丁语 agere「做」的词干 act-；-ess 这一层是近代英语给职业女性单加的标记，如今 actress 一词本身也渐渐少用。\",\"actuality\":\"actual 源于晚期拉丁语 actualis「实际的」，仍是 agere「做」的词干 act-。actual 原义「在行动中的、正在做的」，与「假设的」相对——现实性就是「真的做了」的那一面。\",\"adaptability\":\"adapt 来自拉丁语 adaptare「使合身」：ad-「向」+ aptare「使适合」（aptus 合适的）。把自己「调到合身」，就是 adapt；适应力就是反复调合身的能力。apt（恰当的）是它不带前缀的老乡。\",\"addict\":\"来自拉丁语 addictus「被判交出去的（人）」：ad- + dicere「说」。罗马法里 addictus 是法官一句话就「说」给债主抵债的人——被判给某物、身不由己，正是成瘾的字面写照。\",\"addition\":\"来自拉丁语 addere「加上」：ad-「向」+ dare「给予」。把一份再「给」上去，就是加法；date（日期）里的 dat- 也是 dare「给」的词干，远亲关系藏在词形里。\",\"address\":\"经古法语 adresser 进入英语，源头是拉丁语 directus「拉直、朝向」：ad- + regere 的词干。先是「把话朝向某人」，才有地址（话朝向的地方）和「处理（问题）」——它和 direct 是同根亲戚。\",\"adequacy\":\"adequate 源于拉丁语 adaequare「使相等」：ad- + aequus「平等的」。量给到「刚刚平齐」就是充足——不多不少，与要求拉平。\",\"adequate\":\"来自拉丁语 adaequare「使相等」：ad- + aequus「相等」。adequate 不夸「多」，只夸「齐」：与需要恰好拉平，就是充足；equal（相等）是同一词根的直系。\",\"adhere\":\"来自拉丁语 adhaerere「粘着」：ad-「向」+ haerere「粘、卡住」。紧紧贴住不松口，既是黏附，也是「坚持（原则）」——两种黏，同一动作。\",\"adjacency\":\"源于拉丁语 adjacens「躺在附近的」：ad- + jacere「躺、卧」。邻近的字面图景是两个东西「挨着躺在一起」；adjacent 与其同形，词根 jac- 不是 throw 义的 ject，别混淆。\",\"adjustment\":\"adjust 经法语 ajuster 进入英语，根子在拉丁语 justus「正当、合尺」：把东西「拨到正」就是调整。just（公正、恰好）是它同根的老牌词。\",\"administer\":\"来自拉丁语 administrare「服侍、管理」：ad- + ministrare，而 minister 本义是「仆人、下属」（源于 minus「较小的」）。管理在词源里先是「伺候、办事」，权力色彩是后加的。\",\"admirable\":\"admire 的形容词形。admire 源于拉丁语 admirari「惊奇、钦佩」：ad- + mirari「惊叹」。值得钦佩，先要值得「看得发愣」；miracle（奇迹）是同一 mir- 的亲戚。\",\"admiration\":\"admire 的名词形，源头是拉丁语 admirari「惊奇」：mir- 是「惊叹」。钦佩的底色是惊奇——先被震到，才有敬意；与 miracle、mirage 同根。\",\"admire\":\"来自拉丁语 admirari「惊叹、钦佩」：ad- + mirari「感到惊奇」。词源里钦佩不是评判，而是「看呆了」；mirror 的 mir- 是「看」，mirari 的 mir- 是「惊奇」，相近而不同源，别串门。\",\"admit\":\"来自拉丁语 admittere「放进来、准许进入」：ad-「向里」+ mittere「送、放」。门把人「送」进来，既是承认入场，也是 admit 错误——把事实也放进门来。\",\"adolescent\":\"来自拉丁语 adolescens「正在长大的（人）」：ad- + alescere「生长」（alere 滋养）。青春期就是「长」的进行时；adult（成年人）是同一动词的完成分词——一个正在长，一个长成了。\",\"adoption\":\"来自拉丁语 adoptare「选作己子」：ad- + optare「挑选、愿望」。收养在词源里是一次郑重的「选择」；option（选项）、opt（选择）都是这个 opt-。\",\"advance\":\"来自古法语 avancier，源头是拉丁语 abante「在…之前」：ab- + ante「在前」。往前到别人之前，就是推进；注意拼写的 d 是后来按拉丁 ad- 模样添的，原词并无 d 的读音根据。\",\"advantage\":\"来自古法语 avantage，出自 avant「在前」（拉丁语 abante）。站到前面去，就有了 advantage——优势的本义就是「位置靠前」；与 advance 同族。\",\"adventure\":\"来自拉丁语 adventura「将要发生的事」：ad- + venire「来」。等着它「来」到的事，吉凶未卜——冒险就是迎接未知的到来；与 advent（降临）同根。\",\"adverse\":\"来自拉丁语 adversus「转过脸相对的」：ad- + versus「转」（vertere 转）。迎面转过来对着你的，就是不利的、相反的；与 versus（对抗）同一词形出身。\",\"advertiser\":\"advertise 的派生词，advertise 出自拉丁语 advertere「把（注意力）转向」：ad- + vertere「转」。广告的全部手艺在词源里就一句：把人的目光「转」过来；advertiser 是专做这件事的人。\",\"advertising\":\"advertise 的名词形，根子是拉丁语 vertere「转」：广告就是「把注意力转过来」的行业。注意 advert 本义是「留意、提及」，叫卖义是后来在商业里长出来的。\",\"advice\":\"来自古法语 avis「意见」，源头是拉丁语短语 ad visum「依所见」：vis- 是「看」（videre）。建议的字面是「把我看到的告诉你」；advise、advisor 里的 vis- 都是这个「看」。\",\"advisor\":\"advise 出自拉丁语 ad visum「依所见」的法语后代，vis- 是 videre「看」。顾问就是那个「看得更清楚、再告诉你」的人；与 advice 同根，拼写的 s/z 之分是英美习惯。\",\"advocacy\":\"advocate 来自拉丁语 advocatus「被叫来（助辩）的人」：ad- + vocare「呼唤」（vox 声音）。律师在罗马是被「喊来发声」的人；倡导 advocacy 就是替某个立场把声音喊出来。\",\"aerial\":\"来自拉丁语 aerius「空气的」，根子是希腊语 aēr「空气」。aerial 是天线时，指它伸向空中的样子；作「空中的」解时更贴词源本义。radio 普及前，这个词先属鸟和风。\",\"aerobics\":\"1968 年由美国军医 Kenneth Cooper 推广的造词：aero-「空气、氧」+ -bics（仿 gymnastics 的词尾）。aerobic 本是生物学词「需氧的」，挪来给运动命名，氧气从此成了健身的招牌。\",\"aesthetic\":\"来自希腊语 aisthētikos「能感知的」，源头 aisthanesthai「感觉、知觉」。美学原是「感觉之学」——研究人如何感知，远晚于哲学才专指美丑；anaesthetic（麻醉）是它的反面：使感觉消失。\",\"affair\":\"来自古法语 afaire，即 à faire「要办的事」：faire 是「做」（拉丁语 facere）。事务的字面就是「待做的事」；英语 affair 的暧昧义（私情）是从「要事」里偷跑出来的旁支。\",\"affection\":\"来自拉丁语 affectio「心境、被触动的状态」，出自 afficere「作用于、感动」：ad- + facere「做」。情感在词源里是「被外界做了点什么」后心里留下的状态。\",\"affiliation\":\"affiliate 源于中世纪拉丁语 affiliari「认作儿子」：ad- + filius「儿子」。机构之间谈 affiliation，如同认亲——总机构把分支「收作自家孩子」；filial（子女的）同根。\",\"affinity\":\"来自拉丁语 affinitas「姻亲关系」：ad- + finis「边界」。两家地界挨着、再结成亲家，就是 affinity；亲和力是从「边界相接」长出来的比喻，化学里的亲和也借此说。\",\"affirm\":\"来自拉丁语 affirmare「使坚定、确认」：ad- + firmare「使牢固」（firmus 坚固的）。肯定一件事，就是把话「钉牢」；firm（坚定的、公司）是它没穿前缀的本家。\",\"affirmation\":\"affirm 的名词形。affirm 出自拉丁语 affirmare「钉牢、确认」，firm- 是「坚固」——肯定，就是把主张钉在坚固处不让它晃。\",\"affluent\":\"来自拉丁语 affluens「涌流向」：ad- + fluere「流」。财富像水一样涌进来，就是富裕；influence（影响）也是这条「流」——一个流进钱包，一个流进人心。\",\"afford\":\"源于古英语 geforðian「促成、供给」，forð 是「向前」（forth 的亲戚）。afford 先是「拿得出、办得到」，金钱义是近代才定型的；别被 a- 骗去找拉丁词根，它是地道的日耳曼词。\",\"affordability\":\"afford 的名词形。afford 是古英语词「促成、拿得出」（forð 向前），affordability 把它名词化，专说「钱拿不拿得出」这一件事。\",\"agent\":\"来自拉丁语 agens「做事者」，出自 agere「做、驱动」。agent 是「被派去做事的人」，本质是动作的执行端；agenda、agile、agitate 全是这个 ag- 的后代。\",\"aggravate\":\"来自拉丁语 aggravare「使加重」：ad- + gravis「重的」。病情加重是往秤上再加砝码；口语里「惹恼」的义是后起的，词源只认「重」这一个理。gravity（重力）同根。\",\"aggressive\":\"来自拉丁语 aggredi「走上前去（攻击）」：ad- + gradi「行走」（gradus 步）。好斗者的姿态在词源里是「迈步逼近」；progress 的 gress 也是走，这一家靠脚程分胜负。\",\"agile\":\"来自拉丁语 agilis「灵便的」，出自 agere「做、驱动」。做得快、转得灵，就是 agile；它与 agent 同根，一个强调「做」，一个强调「做得麻利」。\",\"agility\":\"agile 的名词形，根子是拉丁语 agere「做、驱动」。敏捷在词源里不是腿脚快，而是「驱动自己时阻力小」——agility 说到底是动作的流畅度。\",\"aging\":\"age 来自拉丁语 aetas「一生、年代」的法语后代 âge。age 本是「走过的岁月」总量，aging 是这笔岁月继续累积的过程；注意它不是词根 ag-（做）那一家，只是拼写撞脸。\",\"agitate\":\"来自拉丁语 agitare「反复驱动、摇动」，是 agere「做、驱动」的反复体。把液体来回「驱赶」就是搅动，把人心来回驱动，就是煽动、焦虑——同一动作，两处现场。\",\"agree\":\"来自古法语 agréer，源头是拉丁语 ad gratum「合（某人）的心意」：gratus「令人愉快的」。同意的字面是「觉得合意」；agreeable（宜人的）还留着 grat- 的原味。\",\"agreeable\":\"agree 加 -able。agree 的根是拉丁语 gratus「合意的」：觉得合意所以同意（agree），本身合意所以宜人（agreeable）——一个词根管了态度和气质两头。\",\"agreement\":\"agree 的名词形，根子仍是拉丁语 gratus「合意」。agreement 不是纸面文件先行，而是「心意对上了」在先，文件在后——词源的顺序别记反。\",\"aid\":\"经古法语 aidier 进入英语，源头是拉丁语 adjuvare「帮助」：ad- + juvare「助、使高兴」。援助在词源里带着善意：adjutant（副官）是它在军营里的亲戚，coadjutor（助理主教）也是。\",\"ailment\":\"ail 是古英语 eglan「折磨、使难受」，日耳曼本族词，源头细节不甚明朗。ailment 加了 -ment 才成名词；词源的诚实标注是：老词，病痛义，确切来历存疑。\",\"aim\":\"经古法语 esmer 进入英语，源头是拉丁语 aestimare「估量」。瞄准先要「估量」距离与方向——aim 与 estimate（估计）竟是同一个词的两条命：一个估数，一个瞄靶。\",\"aircraft\":\"air + craft 的复合词。craft 是古英语 cræft「力量、技艺」，先指手艺、再指船（craft 也可单指船只），才轮到飞行器；aircraft 是「空中的 craft」，单复数同形也是它的小脾气。\",\"airline\":\"air + line 的复合。line 在这里是「航线、公司」的 line——19 世纪航运公司先叫 line（班轮线），航空公司沿用了这个说法：先有海上的线，后有天上的线。\",\"aisle\":\"经法语 aile 进入英语，源头是拉丁语 ala「翅膀」：教堂侧廊像主殿伸出的「翼」。拼写里的 s 是 18 世纪受 isle（岛）牵连添的，不发音——一封写给 island 的「假亲戚信」。\",\"alarm\":\"来自意大利语号令 all'arme!「拿起武器！」（alle arme）。战场上的这声喊先变成警报，再变成闹钟——每天叫醒你的，是五百年前哨兵嗓子里的备战令。\",\"album\":\"来自拉丁语 album「白色；白版」，是 albus「白」的名词形。古罗马把告示写在刷白的木板上，album 先是「留言白板」，再是相册、专辑——收集页的底色本是白。\",\"alcohol\":\"来自阿拉伯语 al-kuḥl：al- 是定冠词，kuḥl 原指锑粉眼影。炼金术士把它转指「蒸馏出的精华粉末」，再转指酒中精华——酒精一词的履历从化妆品柜台开始。\",\"alert\":\"来自意大利语 all'erta「上瞭望塔（戒备）」：erta 是「陡坡、高地」。警觉的字面姿势是「爬上高处守望」；它与 alarm 同为意大利军事口令出身，进了英语后各管一摊。\",\"alertness\":\"alert 的名词形。alert 出自意大利语 all'erta「上高地戒备」——警觉性，词源上就是「在高处守望的持续状态」。\",\"alien\":\"来自拉丁语 alienus「属于别人的、外国的」，源头 alius「其他的」。外星人、外人、异乡人共用一个词：alien 的判据从来都是「不是我们这边的」。\",\"alienate\":\"alien（外来的）加动词尾。把自己人变成「别人」，就是 alienate——疏远在词源里是一次身份改判；alien 本是拉丁语 alius「其他」。\",\"align\":\"经法语 aligner 进入英语：à ligne「排成线」，ligne 来自拉丁语 linea「线」（linum 亚麻线）。对齐就是「把东西拽回线」；line 本人就是这条线的源头词。\",\"alignment\":\"align 的名词形。align 的 ligne 是拉丁语 linea「线」：alignment 是把散点收回同一条线的状态，工程图纸和政党立场共用这一条线。\",\"alike\":\"古英语 gelīc / 古诺尔斯语 álíkr 的后代：a- + like「相像」。like 的老家是日耳曼语「形体、模样」；alike 是本族词，不必去拉丁词库里找它的亲戚。\",\"alimony\":\"来自拉丁语 alimonia「养分、给养」，出自动词 alere「滋养」。赡养费的字面是「养活对方的口粮钱」，al- 是「养」不是「其他」；alimentary（食物的、营养的）是直系亲属。\",\"alive\":\"古英语 on līfe「在生命里」缩合而成：a- 是 on 的弱化，live 是「生命」。活着的字面就是「正泡在生命状态里」；纯粹的日耳曼老词，无拉丁背景。\",\"allegation\":\"allege 来自拉丁语 allegare「派去、提出、宣称」：ad- + legare「派遣」。到庭上「把说法派出来」，就是指控性主张；alleged 因此永远带着「据称、尚未坐实」的保留味，新闻写作最看重这一点。\",\"alleged\":\"allege 的分词形，源于拉丁语 allegare「提出、宣称」（legare 派遣）。alleged 作定语时是法律护身符：写「the alleged thief」等于声明这人只是被指控，未经定罪。\",\"allergic\":\"allergy 是 1906 年奥地利医生 von Pirquet 造的词：希腊语 allos「其他的」+ ergon「作用、反应」。身体对寻常物质「反应过头、反应错位」，就是过敏——20 世纪才定名，托福听力医学讲座高频出现。\",\"alley\":\"来自古法语 alee「走道」，是 aller「走」的名词形。小巷就是「人走出来的窄路」；与法语 aller 的确切源头学界尚有讨论，但「走道」义从中世纪一路未变。\",\"alliance\":\"ally 出自拉丁语 alligare「绑在一起」：ad- + ligare「绑」。同盟就是被绳子绑在同一条船上的人；ligament（韧带）是身体里那根真正的「绑带」。\",\"allocation\":\"allocate 源于中世纪拉丁语 allocare「放到位」：ad- + locare「放置」（locus 地方）。分配就是把资源一件件「放到该放的位置」；location（地点）是它的同胞。\",\"allotment\":\"allot 经古法语 aloter 分：à + lot「份额」。lot 本是抽签用的签筹，后指「分到的那一份」：分配额是把份额一份份发下去的结果，与 lottery 同源。\",\"allowance\":\"allow 身世复杂：一支是古法语 alouer「放置、分配」（拉丁语 allocare），一支是 alouer「赞许」（拉丁语 allaudare）。津贴走的是「分配」那一支：被拨出来准你支用的那一份。\",\"ally\":\"来自拉丁语 alligare「绑在一起」：ad- + ligare「绑」。盟友就是与你「同绑」的国家或人；动词、名词同形，词源里绑的动作始终没解开。\",\"almond\":\"经古法语 amande 进入英语，源头是希腊语 amygdalē「杏仁」，拉丁作 amygdala。中世纪拼写添了个 l（受阿拉伯定冠词 al- 牵连的说法很多）——杏仁的 l 不发音，正是这段借词史留下的疤。\",\"aloof\":\"源于荷兰语航海词 loef「迎风舷侧」，a- 是「向、朝」：船要保持距离「向迎风侧偏」。疏远感是从船员的避让动作里漂来的；进入英语后先形容船，再形容人。\",\"alpaca\":\"经西班牙语 alpaca 进入英语，源头是南美艾马拉语 allpaqa。羊驼连名字都是跟着西班牙殖民者从安第斯山下来的——借词的路线，就是殖民与贸易的路线。\",\"alphabet\":\"来自希腊语 alphabētos，就是排头两个字母 alpha + beta 拼成的词。字母表以头两位成员命名自己；alphabet 的希腊源头再往前，是腓尼基字母的 aleph（牛）与 beth（房屋）。\",\"altar\":\"来自拉丁语 altare「祭台」，一般认为与 altus「高」有关：祭台是架高了的台子。altar 的「高」和 altitude（高度）的 alt- 是同一家；婚礼、献祭都在这张高台上办。\",\"alteration\":\"alter 是拉丁语 alter「另一个（两者中的另一个）」。alteration 是把事物往「另一个样子」推一下：改动不大时用它，大变身轮不到它；alternate（交替）是让两个「另一个」轮流上场。\",\"alternate\":\"来自拉丁语 alternus「轮流的」，出自 alter「另一个」。交替就是让 A、B 两位「另一个」你来我往；注意它和 altar（祭坛）只是长得像，毫无亲缘。\",\"altruistic\":\"altruism 是 19 世纪法国哲学家孔德造的词，取自法语 autrui「他人」（源于拉丁语 alter「另一个」）。利他主义先在法语里出生，词干却仍是拉丁的「另一个人」：为他人，即为「另一个」。\",\"amalgamate\":\"amalgam（汞合金）出自中世纪拉丁语 amalgama，一般上溯希腊语 malagma「软膏、使软之物」（malassein 揉软）。汞能把金属「揉软合并」，amalgamate 就成了合并的通称；中间路线经阿拉伯炼金文献的说法也存在，细节有争议。\",\"amass\":\"经古法语 amasser 进入英语：à + masse「团块」，masse 的源头是拉丁语 massa「面团、块」。积聚就是把零散东西「堆成一团」；mass（大量、弥撒）与它同根两路，别混。\",\"amaze\":\"源于古英语 āmasian「使困惑、使失神」，核心是 maze「迷宫」。amaze 的老图景是「把人引进迷宫」：惊奇感里有三分是迷路；amazing 好到「让人失神」，也是这个理。\",\"amazement\":\"amaze 的名词形。amaze 的根在古英语 maze「迷宫」：amazement 是站在迷宫正中央那种又惊又懵的状态，惊叹号里藏着一面墙。\",\"ambassador\":\"经法语 ambassadeur 进入英语，一般上溯拉丁语 ambactus「仆从、随员」（凯尔特语源）。大使的字面履历是「被派出去伺候差事的人」——先跑腿，后代表。意大利语 ambasciatore 一支也有影响，细节学界有讨论。\",\"ambiguity\":\"ambiguous 来自拉丁语 ambiguus「两可的、在两边游移的」：ambi-「两边」+ agere「驱动」。词义像被往两边同时「驱赶」，定不下来，才有歧义；它和 current 一样藏着「动」词根，但藏的是 agere 的 ag。\",\"ambition\":\"来自拉丁语 ambitio「四处走动（拉票）」：ambi-「四处」+ ire「走」。罗马候选人绕着广场挨个握手求票，这个动作就叫 ambitio——雄心先是一种到处奔走的姿态。\",\"ambulance\":\"来自法语 hôpital ambulant「流动医院」：拉丁语 ambulare「行走」。拿破仑战争里能跟着部队「走」的医院，后来缩到那辆车上；ambul- 是「走」，和 ambush 的 bosc 无关。\",\"ambush\":\"来自古法语 embuscher「埋伏进树林」：en-「进入」+ bosc「灌木、树林」（日耳曼借词，bush 的亲戚）。伏击的字面现场是钻进林子猫着；amb- 在这里不是「两边」，别按拉丁 ambi- 硬拆。\",\"amendment\":\"amend 出自拉丁语 emendare「去错、改正」：e-「出」+ menda「瑕疵、错误」。修正案是把文件里的「瑕疵」挑出来改掉；mend（修补）正是 amend 脱了帽子的短形。\",\"amenity\":\"来自拉丁语 amoenitas「宜人、舒适」，源头 amoenus「令人愉悦的」。amenity 先是地方的宜人气质，现代才具体化为便利设施——从「住着舒服」到「设施齐全」，词义一步步落地。\",\"amount\":\"经古法语 amonter「累加至」，源头是拉丁语短语 ad montem「向山上」：mons「山」。总额是一点点往上「堆成山」的数；mount（山）就是词里那座山，如今只在词源里还看得见。\",\"ample\":\"来自拉丁语 amplus「宽大的、充裕的」。amplus 的更深层来源不甚明朗，英语里它只管一件事：量大到绰绰有余；ample 与 amplify 同家，后者是把它动词化：使宽大。\",\"amplify\":\"来自拉丁语 amplificare「使宽大」：amplus「宽大」+ facere「做」。放大声音就是把声波「做宽」；-fy 这一截是 facere 的老招牌，与 factory 同一车间出身。\",\"amuse\":\"来自古法语 amuser「使出神、消遣」，核心 muse 意为「愣神、闲逛」。amuse 的老图景是让人「傻站着发会儿呆」——娱乐的起点是走神；与缪斯（Muse）是否同源，学界说法不一，不宜讲死。\",\"amusement\":\"amuse 的名词形。amuse 出自古法语「使出神」：amusement 是把人从正事里勾走的那段时间，游乐场用 amusement park 命名，正是这份「勾人走神」的本事。\",\"amusing\":\"amuse 的形容词形，根在古法语 muse「出神」。amusing 的笑点不在闹，而在「勾人」：能让人不知不觉停下来看的，才最 amusing。\",\"analog\":\"来自希腊语 analogos「按比例的」：ana-「按、依」+ logos「言说、比值」。模拟信号之所以叫 analog，是它以连续的「比例」对应原物；analogy（类比）是同一个「按比例对应」的说法。注意词头是 ana-，不是 ab-。\",\"analyse\":\"英国拼写，美国作 analyze。来自希腊语 analysis「松开、分解」：ana-「往上、彻底」+ lysis「松开」（lyein 解开）。把整体「拆松」来验看，就是分析；-yse/-yze 之争纯属拼写路线，与词源无关。\",\"analyst\":\"analysis（分析）的派生词，根在希腊语 lysis「松开、分解」。analyst 是专门替人「拆开来看」的人；psychoanalyst（精神分析师）是其中最出名的一支。\",\"ancestor\":\"经古法语 ancessour 进入英语，源头是拉丁语 antecessor「走在前面的人」：ante-「在前」+ cedere「走」。祖先就是「先于我们走完这条路的人」；successor（继任者）是同一条路的后半段。\",\"anchor\":\"经拉丁语 ancora 进入英语，源头是希腊语 ankyra「弯钩、锚」，再往前与印欧语根 *ank-「弯」有关。锚的功能全在那个「钩弯」：勾住海底，拴住船；与 angle（角）是弯曲家族的远亲。\",\"ancient\":\"经古法语 ancien 进入英语，源头一般认为是拉丁语 *antianus，出自 ante「在…之前」。ancient 的核心是「在（我们）之前很久」；它和 antique 同出 ante 一门，却不是 anti-「反对」那一家。\",\"anecdote\":\"来自希腊语 anekdota「未发表的东西」：an-「不」+ ekdotos「已交出的、已出版的」。普罗柯比的《秘史》专记宫廷秘闻，死后才刊行——轶事的基因里就带着「没打算发表」。\",\"angel\":\"经拉丁语 angelus 进入英语，源头是希腊语 angelos「信使」。天使在词源里首先是「送信的」：evangel（福音）是 eu-「好」+ angelos「消息」——好消息本身。\",\"angle\":\"来自拉丁语 angulus「角」，与印欧语根 *ank-「弯」有关（anchor 的 ankyra 也是）。角就是线条「弯折」出来的地方；钓鱼义的 angle 是另一条支流，经古英语 angel「鱼钩」而来，同形合流。\",\"angular\":\"angle 加 -ar。angle 源于拉丁语 angulus「角」：angular 形容「有棱角的」，从几何图形借到人脸上——angular 的脸，就是线条转折分明的那种。\",\"animal\":\"来自拉丁语 animal「活物」，源头是 anima「气息、灵魂」。古人给活物的定义很直接：有「气」的就是 animal；animate（使活、动画）同根——动画就是给静物「吹气」。\",\"animate\":\"来自拉丁语 animare「赋予生命」：anima「气息、灵魂」+ 动词尾。使生动就是「注入气息」；动画片里的角色被画师一个个「吹活」，词源一字不差。\",\"animation\":\"animate 的名词形，根子是拉丁语 anima「气息」。animation 一词 20 世纪才被动画行业领走，之前它泛指「生气勃勃」——行业新义盖住了老义，词源还在 anima。\",\"ankle\":\"古英语 anclēow（也作 ancléow），日耳曼本族词，一般认为与 *ank-「弯」一脉有关：踝是腿与脚「打弯」的关节。它与 angle、anchor 属远房，但走的是日耳曼自家路线。\",\"anniversary\":\"来自拉丁语 anniversarius「每年返回的」：annus「年」+ versus「转」（vertere）。周年就是时间「转满一圈回到原点」的日子；annual（每年的）只取了 annus 一半身子。\",\"announce\":\"经古法语 anoncier 进入英语，源头是拉丁语 annuntiare「带信给」：ad- + nuntius「信使」。宣布就是「把信使派出去喊」；词干 nounc- 是 nuntius 的法语面孔。\",\"announcement\":\"announce 加 -ment。announce 的根是拉丁语 nuntius「信使」：公告就是信使喊过的话凝固成的那张纸（或那块屏幕）。\",\"anomaly\":\"来自希腊语 anōmalia「不平整」：an-「不」+ homalos「平整的」（homos 相同的）。异常就是「不合平整面」的那块凸起；注意它的词干是 homal-，不是 nomos「法则」——页面旧拆法把 nom 认错了门。\",\"answer\":\"古英语 andswaru：and-「对着、回」+ swaru「宣誓、郑重之言」（swear 的亲戚）。回答在盎格鲁-撒克逊人那里是「对着问话发一句郑重的话」，answerable（须负责）还留着这份郑重。\",\"antagonist\":\"来自希腊语 antagōnistēs「对抗者」：anti-「相对、对抗」+ agōn「竞赛、斗争」。反派的本职是「站在对面较量的人」；protagonist（主角）是「第一较量者」，两人本是同一赛场的选手。\",\"antagonistic\":\"antagonist 的形容词形，根在希腊语 agōn「竞赛」。敌对感来自赛场：对方的每一次发力，都冲着把你比下去——agōn 还给了英语 agony（剧痛、挣扎）。\",\"antenna\":\"来自拉丁语 antenna（也作 antemna）「船帆的桁木」，确切源头不详，可能是地中海旧词。昆虫的触角和收音机的天线，都是借这根「横在高处的杆子」命名——先航海，后生物，再无线电。\",\"anterior\":\"来自拉丁语 anterior「更靠前的」，是 ante「在前」的比较级。anterior 不说「反对」，只说「位置在前」；与 posterior（后面的）成对，解剖学里天天见面。\",\"anthem\":\"经拉丁语 antiphona 进入英语，源头是希腊语 antiphōna「应答之歌」：anti-「相对」+ phōnē「声音」。教堂里两班唱诗班隔空对唱，就是 anthem 的老现场；国歌是它的世俗封号。\",\"anthropologist\":\"anthropology 出自希腊语 anthrōpos「人」+ logos「学问」。研究「人」的学问，词名直白；anthropologist 是操这门学问的人，-ist 只是「…者」。\",\"anticipation\":\"来自拉丁语 anticipare「预先取、提前占」：ante-「在前」+ capere「抓、取」。期待的字面是「抢在事情到来之前先把它抓住」——它以 ante- 开头，与 anti-「反对」无关；cap- 与 current 的 curr 一样，是最容易被认错门牌的词根之一。\",\"antique\":\"来自拉丁语 antiquus「古时的」，源头一般认为是 ante「在…之前」（旧说还有 ante + oculus 一支，不取）。古董的判据是「在很久之前」；看见 anti- 别急着译「反对」，这里没有对手，只有年头。\",\"anxious\":\"来自拉丁语 anxius「忧虑的」，源头是 angere「勒紧、使窒息」。焦虑在词源里是身体感受：像被什么「勒着」透不过气；anger 的近亲 angina（心绞痛）同出 ang-「勒」一家。\",\"apartment\":\"经法语 appartement、意大利语 appartamento 进入英语，出自 a parte「分开（的部分）」：拉丁语 pars/part-「部分」。公寓就是大建筑里「分隔出来归你」的那一份；part 是它的词根。\",\"apathetic\":\"apathy 加 -ic。apathy 出自希腊语 apatheia「无感受」：a-「没有」+ pathos「感受、痛苦」。冷漠在词源里不是态度差，而是「感受通道关了」；sympathy（同情）是同一 path- 的正体。\",\"apathy\":\"来自希腊语 apatheia：a-「没有」+ pathos「感受」。斯多葛派把 apatheia 当修养目标——不受激情扰动；现代英语却把它用成了贬义的「漠不关心」，褒贬在两千年里翻了面。\",\"ape\":\"古英语 apa，日耳曼本族词，源头更深处不详。ape 与 monkey 的老分工是：ape 无尾（类人猿），monkey 有尾；它后来兼作动词「模仿」，因为猿最像人，也最会学人。\",\"aperture\":\"来自拉丁语 apertura「开口」，出自 aperire「打开」。孔径就是「打开的口子的直径」；overture（序曲）经法语也是 aperire 的后代——序曲是「打开场面」的那一段。\",\"apex\":\"来自拉丁语 apex「尖端、顶点」，本义是罗马祭祀帽上的小尖饰，其更深源头不详。apex 不解释、只指位：任何体系里最高的那一点，都可以顶着这个词。\",\"apologetic\":\"apology 的形容词形。apology 出自希腊语 apologia「申辩」：apo-「离开、撇清」+ logos「言说」。道歉的本义是「为自己申辩」——苏格拉底那篇《申辩篇》英文就叫 Apology，并不是去认错的。\",\"apologize\":\"apology 加 -ize。apology 的希腊老家是「法庭申辩」：先为自己说话、撇清，再慢慢变成认错；apologize 用了四百年，才固定成今天的「道歉」。\",\"apology\":\"来自希腊语 apologia「申辩辞」：apo- + logos「言说」。apology 的词义史是一条下坡路：从苏格拉底的慷慨陈词，滑到日常的「对不起」——申辩没了，只剩撇清的那一半。\",\"apostrophe\":\"来自希腊语 apostrophos「转开（的符号）」：apo-「离开」+ strephein「转」。它一身二任：撇号表示字母「转身离开」（省略），修辞格 apostrophe 是演说者「转身」对不在场者说话；catastrophe 的 -strophe 也是这个「转」。\",\"appeal\":\"经古法语 apeler 进入英语，源头是拉丁语 appellare「呼唤、向（法院）申诉」：ad- + pellere 家族的 appellare。上诉的字面是「把案子再喊一遍给更高处听」；吸引力义是「喊得动人」的那一支。\",\"appealing\":\"appeal 的形容词形。appeal 出自拉丁语 appellare「呼唤」：appealing 就是「喊得住人」的——吸引力在词源里是一种声音的本事。\",\"appear\":\"经古法语 apareir 进入英语，源头是拉丁语 apparere「显现」：ad- + parere「出现、被看见」。出现就是「进入视线」；apparent（明显的）是它「看得见」的那一面，相貌义的 appearance 从此分出。\",\"appearance\":\"appear 加 -ance。appear 的根是拉丁语 parere「显现」：外貌就是「显现给人看的那一层」，所以 appearance 永远带一点「未必是里子」的保留。\",\"appetite\":\"来自拉丁语 appetitus「渴望、趋向」，出自 appetere「伸手追求」：ad- + petere「追求、请求」。食欲是 petere 最日常的一种「伸手」；petition（请愿）是同一动作的公文版。\",\"appliance\":\"apply 的名词化专门形。apply 出自拉丁语 applicare「贴上、附着」：ad- + plicare「折叠」。器具是「贴到工作上用的那件东西」——词源里 appliance 讲的是用途，不是品类。\",\"applicable\":\"apply 出自拉丁语 applicare「折叠贴合」：plic-「折」。applicable 是「能贴得上（这个场合）」的：规则像布，贴得服帖才叫适用；与 explicit 的 plic 同一折法。\",\"applicant\":\"apply 的名词形，根在拉丁语 plicare「折」。申请人是「把自己贴到岗位上去」的人：application 先是申请（书），人再由动作得名。\",\"appoint\":\"经古法语 apointer 进入英语，出自拉丁语 ad punctum「到点上」：punctum「点」（pungere 刺）。任命、约定的老图景是「把事情钉在一个点上」：定了时间点，也定了人选点；punctual（准时）同根。\",\"appointment\":\"appoint 加 -ment。appoint 出自「ad punctum 到点」：约会、任命都是「点被定下来」的结果——一个是时间点，一个是职位点。\",\"appraisal\":\"appraise 的名词形。appraise 是 apprize（估价）的变体，受 praise（赞扬）拼写牵连才多出个 a 的模样；根子是拉丁语 pretium「价格」——评估先是估价，赞美是后来的拼写误会。\",\"appraise\":\"源于 apprize「定价」，出自拉丁语 pretium「价格」：与 price、prize 同根。它沾上 praise 的拼写纯属看脸认亲；鉴定师做的是估「价」，不是夸人。\",\"appreciation\":\"appreciate 出自拉丁语 appretiatum「被定过价的」：ad- + pretium「价格」。欣赏与增值同词：看懂了价值，价格（在心里）就涨了——appreciation 一身兼二义，词源里本就是一件事。\",\"appreciative\":\"appreciate 的形容词形，根是拉丁语 pretium「价格、价值」。感激的，是「把对方的价值估足了」的人：谢意在词源里是一张开得公道的估价单。\",\"apprehensive\":\"apprehend 出自拉丁语 apprehendere「抓住」：ad- + prehendere「抓」。抓住嫌犯是 apprehend，抓住（理解）要点也是它；忧虑义走的是第三条路：心先被「揪住」了。comprehend（理解）是同根的「全抓」。\",\"approachable\":\"approach 出自拉丁语 appropiare「走近」：ad- + prope「近」。平易近人就是「走得近、不设防」；approach 本人既当动词（靠近）又当名词（方法：走近问题的路）。\",\"appropriateness\":\"appropriate 出自拉丁语 appropriare「据为己有」：ad- + proprius「自己的」。适当义的来历是「合乎（场合）身份、恰如其分」；appropriateness 追问的永远是「这配置配不配这个场」。\",\"approval\":\"approve 出自拉丁语 approbare「认可为好」：ad- + probare「检验、证明」（probus 好的）。批准之前先有「验过、算好」这一关；proof（证据）与 probare 是同门。\",\"approve\":\"经古法语 aprover 进入英语，源头拉丁语 approbare「断定为好、批准」：probare「考验」。批准的字面是「考过、算数」；英语 approve 先有「证明」义，后才定型为「点头」。\",\"approximate\":\"来自拉丁语 approximare「靠近」：ad- + proximus「最近的」（superlative of prope 近）。近似值不是「差不多糊弄」，而是「尽量靠到最近」——proximus 本就是最高级：最近的那个。\",\"approximation\":\"approximate 的名词形，根在拉丁语 proximus「最近的」。approximation 在数学里是体面的方法名：真值拿不到手，就站到离它最近的位置上去。\",\"apricot\":\"绕了大半个地球的借词：拉丁语 praecoquus「早熟的」→希腊语 praikokion→阿拉伯语 al-burqūq→西班牙、法语 abricot→英语 apricot。词尾的 -cot 是路上沾的；它和 peach 那一家并无亲缘，勿认错。\",\"apron\":\"来自古法语 naperon「小桌布」，出自 nape「桌布」（拉丁语 mappa）。本该是 a napron，英语耳朵把 n 划给了冠词，成了 an apron——围裙是被连读「偷」走一个字母的词，napkin 还保留着原样。\",\"aquarium\":\"来自拉丁语 aquarium「饮水处」，出自 aqua「水」。19 世纪玻璃缸流行，它从「牲口饮水槽」升格为「水族馆」；-arium 是「装某物的场所」，与 terrarium（陆生缸）成对。\",\"aqueduct\":\"来自拉丁语 aquaeductus：aquae（水的）+ ductus「引导」（ducere 带领）。罗马人把「引水」这件事砌成了地标；aqueduct 的 du- 与 duke（公爵，原义领军者）同是「带领」一家。\",\"arc\":\"来自拉丁语 arcus「弓；拱」。弧线就是「弓绷出的那道弯」；arch（拱门）是它在建筑里的变体拼写，electric arc 电弧则借形不借料。\",\"archaeologist\":\"archaeology 出自希腊语 arkhaios「古老的」+ logos「学问」：研究「古」的学问。archaeologist 挖的是时间；注意 arch- 在这里是「古、始」，与 architect 的「首席」同形同源（都出自 arkhē 起始）。\",\"archetype\":\"来自希腊语 arkhetypos「最初的模型」：arkhē「起始」+ typos「印痕、模样」。原型就是「最先敲出来的那块版」；type（类型、打字）是 typos 在印刷术里的后半生。\",\"architect\":\"来自希腊语 arkhitektōn「首席工匠」：arkhi-「首席」+ tektōn「木匠、建造者」。建筑师在词源里是工匠的头儿，不是画图的文员；tectonic（板块的）的 tect- 也是这位「建造者」。\",\"arduous\":\"来自拉丁语 arduus「高陡的、难攀的」。艰巨的字面是「坡太陡」——任务像山一样立在面前；arduous 不说事情多，只说坡度大。\",\"arena\":\"来自拉丁语 harena「沙子」。罗马竞技场地面铺沙吸血，场地便以「沙」为名；arena 后来泛指较量的场子——政治、体育都行，就是别忘了脚下那层沙的本义。\",\"argue\":\"经古法语 arguer 进入英语，源头是拉丁语 arguere（也作 argutare）「使清楚、提出主张」，再往前与印欧语根 *arg-「闪亮」相连（argent 银）。争论的本职是「把理说亮」：argument 是亮出来的那份理据。\",\"argument\":\"来自拉丁语 argumentum「证据、论点」，出自 arguere「使清楚」。argument 先是「使事情变清楚的那段话」，吵翻天的义是后世添的火气；学术 argument 只认前一层。\",\"arid\":\"来自拉丁语 aridus「干透的」，出自 arere「干」。干旱就是「干」到了形容词的程度；注意别和 ardent 的 ard-「燃烧」混门，两家拼写近，履历分明。\",\"arise\":\"古英语 ārīsan：ā-（起）+ rīsan「上升」（rise 的本家）。arise 是 rise 穿了前缀的正式版：事情「升起来」了，就是发生；纯日耳曼词，无拉丁亲戚。\",\"aristocracy\":\"来自希腊语 aristokratia「最优秀者的统治」：aristos「最优秀的」+ kratos「力量、统治」。贵族制的自我标榜全写在词里——「最优者治国」；是否名副其实，词源不负责。\",\"aristocratic\":\"aristocracy 的形容词形。aristos「最优秀」+ kratos「统治」：aristocratic 的字面门槛是「配得上统治的最优者」，现代只取其气质义（高贵的），政治义退居词史。\",\"arm\":\"手臂义是古英语 earm，日耳曼本族词，与拉丁语 armus「肩」同出印欧语根 *ar-「拼合」（关节拼合处）。提醒：武器义的 arms 是另一路——经法语借的拉丁语 arma「装备」，两个 arm 在英语拼写里合流了。\",\"armada\":\"来自西班牙语 armada「武装力量」，出自拉丁语 armata「被武装的」。1588 年西班牙「无敌舰队」大败，这个词从此自带舰队专名气场；英语借它时，连败绩的教训一起借了。\",\"armchair\":\"arm + chair 的复合：扶手椅就是「带臂的椅子」。armchair 还兼作形容词，指「纸上谈兵的」（如 armchair strategist）——坐在扶手椅里指挥的人，词源不评理，画面自明。\",\"armor\":\"经古法语 armure 进入英语，源头是拉丁语 armatura「装备」，出自 arma「武器」。盔甲在词源里是「全副武装」的一个切片；英美拼写 armor/armour 之分与拉丁无关。\",\"armpit\":\"arm + pit 的古英语式复合（earmpytt 有案可查）。pit 是「凹坑」：腋窝就是胳膊底下那个坑——命名朴素到近乎直白，是日耳曼造词的典型手法。\",\"army\":\"经古法语 armee 进入英语，源头是拉丁语 armata「武装起来的（队伍）」，arma 是「武器」。军队先是「被武装的人群总称」，armada（舰队）是它的海上变体拼写。\",\"aromatic\":\"来自希腊语 arōma「香料、香气」（经拉丁语 aromaticus）。arōma 的更深层来源不详；芳香的判据在词源里不在鼻子，而在货架——arōma 本是可买卖的香料。\",\"arrange\":\"经法语 arranger 进入英语：à + rang「行列、排」。rang 出自日耳曼语「环、圈」（ring 的亲戚），排队先成环再成行；arrange 就是「把散件摆进队列」，range（范围、山脉）同门。\",\"arrangement\":\"arrange 加 -ment。arrange 的 rang 是「行列」：arrangement 是队列摆好后的成品图——花艺、编曲、协议安排，共享同一套「摆列」逻辑。\",\"array\":\"经古法语 arei「秩序、队列」进入英语，与 arrange 同出「列队」一义（源头细节有争议，一般系于日耳曼语）。array 先是军队摆阵，后是数据排队：计算机的「数组」正是队列义的现代岗。\",\"arrears\":\"经古法语 arrere「在后面」进入英语，源头是拉丁语 ad retro「向后」。欠款就是「落在后面没跟上的账」；rear（后部）是 retro 在英语里的另一张脸。\",\"arrest\":\"经古法语 arester 进入英语，源头是拉丁语 ad- + restare「停住、留下」：restare 是 stare「站」的后代。逮捕的字面是「使（人）站住」；arrest 的 rest 不是「休息」那个 rest（那是另一词），别拼错门。\",\"arrival\":\"arrive 加 -al。arrive 出自拉丁语 ad ripam「到岸」：arrival 是船靠岸的动作被名词化——每一次 arrival，词源里都先有一片水退到脚后。\",\"arrive\":\"经古法语 arriver 进入英语，源头一般认为是拉丁语 *arripare「抵达岸边」：ad- + ripa「河岸」。古人最隆重的到达是船靠岸，arrive 把「抵岸」泛化成了所有到达；river 与 ripa 同根，河与岸本一家。\",\"art\":\"来自拉丁语 ars（属格 artis）「技艺、手艺」，再往前一般系于印欧语根 *ar-「拼合」。art 的老义是「把部件拼合成器的本事」——先手艺，后艺术；article（小接合物）是它的近亲。\",\"article\":\"来自拉丁语 articulus「小关节、条目」，是 artus「关节」的指小形。文章由「节」拼成，条文按「节」分行，冠词是语法的小关节——article 的三副面孔都从「接点」长出来。\",\"articulate\":\"来自拉丁语 articulatus「分节的」，出自 artus「关节」。表达清晰就是「话像关节一样一节一节咬合」；口齿不清在词源里是「脱节」。\",\"artifact\":\"来自拉丁语 arte factum「凭技艺做成的（东西）」：ars「技艺」+ factum「所做之物」（facere 做）。文物先是「人造物」，考古学给它加了年头；注意 artefact 是英国拼写偏好。\",\"artifice\":\"来自拉丁语 artificium「手艺、巧法」：ars + facere「做」。诡计在词源里是「做得太巧的手艺」：巧到用来骗人，就成了贬义；artificial（人造的）是它中性的兄弟。\",\"artillery\":\"经古法语 artillerie 进入英语，一般与 artillier「装备、器械」相连，源头细节有争议（或经由拉丁语 ars 一路）。大炮得名于「器械」总称：先是全套攻城家伙，后专归火炮。\",\"artist\":\"art 加 -ist。art 出自拉丁语 ars「技艺」：artist 是「以技艺为业的人」——中世纪它还包括手艺人和学者，专指艺术家是近代的事。\",\"artistic\":\"artist / art 的形容词形，根在拉丁语 ars「技艺」。artistic 评价的从来不是天赋，而是「技艺的成色」；这份词源观，今天的艺术教育还在用。\",\"artistry\":\"artist 加 -ry（行业、技艺）。artistry 是把 artist 的本事抽出来单说：技艺本身的高低；词尾 -ry 与 bravery（勇气行当）同工。\",\"artwork\":\"art + work 的复合，19 世纪才定型。work 是古英语 weorc，日耳曼老词；artwork 的命名很直白：算「艺术」的那件「作品」，与 masterpiece（杰作）的师徒制老词分属两个时代。\",\"asbestos\":\"来自希腊语 asbestos「熄不灭的」：a-「不」+ sbennumi「熄灭」。古人见这种纤维织物入火不燃，以为神奇——讽刺的是「烧不坏」的石棉，坏在别处：它的纤维伤肺，词源的赞美后来成了警示。\",\"ash\":\"古英语 æsce，日耳曼本族词。ash 是燃烧的终点词：火过之后剩下的就是它；另一同形词 ash（白蜡树）是古英语 æsc，出身不同，只是拼写合流。\",\"ashamed\":\"古英语 āsceamod 的后代：a- + shame。shame 是古英语 scamu「羞耻」，日耳曼老词。ashamed 的构造是「被羞耻罩住」；ashame 早已不用，只剩这个分词形活着。\",\"askew\":\"a- + skew。skew 经法语 eschiver「躲开、避开」（日耳曼语源）而来：歪斜就是「躲开了正线」。askew 自带画面：一切不肯站直的东西，都是在躲。\",\"asphalt\":\"来自希腊语 asphaltos「沥青」，更深层来源不详（一说与「使稳固、防滑落」有关，未成定论）。佩特拉与死海沿岸的天然沥青先于这个词成名；词源的诚实答案是：希腊老词，源流待考。\",\"aspiration\":\"来自拉丁语 aspirare「吹向、渴望」：ad- + spirare「呼吸」。抱负在词源里是一口「朝着目标吹过去的气」；aspirin 的名字里也有个 aspir-，却是向绣线菊借的，别认错。\",\"assassin\":\"来自阿拉伯语 ḥashshāshīn，十字军时代对尼扎里派成员的称呼（与 hashish 大麻的关联是著名传说，学界对得名细节有争议）。刺客一词漂洋过海进欧洲各语言时，自带阴影：专杀要人的那种杀手。\",\"assembly\":\"assemble 经古法语 assembler 进入英语，源头是拉丁语 assimulare / ad + simul「同时、一处」一脉（与 simul「一起」相关）。集会就是「把人聚到同一时同一地」；注意别和 simulate（模拟，simulare 假装像）混账，那是近亲不同支。\",\"assent\":\"来自拉丁语 assentire「赞同」：ad- + sentire「感觉、以为」。点头同意在词源里是「感觉跟上了」；sentence 的 sent- 也是「所感所想」，一家两用。\",\"assert\":\"来自拉丁语 asserere「宣称、主张（权利）」：ad- + serere「连接」。asserere 在罗马法里是「把（自由身份）与人连接起来宣称」；断言就是把主张「接」到事实上去，series（系列）是 serere「串连」的另一后代。\",\"assertion\":\"assert 的名词形，根在拉丁语 serere「连接、宣称」。assertion 是把话说死的那一下：主张被「接」在说话人身上，收不回去。\",\"assertive\":\"assert 的形容词形。assertive 的底气来自 asserere「宣称权利」：坚定自信不是嗓门大，而是把主张「接到自己名下」不躲闪。\",\"assessment\":\"assess 出自拉丁语 assessus「坐在一旁（估税）」：ad- + sedere「坐」。assessment 沿用至今：评估就是坐下来把价值算清；上一轮已改正其词根为 sess「坐」，这里的词源与拆分是一套。\",\"asset\":\"来自古法语 assez「足够」，源头是拉丁语 ad satis「足够多」。法律英语里 assets 本是「足够偿清债务的财产」：资产的判据先是「够不够抵债」，富余义是后来才有的。\",\"assimilate\":\"来自拉丁语 assimilare「使相似、使同化」：ad- + similis「相似」。消化是把食物「化成像自己的」，文化同化是把人「化得像本地的」——同一动作，两个考场（生物与社会）。\",\"assistant\":\"assist 出自拉丁语 assistere「站在旁边」：ad- + sistere「站」。助理的字面岗位就是「站在旁边的人」：随时搭手，所以叫 assistant；insist 的 sist 也是站——坚持是「站住不走」。\",\"associate\":\"来自拉丁语 associare「结成伙伴」：ad- + socius「伙伴」。associate 的老义是「拉人入伙」；联想义是心理学的后起用法：观念也结伙，一个露面，另一个跟着来。social 是 socius 的直系。\",\"annoyance\":\"annoy 经古法语 anoier 进入英语，一般上溯晚期拉丁语短语 in odio「在仇恨里、招人厌」。annoyance 是「招人厌」的状态名词化；annoy 本人的词义史带着中世纪宫廷的火药味：先是憎恶，后才降格为日常烦恼。\",\"arrow\":\"古英语 arwe / earh，日耳曼本族词，一般上溯原始日耳曼语 *arhwō；有学者把它与拉丁语 arcus「弓」联系（箭与弓同出狩猎场），此说常见但未成定论。稳妥记法：箭是日耳曼老词，与弓关系密切。\",\"revenue\":\"来自古法语 revenu，源头是拉丁语 revenire「回来」：re-「回」+ venire「来」。收入的字面义就是「回流到你手里的钱」；它和 venue（场地，原义「到来」）、advent（到来）同出 ven / venire 一家。\",\"wage\":\"来自古法语 wage「抵押、保证金」，是日耳曼语借词，与 wed（结婚押上承诺）、engage（押上）同源。工资最初是雇主「押给」雇员的报酬：先有担保，后有工钱。wages 现在多用复数指计件、计时工资。\",\"bonus\":\"直接取自拉丁语 bonus「好的」：18 世纪伦敦金融行话里，它指分红之外「额外多给的那份好东西」。词形像阴性名词其实是拉丁形容词被当名词用；bonus 的反面笑话 malus（罚款式扣减）也是后来照它仿造的。\",\"pension\":\"来自拉丁语 pensionem「一笔付款」，动词 pendere 兼有「悬挂称量」与「支付」两义——罗马人付钱前要过秤称银。养老金就是退休后仍在持续「称付」的那笔钱；它和 pendant（垂饰，悬挂义）、pensive（掂量→沉思）是同根的不同分支。\",\"insurance\":\"insure 来自古法语 enseurer「使安全」，源头是拉丁语 securus「无忧的」：se-「无」+ cura「忧虑、照料」。保险的字面义就是「把忧虑拿掉」；它和 security 同出 cura 家族——注意那是「照料」的 cur，与 current 里「跑」的 curr 不是一回事。\",\"premium\":\"来自拉丁语 praemium「奖赏、战利品」：prae-「在前」+ emere「拿、买」。先是「拿在前面的奖赏」，保险业里转指为保单预先付出的那笔钱——保费就是买下保障的「价金」。\",\"claim\":\"来自拉丁语 clamare「喊叫、呼唤」，经古法语 clamer 进入英语。索赔、主张权利在古代就是当众「喊出」自己的要求：声音越大，权利越不能装作没听见。它和 exclaim、clamor 同根。\",\"duty\":\"due 的名词化：due 来自古法语 deu，源头是拉丁语 debere「欠」。duty 本义是「欠下的、该做的事」；作「税款」讲时，是欠国家的那一份——关税、消费税都是这一支。\",\"subsidy\":\"来自拉丁语 subsidium「后备队、援军」：sub-「在下方」+ sedere「坐」。罗马军团里坐在后排随时顶上的预备队叫 subsidium；政府补贴就是经济上的「后备援军」，与 subsidy 同根的是 sid / sess「坐」家族（reside、session）。\",\"liability\":\"liable 来自古法语 lier「捆绑」，源头是拉丁语 ligare「绑」。法律上被「绑住」就得负责：liability 是绑在身上的义务与债务。它和 ligament（韧带）、league（联盟）同出 ligare 一家。\",\"bankruptcy\":\"来自意大利语 banca rotta「砸断的长凳」：banca 是钱商做生意的长凳（bank 银行也由此而来），rotta 是「断裂的」（拉丁 ruptus）。相传无力偿债的钱商长凳要被当众砸断，生意就此收摊——破产的字面画面就是「摊子被砸」。\",\"auction\":\"来自拉丁语 auctio「公开出售」，动词 augere 是「增加、扩大」。拍卖的规则写在词里：价格只能往上「增」。它和 augment（增加）、author（创始者，把作品「增」出来的人）同根。\",\"bid\":\"这个词是两个古英语词在中古英语里合并的结果：biddan「请求、祈祷」与 beodan「出价、宣布」。所以 bid 既能是拍卖场上的「出价」，也能是「请求、吩咐」（do someone's bidding）——两条河汇成了一个词。\",\"negotiation\":\"来自拉丁语 negotiatio，源头 negotium「生意、事务」：nec-「不」+ otium「闲暇」。谈判的字面义是「没有闲暇地谈生意」；negotiate 也可指「顺利通过（弯道、障碍）」，都是「把难事谈成、办成」。\",\"partnership\":\"partner 来自古法语 parçonier「合伙分利的人」，源头是拉丁语 partitio「划分」；partner 的拼写后来被 part（部分）带偏。合伙企业的核心就是词里那个动作：分——分股、分工，也分担风险。\",\"corporation\":\"来自拉丁语 corpus「身体」+ -ation：法律把一群人「做成一个身体」，于是公司成为能签约、能起诉的独立「法人」。它和 corpse（尸体）、corps（军团）同出 corpus 一家，读音分工不同而已。\",\"enterprise\":\"来自古法语 entreprise「着手进行的事业」，动词 entreprendre 源于拉丁语 inter + prehendere「抓、着手」。企业的字面义是「抓在手里做起来的事」；形容词 enterprising「有闯劲」保留着这股主动劲儿。\",\"entrepreneur\":\"直接借自法语 entrepreneur「承包人、承办人」，与 enterprise 同根（entreprendre「着手做」）。它在 19 世纪经济学里被固定为「企业家」：敢把一件事从零抓起来做的人。注意法语读音，词尾 -eur 是「做事的人」。\",\"manager\":\"manage 来自意大利语 maneggiare「训练马匹、操控」，源头是拉丁语 manus「手」。管理最初是「用手驭马」：缰绳在手，方向由你。它和 manual（手动的）、manuscript（手稿）同出 manus 一家。\",\"employer\":\"employ 来自古法语 employer「使用、雇用」，源头是拉丁语 implicare「卷入、使参与」：in- + plicare「折叠」。雇用一个人，就是把他「卷进」你的事务里；employer 是发出这份邀请的老板。它与 apply、explicit 同出 plic「折叠」家族。\",\"union\":\"来自拉丁语 unio「合一；单颗的珍珠」，源于 unus「一」。工会（labor / trade union）的字面义就是「合而为一」：单个工人是散珠，组织起来才成串。它和 unit、unique、universe 同出 unus。\",\"strike\":\"罢工义是个地道的航海典故：1768 年伦敦水手为抗议而「strike」——降下（strike 本义之一）船帆让船停航，strike 从此有了「停工抗议」的含义。strike 的古英语本源 strican 是「轻擦、走过」，降帆、击打、罢工都是它一路上捡到的义项。\",\"unemployment\":\"un-「不」+ employment 的名词化。employ 源于拉丁语 implicare「卷入」（见 employer）：失业的字面画面是「没有被任何事务卷进去」的状态。失业率 unemployment rate 是托福听力与阅读的高频搭配。\",\"inflation\":\"来自拉丁语 inflare「吹入、吹胀」：in- + flare「吹」。物价像被吹胀的气球：钱还在，购买力被吹薄了。通货膨胀的说法 19 世纪在美国流行开来；它与 deflation 正好是充气与放气的一对。\",\"deflation\":\"de-「向下、去除」+ inflation（见上条）：字面义是「把吹胀的气放掉」。物价与货币供应一起收缩，就是通货紧缩——气球瘪下去，钱反而更「值钱」，但经济也随之发冷。\",\"recession\":\"来自拉丁语 recessio「后退」，动词 recedere 是 re-「回」+ cedere「走」。经济衰退的字面义就是「往回走」：增长掉头。经济学上常以连续两个季度 GDP 下滑为标志；它和 process（向前走）正好是一对反义同根词。\",\"stagnation\":\"来自拉丁语 stagnum「一潭死水、池塘」。水不流动会发臭，经济不增长就叫停滞：stagnation 的核心画面是「 stagnant water」——静止。1970 年代的 stagflation（滞胀）就是它和 inflation 的混血词。\",\"stability\":\"来自拉丁语 stabilis「站得稳的」，源于 stare「站立」。稳定性的字面义是「站得住」：它和 state、station、statue 同出 sta「站」家族——站得稳，才成状态、成制度。\",\"import\":\"来自拉丁语 importare「运进来」：in- + portare「搬运」。进口就是把货物「搬进来」；import 的另一义「重要性」同出一源：分量是被「搬进」天平的那份重。它属 port「搬运」家族（export、transport、portable）。\",\"customs\":\"custom 来自拉丁语 consuetudo「习惯、惯例」，海关义由此生出：在边境按「惯例」缴纳的过路费，就叫 customs（关税），收税的衙门就成了海关。一个词把「风俗」与「关税」连在一起，因为两者都是「向来如此」的规矩。\",\"quota\":\"来自拉丁语 quota (pars)「（第）多少份、应摊的那一份」，源于 quot「多少」。配额的字面义是「分到你头上的份额」：进口配额、招生配额都是先把总量切份，再按份领取。\",\"brand\":\"来自古英语 brand「燃烧、火把」，是日耳曼语本族词。品牌的字面起点是「烙印」：牧场主用烧红的铁在牲口身上烫下记号，后来工匠在酒桶、商品上烙下自己的标记——brand 就这样从「火烫的印」变成「牌子」。\",\"trademark\":\"trade（买卖）+ mark（标记）的复合词。mark 来自古英语 mearc「记号、界标」，日耳曼语源。商标就是「做买卖用的标记」，与 brand 的烙印义殊途同归；注册后写作 ®。\",\"copyright\":\"copy + right 的复合词。copy 源于拉丁语 copia「丰富、大量」（抄本因复制而多）；版权即「复制的权利」，18 世纪英国《安妮法令》（1710）之后成为出版业的核心概念。它只保护表达，不保护思想本身。\",\"inventory\":\"来自拉丁语 inventarium「财产清单」，动词 invenire 是 in- + venire「来」——「来到（眼前）的东西」要逐件登记。库存清单的字面义是「找出来的全部家当」；invent（发明）与它同根：发明也是把新东西「找出来」。\",\"warehouse\":\"ware + house 的复合词。ware 来自古英语 waru「被看管的货物」，与 aware（察觉、留心）同源：仓库就是「看管货物的房子」。软件里的 data warehouse（数据仓库）借的正是这个画面。\",\"shipment\":\"ship + -ment 的复合词。ship 来自古英语 scip，日耳曼语本族词。shipment 起初专指「装船」这件事与船上的货，后来公路、航空托运也沿用；所以一卡车货也能叫 a shipment。\",\"delivery\":\"deliver 来自古法语 delivrer，源头是拉丁语 de- + liberare「使自由」（liber「自由的」）。交付的字面义是「把东西从束缚里解放出来交到对方手上」：分娩叫 delivery、投递邮件也叫 delivery，都是「送达即释出」。它和 liberty 同出一家。\",\"logistics\":\"来自法语 logistique「军队后勤学」，源于 loger「驻扎、住宿」、logis「营舍」——管的是大军住哪、吃什么、怎么运。它常被误拆成希腊语 logos「言语、理性」：两者只是碰巧同形，logistics 的 log- 是「营舍」不是「逻辑」。二战后这个词才从军营走进供应链管理。\",\"invoice\":\"来自古法语 envois「寄出之物」，动词 envoyer 是「派送上路」：源头可上溯拉丁语 in + via「在路上」。发票就是随货「在路上」的那张清单；它与 envoy（使节，被派上路的人）同出一家，属 via「路」家族。\",\"receipt\":\"来自拉丁语 recepta「被收下的东西」，动词 recipere 是 re- + capere「拿」。收据的字面义是「已拿到的凭证」：一张写明「收到了」的纸。它和 receive、reception 同出 capere「拿」家族；注意 receipt 里的 p 不发音，是文人后来按拉丁原形加回去的。\",\"discount\":\"dis-「去掉」+ count「数、算」：字面义是「从总数里数掉一部分」。count 源于拉丁语 computare「合计」（com- + putare「清点」），所以 discount 是账房里的动作：把该减的那笔当场算掉。它和 compute、account 同出 put「清点」家族。\",\"warranty\":\"来自古法语 warantie「担保」，保证人 warant 是日耳曼语借词。它和 guarantee 其实是同一个词的两条入境路线（一走诺曼法语、一走巴黎法语），w / gu 的差异来自方言发音。保修的字面义就是「有人作保」。\",\"state\":\"来自拉丁语 status「站立姿态、状况」，源于 stare「站」。政治义经由「国家的状况 / 体制」发展而来：state 是「站定了的政体」。它与 stability 同出 sta「站」家族；美式英语里 state 又专指联邦的「州」。\",\"country\":\"来自古法语 contrée，源头是拉丁语 contra「对面、在前面」+ terra 的俗语形式：意为「摊在眼前的那片土地」。先指乡野地区，后指有边界的国土。它与 encounter（迎面相遇）共享 contra「相对」的画面。\",\"asylum\":\"来自希腊语 asylon「不可侵犯的避难所」：a-「不」+ sylē「抢夺」。避难所的字面承诺是「在这里不许抓人」：古希腊神庙即有此神圣性。后来词义扩展出「精神病院」的旧称义（asylum 作为庇护所收治病人）。\",\"constitution\":\"来自拉丁语 constitutio「设立、构成」，动词 constituere 是 con- + statuere「竖立」（stare「站」）。宪法的字面义是「把国家立起来的那套根本安排」；它还有「体质、构成」义——身体怎么「立」起来，和国家是同一个词。\",\"ordinance\":\"来自古法语 ordenance，源头是拉丁语 ordinare「排列成序、规制」，名词 ordo 是「行列、秩序」。条例的字面义是「排进秩序里的规定」；它和 order、ordinary 同出一家——ordinary 的「普通」正是「在常规秩序之内」。\",\"decree\":\"来自拉丁语 decretum「裁定、判决」，动词 decernere 是 de- + cernere「筛分、判定」。法令的字面义是「筛过之后定下来的」；它与 discern（辨别）、certain（筛定→确定的）同出 cernere 家族。\",\"bill\":\"来自中世纪拉丁语 bulla「印章、盖印文书」——bulla 本义是「圆泡、圆徽」，罗马教皇诏书以铅印封缄，故称 bulla。议案在成为法律之前是一纸「文书」，bill 的法案义由此而来；账单、钞票义也都是「一纸文书」的分流。\",\"law\":\"来自古英语 lagu，借自古诺尔斯语 lag「被定下来的东西」，本源动词是「放置、躺下」：法律就是「被放定、不许挪动的规矩」。这是日耳曼语（北欧）来客，不走拉丁路线；outlaw（法外之人）也是同一血统。\",\"illegal\":\"in-「不」（在 l 前同化为 il-）+ legal「合法的」。legal 源于拉丁语 legalis，名词 lex 是「法律」；lex 的更深来源有争议，一说与 legere「诵读、颁布」有关，未成定论——记到 lex「法」这一层最稳妥。\",\"court\":\"来自古法语 cort，源头是拉丁语 cohors「院子、围场；随从队伍」。国王被随从围在院子里议事，court 先是「宫廷」，再是「审案的法庭」：同一个围场，三种身份。它和 courtyard、cohort 同出一源。\",\"lawyer\":\"law + -yer（从事……的人，如 sawyer 锯木工）的复合构词，中古英语成词。它是本土地道的「日耳曼式」职业名，与源自法语的 attorney 并行使用至今：一个说「懂法律的人」，一个说「被托付的人」。\",\"attorney\":\"来自古法语 atorné「被指定的人」，动词 atorner 是「转向、委派」，源头拉丁语 tornare「车削、旋转」。代理人的字面义是「被（当事人）转向托付的那个人」：你把案子「转」给他，他替你出面。它与 turn 同出一家。\",\"defendant\":\"defend「辩护」+ -ant「……的人」：defend 源于拉丁语 defendere「挡开」（de- + fendere「击打」）。被告的字面岗位是「挡开指控的人」；原告是进攻方，被告是防守方，词形本身就写着攻守。\",\"plaintiff\":\"来自古法语 plaintif「哀诉的」，名词 plainte 是「诉苦、控告」，源头拉丁语 planctus「捶胸哀哭」（plangere「击打」）。原告的字面形象是「捶着胸口喊冤的人」；它与 complaint 同根——complaint 最初也是喊冤，后来才降格为日常抱怨。\",\"witness\":\"来自古英语 witnes：wit「知晓」+ -ness「状态」。证人的字面义是「知情」本身：亲眼见过、心里有数，才能出庭作证。wit 与拉丁语 videre「看」同出印欧语 *weid-「看见→知道」——与 video、vision 是远亲。\",\"trial\":\"来自盎格鲁-法语 trial，动词 trier 是「挑选、筛选、试验」。审判的字面义是「把事实筛一遍」；try 的更深来源有争议，一说与拉丁语 tritare「碾磨、脱粒」有关（筛谷画面），未成定论——记到「筛选、考验」这一层即可。\",\"sentence\":\"来自拉丁语 sententia「意见、看法、判决」，动词 sentire 是「感觉、思考」。法官的「看法」落槌就成了判决；语法里的「句子」也是同源分流：一段完整的「所思所言」。它与 sense、sentiment 同出 sentire 一家。\",\"penalty\":\"来自拉丁语 poena「惩罚、罚金」，poena 又借自希腊语 poinē「血债、赎罪金」，经中世纪拉丁语与法语演变为 penalty。处罚的字面义是「付出的代价」；同根的 pain（痛苦）把这份代价写在了身体上。\",\"imprisonment\":\"imprison = in- + prison：prison 来自拉丁语 prehensio「抓捕」，动词 prehendere 是 prae- + hendere「抓」。监禁的字面义就是「被抓住、关起来」；它与 enterprise（着手抓事）、comprehend（抓全→理解）同出「抓」这一动作。\",\"supreme\":\"来自拉丁语 supremus「最高的」，是 superus「在上的」的最高级，源头 super「在……之上」。最高法院的字面义就写在词里：坐在所有法院「之上」的那一家。它和 superior、superb 同出 super。\",\"justice\":\"来自拉丁语 justitia，形容词 justus 源于 jus「法、权利」。正义的字面义是「合乎法的状态」：justice 既指抽象的公正，也指司法体系本身（the Department of Justice）。\",\"criminal\":\"来自拉丁语 crimen「指控、罪行」+ -al。crimen 一般上溯 cernere「筛分、判定」：它最初指法庭上的裁断与指控，后来才转指罪行本身。罪犯就是名字与 crimen 绑在一起的人。\",\"theft\":\"来自古英语 þeofþ：þeof「贼」+ 名词后缀（与 health、width 同一构词法）。盗窃是纯日耳曼语老词，没有拉丁词根可拆，整体认读即可；thief（贼）是它的同族兄弟。\",\"robbery\":\"rob 来自古法语 rober「抢夺」，是日耳曼语借词（与德语 rauben 同源）。抢劫自古偏指「当面夺取」，与 theft 的暗中偷窃相对：一个靠吓，一个靠藏。\",\"burglary\":\"来自中世纪拉丁语 burglaria。burglar 的确切来源有争议：通说认为前半与 burg「设防的居所」有关，后半或与拉丁语 latro「贼」相连，未成定论。可以确定的是它的法律核心——夜间潜入住所行窃，「入室」是这个词的界碑。\",\"murder\":\"来自古英语 morðor「暗杀、重罪」，日耳曼语词，与拉丁语 mors「死亡」同出印欧语词根 *mer-「死」（mortal「终有一死的」是远亲）。它最初特指「秘密杀人」，后扩展为一切非法故意杀人；拼写中的 d 是中世纪受法语 murdre 影响定型的。\",\"bribery\":\"bribe 来自古法语 bribe「讨来的一小块面包」，后指「偷来的零碎、不正当的好处」，再转指塞给官员的贿赂。词义轨迹很生动：乞食的面包 → 顺手牵羊的赃物 → 买通权力的价钱。bribery 是它的派生名词。\",\"corruption\":\"来自拉丁语 corruptio，动词 corrumpere 是 com-「彻底」+ rumpere「打破、弄坏」。腐败的字面义是「从里头彻底坏掉」；它与 rupture（破裂）、bankrupt（摊子被砸断）同出 rupt「断裂」家族。\",\"smuggling\":\"smuggle 源于低地德语 / 荷兰语 smokkelen「偷偷搬运」。英语里先出现的是 smuggler（走私者，17 世纪），动词是后来逆生出来的。走私没有拉丁词根，它本就是港口暗巷里的行话。\",\"treason\":\"来自古法语 traïson，源头是拉丁语 traditio「交付、交出」：tradere 是 trans-「越过」+ dare「给」。叛国的字面义是「把国家交到敌方手里」；tradition（传统）与它同根——传统是把文化「交付」给下一代，同一个动作，一褒一贬。\",\"officer\":\"office + -er。office 源于拉丁语 officium「职责、公务」，一般分析为 opus「工作」+ facere「做」的缩合。警官、军官的字面义都是「担着职责的人」；official 与它同出一门，一个偏指人，一个偏指官方性质。\",\"detective\":\"detect「查出」+ -ive。detect 源于拉丁语 detegere「揭开」：de-「去掉」+ tegere「遮盖」。侦探的字面工作是「掀开盖子找真相」；它与 protect（在前面盖护）同出 tegere「盖」家族，一揭一盖。\",\"patrol\":\"来自法语 patrouille，动词 patrouiller 原义是「在泥泞里蹚行」，源于 patte「爪子、脚掌」。巡逻的字面画面是士兵踩着泥水一圈圈「蹚」完防区——本是脚力活儿，后来才轮到警车。\",\"custody\":\"来自拉丁语 custodia「看守、监护」，名词 custos 是「守卫」。拘留在字面义上是「被置于看守之下」；它也指离婚案中孩子的监护权——两种 custody 问的都是同一句话：由谁看着。\",\"jail\":\"来自古法语 jaiole「小笼子、牢房」，源头是拉丁语 caveola——cavea「笼子」的小称（cavus「空」）。牢房的字面义就是「小笼子」；它与 cage 同源，jail 与 gaol 两种拼写是这个词经不同法语方言入境留下的双胞胎。\",\"probation\":\"来自拉丁语 probatio「检验、证明」，动词 probare「试验、证实」源于 probus「正直的」。缓刑的字面义是「考察期」：先拿出证明来。它与 prove、probe 同出一家，核心动作都是「验一验」。\",\"parole\":\"借自法语 parole「话语、诺言」，源头是拉丁语 parabola「言辞、比喻」（希腊语 parabolē）。假释的字面义是「凭一句话放人」：以承诺作保。它与 parable（寓言）、parliament（说话的集会）同在一条「言辞」的线上。\",\"dictatorship\":\"dictator 源于拉丁语 dictare「宣令、口授」（dicere「说」）。罗马在危急时任命独裁官授以全权，本是限期职位；dictator 的字面义只是「发号施令的人」，贬义是后世政治史加上去的。它属 dict「说」家族，与 dictionary 同门。\",\"tyranny\":\"来自希腊语 tyrannos「僭主」，经拉丁语、法语进入英语。tyrannos 的确切来源存疑，可能借自小亚细亚的吕底亚语。要紧的是：它在希腊语里起初不带贬义，指以非世袭手段取得政权的统治者；「暴政」的色彩是后来才染上的。\",\"ballot\":\"来自意大利语 ballotta「小球」，是 ball 的小称。威尼斯等城邦投票时投有色小球表决，选票由此得名；secret ballot 就是「无记名投票」。它与 ballet 没有关系——那是另一条词源线。\",\"party\":\"来自古法语 partie「一部分」，源头是拉丁语 pars「部分」。政党的字面义是「全体中的一部分人」。它与 partner（分一份的人）、partial（部分的）同源；社交「聚会」义是后起的分流。\",\"conservative\":\"来自拉丁语 conservare「保存、守护」：con- + servare「保持、看护」。保守的字面义是「把现有的看护好」。它与 preserve、reserve 同出 serv「保存」家族；server 的 serv 是同一词根的「服务」一面。\",\"radical\":\"来自拉丁语 radix「根」+ -al。激进的字面义是「动到根的」：radical reform 即连根拔起式的变革。它与 radish（萝卜）、eradicate（根除）同家；化学里的「自由基」、数学里的「根式」也都绕着「根」转。\",\"moderate\":\"来自拉丁语 moderatus「适度的」，动词 moderari「控制、调节」源于 modus「限度、方式」。温和的字面义是「守住限度」；它与 mode（方式）、modest（有分寸→谦逊）同出 modus 一家。\",\"parliament\":\"来自古法语 parlement「谈话、议事集会」，动词 parler「说话」上溯晚期拉丁语 parabolare「讲话」（parabola「言辞」）。议会的字面义朴素得很：一个「说话的地方」——先有辩论，后有大厦。它与 parole 同根。\",\"cabinet\":\"来自法语 cabinet「小房间」，源于 cabane「小屋」。内阁的字面义是「密室」：君主同亲信在小房间里议事，后来「小房间里的人」成了内阁。它作「橱柜」讲是同一词的另一面：都是能关上门的小空间。\",\"minister\":\"来自拉丁语 minister「仆人、助手」，源于 minus「更少」。部长的字面义出人意料——先是「侍奉者」：侍奉君主与国家的人。它与 administer、minus 同源；教会里的 minister（牧师）保留着「侍奉」的原义。\",\"premier\":\"借自法语 premier「第一的」，源头是拉丁语 primus「首要的」。总理的字面义就是「第一（部长）」，与 prime minister 是同一个概念的两种说法；prime、primary 与它同家。\",\"mayor\":\"来自古法语 maire，源头是拉丁语 major「更大者」（magnus「大」的比较级）。市长的字面义是城镇里的「头号人物」；major（主要的）、majority（多数）与它同出一家，都是「更大的那一头」。\",\"official\":\"来自拉丁语 officialis「公务属员的」，源于 officium「职责」（见 officer 条）。official 做名词是官员，做形容词是「正式的」——两种用法都出自「在公务名册之内」这一层意思。\",\"bureaucracy\":\"法语造词 bureaucratie：bureau「办公桌、办公室」+ 希腊语 kratos「统治、权力」。bureau 原指铺在桌上的粗呢布，继而指桌子、办公室。官僚制的字面义是「办公桌的统治」——这词 18 世纪诞生时就带着讽刺味。\",\"embassy\":\"来自古法语 ambassade「使命、使团」，源于中世纪拉丁语 ambactia「差事」，再上溯凯尔特语 ambactus「仆从、随员」（高卢语借词）。大使馆的字面义是「奉命出差的那一班人及其驻地」；ambassador 同源，绕了一个凯尔特弯子。\",\"neutrality\":\"来自拉丁语 neuter「两者都不」：ne-「不」+ uter「（两者中）哪一个」。中立的字面义是「两边都不站」；语法术语 neuter（中性）是同一个词——既非阳性亦非阴性，正是「两者都不是」。\",\"sovereignty\":\"来自古法语 soveraineté，源头是中世纪拉丁语 *superanus「在上者」（super「在上」）。主权的字面义是「居于一切之上的权力」。要留意：sovereign 里的 g 是文人误以为它与 reign 同源而添入的，词源上本不存在——一个被写进词典的错误。\",\"territory\":\"来自拉丁语 territorium「城邦管辖的土地」，源于 terra「土地」。民间曾有「吓退外人之地」（源于 terrere「吓唬」）的说法，但主流词源学取 terra 一线。它与 terrain、terrace 同家。\",\"independence\":\"in-「不」+ dependence。depend 源于拉丁语 dependere「垂下、依附」：de- + pendere「悬挂」。独立的字面义是「不再吊在别人下面」；pendere 的另一支是 pension（称量→支付）——一头挂着依附，一头挂着发钱。\",\"rebellion\":\"来自拉丁语 rebellio「重新开战」：re-「重新」+ bellum「战争」。叛乱的字面义是「败了再度举兵」；bellum 也在 antebellum（战前的）里露面。它属 bell「战争」词根，与 bellicose（好战的）同门。\",\"protest\":\"来自拉丁语 protestari「公开声明、作证」：pro-「在众人前」+ testari「作证」（testis「证人」）。protest 的老义是「公开宣示立场」，反对色彩是后加的；testament（遗嘱）、testify 与它同出 testis 一家。\",\"demonstration\":\"来自拉丁语 demonstrare「指出、展示」：de- + monstrare「指给看」（monstrum「征兆、警示之物」）。示威的字面义是「把诉求亮给人看」；monster 与它同根——怪物最初是「被展示出来的异象」。\",\"petition\":\"来自拉丁语 petitio「请求、申请」，动词 petere「追求、请求」。请愿的字面义是「正式递上去的请求」；compete（共同追求→竞争）、appetite（追求→食欲）与它同出 petere，一根词干分管欲望、竞争与公文。\",\"referendum\":\"取自拉丁语 referendum「必须提交（表决）的事」，是 referre「送回、提交」的动名词形式：re- + ferre「携带」。公投的字面义是「把决定送回到选民手里」；它属 fer「携带」家族，与 transfer、proliferate 同门。\",\"census\":\"来自拉丁语 census「人口与财产登记」，动词 censere「评估、估量」。罗马监察官每五年登记公民与财产以定税级与兵役——人口普查从诞生起就与税收绑定。它与 censor、censure 同源。\",\"reform\":\"来自拉丁语 reformare「重新成形」：re- + formare（forma「形状、形式」）。改革的字面义是「把形状再捏一遍」：材料不换，形状重塑。它与 formal、formation 同家；宗教改革 Reformation 因此得名。\",\"welfare\":\"well（好）+ fare（过活）的复合词。fare 来自古英语 faran「走、生活」，是日耳曼语本族词。福利的字面义是「日子过得顺不顺」；20 世纪它才固定指国家社会保障（welfare state 福利国家）。\",\"dynasty\":\"来自希腊语 dynasteia「权力、统治」，源于 dynastēs「统治者」、dynasthai「有能力、能做到」。王朝的字面义是「权力（在一家手里）连续」；dynasty 的重音与拼写都保留着希腊血统。\",\"kingdom\":\"来自古英语 cyningdōm 的复合：king + -dom（领域、状态）。king 本身源于 cyning「族中之首」——cynn「亲族」+ -ing「……之后」，国王最初是「本族所出的人」。王国是纯正的日耳曼复合词，没有拉丁成分。\",\"tribe\":\"来自拉丁语 tribus「部落」。传统解释把它与 tri-「三」联系：传说罗马最初由三个部落组成，故名。此说流传最广，但语言学家对细节仍有保留——可以记作「三分而治的部落」这一层。\",\"clan\":\"来自苏格兰盖尔语 clann「子孙、后代」，而 clann 又借自拉丁语 planta「幼苗、插条」。氏族的字面义是「同一株上发出的苗」：血缘被想象成植物的分枝，意象与 family 的「一家人」完全不同。\",\"nomad\":\"来自希腊语 nomas「四处放牧的」，源于 nemein「分配、放牧」与 nomos「牧场、惯例」。游牧者的字面义是「逐水草分配牧场的人」；数码游民 digital nomad 借的正是这种「无定所」。\",\"settler\":\"settle 来自古英语 setlan「使坐下、安顿」，名词 setl 是「座位」。定居者的字面动作是「坐下来不走了」；它与拉丁语 sedere「坐」同出印欧语 *sed-，是英语本族的「坐」字辈。\",\"colonist\":\"来自拉丁语 colonus「农夫、垦殖者」+ -ist，动词 colere 是「耕种、居住」。殖民地（colony）的老义是「农庄拓殖地」：殖民者先是拿锄头的人。它与 culture、cultivate 同出 colere——耕种与文化，在拉丁语里本是一个动作。\",\"slave\":\"来自中世纪拉丁语 sclavus「斯拉夫人」。中世纪战争中大量斯拉夫人被俘为奴，以至族名直接变成了「奴隶」的通称。slave 与 Slav 同形同源，是欧洲史在词汇里留下的伤口；slavery 是它的派生名词。\",\"slavery\":\"slave + -ery（状态、行当）构成。词的来历见 slave 条：族名变作奴名，制度名再由人身上长出来——奴隶制就是「把人当作 sclavus」的整套安排。\",\"medieval\":\"来自拉丁语 medium aevum「中间的时代」：medius「中间的」+ aevum「时代、永恒」。这是后世史学家（17 世纪起）给古典与文艺复兴之间那一千年贴的标签；aevum 也在 eternity 里出现过——时代与永恒，在拉丁语里是同一个词根。\",\"pre-historic\":\"pre-「在前」+ historic 的新造复合词，19 世纪考古学兴起时成形。history 源于希腊语 historia「探究、记述」：史前即「还没有文字记述的时代」——分界线不在年代，在有没有人写下来。\",\"relic\":\"来自拉丁语 reliquiae「遗留之物」，动词 relinquere 是 re- + linquere「离开、留下」。遗迹的字面义是「被时间留下的那部分」；它在宗教语境里先指圣徒遗物，后扩展到一切古物。它与 relinquish（放弃）同门。\",\"ruin\":\"来自拉丁语 ruina「倒塌、崩落」，动词 ruere 是「冲倒、坍塌」。废墟的字面义是「倒塌之后的样子」；ruin 也作动词「毁掉」，名词动词同形——坍塌的动作与结果，在这个词里没有分家。\",\"tomb\":\"来自希腊语 tymbos「坟丘、冢」，经拉丁语 tumba、古法语 tombe 进入英语。坟墓的字面起点是地面隆起的那座「土堆」；拼写里的 b 不发音，是中古英语以后按拉丁形式缀上的。\",\"pyramid\":\"来自希腊语 pyramis。确切来源有争议：一说源于埃及语中表示金字塔的词，一说与希腊语 pyramous「小麦糕」（形状相似）有关，未成定论。可以确定的是：希腊人用它命名了尼罗河畔那些尖顶巨石建筑，词随建筑一起传遍世界。\",\"shrine\":\"来自拉丁语 scrinium「匣子、文书箱」，古英语作 scrin。匣子先装经文与圣物，后来供奉圣物的场所也叫 shrine——神龛的字面义是「放圣物的那只箱子」，容器变成了圣地本身。\",\"mosque\":\"来自阿拉伯语 masjid「礼拜、叩拜之所」，动词 sajada 是「叩拜」，经西班牙语 mezquita、法语 mosquée 转入英语。清真寺的字面义不在建筑，在动作：向真主叩拜的地方。\",\"cathedral\":\"来自拉丁语 cathedra「主教座椅」，源于希腊语 kathedra：kata-「向下」+ hedra「座位」。大教堂的字面标志是那把椅子：设有主教座位的教堂才叫 cathedral。它与 chair 是同一词源的两条路线——一个走了学术拉丁，一个走了民间法语。\",\"monastery\":\"来自希腊语 monastērion，源于 monazein「独居」、monos「单独」。修道院的字面义是「独居者聚居的地方」——说法本身带着悖论：为了各自独修而住到一起。它与 monk、monopoly 共享 monos「单」。\",\"castle\":\"来自古法语 castel，源于拉丁语 castellum「小要塞」，是 castrum「军营、堡垒」的小称。城堡的字面义是「小号的设防营地」；英国地名后缀 -chester、-caster 都来自 castrum，是罗马军营在地图上的化石。\",\"palace\":\"来自拉丁语 Palatium——罗马七丘之一「巴拉丁山」的名字，奥古斯都等皇帝的宫殿就建在山上，于是山名变成了「宫殿」的通称。宫殿一词的来历是地名泛化：先有那座山，后有满世界的 palace。\",\"throne\":\"来自希腊语 thronos「高座、宝座」，经拉丁语 thronus、古法语 trone 进入英语。王位的字面义朴素得很：那把高高在上的椅子；「登基」在英语里就是 ascend the throne，爬上那把椅子。\",\"crown\":\"来自拉丁语 corona「花冠、王冠」。古罗马的花冠（corona）既是凯旋的荣誉，也借自希腊语 korōnē「弯曲之物」的意象。后来 corona 兼指「冠冕」与解剖学、光学里的冠状物，日冕（corona）也是它。\",\"scepter\":\"来自希腊语 skēptron「手杖」，动词 skēptesthai 是「倚靠」。权杖的字面义是「倚靠的那根杖」：从牧人、老者手里的支撑，变成君主手中的权威象征。拼写中的 p 不发音，是法语 sceptre 的遗形。\",\"knight\":\"来自古英语 cniht「男孩、侍从、青年」，日耳曼语本族词（德语 Knecht 至今仍是「仆人」）。骑士的字面履历是升职记：从贵族家中的侍从小伙，到披甲效忠的阶层。拼写里沉默的 k 与 gh，都是古英语发音的遗迹。\",\"warrior\":\"war + 表人后缀构成。war 来自古法语 werre，是日耳曼语借词（原始义近于「混乱、争斗」）。武士的字面义是「以战争为业的人」；warrior 偏重个体的勇武，与 soldier（领饷服役者）的来历形成对照。\",\"spear\":\"来自古英语 spere，日耳曼语本族词（德语 Speer）。长矛是日耳曼老词，没有拉丁词根可拆，靠整体认读；它也是许多复合词的零件，如 spearhead（先锋，字面为矛头）。\",\"spearman\":\"spear + man 的透明复合词。持矛者在冷兵器方阵里是最基础的兵种；这类「武器 + 人」的复合（swordsman、bowman）是古英语构词的典型手法。\",\"shield\":\"来自古英语 scild，日耳曼语本族词。一说它与「分开的木板」有关（盾常以木板拼成），但细节未成定论。稳妥记法：盾牌是日耳曼老词，shield 兼作动词「遮护」——名词就是动作本身。\",\"sword\":\"来自古英语 sweord，日耳曼语本族词，更深来源不明。剑是日耳曼老词：拼写里的 w 在中古英语后不再发音，却留了下来。靠整体认读，不要硬拆。\",\"battle\":\"来自古法语 bataille，源于拉丁语 battualia「士兵的击剑操练」，动词 battuere 是「击打」。战役的字面起点在训练场：操练的击打变成真刀真枪。它与 batter（猛击）同出一源。\",\"warfare\":\"war + fare 的复合词，fare 来自古英语 faran「行进、经历」（与 welfare 的 fare 同一个）。战争的字面义是「战争这件事的全过程」：-fare 在这里指「行程与境况」，不只是打仗的一瞬。\",\"siege\":\"来自古法语 sege「座位、围坐」，源于拉丁语 sedere「坐」。围攻的字面义是「在城外坐下来」：大军坐守城池、断其补给，耗到城开。它属 sid / sess「坐」家族，与 subsidy（坐在后排的预备队）是同一条「坐」的线。\",\"retreat\":\"来自古法语 retraire，源于拉丁语 retrahere「拉回、撤回」：re- + trahere「拉」。撤退的字面义是「把队伍往回拉」；它与 tractor（拖拉机）、extract（拉出）同出 trahere 一家。它也指静修、退隐处——都是「退回去」。\",\"silk\":\"来自古英语 seolc，上溯拉丁语 sericum「丝织品」、希腊语 sērikon，源头 Sēres 是古希腊罗马对「产丝之国」（中国一带）的称呼。丝绸以产地之民命名：Seres 人的布。丝绸之路在英语里是 the Silk Road。\",\"spice\":\"来自古法语 espice，源于拉丁语 species「种类、外观」，后专指「货物、商品」。香料是中世纪贸易里最金贵的那类「货」：胡椒、肉桂皆按 species 统称。它与 species（物种）、special 同出一源——香料是最「特别」的那类货物。\",\"porcelain\":\"来自意大利语 porcellana。它原指一种表面光滑的宝螺贝壳；porcellana 又与 porcella「小母猪」相连，据说因贝壳形状相似得名。马可·波罗时代的人拿这种贝壳的光泽感给中国瓷器命名：瓷器的名字里，藏着一枚地中海贝壳。此说流传最广，细节仍有讨论。\",\"wheel\":\"来自古英语 hwēol，日耳曼语本族词，与希腊语 kyklos「圆圈」同出印欧语 *kwekwlo-「转动」。轮子是人类最老的发明词之一；cycle（循环）是它走希腊路线的远亲——圆与转，本是一个意象。\",\"plow\":\"来自古英语 plōh（又作 plough），日耳曼语词，可能更早借自某种阿尔卑斯地区的语言，确切来源存疑。犁在农业文明里地位极高：英语里量地单位 furlong 等旧词都与犁田有关。美式拼写 plow 更贴近读音。\",\"irrigation\":\"来自拉丁语 irrigare「引水浸润」：in- + rigare「浇水、灌溉」。灌溉的字面义是「把水引进田里」；irrigate 的对象既可是农田，也可是伤口（冲洗）——都是让液体流过表面。\",\"dam\":\"来自中古荷兰语 / 日耳曼语 dam「水坝」。水坝是低地国家的看家词：Amsterdam（阿姆斯特丹）即「阿姆斯特尔河上的坝」。dam 兼作动词「筑坝拦水」，拦住之后的水位与流量，就是水利工程的全部主题。\",\"canal\":\"来自拉丁语 canalis「管道、沟渠」，源于 canna「芦苇、竹管」（希腊语 kanna）。运河的字面义是「人工挖出的大管子」；它与 channel（水道）同出一源，一个走拉丁原形、一个走法语变体。耳道、根管在解剖学里也叫 canal。\",\"printing\":\"print 来自古法语 preinte「压印」，源于拉丁语 premere「压、挤」。印刷的字面义是「压出来的印记」：活字压上纸面，文字成批复制。它与 press（压；新闻业）、pressure 同出一源——印刷机在英语里就叫 printing press。\",\"paper\":\"来自拉丁语 papyrus，源于希腊语 papyros「纸莎草」——埃及人以莎草茎制纸，植物名变成了纸的通称。中国纸经阿拉伯传入欧洲后，沿用了这个埃及名字：词与物，各有各的故乡。\",\"scroll\":\"来自古法语 escroe「撕下的一条（皮纸、布）」，是日耳曼语借词。卷轴的字面义是「一条」：先有条状的书写材料，才有卷起来读的形式。今天屏幕上的 scroll（滑动）借的正是展开卷轴的动作。\",\"scribe\":\"来自拉丁语 scriba「书记员」，动词 scribere 是「写、刻」。抄写员的字面义是「以写为职的人」；在印刷术之前，文明靠 scribe 一笔一笔续命。它属 scrib「写」家族（script、describe、inscription）。\",\"inscription\":\"来自拉丁语 inscriptio：in-「在……之上」+ scribere「写、刻」。铭文的字面义是「刻在（石头、金属）上面的字」：写给千年之后的读者，材料先要比纸长寿。它与 scribe 同出 scrib 家族。\",\"tablet\":\"来自古法语 tablete「小板」，是拉丁语 tabula「木板、写字板」的小称。泥板、石板本质都是「板」：tabula 是罗马人的写字板，tablet 把尺寸缩小随身带。现代 tablet（平板电脑）是这个隐喻的第二次转世；table（桌子）与它同源。\",\"weaving\":\"weave 来自古英语 wefan，日耳曼语本族词（德语 weben）。织造靠整体认读：经纬交错的画面全在动作里。它派生的 web（网；后指万维网）是织物意象的现代回声。\",\"spinning\":\"spin 来自古英语 spinnan「抽丝、纺线」，日耳曼语本族词。纺纱的字面动作是「拉出一条线」；冷知识：spider（蜘蛛）的古义正是「纺织者」。spin 后来兼指旋转——纺锤的转动太深入人心。\",\"metallurgy\":\"来自希腊语 metallourgos「采矿与炼金的人」：metallon「矿山、金属」+ ergon「工作」。冶金学的字面义是「跟金属打交道的工」；ergon 也在 energy（能量，原义「运作」）里出现——工作，是这条词根线的核心。\",\"mining\":\"mine 的确切来源存疑：一般认为经古法语 mine 进入英语，可能源于凯尔特语，或与拉丁语 minare「引导、驱赶（牲口下井道）」有关，未成定论。可以确定的是：采矿与「我的」（mine 所有格）只是同形，毫不相干。\",\"domestication\":\"来自拉丁语 domesticus「家里的」，源于 domus「家、房屋」。驯化的字面义是「领进家门」：野生动植物搬进人类屋檐下，几代之后性情与形态都被「家」重塑。它与 domestic、dome 同出 domus 一家。\",\"olympic\":\"来自希腊地名 Olympia「奥林匹亚」——宙斯圣地与古代奥运会的举办地，在伯罗奔尼撒半岛西部。Olympic 是纯粹的地名形容词；注意它与 Olympus（奥林匹斯山，众神住所）是两个地方，别混。\",\"marathon\":\"来自希腊地名 Marathon（马拉松平原）。公元前 490 年希军在此击败波斯；传说传令兵一路跑回雅典报捷、力竭而死——但要注意：史家希罗多德记载的是战前派人跑往斯巴达求援，「报捷跑」是后世演绎的版本。1896 年首届现代奥运会据此传说设立长跑，马拉松由此得名，1921 年定为 42.195 公里。\",\"myth\":\"来自希腊语 mythos「话语、叙述、故事」。它起初不带真假色彩，指一切口耳相传的叙事；后来与 logos（理性论说）分工，才专指「神话、虚构的故事」。myth 的今义是历史分工的结果。\",\"epic\":\"来自希腊语 epos「言辞、歌、叙事诗」+ -ic。史诗的字面义是「被吟诵出来的长歌」：《伊利亚特》先是歌，后是书。今天 epic 也作口语形容词指「宏大的」——词义仍在膨胀。\",\"saga\":\"来自古诺尔斯语 saga「叙述、所说之事」，动词 segja 是「说」。萨迦是冰岛中世纪的家族传奇散文：一个「说」字撑起整个文类。它与英语 say 同出日耳曼语 *sag-「说」。\",\"ritual\":\"来自拉丁语 ritus「仪式、惯例」+ -al。ritus 的更深来源存疑，一说与「计数、秩序」有关，未成定论。可以确定的是它在古典拉丁语里专指「按规矩举行的宗教仪式」——仪式的核心不是动作，是「照着规矩」。\",\"ceremony\":\"来自拉丁语 caerimonia「神圣性、宗教敬畏、仪式」。它的确切来源存疑：古人曾把它与伊特鲁里亚城市 Caere 联系，现代学者多持保留。典礼一词的古老程度超过了我们能确证的范围，老实标注存疑即可。\",\"sacrifice\":\"来自拉丁语 sacrificium：sacer「神圣的」+ facere「做」。祭祀的字面义是「把（供品）做成神圣的」：献祭即所有权的转移，从人间转给神明。它扩展出的「牺牲、舍弃」义保留着这层交换结构。它与 sacred 同出 sacer。\",\"worship\":\"来自古英语 weorþscipe：weorþ「价值、尊贵」+ -scipe「状态」（即现代 -ship）。崇拜的字面义是「承认其价值」：先有「值得尊敬」，后专指对神的敬拜。它是纯粹的日耳曼复合词，与 ship（船）无关，别被词形骗了。\",\"pilgrim\":\"来自拉丁语 peregrinus「外国人、远行者」：per-「穿过」+ ager「田野」。朝圣者的字面义是「穿越异乡田野的人」；它经古法语 pelerin 变形入境。它与 agriculture 的 ager（田地）同源——朝圣之路，两边全是田野。\",\"crusade\":\"来自西班牙语 cruzada / 古法语 croisade，源于拉丁语 crux「十字」。十字军东征的字面标记就在胸前：士兵衣上缝十字，表明为信仰出征。crusade 后来也比喻「为正义事业的长期奋斗」；它与 cross、crucial（十字路口→关键的）同出 crux。\",\"painting\":\"paint 来自古法语 peindre，源于拉丁语 pingere「描绘、上色」。绘画的字面义是「把颜色抹上去」；它与 pigment（颜料）同出 pingere，picture 也在近支——一个词根分管了颜料、画作与图像。\",\"sketch\":\"经荷兰语 schets、意大利语 schizzo 进入英语，上溯拉丁语 schedius「即兴的、临时的」（希腊语 schedios）。素描的字面义是「即兴抓下来的稿」：贵在快，不在全。这也解释了 sketch 兼指小品、梗概——都是「纲要版」。\",\"canvas\":\"来自古法语 canevas，源于拉丁语 cannabis「大麻」。画布起初确是大麻粗布：结实、耐张，做船帆也做画布。canvas 因此兼指帆布与油画本身（a canvas 即一幅油画）；它与 cannabis 是同一个词的纺织支线。\",\"palette\":\"来自法语 palette「小铲、小薄板」，源于 pale「铲」，再上溯拉丁语 pala「锹」。调色板的字面义是「小铲子（形状的板）」：大拇指扣住的那块板，原型是一把扁锹。\",\"brush\":\"来自古法语 broisse「灌木丛、枝条束」，与 broce「灌木」同族，更深来源不甚明朗。画笔的字面起点是「一束枝条」：最早的刷子就是捆扎的植物枝。brush 因此兼指刷子、灌木丛与「轻触」——词形把三段历史装在了一起。\",\"pigment\":\"来自拉丁语 pigmentum「颜料、染料」，源于 pingere「描绘、上色」。颜料的字面义是「用来画的东西」；生物学里的 pigment（色素）是同一逻辑：让皮肤、羽毛显色的物质。它与 painting 同根。\",\"watercolor\":\"water + color 的透明复合词。color 源于拉丁语 color「颜色、肤色」，其更深来源有争议，一说与 celare「遮盖」有关（颜色是覆在表面的一层），未成定论。水彩的字面义老实得很：用水调和的颜色。\",\"oil\":\"来自古法语 oile，上溯拉丁语 oleum「橄榄油」，源于希腊语 elaion（elaia「橄榄树」）。油画（oil painting）的颜料以油为媒剂，故名；oil 的石油义是后来居上——地下的「油」借了厨房的词。\",\"mural\":\"来自拉丁语 murus「墙」+ -al。墙画的字面义是「（画）在墙上的」：位置即定义。它与 immure（禁闭，字面为「关进墙内」）同出 murus——墙在拉丁语里既能挂画，也能关人。\",\"sculptor\":\"来自拉丁语 sculptor，动词 sculpere 是「刻、凿」。雕塑家的字面义是「拿凿子的人」；sculpere 的动作只管减法：把多余的石头去掉，形象自己走出来。它与 sculpture 同门。\",\"statue\":\"来自拉丁语 statua，动词 statuere 是「竖立、设立」，源于 stare「站」。雕像的字面义是「被立起来的（人像）」：它与 state、statue、stature 同出 sta「站」家族——立像先要「站得住」。\",\"bust\":\"来自意大利语 busto / 法语 buste「躯干、半身像」。确切来源有争议：一说与拉丁语 bustum「火葬堆、坟墓」有关（立于墓上的像），未成定论。可以确定的是它 17 世纪才进入英语，专指头胸段的肖像雕塑。\",\"curator\":\"来自拉丁语 curator「照管人、管理者」，动词 curare 是「照料」，名词 cura「操心、照管」。馆长的字面义是「照看藏品的人」——注意：这是「照料」的 cur 家族（同 cure、security），与 current 里「跑」的 curr 完全是两回事，正好对照着记。\",\"masterpiece\":\"master + piece 的复合词，一般认为是荷兰语 meesterstuk / 德语 Meisterstück 的仿译：行会学徒出师时提交的「证明师傅水准的作品」。杰作的字面义是「资格考试作品」：先过行会这一关，才轮到后世喝彩。\",\"style\":\"来自拉丁语 stilus「（写字用的）尖笔、铁笔」。风格的字面轨迹是：笔 → 笔法 → 文风 → 一切 manner。它拼写里的 y 是受希腊语 stylos「柱子」误导而改的——又一个被写错却沿用至今的词形。\",\"technique\":\"来自希腊语 tekhnikos，源于 tekhnē「技艺、手艺、艺术」。技法的字面义是「手艺人的那套本事」：在希腊语里，木匠活与艺术创作共用 tekhnē 一词。它与 technology、architect（tekton「木匠」+ arkhi「首」）同门。\",\"composition\":\"来自拉丁语 compositio「拼合、构成」：com-「一起」+ ponere「放」。构图、作文、作曲在英语里同叫 composition，因为本质是同一个动作——把部件「放到一起」。它与 component、position 同出 ponere。\",\"symmetry\":\"来自希腊语 symmetria：syn-「共同」+ metron「尺度、测量」。对称的字面义是「用同一把尺量得齐」：古希腊人用它指比例协调，不限于镜像。它与 meter、geometry 共享 metron 这把「尺」。\",\"texture\":\"来自拉丁语 textura「织法、结构」，动词 texere 是「编织」。质感的字面义是「织出来的纹理」；它与 text 同根——文字在拉丁人的想象里也是「织」出来的：text 是织好的词句，texture 是织好的表面。\",\"color\":\"来自拉丁语 color「颜色、外观」。它的更深来源有争议：一说与 celare「遮盖」同源（颜色是覆于表面之色），语言学上未成定论。记到 color 这一层最稳妥；拼写 -or 是美式简化，英式保留 colour。\",\"shade\":\"来自古英语 sceadu「阴影、荫凉」，日耳曼语本族词（德语 Schatten）。阴影与 shadow 是同一词的两种古形分化：一个偏指「色调深浅」，一个偏指「物体的影子」。画家的 shade（加深）正是往暗处走的那一格。\",\"tone\":\"来自希腊语 tonos「绷紧、音高」，动词 teinein 是「拉伸」，经拉丁语 tonus 进入英语。色调的字面起点是琴弦：弦绷得越紧，音越高；声音的「调」被借去说颜色的「调」与文气的「调」。它与 tend（伸展）家族同源。\",\"sketchbook\":\"sketch + book 的复合词（sketch 的来历见 sketch 条）。book 来自古英语 bōc，传统上认为与 beech（榉树）同源——日耳曼人曾在榉木板上刻字。素描本的字面义是「速写 + 木板书」，两层都是速记的工具史。\",\"easel\":\"来自荷兰语 ezel「驴」。画架的字面义是个比喻：一头驮着画布默默站立的「驴」。德语 Staffelei 也同源于此。动物命名工具，在欧洲语言里并不罕见——起重机 crane 也是鸟名。\",\"studio\":\"来自意大利语 studio，源于拉丁语 studium「热忱、研习」，动词 studere 是「用功、钻研」。工作室的字面义是「做学问的地方」：先属学者，后归画家，再归摄影师与电影厂。它与 study、student 同门。\",\"model\":\"来自意大利语 modello，源于拉丁语 modulus「小尺度、样本」，是 modus「尺度、方式」的小称。模特的字面义是「供照着做的样本」：先有建筑师的模型，再有画家的模特。它与 mode、moderate、mold 同出 modus 一家。\",\"cinema\":\"是 cinématographe 的缩略，源于希腊语 kinēma「运动」（kinein「动」）。电影的字面义是「把运动记录下来」——1895 年卢米埃尔兄弟以此命名放映机。它与 kinetic（运动的）同根；英式 cinema 指影院，美式多说 movie theater。\",\"director\":\"来自拉丁语 dirigere「指直、引导」：dis- + regere「拉直、统治」+ -or。导演的字面义是「把方向掰直的人」；公司董事也叫 director——同样是「掌方向」的职位。它与 direct 同门，regere 还通向 royal 一系。\",\"stage\":\"来自古法语 estage「站立处、楼层、台架」，上溯俗拉丁语 *staticum，源于 stare「站」。舞台的字面义是「站人的台子」；它与 state、statue 同出 sta「站」家族。stage 兼指「阶段」——人生如台，一层一层往上站。\",\"audience\":\"来自拉丁语 audientia「倾听、听审」，动词 audire 是「听」。观众的字面义是「听的人」：戏剧最初是给耳朵的艺术。它与 audio、audition（试镜，原义试听）同出 aud「听」家族。\",\"performance\":\"perform 来自古法语 parfournir「彻底完成、备齐」：par-「彻底」+ fournir「提供、装备」。要紧的纠正：perform 不是 per- + form 拼成的，它的今形是后来受 form 影响改的。表演的字面义是「把一件事做满、做完」——演出是把排练「履行」出来。\",\"rehearsal\":\"rehearse 来自古法语 rehercier「再耙一遍」：re-「再」+ hercier「耙地」（拉丁语 hirpex「耙」）。排练的字面义是农活：把同一块地再耙一遍，直到平整。它与 hearse（灵车，原指耙形烛台）的纠葛是另一段暗线，现今只记「再耙一遍」即可。\",\"script\":\"来自拉丁语 scriptum「写成的东西」，动词 scribere「写」。剧本的字面义就是「写下来的那份」；它属 scrib「写」家族（scribe、inscription），计算机里的 script（脚本）借的也是「照着念/照着执行」这层意思。\",\"plot\":\"来自古英语 plot「一小块土地」。情节义的演变路径细节有争议：约在 16 世纪，plot 先有「计划、图谋」义（或与 plan 的图形义交汇），再转指戏剧、小说的「情节线」。可以确定的是起点在土地：先有地块的划分，才有故事的布局。\",\"protagonist\":\"来自希腊语 prōtagōnistēs：prōtos「第一」+ agōnistēs「演员、竞赛者」（agōn「竞赛、集会」）。主角的字面义是「头号演员」：古希腊戏剧里第一个出场与命运缠斗的人。注意它不是 pro- + antagonist 的反义拼凑。\",\"narrator\":\"来自拉丁语 narrare「讲述」+ -or。narrare 源于 gnarus「知道的、内行的」：叙述者的字面义是「那个知道内情并说出来的人」。它与 ignorant（不知道的）是同一词根的正反面。\",\"dialogue\":\"来自希腊语 dialogos：dia-「穿过、往来」+ logos「言辞、道理」。对话的字面义是「话在两人之间穿行」；dia- 在这里不是「二」，是「贯穿」。柏拉图的对话录让这个词成了文体名。它属 log「言辞」家族。\",\"monologue\":\"来自希腊语 monologos：monos「单独」+ logos「言辞」。独白的字面义是「一个人说的话」；它与 dialogue 结构对照鲜明——mono- 换 dia-，满场只剩一个声音。它与 monastery 共享 monos「单」。\",\"soliloquy\":\"来自拉丁语 soliloquium：solus「单独的」+ loqui「说」。自言自语的字面义是「独自一人时说的话」，本是奥古斯丁一部神学著作的标题，后被戏剧借去指角色独白。它属 loqu「说」家族（eloquent、loquacious）。\",\"poetry\":\"来自希腊语 poiēsis「制作、创作」，动词 poiein 是「做、造」。诗歌的字面义是「被做出来的东西」：在希腊人眼里，诗人首先是匠人。它与 poet 同源；亚里士多德的《诗学》原名就是 Poiētikē——「论制作」。\",\"poet\":\"来自希腊语 poiētēs「制作者、诗人」，源于 poiein「做」。诗人的字面义是「做东西的人」：做的是诗行。它经拉丁语 poeta、古法语 poete 进入英语；maker 在古英语里曾是 poet 的对应词，同样直白。\",\"verse\":\"来自拉丁语 versus「犁沟的一行；转行」，动词 vertere 是「转」。诗句的字面义在田里：犁到地头要「转」回来，诗行写到头也要「转」下去。它与 version（版本，转译）、convert（转）同出 vert「转」家族。\",\"rhyme\":\"来自古法语 rime，其来源与两条线交汇：拉丁语 rhythmus（希腊语 rhythmos「节奏」）与日耳曼语 *rīm「数列、顺序」。中古英语里它常拼作 rime；今天的 rhyme 拼法是受 rhythm 牵引的「雅化」。押韵与节奏，在词形里本就是亲戚。\",\"rhythm\":\"来自希腊语 rhythmos「测度、节奏」，动词 rhein 是「流动」。节奏的字面义是「流动的节制」：水无序是流，有序地流便是 rhythm。它与 rheumatism（风湿，古人以为体液流动致病）同出 rhein——流，是这条线的底。\",\"stanza\":\"来自意大利语 stanza「房间、停驻处」，上溯俗拉丁语 *stantia，源于 stare「站」。诗节的字面义是「一间房」：诗在一节里「停下」喘口气，再进下一间。它与 stage、statue 同出 sta「站」家族。\",\"simile\":\"来自拉丁语 simile「相似之物」，形容词 similis 是「像、相似」。明喻的字面义是「拿相似的东西来比」；它与 similar 同门——simile 是修辞格的名字，similar 是日常形容词。\",\"imagery\":\"image + -ery 构成。image 来自拉丁语 imago「肖像、影像」，与 imitari「模仿」同族：影像是对实物的「摹本」。意象的字面义是「影像的集合」；文学里的 imagery 正是让读者在脑中成像的那组词。\",\"symbolism\":\"来自希腊语 symbolon「信物、标记」：syn-「合」+ ballein「投、掷」。古人把信物掰成两半，见面时「合在一起」验明身份——symbol 的字面义是「合得上的那一半」。象征主义由此得名：意义藏在「对得上」的另一半里。problem（掷到面前的难题）与它同出 ballein。\",\"biography\":\"来自希腊语 biographia：bios「生命、人生」+ graphein「写」。传记的字面义是「把一个人的一生写下来」；它与 biology（生命之学）、graphic（书写的→图像的）同门——bio 管生命，graph 管落笔。\",\"autobiography\":\"auto-「自己」+ biography 的复合新造词，18 世纪末才在英语里定型。自传的字面义是「自己写自己的一生」：构词全是希腊零件，成词却很晚——文体意识比词更年轻。\",\"prose\":\"来自拉丁语 prosa (oratio)「直行的言辞」，形容词 prorsus 是「径直向前」（pro- + versus「转」）。散文的字面义是「不拐弯、直着走的话」，与 verse（要转行的诗句）正成对照：一个直行，一个回转。\",\"opera\":\"来自意大利语 opera「作品」，源于拉丁语 opera「劳动、成果」（opus 的复数形式被当作单数用）。歌剧的字面义是「（音乐的）作品」——1600 年前后佛罗伦萨人复兴古希腊戏剧时的产物。它与 opus、operation 同出一源。\",\"ballet\":\"来自法语 ballet，源于意大利语 balletto「小舞蹈」，是 ballo「舞会、舞蹈」的小称；ballare「跳舞」出自晚期拉丁语。芭蕾的字面义是「小小的舞」：词形一路缩小，舞台上的分量却越来越大。\",\"orchestra\":\"来自希腊语 orkhēstra「（剧场中）供歌舞队表演的场地」，动词 orkheisthai 是「跳舞」。乐队的字面义本是块地：古希腊剧场里合唱队载歌载舞的那片半圆区；乐器搬进来坐定之后，地名让给了乐队。\",\"composer\":\"compose「作曲、构成」+ -er。compose 来自古法语 composer，上溯拉丁语 componere「放在一起」：com- + ponere「放」。作曲家的字面义是「把音符放到一起的人」，与 composition（构图）是同一套动作。\",\"symphony\":\"来自希腊语 symphōnia：syn-「共同」+ phōnē「声音」。交响乐的字面义是「声音合在一起」：起初泛指和声、协奏，18 世纪后固定为管弦乐的大型体裁。它与 telephone 的 phon（声音）同门。\",\"melody\":\"来自希腊语 melōidia「歌唱、曲调」：melos「歌、乐曲」+ ōidē「歌曲」。旋律的字面义是「唱出来的调子」；ōidē 也在 ode（颂诗）与 comedy（喜剧，原义「狂欢之歌」）里出现——一首歌的零件，散在好几个文体名里。\",\"chorus\":\"来自希腊语 khoros「歌舞队、环舞」，经拉丁语 chorus 进入英语。合唱的字面义是「一队人边舞边唱」：古希腊戏剧的歌队既是演员，也是评论员。副歌叫 chorus，因为那是全场齐唱的部分。\",\"software\":\"soft + ware 的复合词，1958 年由统计学家图基（John Tukey）首次见诸文字，与 hardware 对举。ware 来自古英语 waru「货物」（见 warehouse 条）：软件的字面义是「软的那批货」——摸不着的货物。\",\"program\":\"来自希腊语 programma「告示、纲要」：pro-「在前」+ graphein「写」。节目的字面义是「预先写出来贴给大家看的单子」；计算机程序继承的是「预先写好的指令单」。它属 graph「写」家族，与 biography 的后半同源。\",\"code\":\"来自拉丁语 codex「法典、册子」，原指装订成册的木板书，源于 caudex「树干、木块」。代码的字面轨迹是：木块 → 书册 → 法典 → 密码与程序。法典与代码同名，因为两者都是「成套的规定」；摩尔斯电码用的也是这层意思。\",\"database\":\"data + base 的复合词，1960 年代计算机业成形。data 是拉丁语 datum「被给出的东西」的复数（dare「给」）。数据库的字面义是「存放既定资料的底座」；datum 也在 tradition、referendum 的 dare 线上——「给」是这一家的老动作。\",\"internet\":\"是 internetwork 的缩略：inter-「之间」+ network「网络」。1970 年代为连接多个独立网络而造，原指「网际互联」的构想，后专指最大的那一个。net 来自古英语「网」，日耳曼老词；词是新的，零件很古。\",\"website\":\"web + site 的复合词，1990 年代随万维网普及。site 来自拉丁语 situs「位置、场所」，源于 sinere「放置、允许」。网站的字面义是「网上的一个位子」；web 本义「织物」，与 weaving 同出日耳曼语的「织」。\",\"browser\":\"browse 原指「啃食嫩芽」：来自古法语 brouster（broust「嫩芽」）。浏览器的字面轨迹很形象：牲口一路啃嫩芽 → 人随手翻书「啃」信息 → 软件替你翻网页。1990 年代的 browser 把啃食的节奏交给了鼠标。\",\"server\":\"serve + -er。serve 来自古法语 servir，源于拉丁语 servire「服侍」，名词 servus 是「奴隶、仆人」。服务器的字面义是「侍者」：你点菜（请求），它端上来（响应）。它与 service、conservative 的 serv 是同一词根的明暗两面。\",\"user\":\"use 的派生词。use 来自古法语 user，上溯拉丁语 uti「使用」的过去分词 usus。用户的字面义平平无奇——「使用的人」；但在计算机语境里，它与「使用者权利」的讨论绑定，是数字时代的核心词之一。\",\"decryption\":\"de-「去除」+ crypt「隐藏」+ -ion，是 20 世纪密码学造的新词。crypt 源于希腊语 kryptos「隐藏的」、kryptein「藏」。解密的字面义是「把藏起来的东西解开」；crypt 作名词另指地下墓穴——藏，人与信息用的是同一个希腊词根。\",\"backup\":\"back + up 的短语动词名词化，20 世纪成词，计算机义在 1950 年代后普及。备份的字面义是「顶在后面的（支援）」：back up 本指「在后支援」，数据备份就是给文件留一个「后援」。\",\"storage\":\"store + -age。store 来自古法语 estor「储备、补给」，上溯拉丁语 instaurare「重建、备置」。存储的字面义是「把东西备置起来（以备后用）」；它与 restaurant 的 restaurare 是近亲——一个备货，一个「恢复」元气，都含「重新备好」的意思。\",\"processor\":\"process + -or。process 来自拉丁语 processus「前进、进程」，动词 procedere 是 pro-「向前」+ cedere「走」。处理器的字面义是「让（数据）向前走的东西」；它与 recession（向后走）正成一对：cess / cede 家族里全是脚步。\",\"chip\":\"来自古英语相关形式（与德语 kipfen「切」同族），本义是「切下的一小片、碎屑」，日耳曼语源。芯片义诞生于 1960 年代：集成电路薄薄一小片，正像木头上削下的 chip。词很老，义很新。\",\"sensor\":\"20 世纪初的新造词：拉丁语 sentire「感觉」+ -or「器物」。传感器的字面义是「感觉的器官（人造版）」；它与 sense、sentence 同出 sentire——机器的感觉，先从这个词根借词。\",\"robot\":\"来自捷克语 robota「苦役、强制劳动」。1920 年捷克作家恰佩克在剧作《R.U.R.》中用 robot 指人造劳工（词形由其兄约瑟夫建议），次年英译后传遍世界。机器人的名字里写着它的出身：为服苦役而造。\",\"automation\":\"由 automatic 派生，源于希腊语 automatos「自动的、自发的」：autos「自己」+ -matos（与「意愿、冲动」相关）。automation 一词 1940 年代在美国汽车工业（福特）语境中定型，指整条产线的自动运转——不只是机器自动，而是系统自动。\",\"machine\":\"来自法语 machine，上溯拉丁语 machina、希腊语 mēkhanē「装置、巧计、机械」。机器的字面义是「人为的巧装置」：希腊语里它也指舞台上吊起神明的机关（「机械降神」deus ex machina 即此）。它与 mechanic 同源。\",\"neural\":\"来自希腊语 neuron「腱、弦、神经」+ -al。neuron 在古希腊语里先指「筋与弦」，解剖学借它命名神经——形状都是细长的索。神经网络（neural network）的命名正是把大脑的「索网」借给算法；nerve 是它走拉丁语路线的亲戚（nervus）。\",\"modeling\":\"model 的动名词（model 的来历见 model 条：拉丁语 modulus「小尺度、样本」）。建模的字面义是「先做一个小尺度的样本」：无论黏土、数学公式还是神经网络，都是先立样本，再推真实。\",\"virtual\":\"来自拉丁语 virtualis，源于 virtus「力量、效能、德性」，再上溯 vir「男人」——virtus 的老义是「男子气概、勇武」。虚拟的字面义是「有效能但无实体」：中世纪哲学里指「以效果存在」；1950 年代后的计算机义（virtual memory 虚拟内存）继承的正是这一层。\",\"reality\":\"来自拉丁语 realis「与事物有关的」，源头 res 是「东西、实物」。中世纪哲学把 res（实存之物）和脑中的观念相对照，real 一词就带上了「真实存在」的分量；reality 是这份「实存」的状态，virtual reality 的「现实」也从这里来。\",\"augmented\":\"augment 来自拉丁语 augere「增加、使长大」（名词 augmentum「增量」），与希腊语 auxein「增长」同源。augmented reality「增强现实」是 1990 年前后造出的说法：不替换现实世界，只在真实画面上叠加数字信息——「增强」正是 augere 的本行。\",\"digital\":\"digit 来自拉丁语 digitus「手指、脚趾」。古人掰着手指数数，digitus 先兼指「个位数、数字」，再到「数码」；digital 就是「用离散数字（0 和 1）表示信息」的，与之相对的 analog 是连续量。\",\"signal\":\"来自拉丁语 signum「标记、记号」，经晚期拉丁语 signale、古法语 seignal 进入英语。战场上约定的号声、旗语都是 signum；电报、无线电时代，这个词顺势接管了一切「用电波送出的记号」。\",\"transmission\":\"来自拉丁语 transmittere：trans-「横过、到对岸」+ mittere「送、派」。先是「把东西送过去」，19 世纪又指机器里把动力传到车轮的传动装置，电报、广播时代再扩展到信号的传送——mittere 家族（mission、admit 等）都是「送」。\",\"bandwidth\":\"band「频带」+ width「宽」的现代合成词。band 在无线电里指一段频率范围（这个 band 与乐队、带子的 band 拼写相同、来源不同），带宽本义是「频带有多宽」；20 世纪中叶起被借去形容数据通道的吞吐能力。\",\"protocol\":\"来自希腊语 prōtokollon：prōtos「第一」+ kolla「胶水」——粘在纸草卷最前面、写着出处与内容的第一页。由「卷首凭证」变成外交场合的礼仪成规，再变成计算机之间必须共同遵守的通信规则，三步都是「开头的约定」。\",\"operating\":\"operate 来自拉丁语 operari「工作、运作」，源头 opus 是「工作、作品」（opera 歌剧本义也是「作品」）。operating system「操作系统」是 20 世纪 60 年代的说法：让整台机器「运转起来」的那套软件。\",\"mobile\":\"来自拉丁语 mobilis「可移动的」，源头 movere「移动」（move 的祖先）。mobile phone 是 mobile telephone 的简称：能带着走的电话。mob「暴徒」也出自 mobilis——拉丁语里 mobile vulgus 就是「易变的乌合之众」。\",\"laptop\":\"lap「大腿面」+ top「顶部」的 20 世纪 80 年代合成词：放在腿上用的电脑，与 desktop「放在桌面上的」成对出现。desktop 先有，laptop 是照它的样子仿造的。\",\"desktop\":\"desk「书桌」+ top「面」。先指「桌面」本身，20 世纪 80 年代图形界面借它作比喻：屏幕就是一张办公桌，文件、文件夹摊在上面；后来又转指放在桌上的台式机。\",\"keyboard\":\"key「按键」+ board「板」。键盘先是乐器（钢琴、风琴）的部件，打字机沿用，电脑再接手。key 本身是古英语 cǣg，来源已不甚明朗——这个小词的词源是个悬案，诚实标注：无定论。\",\"mouse\":\"古英语 mūs，日耳曼语固有词，指啮齿动物本身。1960 年代道格拉斯·恩格尔巴特团队给手持定位设备起名 mouse：圆滚滚的身子拖着一根线，像老鼠拖着尾巴——昵称叫顺了口，就成了正式名。\",\"printer\":\"print 来自拉丁语 premere「压」：经古法语 preinte 指「压出的印记」。印刷就是把版面压到纸上；printer 先指印刷工，再指印刷机，20 世纪 50 年代又接管了计算机的打印设备。\",\"scanner\":\"scan 来自拉丁语 scandere，本义「攀登」，在诗律学里指「按音步逐个拆解诗句」。于是 scan 有了「逐行细查」的核心动作：雷达扫描、医学扫描、把纸面逐行读进电脑，都是同一种「一行行地过」。\",\"drone\":\"古英语 drān 是「雄蜂」：不采蜜、不蜇人，只发出嗡嗡声。20 世纪 30 年代，无人驾驶的靶机因嗡嗡作响又任人遥控，得了这个名字；民用无人机沿用至今。drone 作动词「嗡嗡响、低吟」也是同一条线。\",\"rocket\":\"来自意大利语 rocchetta，是 rocca「纺锤、绕线杆」的小称——早期火箭筒细长如纺杆，故名，经法语 roquette 进入英语。中国的火药火箭出现得更早，但 rocket 这个名字是意大利人按形状起的。\",\"spacecraft\":\"space「太空」+ craft 的合成词。craft 本义「技艺、力量」，在 boat 一类词里转指「船、器」（aircraft 是先行的例子）；20 世纪初科幻作品造出 spacecraft，50 年代航天时代正式启用，指一切人造飞行器。\",\"optic\":\"来自希腊语 optikos「视觉的」，源头 optos「被看见的」、ops「眼睛」。optics 光学研究光如何被人看见；optical fiber 光纤是 20 世纪的新词，但词根还是古希腊的「眼」。\",\"panel\":\"来自拉丁语 pannus「布」，经古法语 panel 先指「一小块布、马鞍垫」，再指镶嵌用的一块板、写在羊皮纸条上的陪审员名单（panel 由此有「专家组」义），最后指仪表板、控制面板。一块布走出了三条路。\",\"wind\":\"古英语 wind，日耳曼语固有词，与拉丁语 ventus（vent 通风口的来源）、weather 一样，都源于印欧语根 *h₂weh₁-「吹」。风这个词在欧洲各语言里本是一家人，英语留了日耳曼的拼法。\",\"vehicle\":\"来自拉丁语 vehiculum，源头 vehere「运载、搬运」。印欧语根 *weǵʰ-「移动、运载」在英语里还留下 wagon（运货马车）——vehicle 与 wagon 隔着拉丁和日耳曼两条路，其实是远房同族。\",\"engine\":\"来自拉丁语 ingenium「天生的才智、巧思」，经古法语 engin 先指「巧妙的装置、攻城器械」。engine 的第一义是「聪明」，然后才是「把聪明做出来的机器」；engineer 最初就是造攻城器械的工程师。\",\"brake\":\"词源有争议，未有定论。一说源于中古荷兰语 / 中古低地德语 brake，指套在马鼻上、让马停步的笼头；由「勒住马的器具」转指一切制动装置。本条按诚实标注：主流辞书均标为来源不确定。\",\"steering\":\"steer 来自古英语 stēoran「驾驶、引导（船）」，源头 stēor 是「舵、引导」——方向盘、舵轮管的还是古人那件事：给船定方向。注意作名词「小公牛」的 steer 拼写相同，却是另一个词（古英语 stēor，年轻的公牛）。\",\"navigation\":\"来自拉丁语 navigare：navis「船」+ agere「驱动」——本义就是「开船」。指南针、大航海让它成为「航海术」的正名；飞机、汽车乃至手机界面里的「导航」，都是开船这件事的延伸。\",\"radar\":\"20 世纪的字母缩略词：1940 年由美国海军造出，取 RAdio Detection And Ranging「无线电探测与测距」的首字母；正读反读相同的回文拼法是刻意设计，方便记忆与保密。\",\"wireless\":\"wire「电线」+ -less「没有…的」，19 世纪末的合成词。电报、电话都要拉线，马可尼的「无线电报」偏偏不用线——wireless 先指无线电报与广播，手机时代又回潮指一切无线连接。\",\"bluetooth\":\"得名于 10 世纪丹麦国王哈拉尔「蓝牙」（Haraldr blátǫnn）：他统一了丹麦与挪威的部族。1997 年英特尔工程师吉姆·卡达赫提议用他的名字给短距离无线标准命名——像国王联合部族一样联合各种设备；标志正是其名首字母 H 与 B 的北欧如尼文叠写。至于国王为何叫「蓝牙」，一说源于他一颗发暗的坏牙，未有定论。\",\"wifi\":\"1999 年由品牌咨询公司仿照 hi-fi（high fidelity「高保真」）造出的商标名，朗朗上口而已。常听到的 Wireless Fidelity 其实是事后附会的说法：Wi-Fi 联盟官方从未把它当作缩略词，本条按实情标注——Wi-Fi 不是任何词的缩写。\",\"assure\":\"来自拉丁语 securus「安心的、无忧的」（se-「离开、没有」+ cura「忧虑、照料」），经古法语 aseürer「使安心、担保」进入英语。所以 assure 的底层是「让人把心放下」；它和 secure、security 是同一家人（cur 的「照料」义），与 current 的 curr「跑」无关。\",\"attach\":\"经古法语 atachier「钉住、系上」进入英语，再往上是日耳曼语的 *stak-「木桩」（法语 estache「桩」）。把东西钉在桩上就是 attach；attaché「使馆随员」也是「被派驻、系在某处的人」。注意它和 attack 本是同源的双生词。\",\"attack\":\"来自意大利语 attaccare「系上、投入战斗」，与 attach 出自同一条「钉住、系住」的根：先有「扑上去缠住对手」，才有「攻击」。attach 与 attack 在词源上是一对分了家的同源词——一个系附件，一个系战斗。\",\"attend\":\"来自拉丁语 attendere：ad-「朝向」+ tendere「伸展」。把注意力「伸向」某处，就是出席、到场与专心；attention 是同一动作的名词。tend「伸展」也在 extend、tension 里。\",\"augment\":\"来自拉丁语 augere「增加、使长大」，与希腊语 auxein 同源；英语土生的 eke（eke out「勉强维持」）也是它的远亲。augment 是把已有的东西再往上添，和 increase 是近义，但血统上更靠近 author——auctor「创始者」同样出自 augere「使生长」。\",\"authenticate\":\"来自希腊语 authentikos「真实的、原件的」，源头 authentēs 是「亲手做事的人、主事者」（autos「自己」+ 表「做事者」的词尾）。由本人亲手做的，才叫 authentic；authenticate 就是验明「这是不是本人亲手的那一份」。\",\"authorise\":\"authorize 的英式拼写。词干 author 来自拉丁语 auctor「创始者、增进者」（augere「使增长」）；后缀 -ize 来自希腊语 -izein，英式书写常把这个 -ize 写成 -ise，于是同一动词有了 authorise 与 authorize 两副面孔，美式只认后者。\",\"authorize\":\"author（拉丁语 auctor「创始者」，源头 augere「使生长」）+ -ize。auctor 是「让事情生长出来的人」，由此有「作者」也有「权威」；authorize 就是把 auctor 的分量借给别人——授权。\",\"automate\":\"由 automation 逆构而成。automation 是 20 世纪 40 年代福特公司造的词，根子是希腊语 automaton「自己动起来的」（autos「自己」+ -matos「有意愿的」）：自动人偶 automaton 在先，「自动化」的名词在后，动词 automate 最后补上。\",\"avail\":\"经古法语 vail「有价值」，源头是拉丁语 valere「强壮、有价值」（valid、value 的同族）。avail 的本行是「顶用」：of no avail 是「一点不顶用」，to avail oneself of 是「让某物为自己顶用」。\",\"avenge\":\"来自拉丁语 vindicare「提出主张、惩罚、解救」，经古法语 avengier 进入英语。vindicare 也留下 revenge（经法语再入）与 vindicate（为自己伸张）——avenge 与 revenge 是同根的双生词，一个偏「替人报仇」，一个偏「报复」。\",\"average\":\"通行说法是经海商法辗转而来：阿拉伯语 ʿawār「损伤」→ 意大利语 avaria「货物损失」→ 法语 avarie。海损要按各货主货值的比例分摊，分摊的份额叫 average——由「按比例分摊」算出「平均数」，再引申为「平常、一般」。源头一环有不同意见，本条标注为通行说。\",\"avert\":\"来自拉丁语 avertere：ab-「离开」+ vertere「转」。把脸、把目光、把一场灾祸「转开」，就是 avert；aversion「厌恶」是同一种转身——心里转开，就是不想见。\",\"avoid\":\"经盎格鲁-法语 avoider 进入英语，本义是「倒空、腾出」：源头是拉丁语系的「空」（vacuus 一族的通俗形式）。先有「把地方清空、退开」，才有「躲开、避开」——avoid 的第一步是抽身，不是迎战。\",\"await\":\"来自古法语 awaitier「守望、等候」：a- + waitier「看守」，再往上是日耳曼语 waht「守望」（与 wait、wake 同族）。await 比 wait 多一层「守着望着」的郑重，所以法律与正式文书爱用它。\",\"awake\":\"来自古英语 āwæcnan，是 wake 家族的强化形式：wacan「醒着、守望」本就是日耳曼语里「醒」与「看守」不分家的词。awake 与 wake、watch 同出一脉——醒着，就是在守望。\",\"award\":\"来自古法语 eswarder「查看、裁决」：es-（拉丁 ex-）+ 日耳曼语 ward「看守、审视」（guard 的同族）。裁决者先「看清楚」再下判：奖项是审视之后的定论，法庭的赔偿裁定（award）也是同一个词。\",\"backfire\":\"back「向后」+ fire「开火」的 20 世纪合成词。先指内燃机的「回火」：火焰窜错方向，烧回进气口；不久转喻「事与愿违」——放出去的一枪，反弹回自己身上。\",\"backpack\":\"back「背」+ pack「包裹」的合成词。pack 经中古荷兰语 pak 进入英语，本是「捆成一包的货」；backpack 作名词指双肩背包，作动词「背包旅行」是 20 世纪中叶背包客文化兴起后的新用法。\",\"backtrack\":\"back「向后」+ track「足迹、小径」。track 经古法语 trac 进入英语，指人走过留下的痕迹，其更深来源不甚明朗，本条不下定论。沿着自己的脚印往回走，就是 backtrack，也转指「收回先前立场」。\",\"badge\":\"中古英语 bagge 一词的来源至今无定论：一说与纹章符号有关，但没有确证。本条按诚实标注：词源不明。能确定的是它从中世纪起就指佩戴在身上、表明身份或归属的标记，动词义「标记」由此而来。\",\"baffle\":\"来源有争议，未有定论。一说与苏格兰语 bawf「突然的吹打」等拟声形式有关，一说受法语 bafouer「嘲弄、愚弄」影响。本条按诚实标注：主流辞书标为 origin uncertain，只确定它 16 世纪后有「使困惑、阻挡」诸义。\",\"bag\":\"来自古诺尔斯语 baggi「袋子、包裹」。维京时代的贸易把这个北欧词带进英语；baggi 的更深来源不甚明朗，本条标注到此为止。装袋、打包的动作都从这个名词长出来。\",\"bake\":\"古英语 bacan，日耳曼语固有词，印欧语根 *bʰeg- 是「烤、炙」。bake 与 bath 在语义场上是近邻——都关乎「热」：一个烤食物，一个泡热水。\",\"balance\":\"来自拉丁语 bilanx：bi-「二」+ lanx「盘子」——双盘天平。经古法语 balance 进入英语。钱包里的 balance「结余」也是天平意象：借贷两边称平之后剩下的数。\",\"ban\":\"古英语 bannan「召唤、公告」，日耳曼语 *bannan 本义是「公开说话」。官方当众宣告的话先是「征召令」，再收窄为「禁令」；banish（放逐）与 bandit 一系的词都沾着这层「被公告驱逐」的意味。\",\"bang\":\"来自古诺尔斯语 banga「敲打」，带拟声色彩的词。锤子落下的声音就是意义本身，后来也指刘海（bang 的美式发式义是另一段支线）。\",\"banish\":\"来自古法语 banir「宣告、放逐」，根子是日耳曼语 ban「公告」（与 ban 同源）：国王当众宣告某人不得踏入国境，就是 banish。放逐从来不是悄悄进行的——先要宣之于众。\",\"bar\":\"经古法语 barre 进入英语，再往上是通俗拉丁语 *barra「横杆」，其更深来源（一说凯尔特语）不甚明朗。「横杆」是全部义项的中心：拦路的杆、柜台的长条、法庭的栏杆（律师界 the bar），还有乐谱的小节线；动词「禁止进入」是「用杆拦住」。\",\"bare\":\"古英语 bær「裸露的、无遮盖的」，日耳曼语固有词。bare 做动词是「使裸露」：露出牙齿、袒露心迹都是把遮盖拿掉。\",\"bargain\":\"来自古法语 bargaignier「讨价还价」，更深的来源不确定：一说与日耳曼语 *borgan「借、担保」有关，未成定论，本条按诚实标注。能确定的是它从市场上的你来我往里来：先是「讲价的交涉」，后是「谈成的交易」，再是「划算的买卖」。\",\"barge\":\"作动词「闯入」是 20 世纪的新义：驳船（barge）笨重、直来直去，人像驳船一样横冲进来，就是 barge in。驳船名经古法语 barge 源于拉丁语 barca「小船」，barca 再往上（一说经希腊语借自埃及船名）不甚明朗。\",\"barrel\":\"来自古法语 baril「桶」，中世纪拉丁语作 barriclus；再深的来源无定论，一说与 bar「条、杆」有关（桶由木条箍成），未获证实，本条按诚实标注。石油以「桶」计价的 barrel 是工业标准留下的计量单位。\",\"barricade\":\"来自法语 barricade，源头 barrique 是「大酒桶」。1588 年巴黎「街垒日」，市民用装满土的酒桶垒起街垒封锁街道，barricade 由此得名——路障的第一块砖，是酒桶。\",\"barter\":\"来自古法语 barater「交换；欺骗」，再深来源不确定（一说凯尔特语）。这个词源在中世纪同时带着「做买卖」与「耍手腕」两层气味——以物易物的集市上，精明与欺瞒从来只隔一层皮。无定论处，本条标注存疑。\",\"bask\":\"来自古诺尔斯语 baðask「洗澡」，是 baða（洗）的反身形式——本义「给自己泡个澡」。北欧人把「泡在热水里」的舒坦搬到阳光下：晒太阳，就是泡一场日光浴。\",\"batch\":\"源于古英语 bacan「烤」（bake 的同族）：一炉烤出的面包是一个 batch。由「一炉的量」推广为生产、数据处理的「一批」——批次观念是从面包房出炉口开始的。\",\"bath\":\"古英语 bæþ，日耳曼语固有词，与 bake 同属「热」的语义场：bath 的原初场景是热水浸泡。作动词「给……洗澡」与名词同形，英式英语里尤其常用。\",\"batter\":\"「连续猛击」来自古法语 batre、拉丁语 battuere「打、击」（battle 的同族）加表反复的词尾：一下下地打。厨房里的 batter「面糊」也是同一个词——要反复搅打才成糊。\",\"bawl\":\"带拟声色彩的词，一说源于古诺尔斯语 baula「（牛）哞叫」，一说纯为拟声造词，无定论，本条标注存疑。放声大哭与扯着嗓子喊，靠的都是那副大嗓门。\",\"beacon\":\"古英语 bēacen「标记、信号」，日耳曼语固有词。山顶烽火台的火光是古代的 beacon；作动词「作灯塔指引」是现代用法。beckon「招手示意」与它同源——最初都是「打信号」。\",\"bead\":\"古英语 bed、gebed 的本义是「祈祷」：念珠是数祈祷次数的工具，数着数着，「珠子」反客为主，成了这个词的正义。bead 是英语里「工具吞掉动作」的经典案例。\",\"beam\":\"古英语 bēam「树、大梁」，日耳曼语固有词。房梁是横木，阳光的「梁」是光柱（beam of light），笑容「beam」则是脸上放光——三义都从「一道横贯的亮木」出发。\",\"bean\":\"古英语 bēan，日耳曼语固有词 *baunō。豆子是旧大陆最古老的作物之一，这个词的年纪也足够老；再往印欧语追溯已无定论，本条标注到此为止。\",\"bear\":\"「忍受」来自古英语 beran「携带、承受」，印欧语根 *bʰer-「拿、扛」：拉丁语 ferre（transfer、fertile 的词根）与希腊语 pherein 都是同根。扛得住重量，就是 bear 得住痛苦；作名词「熊」的 bear 拼写相同，却是另一个词（「棕色的家伙」）。\",\"beast\":\"来自古法语 beste、拉丁语 bestia「野兽、牲畜」。bestia 在拉丁语里泛指一切牲畜野兽；英语里 beast 的词义一路下滑，从「动物」到「野兽」再到骂人的「畜生」——「野兽般对待」正是这条下滑线的末端。\",\"beat\":\"古英语 bēatan「敲打」，日耳曼语拟声根 *baut-。击打的节奏感让 beat 一词多义共生：打败（把对手打趴）、节拍（一下下打点）、疲惫（beat，被打蔫了）。\",\"beautify\":\"beauty 来自古法语 beauté，源头是拉丁语 bellus「好看的、漂亮的」；后缀 -ify 来自拉丁语 -ficare（facere「做」）。beautify 就是「把 bellus 做出来」——使变美。\",\"beckon\":\"来自古英语 bēacnian「打信号、示意」，与 beacon（信号）同源。先是烽火与旗语式的信号，后缩成一个手势：指尖一勾，就是 beckon。\",\"become\":\"古英语 becuman：be- + cuman「来」——「来到某种状态」。人不是瞬间变成什么，而是「走到了」那里；become 的语法里藏着一段路程。\",\"bed\":\"古英语 bedd，日耳曼语 *badją。一说其本义是「掘出的睡窝」——人在地上刨出凹处铺草而卧，未成定论，本条标注存疑。花坛叫 flower bed，正是借了这层「铺平的一片地」。\",\"beep\":\"20 世纪的拟声词，摹仿汽车喇叭与电子设备的短促鸣声而造。词源上没有祖先可追：声音响起，词也随之诞生。\",\"befall\":\"be- + fall 的古英语合成词 befeallan「落到……头上、发生」。坏事像从天而降砸在某人身上，befall 至今多用于不幸之事——降临，从来不是请来的。\",\"beforehand\":\"before「在前」+ hand「手」的合成词，中古英语已有。把事「提前握在手里」就是预先准备；hand 在这里是「掌握、经手」的那只手，与 firsthand「第一手」同理。\",\"befriend\":\"be-（使）+ friend。friend 来自古英语 frēond，本是动词 frēogan「爱」的现在分词——「朋友」字面就是「爱着（你）的那个人」。与人交友 befriend，就是主动去做那个爱着的人。\",\"beg\":\"来源不明，无定论。一说与中古英语 bedecian「乞讨」有关，一说与乞讨修士的称呼有关，均未证实，本条按诚实标注。只确定它中古英语时期已表「乞求」，尤指沿门求乞。\",\"beget\":\"be- + get。get 来自古诺尔斯语 geta「获得；生育」——geta 在北欧语里本就兼表「得到孩子」。beget 是圣经译笔爱用的郑重词：生儿育女，也转指「引发、招致」（violence begets violence）。\",\"begin\":\"古英语 beginnan，日耳曼语合成词，后半 -ginnan 的确切来源有争议（一说与「张开、开端」有关），本条标注存疑。begin 比 start 多一层郑重：start 本义是「猛然一动」，begin 是「着手展开」。\",\"behave\":\"be- + have（古英语 habban「拥有、持有」）的中古英语合成词，本义「持有（自己的举止）、待人接物」。behave yourself 不是「表现你自己」，字面是「把你的举止拿好」。\",\"belch\":\"古英语 bealcian，拟声色彩的日耳曼语词：气从胃里冲出喉头的声响，就是词义本身。火山、烟囱「喷吐」浓烟也用 belch，是拟声义的延伸。\",\"belie\":\"be- + lie（古英语 lēogan「说谎」）：本义「用谎言中伤、歪曲」，后转指「与表象相矛盾、掩盖真相」——纤细的外表 belie 了惊人的力量，即「外表在撒谎」。\",\"believe\":\"来自古英语 belȳfan 一系，与 lēof「亲爱的」同根（德语 glauben 同源）：「把某事放在心上当真」，先有信任，后有信仰。believe 与 love 在词源深处是邻居——都是「珍视」。\",\"bellow\":\"来自古英语 bylgan「吼叫」，拟声词，与 bell 在声音意象上相近（是否同源无定论）。公牛的低吼、风箱的轰鸣、人的怒喊，共用这一个从喉咙深处滚出来的声音。\",\"belong\":\"be- + long。但此 long 非「长」：中古英语 longen 源于古英语 gelang「伴随的、现成在手的」，义为「恰好相配、归属」。belong 的核心是「各归其位」：物有所属，人有所属，都是放对了地方。\",\"belt\":\"来自古英语 belt，借自拉丁语 balteus「佩剑的腰带」——英语从罗马军装里借来的老词。动词「用带系、（一路）猛冲」都是后起义。\",\"bemuse\":\"be- + muse。muse「沉思、出神」经古法语 muser 而来，再往上（一说拉丁语 musa「缪斯」，一说与「愣神、张口呆望」有关）无定论，本条标注存疑。bemuse 是「把人推进出神状态」：不是困惑得皱眉，是懵住。\",\"bend\":\"来自古英语 bendan「弯曲；拉弓」，与 bind 同族：拉弓时弓身被弦「绷弯」——bend 的原始场景就是一张弓。make 式的因果关系还在：bendan 本是「使（弓）弯」。\",\"bequeath\":\"来自古英语 becweþan：be- + cweþan「说」（古词 quoth「说」的本家）。遗赠靠的是「说出口的遗嘱」：在文字契约普及之前，临终的口头宣告就是 bequest 的法律形式。\",\"bereave\":\"来自古英语 berēafian「抢走、剥夺」：reave 是「劫掠」（与 rob 的祖先是近亲）。bereaved「丧亲的」字面是「被（死亡）抢走了亲人的人」——英语对丧亲的说法，从来带着被掠夺的痛感。\",\"beset\":\"来自古英语 besettan：be-（环绕、彻底）+ set「安放、布置」。兵力在四周「布置」开来，就是围攻；困难 beset 某人，也是从四面八方围上来。\",\"besiege\":\"be- + siege。siege 经古法语 sege「围城」源于拉丁语 sedēre「坐」：围城军在城外「坐」下来，耗到城里断粮。siege 与 sit、seat、session 同出一根——围城，拼的是谁坐得更久。\",\"besmirch\":\"be- + smirch「污点」。smirch 的来源有争议：一说与古法语 esmorcher 有关，无定论，本条标注存疑。besmirch 多用于名誉：玷污的往往不是衣服，是招牌。\",\"bestow\":\"be- + stow「放置」（古英语 stōw「地方」）：把（荣誉、礼物）郑重地「安放在」某人身上，就是授予。stow 至今还有「妥善存放」义（stow away 偷渡者即「藏起来的人」）。\",\"bet\":\"来源有争议，无定论：一说它是古法语 abet「怂恿、唆使」一系的缩略（打赌原是怂人押注），一说为独立的口语造词。本条按诚实标注：主流辞书标为 origin uncertain，16 世纪末起见于记载。\",\"betray\":\"来自古法语 traïr，源头是拉丁语 tradere：trans-「交到对面」+ dare「给」——「交出去」。tradere 是个中性的词：交出的是传统，就是 tradition；交出的是自己人，就是 betrayal。traitor 同源。\",\"beware\":\"来自古英语 bewarian：be- + warian「守望、防备」，与 wary（警惕的）、ward（看守）、aware（察觉的）同族。beware 是个只剩祈使语气的化石词：满街警示牌上的 BEWARE，就是古人那句「留神看守」。\",\"bewilder\":\"be- + wilder「使迷失于荒野」：wilder 出自 wilderness（荒野）一系，本义「把人带进野地里丢了路」。bewildered 的人，就是心里在荒野中转圈的人。\",\"bewitch\":\"be- + witch。witch 来自古英语 wicce（女巫）/ wicca（男巫），再深的来源无定论。bewitch 的魔法是字面的：中世纪的人相信，着魔是真的中了咒。\",\"bind\":\"古英语 bindan「捆、绑」，日耳曼语 *bend- 一族的总源头：band（带子）、bend（拉弓绷弯）、bundle（一捆）都是这条根上的枝。bind 的核心动作从未变过：把东西系紧。\",\"binge\":\"来源有争议：一说源于英格兰方言 binge「浸泡（木桶）」——先把桶泡胀不漏，再转指泡在酒里；19 世纪末起作「狂饮狂欢」解。本条标注为流行说法，未有定论。\",\"biodegrade\":\"20 世纪合成词：bio-（希腊语 bios「生命」）+ degrade（拉丁语 degradare：de-「向下」+ gradus「台阶」）。「被活物一级一级拆解下去」，就是生物降解；biodegradable「可生物降解的」1960 年代进入日常用语。\",\"bite\":\"古英语 bītan「咬」，印欧语根 *bʰeyd- 是「劈开、裂开」：咬，就是用牙齿把东西劈开。同根的 bitter 原指「咬舌头的（辛辣）」，bit 是「咬下的一小块 / 被劈下的碎片」。\",\"blab\":\"中古英语的拟声词 blabbe，摹仿嘴唇不停翕动的声音；德语方言 blappern 是它的亲戚。话多藏不住，就成了「泄密」——blab 的词义是被声音出卖的。\",\"blacken\":\"black（古英语 blæc「黑」）+ -en（使变成……）。变黑可以是熏的、晒的，也可以是名誉上的：blacken someone's name 是把人「抹黑」，与中文不约而同。\",\"blacklist\":\"black「黑」+ list「名单」的 17 世纪合成词。当时「黑皮书」（black book）专记不良人等，列入黑名单就是被记进黑册子；计算机安全里的「黑名单 / 白名单」对子仍是这套隐喻。\",\"blackmail\":\"mail 不是「邮件」：它是苏格兰语 mail「租金、贡赋」，源于古诺尔斯语 mál「约定、付款」。16—17 世纪苏格兰边境地主向强人交「保护费」买平安，这种以货代银（非白银，故称 black）的勒索款就是 blackmail。\",\"blame\":\"来自古法语 blasmer，源头是拉丁语 blasphemare、希腊语 blasphēmein「说坏话、亵渎」——blame 与 blasphemy（亵渎）是同一词的双生分化：一个落到日常责备，一个留在宗教语境。\",\"blare\":\"拟声词，与中古荷兰语 blaren「咩叫、高喊」相近。喇叭的尖啸、嗓门的轰响都是 blare；词源上，它是先有声音、后有词。\",\"blast\":\"古英语 blǣst「一阵风、气流」，源于 blāwan「吹」（blow 的祖先）。blast 的第一义是「吹」：一阵狂风是 blast，爆炸是气浪的 blast，高炉是「鼓风」的 blast furnace。\",\"blaze\":\"古英语 blæse「火炬、火焰」，日耳曼语词。blaze 的火是「明亮地烧」：火焰、怒火（blaze of anger）、光芒都从火炬来。树干上刻的「路标」blaze 与马额的白斑 blaze 出自古诺尔斯语 blesi，是拼写相同的另一个词。\",\"bleach\":\"来自古英语 blǣcan，与 blāc「苍白的、发亮的」同族：晒白、洗白都是让颜色「变淡变亮」。漂白剂 bleach 是这个动词转成的名词。\",\"bleed\":\"来自古英语 blēdan，是 blōd「血」的动词形式——「出血」就是「血（在）流」。外科旧法「放血」也叫 bleed；印刷里图版出边叫 bleed，又是另一条延伸线。\",\"blemish\":\"来自古法语 blesmir「使苍白、弄脏、损害」，再往上（一说日耳曼语 *blesmjan「发白」）无定论，本条标注存疑。blemish 的主战场是名誉与表面：无瑕的声誉上多了一块污点。\",\"bendable\":\"bend + -able 的透明合成词。bend 本身出自古英语 bendan「拉弓、绷弯」（bind 一族）：能被绷弯而不折的，就是 bendable。\",\"assortment\":\"来自古法语 assortir：a- + 拉丁语 sors「签、命运、类别」。sort 本义是抽签分到的「那一份、那一类」；assort 是按类分配，assortment 就是「各式各样配齐了的一摊」。命运女神的签筒，是分类学的老祖宗。\",\"assurance\":\"来自古法语 asseürance，是 assure（源于拉丁语 securus「安心的」）的名词形式：保证的本质是「让对方把心放下」。保险在英式用法里也叫 assurance（life assurance 人寿保险），同样是买一份安心。\",\"asterisk\":\"来自希腊语 asteriskos「小星星」，是 astēr「星」的小称。亚历山大港的学者早在公元前就用星形符号标注文本；印刷时代留下了这个 *，注释符号的本名其实是「小星星」。\",\"astonishment\":\"astonish 来自古法语 estoner，源头是拉丁语 *extonare：ex- + tonare「打雷」——「被雷劈中」。惊讶在词源里就是挨了一记闷雷；stun（打晕）与它同出一门，是同一词经不同路径进入英语的双生词。\",\"astrology\":\"来自希腊语 astrologia：astēr「星」+ logos「言说、学问」。在古代，astrology 与 astronomy 是同一个词：看星象既是天文，也是占卜；17 世纪后两者才分家，一门留下算命，一门留下算轨道。\",\"astronomer\":\"来自希腊语 astronomia：astēr「星」+ nomos「法则、安排」——「给星星排布法则的人」。astronomy 的 -nomy 还在 economy（oikos 家 + nomos 法则，「治家之法」）里，管星和管家，用的是同一个「法则」。\",\"athlete\":\"来自希腊语 athlētēs，源头 athlon 是「竞赛；奖品」。athlete 字面是「为奖品而赛的人」——古希腊的竞技者为橄榄冠与荣誉而战，职业运动员的「职业」二字，是 athlon 留下的底色。\",\"athletics\":\"athlete + -ics（源于希腊语 -ika，表「……之学、……之事」）。英式英语里 athletics 专指田径，美式则泛指体育运动总称——同一个词，两种版图。\",\"attachment\":\"attach（经古法语 atachier「钉住」，源于日耳曼语「木桩」义）+ -ment。把文件「钉」在邮件上是 attachment；人与人之间被「系住」的情感也叫 attachment——依恋与附件，用的是同一根钉子。\",\"attendant\":\"attend（拉丁语 attendere「把注意力伸向」）+ -ant「……的人」。服务员、随员都是「在旁守候、随时响应的人」；flight attendant 空乘的字面，就是「在航班上守候的人」。\",\"attic\":\"来自拉丁语 Atticus「雅典的、阿提卡的」：古典建筑在檐口上方按阿提卡式样收一层矮墙，内部空间就被叫作 attic。阁楼的名字，是一张希腊地名通行证。\",\"attraction\":\"来自拉丁语 attrahere：ad-「朝向」+ trahere「拉、拖」。磁石拉铁、景点拉客、魅力拉人，都是一种「往这边拉」；tractor（拖拉机）是它的同族兄弟。\",\"attractiveness\":\"attract（拉丁语 attrahere「拉向自己」：ad- + trahere「拖」）+ -ive + -ness。魅力在词源上不玄：就是「把目光往这边拉」的能力值。\",\"audio\":\"直接取自拉丁语 audire「听」：audio- 在 20 世纪成为能产的前缀，audio-visual「视听」1930 年代流行，audio 遂独立成词。耳机包装上的 audio，祖籍是古罗马的动词「听」。\",\"auditorium\":\"来自拉丁语 auditorium「听讲的地方」，源头 auditor「听者」（audire「听」）。礼堂、音乐厅都是为「听」而建的：舞台可以简陋，声音必须到位。旁听生 auditor 也是同一个词。\",\"aunt\":\"经古法语 ante 源于拉丁语 amita「姑母（父亲的姐妹）」；amita 再往上，一说出自儿语式的叠音称呼（与 amma「妈妈」一类），标注为一说。英语本族的「姑母」旧词 modrige 被法语词取代，是诺曼征服后亲属称谓法语化的典型。\",\"authenticity\":\"来自希腊语 authentikos「亲手做的、原件的」（authentēs「亲手做事的人」）。真实性验的从来不是「像不像」，而是「出没出自本人之手」——authenticity 是出身证明。\",\"author\":\"来自拉丁语 auctor「创始者、增进者、权威」，源头 augere「使生长」。auctor 先于「写书的人」存在：让一件事从无到有的人就是 auctor。英语里 author 专指作者，而 authority（权威）仍保留着 auctor 的另一半血统。\",\"authorization\":\"authorize（author 源于拉丁语 auctor「创始者、权威」+ -ize）的名词形式。授权书上盖的章，追根究底是把 auctor 的「创始者分量」分一份给持有人。\",\"autograph\":\"来自希腊语 autographos：autos「自己」+ graphein「写」——「亲手写的」。先指作家的手稿，后收窄为名人亲笔签名；collect autographs 收集的正是「亲手」二字。\",\"automobile\":\"法语 19 世纪造的混血词：希腊语 autos「自己」+ 拉丁语 mobilis「可移动的」。不用马拉、自己会走的车，就是 automobile；当年它击败 steam carriage 等一众候选，靠的是这对希腊—拉丁拼搭足够简洁。\",\"autonomy\":\"来自希腊语 autonomia：autos「自己」+ nomos「法律」——「自己给自己立法」。城邦的自治、个人的自主、机器的自主导航，都是同一条原则：规则由内生。\",\"autumn\":\"来自拉丁语 autumnus，经古法语 autompne 进入英语，其更深来源无定论（一说伊特鲁里亚语）。它挤走了英语本族的季节名 harvest「收获」——harvest 如今只管收成，管季节的是这位拉丁来客。美式 fall 是「落叶」的诗意简称。\",\"availability\":\"available = avail（古法语 vail「有价值」，源于拉丁语 valere「有价值、强壮」）+ -able。availability 是「顶不顶用、到不到手」的程度：有现货、有人手、系统在线，都是 valere 的现代作业。\",\"avenue\":\"来自法语 avenue，是 avenir「到达、来到」的名词形式，源头拉丁语 advenire：ad- + venire「来」。avenue 本义是「通向宅邸的那条迎宾道」：两侧列树、笔直宽阔；城市大街与「途径、门路」的比喻义都从这条迎宾道延伸。\",\"avoidance\":\"avoid（经盎格鲁-法语，本义「腾空、退开」，源于拉丁语「空」的一族）+ -ance。回避在词源上不是交锋，是把场地让出来——tax avoidance 避税用的也是这个「合法腾挪」。\",\"awkwardness\":\"awkward = awk「反着的、别扭的」+ -ward「朝向」。awk 来自古诺尔斯语 afugr「转错方向的」：awkward 字面就是「方向拧了」——动作拧了是笨拙，场面拧了是尴尬，awkwardness 是这份「拧巴」的名词化。\",\"axle\":\"来自古诺尔斯语 öxull，日耳曼语固有词。它与拉丁语 axis「轴」、希腊语 axōn 同出印欧语根 *aks-——车轮的轴在欧亚各语言里是远古的同族，只是英语走了北欧的拼法。\",\"kitchen\":\"古英语 cycene，借自拉丁语 coquina「厨房」，源头 coquere「烹煮」——是罗马烹饪术北上传入日耳曼语的早期借词。cook 本人（拉丁语 coquus）是它的同根兄弟。\",\"bedroom\":\"bed（古英语 bedd「睡处」）+ room（古英语 rūm「空间」）的直白合成词。中古英语已有，指「睡觉的房间」；room 的老义「空地、余地」还留在一句 make room 里。\",\"bathroom\":\"bath（古英语 bæþ「热水浸泡」）+ room 的合成词。美式英语里 bathroom 成了「厕所」的委婉说法：家里那间带浴缸的小屋，名字替全屋的隐私打了掩护。\",\"toilet\":\"来自法语 toilette，是 toile「布」的小称：先是梳妆用的「小布巾」，再是梳妆本身，再是梳妆的房间，最后（19 世纪，委婉语）指抽水马桶与厕所。toile 往上是拉丁语 tela「织布」——厕所的词源，是一块布的三次转手。\",\"shower\":\"古英语 scūr「阵雨、暴雨」，日耳曼语固有词。淋浴器是 19 世纪的发明：水像阵雨一样从头顶浇下来，名字就从天上借来了。\",\"towel\":\"来自古法语 toaille，源头是日耳曼语 *þwahljō，与古英语 þwēan「洗」同根：毛巾生来就是「洗后擦身的布」。towel 的词源里带着水汽。\",\"soap\":\"古英语 sāpe，日耳曼语 *saipōn-。有说法认为它与拉丁语 sapo「肥皂」（高卢人用兽脂与草木灰制的染发膏）互有借贷，孰先孰后无定论，本条标注存疑。肥皂的配方与名字，都在罗马边境上交流过。\",\"shampoo\":\"来自印地语 čāmpo，是动词 čāmpnā「按、揉」的命令式——「揉！」。18 世纪英属印度的浴室里，洗头先是头皮按摩的一道工序；词义随后从按摩转到洗发，再转到洗发水本身。\",\"toothbrush\":\"tooth（古英语 tōþ）+ brush 的合成词。brush 经古法语 broisse 而来，更深来源不甚明朗。植毛牙刷 15 世纪末在中国出现，这个英文复合名是它西传后才配上的。\",\"toothpaste\":\"tooth + paste 的 19 世纪合成词。paste 经古法语源于拉丁语 pasta「面团」，源头希腊语 pasta「大麦糊」：牙「膏」在词源上是一团面糊。\",\"mirror\":\"来自古法语 mireor，源头拉丁语 mirari「惊叹、注视」（admire、miracle 的同族）。镜子在词源里是「让人看得出神的东西」：照镜先是惊叹，后才是整理。\",\"comb\":\"古英语 camb，本义「（鸟的）冠、梳齿状的脊」，日耳曼语固有词。梳子的齿像鸡冠一样排布，词就从鸡冠借来了；山脊（comb）在方言里仍保留着这层老义。\",\"razor\":\"来自古法语 raseor，源头拉丁语 radere「刮、擦」。radere 家族专干「刮擦」：erase（e- + radere「刮掉字迹」）是它最有名的亲戚——剃须刀刮胡子，橡皮刮铅笔字。\",\"needle\":\"古英语 nǣdl，日耳曼语 *nēþlō，印欧语根 *(s)nē- 是「缝、纺」。针与「缝纫」同根而生：德语 nähen「缝」是它的今亲。指针、针叶的 needle 义，都借了这根细长尖物的形状。\",\"thread\":\"古英语 þrǣd，源于 þrāwan「扭转、投掷」（throw 的祖先）：线是「拧成的股」。话语的 thread（线索、帖子主线）借的正是纺线意象——一根拧好的线，从头捋到尾。\",\"button\":\"来自古法语 bouton「芽、圆钮」，是 bouter「推、顶」的名词：圆鼓鼓像花芽一样顶出来的小扣。植物的「芽」与衣服的「扣」在法语里是同一个词；电子时代的「按钮」button，是这颗芽的直系后代。\",\"zipper\":\"zip 是 19 世纪的拟声词，摹仿物体疾速掠过的「嗖」声；zipper 最初是固特异公司 1923 年为胶靴注册的商标：拉链头一拉，「嗖」地合上，声音即名字。商标通用化后，它挤走了 slide fastener 的官方称呼。\",\"pocket\":\"来自古法语 pokete，是 poke「袋子」的小称；poke 出自日耳曼语，指布口袋。pocket 字面就是「小袋袋」；谚语 a pig in a poke「袋里买猪（盲目购买）」里的 poke 还是老样子。\",\"wallet\":\"中古英语 walet 指「旅行袋、背囊」，来源有争议：一说与「卷、裹」的日耳曼语根有关，无定论，本条标注存疑。16 世纪后它收窄为装钱的折叠小包——行囊瘦身，钱包诞生。\",\"purse\":\"古英语 purs，借自晚期拉丁语 bursa「皮包」，源头希腊语 byrsa「兽皮」。bursa 一家还有法语 bourse（证券交易所——最早在布鲁日的「皮包」招牌旅店前交易）与 bursar（财务官）：钱包与股市，同出一张皮。\",\"umbrella\":\"来自意大利语 ombrella，是 ombra「阴影」的小称，源头拉丁语 umbra「影子」。雨伞先是地中海的遮阳伞（parasol 的近亲），传入多雨的英国后才改行挡雨——名字里留着的，还是南方的阳光。\",\"scarf\":\"来源有争议：一说源于古北法语 escarpe「（朝圣者的）行囊带、绶带」，再往上与日耳曼语有关，无定论，本条标注存疑。词义从「斜挎的带子」转到颈间的围巾，是近世服饰史的事。\",\"cap\":\"指帽：古英语 cæppe 借自晚期拉丁语 cappa「头巾、斗篷」。cappa 家族枝繁叶茂：cape（披风）、chapel（礼拜堂，传说因供奉圣马丁的斗篷 cappa 而得名）都从这块布来。「上限、盖子」的 cap 义是后起的延伸。\",\"coat\":\"来自古法语 cote、cotte，源头是法兰克语 *kotta「粗呢外衣」。中世纪的 cote 是男女通穿的外袍；今日的外套、动物的「一身毛」（coat of fur）、一层漆（a coat of paint），穿的都是这件粗呢袍的引申衣。\",\"shirt\":\"古英语 scyrte「短上衣」，日耳曼语 *skurt-「短」一族：shirt（本族词）、skirt（经古诺尔斯语借入的同源双生词）、short（短）本是一家——都出自「剪短的衣料」这一意象。\",\"pants\":\"pantaloons 的简称。Pantalone 是意大利即兴喜剧里的滑稽老头角色，一身宽松长裤，名字又源于威尼斯人崇拜的圣徒圣潘塔莱昂（San Pantaleone）。一条裤子绕了喜剧舞台一圈，才变成美式英语的日常词。\",\"dress\":\"作名词连衣裙：dress 本是动词，来自古法语 drecier「摆正、整理」，源头拉丁语 directus（direct 的词根）——把衣装「理正、穿戴整齐」就是 dress；专指女裙是 19 世纪后的收窄。fancy dress「化装服」还留着「装扮」的老义。\",\"skirt\":\"来自古诺尔斯语 skyrta「衬衫、短上衣」——与 shirt 是同根双生词：南边（古英语）演成衬衫，北边（诺曼—诺尔斯）演成下摆那一半。裙摆与衬衫，在词源上原是同一件衣。\",\"shoe\":\"古英语 scōh，日耳曼语固有词，再往印欧语追溯（*skeuk-「覆盖」一说）无定论，本条标注存疑。鞋的本分自古不变：给脚的覆盖物。\",\"boot\":\"经古法语 bote 进入英语，更深来源不甚明朗（一说日耳曼语），本条标注存疑。靴子先是骑兵与劳作的装备；汽车后备厢在英式英语里叫 boot，是另一条由「车夫座旁的皮箱」延伸的支线。\",\"sock\":\"古英语 socc，借自拉丁语 soccus「轻便拖鞋」——古罗马喜剧演员的专用鞋（悲剧演员穿高底 cothurnus）。喜剧的拖鞋一路演成贴脚的针织袜，舞台与衣柜就这样接上了头。\",\"underwear\":\"under + wear 的 19 世纪合成词。wear 来自古英语 werian「穿着」，日耳曼语固有词。「穿在里边的那一层」始终不好直说，英语的 wardrobe 委婉传统在这个词上留了名分，没留故事。\",\"pajamas\":\"来自波斯语 pāy-jāma：pāy「腿」+ jāma「衣服」——「腿衣」，经乌尔都语、印地语进入英语。英国殖民者把这种宽松长裤从印度带回伦敦当睡裤穿，睡衣的名字也就跟着行李回了家。\",\"suit\":\"作名词「西装」：suit 来自古法语 suite「随从；一套」，源头拉丁语 sequi「跟随」（sequence 的词根）。西装的「一套」与诉讼（lawsuit，「跟下去的案子」）、套房（suite）同源：一套西装，就是「配套跟随」的几件衣服。\",\"tie\":\"「领带」义源于 tie 的本义「绳索、系带」：古英语 tēag「绳」，源于 tēon「拉、牵」（tow 的同族）。17—18 世纪的 cravat 演成现代领带后，tie 以「系在颈上的带子」接过了名字；平局、关系的 tie 都是「绑在一起」的引申。\",\"jewelry\":\"jewel 来自古法语 joel，一说源于拉丁语 *jocale「玩物」，根子是 jocus「玩笑、游戏」（joke 的同根）——珠宝的祖先是「小玩意儿」。贵重，是后来才涨上去的身价；jewellery 是英式拼写。\",\"ring\":\"「戒指」义来自古英语 hring「圆环」，日耳曼语固有词：圆，就是它的一切义项（指环、马戏团的圆场、铃声之外的 ring road 环线）。「铃响」的 ring 出自古英语 hringan，是发音动作的拟声词，同形不同源。\",\"necklace\":\"neck（古英语 hnecca）+ lace 的合成词。lace 来自古法语 laz，源头拉丁语 laqueus「套索、绳圈」：项链字面是「颈上的绳圈」；鞋带的 lace 也是这条「绳」。\",\"bracelet\":\"来自古法语 bracelet，是 bras「手臂」的小称，源头拉丁语 bracchium「臂」（源于希腊语 brakhiōn）。手镯字面是「小臂（饰）」；anklet 踝饰是照它的样子仿造的后辈。\",\"earring\":\"ear（古英语 ēare）+ ring（古英语 hring「圆环」）的古已有之的合成词：耳环的字面就是「耳朵上的环」。\",\"watch\":\"「手表」义来自 watch 的老本行「守夜、值更」：古英语 wæcce「醒着守望」，源于 wacan「醒」（wake 同族）。17 世纪出现的便携计时器因守夜人报时而得名 watch：手表的前身，是更夫的班次。\",\"sunglasses\":\"sun + glasses 的现代合成词。glasses「眼镜」（复数）17 世纪已有；墨镜的祖先是有色护目镜，20 世纪 30 年代雷朋飞行员镜让 sunglasses 成为时尚名词。\",\"key\":\"古英语 cǣg「钥匙」，来源无定论，是英语里少数查不到出身的老词，本条按诚实标注。不过 key 的「关键、要领」义是中古以后的比喻：钥匙开锁，关键开题。\",\"lock\":\"「锁」来自古英语 loc「围合、扣件」，日耳曼语固有词：锁的本义是把东西「围住、合拢」。「一绺头发」的 lock 出自古英语 locc，是拼写相同的近亲词；苏格兰语的 loch「湖」与此无关，不要混淆。\",\"door\":\"古英语 duru / dor，日耳曼语固有词，印欧语根 *dʰwer-「门」：拉丁语 foris「门；门外」（foreign「外国的」源于「门外」）、希腊语 thyra 都是同根。门里门外，是印欧人最古老的分界线之一。\",\"curtain\":\"来自古法语 cortine、晚期拉丁语 cortina「幕、围布」；cortina 与 cohors「围场、庭院」同源，court（宫廷、球场）是它的同族。窗帘与宫廷共用一条根：都是「围起来的那片地方」，一个用布围，一个用人围。\",\"ceiling\":\"来源有争议，无定论：一说与拉丁语 caelare「雕刻」有关（雕花的天花板），一说与 celare「遮盖」有关。本条按诚实标注。只确定 ceil 作动词「给（房间）装顶棚」见于 15 世纪。\",\"wall\":\"古英语 weall，借自拉丁语 vallum「栅栏、防壁」：罗马军团的营垒木栅，把名字留给了不列颠的每一堵墙。wall 是罗马军事工程在英语里的移民后代。\",\"roof\":\"古英语 hrōf「屋顶」，日耳曼语固有词 *hrōfą，更深的来源无定论，本条标注到此为止。roof 的老义还包括「天花板、穹顶」：屋顶是房子最先有的那层盖。\",\"stair\":\"古英语 stǣger，源于 stīgan「攀登」：楼梯字面是「攀登（的器具）」，与 stile（梯蹬）、stirrup（马镫，古英语 stigrāp「攀登绳」）同族。一级一级往上爬，是 stair 的本职。\",\"elevator\":\"来自拉丁语 elevator「举起者」，源头 elevare：e-「出」+ levare「举起」（levis「轻的」）。1850 年代奥的斯的安全升降机让高楼成为可能；美式英语用 elevator，英式用 lift，都是「举起来」的意思。\",\"balcony\":\"来自意大利语 balcone，源头是日耳曼语 *balkô「横梁」（beam 一族）：阳台最初是架在外墙横梁上的木台。德语 Balkon、法语 balcon 都是这条意大利—日耳曼通道上的过客。\",\"yard\":\"「院子」义来自古英语 geard「围起来的地方」，日耳曼语 *gardaz「围栏」：garden（经法语借入的双生路线）、garth 同源。「码」（长度单位）的 yard 出自古英语 gierd「杆」，是另一个词，别混淆。\",\"basement\":\"base + -ment 的 18 世纪建筑词。base 来自拉丁语 basis、希腊语 basis「基座、步子」：basement 是「整座楼基座以下的那一层」，比 cellar 多一层建筑学的分量。\",\"table\":\"来自拉丁语 tabula「木板、平板」，经古法语 table 进入英语。桌子先是一块板：写字的板、吃饭的板；时间表（timetable）、表格（table）的「表」还是这块板。\",\"chair\":\"来自古法语 chaiere，源头拉丁语 cathedra、希腊语 kathedra「座椅」（kata- + hedra「座」）。cathedral「大教堂」是「主教座位所在的教堂」——一把椅子，一个教座，同一个词的两种身价。\",\"desk\":\"来自中世纪拉丁语 desca，源头是拉丁语 discus「圆盘；桌面」、希腊语 diskos「圆盘」。desk、dish（碟子）、discus（铁饼）、disk（磁盘）是同一个「圆盘」的四副面孔：书桌的桌面曾被看作一块平板圆盘。\",\"sofa\":\"来自阿拉伯语 ṣuffa「（铺有垫子的）高台、长榻」，经土耳其语、法语 sofa 进入英语。奥斯曼宫廷的待客长榻随外交与贸易西传，沙发的名字里留着清真寺与宫殿的影子。\",\"lamp\":\"来自希腊语 lampas「火炬」，源头 lampein「发光」，经拉丁语与古法语 lampe 进入英语。lamp 照亮的介质从松脂火炬换到灯油、再换到灯丝，词还是那支火炬。\",\"clock\":\"来自中世纪拉丁语 clocca「钟（铃）」，经中古荷兰语 klok 进入英语；clocca 本身一说出自凯尔特语，带拟声色彩。第一代机械钟没有表盘，只有一口按时敲响的铃——clock 的本名是「铃」，表盘是后加的。\",\"picture\":\"来自拉丁语 pictura「绘画」，源头 pingere「画」（pict- 是它的词干）。picture 先指画出来的像，摄影、电影（motion picture）都是后来搭车的；pictogram 象形图的 pict 也是它。\",\"photo\":\"photograph 的简称（19 世纪末起）。photograph 是希腊语拼搭：phōs「光」+ graphein「画、写」——「用光作画」，1839 年摄影术公布时由赫歇尔等人推广成名。照片是人类给光留下的第一份手迹。\",\"book\":\"古英语 bōc。通行说法是它与 bōce「山毛榉」同源：日耳曼人曾把如尼文刻在山毛榉木片上——书与山毛榉在德语里至今相邻（Buch 书 / Buche 山毛榉）。此说为学界主流，但仍有讨论，本条标注为通行说。\",\"newspaper\":\"news + paper 的 17 世纪合成词。news 是 new 的复数式造词，仿法语 nouvelles「新消息（复数）」；paper 源于拉丁语 papyrus、希腊语 papyros「纸莎草」。报纸的名字 = 新消息 + 莎草纸。\",\"magazine\":\"来自阿拉伯语 makhāzin「仓库（复数）」，经意大利语 magazzino、法语 magasin（商店）进入英语：先指弹药库、仓库，再指「知识仓库」式的期刊，最后（法语线）又成了商店。弹药与杂志共用一词，正是因为都曾是「仓储」。\",\"letter\":\"来自拉丁语 littera：单数是「字母」，复数 litterae 是「信件、文献」——拉丁语里字母与信本来就共用一个词。经古法语 letre 进入英语后，两义并存至今：letters 还是「文学」的体面说法。\",\"envelope\":\"来自古法语 enveloper「包裹」：en- + voloper「裹」，voloper 的更深来源有争议（一说凯尔特语），本条标注存疑。名词义「信封」在 18 世纪定型：信封的本质从来没变，就是把信裹起来。\",\"stamp\":\"作名词「邮票」：stamp 来自古英语 stampian「捣、压印」，日耳曼语拟声根。先有「压出的图章印记」，1840 年英国发行黑便士：小纸片上国王头像的印记就是 stamp，邮票由此得名。动词「跺脚、踩踏」是同一个「捣压」。\",\"pen\":\"来自古法语 penne、拉丁语 penna「羽毛」：钢笔的前身是羽毛笔（quill），笔的名字直接就是「羽毛」。penna 一家还有 pennant（三角旗，形似羽）等。\",\"pencil\":\"来自古法语 pincel「画笔」，源头拉丁语 penicillus「小尾巴」，是 penis「尾巴」的小称——古代画笔用兽尾毛束成，故名。石墨笔芯出现后，这个「毛笔」的名字被铅笔继承了：名字与材料，从此各走各的。\",\"eraser\":\"erase 来自拉丁语 eradere：e-「出」+ radere「刮」——把字从纸面「刮出去」；美国人 19 世纪给橡皮起名 eraser「刮除的家伙」。radere 家族另有 razor：一个刮墨迹，一个刮胡须。\",\"ruler\":\"rule + -er。rule 来自古法语 riule、拉丁语 regula「直棍；准则」，源头 regere「弄直、统治」（regular、region 的同族）：画线用的直棍与治国的准则，在拉丁语里是同一根棍子。\",\"binder\":\"bind（古英语 bindan「捆、绑」）+ -er 的直白合成词：活页夹的本职就是把散页「绑」在一起。注意 binder 不是 bi- 前缀加任何词干——它的切分只有一个：bind + er。\",\"box\":\"古英语 box，借自晚期拉丁语 buxis，源头希腊语 pyxis「黄杨木盒」——pyxis 出自 pyxos「黄杨树」：用黄杨木做的盒子，最后把所有盒子都叫成了 box。盒子（灌木 box）与盒子（容器）是同一个希腊词。\",\"bottle\":\"来自古法语 bouteille、中世纪拉丁语 butticula，是拉丁语 buttis「木桶」的小称：瓶子字面是「小桶」。从桶到瓶，容器一路缩小，名字却记得出身。\",\"cup\":\"古英语 cuppe，借自拉丁语 cuppa「杯、桶」，与 cupa「大桶」同族。由桶而杯，拉丁人量酒的容器在英语里缩成了茶杯的尺寸。\",\"plate\":\"来自古法语 plate、中世纪拉丁语 plata「扁平的金属片」，源头希腊语 platys「宽的、平的」。平片先做成餐盘，又做成印版、号牌；platform、plaza（广场）是它的远房同族——都从「平」展开。\",\"bowl\":\"古英语 bolle、bolla「圆碗」，日耳曼语固有词，与 ball、boll（圆荚）同属「圆鼓鼓」一族。碗的词源没有故事，只有形状。\",\"spoon\":\"古英语 spōn 的本义是「木片、薄片」：最早的勺子就是削薄的木片。勺子得名于材料与形状，与金属无关；spoon 引申的「调羹量」也是这块木片的标准像。\",\"knife\":\"古英语 cnīf，一说借自古诺尔斯语 knífr；再往日耳曼语之前追溯无定论，本条标注存疑。cnīf 的 cn- 在古英语里是发音的，现代 knife 的 k 沉默，只是拼写的化石。\",\"chopstick\":\"chop 是「快」：源于 17 世纪水手洋泾浜对粤语 kap「急、快」的仿译（chop-chop「快点」由此而来），正对应汉字「筷」从快的取义；加 stick「棍」。中餐的「快」与洋泾浜的「快」，在一双筷子上对上了号。\",\"pot\":\"古英语 pott，借自晚期拉丁语 *pottus，其更深来源（一说凯尔特语）不甚明朗，本条标注存疑。锅是英语厨房里最沉默的老住户：名字查不清，位置从没动过。\",\"pan\":\"古英语 panne，一说借自拉丁语 patina「浅盘」，源头希腊语 patanē「平盘」。平底锅与 patina（铜绿、包浆）同出一只浅盘；烤盘、量盘的 pan 义都从「浅」来。\",\"oven\":\"古英语 ofen，日耳曼语 *ufnaz，确切来源无定论（一说与「锅、罐」有关），本条标注存疑。烤箱与陶窑在古英语里同名——都是「烧热的腔体」。\",\"stove\":\"来自中古荷兰语 stove「暖房、蒸汽浴室」，日耳曼语固有词：先有「烧热的房间」，再缩小为房间里的炉子。stew「炖菜；蒸」经古法语 estuve 与它同源——炉灶与炖锅，本是一间蒸汽房里分出来的两件家当。\",\"microwave\":\"micro-（希腊语 mikros「小」）+ wave 的 20 世纪物理词：微波本义是「波长很短的电磁波」（1930 年代）。1945 年雷神公司工程师珀西·斯宾塞发现微波能烤化口袋里的巧克力，微波炉由此而来；词义从波段移到了厨电。\",\"sink\":\"名词义来自动词 sink（古英语 sincan「下沉」）：水槽先是「让水漏下去的池子」，中古英语 sink 还指排水沟、污水坑。厨房水槽的洁净形象，是这个词晚近才洗出来的。\",\"tap\":\"「水龙头」（英式）：古英语 tæppa「（酒桶的）塞子、龙头」，日耳曼语固有词。水龙头的祖先是桶上放酒的塞子：拔塞放酒、拧阀放水，是同一种开关。「轻拍」的 tap 出自古法语 taper，拟声，别混淆。\",\"dishwasher\":\"dish + wash + -er 的合成词。dish 出自古英语 disc、拉丁语 discus「圆盘」；洗碟机 19 世纪中叶已有专利，20 世纪才进厨房。切分上它只是「洗 + 碟 + 机器」，与 dis- 前缀无关。\",\"kettle\":\"来自古诺尔斯语 ketill（一路或经古英语 cetel），源头是拉丁语 catillus「小深锅」，catinus 的小称。罗马人的锅借道维京人的厨房进了英语，今日烧水壶的名字里还有拉丁炊具的回声。\",\"toaster\":\"toast + -er。toast「烤面包片」来自古法语 toster，源头拉丁语 torrere「烤干、炙」（tostus 是其分词）：烤，就是把面包烤到焦香。注意「祝酒」的 toast 是另一条线：古人曾在酒里泡一片烤面包调味。\",\"blender\":\"blend + -er。blend 来自古英语 blendan「混合」，更深来源（一说与「使熔化、倾倒」有关）不甚明朗，本条标注存疑。电动搅拌机是 20 世纪 30 年代的厨房电器，名字只是「混合的机器」。\",\"milk\":\"古英语 meoluc，日耳曼语 *meluk-，印欧语根 *melǵ- 是「挤（奶）、捋」：拉丁语 mulgere「挤奶」是同根，emulsion（乳液）就出自它。挤奶这个动作，给半个印欧语系留下了「奶」的名字。\",\"juice\":\"来自古法语 jus「汤汁、肉汁」，源头是拉丁语 jus「汤、酱汁」。拉丁语里还有另一个拼写相同的 jus「法律、权利」——同形异源，别混淆。果汁义是 14 世纪后从「汤汁」里分出来的。\",\"bread\":\"古英语 brēad 的本义是「碎块、掰下的一口」：在中古英语早期，它挤走了更老的面包名 hlāf（即 loaf 的祖先）。hlāf 并未消失：lord 出自 hlāford「面包守护者」，lady 出自 hlǣfdige「揉面包的女子」——封建主的头衔，是从面包房里长出来的。\",\"butter\":\"来自拉丁语 butyrum、希腊语 boutyron：通常解析为 bous「牛」+ tyros「奶酪」——「牛的酪」。也有说法认为它是随黄油制作术从北方游牧民族传入希腊的外来词，被希腊人按音拼成了「牛奶酪」；本条两说并存，主流取前者。\",\"cheese\":\"古英语 cēse，借自拉丁语 caseus「奶酪」：罗马人的制酪术连同名字一起传入日耳曼。现代蛋白质 casein「酪蛋白」仍取自 caseus。\",\"egg\":\"中古英语的「蛋」本有南北两派：南方 ey（复数 eyren，出自古英语 æg），北方 egg（出自古诺尔斯语 egg）。1490 年卡克斯顿印《埃涅阿斯记》序言里专门抱怨过：南方人听不懂北方人要的 egges。印刷与伦敦话最终让北欧拼法 egg 胜出。\",\"rice\":\"沿贸易路线一路西传：英语经古法语 ris、意大利语 riso 回到拉丁语 oryza、希腊语 oryza；再往东的终极源头应在亚洲语言里（有与梵语 vrīhi「稻」相关的说法），那一段链条细节尚无定论。水稻从东方来，词也从东方来。\",\"noodle\":\"18 世纪借自德语 Nudel「面条」。Nudel 本身的更早来源不完全确定，一说与德语 Knödel「面团丸子」同族（都是揉出来的面食）。英语的面条词是向德国借的，意大利面大举进入英语世界之前，noodle 先站住了脚。\",\"pasta\":\"借自意大利语 pasta「面团、面食」，上溯拉丁语 pasta「面团」，再到希腊语 pastē「撒了盐的大麦面糊」（源自动词 passein「撒」）。pasta 的本行是「揉成的面团」，意大利人把它做成了几百种形状。\",\"pizza\":\"借自意大利语 pizza，指那不勒斯的扁平烤饼。词源有争议：一说源于拉丁语 pinsa「压扁的饼」（pinsere「捣、压」），一说与希腊语 pitta「饼」或伦巴第语 bizzo「一口」有关，无定论。但公认的是：词和做法都出自意大利南部的平民厨房。\",\"burger\":\"hamburger 的缩略。hamburger 本是「汉堡（Hamburg）式的」：19 世纪德国汉堡的碎牛肉饼随移民渡美，夹进面包后成了 hamburger sandwich，后来独立成词，又缩成 burger。它和 ham「火腿」毫无关系，cheeseburger、fishburger 的 -burger 已被拆出来当后缀用。\",\"sandwich\":\"以第四代三明治伯爵约翰·蒙塔古（1718–1792）得名：传说他打牌时吩咐仆人把肉夹在两片面包之间，好不离赌桌进食——故事细节或有附会，但词由伯爵封号而来是学界共识。封号本身来自肯特郡地名 Sandwich，古英语意为「沙地上的村镇」。\",\"soup\":\"源于古法语 soupe「汤；泡在汤里的面包」，再往上是日耳曼语的 suppa「泡汤的面包片」：最早的 soup 不是汤本身，而是泡在热汤里的那块面包。supper「晚餐」与它同源——一天最后一餐，当年就是一碗热汤泡面包。\",\"cake\":\"13 世纪借自古诺尔斯语 kaka「饼」，是维京人留在英语里的厨房词。cake 与 cookie 本是同族（见 cookie），古英语自己也有 āc 等面食词，但北欧的 kaka 拼法最终胜出，特指甜点圆饼。\",\"cookie\":\"借自荷兰语 koekje「小饼干」：koek「饼」加指小后缀 -je。17 世纪荷兰移民把这种茶点带到北美，koekje 在美式英语里成了 cookie；英式英语则用 biscuit（见词库后段）。它与 cake 同出一个日耳曼饼词家族。\",\"candy\":\"源于古法语 sucre candi「冰糖」，其中 candi 来自阿拉伯语 qand「甘蔗糖」，再往上是波斯语 qand，最终可能源于梵语 khaṇḍa「碎块」——指敲碎的糖块。糖从印度经波斯、阿拉伯世界西传，词也一路跟着商队走。\",\"strawberry\":\"古英语 strēawberige。名字里为什么是 straw「稻草」，说法不一：一说果农在果下垫稻草防泥防烂，一说源于匍匐茎四处「撒布」（与 strew「撒」同音混同）。学界无定论，但 straw 与果实表面的籽粒无关，这一条可以确定。\",\"pear\":\"古英语 pere，上溯通俗拉丁语 pira（单数 pirum）。拉丁语这个词本身又是从地中海某古老语言借来的水果名，具体源头已不可考。梨在欧洲栽培极早，词比罗马帝国还老。\",\"melon\":\"经中世纪拉丁语 mēlō 回到希腊语 mēlopepōn「苹果瓜」：mēlon「苹果（泛指圆果）」加 pepōn「熟瓜」。古希腊人眼里瓜是长在藤上的大苹果；pumpkin 的 pepōn 与这里是同一个词（见 pumpkin）。\",\"mango\":\"绕了大半个地球：英语经葡萄牙语 manga、马来语 mangga，回到泰米尔语 māṅkāy——mā 是芒果树，kāy 是未熟的果子。16 世纪葡萄牙商人在印度果阿收购芒果，词就跟着船回了欧洲。\",\"pineapple\":\"pine「松」加 apple「果」：16 世纪的英语里 pineapple 先指松果（外形同理），后来见到美洲这种带鳞甲、顶着冠芽的果实，觉得像松果，便把名字转给了它。apple 在古英语里本可泛指一切果实，所以苹果味与它无关。\",\"carpenter\":\"源于古法语 carpentier，上溯晚期拉丁语 carpentārius「制车匠」，其词干 carpentum 是凯尔特人的一种木制货车与战车。木匠最早的本行是造木车，后来才包下房屋梁架——车轮与房梁，用的是同一套木工手艺。\",\"plumber\":\"来自拉丁语 plumbum「铅」：罗马时代起水管多用铅制，plumber 就是「跟铅打交道的人」，后来专指管道工。测深的 plumb「铅锤」、plumb line「铅垂线」都是同一个 plumbum 的后代。\",\"electrician\":\"electric 回溯希腊语 ēlektron「琥珀」：摩擦琥珀能吸起轻物，古人最早见的电就是琥珀的魔力（electron「电子」同源，词库词根部分已讲）。electrician 是 19 世纪电气时代才有的新职业，加的是 -ician「从事……的人」。\",\"mechanic\":\"经拉丁语 mechanicus 回到希腊语 mēkhanē「器械、巧计」。mēkhanē 在希腊语里既是机器，也是舞台上吊神仙下凡的机关（戏剧术语 deus ex machina 即源于此）。machine 与 mechanic 同根：一个造机器，一个修机器。\",\"baker\":\"古英语 bæcere，源自动词 bacan「烘烤」。历史上女面包师叫 bakester，英国姓氏 Baxter 就是这么来的。bake 是日耳曼厨房里的老动词，面包师的职业名直接从炉火边长出来。\",\"chef\":\"借自法语 chef「头儿、主厨」，是 chef de cuisine「厨房之首」的省略。chef 的源头是拉丁语 caput「头」，与 chief 同根（见 chief）：主厨就是厨房里的「头」。帽子高高、说话算数，都是这个「头」字撑的。\",\"waiter\":\"wait 的本义不是「等」而是「守望、伺候」：古法语 waiter 源于日耳曼语的「看守」一词，waiter 起初是守夜与伺候的人。餐厅兴起后，它专指在桌边伺候上菜的人；「等待」义是守望义的旁支——守着，自然要等。\",\"miner\":\"mine「矿」经古法语 mine 进入英语，其更早源头可能在凯尔特语，细节未定（与拉丁语无亲）。mineral「矿物」是 mine 的亲戚。miner 就是下到 mine 里的人，煤矿金矿，古来如此。\",\"sailor\":\"sail「帆」加表人的 -or（本应是 -er，拼写受 tailor 等词影响定型）。sail 本身是古英语 segl，日耳曼语的老航海词。靠 wind 吃饭的职业，名字就挂在帆上。\",\"pilot\":\"经法语 pilote、意大利语 pilota 回到希腊语 pēdon「舵桨」（复数 pēda）。pilot 最早是港内掌舵引船的人——在希腊人手里，船的方向全在那把桨式舵上。20 世纪飞机上天，引航员的名字被飞行员接了过去。\",\"driver\":\"drive 在古英语里是 drīfan「驱赶、催动」：赶牲口、赶马车，都用这个词。driver 最早就是赶车的人，汽车时代到来后，他把缰绳换成了方向盘，词没换。drive 的「驾驶」义正是从赶马车沿用下来的。\",\"janitor\":\"来自拉丁语 iānitor「看门人」，源于 iānus「门洞、拱形通道」。罗马的门神 Janus（两面神）守的就是门，January「一月」是「年之门」，同出一家。janitor 从大楼门房做起，后来兼管整栋楼的维护清洁。\",\"librarian\":\"library 上溯拉丁语 liber「书」；liber 的更早本义是「树皮」——纸草与羊皮纸之前，内层树皮就是书写材料。librarian 是「守书的人」，liberty 的 liber「自由」是另一个同形词根，不要混淆。\",\"secretary\":\"源于中世纪拉丁语 secretarius「掌管机密的人」，出自 secretum「秘密」。最早的 secretary 是替君主与贵族守口如瓶、代笔密信的心腹，后来才演变为文书与行政职位；secret「秘密」就是它的词根（见词库 secret 一词的拆分）。\",\"clerk\":\"源于拉丁语 clēricus「教士、神职人员」。中世纪的欧洲只有教士普遍识字，文书账册全由他们掌管，于是 clēricus 一词分饰两角：既是神职，也是文员。英式读音读作 /klɑːk/，是这段历史留下的化石。\",\"cashier\":\"cash 源于法语 caisse「钱箱」，再上溯拉丁语 capsa「盒子、匣子」。cashier 本是看守钱箱出纳的人。注意还有个同形动词 cashier「革除、开除」，来自荷兰语 casseren「废止」，与钱无关，是另一条线。\",\"salesman\":\"sale 源于古英语 sala，与 sell「卖」同族。salesman 是 19 世纪才定型的复合词，行商与推销员兴起的年代。-man 在此是中性的职业后缀，saleswoman、salesperson 是后来的对应说法。\",\"tailor\":\"源于古法语 tailleor「裁剪者」，动词 tailler 是「切、裁」，再上溯拉丁语 tālea「剪下的枝条」。裁缝的本行就是一刀一刀地裁——tally「记账的刻痕木签」与 tālea 同源，都是在木头上刻切做标记。\",\"barber\":\"源于古法语 barbeor，出自 barbe「胡子」，再上溯拉丁语 barba「胡须」。barber 原专指修胡子的人，后来理发也归了他。barb「倒钩」同出 barba：尖刺如须，扎人一下。\",\"pharmacist\":\"pharmacy 源于希腊语 pharmakon——这个词同时指药物、毒药与巫药，救人还是害人全看剂量与用心。pharmacist 是配 pharmakon 的人，这个行业的谨慎，从词根起就刻着。\",\"veterinarian\":\"源于拉丁语 veterīnārius，与 veterīnus「关于驮兽的」有关（再往上或与 vetus「老的」相连，因驮畜多用老成牲口）。兽医的原装客户不是宠物，而是耕田拉车的牛马——农业时代的牲口医生。\",\"scientist\":\"这是个被「造」出来的词：1833 年，英国学者休厄尔（William Whewell）仿 artist「艺术家」造出 scientist，专指研究自然的人。在此之前他们叫 natural philosopher「自然哲学家」。science 本身源于拉丁语 scire「知道」。\",\"mathematician\":\"经拉丁语回到希腊语 mathēma「学到的东西、学问」，源头是 manthanein「学习」。在古希腊，mathēmata 是「学问」的总称，几何、天文、音乐都在内；后来词义收窄，专归给数量与图形这门最古老的学问。\",\"physicist\":\"physics 源于希腊语 physikē「自然之学」，词根 physis 是「自然、本性」。physicist 与 physician「内科医生」本是近亲——physic 在旧英语里就是医学；19 世纪研究自然规律的人单独立户，physicist 才专指物理学家。\",\"chemist\":\"alchemist「炼金术士」的缩略：炼金术一词经阿拉伯语 al-kīmiyāʾ 传入欧洲，源头还有希腊语 khēmeia「熔炼」一说。炼金术褪去神秘色彩、变成实验科学后，干活的人就叫 chemist；在英国它还兼指药房的药剂师。\",\"biologist\":\"biology 是 19 世纪初才拼出的词：希腊语 bios「生命」加 -logia「学问、论说」。法国博物学家拉马克等人差不多同时启用它，给「研究活物的学问」立了户；biologist 随之而生。bios 还藏在 antibiotic「抗生素」里：anti「对抗」加 bios「生命」。\",\"economist\":\"economy 上溯希腊语 oikonomia「家政管理」：oikos「家」加 nomos「管理、法则」。在希腊人那里，economy 管的是庄园家计；亚当·斯密之后它放大到国家财富。economist 是替这个大「家」算账的人。demo「人民」与 nomos 的组合，见 democracy 的拆分。\",\"diplomat\":\"源于法语 diplomate，其根是拉丁语 diploma「官方文书、通行证书」，再上溯希腊语 diplōma「对折的文件」（diploos「双倍」加折叠）。古代使节怀揣对折封好的证书出使，外交官的职业名就来自他怀里那份文书。\",\"journalist\":\"journal 在法语里是「日报」，源头是拉丁语 diurnus「每日的」（dies「日」）。journalist 便是为日报写稿的人。diary「日记」与它同源；journey「旅程」原义也是「一天的路程」，同样出自这条「日」的词根链。\",\"reporter\":\"report 源于拉丁语 reportāre「带回来」：re-「回」加 portāre「搬运」。记者干的正是把远处发生的事「搬回来」交给读者。port「搬运」这一词根家族庞大，见 portable、transport 的拆分。\",\"editor\":\"源于拉丁语 ēditor「发布者、（竞技）主办人」，出自动词 ēdere「给出、发表」：e-「出」加 dare「给」。古罗马的 editor 是出钱办角斗表演的人；印刷术之后，词转给了把文稿「发表出去」的人。\",\"novelist\":\"novel 源于意大利语 novella「新故事」，词根是拉丁语 novus「新的」。14 世纪薄伽丘的短篇集就叫 novelle「新奇的故事」；novel 后来专指长篇小说。novus 与 new 是印欧语里的远亲，novice「新手」、innovate「创新」同出一根。\",\"painter\":\"paint 经古法语 peindre 回到拉丁语 pingere「描绘、着色」，其过去分词 pictus 又生出 picture「图画」。painter 就是以 pingere 为生的人；颜料 pigment 也是这家的亲戚。\",\"musician\":\"music 源于希腊语 mousikē「缪斯的技艺」：缪斯（Mousa）是司文艺的九位女神。museum「博物馆」的本义是「缪斯的神庙」——最早收藏文艺与学问的地方。musician 是侍奉缪斯、以乐声为业的人。\",\"singer\":\"sing 是古英语 singan，日耳曼语里源远流长的老词，德语 singen 是它的亲兄弟。song 是它的名词。singer 的词形简单直接：开口唱的人。没有拉丁希腊的华丽出身，但根基极深。\",\"dancer\":\"dance 经古法语 danser 进入英语，再往上的源头并不确定：一说出自法兰克语（日耳曼语的一支）表示「摇摆、伸展」的词。学界对其祖籍尚无定论，中世纪欧洲宫廷舞兴起时，这个词跟着舞步传遍了各国语言。\",\"designer\":\"design 源于拉丁语 dēsignāre「标出、勾勒」：de- 加 signum「记号、标记」。先用线条把想法标记下来，再照着做——designer 的工作顺序就写在词里。sign「记号」是它的词根，见 signature 的拆分。\",\"programmer\":\"program 源于希腊语 programma「张贴的告示」：pro-「在前」加 graphein「写」。先「写在前面」的清单，从演出节目单一路用到计算机指令表。programmer 便是写这张「指令单」的人；graphein 还留下了 grammar、graph 等一串「写」的亲戚。\",\"developer\":\"develop 借自法语 développer「展开、解开包裹」，与 envelopper「包入」（envelope「信封」的亲戚）正好相反，dé- 表示解开。其内核 -velop 的更早来源不确切，学界无定论。软件 developer 是 20 世纪后半叶才普及的新义：把蓝图「展开」成产品的人。\",\"technician\":\"technique 源于希腊语 tekhnē「技艺、手艺、诀窍」。在希腊语里 tekhnē 指一切靠练习掌握的本事，从木工到修辞无所不包。technology 是「技艺之学」，technician 是掌握 tekhnē 并以此为业的人。\",\"investigator\":\"源于拉丁语 investīgāre「追踪、查访」：in- 加 vestīgium「足迹」。侦探的古法就是循着足迹走；vestige「遗迹、残迹」是同一个 vestīgium 的另一后代——过去留下的「脚印」。追踪与遗迹，都从这一步脚印来。\",\"lifeguard\":\"life 加 guard 的复合词。guard 经古法语 garde 回到日耳曼语的「看守」一词，与 ward「守护」、warden「看守人」同源。lifeguard 作为海滩救生员的称呼是 20 世纪初在美国定型的：守在水边，看护生命。\",\"coach\":\"coach 的老家在匈牙利小镇科奇（Kocs）：15、16 世纪那里造的轻便四轮马车风行欧洲，各国语言都以镇名呼之，英语写作 coach。19 世纪它先喻指把学生「载」过考试的辅导教师，后又转指训练运动员的人——载人过关的本行没变，只是车换了。\",\"referee\":\"refer「提交裁决」加被动后缀 -ee「被……的人」：referee 是「被双方请来裁断的人」，17 世纪先用于法律与议会。体育裁判义是 19 世纪末才有的。refer 上溯拉丁语 referre「带回、呈报」，ferre「搬运」与 lat「携带」同出一源（见 relate 的词源）。\",\"champion\":\"经古法语 champion 回到中世纪拉丁语 campiō「角斗士、为他人决斗的战士」，词根 campus 是「战场、平原」。campus「校园」与 campaign「战役」同出 campus 一门：一个是练兵的平原，一个是求学的平原。champion 最早是替领主上决斗场的人，胜者为王。\",\"leader\":\"lead 在古英语里是 lædan「引导、带领」，leader 就是走在前面领路的人。注意 lead「铅」是另一个同形词（古英语 lēad），两者无关——发音一轻一重，正好分家。\",\"chief\":\"经古法语 chief 回到拉丁语 caput「头」。部落与机构的「头」就是 chief；chef「主厨」是同一个词在法语里的后代（见 chef）。captain、chapter 都出自 caput 这一大家族：一章之「首」、一船之「头」，全是「头」的分身。\",\"boss\":\"借自荷兰语 baas「主人、工头」。17 世纪荷兰殖民者在新阿姆斯特丹（今纽约）当东家，baas 随之进入美式英语，19 世纪全面取代 master 成为口语里的「老板」。它和 base、bosom 都没有亲戚关系。\",\"chairman\":\"chair 经古法语 chaiere 回到拉丁语 cathedra「有靠背的座椅」，再上溯希腊语 kathedra。主持会议的人坐主位，chairman 便是「坐主位的人」；cathedral「大教堂」本义正是「主教座位所在的教堂」。\",\"senator\":\"源于拉丁语 senātus「元老院」，词根 senex 是「老人」。罗马元老院以年长者为尊，senator 就是院里的长老。senior「年长的」、senile「衰老的」同出 senex：参议员的头衔里，自带一份年高德劭的期许。\",\"representative\":\"represent 源于拉丁语 repraesentāre「使现前、再现」：re-「再」加 praesentāre「呈现」（prae「在前」加 esse「在」）。代表就是让缺席者「重新在场」的人。present「在场的；礼物」是这家的近亲。\",\"pioneer\":\"源于法语 pionnier「步兵、开路工兵」，词根 pion 是「步卒」，再上溯拉丁语 pēs「脚」（步兵靠脚行军）。pioneer 最初是军队里逢山开路的工兵，后来转指拓荒者与各行各业的先行者。pedestrian「行人」同出 pēs 一根。\",\"inventor\":\"invent 源于拉丁语 invenīre「遇见、发现」：in- 加 venīre「来」——走到它跟前，就是发现。古典时代 invent 只指发现与构思，近代才专指发明创造。venīre 这一家族庞大，revenue「回流的钱」、venue「到场之地」都是亲戚。\",\"banker\":\"bank 源于意大利语 banca「长凳、钱柜台」：中世纪威尼斯与佛罗伦萨的钱商就在长凳上摆摊兑换货币。bankruptcy「破产」是「砸断长凳」——摊子被砸，生意完结（词库 bankruptcy 已有词源条）。banker 就是守着这张长凳经营钱的人。\",\"broker\":\"源于盎格鲁-法语 brocour「酒商、零售中间人」，更早的来源有争议：一说与 broche「酒桶的龙头、尖签」有关，指开桶论杯卖酒的人。后来词义泛化为一切居间买卖的人。词源的细节学界未有定论，但「中间人」的身份从一开始就写在里面。\",\"consultant\":\"consult 源于拉丁语 cōnsulere「商议、请教」。古罗马的 consul「执政官」也是这条根：遇事与元老院商议的人。consultant 是「被请来商议的人」——顾问的本职，就是出主意。\",\"visitor\":\"visit 源于拉丁语 vīsitāre「去看望」，是 vidēre「看」的反复形式。visitor 是「来看的人」：来看展、来看朋友。vision、video、view 都出自 vidēre 这条「看」的词根链。\",\"tourist\":\"tour 源于拉丁语 tornus「车床」，再上溯希腊语 tornos「圆规、车床」：tour 的本义是「转一圈」。旅游就是出门转一圈再回来，tourist 正是「转圈的人」。turn「转」与它同出一源。\",\"stranger\":\"strange 源于古法语 estrange，上溯拉丁语 extrāneus「外来的、门外的」，词根 extra 是「在……之外」。stranger 就是从门外来的人；extraneous「无关的、外来的」是它的书面语亲戚。\",\"neighbor\":\"古英语 nēahgebūr 的直译就是「住得很近的人」：nēah「近」（nigh 的古形）加 gebūr「农户、居民」。在村庄年代，邻居就是隔着篱笆的那户人家。\",\"prisoner\":\"prison 经古法语 prison 回到拉丁语 prēnsiō「抓捕」，源头动词 prehendere 是「抓住」。prisoner 是被抓住、被关起的人；apprehend「逮捕；理解」是同一个 prehendere 的另一后代——抓住人，抓住意思，用的都是这只手。\",\"thief\":\"古英语 þēof，日耳曼语的老词，德语 Dieb 是它的亲兄弟；再往上的源头并不清楚。thief 的拼写里那个 ie，是中古英语的遗存。这个词不跟拉丁语 furtum 那一家（furtive「鬼祟的」）亲。\",\"robber\":\"rob 经古法语 rober 进入英语，源头是日耳曼语的「掠夺」一词，与德语 rauben 同源。有意思的是 robe「长袍」也出自这条根：战利品里最常见的就是衣服，robe 的原义竟是「掳来的衣物」。抢与袍，同出一条根。\",\"murderer\":\"murder 源于古英语 morþor「杀戮」，可上溯印欧语词根 *mer-「死」。mortal「必死的」、mortgage「死亡质押」（见词库该词词源）都是这条根的后代。murderer 是动手让别人「死」的人，词根里没有半点遮掩。\",\"suspect\":\"源于拉丁语 suspicere「暗中看、心存怀疑」：sub-「在下」加 specere「看」——从下往上斜着眼打量，就是怀疑的姿势。specere 这条「看」的词根串起了 inspect、expect、spectacle 一大家子，suspect 是其中最不信任的一个。\",\"villain\":\"源于古法语 vilain「庄园里的农奴」，再上溯中世纪拉丁语 vīllānus，出自 villa「乡间庄园」。词义堕落史很典型：庄园农人 → 粗野乡下人 → 无赖 → 恶棍。villa 与 village「村庄」是它的中性亲戚。\",\"wizard\":\"wise「智慧的」加后缀 -ard 构成（同后缀见 drunkard「酒鬼」）。wizard 最初就是「智者、哲人」，15 世纪后才专指男巫。智慧与巫术在中世纪本就只有一线之隔，这个词正好站在那条线上。\",\"witch\":\"古英语 wicce（女巫）与 wicca（男巫），再往上的确切来源学界未有定论，或与某些日耳曼语的魔法、占卜词有关。女巫迫害的年代让这个词背上厚重的历史，但词本身比那段历史老得多。\",\"devil\":\"经古英语 dēofol、拉丁语 diabolus 回到希腊语 diabolos「诽谤者、控告者」：dia-「穿过」加 ballein「投掷」，本义是隔空投掷恶言的人。《圣经》希腊文译本用它对译希伯来语的「撒旦」，devil 从此成了魔鬼的通名。\",\"king\":\"古英语 cyning 可拆为 cyn「家族、血统」加 -ing「……的后代」：king 的字面就是「族之子」。kin「亲族」与它同根。国王的合法性写在血统里，这个词从一开始就是这么说的。\",\"queen\":\"古英语 cwēn「王后；妻子」，上溯印欧语 *gʷen-「女人」。希腊语 gynē「女人」是它的远亲，藏在 gynecology「妇科」里。queen 与 quean「荡妇」古时同源，后来一个升上王座，一个跌进泥里，拼写与命运都分了家。\",\"prince\":\"经古法语回到拉丁语 prīnceps「第一人、元首」：prīmus「第一」加 capere「取」。奥古斯都就以 princeps 自称——共和国的「第一公民」。principal「主要的；校长」与 principle「原则」同出这一词：一个是居首的人，一批是居首的道理。\",\"princess\":\"prince 加阴性后缀 -ess（经法语 princesse 进入英语；-ess 再上溯希腊语阴性后缀 -issa）。中世纪童话与王室政治一起把这个词推到今天的位置：居首者（princeps）的女儿或妻子。\",\"emperor\":\"经古法语回到拉丁语 imperātor「统帅、凯旋将军」，出自动词 imperāre「下令」：in- 加 parāre「备置、安排」。imperātor 本是军队的最高指挥官头衔，屋大维之后成为皇帝专名。empire、imperial 同出一家。\",\"duke\":\"经古法语 duc 回到拉丁语 dux「领袖、统帅」，源头动词 dūcere 是「带领」。duct「管道」（把水领走）、educate「教育」（把人领出来，见词库拆分）同出 dūcere 一根。公爵原本是带兵的人。\",\"lord\":\"古英语 hlāford 是 hlāf「面包」（loaf 的古形）加 weard「守护者」的缩合：「守面包的人」，即供养一家人的家主。它的搭档 lady 出自「揉面包的女人」。封建领主的头衔，竟是从餐桌上的一块面包长出来的。\",\"reptile\":\"源于拉丁语 rēptilis「爬行的」，动词 rēpere 是「爬」。 Linnaeus（林奈）分类时用它命名这一纲冷血脊椎动物。reptile 的字面谦逊得很：会爬的那一类。\",\"beetle\":\"古英语 bitela「小咬人者」，源头是 bītan「咬」（bite）——甲虫以下颚有力、爱啃咬得名。注意锤子义的 beetle「重槌」是另一个词（与 beat 有关），同形不同源。\",\"cockroach\":\"这是民间词源改造的经典案例：蟑螂名本是西班牙语 cucaracha，17 世纪进入英语后，英国人听着像 cock「公鸡」加 roach「鲦鱼」，硬改成了 cockroach——跟公鸡和鱼其实毫无关系。\",\"cricket\":\"古法语 criquet，源头是动词 criquer「发出咯吱声」，纯粹拟声——蟋蟀的鸣叫就是它的名字。注意板球运动 cricket 是另一个来源不明的同形词，两者不要混为一谈。\",\"dragonfly\":\"dragon「龙」加 fly「蝇」的复合词。dragon 经拉丁语 dracō 回到希腊语 drakōn「大蛇」。蜻蜓在欧洲民间别名极多（如「魔鬼的缝衣针」），与龙的联名大概出于它那双大眼与迅疾的飞行。\",\"ladybug\":\"lady 指圣母玛利亚（Our Lady）：七星瓢虫红底黑点的甲壳让欧洲农民想起圣母的红袍，传说中的斑点数还被附会为圣母的七喜七悲。bug 的确切来源不明。瓢虫吃蚜虫护庄稼，名字里带着农人的敬意。\",\"moth\":\"古英语 moþþe，日耳曼语的老词。moth 与 midge「小蚊蚋」可能同源，都是小飞虫一路。蛾的幼虫啃衣物，英语旧谚里 moth 与 rust（锈）并列为毁物者，《圣经》译文沿用至今。\",\"wasp\":\"古英语 wæsp，日耳曼语的老词，其印欧源头 *wobhes- 或与 weave「编织」同根：一说黄蜂以咀嚼木纤维筑纸巢，如同织工。词义之路尚有争议，但黄蜂筑巢的本事是真的。\",\"louse\":\"古英语 lūs（复数 lȳs），印欧语里极古老的虫名，德语 Laus 是亲兄弟。单复数 louse / lice 的元音变化与 mouse / mice 同属古英语的变音复数遗存。\",\"tick\":\"古英语 ticia，西日耳曼语的虫名，再往上的来源不确切。tick「滴答声」、tick「打勾」是另外的同形词。蜱虫这个 tick 就老实地待在动物名里，与时间、记号都不相干。\",\"mite\":\"古英语 mīte 本指极小的虫，后来兼指「极微小的量」：寡妇的 mite 是《圣经》里的小额奉献，成语 the widow's mite 即源于此。螨虫与「微量」同名，因为它们都小到几乎看不见。\",\"centipede\":\"源于拉丁语 centipeda：centum「一百」加 pēs「脚」。名不副实——蜈蚣的脚数随种类从 30 到 300 多都有，却从没有恰好 100 的。centum 这条根还生了 century「百年」与 percent「百分之」。\",\"millipede\":\"近代拉丁语造词：mille「一千」加 pēs「脚」，仿 centipede 而来。同样名不副实：马陆的脚数纪录不过 700 多条，离一千还差得远。千足百足，都是夸张的整数修辞。\",\"scorpion\":\"经拉丁语 scorpiō 回到希腊语 skorpios。其更早来源不明，可能来自地中海的前希腊语言。蝎子进入星名（Scorpio 天蝎座）与矿物名（scorpion 也是旧式弩炮名），都源于那条翘起的尾刺。\",\"crab\":\"古英语 crabba，日耳曼语的老词，或与「抓爬」动作的词群相邻。值得一记的是：拉丁语里对应的 cancer 本义正是「螃蟹」，希腊语 karkinos「螃蟹」被医学之父希波克拉底借去比喻肿瘤——cancer「癌症」之名即由此来。\",\"lobster\":\"古英语 lopustre 是拉丁语 locusta 变了形的后代：locusta 在拉丁语里一词两指，既是蝗虫也是龙虾（英语 locust 只取了蝗虫义）。lobster 的后半截被英语口音改造，后来还加了 -ster 的模样。\",\"shrimp\":\"中古英语 shrimpe，来源多与「蜷缩、皱缩」联系：一说与古诺尔斯语 skorpna「收缩」或德语 schrumpfen 同族——虾弓着身子，名字说的就是这个蜷缩的姿势。定论未下，但画面统一。\",\"prawn\":\"中古英语 prayne，来源不明，词典只能止步于此。对虾与 shrimp 的分工也是近代餐饮才细分的。有些词的历史比厨房还沉默，prawn 就是一个。\",\"squid\":\"16 世纪才在英语里冒头，来源不明。一说与 squirt「喷射」有民间联想：鱿鱼受惊喷墨、借喷水逃生——但这只是猜测，无文献定论。名字来历存疑，喷墨的本事确凿。\",\"jellyfish\":\"jelly 源于拉丁语 gelāre「冻结、凝结」（gel「凝胶」、congeal「凝固」同根）：水母通体是凝胶，jellyfish 就是「胶冻鱼」。只是名字带 fish，它与鱼类毫无亲缘——这类借名在动物词里比比皆是。\",\"starfish\":\"star「星」加 fish「鱼」的直白复合词：五腕张开如星。海星既不是鱼，也不在天上——英语动物名常常先看形状下菜碟，starfish 与 jellyfish 都是这样命名的。\",\"seahorse\":\"sea 加 horse：头部弯成马首形，名字直取其形。它的学名 Hippocampus 正是希腊语 hippos「马」加 kampos「海怪」的对译——东西方看同一只小兽，想到的是同一匹马。\",\"oyster\":\"经古法语 oistre 回到希腊语 ostreon「牡蛎」，与 osteon「骨头」同族：硬壳如骨。希腊语 ostrakon「贝壳；陶片」又生出 ostracize「陶片放逐」——雅典人用贝壳碎片投票放逐政客。牡蛎这一家，从餐桌通到政治。\",\"clam\":\"古英语 clamm 本义是「抓握、钳紧」，与 clamp「夹钳」同源。蚌受惊即闭壳死钳，clam 的名字说的就是这一夹。习语 clam up「闭口不言」正是从蚌壳借的意象。\",\"mussel\":\"与 muscle「肌肉」竟是同一个词：拉丁语 mūsculus 是 mūs「老鼠」的小称，「小老鼠」——古罗马人既用它称肌肉（皮下窜动如小鼠），也称这种形似小鼠的贝类。英语里分道扬镳成 mussel 与 muscle 两个拼写。muscle 的词源故事见肌肉条下。\",\"scallop\":\"经古诺曼法语 escalope「壳」借入，源头是日耳曼语的「壳片」一词，与 scale「鳞；壳片」同族。扇贝得名于它那把能开合的扇形硬壳——壳就是本体，名字直截了当。\",\"eel\":\"古英语 ǣl，日耳曼语的老词，再往上的源头不明。鳗鱼滑不溜手，词史学家也抓不住它： eel 的祖籍至今写在词典的「 origin unknown」里。\",\"trout\":\"经拉丁语 tructa 回到希腊语 trōktēs「啃食者」，源头 trōgein 是「啃、咬」。鳟鱼贪食凶猛，见饵即咬——希腊人给它的名字，是一句食评。\",\"tuna\":\"一条清晰的借词链：西班牙语 atún ← 阿拉伯语 al-tūn ← 拉丁语 thunnus ← 希腊语 thynnos。金枪鱼是地中海的古老渔获，从希腊市场一路叫到阿拉伯与西班牙的港口，词随鱼市西行。\",\"cod\":\"中古英语 cod，来源未有定论（另一个 cod「荚、袋」是不同的词，codpiece 的 cod 即是）。鳕鱼撑起了北大西洋几百年的渔业与贸易史，它的名字却意外地沉默——词典在此只能存疑。\",\"bass\":\"指鲈鱼的 bass 是古英语 bærs，本指多刺的鲈（或与 bristle「刚毛」同族——背上竖着鳍刺）。注意音乐里的 bass「低音」是意大利语 basso「低」，两词同形异源，读音也不同，别让乐队抢了渔船的词。\",\"carp\":\"经中世纪拉丁语 carpa 传入，源头可能在日耳曼语诸语言（鲤鱼养殖由多瑙河流域西传，词也随之西行）。另有一个同形动词 carp「挑剔抱怨」，来自古诺尔斯语 karpa「夸口」，与鲤鱼无关。\",\"catfish\":\"cat「猫」加 fish「鱼」：鲶鱼口边长须，像猫的胡须。18 世纪在美洲河流里定名的复合词——命名者显然是照着脸起的。\",\"piranha\":\"经葡萄牙语借自图皮语（巴西原住民语言）：一说 pirá「鱼」加 sainha「牙」，「有牙的鱼」；一说义为「剪刀」。两种说法都指向同一处：那口锯齿。\",\"seagull\":\"sea「海」加 gull 的复合词。gull 的源头或在凯尔特语：威尔士语 gwylan 是海鸥名，其鸣声也是词源灵感的常客。海岸线上空盘旋的白影，名字里一半是海，一半是它自己。\",\"pelican\":\"经拉丁语 pelicānus 回到希腊语 pelekan。 pelekan 的词源细节有争议，一说与 pelekys「斧头」相关——那张长喙开合确如斧。鹈鹕在中世纪传说里以血哺子，后世文学沿用了这个并不真实的形象。\",\"ostrich\":\"经古法语 ostruce、拉丁语 strūthiō 回到希腊语 strouthion「大鸟」；而 strouthos 在希腊语里本指麻雀这样的小鸟——最大的鸟顶着「大麻雀」的名字，是希腊人的冷幽默。词首多出的 o- 是法语阶段黏上的（与 island 里多出的 s 是同类事故）。\",\"peacock\":\"pea- 来自古英语 pāwa（再上溯拉丁语 pāvō「孔雀」，或为拟声其鸣叫），加 cock「公鸡」。雌孔雀叫 peahen。开屏的是雄鸟，名字里也就明写着公字。\",\"swan\":\"古英语 swan，日耳曼语的老词。一说它与印欧语 *swen-「发声」同根（天鹅以鸣声闻名，拉丁语 sonus「声音」是远亲）——但此说未成定论。词典对 swan 的祖籍保持克制：老日耳曼词，更早存疑。\",\"duck\":\"古英语 dūce，与动词 dȳfan「潜入、下扎」同族：鸭子是「爱扎猛子的鸟」。动词 duck「低头闪避」是同一动作的人版——头往下一扎，水鸟与人都一样。\",\"chicken\":\"古英语 cicen「小鸡」，拟声色彩浓厚（咯咯声）。chick 是它的简版。成年鸡在古英语里另有 hana（公）与 henn（母，hen 的祖形），chicken 从「小鸡」起家，后来成了全族的通称。\",\"rooster\":\"roost「栖木」加 -er：「上架栖息的（雄）鸟」。rooster 是 18 世纪末在美国兴起的替代词，当时 cock 的粗俗引申义让人们避讳原名——一只鸟的名字，竟是被礼貌逼出来的。\",\"parrot\":\"源于法语 perroquet，更早来源有争议：一说它是 Pierrot「小彼得」的变体（法国人爱给鹦鹉起人名），一说与西班牙语 perico 相连。无定论，但鹦鹉学舌起人名，先得有个名字——这个猜测本身倒很贴题。\",\"canary\":\"以加那利群岛（Canary Islands）命名的鸟。群岛名源于拉丁语 Canāriae Īnsulae「狗之岛」：罗马作家普林尼说岛上多巨犬（canis「狗」）。于是绕了一圈：狗之岛产的鸟，叫了 canary。canine「犬的」是 canis 的另一后代。\",\"robin\":\"Robin 是人名 Robert 的昵称，被英国人送给了红胸的知更鸟（原名 robin redbreast「红胸罗宾」）。北美移民见到当地的红胸鸫，顺手叫了同一个名字——美洲知更鸟与英国知更鸟并不同种，名字却一起移民了。\",\"raven\":\"古英语 hræfn，源头是拟声：印欧语 *ker- 一族专出乌鸦叫声类的词，crow「乌鸦」是近亲。渡鸦体型最大、叫声最沉，名字里留着那声哑鸣。\",\"magpie\":\"Mag 是 Margaret 的昵称（喻喜鹊鸣声聒噪如话痨），加 pie——pie 上溯拉丁语 pīca「喜鹊」。pica 后来还被医学借走：异食癖叫 pica，因为喜鹊见什么都叼。叼东西的名声，跟着这个词进了教科书。\",\"cuckoo\":\"拟声词，经古法语 cucu 借入，摹的就是布谷鸟那两声标志性鸣叫。cuckold「被戴绿帽者」正是从它演变来的：布谷鸟在别鸟巢里下蛋，中世纪的法国人把这层意思挪到了人身上。\",\"woodpecker\":\"wood「林木」加 pecker「啄者」的直白复合。peck「啄」本身或与 pick 同族。啄木鸟一生在树干上敲门，名字就是它的工种说明。\",\"bat\":\"中古英语 bakke，源头可能在斯堪的纳维亚语：古瑞典语 natbakka 字面是「夜蝙蝠」。蝙蝠在英语古名里本可叫 flittermouse「飞鼠」（与德语 Fledermaus 一致），bakke 简单胜出，flittermouse 只留在方言里。\",\"squirrel\":\"一段可爱的希腊语：skia「影子」加 oura「尾巴」组成 skiouros——坐在自己尾巴的阴影里。经拉丁语 sciūrus、古法语 esquirel 进入英语，拼写一路变形，本义一路被遗忘。松鼠那条大尾巴遮阳，希腊人看在眼里，写进了名字。\",\"chipmunk\":\"借自阿尔冈昆语族的奥吉布瓦语 ajidamoo（拼写随方言而异），意为「头朝下倒挂（下树）者」——花栗鼠下树正是头朝下。17 世纪的北美殖民者向原住民学来了这个精准的动作描写。\",\"beaver\":\"古英语 beofor，上溯印欧语 *bhebhru-「棕色的」：河狸以一身棕毛得名。拉丁语 fiber、德语 Biber 都是同根兄弟。顺带说：beaver 与 beverage「饮料」毫无关系，别被前缀骗了。\",\"otter\":\"古英语 otor 可上溯印欧语词根 *wed-「水」：water「水」、wet「湿的」都是同族。水獭的名字就是「水里的那个」——词根直接，不绕弯。\",\"skunk\":\"17 世纪借自马萨诸塞特一带的阿尔冈昆语 seganku（拼写不一）。新英格兰的殖民者对这种会放臭气的动物印象深刻，连名字都是向原住民现学的。\",\"raccoon\":\"借自弗吉尼亚的波瓦坦语 ärähkun（拼写随记录者而异），意为「用双手抓挠（洗涮）的动物」。波卡洪塔斯的年代，它的名字跟着毛皮贸易进了英语。浣熊那双不停搓洗的手，原住民早就写进了名字。\",\"opossum\":\"同样借自波瓦坦语 apasum，意为「白色的兽」。possum 是它在口语里的缩略形。背着育儿袋、遇险装死——名字只说了毛色，本事得另学。\",\"kangaroo\":\"借自澳大利亚约克角原住民古古伊米迪尔语 gangurru，指当地一种大袋鼠。1770 年库克船长的船员在当地记录下这个词。流传甚广的「kangaroo 本义是『我听不懂』」只是讹传，语言学家已证伪——这个澄清本身，比传说更值得记。\",\"koala\":\"借自悉尼一带原住民达拉格语 gula（亦作 gulawan）。18、19 世纪的殖民记录拼写几经变化，koala 定型。考拉几乎不喝水（水分全来自桉树叶），「不喝水」是附会在它名字上的民间说法，非词源本义。\",\"panda\":\"来源不确切：一说经法语 panda 借自尼泊尔一带的语言，指当地吃竹子的兽（尼泊尔语有 ponya 之类的称呼与小熊猫相关）。这个词最早贴在小熊猫身上，大熊猫被发现后借用了它。词源的细节，词典诚实地留了白。\",\"wolf\":\"古英语 wulf，上溯印欧语 *wĺ̥kʷos，是欧亚大陆最古老的兽名之一：希腊语 lykos、拉丁语 lupus（经方言音变）都是它的亲戚。狼在哪儿，词就跟到哪儿。\",\"coyote\":\"经西班牙语 coyote 借自纳瓦特尔语 coyotl。郊狼是北美草原的原住民，阿兹特克人给它起的名字随西班牙殖民进入欧洲语言，原样未译。\",\"lion\":\"经古法语回到拉丁语 leō，再上溯希腊语 leōn；再往东的终极源头不明，可能借自某种闪语或古埃及语——狮子本就不是欧洲的动物，词也是进口的。leopard 是 leō 加 pardos 的拼凑（见 leopard）。\",\"leopard\":\"希腊语 leopardos：leōn「狮」加 pardos「豹」——古希腊罗马人以为豹是狮与豹的混血，这个名字就是那场误会。pardos 是更古老的豹名，后来单用 pard 也指豹。误会散了，名字留下了。\",\"cheetah\":\"借自印地语 cītā，上溯梵语 citraka「有斑纹的」，词根 citra 是「斑斓、醒目」。猎豹一身斑点，名字就是一幅速写。\",\"jaguar\":\"经葡萄牙语借自图皮-瓜拉尼语 yaguara：在图皮语里本是「野兽」的通称，尤其指这类食肉猛兽。亚马逊的猎手叫它什么，欧洲人就跟着叫什么。\",\"cougar\":\"经法语 couguar、葡萄牙语 çuçuarana 回到图皮语 suasuarana：suasu「鹿」加 rana「像、假」——「假鹿」。图皮人为什么管美洲狮叫假鹿，有说是毛色近鹿，有说是它猎鹿。名字的比喻义细节，说法不一。\",\"lynx\":\"经拉丁语回到希腊语 lynx，更深的源头或与印欧语 *leuk-「光」相连：一说因它双眼明亮夜视（传说猞猁的目光能穿墙）。light「光」是这条根最有名的后代。此说未成铁案，但猞猁的招牌正是那双眼睛。\",\"rhino\":\"rhinoceros 的缩略：希腊语 rhīs「鼻子」加 keras「角」——鼻子上长角的兽。犀牛角不是骨头，是角蛋白（与指甲同质）；keras 这条「角」根还生了 unicorn 独角兽的一半（见 horn 的亲戚 cornu 一族）。\",\"zebra\":\"借自葡萄牙语 zebra，它在伊比利亚半岛本是野驴的名字。词源链条有争议：主流意见认为它与拉丁语 equiferus「野马」（equus「马」加 ferus「野的」）的演变有关，但中间环节并无定论。斑马是非洲的兽，名字却是在伊比利亚半岛转手的。\",\"donkey\":\"18 世纪下半叶才出现的新词，确切来源不明：或与 dun「灰褐色」加小称 -ey 有关（毛色命名），或源于人名 Duncan 的昵称，或是仿 monkey 押韵造的词。驴在英语里本名 ass（拉丁语 asinus），donkey 是个来历不明的后来者——词典在此如实存疑。\",\"mule\":\"经古法语回到拉丁语 mūlus，拉丁语这个词本身的更早来源不明，或是地中海一带某古语言的借词。骡是驴马杂交的产物，拉丁名跟着帝国的驿道传遍欧洲。（指鞋的 mule「穆勒鞋」是另一来源，不要混。）\",\"llama\":\"经西班牙语 llama 直接借自克丘亚语 llama。安第斯山民驯养它几千年，西班牙人照着克丘亚语的叫法原样搬进欧洲语言——与 kangaroo 一样，是殖民者笔记本上的原住民词。\",\"deer\":\"古英语 dēor 的本义是泛指的「野兽、动物」，不限于鹿（莎士比亚文中仍有此用法，与德语 Tier「动物」同源）。中世纪后词义收窄，专归给鹿科。读旧文学时遇到 deer，先别急着在脑内放出一头鹿。\",\"elk\":\"源于古英语 eolh 与古诺尔斯语 elgr，是北欧的老兽名，更早的源头或与印欧语 *el-「红棕色」相连（指毛皮色），未成定论。在英国 elk 指驼鹿，在北美被转用给马鹿（wapiti）——同名异兽，跨大西洋时要小心。\",\"moose\":\"借自纳拉甘塞特语（阿尔冈昆语族）moos，一说本义为「它剥下（树皮）吃」——驼鹿啃食树皮与嫩枝，原住民以食性为它命名。17 世纪初进入英语，是北美大兽里最早「入籍」的原住民词之一。\",\"reindeer\":\"源于古诺尔斯语 hreindýri：hreinn 就是驯鹿（北欧词，或借自萨米语），dýr 是「兽」。要澄清一个节日误会：reindeer 的 rein 与「缰绳」reign/rein 拼写相近却无亲戚关系——圣诞老人手里的缰绳，是后人望文生义。\",\"caribou\":\"经加拿大法语 caribou 借自米克马克语 qalipu「铲雪者」：北美驯鹿冬天用蹄子刨开积雪啃食地衣，原住民的命名精准到动作。reindeer 是它的欧洲亲戚（不同亚种），caribou 是北美本地的名字。\",\"buffalo\":\"经葡萄牙语或西班牙语 búfalo 回到拉丁语 būfalus（希腊语 boubalos），本指水牛一类的野牛。美洲的 bison 被早期欧洲殖民者误叫 buffalo，叫错了三百年，也就成了正名——词典至今为它保留着这个「将错就错」的身份。\",\"ox\":\"古英语 oxa，上溯印欧语 *ukʷs-én-，是欧亚农耕语言共有的老词（德语 Ochse 是亲兄弟）。复数 oxen 保留了古英语的弱变化 -en 尾，与 children 是同一种古董。\",\"bull\":\"源于古诺尔斯语 boli（古英语作 bula），或与表示吼叫的词群相邻——公牛以吼声与体格立名。此说未完全坐实。bull 与 boletus 等拉丁词无关；它与 bear「熊」也不是亲戚，拼写相近而已。\",\"cow\":\"古英语 cū，上溯印欧语 *gʷōus，是欧亚语言最古老的家畜名之一，常被认为带拟声色彩（哞）。拉丁语 bōs 是同根兄弟，走的是另一条音变路，最后变成餐桌词 beef 的祖先（见 beef）。同一头牛，栏里与桌上，两个名字两种语言。\",\"calf\":\"古英语 cealf，日耳曼语的幼畜通名。注意小腿肚 calf 是另一个同形词，源于古诺尔斯语 kálfi，与牛无关——人的小腿鼓起如幼兽之形，是后世的形似联想，两词各过各的。\",\"sheep\":\"古英语 scēap，日耳曼语的老词，更早源头不确切。单复数同形（a sheep / two sheep）是古英语一批中性名词的遗存，与 deer 相同。羊是英语农场里最老的住户，名字也最不事雕琢。\",\"lamb\":\"古英语 lamb，日耳曼语的老词。拼写末尾的 b 在中古英语后期才加上，本就不发音（与 climb、thumb 的哑 b 是同类装饰）。羔羊肉与羊羔同名，不像 beef / cow 那样分家——羊在诺曼餐桌上的待遇，留在了词里。\",\"pig\":\"中古英语 pigge 原专指小猪，来源不明；成年猪的通名是 swine。pig 后来居上统称全族，swine 退守书面与骂人的场合。猪词在英语里身世最杂，这个顶梁柱的来历偏偏最不清楚，词典只能存疑。\",\"boar\":\"古英语 bār，日耳曼语的老词，德语 Bär 一类并不同源（那是熊）；boar 的更早源头不确切，或与「刚猛」义的词群相关，未成定论。野猪獠牙凶悍，词史却给不出更细的出处。\",\"sow\":\"古英语 sugu，上溯印欧语 *sū-：拉丁语 sūs、希腊语 hŷs 都是同根的猪名。提醒一个经典假朋友：sow「母猪」与 sew「缝纫」同形，但读音不同（/saʊ/ 与 /soʊ/），源头也毫不相干。\",\"rabbit\":\"中古英语 rabet 原专指幼兔，可能源于古法语或瓦隆语的某个小称，确切来源未有定论。成年兔的旧名是 coney（源于拉丁语 cunīculus），18 世纪后 rabbit 接管全族，coney 只剩地名与《圣经》译本里的踪迹。\",\"rat\":\"古英语 ræt，来源不明：它出现得突然，有说是拟声啃咬，有说与拉丁语 rattus 有某种平行关系，均无定论。老鼠随人类粮仓遍布世界，名字却在词源学里断了线。\",\"mole\":\"中古英语 molle，来源有争议：一说与 mold「泥土」相邻——鼹鼠的古名 mouldwarp 字面就是「抛土者」，出土成堆正是它的招牌。此说未定论。另外 mole 还有痣、防波堤、摩尔等几个同形词，各自独立，不要混。\",\"porcupine\":\"源于古法语 porc espin「带刺的猪」：porc 是猪（拉丁语 porcus），espin 是刺（拉丁语 spīna）。豪猪与猪并无亲缘，命名者看的是体型与那一身针。spine「脊柱；刺」是 spīna 的另一后代。\",\"monkey\":\"来源争论颇多：一说出自中古低地德语 Moneke——《列那狐》故事里猴子的名字（Martin 的儿子），一说与 monk「修士」的戏称相关。猴子词历来爱和人名搅在一起，确切源头无定论，词典如实存疑。\",\"chimpanzee\":\"源于刚果河流域的班图语言：一说来自奇卢巴语或刚果语的 kivili-chimpenze，意近「似人的兽」。18 世纪经葡萄牙语与法语记录进入英语。具体的源语言细节各书记载略有出入，刚果源头则无异议。\",\"orangutan\":\"借自马来语 orang hutan：orang 是「人」，hutan 是「森林」——「森林里的人」。当地人对这种红毛猿的称呼被荷兰与英国的博物学家原样记下，成了它的世界通行证。\",\"baboon\":\"源于法语 babouin。词源有一说与法语 baboue「撇嘴、鬼脸」相关——狒狒那张长脸龇牙时，正像在做鬼脸。此说未成定论，但 baboon 从中世纪起就是滑稽丑角的代名词，词义倒与猜测很合拍。\",\"lemur\":\"源于拉丁语 lemurēs「亡灵、夜游的鬼魂」。林奈给马达加斯加这群夜行动物起名 lemur：大眼睛在夜里发亮，动作悄无声息，如见幽灵。romans 的祖先崇拜里 lemures 是不安分的亡魂，名字带着一丝阴气。\",\"vegetable\":\"源于拉丁语 vegetābilis「能生长的」，动词 vegetāre 是「赋予生机」，再上溯 vegēre「活跃、有生气」。vegetable 最初是形容词「植物的」，17 世纪后才专指餐桌上的菜蔬。vegetarian 同根：吃「长出来的东西」的人。\",\"cabbage\":\"经古法语 caboche「头」可回到拉丁语 caput「头」：卷心菜层层包成一个「头」。caput 这一家族在词库里枝繁叶茂——chef、chief、captain 都是一颗「头」生出来的（见 chief 的词源）。\",\"cauliflower\":\"源于意大利语 cavolfiore / 中世纪拉丁语 caulis flōs：caulis 是「茎、甘蓝」，flōs 是「花」——「甘蓝开出的花」。caulis 这条根还藏在 coleslaw 的 cole 与德语 Kohl 里。吃的花球，名字里写得明白。\",\"broccoli\":\"借自意大利语 broccoli，是 brocco「嫩芽、小枝」的复数（brocco 再上溯拉丁语 broccus「尖突的」）。意大利人吃的正是一簇未开的小花芽；英语把复数形式整个借来当单数用——餐桌上说 a broccoli，其实偷了个复数。\",\"lettuce\":\"经古法语 laitue 回到拉丁语 lactūca，而 lactūca 源于 lac「奶」（属格 lactis）：莴苣茎叶折断处会渗出白色乳汁。lactic「乳酸的」、galaxy「银河」（希腊语 gala 也是奶）都在这条「乳」的词根线上。\",\"celery\":\"经法语 céleri 回到意大利语 seleri（拉丁语 selīnum 的复数形式），再上溯希腊语 selinon「芹菜、欧芹」——希腊语里芹菜与欧芹本是一家。注意它与 celerity「迅速」无关，那是拉丁语 celer 的后代。\",\"cucumber\":\"经古法语回到拉丁语 cucumis / cucumer-，其更早来源不明，或是地中海某种前拉丁语言的借词。旧拼写 cowcumber 曾通行二百年，读法被词形牵着走；约翰逊博士的词典里用的正是那个怪拼写。\",\"pumpkin\":\"链条很长：希腊语 pepōn「熟瓜」（源头 pept-「煮、晒熟」）→ 拉丁语 pepō → 法语 pompon → 英语 pumpion，再加指小后缀 -kin 定型为 pumpkin。melon 里的 pepōn 与它是同一个词（见 melon）：瓜熟蒂落，词也一路熟着走。\",\"zucchini\":\"借自意大利语 zucchini，是 zucca「葫芦、南瓜」的复数小称（zucca 再上溯晚期拉丁语 cucutia 一类的葫芦名）。与 broccoli 一样，英语把意大利语的复数整个借来当单数用。绿皮夏南瓜本是美洲南瓜的嫩果，名字却在意大利定型。\",\"eggplant\":\"egg「蛋」加 plant「植物」：18 世纪英国流行的茄子品种结白色卵形小果，像挂在枝上的鸡蛋（今天常见的紫长茄是另一品种）。茄子经印度、阿拉伯世界西传，意大利语 melanzana 曾被民间误读成 mela insana「疯苹果」——无端背了个疯名。\",\"chili\":\"经西班牙语 chile 直接借自纳瓦特尔语 chīlli。辣椒原产美洲，阿兹特克人的名字随哥伦布之后的 Columbian Exchange（物种大交换）传遍世界；英语拼写 chili / chilli / chile 三式并存，都是它。\",\"onion\":\"源于拉丁语 ūniō，本义是「合一、单个」，也指大颗珍珠（因其独粒）。洋葱层层裹成一个完整的球，罗马人就以「一体」名之。union「联合」与它同出 ūnus「一」：一颗洋葱里，藏着个统一的概念。\",\"carrot\":\"经法语 carotte、拉丁语 carōta 回到希腊语 karōton。其词根细节有一说与 kara「头」相关（指根部的头状膨大），未成定论。胡萝卜由阿富汗一带驯化西传，橙色品种是 17 世纪荷兰园艺家的作品，词比橙色老得多。\",\"corn\":\"古英语 corn 本义是「谷粒、（当地的）主粮」，上溯印欧语 *ǵr̥h₂nóm，与 grain、kernel 同根。到了美洲，corn 被殖民者专指当地主粮玉米（原住民的 maize）；在英国，corn 至今可指小麦。玉米的英文正名是 maize，corn 是半路转正的地方名。\",\"pea\":\"17 世纪的一次「听错」：pease 本是不可数名词（像 rice 一样是集合名），以 -se 结尾被误听成复数，于是倒推出单数 pea——这叫逆构词（back-formation）。pease 上溯拉丁语 pisum、希腊语 pison。豌豆的单数，是耳朵造的词。\",\"soybean\":\"soy 先行：日语 shōyu「酱油」借入英语作 soy（shōyu 再往上是汉语「酱油」的音）。19 世纪大豆作为酱油原料被西方认识，先以 soy bean 之名立户——豆排在酱后，顺序说明它当年是配角。bean 本身是古英语的老词。\",\"peanut\":\"pea「豌豆」加 nut「坚果」的复合词：荚像豆、仁像坚果，但花生最特别的是花落后把子房扎进土里结果——别名 groundnut「地坚果」说的就是这件事。名字有两个，角度各不同。\",\"cashew\":\"经葡萄牙语 caju 借自巴西图皮语 acaju。腰果树原产巴西，葡萄牙人把它带向非洲与印度，今天越南、印度成了主产地——词却还留着图皮语的原名。\",\"walnut\":\"古英语 wealhhnutu 的直译是「外国的坚果」：wealh 指异邦人（尤指南方的罗马-高卢世界，Welsh「威尔士人」同源）。核桃原产波斯一带、经罗马传入不列颠，在盎格鲁-撒克逊人眼里是正经的进口货，名字里盖着海关的戳。\",\"chestnut\":\"经古法语 chastaigne 回到拉丁语 castanea，再上溯希腊语 kastaneia。希腊名有一说来自小亚细亚的地名 Kastana（以产地命名果子）。指箱子的 chest 是另一个词（拉丁语 cista），与栗子同形不同源。\",\"coconut\":\"葡萄牙语 coco 在航海时代指哄孩子的「鬼脸精」：椰壳底部三个黑孔像一张脸，葡萄牙水手便以 coco 呼之，英语再加 nut 点明果核。椰子脸朝着人，名字就这么定下来了。\",\"olive\":\"经拉丁语 olīva 回到希腊语 elaia，其根源在地中海更古老的语言里。olive oil 的 oil 与它同出一系（拉丁语 oleum 本就是橄榄油）。橄榄枝的和平象征源自《圣经》与希腊神话，词本身比象征还老。\",\"avocado\":\"经西班牙语 aguacate 借自纳瓦特尔语 āhuacatl——这个词在纳瓦特尔语里兼指此果与睾丸（取其形）。英语 avocado 的拼写是被民间词源改过的：人们拿它与西班牙语 abogado「律师」混过一阵，最终定成现在的模样。\",\"date\":\"指枣的 date 经古法语、拉丁语 dactylus 回到希腊语 daktylos「手指」：椰枣细长成串，形如手指垂下。注意表示日期的 date 是另一个词（拉丁语 datum「给定的」），同形不同源——一只手与一份文书的区别。\",\"plum\":\"经古英语回到拉丁语 prūnum，再上溯希腊语 proumnon，其终极源头或在西亚某古语言。prune「西梅干」是 prūnum 的法语后代。注意测深的 plumb 与铅 plumbing 是 plumbum 一家，与李子无关。\",\"papaya\":\"经西班牙语 papaya 借自加勒比地区阿拉瓦克语的 papaia。英语 pawpaw 与它同源（指北美泡泡果时已转指别种）。哥伦布之后的物种交换里，木瓜从美洲走向了全世界的热带餐桌，名字也跟着上了船。\",\"pomegranate\":\"经古法语 pome grenate：pome 是「苹果」（拉丁语 pōmum，本义泛指果实），grenate 源于 grānum「籽粒」——「多籽的苹果」。手榴弹 grenade 正是借石榴之形与多籽（弹片）得名，与它同根。grain「谷粒」是 grānum 最有名的后代。\",\"blueberry\":\"blue 加 berry 的直白复合。berry 是古英语 berie「浆果」。蓝莓本是北美野生浆果，20 世纪初才被驯化栽培成今天的模样，名字则一直是农人口中的直呼。\",\"raspberry\":\"rasp 是「锉刀；粗糙」，raspberry 的得名一说在于果面覆着细毛、触感粗糙如锉；另一说与 raspis（一种淡红葡萄酒）有关。两种说法并存，无定论——但无论哪种，raspberry 那个独一无二的词尾 -p- 都来自粗糙的那一面。\",\"blackberry\":\"古英语 blæcberige 的直译复合：黑色的莓。黑莓在不列颠野生极多，古英语时代就已有名，不像许多浆果词是后来的拼凑——它从一开始就叫这个。\",\"cranberry\":\"源于低地德语 kraanbere「鹤的莓」：蔓越莓开花时花瓣反卷，像仙鹤低垂的头颈，果又生在鹤栖息的沼泽里。经新英格兰传开后，德语名头换成英语拼写，鹤的意象还留在词根里。\",\"watermelon\":\"water 加 melon 的直白复合：果肉九成以上是水。melon 的希腊词源见 melon 条（「苹果瓜」）；watermelon 的祖籍是非洲，词却是英语自己拼的。\",\"cantaloupe\":\"以意大利拉齐奥的 Cantalupo 地名得名：那里曾是教皇的乡间庄园，传说哈密瓜的种子由亚美尼亚传入、先在此地种成。地名在意大利语里字面是「狼嚎」，与瓜无关，瓜只是在那儿落了户。\",\"lime\":\"指酸橙的 lime 经法语、西班牙语回到阿拉伯语 līmah，与 lemon 同路（源头是波斯语 līmūn）。注意石灰 lime 是古英语 līm，日耳曼老词——果园与窑厂同名，是英语里的一场巧合。\",\"basil\":\"经拉丁语回到希腊语 basilikos「王的、王室的」，源头 basileus 是「国王」。罗勒在地中海传统里被奉为香草之王，名字就是王冠。basilica「长方形大教堂」同出 basileus：原义是「王宫式的厅堂」。\",\"mint\":\"经拉丁语 mentha 回到希腊语 minthē。神话里冥王哈得斯的恋人明忒（Minthē）被冥后踩作一株香草，薄荷之名即由此传说附会；词本身可能出自前希腊语言。注意造币厂 mint 是另一个词（拉丁语 monēta），与薄荷无关。\",\"parsley\":\"经拉丁语回到希腊语 petroselinon：petra「岩石」加 selinon「芹菜」——「生在岩石上的芹」。petra 这条「石」根还生出了 Peter（磐石）与 petroleum（石中油）。欧芹在希腊人眼里是石缝里的芹菜。\",\"cilantro\":\"经西班牙语 cilantro 回到拉丁语 coriandrum，再上溯希腊语 koriannon「芫荽」。英语里分工有趣：coriander 多指种子与粉末，美式英语的 cilantro 专指鲜叶——同一株植物，两个名字按部位上岗。\",\"dill\":\"源于古诺尔斯语 dilla「哄睡、安抚」。莳萝在北欧古方里用于安神助眠、哄婴儿入睡，名字就是它那剂草药的功效说明；此说未完全坐实，但是词典里最常见的解释。\",\"thyme\":\"经拉丁语回到希腊语 thymon，一般认为源于 thyein「焚烧、献祭」：百里香是希腊祭坛上的焚香料。它又与 thymos「心气、勇气」相邻——传说希腊士兵沐浴百里香水以壮胆。香与勇，同一个词根里升起。\",\"oregano\":\"经拉丁语回到希腊语 orīganon：oros「山」加 ganos「光彩、喜悦」——「山岳的喜悦」。地中海山坡上野牛至成片开放，希腊人这个名字起得颇有诗意，词典记载一致。\",\"cinnamon\":\"经古法语与拉丁语回到希腊语 kinnamōmon，是闪语借词（希伯来语 qinnāmōn），由腓尼基商人沿香料之路带进地中海。肉桂取的是树皮，卷成管状出售，希腊人最早只闻其名、不知其树，产地被商人故意说得云山雾罩。\",\"vanilla\":\"借自西班牙语 vainilla，是 vaina「豆荚、鞘」的小称（vaina 再上溯拉丁语 vāgīna「鞘」）。香草兰的果荚细长如小鞘，名字就按形状起。香草原产墨西哥，托托纳克人与阿兹特克人先于欧洲人用它调味可可。\",\"cocoa\":\"经西班牙语 cacao 回到纳瓦特尔语 cacahuatl「可可豆」。cocoa 这个拼写是 18 世纪以后被 coco（椰子）带偏的结果，本与椰子无关。顺带分清：cacao / cocoa 是巧克力原料，coca 是古柯，完全两回事。\",\"barley\":\"古英语 bere 是「大麦」，barley 原作 bærlic「大麦的」。barn「谷仓」本是 bere 加 ærn「房子」——「放大麦的屋子」。barley 的印欧源头或与「麦芒、刺尖」相关，未成定论；但它与 barn 的亲戚关系是实打实的。\",\"oat\":\"古英语 āte（多用复数 ātan），更早来源不明。在英格兰，燕麦常被视为马料（约翰逊博士词典里那句著名刻薄话即源于此）；苏格兰人以它为主粮。同一个词，两地两种身价。\",\"rye\":\"古英语 ryge，可上溯印欧语 *wrughyo- 一系，德语 Roggen、俄语 rozhʹ 都是同根的黑麦名。黑麦耐寒，词也带着北方农耕的凉意。\",\"millet\":\"经法语 millet 回到拉丁语 milium「粟」。milium 是否与 mille「千」同根（因一穗千籽）说法不一，未成定论。小米是中国最古老的谷物之一（粟），它的西方名字走的是拉丁—法语一线。\",\"sorghum\":\"经意大利语 sorgo、中世纪拉丁语 sorghum 而来；更早的来源有争议，一说与「叙利亚」（Syricum）相关——经印度与中东转手传入的路线留在了名字里。此说未成定论，词典多标注 uncertain。\",\"quinoa\":\"经西班牙语直接借自克丘亚语 kinwa。藜麦是安第斯高原的古老谷物，印加人称它「万谷之母」；名字跟着种子一起下山，拼写被西班牙语转写定格。\",\"dough\":\"古英语 dāh「揉好的面团」，上溯印欧语词根 *dʰeyǵʰ-「揉捏、塑造」。拉丁语的 fingere「塑造」是同根兄弟——fiction「虚构」（塑造出来的故事）的拆分里正有它。面包房与小说家，用的是同一双手。\",\"yeast\":\"古英语 gist / gyst，与德语 Gischt「泡沫」相邻：一说其印欧源头与「沸腾、冒泡」相关（希腊语 zein「沸腾」是远亲）。酵母让面团与酒液起泡，名字若真出于泡沫，正是对发酵最直观的命名。此说常见，但非铁案。\",\"crumb\":\"古英语 cruma「碎块」，尤指面包的内瓤与掉落的屑。crust 是外皮，crumb 是内里：英语把一块面包的内外分得清清楚楚。crumble「弄碎」就是把整块变成 crumb 的动作。\",\"slice\":\"经古法语 esclice「劈下的薄片」可回溯法兰克语的日耳曼词根「撕裂、劈开」（与 slit「裂口」同族）。slice 的本行是从整块上劈下来的那一片：先劈，后有片。\",\"chunk\":\"18 世纪在美洲英语里出现的词，来源未定：或与 chuck「投掷；一大块」相连，或是拟声造词。词典对 chunk 的出身只能写 origin unknown。有些词年轻得查得到生日，却查不到父母。\",\"kernel\":\"古英语 cyrnel 是 corn「谷粒」加指小后缀 -el 构成的：「小谷粒」。它后来引申为一切事物的核心——坚果仁、思想要点、操作系统的 kernel，都是从谷粒的心开始的。colonel「上校」与它无关，别被读音骗了。\",\"stalk\":\"指茎的 stalk 是中古英语的词，或为 stale「长杆、梯档」一类的指小形式，细节未完全定论。与它同形的 stalk「潜步追踪」是另一个词（猎手分步潜近猎物），两者各有出处，不要混讲。\",\"bacon\":\"源于古法语 bacon，更早是日耳曼语的 *bakkon「背肉」（back「背」一族）：猪背与后腿肉盐腌烟熏，就是 bacon。培根的英文名几乎直说部位：用盐与烟收拾过的猪背肉。\",\"steak\":\"借自古诺尔斯语 steik「烤肉」，动词 steikja 是「（串在扦子上）炙烤」，或与 stick「扦子」同族。牛排的祖先是维京人架在火上的一串肉；后来才有煎锅里的厚切。\",\"beef\":\"诺曼征服留下的餐桌分工：栏里活牛叫古英语的 cow，端上贵族餐桌的肉叫法语的 bœuf（源于拉丁语 bōs「牛」）。司各特在《艾凡赫》里借人物之口点破过这条规矩：干活的撒克逊人养牲口，吃肉的诺曼老爷命名肉。\",\"pork\":\"与 beef 同理：古法语 porc 回到拉丁语 porcus「猪」——诺曼人的餐桌词。porcupine 的前一半就是它（见 porcupine）。活猪在栏里叫 swine / pig，上了桌就得说法语。\",\"mutton\":\"与 beef、pork 同属诺曼餐桌词：古法语 moton，上溯中世纪拉丁语 multō，源头可能在凯尔特语（指公羊）。撒克逊人栏里养 sheep，诺曼人桌上吃 mutton——同一套分工，羊也没逃过。\",\"axe\":\"古英语 æx，日耳曼语固有词，与希腊语 axinē、拉丁语 ascia 在印欧层面同源：石器时代的工具，留了一个石器时代的老词。美式拼写常简作 ax。\",\"axiom\":\"来自希腊语 axiōma「被认为值得接受的命题」，词根 axios 是「值得的」。欧几里得把 axiom 立为几何的出发点：不必证明，因为「值得相信」就是它的通行证。\",\"badminton\":\"以地名命名：19 世纪英国格洛斯特郡有座 Badminton House 公爵庄园，驻印军官把印度的 poona 球戏带回英国并在庄园里推广，运动便随庄园得名；庄园名本身的来历则另有古英语渊源。\",\"bakery\":\"透明派生词 bake + -ery（场所后缀）。bake 是古英语 bacan，日耳曼固有词，在印欧层面可能与希腊语 phōgein「烘烤」同源——烘烤这件事，各语言都留了老词。\",\"balloon\":\"来自法语 ballon「大球」，源头是意大利语 pallone（palla「球」的加大形）。它先指球类，1783 年蒙戈尔菲耶兄弟的热气球升空后，又兼指气球——球与气球共享「充气成形」的样子。\",\"banjo\":\"来源有争议，主流说法是源于西非弦乐器的名字（如刚果语 mbanza 一类），随被贩卖到美洲的非洲人经加勒比传入美国南方英语；传播的确切路径至今未有定论。\",\"barbecue\":\"来自西班牙语 barbacoa，源头是加勒比地区泰诺语，指「架起木架烤肉的架子」（也兼指吊床架）：先指烤架，再指烤肉本身，最后指整场户外烧烤会。\",\"barn\":\"古英语 bereærn：bere「大麦」+ ærn「储藏处」——字面就是「存大麦的屋子」。本义窄到只存一种谷物，后来泛指农场的仓房与牲口棚。\",\"baseball\":\"透明复合词 base + ball。base「垒」源于拉丁语 basis「底座」（希腊语，本义「迈步、踏脚处」）。19 世纪在美国定型的这项运动，核心动作就是跑垒，名字记的正是这一点。\",\"basketball\":\"透明复合词 basket + ball。1891 年奈史密斯在美国发明这项运动时，篮子就是装桃子的竹筐（peach basket），钉在高处——运动直接以道具得名，球筐至今仍叫 basket。\",\"bench\":\"古英语 benc，日耳曼语固有词，与 bank 同源（都是「长条形的台面」一脉）：长凳是 bench，老式柜台长桌演成了 bank，河边隆起成长堤的也是 bank。\",\"birthday\":\"透明复合词 birth + day。birth 源于古诺尔斯语 byrð，与 bear「生育、承载」同族：一个人「被生下来的那一天」，就是 birthday。\",\"blanket\":\"来自古法语 blanquette「小白布」：blanc 是「白」（日耳曼语，与 blank 同源）。中世纪的毯子多是未经染色的白羊毛织物——颜色直接写进了名字。\",\"bolt\":\"古英语 bolt「短而粗的弩箭」，日耳曼语固有词。门闩形如短箭而得名；闪电是「天射之箭」（a bolt of lightning）；螺栓与一卷布，也在同一形象线上。\",\"bookcase\":\"透明复合词 book + case。这个 case「箱匣」来自拉丁语 capsa「盒子」（与 capere「容纳」一脉）；而 case「案例、病例」出自拉丁语 casus「落下、发生」，是另一个词，同形异源。\",\"bookshelf\":\"透明复合词 book + shelf。shelf 是古英语 scylfe「搁板、突出的台面」，本与山崖上平出的岩架同名——一块平出的板，就是它的全部出身。\",\"bookstore\":\"透明复合词 book + store。book 源于古英语 bōc，与 beech「山毛榉」同源——一说古人把文字刻在山毛榉木板上。store 的来历见 store 条：本义是「储备的货物」。\",\"boulevard\":\"来自法语 boulevard，源头是荷兰语 bolwerk「堡垒、棱堡」（与 bulwark 同源）。旧城的棱堡被拆除后，宽阔的堡顶改建成散步大道——巴黎那些林荫大道的前身，其实是军事工事。\",\"boxing\":\"来自动词 box「用拳击打」。这个 box 的来源没有定论，词典只注明它与 box「盒子」（源于拉丁语 buxis「黄杨木盒」）并非同源——同形异源，别被盒子带偏。\",\"bridge\":\"古英语 brycg，日耳曼语固有词，与德语 Brücke 同源，更深的来源或与「原木、横木」有关——最早的桥就是一根横搭过河的木头。它还兼指鼻梁与眼镜的鼻桥，都是「横跨」之形。\",\"broom\":\"古英语 brōm 本是「金雀花」这种灌木的名字：古人剪下金雀花枝条绑成扫帚，工具随材料得名。直到今天，broom 同时还是金雀花的名字。\",\"bucket\":\"来自盎格鲁-法语 buket「小桶」；更深来源有一点争议，多认为与古英语 būc「大腹的容器」一类的日耳曼词有关——「鼓着肚子的容器」，是它对形状的素描。\",\"bulb\":\"来自拉丁语 bulbus「球根、洋葱头」，经法语进入英语。先指植物的球根；电灯时代，玻璃泡的形状像极了球根，bulb 顺手被借去命名灯泡——洋葱的亲戚当了电灯。\",\"butcher\":\"来自古法语 bouchier「卖山羊肉的人」，源头是 buc「公山羊」（与 buck 同源）。屠夫这行当最早以羊肉为招牌，后来才泛指一切肉铺与屠夫。\",\"cafe\":\"法语 café 的直借：本义是「咖啡」，再指「卖咖啡的馆子」。café 与 coffee 同源，都来自土耳其语 kahve，上溯阿拉伯语 qahwa——咖啡从阿拉伯世界经土耳其进入欧洲，词也一路跟了过来。\",\"camping\":\"派生于 camp「营地」：camp 经法语上溯拉丁语 campus「平原、演兵场」——罗马军团在平原上扎营行军；campus 后来还留下了「校园」这个后代。\",\"candle\":\"拉丁语 candela 在古英语时代就被借入：词干 candere 是「发白光、闪耀」，与 candid「坦白的」、incandescent「白炽的」同族——蜡烛就是「发亮之物」。\",\"canoeing\":\"canoe 来自西班牙语 canoa，源头是加勒比地区阿拉瓦克语的 kanawa「独木舟」：哥伦布的船员把这个词带回欧洲，它是美洲原住民语言进入英语最早的一批词之一。\",\"canon\":\"来自希腊语 kanōn「芦苇杆、直尺」，经拉丁语 canon 进入英语：尺即标准——教会的「正典」书目、文学的「经典」，都是拿这把尺量出来的。它与 cane「藤条」同源，都是芦苇一家。\",\"carnival\":\"来自意大利语 carnevale，更深是中世纪拉丁语 carnelevare「除去肉食」：carne「肉」+ levare「拿走」。大斋期禁肉之前最后的狂欢，名字里写着「向肉告别」。\",\"carpet\":\"来自中世纪拉丁语 carpita「撕碎拼成的布」，动词 carpere 是「摘取、撕扯」——正是 carpe diem「抓住今天」里的那个 carpe。早期地毯由撕开的布条织成；它先指桌布床罩，后来才专指地毯。\",\"cartoon\":\"来自意大利语 cartone「厚纸板」，是 carta「纸」的加大形（与 card、chart 同族）。它先指画在厚纸上的草图，19 世纪讽刺杂志借指漫画，后来又转指动画片——一张纸的词，走成了画的词。\",\"cello\":\"violoncello 的缩略：意大利语 violone 是「大维奥拉」，加上指小后缀 -cello，反而成了「小小的大提琴」这个绕口的名字，英语干脆只留下 cello。\",\"chain\":\"来自拉丁语 catēna「锁链」，经古法语 chaine 进入英语；catēna 更深的来源不明。chain 兼指山脉与连锁店，靠的都是「环环相扣」这同一个形象。\",\"chess\":\"来自古法语 esches（eschec 的复数形式），源头是波斯语 shāh「国王」——整盘棋的目标就是困住对方的王。将死 checkmate 出自波斯语 shāh māt，意为「王已无路可走」（一译「王死了」）。\",\"circumference\":\"来自拉丁语 circumferre「环绕着带行」：circum-「环绕」+ ferre「带、运」（与 transfer 里的 fer 同族）。绕着圆走完一圈量出的那条线，就是周长；希腊版的同义词是 perimeter。\",\"circus\":\"拉丁语 circus「圆圈、环形竞技场」直借，上溯希腊语 kirkos「圆环」，与 circle 同源。罗马的竞技场本是战车绕圈比赛之地，现代马戏的圆形表演场沿用了这个名字。\",\"citation\":\"来自拉丁语 citare「召唤、传唤」，词根是 cire「使移动」：法庭传人到堂，学界则「传唤」前人的文字到纸面作证——引文与传票同源。excite 里的 cit 也是这一根，义为「唤起」。\",\"city\":\"来自拉丁语 civitas「公民身份、城邦共同体」，经古法语 cité 进入英语，词干 civis 是「公民」。city 的核心从来不是高楼，而是公民组成的共同体；civil、citizen、civilization 全是这一族。\",\"clarinet\":\"来自法语 clarinette，源头是意大利语 clarino「高音小号」的指小形；clarino 再上溯拉丁语 clarus「明亮、清澈」——单簧管音色明亮如小号，故得此名。clarify、clear 与 clarus 同族。\",\"climbing\":\"派生于 climb：古英语 climban，日耳曼语固有词，可能与 cling「攀附、黏着」同源。词尾那个不发音的 b，是古英语老拼写留下的残迹。\",\"clown\":\"来源不明：16 世纪时它先指「乡巴佬、粗鲁的人」，后来才专指舞台丑角；有人猜它与斯堪的纳维亚语里「笨拙者」一类的词有关，但没有定论。\",\"codex\":\"拉丁语 codex（旧作 caudex）本义是「树干、木块」：把木板涂蜡、刻字、装订成册，就是 codex——相对于卷轴的革命性书形。code「法典、代码」正是它的后代。\",\"coherence\":\"来自拉丁语 cohaerere「粘在一起」：com-「一起」+ haerere「粘着」（与 adhesive 同根）。论点彼此粘得住，就是连贯；物理学里的「相干」也是这同一个词。\",\"collaboration\":\"来自拉丁语 con-「一起」+ laborare「劳作」（labor「劳动」）：本义就是一起干活。它另有一层阴影义——二战时「与占领者合作」的用法，让 collaboration 带上了「通敌」的贬义面。\",\"collage\":\"法语 collage「粘贴」，动词 coller「上胶」，源头是希腊语 kolla「胶水」。1912 年前后，毕加索与布拉克把报纸、布片粘上画布，拼贴自此成为现代艺术的一派。\",\"commentary\":\"来自拉丁语 commentarius「备忘录、注疏」，动词 comminisci 是「想出、构思」（含 mens「心智」一脉）。古典时代给经典作注的文体，今天既指学术评论，也指体育解说。\",\"compromise\":\"来自拉丁语 compromissum「共同的承诺」：争执双方事先约定，共同接受仲裁者的裁决——妥协的本义是「互相许诺让步」。它后来「损害、危及」的动词义（compromise 安全），是转义。\",\"concession\":\"来自拉丁语 concessio「让予」，动词 concedere 是「退让、允许」：con- + cedere「走开」（与 cede、proceed 里的 ced 同族）。让出一步就是让步；「特许经营权」义也出自官方的「让予」。\",\"concord\":\"来自拉丁语 concordia「同心」：con-「一起」+ cor / cord-「心」（与 courage 同根）。英法合造的协和飞机 Concorde 正是借这个「同心」命名；它的反面是 discord「不和」。\",\"configuration\":\"来自拉丁语 configurare「塑造成形」：con- + figura「图形」（与 figure 同族）。各部分排布成的整体形状就是 configuration；计算机的「配置」义是 20 世纪长出的新面。\",\"conjecture\":\"来自拉丁语 conicere「抛到一起、凭迹推断」：con- + iacere「抛」（与 project 里的 ject 同族）。把零散线索抛到一起凑出判断——conjecture 自带「尚未证实」的分寸。\",\"consensus\":\"拉丁语 consensus「一致同意」，动词 consentire 是「同感」：con- + sentire「感觉」（与 sense、sentiment 同族）。大家的感觉一致，就是共识。\",\"conservation\":\"来自拉丁语 conservare「完整地保存」：con-（加强）+ servare「保存、看守」（与 reserve、observe 里的 serv 同族）。文物保存与生态保护，在英语里共用这一个词。\",\"consistency\":\"来自拉丁语 consistere「站定、由……构成」：con- + sistere「站立」（与 consist、exist 的 st / sist 一脉）。站得住、不自相矛盾，就是一致性；讲稠度时，它指的也是「站立」的程度。\",\"constituent\":\"来自拉丁语 constituere「设立、构成」：con- + statuere「竖立」（与 statute、institute 里的 stat 同族）。构成整体的每一部分都是 constituent；政治里的「选民」，是「构成议会的人」。\",\"continuum\":\"拉丁语 continuus「连续的」的中性形式直接入词：con- + tenere「握住、延伸」（与 contain、tenet 的 ten 同族）。中间没有任何断裂的连续统一体就是 continuum，时空即其最著名的例子。\",\"contradiction\":\"来自拉丁语 contradicere「反着说」：contra-「相反」+ dicere「说」（与 diction、dictate 的 dic 同族）。两句话互相对着说，就是矛盾；法律上的「反驳」义至今仍在用。\",\"conversion\":\"来自拉丁语 convertere「完全转向」：con- + vertere「转」（与 version、versus 的 vert / vers 同族）。改宗、换算单位、转换格式，在英语里都是同一次「转向」。\",\"cord\":\"来自拉丁语 chorda「弦、绳」，源头是希腊语 chordē「肠线」——最早的琴弦就是羊肠拧成的。cord 与 chord「和弦」同源异写；脐带 umbilical cord、脊髓 spinal cord 取的都是「索」的义。\",\"corner\":\"来自拉丁语 cornu「兽角、角」一脉，经古法语 cornier 进入英语：角是尖出来的一端，墙角、街角、眼角都是「角」。unicorn「独角兽」与它同族；注意 corn「谷物」是另一条线。\",\"corollary\":\"来自拉丁语 corollarium「小花环、额外的小礼物」，corolla 是「小花环」：古罗马人结账时常多送这样一份添头。由已证的定理顺手多送出的结论，就是 corollary 推论。\",\"couch\":\"来自古法语 couche「床榻」，动词 coucher「躺下」源于拉丁语 collocare「安放」。它本是「躺卧之处」，长沙发取其可以躺——couch 的核心动作一直是「躺」。\",\"county\":\"来自盎格鲁-法语 counté「伯爵的领地」，源头是拉丁语 comes「随从、伯爵」。诺曼征服后，伯爵的辖地成了英国的「郡」，再传到美国成为州之下的县。注意 count「伯爵」与 count「计数」是两条线，后者源于 computare「计算」。\",\"crosswalk\":\"美国英语的透明复合词 cross + walk：横穿马路的人行通道。它的白色条纹形似斑马纹，所以英国人干脆叫它 zebra crossing。\",\"cruise\":\"来自荷兰语 kruisen「横穿、往返航行」，源头是 kruis「十字」（拉丁语 crux）。船在海上交叉往返巡航——cruise 与 crux「关键点」在词源深处同源。\",\"crux\":\"拉丁语 crux「十字架、刑架」直接入词：各方的线索在一点上交汇，如立在路口的十字——the crux of the matter 就是「事情的要害」。南十字座 Crux 与 crucial 都是同族。\",\"culmination\":\"来自中世纪拉丁语 culminare「登顶」，源头 culmen「山顶、屋脊」，与 column「柱子」同出一根——都是「高耸之物」。星辰升到子午线最高点叫 culminate，事情的高潮义由此而来。\",\"cupboard\":\"透明复合词 cup + board：本义就是「放杯盘的板子」。中世纪它是敞口的陈列架，后来加了柜门才成碗柜；读音弱化成近似「cubberd」，是英语老名物词的常见命运。\",\"custard\":\"本是「带酥皮的馅饼」：源头是古法语 crouste「脆皮」（与 crust 同源），中古英语 crustade 指烤在酥皮里的馅饼；后来酥皮消失了，只剩下里面蛋奶凝成的芯，名字却留了下来。\",\"cycling\":\"派生于 cycle：cycle 来自希腊语 kyklos「圆圈、轮子」（经拉丁语 cyclus）。它先指周期，后指「带轮的车」——车轮的圆把两个意思串在了一起，自行车运动因此得名。\",\"dancing\":\"派生于 dance：dance 经古法语 danser 进入英语，更深的来源没有定论（一说与日耳曼语「伸展、拖曳」一类的词有关）。自进入英语起，它就与「随乐而动」绑定。\",\"delineation\":\"来自拉丁语 delineare「画出轮廓」：de- + linea「线」（与 line 同族，linea 本义「亚麻线」）。用线条勾出形状，就是描绘；划定边界用的也是这个词。\",\"dependence\":\"来自拉丁语 dependere「垂下、悬挂着」：de-「向下」+ pendere「悬挂」（与 pendant、pending 的 pend 同族）。挂在别人身上存活，就是依赖；independence 就是「不挂靠」。\",\"deployment\":\"来自法语 déployer「展开」，源头是拉丁语 displicare「把褶皱展开」：dis-「分开」+ plicare「折叠」（与 display 同源同构）。把收拢的兵力展开摆开，就是部署；软件的「上线部署」是新义。\",\"deprivation\":\"来自中世纪拉丁语 deprivare「完全夺走」：de- + privare「使失去」，privare 又出自 privus「属于个人的」——正是 private 的祖先。本属自己的被拿走，就是剥夺；sleep deprivation「睡眠剥夺」是心理学常客。\",\"derivative\":\"来自拉丁语 derivare「引水改道」：de- + rivus「小溪」（与 river、rival 的 riv 同族）。词义的引申物、金融的衍生品、微积分的导数，都是从主流上引出的一条支流。\",\"description\":\"来自拉丁语 describere「照着写下、描摹」：de- + scribere「写」（与 script、scribe 同族）。本义是「照样写下来」——所以描写与登记（人物的体貌 description）在英语里共用一词。\",\"dessert\":\"来自法语 dessert，动词 desservir 是「撤席、收桌」（des- 去除 + servir 上菜）：正餐的餐具撤下之后才端上的那道甜食，就叫 dessert。注意它与 desert「沙漠」只差一个 s，词源毫无关系。\",\"destruction\":\"来自拉丁语 destruere「拆毁」：de-（向下、解除）+ struere「堆建」——它与 structure 正是正反一对：一个把东西建起来，一个把它拆掉。\",\"detection\":\"来自拉丁语 detegere「揭开盖子」：de-「去除」+ tegere「覆盖」（与 protect 的 teg 同族）。掀开遮蔽、让藏着的东西露出来，就是侦测；detective 是「揭盖的人」。\",\"deterrent\":\"来自拉丁语 deterrere「吓退」：de-「离开」+ terrere「惊吓」（与 terror、terrible 同族）。核威慑 deterrence 的逻辑就写在词里——用恐惧让对方离开原先的打算。\",\"deviation\":\"来自中世纪拉丁语 deviare「离开大路」：de- + via「路」（与 obvious、previous 的 via 同族）。离开正道是偏差；统计学里与平均值的距离，也沿用此名。\",\"diameter\":\"来自希腊语 diametros「横穿量度」：dia-「穿过」+ metron「尺度」（与 meter 同属「量」的老根）。直径的字面意思朴素得很——「横穿圆心量过去」。\",\"dice\":\"dice 是 die 的复数：die 来自古法语 dé，源头是拉丁语 datum「被给出的东西」——掷骰掷出的，就是「命运给出的」点数。现代口语里 dice 常兼作单数。\",\"dichotomy\":\"来自希腊语 dichotomia「切成两半」：dicha「成两半」+ tomia「切割」（与 atom「不可再切者」、anatomy 的 tom 同族）。一分为二的分类法，由此得名。\",\"dictation\":\"来自拉丁语 dictare「口授、发令」，是 dicere「说」的频繁体：老师念、学生记，是 dictation；发号施令的 dictator「独裁者」与它同出一词，分道两途。\",\"diction\":\"来自拉丁语 dictio「言说、措辞」，同出 dicere「说」：dictionary 是「词语之书」，diction 是运用词语的功夫——说与词，本是一家。\",\"difference\":\"来自拉丁语 differre「被带往不同方向、相异」：dis-「分开」+ ferre「携带」（与 differ、defer 里的 fer 同根）。东西被分开带走，差异由此而生；数学的「差」只是它的一面。\",\"dignity\":\"来自拉丁语 dignitas「价值、尊严」，形容词 dignus 是「值得的、相称的」：与 deign、disdain 是亲戚。尊严的字面底账，是「一个人值得的份量」。\",\"diminution\":\"来自拉丁语 deminutio「减损」，动词 deminuere 是「切小」：de- + minuere「使变小」，出自 minus「较少」一脉（与 minute、minor 同族）。音乐里把主题的时值缩短，也叫 diminution。\",\"dioxide\":\"现代科技术语：di-（希腊语「二」）+ oxide「氧化物」。oxide 的 ox- 出自希腊语 oxys「尖锐的、酸的」——拉瓦锡误以为氧是「成酸之素」，oxygen 由此得名；carbon dioxide 是这个词最著名的搭配。\",\"direction\":\"来自拉丁语 directio「对准、指引」，动词 dirigere 是「使变直、引导」：dis- + regere「拉直、统治」（与 regulate、ruler 的 reg 同族）。方向，就是被拉直后指着的那条线。\",\"disability\":\"dis-（去除）+ ability「能力」：ability 源于拉丁语 habilis「顺手的、能干的」（与 able 同源）。「能力被去除的状态」是它的字面义；现代用法更强调障碍来自环境而非个人。\",\"disagreement\":\"dis-（分开）+ agreement「同意」：agree 经古法语 agréer 上溯拉丁语 gratus「令人愉快的」（与 grace、grateful 同族）。心意合不拢、彼此分开，就是分歧。\",\"discernment\":\"来自拉丁语 discernere「筛分开、辨别」：dis- + cernere「筛、分辨」（与 concern、certain 里的 cern / cert 一脉）。把混在一起的东西筛分清楚——眼力，就是筛子的功夫。\",\"discourse\":\"来自拉丁语 discursus「来回奔走、漫谈」，动词 discurrere 是 dis-「四散」+ currere「跑」——正是 current 的那个 curr。话语来回奔走、成段成篇，就是论述；学术界的 discourse 分析由此而来。\",\"discrepancy\":\"来自拉丁语 discrepantia「不一致」，动词 discrepare 是「发出不和谐的声响」：dis- + crepare「咔哒作响」。本义是声音打架——两组数据对不上，就像数字在发出杂音。\",\"discretion\":\"来自拉丁语 discretio「分开、分辨」，与 discernere 同出一脉（见 discernment）：先有明辨，才有「自行裁量」与「谨言慎行」。discreet「谨慎的」与 discrete「分离的」本是同一个词的两种拼写。\",\"discus\":\"来自希腊语 diskos「圆盘」，经拉丁语进入英语。它与 disk、dish、desk 同出一源：同一个 diskos，在不同语言里分化成了圆盘、盘子与书桌；古希腊的掷铁饼与《掷铁饼者》雕像都源于它。\",\"discussion\":\"来自拉丁语 discussio「摇散、细查」，动词 discutere 是「打碎、摇散」：dis- + quatere「摇击」（与 percussion 的 cuss 同族）。把问题打碎了细看，就是讨论——本义颇有点暴力。\",\"disease\":\"来自古法语 desaise「不适」：des-「去除」+ aise「安适」（与 ease 同词）。「安适被拿走」就是疾病；17 世纪以后它专指具体的病，笼统的「不适」义退场。\",\"disgrace\":\"来自意大利语 disgrazia / 法语 disgrâce：dis- + grazia / grâce「恩宠、优雅」（拉丁语 gratia，与 grace 同词）。从恩宠里跌出来，就是耻辱——在旧欧洲，失宠与丢脸原是一回事。\",\"disguise\":\"来自古法语 desguiser「改换装扮」：des-「改变」+ guise「外貌、方式」（日耳曼语一脉，与 wise 的古义「方式」同族）。换掉本来的样子，就是伪装。\",\"displacement\":\"dis- + placement（place 源于拉丁语 platea「广场」一脉）：物理义「排开的水量」源于阿基米德的浴缸——物体排开多少水，浮力与位移就此结缘；心理学里的「移情」义是后起的。\",\"disposal\":\"派生于 dispose：经古法语 disposer 上溯拉丁语 disponere「分开放置」（dis- + ponere「放」，与 position 的 pon 同族）。把东西各就各位地处理掉，就是 disposal；「任凭处置」at your disposal 与它同源。\",\"disposition\":\"与 disposal 同出拉丁语 disponere「摆放」：东西的摆法成格局，人的「摆放方式」就是性情；军队的部署、财产的处置，也都出自这一个「摆」字。\",\"disruption\":\"来自拉丁语 disrumpere「扯断、冲断」：dis- + rumpere「断裂」（与 interrupt、rupture 的 rupt 同族）。把连续性生生扯断，就是 disruption；「颠覆式创新」是它现代的头衔。\",\"dissemination\":\"来自拉丁语 disseminare「到处播种」：dis-「四散」+ seminare「播种」，词干 semen 是「种子」——seminar「研讨班」本义正是「苗圃」。把思想当种子撒出去，就是传播。\",\"dissent\":\"来自拉丁语 dissentire「感觉不同」：dis-「分开」+ sentire「感觉」（与 consensus 的 sens 恰成正反）。感觉不一致并且说出来，就是异议；判决书里的 dissenting opinion 是少数派的正式席位。\",\"dissipation\":\"来自拉丁语 dissipare「驱散、抛散」：dis- + 一个表「抛掷」的旧动词（细节稍有争议）。能量耗散、雾气消散、挥霍家产——物理与道德，共用这一个「散」字。\",\"diving\":\"派生于 dive：古英语 dȳfan「浸入、潜下」，与 deep、dip 同族，都出自「深、沉」的老根。跳水与潜水共用此词，核心都是「扎进深处」。\",\"dock\":\"来源有一点争议，多认为来自中古荷兰语 docke「水槽、船埠旁蓄水的洼地」：指挖出来蓄水以便修船、装卸的人工水域，后来兼指码头岸线；dry dock「干船坞」是它的本行。\",\"documentary\":\"派生于 document：拉丁语 documentum「例证、教训」，动词 docere 是「教」。纪录片这一义由电影人格里尔逊在 1920 年代确立（借自法语 documentaire）——以真实材料教人，正是它的本行。\",\"doll\":\"由人名转成：Doll 本是 Dorothy 的昵称，16 世纪起被用来称呼玩偶——如同给布娃娃起个小名。更早的英语玩偶叫 poppet，是 puppet 的亲戚。\",\"domino\":\"来自法语 domino，本指一种带兜帽的化装长袍与面具，其更深源头或与拉丁语 dominus「主人」有关（神父的冬袍）。骨牌黑白分明、形似这身装束，因而得名；「多米诺效应」是后起的比喻。\",\"downtown\":\"美国英语的透明复合词：down + town。19 世纪纽约人把曼哈顿南端（在地图与地势上都更靠下）叫 down-town，与 uptown 相对；后来泛指任何城市的中心商业区。\",\"dresser\":\"派生于 dress：dress 经古法语 dresser「摆正、布置」而来，深层与拉丁语 directus「直的」一脉（与 direct 同族）。dresser 先是厨房里摆置盘碟的架台，美式英语里又转指梳妆台与五斗柜。\",\"drill\":\"来自荷兰语 drillen「旋转、钻孔」，带拟声色彩的日耳曼词。军事「操练」义的 drill 多认为出自同一个词：操练如钻孔，一遍遍重复成形。\",\"drum\":\"来历没有定论：多认为它与荷兰语、低地德语的 trommel「鼓」同出一脉，且带拟声色彩——模仿的正是鼓声。在 drum 之前，英语里多用 tabour 称鼓。\",\"dustpan\":\"透明复合词 dust + pan。pan 是古英语 panne「平底锅」，多认为与拉丁语 patina「浅盘」有关：接灰的浅盘子，与下厨的平底锅本是一家。\",\"inn\":\"古英语 inn 本义是「房子的内部、居所」，与 in 同源：家里能留宿外人，就是客栈。伦敦的 Inns of Court「律师学院」，名字也源于当年供学徒寄宿的院落。\",\"instrument\":\"来自拉丁语 instrumentum「工具、装备」，动词 instruere 是「建造、装备」（in- + struere「堆建」，与 structure 同族）。乐器即「发声的工具」；科学仪器与法律文书同用此词，都是「工具」的义面。\",\"intersection\":\"来自拉丁语 intersecare「从中切开」：inter-「在中间」+ secare「切」（与 section 同根）。两条道路互相切过的地方就是十字路口；数学里的「交集」也是同一个词。\",\"jam\":\"词源存疑：较流行的说法是源自动词 jam「用力挤压」——果子被压烂、熬稠再装罐；但 jam 这个动词本身来历也不明，这条只能算合理推测。果酱义到 18 世纪才出现。\",\"javelin\":\"来自古法语 javeline「小投矛」；更深一层多认为与凯尔特语有关（细节有争议）。标枪本是古代打猎与战争的投矛，田径里的 javelin 是它留下的竞技形态。\",\"jelly\":\"来自拉丁语 gelare「冻结、凝结」，经古法语 gelée 进入英语，与 gel、congeal、gelatin 同族，核心画面都是「冻住」。果汁加糖熬后冷却成冻就是 jelly；jellyfish「水母」也是取它胶冻般的质感。\",\"jogging\":\"派生于 jog：jog 的来源不明，16 世纪时义为「轻推、颠动」，或许与方言里的 shog「摇动」有关，无定论。「慢跑」这个健身义是 20 世纪才兴起的新用法。\",\"joke\":\"来自拉丁语 iocus「玩笑、戏言」。它的同族还有 jocular「诙谐的」与 juggle（见 juggle 条）；joke 从进入英语起就守着「逗人发笑的话」这一个核心。\",\"judo\":\"日语「柔道」直借：柔（jū）是「柔顺」，道（dō）是「道路、方法」。嘉纳治五郎 1882 年创立，取「以柔克刚之道」之义；它的源头是日本的柔术（jūjutsu）。\",\"juggle\":\"来自古法语 jogler「说笑逗乐、耍把戏」，源头是拉丁语 joculari「开玩笑」（iocus「玩笑」，与 joke 同源）：杂耍艺人本是逗笑的人，抛接杂耍只是他的一门绝活。\",\"jungle\":\"来自印地语 jangal「荒地、丛林」，源头是梵语 jāṅgala「干旱不毛之地」。有趣的反转：这个词本指干荒地，被英语借来之后却专指热带密林——词义在旅行途中变了样。\",\"karate\":\"日语「空手」直借：kara「空」+ te「手」。它源于冲绳，本与「唐手」同音同源，20 世纪传入日本本土后改写汉字为「空手」，强调徒手无器械。\",\"kayaking\":\"kayak 来自因纽特语 qajaq「猎人的小船」：兽皮蒙住木架，舱口仅容一人坐入，双叶桨左右划水。18 世纪经探险者进入欧洲语言；kayak 还是个回文词，正读反读都一样。\",\"ketchup\":\"词源有争议，主流一说来自闽南语「茄汁」kê-tsiap（腌鱼的卤汁），经马来语 kecap 传入英语。最初的 ketchup 是蘑菇、核桃做的发酵酱，并无番茄；19 世纪美国人改用番茄，才有了今天的红色版本。\",\"kite\":\"古英语 cȳta 本是一种猛禽「鸢」的名字，日耳曼语固有词。纸做的玩具在天上盘旋如鸢，遂借鸟名——与汉语「纸鸢」的命名思路不谋而合。\",\"lane\":\"古英语 lanu「两边有篱笆或房子的窄路」，日耳曼语固有词。乡间小巷、泳池的泳道、公路的车道都是它：一旦划出一条窄带，英语就叫它 lane。\",\"lantern\":\"来自拉丁语 lanterna（源于希腊语 lamptēr「火炬」，与 lamp 同根），经古法语进入英语。灯笼是「带罩的灯」：牛角、薄纸或玻璃护住火苗，才能提着走夜路。\",\"lighthouse\":\"透明复合词 light + house：塔顶燃火或点灯为夜航的船指路。古代世界七大奇迹之一的亚历山大法罗斯灯塔，其名 pharos 后来成了多国语言里「灯塔」的词（如法语 phare）。\",\"loveseat\":\"19 世纪美国商家给双人沙发起的卖名：早期的宽双人椅本为容纳女性的蓬裙而设计，坐得下两人后，商家顺势以 love 命名——营销先于词源的一个例子。\",\"magic\":\"来自希腊语 magikē（tekhnē）「魔法的（技艺）」，源头是波斯祭司 Magi（magos）：东方贤士的秘术在希腊人眼中就是魔法。magus 的复数，正是圣诞故事里来朝拜的「三博士」。\",\"mall\":\"先是一项游戏：pall-mall 是 17 世纪流行的槌球戏（源于意大利语 palla「球」+ maglio「槌」），伦敦的球场 Pall Mall 后来成了时尚大道，mall 遂转指林荫步道；20 世纪美国再用它命名封闭式购物中心。\",\"mandolin\":\"来自意大利语 mandolino，是 mandola 的指小形；mandola 再上溯至 pandura「琵琶类乐器」（希腊语 pandoura）。它与 almond「杏仁」只是外形联想，词源上并无关联。\",\"marionette\":\"法语 marionnette，是 Marion（Marie 的指小形）的叠指小：中世纪宗教剧里的小圣母木偶被叫作「小玛丽」，提线木偶就此得名。\",\"mat\":\"古英语 meatte，源头是拉丁语 matta「芦苇席」（可能更早经腓尼基语传播）。人类最早的「垫子」就是苇席，mat 的词义一路从苇席铺到门垫与瑜伽垫。\",\"mattress\":\"来自阿拉伯语 maṭraḥ「垫子、抛掷之地」（动词 ṭaraḥa「投掷」），经意大利语 materasso、古法语 materas 进入英语：把垫子往地上一扔就是床——中世纪欧洲人睡的正是这种地垫。\",\"mayonnaise\":\"法语词，来源众说纷纭：一说得名于西班牙梅诺卡岛的马翁港（Mahón），1756 年法军取胜后当地厨师创制了这种酱；一说源于古法语 moyeu「蛋黄」。至今无定论，词典多标注来源不确定。\",\"merry-go-round\":\"透明复合词：merry（古英语 myrge「愉快的」）+ go-round「转圈」。旋转木马 19 世纪在美国游乐场定型，名字直白地写着「快乐地转圈圈」。\",\"metropolis\":\"希腊语 mētropolis：mētēr「母亲」+ polis「城邦」。希腊殖民时代，派出殖民船的母邦叫「母城」，新殖民地是女儿城；后来转指一国或一域的首要大都市。\",\"mop\":\"来源不明：15 世纪写作 mappe，或与拉丁语 mappa「布」有关（napkin 的远亲），但没有定论。拖把的头是布条，这个词的出身却说不清。\",\"motel\":\"20 世纪美国人造的混成词：motor + hotel。1925 年加州的 Milestone Mo-Tel 号称第一家汽车旅馆；汽车时代的旅馆，车可以直接停在房门口。\",\"movie\":\"美国英语的造词：moving picture「活动的画面」缩略为 movie，再添上亲昵后缀 -ie，20 世纪初成词。英国人同期更爱说 film 或 cinema（源于希腊语 kinēma「运动」）。\",\"mustard\":\"名字出自拉丁语 mustum ardens——「灼热的葡萄汁」：mustum 是新榨的未发酵葡萄汁，古罗马人用它调和芥籽粉做酱，辛辣灼口；酱以原料得名，经古法语 moustarde 进入英语。\",\"nail\":\"古英语 nægl 一身二任：「指甲」与「钉子」，日耳曼语固有词。钉子就是「铁做的指甲」——英语干脆让它们共用一个词，至今 fingernail 与钉子仍是同源同词。\",\"neighborhood\":\"透明复合词：neighbor + -hood（状态、范围后缀）。neighbor 是古英语 nēahgebūr——nēah「近」+ gebūr「居民」，字面就是「住在近处的人」；他们的关系所及的那片地方，就是 neighborhood。\",\"nightstand\":\"美国英语的透明复合词 night + stand「架台」：立在床边、放水杯与书的小柜子。stand 的本义是「站立之处」，家具名里它专指各种立架。\",\"nursery\":\"来自 nurse 一脉：古法语 norrice「乳母」，源头是拉丁语 nutrire「喂养、哺育」。先是「哺育婴儿的房间」，再是托儿所；后来又引申出「苗圃」——幼苗和婴儿一样，都要人精心喂养照料。\",\"oboe\":\"来自法语 hautbois：haut「高」+ bois「木头」——「高音的木管」。意大利语按法语发音转写为 oboe，英语又从意大利语借来；名字本身就是一份说明书。\",\"office\":\"来自拉丁语 officium「职责、服务」，多认为由 opus「工作」+ facere「做」合成缩略而来，经古法语进入英语。先指职务与公务，再指办职务的房间；official、officer 都是同族。\",\"orchard\":\"古英语 ortgeard：前段多认为源于拉丁语 hortus「园子」，后段 geard 是「围地」（与 garden、yard 同源）。围起来种果树的园子就是 orchard，苹果园、梨园都属此列。\",\"ottoman\":\"以奥斯曼帝国得名：18 世纪欧洲宫廷流行「土耳其风」，这种无背无扶手的软长凳从奥斯曼宫廷的坐具借形借名——家具名里藏着一段欧洲的东方热。\",\"outskirts\":\"透明复合词：out + skirts（复数）。skirt 本义是「衣裙的下摆、边缘」（古诺尔斯语来源），城邑的「裙边」就是市郊；这个词习惯上恒用复数形式。\",\"pasture\":\"来自拉丁语 pastura「喂养、放牧之地」，动词 pascere 是「喂食、放牧」。它与 pastor 同源——pastor 本义是「放羊的人」，后来才专指牧师；羊群在哪里吃草，哪里就是 pasture。\",\"piano\":\"意大利语 pianoforte 的缩略：piano「轻柔地」+ forte「强烈地」。1700 年前后克里斯托福里发明此琴，卖点正是「能弱能强」，一改羽管键琴力度单一的毛病——名字就是广告语。\",\"picnic\":\"来自法语 pique-nique：pique「啄、挑拣」+ nique「小玩意儿」式的叠词，本指各人自带一份食物凑成的聚餐；18 世纪进入英语后，场景移向了户外。\",\"pier\":\"细节存疑：中古英语 pere 源于中世纪拉丁语 pera，原义不甚明了，可能指「石堆、石垛」。它本是伸入水中防波、系船的石构堤岸，后来才有木栈桥与观光码头的样子。\",\"pilates\":\"以人名命名：德国人约瑟夫·普拉提（Joseph Pilates）在 20 世纪创立这套训练法，他本人称之为 Contrology「控制学」；他身后，人们以他的姓氏称呼这门运动。\",\"pillow\":\"来自拉丁语 pulvīnus「坐垫、靠垫」，经古英语 pyle 进入。pulvīnus 在罗马还指神像前的软垫；英语 pillow 后来专指枕头，与 pile「堆」并无关系。\",\"playground\":\"透明复合词 play + ground：供游戏的场地。ground 是古英语 grund「地面、底部」；play 则是古英语 plega「游戏、运动」，都是日耳曼的老词。\",\"plaza\":\"西班牙语 plaza「广场」，与 place 同源，都出自拉丁语 platea「宽街、广场」（希腊语 plateia）。西班牙殖民城市以中央广场为心脏，这个词随之进入英语，美式英语里还兼指购物中心。\",\"pliers\":\"来自法语 plier「弯折」（拉丁语 plicare「折叠」，与 apply、explicit 里的 plic 同族）：钳子就是「能夹住并弯折东西的工具」，plier 直译是「弯折者」。\",\"plug\":\"来自荷兰语 plugge「塞子、木栓」，与德语 Pflock「木桩」同族：本是堵洞的木栓。电插头是「插入的栓」的引申；plug 的「卖力推销」义是后起的俚语。\",\"poker\":\"来源有争议：多认为来自法语 poque（一种纸牌戏），再上溯德语 Pochspiel「敲桌虚张声势的游戏」；也有源于其他牌戏的说法，至今没有定论。\",\"pool\":\"古英语 pōl「水塘、池子」，日耳曼语固有词：天然水塘引申为人工泳池。注意 pool 还有「共同赌注、联合资源」一义，那来自法语 poule 的另一条线，与水塘这个 pool 同形异源，不要混淆。\",\"province\":\"来自拉丁语 provincia：本指罗马授予执政官的「职权范围、辖区」，多是意大利以外征服来的行省；更深一层的来源有争议（一说与 vincere「征服」有关），但「罗马辖区」这层是定论。今天它是加拿大、中国等国的一级行政区。\",\"pudding\":\"多认为来自古法语 boudin「香肠」（源头是拉丁语 botellus「小肠、香肠」）：最早的 pudding 是灌进肠衣蒸熟的咸食，黑布丁与 haggis 都是这一脉；后来才变成甜点的统称。\",\"puppet\":\"来自法语 poupette「小娃娃」，源头是拉丁语 pupa「女孩、玩偶」。pupa 后来还留下了生物学义「蛹」——蛹像裹起来的小婴偶，木偶与蛹靠「小人形」相认。\",\"puzzle\":\"来源不明：16 世纪末它忽然出现，动词义「使困惑」先于名词；有人猜它与 pose「摆出难题」一脉有关，但没有定论。拼图玩具专名 jigsaw puzzle 是 20 世纪的事。\",\"quilt\":\"来自拉丁语 culcita「塞着填充物的垫子、床褥」，经古法语 cuilte 进入英语：被芯塞棉再绗缝成格，就是 quilt；它既是被子，也是「绗缝」这个动作本身。\",\"rafting\":\"派生于 raft「木筏」：raft 来自古诺尔斯语 raptr「原木、椽木」。几根原木绑在一起就是筏；乘筏顺激流而下，就是 rafting 漂流。\",\"rainforest\":\"透明复合词 rain + forest，20 世纪才成词，一说是对德语 Regenwald 的译借。forest 源于中世纪拉丁语 forestis，多认为与拉丁语 foris「门外」有关——指王宫围地之外、专供狩猎的林地。\",\"rake\":\"古英语 raca「耙」，日耳曼语固有词，与德语 Rechen 同源。注意 rake「浪荡子」是另一条线（rakehell 的缩略），与农具同形异源。\",\"ranch\":\"来自美洲西班牙语 rancho「小农舍、牧场工棚」，更深的源头与「列队扎营」一脉的日耳曼词有关。19 世纪随美国西部的牧牛业进入英语，成为大牧场的通名。\",\"recycling\":\"现代派生词 re-「再」+ cycle（希腊语 kyklos「圆圈」）：材料转上一圈再回到用途里。recycling 作为日常词普及于 1970 年代的环保运动，名字本身就是一张循环图。\",\"relay\":\"来自古法语 relais「接替的人马」，动词一脉是 re- + laissier「留下」（源头拉丁语 laxare「放松」）：驿站换马、猎场换犬的「中继」就是 relais；接力赛与电子继电器都借了这个「接力棒」的画面。\",\"resort\":\"来自动词 resort「常去、诉诸于」，源头经古法语 resortir（re-「再」+ sortir「出去」）。本义是「人们常去的地方」，后来专指度假胜地；「最后手段」last resort 是同一个词的另一面。\",\"restaurant\":\"来自法语 restaurant，是 restaurer「使恢复」的现在分词，源头为拉丁语 restaurare（与 restore 同源）。18 世纪巴黎先出现卖「滋补汤」的小店，汤就叫 restaurant——「恢复元气的汤」；卖汤的店随后跟着叫了这个名字，现代餐馆由此诞生。\",\"riddle\":\"古英语 rædels「谜、猜测」，源于 rædan「解读、劝告」，与 read 同源——谜语就是「要人解读的话」。注意 riddle 还有「粗筛子」一义，那是另一条线，同形异源。\",\"rocking\":\"派生于 rock「摇晃」：古英语 roccian「摇动」，日耳曼语固有词，摇篮的 rock 也是它。注意 rock「岩石」是另一个词（古英语 rocc，深层或与拉丁语 rocca 有关），两者同形异源。\",\"rope\":\"古英语 rāp「绳索」，日耳曼语固有词，与德语 Reif「圈、箍」同族。英语按粗细给绳索分了家：粗索是 rope，细线是 string。\",\"rowing\":\"派生于 row「划桨」：古英语 rōwan，日耳曼语固有词，与 rudder「舵」同出一脉——都是古人在船上使力的部件与动作。\",\"rug\":\"来自斯堪的纳维亚语一脉（挪威语方言 rugga、瑞典语 rugg 都是「粗毛、乱毛织物」的意思）：本指粗羊毛的厚布，铺到地上就成了小地毯——「毛茸茸」是它出身的关键词。\",\"rugby\":\"以英格兰的 Rugby 学校得名。相传 1823 年该校学生埃利斯在足球比赛中抱起球奔跑——这段故事多被后世视为传说；但橄榄球运动确实是在这所学校成形并定下规则的。\",\"running\":\"派生于 run：古英语 rinnan / irnan，日耳曼语固有词。它的过去式 ran 是元音交替留下的老形态；run 既是日常的「跑」，也是河流、机器「运转」的那个 run。\",\"sailing\":\"派生于 sail「帆」：古英语 segl，日耳曼语固有词。驾驶帆船、乘船航行都叫 sailing；船的「出航时刻」（sailing time）也出自它。\",\"saw\":\"古英语 saga「锯」，日耳曼语固有词，在印欧层面与拉丁语 secare「切」同源——section 的 sect- 就是它的拉丁后代。注意 saw 还是 see 的过去式，两者同形异源，不要混淆。\",\"screw\":\"来自古法语 escroe「螺母、内螺纹」，更深的来源没有定论：流传的「母猪尾巴盘绕」之说（拉丁语 scrōfa「母猪」）缺乏实证，多被词典标注为存疑。\",\"seafood\":\"透明复合词：sea「海」（古英语 sæ）+ food「食物」（古英语 foda）。19 世纪在美国英语里成词，泛指可食用的鱼、虾、蟹、贝；它是不可数名词，也是食品过敏提示里出镜率最高的词之一。\",\"seesaw\":\"叠韵拟态词：源于锯木时锯子一推一拉的节奏，儿歌里唱作 see-saw。跷跷板一上一下正如拉锯，18 世纪这个唱词就成了玩具的名字。\",\"sheet\":\"古英语 scēat「布的一角、一块布」，与 shoot 同族。床单是一整块布；sheet 还兼指一张纸、一片冰面，核心都是「薄而平的一片」。\",\"shooting\":\"派生于 shoot：古英语 scēotan「急速射出」，日耳曼语固有词，与 shot、shuttle 同族。作为运动名的 shooting，就是其名词化的用法。\",\"shop\":\"古英语 sceoppa「棚屋、小作坊」，日耳曼语固有词：本是工匠干活的棚子，前店后坊，出售只是附带；现代 shopping 的逛购义是后来才长出来的。\",\"shovel\":\"古英语 scofl「铲」，与 shove「推」同源：铲土就是把土「推」开、搬走。德语 Schaufel 是它的同源词，形状与发音都还留着亲戚相。\",\"sidewalk\":\"美国英语的透明复合词 side + walk，19 世纪成词，指马路边上专供行人走的那条带子；英国英语里它叫 pavement，同一个东西两种叫法。\",\"singing\":\"派生于 sing：古英语 singan，日耳曼语固有词，与德语 singen 同源；名词 song 是它的一对孪生词——一个管动作，一个管作品。\",\"skating\":\"派生于 skate「冰鞋」：skate 来自荷兰语 schaats，本指绑在鞋底的滑条，其更深来源有一点争议（或与「高跷」一类的词有关）。穿上它在冰上滑行，就是 skating。\",\"skiing\":\"派生于 ski：ski 来自挪威语 ski「劈开的木片」，源头是古诺尔斯语 skíð「劈柴、木条」——滑雪板本就是一片劈开的长木。19 世纪它随挪威人进入英语。\",\"slide\":\"古英语 slīdan「滑行」，日耳曼语固有词，与 sled「雪橇」同族。滑梯、幻灯片（在放映机中滑入的那一张）、山体滑坡，取的都是「滑」这一个动作。\",\"snowboarding\":\"透明复合词 snow + board。board 是古英语 bord「木板」：1965 年美国人波彭把滑雪板改成一块宽板，称之为 snurfer（雪上冲浪板），单板滑雪由此发端。\",\"softball\":\"透明复合词 soft + ball。1887 年起源于芝加哥，本是棒球的室内变体，球更大、更软而得名；其实现代比赛用球并不软，名字只是留作纪念。\",\"sprint\":\"来自古诺尔斯语 spretta「跳起、迸出」，与 spurt「喷涌」同族：本义是突然间的迸发——短跑要的正是这一下爆发力，名字先写好了动作。\",\"stadium\":\"来自希腊语 stadion：本是长度单位（600 希腊尺，约 192 米），也是这个距离的短跑项目与跑道本身。古奥林匹亚的跑道正是一 stadion 长；现代体育场是借了古名。\",\"stool\":\"古英语 stōl「座位、宝座」，日耳曼语固有词，与德语 Stuhl「椅子」同源。英语里 stool 缩小成无靠背的凳子，德语 Stuhl 却泛指一切椅子——同源词在两地分了工。\",\"store\":\"来自古法语 estor「储备、补给」，源头是拉丁语 instaurare「修整、备置」。本义是「存货」：仓库里存的货多到可以拿出来卖，就成了商店——store 的「商店」义是在美国英语里发扬光大的。它与 story 并不同源。\",\"string\":\"古英语 streng「绳、弦」，与 strong 同族，都出自「拉紧、用力」的日耳曼老根：拉紧的线最有力量。弓弦、琴弦、鞋带，乃至「一串」（a string of）都由此伸展。\",\"suburb\":\"来自拉丁语 suburbium：sub-「在……之下、邻近」+ urbs「城市」。本义是「城墙外紧邻城区的地方」——罗马时代就已是城郊；urban、urbane 都出自同一个 urbs。\",\"supermarket\":\"透明复合词：super-（拉丁语「在……之上、超越」）+ market（市场，源于拉丁语 mercatus「贸易」，与 merchant 同族）。20 世纪在美国成词，指比普通市场大得多、自助选购的新式商店。\",\"surfing\":\"派生于 surf「拍岸的碎浪」：surf 一词来历不明，可能与拟声的 sough 有关，并无定论。冲浪本是波利尼西亚人的传统，经夏威夷走向世界，运动名随之通行。\",\"swimming\":\"派生于 swim：古英语 swimman，日耳曼语固有词，本义就是「在水中移动」，与德语 schwimmen 同源；作名词的 swimming 是这项运动与技能的统称。\",\"swing\":\"古英语 swingan「挥动、摆动」，日耳曼语固有词，与德语 schwingen 同源。秋千取其来回摆荡；棒球里的挥棒、爵士乐里的摇摆（swing），都是同一个动作核心。\",\"switch\":\"本是「细长柔韧的枝条」（16 世纪），其来源细节没有定论：枝条一挥如鞭；后来的电闸开关借其「一扳即动」的样子得名，再引申出「转换、交换」。\",\"syrup\":\"来自阿拉伯语 sharāb「饮料、酒」，经中世纪拉丁语 siropus、古法语 sirop 进入英语；与 sherbet、sorbet 同源（阿拉伯语 shariba「喝」）。本义是「甜饮」，后指浓稠的糖浆；maple syrup 是北美的枫糖浆。\",\"taekwondo\":\"韩语「跆拳道」直借：tae「用脚踢」、gwon（권）「拳」、do「道」。1955 年韩国统合各派武术后定名——踢、打、修为，三层意思都写进了名字。\",\"tennis\":\"来自古法语 tenez——动词 tenir「拿、接」的命令式，意思是「拿着！接住！」：宫廷网球发球前要向对手喊这一声，喊声最后成了运动的名字。tennis 的前身是宫廷手球 jeu de paume。\",\"tour\":\"来自拉丁语 tornus「车床」（源于希腊语 tornos），经古法语 tour「旋转、绕行」：绕上一圈再回到原点，就是一次 tour。tourist、tournament（骑士比武的绕场）都是同族。\",\"town\":\"古英语 tūn 本义是「篱笆围起的地方、农庄」，与德语 Zaun「篱笆」同源。围栏圈起的聚落长大成镇；英国地名里成批的 -ton（如 Newton）多半就是当年的 tūn。\",\"township\":\"透明复合词：town + -ship（辖区、状态后缀）。古英语 tūnscipe 本指「一镇居民的全体」，后来指小行政区；美国中西部那种方格状的「镇区」也源于此。\",\"toy\":\"来源不明：14 世纪时 toy 指「玩笑、调情」，17 世纪才专指儿童的玩物；词源没有定论，是英语常用词里少数查不到出身的一个。\",\"trail\":\"来自动词 trail「拖曳」，经古法语 trailler 上溯拉丁语 tragula「拖网」：猎物走过，脚印与气味像被「拖」出一条线——这就是兽径；人走出的山间小道也沿用此名。\",\"trash\":\"多认为来自斯堪的纳维亚语一脉（挪威语方言 trask 是「破烂杂物」，瑞典语 trasa 是「碎布」），细节未完全定论。16 世纪它先指剪落的碎枝败叶，后来泛指一切垃圾。\",\"trick\":\"来自古法语 triche「欺骗、作弊」，trichier 是「骗」；更深来源或与拉丁语 tricari「耍花招、拖延」有关。魔术里的 trick 是「善意的诡计」——这个词的核心自始带着「计谋」。\",\"trip\":\"经古法语 triper「轻跳、碎步走」而来，深层来源多认为在日耳曼语（如荷兰语 trippen「碎步走」），细节有争议。本义是轻快短促的行程，后来又兼指「绊倒」与药物带来的幻觉之旅。\",\"trombone\":\"意大利语 trombone：tromba「小号」+ 加大后缀 -one——「大一号的小号」就是长号。它在英语里的旧名是 sackbut，源于法语 saqueboute「推拉筒」，写实得很。\",\"trumpet\":\"来自古法语 trompette，是 trompe「号角」的指小形；trompe 的更深来源可能是日耳曼语的拟声词——模仿的正是号声。小号的祖先是军号与猎号。\",\"tunnel\":\"来自古法语 tonnelle，本是 tonnel「大酒桶」的指小形（源头 tonne「桶」，与 ton「吨」同源）：先指桶形的罩网与通道，后来指穿山越岭的隧洞。桶、吨、隧道，都在这条「大容器」的线上。\",\"vacation\":\"来自拉丁语 vacare「空着、闲着」的一脉（名词 vacatio「免除、空闲」），与 vacant、vacuum 同族：假期就是「被空出来的时间」。美式英语用 vacation，英式英语多用 holiday——那是 holy day「圣日」的缩合。\",\"village\":\"来自拉丁语 villa「乡间庄园、农舍」一脉，经古法语 village 进入英语：先是庄园，后是庄园周围聚起来的村落。villain「恶棍」与它同源——villain 本义是「庄园上的佃农」，词义一路滑向贬义。\",\"vinegar\":\"来自古法语 vin aigre「酸酒」：vin 是酒，aigre 是「酸」（源于拉丁语 acer「尖锐的」）。酒放酸了就是醋，法语把这句判断直接拼成了词；eager「热切的」与 aigre 同源，「尖锐」一根分两枝。\",\"vineyard\":\"透明复合词 vine + yard。vine「葡萄藤」来自拉丁语 vinum「葡萄酒」一脉（经古法语）；yard 是古英语 geard「围地」，与 garden、orchard 的后段同源——围起来种葡萄的地。\",\"violin\":\"来自意大利语 violino「小维奥拉」，是 viola 的指小形。viola 一族的深层来源有争议（一说与中世纪拉丁语 vitula「弦乐器」有关）。16 世纪意大利克雷莫纳的工坊定型了现代小提琴。\",\"volleyball\":\"透明复合词 volley + ball。volley 源于法语 volée「飞行」（拉丁语 volare「飞」）：1895 年这项运动诞生时强调球不落地、在空中飞来飞去；它最初的名字是 mintonette。\",\"wardrobe\":\"来自古法语 warderobe：warder「保管」（日耳曼语，与 guard 同源）+ robe「长袍、衣物」。本义是「保管衣物的房间」，后来缩小为衣柜；剧组与片场的「服装间」仍用此词。\",\"wedding\":\"派生于 wed：古英语 wedd 是「誓约、抵押品」。婚礼先是一纸立约——古人以 wedd 作为担保与承诺，后来它专指婚约，wedding 就是缔结这份约的仪式。\",\"well\":\"古英语 wella「泉、涌出水的地方」，与 weallan「沸腾、涌起」同源：本义是天然涌泉，后指人工打出的水井。作副词讲「好」的 well 是另一条线（源于「意愿」），与水井同形异源。\",\"wire\":\"古英语 wīr「金属丝」，日耳曼语固有词，更深来源或与「弯曲、编织」一脉的词有关，细节存疑。电线、铁丝网、窃听器（wiretap）都出自这一根金属丝。\",\"woods\":\"wood 是古英语 wudu「树木、木材」，日耳曼语固有词。单数多指木材，作「树林」讲时习惯用复数 woods；wood 与 wide 没有关系，只是个头碰巧相近。\",\"wrench\":\"古英语 wrenc「扭转、诡计」，动词 wrencan 是「扭」，与 wrong「错的」（被扭歪的）同族：扳手就是「扭的工具」；wrench 还兼指猛地一拧与锥心的痛。\",\"wrestling\":\"古英语 wræstlung，动词 wræstan 是「扭、拧」，与 wrist「手腕」、wring「绞拧」同族：摔跤的核心动作正是扭转、控制对方的身体。\",\"yoga\":\"来自梵语 yoga「结合、轭」，词根 yuj 是「套上轭、连接」，与英语 yoke「牛轭」是印欧语层面的同源词。瑜伽取义身与心、个体与宇宙的「合一」。\",\"zone\":\"来自希腊语 zōnē「腰带」，经拉丁语 zona 进入英语。古人把地球想象成系着几条带子——热带、温带、寒带就是气候的「带」；后来泛指任何划出的条带区域，time zone「时区」同理。\",\"distance\":\"来自拉丁语 distantia，源于 distare「分开站立」（dis- 分开 + stare 站）：两点各自站开，中间隔出的就是距离；distant 是它的形容词兄弟。\",\"distortion\":\"来自拉丁语 distortio，源于 distorquere「扭歪」（dis- + torquere 扭）：本是把东西拧变形，后指图像、声音、事实被扭曲；同根的 torture（酷刑）也是「拧」出来的。\",\"disturbance\":\"来自拉丁语 disturbare「搅乱」（dis- + turbare 搅动，turba 人群、混乱）：把平静搅成一团乱就是 disturbance；turbulent（湍流的）出自同一个搅动家族。\",\"ditch\":\"来自古英语 dīc，本义就是挖出的沟，也指堆沟土成的堤；它与 dike（堤坝）是同一个词的一体两面——挖沟与堆堤本是一回事。\",\"diversity\":\"来自拉丁语 diversitas，源于 divertere「转向不同方向」（di- + vertere 转）：朝不同方向转开，就是各不相同；diverse、divert 同族。\",\"division\":\"来自拉丁语 divisio，源于 dividere「分开、分配」：一刀分成几份既是除法，也是部门与分歧；divide 是动词本体。\",\"doctrine\":\"来自拉丁语 doctrina「教导、学说」，源于 docere「教」：与 doctor（本义教师）、document（本义教本）同族——一套被教、被传的成体系信条。\",\"doubt\":\"经古法语源于拉丁语 dubitare「在两者之间摇摆、拿不准」，与 duo「二」同族：心里有两个选项晃来晃去就是怀疑；词中那个不发音的 b 是学者按拉丁原形硬加回去的。\",\"drainage\":\"drain 源于古英语 drēahnian「沥干、滤干」，与 dry（干）同源：把水沥走就是排水，drainage 是排水系统与过程。\",\"droplet\":\"drop（水滴，古英语 dropa）加指小后缀 -let「小」：drop 本身是日耳曼语老词，一颗小水滴就是 droplet。\",\"dynamite\":\"诺贝尔 1867 年命名的造词：希腊语 dynamis「力量」+ 炸药命名惯用的后缀 -ite——把「力量」装进管子里的发明；dynamic（动力的）是同根兄弟。\",\"earnestness\":\"earnest 源于古英语 eornost「认真、郑重」，是日耳曼语老词，earnestness 就是一本正经、全力以赴的状态；注意它与表「定金」的 earnest（源于法语 erres）不是一回事。\",\"eccentricity\":\"经拉丁语源于希腊语 ekkentros「偏离中心的」（ek- 出 + kentron 中心）：天文学先用它讲轨道偏心，为人偏离「中心常规」就是古怪；eccentric 是形容词本体。\",\"ecosystem\":\"ecology（生态学：希腊语 oikos 家 + logos 学问）与 system（体系）的拼合，1935 年由英国生态学家坦斯利提出：把一片环境看作一个有组织的「家政系统」。\",\"edge\":\"来自古英语 ecg「锋刃、刀口」，是日耳曼语老词：先有刀刃，才有边缘——物体的边线就是它的「刃口」；have an edge（占优势）也是从刃口的锋利引申来的。\",\"edition\":\"来自拉丁语 editio「出版、发行」，源于 edere「给出、发表」（e- 出 + dare 给）：每正式「给出」一次，就是一个版本；editor（编辑）是负责放行的人。\",\"effectiveness\":\"effective 源于拉丁语 efficere「做成、实现」（ex- + facere 做）：真能「做成事」的程度就是 effectiveness；effect 的本义就是做出来的结果。\",\"efficiency\":\"来自拉丁语 efficientia，源于 efficere「做成」：与 effectiveness 同出 facere「做」家族——efficiency 讲的是用最少的投入做成事，即效率。\",\"ego\":\"直接借自拉丁语 ego「我」：弗洛伊德借它命名人格中面对现实的「自我」一层；egoism、egotist 都从这个「我」长出。\",\"ejection\":\"来自拉丁语 eiectio，源于 eicere「抛出」（e- 出 + iacere 扔）：与 inject（注射，往里扔）、project（投射，往前扔）同是 iacere 家族——eject 就是往外扔。\",\"elasticity\":\"elastic 经法语源于希腊语 elastikos，源头是 elaunein「驱动、锻打」：本指金属可锻打延展，17 世纪后转指橡皮筋式的弹回；elasticity 是这份弹性的程度。\",\"elicitation\":\"elicit 源于拉丁语 elicere「引出、诱出」（e- 出 + lacere 引诱）：把藏着的话、反应一点点引出来，过程就是 elicitation；注意与 illicit（非法的）只是形近。\",\"eligibility\":\"eligible 经法语源于拉丁语 eligere「挑选出来」（e- + legere 选）：够格「被选中」的条件就是 eligibility；elect（选举）正是同一个挑选动作。\",\"elimination\":\"来自拉丁语 eliminare「逐出门外」（e- + limen 门槛）：本义是把人赶过门槛、逐出家门，后泛指一切消除、淘汰；preliminary（初步的）里的 limen 也是门槛。\",\"elite\":\"法语 élite「被选出的人」，源于拉丁语 eligere「挑选」：与 eligible、election 同族——elite 就是各行各业被挑出来的那一小撮。\",\"eloquence\":\"来自拉丁语 eloquentia，源于 eloqui「说出」（e- + loqui 说）：把话说得流畅有力就是 eloquence；soliloquy（独白）同出 loqui「说」家族。\",\"elucidation\":\"来自拉丁语 elucidare「照亮、阐明」（e- + lux 光）：把光打进去让暗处看清，就是 elucidation；lucid（清晰的）是同一束光。\",\"emancipation\":\"来自拉丁语 emancipatio，源于 emancipare「交出所有权、使脱离掌控」（e- + manus 手 + capere 抓）：法律上把人从「手心」里放出去，就是解放；manual（手的）、capture（抓）都在词源里留着印。\",\"embargo\":\"西班牙语 embargo「扣押、妨碍」，源于 embargar「阻拦」：政府下令扣住贸易、封锁港口，就是 embargo；西班牙语源的词在英语里不多，它是显眼的一个。\",\"embarkation\":\"embark 经法语 embarquer「登船」（em- + barque 小船）：本义是人上小船，后泛指登机、启程；embarkation 就是登船登机的过程，disembark 是反向。\",\"embarrassment\":\"embarrass 经法语 embarrasser「设障碍、阻碍」（em- + barre 栏杆）：进退都被栏住的窘境就是 embarrassment；西班牙语 embarazo（怀孕）与它同源，是著名的假朋友。\",\"embellishment\":\"embellish 源于古法语 embellir「使变美」（em- + bel 美，拉丁语 bellus）：给文章、房间添上美的东西就是 embellishment；belle（美人）是同一个美的家族。\",\"ember\":\"来自古英语 ǣmyrge「余烬、灰烬」，是日耳曼语老词：火灭之后还红着的炭块就是 ember，常用复数 embers。\",\"embodiment\":\"embody 是 em-（使进入）+ body（身体）：让抽象的东西获得一具「身体」，就是 embodiment；化身、体现都从这具身体来。\",\"embrace\":\"经古法语 embracer「抱入双臂」（em- + bras 手臂，拉丁语 bracchium）：双臂围拢就是拥抱，后引申为欣然接受新思想；bracelet（手镯）戴在同一条手臂上。\",\"embryo\":\"经拉丁语源于希腊语 embryon「初生之物」（en- + bryein 萌发、膨胀）：在母体内萌发生长的那一团，就是 embryo。\",\"emerald\":\"经古法语、拉丁语 smaragdus 源于希腊语 smaragdos「绿宝石」，更早的源头可能在闪族语言或梵语 marakata——宝石沿贸易路西行，词也一路西传；Emerald Isle 是爱尔兰的别称。\",\"empiricism\":\"希腊语 empeiria「经验」（en- + peira 尝试、试验）：只认亲身试出来的经验，就是 empiricism；empirical（实证的）同族，experience 里的 per 也是同一个「试」。\",\"employment\":\"employ 经古法语 employer，源于拉丁语 implicare「卷入、投入」（in- + plicare 折叠）：把人的时间「卷进」一项工作，就是 employment；它与 imply 同根，那层「卷入」还在。\",\"emptiness\":\"empty 源于古英语 ǣmtig「空的、闲着的」，本与 ǣmetta「闲暇」有关：先是「没被占用的」，再变成「里面什么都没有」；empty 加 -ness 就是空虚的状态。\",\"enactment\":\"enact 是 en- + act（做，拉丁语 agere）：把议案正式「做」成法律，就是 enactment；act 家族（action、agent）都出自 agere「做、驱动」。\",\"enamel\":\"经法语 émail，源头是日耳曼语的 smalt「熔化的釉料」（与 smelt 熔炼同源）：烧熔后附在金属、牙齿表面的硬壳就是 enamel，牙釉质是它最常出现的场合。\",\"enclosure\":\"enclose 源于拉丁语 includere「关进去」（in- + claudere 关）：用篱笆把地「关」起来，就是 enclosure；close、include 都出自 claudere「关」家族。\",\"encore\":\"直接借自法语 encore「再一次」：观众喊 encore，就是要求再来一次；它的更深来源（拉丁语 hanc horam「到此刻」等说法）尚有争议，法语这一层已足够清楚。\",\"encouragement\":\"encourage 经法语，源于 encouragier「给勇气」（en- + courage 心、勇气，拉丁语 cor 心脏）：把勇气放进人心里就是 encouragement；courage 本身就是从「心」长出来的词。\",\"encroachment\":\"encroach 源于古法语 encrochier「钩住、抓取」（en- + croc 钩子）：像钩子一样一点点探进别人的地界，就是 encroachment；crochet（钩针编织）用的是同一把钩子。\",\"endangerment\":\"endanger 是 en- + danger；danger 源于拉丁语 dominium「主人的权力」经法语演变，本义是「处于他人支配之下、易受伤害」，后来才变成「危险」：endangerment 是把人或物置于这种境地的行为。\",\"endorsement\":\"endorse 源于中世纪拉丁语 indorsare「写在背面」（in- + dorsum 背）：支票背面签名叫背书，endorsement 就是这份签在背后的支持；dorsal（背部的）是同一个「背」。\",\"endurance\":\"endure 经法语源于拉丁语 indurare「使变硬」（in- + durus 硬）：硬撑着不垮，就是 endurance；durable（耐用的）是 durus「硬、持久」的家族。\",\"enforcement\":\"enforce 源于古法语 enforcier「使强、强行」（en- + force 力，拉丁语 fortis 强）：动用力量让规则落地，就是 enforcement；force 本人经法语来自 fortis「强壮」。\",\"engagement\":\"engage 经法语 engager「抵押、立约」（en- + gage 抵押物）：先是把东西押出去订约，后有订婚（婚约）与参与、交战诸义；engagement 是这份「被约定绑住」的状态。\",\"engineer\":\"engine 经法语 engin，源于拉丁语 ingenium「天生的才能、巧思」：engineer 本是设计器械的巧思之人；ingenious（精巧的）与它同根，engine 早年指一切巧妙的机械装置。\",\"engraving\":\"engrave 是 en- + grave「刻」；表「刻」的 grave 源于古英语 grafan「挖、刻」，与 grave（坟墓，本义挖出的坑）同源：在金属板上挖出线条，就是 engraving。\",\"enhancement\":\"enhance 源于盎格鲁-法语 enhauncer「抬高」，深层是拉丁语 altus「高」（经 inaltiare）：把品质、价格往高处抬，就是 enhancement；altitude（海拔）共享同一个「高」。\",\"enigma\":\"经拉丁语源于希腊语 ainigma「谜语」，源于 ainissesthai「暗示、用谜语说」：说得让人猜不透的东西就是 enigma；二战德军密码机 Enigma 就以它命名。\",\"enjoyment\":\"enjoy 源于古法语 enjoir「享用、使高兴」（en- + joie 喜悦，拉丁语 gaudium）：enjoyment 是享受本身；joy 是它的近亲，joie 的「喜悦」一脉相承。\",\"enlargement\":\"enlarge 是 en- + large（大、宽，拉丁语 largus 慷慨的、丰盛的）：large 的本义是「给得多、宽绰」，放大、扩大的 enlargement 从这份宽绰长出。\",\"enlightenment\":\"enlighten 是 en- + lighten（照亮，light 光）：把光放进黑暗处就是启蒙；18 世纪的 Enlightenment 启蒙运动正是借这束光命名——理性照亮蒙昧。\",\"enmity\":\"经古法语源于拉丁语 inimicus「敌人」（in- 不 + amicus 朋友）：字面就是「非朋友」——enmity 是深入骨髓的敌意；enemy（敌人）是同一个 inimicus 的另一条演化线。\",\"enormity\":\"来自拉丁语 enormitas，源于 enormis「超出常规的」（e- 出 + norma 规尺、直角尺）：大到跳出尺子的量程，先指滔天罪行，后兼指体量巨大；norm（标准）就是那把被超出的尺。\",\"enrichment\":\"enrich 是 en- + rich；rich 源于古英语 rīce「强大的、有权势的」，与拉丁语 rex（国王）、德语 Reich（帝国）同出一个印欧语「统治」词根：先有权势，后有财富；enrichment 是让土地、生活「富起来」的过程。\",\"ensemble\":\"直接借自法语 ensemble「一起、整体」，源于拉丁语 insimul「同时」（in- + simul 一起）：一群人合在一起的整体就是 ensemble；simultaneous（同时的）共享 simul「一起」。\",\"enslavement\":\"enslave 是 en- + slave；slave 源于中世纪拉丁语 sclavus「斯拉夫人」——中世纪大量斯拉夫人被掳为奴，族名竟成了奴隶的通称：enslavement 记录着这段沉重历史。\",\"enthusiasm\":\"希腊语 enthousiasmos「神灵附体、灵感」，源于 entheos「神在体内」（en- + theos 神）：古人把狂热解释为神进了身体；今天 enthusiasm 只剩热忱，theos 还藏在 theology（神学）里。\",\"entirety\":\"entire 源于拉丁语 integer「完整无缺的」（in- 未 + tangere 触碰）：没被碰过、没缺一块的整体就是 entirety；integer（整数）与 integrity（正直）是同一个「完整」家族。\",\"entrance\":\"enter 源于拉丁语 intrare「走进」，entrance 是走进的门与动作；注意表「使入迷」的 entrance 源于 trance（恍惚），与入口一词同形而不同源。\",\"entry\":\"经古法语 entree，源于拉丁语 intrare「走进」：走进的记录、词条、参赛登记都是 entry——每个条目都是一次「进入」档案的机会。\",\"environs\":\"法语 environ「周围」的名词化，源于 en viron「绕成一圈」（viron 圈，源于 virer 转）：城墙外绕着的那一圈地带就是 environs，常用复数。\",\"envoy\":\"法语 envoyé「被派遣的人」，源于 envoyer「派遣」（en- + voie 路，拉丁语 via）：被派上路的人就是 envoy（使节）；convey（传送）走的也是 via 这条「路」。\",\"envy\":\"经古法语源于拉丁语 invidia，源于 invidere「斜着眼看、看不顺眼」（in- + videre 看）：嫉妒就是盯着别人的好「斜眼看」；video、vision 的 videre 也在 envy 里藏着一双眼睛。\",\"epilogue\":\"希腊语 epilogos「附加的话」（epi- 在…后 + logos 言语）：正文讲完之后补上的收尾就是 epilogue；prologue（序言）是它的镜像兄弟。\",\"episode\":\"希腊语 epeisodion「插入的部分」（epi- 附加 + eisodos 入场：eis 进 + hodos 路）：本是古希腊悲剧两段合唱之间插入的对白，后成剧集的一集、人生的一段插曲。\",\"epitaph\":\"希腊语 epitaphios「在墓上的」（epi- 在…上 + taphos 坟墓）：刻在墓上（epi-）的话就是 epitaph；taphos 这座「墓」在英语里主要留下了这块碑。\",\"epitome\":\"希腊语 epitomē「删节本」（epi- + temnein 切）：把长卷「切」成精华短本，就是 epitome（缩影）；atom（原子，本义切不开的）与它同出 temnein「切」。\",\"epoch\":\"希腊语 epokhē「停顿、计时的固定点」（epi- + ekhein 持有、停住）：时间长河里被「钉住」的一个点，后成新纪元的起点；epoch-making 就是钉下一个新点。\",\"equality\":\"equal 源于拉丁语 aequalis「相等的」，源于 aequus「平的、公允的」：一样平，就是 equality；equator（赤道）是把地球「平分」的那条线。\",\"equipment\":\"equip 经法语 équiper「装备」，更早与古诺尔斯语 skipa「装配船只」（skip 船）相关：本是给船配齐出航之物，后泛指一切设备；equipment 是不可数名词，指装备总称。\",\"equity\":\"来自拉丁语 aequitas「公平」，源于 aequus「平的、公允的」：与 equality 同根——equality 是数量一样平，equity 是判得公允；衡平法与资产净值两义都从「公平」分出。\",\"era\":\"拉丁语 aera，本义是纪年的计数起点（与 aes「铜、计数用的铜筹」有关）：一段以某个起点算起的历史时期就是 era；它的确切形成细节学界尚有讨论，大方向是「纪年」无疑。\",\"eradication\":\"来自拉丁语 eradicare「连根拔除」（e- 出 + radix 根）：把根从土里拔净就是 eradication；radical（根本的、激进的）、radish（萝卜）都从 radix 这条「根」长出。\",\"erasure\":\"erase 源于拉丁语 eradere「刮掉」（e- + radere 刮、擦）：在蜡版、石板上刮去字迹就是 erase，erasure 是擦除的痕迹与动作；razor（剃刀）是同一个「刮」家族。\",\"erection\":\"来自拉丁语 erectio，源于 erigere「立直」（e- + regere 引直、统治）：把建筑竖起来就是 erection；regere 也在 direct、rule 的祖先里。\",\"errand\":\"来自古英语 ǣrende「使命、口信」，是日耳曼语老词：本是替人传话办事的正式使命，现代缩小成买酱油式的跑腿；errand 本人就是一条被派出去的「口信」。\",\"escalation\":\"escalate 是 20 世纪从 escalator（自动扶梯）逆构出的新词，根在拉丁语 scala「梯子」：一级一级往上爬的紧张局势就是 escalation；scale（梯子→刻度→规模）同族。\",\"escape\":\"经古法语源于通俗拉丁语 excappare「脱出斗篷」（ex- 出 + cappa 斗篷）：追兵只抓到斗篷、人已脱身——金蝉脱壳就是 escape 的字面；cape（斗篷、海角）是那件被留下的斗篷。\",\"escort\":\"经法语源于意大利语 scorta「向导、护卫队」，深层与拉丁语 corrigere「引正、引领」有关，细节略有争议：大意是「被引着安全通过」的人马，护送者 escort 由此而来。\",\"essence\":\"来自拉丁语 essentia，源于 esse「存在、是」：essentia 是哲学家造出来对译希腊语「存在本身」的词——essence 是事物「是其所是」的那一点；essential 同族。\",\"establishment\":\"establish 源于拉丁语 stabilire「使稳固」，源于 stabilis「稳的」（stare 站）：站得稳，才立得住——establishment 是建立的动作，也是立稳了的机构与当权阶层。\",\"blink\":\"中古英语 blinken「闪烁」，与古英语、中古荷兰语的「闪烁、发光」词族关系纠缠，确切路径有争议：眨眼如光的明灭一闪，这个画面倒是古今一致。\",\"bounce\":\"中古英语 bownsen「重击、砰地弹起」，拟声色彩浓厚，来源不确：球撞地的「砰—弹」就是 bounce；支票跳票的 bounce 是 20 世纪的比喻新义。\",\"bow\":\"来自古英语 būgan「弯曲、鞠躬」，是日耳曼语老词：身体向前「弯」就是鞠躬；弓 bow 源于古英语 boga，本是同根的「弯」，而船头 bow 则借自北欧语的「肩」，不要混。\",\"bury\":\"来自古英语 byrgan「埋葬」，源于 beorgan「保护、藏匿」：把逝者「藏护」进土里就是 bury；它受 burh（城镇）拼写影响，读音却保留着古老的元音，所以读作与 berry 相近的音。\",\"chase\":\"经古法语 chacier「追赶」，源于通俗拉丁语 captiare「设法抓捕」，是拉丁语 capere「抓」的后代：chase 的祖先与 capture（捕获）的 capt 同门——追，就是为了抓。\",\"chew\":\"来自古英语 cēowan「咀嚼」，是日耳曼语老词：下巴的研磨动作自古如此；chew over 是把话也放进嘴里慢慢「嚼」。\",\"chop\":\"中古英语 choppen「砍劈」，与 chappen「裂开」等词关系纠缠，属日耳曼语的动作词族：刀落木开的干脆就是 chop；「排骨」chop 是砍下的一块。\",\"clutch\":\"中古英语 clucchen，源于古英语 clyccan「攥紧、弯钩」：手指弯成钩把东西扣死，就是 clutch；汽车离合器 clutch 是「扣合—释放」的同一个动作比喻。\",\"collide\":\"来自拉丁语 collidere「撞在一起」（com- 一起 + laedere 撞击、伤害）：laedere 还生出 lesion（损伤）——collide 是两物带着伤害潜能的相撞。\",\"crash\":\"中古英语 crasshen，拟声词：重物相撞、碎裂的哗啦声直接成词；crash 兼指坠毁、暴跌，都带着「猛地倒下」的劲。\",\"crawl\":\"中古英语 crawlen，可能源于古诺尔斯语 krafla「抓爬」或中古低地德语一带：确切来源在北欧语族里，四肢抓地前行就是 crawl；游泳的 crawl（自由泳）是 20 世纪的新义。\",\"dig\":\"中古英语 diggen，来源不确，可能与日耳曼语「沟」词族（ditch、dike 的亲戚）有关：dig 的确切出身无定论。\",\"drag\":\"中古英语 draggen，可能源于古诺尔斯语 draga「拉」，也与古英语 dragan（draw 的根）有关：在地上摩擦着拉，就是 drag；draw 与 drag 本是同根的「拉」。\",\"drop\":\"来自古英语 dropa「水滴」，动词 droppian，是日耳曼语老词：水滴落下，drop 就兼了「一滴」与「落下」；与德语 Tropfen 同源。\",\"kick\":\"中古英语 kiken，来源不确，可能与北欧语或威尔士语的「踢」词有关：kick 的出身是英语词源学里的小悬案，动作本身倒无人不识。\",\"kiss\":\"来自古英语 cyssan「亲吻」，是日耳曼语老词，德语 küssen 同源：多半带拟声色彩——嘴唇轻触的那一声。\",\"kneel\":\"来自古英语 cnēowlian，源于 cnēow「膝盖」（knee）：knee 的 k 曾经发音，kneel 就是「以膝着地」。\",\"knit\":\"来自古英语 cnyttan「打结」，源于 cnotta「结」（knot）：把线打成一个个结，就是 knit；眉头「打结」的 knit one's brows 是同一个动作。\",\"lean\":\"来自古英语 hleonian「倚靠、倾斜」，是日耳曼语老词，德语 lehnen 同源：身体失去垂直、靠向一侧，就是 lean；ladder（梯子，本义倚墙之物）是它的远亲。\",\"lick\":\"来自古英语 liccian「舔」，与拉丁语 lingere「舔」、希腊语 leikhein 同出一个印欧语词根：舌头所到之处，古今各语言都留了相似的音形。\",\"lift\":\"中古英语 liften，源于古诺尔斯语 lypta「举到空中」，与 lyft「空气、天空」有关：把东西送进「空气」里就是 lift；德语 Luft（空气）是它的亲戚，电梯 lift 亦由此得名。\",\"limp\":\"中古英语 limpen「跛行」，与古英语 lemphealt「跛的」一脉，来源细节不确：limp 既是「一瘸一拐」，也是「柔软无力」——两种「没劲」共用一词。\",\"lower\":\"low（低，源于古诺尔斯语 lágr）的比较级动词化：lower 就是「使更低」；注意表「阴沉」的 lower 源于中古英语 louren，是另一个词。\",\"march\":\"经法语 marcher「行进」，来源有争议：一说源于日耳曼语「踩出足迹」（mark 标记）一族，学界未有定论；月份 March 则是战神 Mars 的词，两者不要混。\",\"mend\":\"mend 是 amend 的缩短：拉丁语 emendare「除去毛病」（e- + menda 缺点）——缝补、修理都是「去缺点」；amend（修正）是它的完整版兄弟。\",\"nod\":\"中古英语 nodden「垂头、点头」，来源不确，可能与德语一带的「摇晃」词有关：困意里头一点一点的动作，就是 nod 的原形。\",\"pack\":\"中古英语 pak，可能源于中古荷兰语、低地德语 pak「包裹」：本是捆扎好的一包东西，后有打包、狼群、挤满诸义——都从「密密装在一起」长出。\",\"pat\":\"多半是拟态词：手掌轻落发出的那一声就是 pat，动作与声音同名；中古英语已有此词。\",\"peek\":\"中古英语 piken「偷看」，来源不确，可能与中古荷兰语 kieken 一类词有关：peek 的确切出身无定论，从缝隙里看的动作倒是写在用法里。\",\"peep\":\"拟声色彩浓厚：小鸡的唧唧声是 peep；「窥视」义的 peep 在 15 世纪出现，可能与 peek 纠缠演变——词典里声音与偷看是分开的两条。\",\"pinch\":\"经盎格鲁-法语 pincier「捏、掐」，更早的源头可能与通俗拉丁语的一种「戳刺」词有关，确切来源有争议：两指一合的力度就是 pinch，还引申出「拮据」。\",\"pull\":\"来自古英语 pullian「拉、拔」，来源不确，可能与低地德语 pulen「剥、拔」有关：pull 的出身朴素含糊，动作却极明确——朝自己方向使劲。\",\"punch\":\"作「击打」讲的 punch 来源未有定论，可能与中古法语「戳」一脉或 pounce（猛扑）有关；它与「打孔器」punch（源于拉丁语 puncta 刺孔）、宾治酒 punch（源于印地语「五」）是三个不同的词。\",\"push\":\"经古法语 poulser，源于拉丁语 pulsare「推、敲击」（pellere 推的反复体）：pulse（脉搏）与 push 同出 pellere 家族——一下一下的推，就是脉搏的跳。\",\"roll\":\"经古法语 roller，源于拉丁语 rotare「旋转」（rota 轮子）：轮子的转动就是 roll；rotate、round 都与 rota 同族，名单义的 roll 来自卷起的卷轴。\",\"rub\":\"中古英语 rubben，可能源于斯堪的纳维亚语（与丹麦语 rubbe「擦」有关），确切来源未定：手掌贴着表面来回，就是 rub。\",\"scratch\":\"中古英语 scracchen，来源不确，可能糅合了古英语与古诺尔斯语的「抓、爬」词：scratch 的确切出身无定论，指甲划过表面的声音与动作是它的招牌。\",\"seek\":\"来自古英语 sēcan「寻找」，是日耳曼语老词，德语 suchen 同源：seek 是英语最古老的「找」之一。\",\"sew\":\"来自古英语 sīwian「缝」，与拉丁语 suere「缝」、梵语 sūtra（线、经）同出印欧语「缝缀」词根：suture（缝合线）是 sew 在医学里的拉丁亲戚。\",\"slap\":\"拟声词，源于低地德语、荷兰语一带的 slap「拍击声」：巴掌落下的声音先进了语言，动作随后同名。\",\"slip\":\"中古英语 slippen，可能源于中古低地德语、荷兰语 slippen「滑」，与 slippery 同族：脚下失去抓力的一瞬就是 slip；陶工用的 slip（泥浆）同出「滑腻」一义。\",\"spin\":\"来自古英语 spinnan「纺线」，是日耳曼语老词：纺锤旋转抽线是本行，后泛指一切旋转；spider（蜘蛛）在古英语里是「纺织者」的绰号。\",\"squat\":\"经古法语 esquatir「压低、蹲下」（es- + quatir 压，深层是拉丁语 coactus 挤压）：身体被「压」到低处就是 squat；非法占住空屋的 squat 义是后来长出的。\",\"squeeze\":\"中古英语 queisen 一脉，源于古英语 cwȳsan「压」：squeeze 的 squ- 是后来添上的音；把东西压出水、压进缝，都是这个「压」。\",\"stab\":\"中古英语 stabbe，来源不确，可能源于苏格兰语 stob「尖桩」：先有尖桩，后有「用尖器刺」的动作；stab 的确切出身学界未定。\",\"stare\":\"来自古英语 starian「凝视」，是日耳曼语老词，与德语 starren「僵直地看」同源：眼神「僵住不动」地看，就是 stare。\",\"stroll\":\"来源不确，可能源于德语 strollen「流浪、闲逛」：stroll 的确切出身无定论，慢悠悠、无目的的步态是它的标志。\",\"suck\":\"来自古英语 sūcan「吸」，与拉丁语 sugere 同源：吸奶的动作词根在印欧语里一路传下；soak（浸泡）是它的亲戚——让东西「吸饱」。\",\"swallow\":\"来自古英语 swelgan「吞咽」，是日耳曼语老词；注意燕子 swallow 源于古英语 swealwe，是完全不同的词——两个同形纯属巧合。\",\"throw\":\"来自古英语 þrāwan「扭转、旋转」，本义是拧、旋：投掷前手臂的旋拧留在了词源里，后来专指扔出；thread（线）是「拧成的」同族亲戚。\",\"toss\":\"晚期中古英语出现，来源不确，可能源于斯堪的纳维亚语：toss 的确切出身无定论，轻轻向上抛的动作自 16 世纪固定下来；toss a coin 是它最经典的场面。\",\"twist\":\"中古英语，源于古英语 -twist「分叉、绳股」，与 twine（双股线）、two 有远亲关系：把两股拧成一股就是 twist，本义里藏着「二」。\",\"unfold\":\"un- + fold；fold 源于古英语 fealdan「折叠」，与拉丁语 plicare 同出印欧语「折」的词根：unfold 是把折起的展开；enfold 是反向的同族词。\",\"unpack\":\"un- + pack：把 pack 的动作倒着做，就是 unpack；这种 un- 逆向构词是英语里最直白的构词法之一。\",\"untie\":\"un-（解开）+ tie；tie 源于古英语 tīgan，与 tēag「绳索」有关：untie 就是把系上的绳结逆向解开，是英语构词最透明的一类。\",\"wander\":\"来自古英语 wandrian「徘徊」，源于 wendan「转、行走」：与 wind（蜿蜒）同族，连 went（go 的过去式，本是 wend 的过去式）都是亲戚——wander 是没有钉死方向的行走。\",\"weave\":\"来自古英语 wefan「织」，是日耳曼语老词，德语 weben 同源：经纬交错就是 weave，它的过去式是 wove。\",\"wink\":\"来自古英语 wincian「闭眼、点头」，是日耳曼语老词，与「偏转」词族有关：头或眼的轻微一偏就是 wink，后来专指眨一只眼示意。\",\"wrap\":\"中古英语 wrappen，来源不确，可能与北欧语「缠绕」词族有关：wrap 的确切出身无定论，包住、裹住的动作是它不变的核心。\",\"calculate\":\"来自拉丁语 calculare，源于 calculus「小石子」——古罗马人用小石子在算盘上计数：calculate 的词根里藏着一把小石子；calculus（微积分）是同一颗石子的学术版。\",\"calibrate\":\"caliber（口径）加 -ate；caliber 经法语源于阿拉伯语 qālib「模具、鞋楦」，更深一层或与希腊语 kalapous「木楦」有关，细节有争议：按模具定尺寸，就是 calibrate（校准）。\",\"cancel\":\"来自拉丁语 cancellare「画格栅、交叉涂掉」，源于 cancelli「格栅、栏杆」：在文书上打叉作废就是 cancel；chancellor（大臣）本是站在宫廷格栅旁的官员，同出这道栅栏。\",\"canvass\":\"源头是 canvas（帆布）：早期 canvass 指把人放进帆布里抛摔式的整治，后转指反复抖搂盘查，再到逐户游说拉票；canvas 本身源于拉丁语 cannabis「大麻」——帆布原是麻织的。\",\"capitalize\":\"capital 源于拉丁语 caput「头」：capitalize on 是把「本金、头筹」用足捞好处，capitalize 字母是把字母升到「头」的位置；cap、chief、captain 都是 caput 家族。\",\"capsize\":\"来源不确，一说与西班牙语 cabezar「低头、船头下沉」（cabeza 头，深层是拉丁语 caput）有关：船「头」栽下去翻覆，就是 capsize；学界标注为起源未定。\",\"captivate\":\"来自拉丁语 captivare「俘获」，源于 capere「抓」：被美貌或表演「抓」住心神，就是 captivate；captive（俘虏）是它的直系亲戚。\",\"capture\":\"来自拉丁语 captura「捕获」，源于 capere「抓、夺」：cap 家族（capable、captive、chase）都伸着这只「抓」的手；capture 是抓到手的那一刻。\",\"carve\":\"来自古英语 ceorfan「切、刻」，是日耳曼语老词，与德语 kerben「刻缺口」同源：在木石上切出形状就是 carve；carve out a career 是把事业也「刻」出来。\",\"cast\":\"源于古诺尔斯语 kasta「投掷」——维京人带来的词：渔网撒出、金属铸入模具、演员被「分配」角色，都从这记投掷长出；cast 的过去式不变形，是北欧语留下的脾气。\",\"catalog\":\"希腊语 katalogos「名单、登记」，源于 katalegein「逐项列举」（kata- 逐下 + legein 数、说）：一项一项往下数的清单就是 catalog；lecture 的 leg- 与它同族。\",\"catalyze\":\"catalyst 由瑞典化学家贝采利乌斯于 1835 年造词：希腊语 katalysis「解开、分解」（kata- 向下 + lyein 松开）——催化剂「解开」反应僵局而自身不变；catalyze 是使这种解开发生。\",\"categorize\":\"category 源于希腊语 katēgoria「公开指控、陈述」，是亚里士多德的术语（kata- + agora 集会广场）：先是在广场上「指认属性」，后成把事物归类的 category；categorize 是执行归类。\",\"cater\":\"源于古法语 acateur「采购食物的人」（acater 买，深层是拉丁语 accaptare 抓取）：cater 本行是承办酒席，cater to 迎合是按客人口味「上菜」的引申。\",\"censor\":\"拉丁语 censor 是罗马的监察官，职责是登记人口、估税、监察风纪，源于 censere「评估、估量」：censor 一词自带罗马官署的威严，审查就是它的现代职务。\",\"certify\":\"来自拉丁语 certificare「使确知」（certus 确定的 + facere 使）：把不确定的变成「已确定」，就是 certify；certain、certificate 都是 certus 家族。\",\"chant\":\"经古法语 chanter，源于拉丁语 cantare「唱」（canere 唱的反复体）：教堂里反复咏唱就是 chant；enchant（使着迷，本义以歌施咒）同出 canere 这支「唱」。\",\"characterize\":\"character 源于希腊语 kharaktēr「刻印的标记」，源于 kharassein「刻」：先是在钱币上刻下的印记，后成人的「品格印记」；characterize 是把这印记描出来。\",\"charm\":\"经古法语 charme，源于拉丁语 carmen「歌、诗、咒语」：古人相信唱出的咒语能迷人——charm 从魔法之歌变成了魅力；incantation 里的 cant 也是唱。\",\"chastise\":\"经古法语 chastier，源于拉丁语 castigare「惩戒、矫正」（castus 纯洁的 + agere）：本义是「使归于纯正」的管教，后专指严厉责罚；caste（种姓，本义纯洁血统）与 castus 同族。\",\"cheapen\":\"cheap 源于古英语 cēap「交易、买卖」，本是名词，后成形容词「便宜的」：cheap 的祖先在集市的讨价还价里（cēap 或与拉丁语 caupo「小贩」有关）；cheapen 是使变贱、使掉价。\",\"cheer\":\"经古法语 chiere「脸、表情」，源于晚期拉丁语 cara「脸」（希腊语 kara 头、脸）：先是脸色，后是心情，再是欢呼——cheer 的词源写在脸上。\",\"chime\":\"中古英语 chime 本指一组编钟，深层源于拉丁语 cymbalum「铙钹」：钟声的谐响就是 chime；chime in（插话附和）是跟着「合鸣」。\",\"chirp\":\"拟声词：鸟鸣的「啁啾」直接成词，中古英语已有 chirpen；与 chirrup 是同一声族。\",\"choke\":\"中古英语 choken，源于古英语 cēocian 一脉（见于 ācēocian「噎住」），与 cheek（脸颊）有关：东西卡进喉咙、贴住脸颊内侧，就是 choke。\",\"choreograph\":\"choreography 是希腊语 khoreia「舞蹈」+ graphia「书写」的 18 世纪造词：先有「舞谱术」，后逆构出动词 choreograph——把舞蹈「写」下来就是编舞。\",\"chuckle\":\"chuck（咯咯声，拟声）加反复后缀 -le：母鸡的咯咯、低笑的咯咯同声——chuckle 是压在喉咙里的轻笑。\",\"churn\":\"来自古英语 cyrin「搅乳器」，是日耳曼语老词：反复搅动奶油成黄油是本行，后泛指一切翻搅；客户流失义的 churn 是 20 世纪电信业的比喻。\",\"circulate\":\"来自拉丁语 circulare，源于 circulus「小圆圈」（circus 圆的指小形式）：沿着圆圈转回来，就是 circulate；circuit 同族。\",\"cite\":\"来自拉丁语 citare「唤起、传唤」，源于 ciere「使动、召唤」：法庭传唤、文中征引，都是把人或文「唤」到面前；excite（唤起兴奋）是同一召唤。\",\"civilize\":\"civil 源于拉丁语 civilis「公民的」，源于 civis「公民」：civilize 是把人带进「公民—城市」的秩序；city、civic、civilian 都围着 civis 这位公民。\",\"clamp\":\"中古英语，源于中古荷兰语、低地德语 klampe「夹具、钩」：把东西死死夹住就是 clamp；clamp down（取缔）是它的比喻。\",\"clap\":\"来自古英语 clæppan「拍打作响」，拟声色彩浓厚的日耳曼语词：双掌相击的那声响既是动作也是声音；a clap of thunder（一声霹雳）是同一下声响。\",\"clash\":\"拟声词，16 世纪出现：金属相撞的「哐当」就是 clash，后泛指冲突、不搭、撞期——凡是硬碰硬，都是这声响。\",\"clasp\":\"中古英语 claspen，来源不确，可能与日耳曼语「扣紧」词族（clip 的亲戚）有关：两手或扣件合拢扣死，就是 clasp；确切出身学界未定。\",\"classify\":\"法语 classifier 的构造：拉丁语 classis「等级、类别」+ facere「做」——classis 本是罗马按财产分的公民等级；classify 是把事物送进各自的等级格子。\",\"clatter\":\"古英语 clatrung 一脉的拟声词：硬物连串相击的「哗啦」就是 clatter，中古英语 clateren 已成形。\",\"cleanse\":\"来自古英语 clǣnsian「净化」，源于 clǣne「干净的」（clean）：cleanse 比 clean 多一层仪式感——涤罪、净化的「净」；clean 本人的更深来源不确。\",\"cleave\":\"英语里藏着两个相反的 cleave：古英语 clēofan「劈开」与古英语 cleofian「粘附」——劈开与粘牢同形，是著名的自反义现象；语境决定它站在哪一边。\",\"clench\":\"来自古英语 -clencan 一脉（见于 beclencan「扣紧」），与 cling、clamp 同属「抓牢」词族：牙关、拳头扣死不动，就是 clench。\",\"click\":\"拟声词，17 世纪进入英语：舌尖与开关的「咔哒」就是 click；计算机时代它成了最高频的动作之一。\",\"cling\":\"来自古英语 clingan「收缩、粘着、干枯」，本义含「缩成一团」：湿衣服缩贴在身上，就是 cling 的原形；后专指紧抓不放。\",\"clip\":\"英语里有两个 clip 合流：古英语 clyppan「拥抱、夹住」生出回形针义的 clip，古诺尔斯语 klippa「剪」生出剪辑义的 clip——夹与剪在现代英语里合成一个词。\",\"cloak\":\"经古法语 cloque「钟形斗篷」，源于中世纪拉丁语 clocca「钟」——斗篷展开如钟罩：披上它，人就没入夜色；cloak 作动词就是「用斗篷盖住」。\",\"clog\":\"中古英语 clogge「大木块」先行：拖在脚上的木块（木屐）引出「阻碍」义，再到管道里的堵塞；clog 的更深来源未定。\",\"clone\":\"希腊语 klōn「嫩枝、插条」：1903 年植物学家借它命名无性繁殖的植株——剪根嫩枝插活，就是一个 clone；后泛指一切复制品。\",\"clothe\":\"来自古英语 clāþian，源于 clāþ「布、衣」（cloth）：给身体披上 cloth，就是 clothe。\",\"clout\":\"来自古英语 clūt「一块布、补丁」，后指缠布的重击之物：一记重击是 clout，影响力是其比喻——一句话如重击的分量；更深来源不确。\",\"cloy\":\"源于古法语 encloyer 一脉（深层是拉丁语 clavus「钉子」）的缩略：甜到「钉住喉咙」就是 cloy；确切路径略有曲折，大方向是「腻到发堵」。\",\"clue\":\"clue 本是 clew「线团」的变体拼写：希腊神话里忒修斯靠阿里阿德涅的线团走出迷宫——顺着线走出谜团，就是 clue。\",\"clump\":\"源于中古低地德语 klumpe「一团、一块」：一丛草、一团土是 clump；表「沉重脚步声」的 clump 是拟声的另一条线，两者在现代合流。\",\"coagulate\":\"来自拉丁语 coagulare，源于 coagulum「使凝结之物」（com- 一起 + agere 驱动）：把分散的颗粒「驱到一处」就是凝固；注意词中的一段并不是「携带」义的 lat，旧式拆法常在此出错。\",\"coalesce\":\"来自拉丁语 coalescere「长合到一起」（com- + alescere 生长，源于 alere 滋养）：两滴水长成一滴、派系合成一派，就是 coalesce；alere 的「滋养」也藏在 alimentary（营养的）里。\",\"codify\":\"code（法典，拉丁语 codex 木片文书）加 -ify「使…化」：把散条文编成一部 codex，就是 codify；codex 的本义是钉在一起的木牍书。\",\"coerce\":\"来自拉丁语 coercere「围起、约束」（com- + arcere 围、关）：把自由「圈」起来强迫就范，就是 coerce；arcere 的「关」也在 arcanum（奥秘，关存之物）里。\",\"coexist\":\"co-（共同）+ exist；exist 源于拉丁语 exsistere「站出来、显现」（ex- + sistere 站）：两种事物「同场站着」，就是 coexist；sistere 的「站」与 resist、insist 同族。\",\"coil\":\"经古法语 coillir「收集、卷起」一脉，源于拉丁语 colligere「聚集」（com- + legere 拾、选）：把绳子一圈圈收拢就是 coil；collect 是它的近亲。\",\"coin\":\"经古法语 coin「楔子、模具」，源于拉丁语 cuneus「楔子」：楔形冲压模打在金属上，硬币就有了形；coin a phrase（造新词）是把新词也当硬币「铸」出来。\",\"collude\":\"来自拉丁语 colludere「一起玩、同谋」（com- + ludere 玩）：字面是「一起玩游戏」，玩的是见不得光的那种；prelude（前奏）、illusion（幻觉，本义被戏弄）同出 ludere。\",\"colonize\":\"colony 源于拉丁语 colonia「殖民定居点」，源于 colonus「农夫、拓殖者」（colere 耕种、居住）：罗马把退伍农兵安置到新地种田，就是 colonia；colonize 是种地起家的扩张。\",\"combat\":\"经法语 combattre，源于晚期拉丁语 combattere「打斗」（com- + battere 打）：battere 是 battle、battery 的祖先——combat 是面对面地「打」。\",\"combust\":\"来自拉丁语 comburere「烧尽」（com- 彻底 + urere 烧）：combust 是化学语境里的「烧起来」；它的名词是 combustion。\",\"commemorate\":\"来自拉丁语 commemorare「使共同记起」（com- 一起 + memor 记着的）：一群人把记忆聚到一处，就是 commemorate；memory、memoir 同出 memor「心记」。\",\"commend\":\"来自拉丁语 commendare「托付、举荐」（com- + mandare 委托）：把人郑重「托付」给好评，就是 commend；command（命令）、recommend（推荐）共享 mandare 这只「托付之手」。\",\"compact\":\"英语里有两个 compact 合流：形容词源于拉丁语 compactus「压紧的」（com- + pangere 钉牢）；名词「协定」源于 compactum「约定」（com- + pacisci 订约）——压紧与订约同形同词。\",\"conceptualize\":\"concept 源于拉丁语 conceptus「怀住的、构想的」，源于 concipere「怀上、构想」（com- + capere 抓、容纳）：把想法在脑中「怀成形」，就是 conceptualize；conceive 是它的动词本体。\",\"concoct\":\"来自拉丁语 concoquere「一起煮、熬制」（com- + coquere 煮）：本义是混煮与消化，引申为「熬」出一个借口；coquere 是 cook 的拉丁祖先。\",\"condemn\":\"来自拉丁语 condemnare「判罪」，源于 damnare「判罚」（damnum 损失、损害）：condemn 的 -demn- 里藏着 damn——判罚使人受损；damn 本人就是 damnare 的直系后代。\",\"condense\":\"来自拉丁语 condensare「使稠密」（com- + densus 稠密的）：把稀疏的压稠、把长文压短，都是 condense；density 是 densus 的名词后代。\",\"conduct\":\"来自拉丁语 conducere「带到一起、引领」（com- + ducere 引）：带队、指挥乐团、传导电流，都是「引」的变奏；duke（公爵）、duct（管道）同出 ducere。\",\"confess\":\"经古法语源于拉丁语 confessus，源于 confiteri「承认」（com- + fateri 承认、说）：把藏着的话说出口就是 confess；profess（公开宣称）是同一 fateri 的另一路。\",\"confiscate\":\"来自拉丁语 confiscare「收归国库」（com- + fiscus 国库、钱篮）：fiscus 本是皇帝装钱的篮子——confiscate 就是把私产装进公家的篮。\",\"confound\":\"经古法语源于拉丁语 confundere「倒在一起、搅乱」（com- + fundere 倒、熔）：把墨水与清水倒成一锅，就是 confound；注意这个 fund- 是「倒」，与 fund（基金，源于 fundus 底部）不是一回事。\",\"confront\":\"经法语源于中世纪拉丁语 confrontare「使额对额」（com- + frons 额头、前额）：额头抵着额头站到对面，就是 confront；front（前面）就是 frons 的后代。\",\"congratulate\":\"来自拉丁语 congratulari「同喜、致贺」（com- + gratulari 道贺，源于 gratus 令人愉快的）：与人同喜就是 congratulate；gratitude（感激）共享 gratus。\",\"conjure\":\"来自拉丁语 coniurare「共同发誓、密谋起誓」（com- + iurare 发誓）：先是结盟的誓，后成召神弄鬼的咒——conjure 的魔术是从「起誓」滑过去的；jury（陪审团，宣誓者）同出 iurare。\",\"conspire\":\"来自拉丁语 conspirare「同呼吸、共谋」（com- + spirare 呼吸）：头碰头、呼吸相闻地密谋，就是 conspire；spirit（精神，本义气息）同出 spirare。\",\"construe\":\"来自拉丁语 construere「堆建、构筑」（com- + struere 堆）：把词句的零件堆成意义，就是 construe（诠释）；construct、structure 共享 struere 这套「堆建」。\",\"contend\":\"来自拉丁语 contendere「绷紧、竭力争夺」（com- + tendere 拉伸）：弓弦绷满般地较量，就是 contend；tension 同出 tendere「拉」。\",\"contest\":\"来自拉丁语 contestari「呼唤见证、在证人前起诉」（com- + testari 作证，testis 证人）：官司要证人在场，比赛要观众作证——contest 从法庭走到了赛场；testament（遗嘱）出自同一证人席。\",\"contrive\":\"经古法语 controver「想出、编造」，更深来源有争议：contrive 的确切出身未定，「费尽心机拼凑出办法」的意味倒是自古稳定。\",\"converge\":\"晚期拉丁语 convergere「倾向一处」（com- + vergere 倾斜、趋向）：条条斜线倾到同一点，就是 converge；diverge 是反方向的同族词。\",\"converse\":\"来自拉丁语 conversari「与人相处、往来」，源于 convertere「转」：本义是「在人群里打转生活」，后专指交谈；convert（转变）是它的近亲。\",\"convey\":\"经古法语 convoier「护送同行」，源于通俗拉丁语 conviare「同行于途」（com- + via 路）：沿路把人货送到，就是 convey；voyage（航行）走的也是 via 这条路。\",\"convict\":\"来自拉丁语 convincere「以证据击败、证实有罪」（com- + vincere 征服）：法庭上的「征服」就是 convict；victory、invincible 共享 vincere。\",\"cordon\":\"法语 cordon「绳带、饰带」，源于 corde「绳」（拉丁语 chorda 弦、绳）：一圈绳索或一队人拉起的环，就是 cordon；cord、chord 都是 chorda 的后代。\",\"cork\":\"经荷兰语、西班牙语一带进入英语，源于西班牙语 alcorque「栓皮栎」，更早或与拉丁语 cortex「树皮」有关，路径细节有争议：软木就是栓皮栎的「树皮」，cork 由此得名。\",\"counsel\":\"来自拉丁语 consilium「商议、忠告」：出主意、做咨询，都是 counsel；它与 council（委员会，源于 concilium 集会）拼写相近却是两个词，是考试常设的陷阱。\",\"counter\":\"两个来源在 counter 里合流：作「反着来」讲源于拉丁语 contra「相对」；作「柜台」讲源于中世纪拉丁语 computatorium「算账处」（computare 计算）——反击与柜台同住一词。\",\"covet\":\"经古法语 coveitier，源于拉丁语 cupiditas「渴望」（cupere 渴求）：对别人的东西起了「想要」的心，就是 covet；丘比特 Cupid 的名字就是 cupere 的拟人化。\",\"crack\":\"来自古英语 cracian「发出爆裂声」，是拟声的日耳曼语词：冰面、骨头、密码——crack 的一声脆响贯穿了它所有义项，连「破译」都是敲开硬壳。\",\"cradle\":\"来自古英语 cradol「摇篮」，来源细节不确，或与篮筐（crate）一族有关：文明的 cradle（发源地）就是文明的摇篮；cradle 的更深出身学界未定。\",\"cram\":\"来自古英语 crammian「塞满」，是日耳曼语老词：把东西硬压进有限空间，就是 cram；考前 cramming 是把知识也这样塞进脑子。\",\"cramp\":\"中古英语 crampe「痉挛、夹钳」，源于古法语 crampe（日耳曼语借词，kramp 弯钩、痉挛）：肌肉「被钩住」般抽紧，就是 cramp；夹具义与它同源。\",\"crane\":\"来自古英语 cran「鹤」：长腿长颈的鸟直接给了名字——起重机 crane 是近代因形似鹤而得名，机器借了鸟的名。\",\"crave\":\"来自古英语 crafian「要求、索取」，是日耳曼语老词：本是理直气壮的「讨要」，后软化为强烈的渴望；crave 的胃口里带着讨要的执拗。\",\"creak\":\"中古英语 creken，拟声词，模拟乌鸦叫与木头的摩擦声：老地板的「嘎吱」就是 creak，与 croak（呱呱叫）是同一拟声家族。\",\"crease\":\"来源不确，可能与 crest（鸡冠、顶部）一族有关：布上压出的一道「脊」就是 crease；确切出身学界未定，crease 先作名词（折痕线）、后作动词。\",\"creep\":\"来自古英语 crēopan「爬行」，是日耳曼语老词：贴地慢行是本义，后长出「悄悄逼近」「令人发毛（creepy）」诸义——都从贴地的慢动作来。\",\"crest\":\"经古法语 creste，源于拉丁语 crista「鸡冠、头饰」：鸡冠立在头顶——山脊、浪尖、纹章，都是各处的「鸡冠」。\",\"crib\":\"来自古英语 crib「牲口棚、食槽」：婴儿床沿用棚栏之形；美式俚语 crib（住所）与考试小抄 crib 的来历细节有争议，源头都是那只食槽。\",\"cringe\":\"来自古英语 cringan「在战斗中倒下、蜷缩」，本义含「屈服倒地」：恐惧时身体先「倒下式」地一缩，就是 cringe；现代「尴尬到缩起来」的用法接得上这条古义。\",\"cripple\":\"来自古英语 crypel「爬行者」，与 creep 同族：腿伤者以爬行代步，故名 cripple；今多用于抽象事物（重创经济），指人时已属冒犯，须避用。\",\"crop\":\"来自古英语 cropp「一簇、一串；鸟的嗉囊；植物的顶头」：庄稼最顶上结实的那一截就是收成；裁剪（剪去边角）义也从『取顶、截取』来。德语 Kropf（嗉囊）是同根亲戚。\",\"crouch\":\"中古英语 crouchen，出处不确：可能与古法语 croche「钩子」一族（crook 弯钩）有关——身子蜷得像只钩；确切来源学界未定，不硬拆。\",\"crystallize\":\"crystal 来自希腊语 krystallos「冰、透明冰晶」（源 kryos「严寒」），经拉丁语 crystallus 进入英语：古罗马人以为水晶是冻得再也化不开的冰；crystallize 就是『结成冰晶那样规整有序的固体』，想法『结晶成形』是它的比喻义。\",\"cub\":\"16 世纪才见于记载，出处不明：可能来自斯堪的纳维亚语或爱尔兰语对幼兽的俗称；学界无定论，整体认读即可。\",\"pupil\":\"两个同形词合流：『学生』义来自拉丁语 pupillus「孤儿、受监护的孩子」（pupus「小男孩」的小称）；『瞳孔』义来自拉丁语 pupilla「小娃娃、小人偶」——照镜子时瞳孔里映出的小小人影，就是它得名的原因。\",\"iris\":\"来自希腊语 iris「彩虹」，也是彩虹女神伊里斯之名：虹膜的颜色千人千样（蓝、棕、灰、绿），鸢尾花的花色同样缤纷，两者都借了彩虹的名字。\",\"cornea\":\"来自拉丁语 cornea「角质的（膜）」，源 cornu「角」（与 horn 同源）：眼球前部这层透明膜质地像薄角片，古罗马解剖学家就称它『角质层』——corn- 是『角』，不是 co- 前缀。\",\"retina\":\"来自中世纪拉丁语 retina，多认为源于拉丁语 rete「网」：视网膜上血管密布如网，得名于此——ret- 是『网』，不是 re- 前缀。\",\"nostril\":\"地道的古英语合成词：nosu「鼻子」+ thȳrel「孔洞」（源 thurh「穿过」）——字面就是『鼻子上的洞』，与拉丁词根无关，是日耳曼语自家造的词。\",\"cheek\":\"来自古英语 cēace「下颌、面颊」，是日耳曼语老词：本指下颌一带，后专指脸蛋；cheeky『厚脸皮的』由此引申。\",\"chin\":\"来自古英语 cin「下巴」，与德语 Kinn 同源，再往上可溯至印欧语 *ǵenu-「颌」：希腊语 genys（颌）、拉丁语 gena（脸颊）都是同根亲戚。\",\"jaw\":\"中古英语 jawe，出处不确：可能来自古法语 joue「面颊」；确切来源学界未定，整体认读。\",\"lip\":\"来自古英语 lippa「嘴唇」，是日耳曼语老词，与德语 Lippe 同源，可能与拉丁语 labium「唇」同出印欧语『松垂之物』一根——嘴唇松松地垂在口边。\",\"tongue\":\"来自古英语 tunge「舌头」，再往上是印欧语的老词：拉丁语里它先写作 dingua，后被 lingua 取代（法语 langue、linguistics 语言学由此来）——舌头即语言，是印欧人共同的比喻。\",\"tooth\":\"来自古英语 tōth，源印欧语 *h₃dónts「牙」：拉丁语 dens、希腊语 odous 都是同根亲戚（dentist 牙医由此来）；复数 teeth 的元音变化（oo 变 ee）是古英语留下的老规矩。\",\"throat\":\"来自古英语 throte「喉咙」，是日耳曼语老词，可能与 throttle「勒喉、节流阀」同族：喉咙就是声音与食物共用的那条要紧通道。\",\"neck\":\"来自古英语 hnecca，本指『脖子后部』，是日耳曼语老词（德语 Nacken 后颈同源）：后泛指整个脖子；瓶子的细口也沿用此名，bottleneck（瓶颈）由此来。\",\"shoulder\":\"来自古英语 sculdor「肩」，是日耳曼语老词（德语 Schulter 同源），再往前的来源不确：整体认读；它和 should（应该）毫无关系，别被拼写骗了。\",\"elbow\":\"古英语合成词：eln「前臂、肘尺」（与拉丁语 ulna 尺骨同源）+ boga「弓、弯曲」（bow 的亲戚）——字面就是『手臂的那道弯』。\",\"wrist\":\"来自古英语 wrist，源 wrīthan「扭转」（writhe 扭动同族）：手腕是手能扭转的关节；wreath（花环，扭编而成）也是这一家的。\",\"palm\":\"来自拉丁语 palma：它在拉丁语里同时指『手掌』与『棕榈』——棕榈叶摊开如手掌，两义本是一词，经古法语 paume 把『手心』义带进英语。\",\"thumb\":\"来自古英语 thūma「拇指」，源印欧语 *tum-「肿、粗大」（拉丁语 tumere 肿胀同源）：五指里最粗壮的那一根，就叫『粗大的手指』。\",\"chest\":\"来自拉丁语 cista「箱子、柜」（希腊语 kistē），经古英语借入：先指带盖的箱柜，后指装着心肺的『胸腔』——家具与身体共用一个『箱子』，藏宝箱也叫 chest。\",\"breast\":\"来自古英语 brēost「胸、乳房」，是日耳曼语老词，可能与『发胀、隆起』一根有关（取胸部隆起之形）；鸟类的胸脯、鸡胸肉（chicken breast）都沿用它。\",\"waist\":\"中古英语 waste，多认为与古英语 weaxan「生长」有关（wax『长大』在 wax and wane 里还留着），指躯干中段；确切路径学界尚有争议，常见说法是『身体的中段、最细的一圈』。\",\"thigh\":\"来自古英语 thēoh「大腿」，是日耳曼语老词，可能源印欧语 *teuk-「肿、厚」：大腿是腿上最粗厚的一段，名字取的就是这份『粗厚』。\",\"knee\":\"来自古英语 cnēo「膝」，源印欧语 *ǵónu「膝」：希腊语 gonu、拉丁语 genu（genuflect 跪拜由此来）都是同根亲戚——『膝』是印欧语里很稳的一个老词。\",\"shin\":\"来自古英语 scinu「胫、小腿前部」，是日耳曼语老词：指膝下那根贴皮长骨（胫骨）所在的一面，皮薄骨硬，所以磕碰最疼。\",\"toe\":\"来自古英语 tā「脚趾」，是日耳曼语老词（德语 Zehe 同源），再往前的来源不确：整体认读即可。\",\"sole\":\"表『脚底、鞋底』的 sole 来自拉丁语 solea「凉鞋、鞋底」（源 solum「地面」）：贴地的那一片就是 sole，比目鱼 sole 也因形似鞋底得名。而表『唯一的』sole 来自拉丁语 solus，是另一个同形词——两者同形异源，别混为一谈。\",\"scalp\":\"中古英语 scalp，可能借自斯堪的纳维亚语，指颅顶一带，出处未完全定论：先记『覆盖头顶的那层皮』即可。\",\"pelvis\":\"来自拉丁语 pelvis「盆、浅盆」：文艺复兴时期的解剖学家看这圈骨头形如一只盆，直接拿『盆』命名——骨盆的字面就是『盆』。\",\"intestine\":\"来自拉丁语 intestinus「内部的」（intus「在里面」）：intestina 在拉丁语里泛指内脏，英语专取肠道——它是最具代表性的『里面的器官』；中间的 test 只是字母巧合，与 test（考试）无关。\",\"stomach\":\"来自希腊语 stomachos「喉咙、食道口、胃」，源 stoma「嘴、口」，经拉丁语 stomachus、古法语 estomac 进入英语：胃是食物之『口』；动词『忍受』义（can't stomach it）是『咽得下、消化得了』的比喻。\",\"bladder\":\"来自古英语 blǣdre「囊、膀胱」，与 blāwan「吹」（blow）同族：膀胱就是一只可充气胀大的囊——鱼鳔、球胆（气囊）在英语里也叫 bladder。\",\"pancreas\":\"来自希腊语 pankreas：pan「全部」+ kreas「肉」——『全是肉』：这条腺体通体是均匀的软组织，古希腊解剖学家就这样直白地命名它。\",\"spleen\":\"来自希腊语 splēn「脾」，经拉丁语、法语进入英语：古希腊医学把忧郁、怒气归给脾，所以 vent one's spleen 是『发泄怒气』，算是西洋版的『脾气』。\",\"diaphragm\":\"来自希腊语 diaphragma「隔墙、隔膜」：dia「横过」+ phragma「栅栏、围墙」——横在胸腔与腹腔之间的那道『墙』；相机光圈同名，也是开合的一道隔片。\",\"trachea\":\"来自希腊语 trakheia (artēria)「粗糙的（管道）」：气管壁上一节节软骨环摸起来粗糙，古希腊人就以『粗糙管』称之，经中世纪拉丁语进入英语；日常口语叫 windpipe。\",\"bone\":\"来自古英语 bān「骨」，是日耳曼语老词，再往前的来源不确：bonfire（篝火）最早写作 bone-fire，是字面意义上『烧骨头的火』。\",\"marrow\":\"来自古英语 mearg「髓」，与德语 Mark、俄语 mozg（脑）同源，出印欧语 *mosgʰo-「髓、脑」：骨头最里面的软芯，引申为事物的精髓（chilled to the marrow 冷到骨子里）。\",\"pore\":\"来自希腊语 poros「通道、孔道」，经拉丁语 porus 进入英语：poros 与『渡过』同根（ford 浅滩、ferry 渡船是亲戚）——毛孔就是皮肤上的一条条微型通道；动词 pore over（埋头钻研）是『凑近细看』的引申。\",\"sweat\":\"来自古英语 swāt「汗」，源印欧语 *sweyd-「出汗」：拉丁语 sudor（汗）、希腊语 hidros 是同根亲戚（sudorific 发汗的由此来）。\",\"tear\":\"表『眼泪』的 tear 来自古英语 tēar，源印欧语 *dáḱru-「泪」：希腊语 dakry、拉丁语 lacrima（由 dacruma 变来）都是同根亲戚。它与『撕裂』的 tear（古英语 teran）同形同拼，但读音与来源都不同。\",\"saliva\":\"来自拉丁语 saliva「唾液、口水」，再往前的来源不确：它是医学正式词，日常口语多说 spit，唾液腺是 salivary gland。\",\"mucus\":\"来自拉丁语 mucus「黏液、鼻涕」，可能与希腊语 myxa「黏液」有关：名词是 mucus，形容词 mucous membrane（黏膜）只多一个字母，别写混。\",\"blood\":\"来自古英语 blōd「血」，是日耳曼语老词，更早来源不确：有趣的是 bless（祝福）源古英语 blētsian『以祭祀之血祝圣』，正与 blood 同出一门。\",\"assorted\":\"sort 来自拉丁语 sors「签、命运、类别」，经古法语 sorte 进入英语：assorted = 把各个『类别』都配齐的什锦（ad- + sort）；sors 也是 sorcery（巫术，源 sortilegium『抽签占卜』）的祖先。\",\"astonished\":\"astonish 来自古法语 estoner「震得发懵」，源拉丁语 *extonare：ex- + tonare「打雷」（thunder 的拉丁亲戚）——『像被雷劈中一样懵住』，与 astound 同出一家。\",\"astounding\":\"astound 出自中古英语 astoned，是 astonish 的旧过去分词：根子同样是拉丁语 tonare『打雷』——『惊人』在词源里就是『雷击级』的震撼。\",\"athletic\":\"来自希腊语 athlētikos，源 athlētēs「参赛者」，再源 athlon「竞赛的奖品」与 athlos「角逐、苦战」：为奖品而拼命角逐的人，就是 athlete（运动员）。\",\"atrocious\":\"来自拉丁语 atrox「凶残的、可怖的」：多认为含 ater「黑、黯」一根，有『面目黝黑可怖』之貌；atrocity（暴行）是它的名词亲戚。\",\"attentive\":\"attend 来自拉丁语 attendere：ad-「朝向」+ tendere「伸展」——把心思『伸向』对方，就是专注与照料；attentive 是这种状态成了习惯。\",\"attractive\":\"来自拉丁语 attrahere：ad-「朝向」+ trahere「拉、拖」（tractor 拖拉机同根）——能把目光与好感『拉过来』的，就是 attractive。\",\"audible\":\"来自晚期拉丁语 audibilis，源 audire「听」（audience 听众、audio 音频同根）：『听得见的』；-ible 表『能够被…』，inaudible 是它的反义。\",\"authentic\":\"来自希腊语 authentikos，源 authentes「亲手做事者、当家人」：autos「自己」+ hentes「做者」——出自本人之手、不是他人代笔假造的，就是『真迹、正宗』。\",\"authoritative\":\"authority 来自拉丁语 auctoritas，源 auctor「创始者、作者」，再源 augere「使生长、增益」（augment 扩大同根）：说话能『长出后果』、有分量的人，才有权威。\",\"autonomous\":\"来自希腊语 autonomos：autos「自己」+ nomos「法则、法律」（economy 里 -nomy 同根）——『自己给自己立法』，就是自治、自主。\",\"averse\":\"来自拉丁语 aversus：ab-「离开」+ vertere「转」（vers 转）——『把身子转开、避之不及』就是厌恶。注意它与 adverse 相反：adverse 是 ad-「朝向」+ 转，『迎面转来相对』，故为『不利的』。\",\"aware\":\"来自古英语 gewær：ge- + wær「警觉的、留神的」，与 wary（谨慎的）、ward（守卫）同出日耳曼语『看护、察觉』一根——『意识到』，就是警觉上线。\",\"awkward\":\"中古英语合成词：awk「别扭的、反着的」（源古诺尔斯语 afugr『转错方向的』）+ -ward「朝向」——『朝别扭方向去的』，就是笨拙、尴尬；awk 本身就是一个『反着来』的词。\",\"awful\":\"awe 来自古诺尔斯语 agi「惊惧、敬畏」，是日耳曼语老词：awful 原指『令人敬畏的』（多指神），后一路贬义漂移成『糟糕透顶』；awfully 作『非常』讲，是这条线的余波。\",\"balanced\":\"balance 来自拉丁语 bilanx：bi-「二」+ lanx「盘子」——天平的两只盘，经古法语 balance 进入英语；balanced 就是两端对等、不偏不倚的状态。注意：这里的 bi- 才是真『二』。\",\"banal\":\"来自法语 banal，源中世纪封建用语 ban「领主敕令」：领主的磨坊、烤炉是领地内『被规定必须人人共用的』——共用即平常，平常再走一步，就是陈腐、平庸。\",\"barbaric\":\"来自希腊语 barbaros「外国的、不懂希腊语的」：希腊人听外族说话只像『bar-bar』的含混声，拟声起家，后引申为『未开化、野蛮』（barbarian 野蛮人同族）。\",\"bashful\":\"bashful = bash（abash『使羞怯』的缩短形）+ -ful：abash 来自古法语 esbahir『惊得张口结舌』——羞得只想往回缩，就是 bashful，比 shy 多一层局促。\",\"basic\":\"base 表『根基、底座』义来自拉丁语 basis、希腊语 basis「底座、踏步」（bainein『迈步』）：basic 就是『打底的、最基础的』。化学里的『碱』base 是另一条法语线（bas『低』），只是拼写合流。\",\"bearable\":\"bear『忍受、承载』来自古英语 beran，源印欧语 *bher-「携带」：拉丁语 ferre、希腊语 pherein 同根（transfer 转移、peripheral 的亲戚都属此族）——bearable 就是『扛得住、忍得下』。\",\"believable\":\"believe 来自古英语 gelēafa「信念」：be- + 日耳曼语 *galaub-『珍重、信赖』一根，与 love（爱）、lief（乐意）同族——『信』在古英语里本是『放在心上珍重』。\",\"beloved\":\"love 来自古英语 lufu，源印欧语 *leubh-「爱、渴望」（拉丁语 lubet『乐意』、libido 同根）：beloved = be- + loved，『被深深爱着的』；作名词时指心爱之人。\",\"beneficial\":\"来自拉丁语 beneficus「行善的、给人好处的」：bene「好地」+ facere「做」（-fic 做）——『做出好处来的』，与 benefit（益处）、benefactor（恩人）是一家人。\",\"benevolent\":\"来自拉丁语 benevolens：bene「好地」+ volens「意愿着的」（velle『想要』，volunteer 志愿者同根）——bene- 是善，vol 是愿，合起来是『心怀好意』。\",\"bent\":\"bend 来自古英语 bendan，本义『把弓弯起来、上紧弦』，是 bindan「捆绑」的使役形式——弦绑紧则弓弯；bent on doing something『铁了心要做』，就是弓已上弦、非发不可。\",\"berserk\":\"来自古诺尔斯语 berserkr：多解作 ber-「熊」+ serkr「衫」——披熊皮作战的北欧狂战士，临阵癫狂；另有『赤膊衫』一说，未定。go berserk（暴怒失控）即源于此。\",\"besides\":\"beside 来自古英语 be sīdan『在旁边』：besides 多出的 -s 是古英语副词性属格词尾（always、towards 同款）——『在旁边再添上』，就是『此外、而且』；与 beside（在旁边）只差这一个 s。\",\"bewildered\":\"bewilder 是 17 世纪造词：be- + wilder「领入迷途」，wilder 源自 wilderness「荒野」；而 wilderness 本是 wild『野』+ deor『野兽』（deer 的古义）+ -ness——『野兽出没之地』，迷失其中就是 bewildered。\",\"biased\":\"bias 来自法语 biais「斜的、斜向」，更早来源不确：由滚木球游戏里『偏重一边使球走偏』引申为『偏见』；注意开头的 bi 不是数字『二』，别拆成 bi- 前缀。\",\"biblical\":\"Bible 来自希腊语 ta biblia『（那）些书』：biblion 源 byblos「纸莎草」——黎巴嫩的比布鲁斯（Byblos）港是古代纸莎草集散地，材料产地之名变成了『书』本身；bibl- 是『书』，不是 bi-『二』。\",\"bigoted\":\"bigot 来自法语 bigot，出处未定：流传的『诺曼人誓言 by God』一说只是民间传说，无实证，不当定论；记『偏执者』即可，开头的 bi 也不是『二』。\",\"bilingual\":\"来自拉丁语 bilinguis：bi-「二、双」+ lingua「舌头、语言」（lingu 语言）——这回的 bi- 才是真『二』：两条『舌头』，两种语言；trilingual 是三语。\",\"binding\":\"bind 来自古英语 bindan「捆绑」，源印欧语 *bhendh-「绑」（band、bond、bundle 同族）：binding 是『像被绳子绑住一样逃不掉的』义务，故为『有约束力』（legally binding）；开头的 b 不属于 bi- 前缀。\",\"biodegradable\":\"20 世纪新造词（约 1961 年见录）：bio-（希腊语 bios『生命』）+ degrade（拉丁语 degradare『逐级降下来』，de- + gradus『台阶、等级』）+ -able——能被微生物『逐级拆解』掉的。\",\"bitter\":\"来自古英语 biter「咬人的、刺痛的」，源 bitan「咬」（bite 同族）：苦味像在咬舌头，后引申到刺骨的冷（bitter cold）与激烈的怨恨；开头的 bi 不是『二』。\",\"bizarre\":\"经法语 bizarre，源意大利语 bizzarro「易怒的、乖张的」，更早出处未定（有巴斯克语 bizarra『胡须』一说，未获证实）：整体认读，开头的 bi 不是『二』。\",\"blameless\":\"blame 来自拉丁语 blasphemare「亵渎、指责」，源希腊语 blasphemein（blasphemy 亵渎是同根亲戚），经古法语 blasmer 进入英语：blame 与『亵渎』原是同一个词，blameless 就是『无可指责』。\",\"bland\":\"来自拉丁语 blandus「光滑的、讨好的、柔和的」：本是褒义的『温润动人』，进入英语后先指温和，再滑向『淡而无味、平淡』，一路褒贬漂移。\",\"blank\":\"来自古法语 blanc「白色的」，源日耳曼语 *blank-「发亮、洁白」（法兰克语）：白纸无字是 blank，空白支票、脑子一片空白（go blank）都从『白』来。\",\"blatant\":\"1596 年诗人斯宾塞在《仙后》中造出 blatant（形容喧闹不休的巨兽 Blatant Beast），可能取材拉丁语 blatire「喋喋不休地嚷」：出处带造词色彩，记『吵嚷得毫不掩饰、明目张胆』即可。\",\"bleak\":\"来自古诺尔斯语 bleikr「苍白的」，与 bleach（漂白）同出日耳曼语『发白、发亮』一根：颜色褪尽之地就是荒凉，bleak prospects 是『黯淡的前景』，狄更斯《荒凉山庄》原名即 Bleak House。\",\"blessed\":\"bless 来自古英语 blētsian，本义『以祭祀之血祝圣』，源 blōd「血」（blood）：基督教时代语义转为『赐福、使幸福』——blessed 的祝福里，藏着一段古代血祭史。\",\"blind\":\"来自古英语 blind「失明的」，与 blend（混杂）、blunder（踉跄犯错）同出印欧语 *bhlendh-「浑浊不清」一族：看不清、辨不明，就是这一根的共同主题。\",\"blissful\":\"bliss 来自古英语 bliss/blīths「欢欣」，与 blithe（愉快）同族：blissful 是『福乐满溢』；它和 bless（祝福）只是音近，常被误认同源，其实各走各的词源路。\",\"bloody\":\"blood（古英语 blōd，血）+ -y：字面义『流血的、血腥的』是本分；英式口语里 bloody 作加强语气词（带粗口色彩），其来源有『by our Lady』缩略等说法，属未定之论。\",\"blooming\":\"bloom 来自古诺尔斯语 blóm「花」，与古英语 blōstma（花朵）、拉丁语 flos（花，flower 的祖先）同出印欧语 *bhleh₃-「开花」：blooming 就是『正值盛放』，也可指气色旺盛。\",\"blunt\":\"中古英语 blont，出处不明，可能来自斯堪的纳维亚语：先记『钝、不锋利』——刀口钝了不切物，引申说话『钝直不绕弯』（to be blunt 是『坦白说』）。\",\"blurred\":\"blur 16 世纪才出现，出处不明（可能与 blear『使视线模糊』有关）：blurred 就是『轮廓化开了的、模糊的』，整体认读，不硬拆。\",\"boastful\":\"boast 出中古英语 bost，出处不明（可能拟声，或源盎格鲁-法语）：boast 本可中性作『引以为豪』，加 -ful 的 boastful 则是贬义的『满口大话、自吹自擂』。\",\"boiling\":\"boil『煮沸』来自拉丁语 bullire「冒泡」，源 bulla「水泡、气泡」，经古法语 boillir 进入英语：水冒泡翻滚就是 boil。注意皮肤上的『疖』boil 是另一个词（古英语 bȳl 肿块），同形异源。\",\"bold\":\"来自古英语 beald「勇敢的」，是日耳曼语老词（古诺尔斯语 ballr 同源）：敢于凸显——粗体字 bold、醒目的 bold colors，也是这股『敢冒头』的气势。\",\"bolted\":\"bolt 来自古英语 bolt，本指弩箭、短箭，是日耳曼语老词：门闩、螺栓都因形似短箭得名；bolted 就是『被门闩或螺栓固定死的』。bolt 作动词『夺门而逃』是另一转义，靠语境分。\",\"bonded\":\"bond 是 band 的变体，同源古诺尔斯语 band「捆绑之物」：bonded 是『被纽带牢牢连成一体』——化学键的结合、保税仓库的海关担保，都是『绑定』在不同领域的落点。\",\"bony\":\"bone（古英语 bān，骨）+ -y『多…的』：bony 就是『骨头突显的』——瘦到见骨，或骨头多（bony fish 硬骨鱼是生物学分类词）。\",\"bookish\":\"book 来自古英语 bōc：常认为与 bēce「山毛榉」同源——日耳曼人曾把文字刻在山毛榉木片上；bookish = book + -ish『…气的』，满身书气、偏于纸上谈兵，略带贬义。\",\"booming\":\"boom 是拟声词，模仿隆隆巨响（荷兰语 bommen 同类）：生意『轰隆隆地爆起来』就是 booming；baby boom（婴儿潮）里的 boom，也是这声『轰』的爆发感。\",\"boorish\":\"boor 来自荷兰语 boer「农民」（与德语 Bauer 同源；neighbour 里的 -bour 古时也是『农民、住户』）：城里人嫌乡下人粗鲁，boor 就成了『粗人』，boorish 是『粗野无礼』。\",\"boosted\":\"boost 19 世纪见于美国英语，出处不明：先记核心画面『从后面、从下面向上托一把』——booster 是助推器、加强针，boosted 就是被托高、被增强后的状态。\",\"borderline\":\"border 来自古法语 bordure，源法兰克语 *bord「边、木板」（本指船舷之板）；line 来自拉丁语 linea「亚麻线」（linum 亚麻）：borderline 就是『贴着边界线的』，归类两难、临界。\",\"bored\":\"bore『使厌烦』18 世纪才出现，出处未定（一说与法语 bourrer『塞满、使厌腻』有关，一说借 bore『钻孔』打比方）：词源存疑，记『被单调磨得没了脾气』即可；它表人的感受，事的性质用 boring。\",\"boring\":\"与 bored 同出 bore『使厌烦』（出处未定）：boring 是事物本身的性质——单调得令人发闷；与表人感受的 bored 成对出现（a boring lecture 让人 bored），别混用。\",\"bossy\":\"boss『老板』来自荷兰语 baas「主人、师傅」，随荷兰移民带进纽约英语：bossy = boss + -y『多…的』，爱摆老板架子、发号施令，多含贬义。（牧场上唤牛的 boss 是另一个词，与此无关。）\",\"sergeant\":\"来自古法语 sergent「仆人、侍从」，源头是拉丁语 serviens「服侍者」。中世纪时指领主的武装侍从，后来固定为军衔名。\",\"comrade\":\"来自西班牙语 camarada「同住一室的人」，源头是拉丁语 camera「房间」——同住一个营房的人，就是战友。\",\"trilogy\":\"来自希腊语 trilogia：tri-「三」+ logos「言说、作品」。古希腊戏剧节上，悲剧演员要连演三部相关剧目。\",\"conscience\":\"来自拉丁语 conscientia「共同知晓、内心自知」：con-「共同」+ scire「知道」——像有个知情者住在心里，看着你做事。\",\"mosaic\":\"来自中世纪拉丁语 mosaicus，与「缪斯（Muses）」有关——这种镶嵌工艺被认为精美得像是缪斯女神的作品。\",\"tremendous\":\"来自拉丁语 tremendus「令人发抖的」，与 tremble「颤抖」同源——大到让人发抖，就是 tremendous。\",\"tyrant\":\"来自希腊语 tyrannos「专制君主」。在古希腊早期这个词未必是贬义，后来才专指残暴滥权者。\",\"extinguish\":\"来自拉丁语 extinguere「彻底刺灭、弄熄」：ex-「出」+ stinguere「刺」。与 extinct「灭绝的」同源。\",\"lagoon\":\"来自意大利语 laguna，源头是拉丁语 lacuna「池塘、空缺」，与 lake 同源。威尼斯泻湖就是最有名的 lagoon。\",\"dispatch\":\"来自意大利语 dispacciare「快速办妥」，经西班牙语进入英语。dis- 在这里不是「否定」，而是「迅速处理掉手头的事」。\",\"climax\":\"来自希腊语 klimax「梯子」，原指修辞上层层递进的手法，后来专指情节的最高点。\",\"tolerance\":\"来自拉丁语 tolerantia「忍耐、承受」，词根 tolerare 意为「背负、忍受」——宽容就是愿意背起不合己意的东西。\",\"amnesia\":\"来自希腊语 amnesia「遗忘」：a-「不」+ mnasthai「记得」。与 memory、mnemonic 同出一个词族。\",\"cardiac\":\"来自希腊语 kardiakos「心脏的」，词根 kardia 就是「心」——cardiology（心脏病学）、cardiogram（心电图）都是它的亲戚。\",\"canine\":\"来自拉丁语 caninus「狗的」，词根 canis 就是「狗」——constellation Canis Major（大犬座）也源于此。\",\"underscore\":\"under + score「刻痕」构成：score 借自古诺斯语 skor「刻痕、二十」。在字下划线强调的，就是 underscore。\",\"commonsensical\":\"common sense 是拉丁语 sensus communis「共同感觉」的译借：古人认为人人共有一份判断感官。再加 -ical。合乎这份人人共有的感觉的，就是 commonsensical。\",\"huffy\":\"huff 来源不完全确定：可能是拟声词，模仿气鼓鼓的喘气声；再加 -y。一碰就气鼓鼓的，就是 huffy。如实标注。\",\"birthright\":\"birth + right 构成的古老复合词。《创世记》里以扫卖掉的正是 birthright——生为长子天然享有的那份权利。\",\"lumpish\":\"lump 来源不完全确定：中古英语 lumpe，可能源自斯堪的纳维亚语或低地德语（与丹麦语 lumpe 一说）；再加 -ish。笨重成团的，就是 lumpish。如实标注。\",\"pitiful\":\"pity 来自拉丁语 pietas「虔诚、怜悯」，经古法语 pité 进入英语；再加 -ful。让人怜的，就是 pitiful；与 piety（虔诚）同根。\",\"paternal\":\"来自拉丁语 paternus「父亲的」，源头 pater「父亲」。父亲般的，就是 paternal；与 pattern（模范，原也是 pater 的后代）同根。\",\"byline\":\"by- + line 构成的报业词：印在标题旁、署着作者名字的那一行，就是 byline。\",\"tinge\":\"来自拉丁语 tingere「染、浸」。染上一点色的，就是 tinge；与 tint 同根。\",\"foxy\":\"fox + -y：像狐狸一样狡黠的，就是 foxy；后也指性感迷人。\",\"shaggy\":\"shag 来源不完全确定：古英语 sceacga「粗毛」，借自古诺斯语 skegg「胡须」一系；再加 -y。毛乱蓬蓬的，就是 shaggy。如实标注。\",\"rearrange\":\"re- + arrange「排列」构成：重新排过的，就是 rearrange。\",\"breakage\":\"break（古英语 brecan「打破」）+ -age「结果」。打碎之后的那堆损失，就是 breakage。\",\"paralytic\":\"paralysis 来自希腊语 paralysis「瘫痪」：para- + lysis「松开」（lyein「解开」）——肢体「解」了劲。瘫掉的，就是 paralytic。\",\"jealousy\":\"jealous 来自古法语 jalous，源头是通俗拉丁语 *zelosus，其根是希腊语 zēlos「热忱、嫉妒」。热忱过了头怕失去，就是 jealousy；与 zeal（热忱）同根。\",\"accomplished\":\"accomplish 来自古法语 acomplir，源头是拉丁语 complere「填满」：com-「完全」+ plere「满」。把事情填满做到头，就是完成；形容人则是技艺已「满」。\",\"overkill\":\"over- + kill 构成的冷战时期词（先指核武器的过量杀伤）：杀过头的，就是 overkill（过犹不及）。\",\"banditry\":\"bandit 来自意大利语 bandito「被放逐者、歹徒」，源头 bandire「宣告放逐」，其根是日耳曼语 *bann「公告、禁令」；再加 -ry「行当」。被官方「公告放逐」的人聚成的行当，就是匪帮活动；与 ban（禁止）同根。\",\"innocence\":\"innocent 来自拉丁语 innocens「无害的」：in- + nocens「有害的」（nocere「伤害」）。没害过人、没沾过罪的，就是 innocence；与 nuisance（滋扰）同根。\",\"truant\":\"来自古法语 truant「流浪汉、懒汉」，其更深来源可能与凯尔特语（威尔士语 truan「可怜人」）有关。逃学的人，就是 truant。如实标注。\",\"unleash\":\"un-「解开」+ leash「牵绳」构成。leash 来自古法语 laisse，源头是拉丁语 laxus「松的」——松开绳。把狗与怒火放开的，就是 unleash。\",\"biographical\":\"biography 是希腊语拼合词：bios「生命、生平」+ graphia「书写」（graphein「写」），经晚期拉丁语、法语进入英语。写一个人一生的，就是传记类的 biographical。\",\"characteristic\":\"character 来自希腊语 kharaktēr「刻印的标记」，源头 kharassein「刻、划」，经拉丁语、法语进入英语。刻在一个人身上的印记，就是 characteristic。\",\"nibble\":\"来源不完全确定：中古英语 nebel、nyble，可能源自低地德语 nibbelen「小口咬」，带拟声色彩。一点点啃的，就是 nibble。如实标注。\",\"demoralize\":\"经法语 démoraliser 而来：本义是「摧毁 morale（士气）」——morale 源头是拉丁语 moralis「道德的、精神的」。士气被抽掉，就是 demoralize。\",\"dissatisfactory\":\"dis-「不」+ satisfactory「令人满意的」：satisfy 源头是拉丁语 satisfacere「使满足」：satis「足够」+ facere「做」。做得不够的，就是 dissatisfactory。\",\"slippery\":\"slipper 是古英语 slipor「滑的」，源头 slīpan「滑动」；再加 -y。抓不住的地面与人，都是 slippery。\",\"blockish\":\"block + -ish「…似的」：像木墩一样方头方脑、迟钝，就是 blockish。\",\"innards\":\"innard 是 inward「内部的」方言变体（-ward「向内」）。肚子里面的那一堆，就是 innards。\",\"improper\":\"im-「不」+ proper「得体的」：proper 来自拉丁语 proprius「自己的、专有的」。不合自家规矩的，就是 improper。\",\"misemploy\":\"mis-「误」+ employ「雇用、使用」构成。employ 来自拉丁语 implicare「卷入」，经法语 employer 转指「使用」。用错地方的，就是 misemploy。\",\"literally\":\"literal 来自拉丁语 litteralis「文字的」，源头 littera「字母」。按字面一个字母不差的，就是 literally。\",\"thoroughfare\":\"thorough（古义「通过」）+ fare「通行」（古英语 faran「行走」）构成：穿得过去的大道，就是 thoroughfare。\",\"warble\":\"来自古法语 werbler「颤声唱」，源头是日耳曼语 *hwerban「旋转」一系（声音转着弯）。鸟的婉转鸣唱，就是 warble。深层来源如实标注为常见说法。\",\"ingredient\":\"来自拉丁语 ingrediens「走进去的」，源头 ingredi：in- + gradi「行走」。走进锅里的每一样，就是 ingredient。\",\"transferable\":\"transfer 来自拉丁语 transferre「搬过去」：trans- + ferre「携带」；再加 -able。搬得走、过户得了的，就是 transferable。\",\"burglarize\":\"burglar 来自中世纪拉丁语 burgator「破门盗」，更深来源有争议，一说与 burgus「设防城镇」有关；-ize 是动词后缀。入室行窃，就是 burglarize。深层来源如实标注存疑。\",\"sewer\":\"（下水道义与缝纫者义同形异源）下水道 sewer 来自古法语 sewiere「排水渠」，源头是通俗拉丁语 *exaquare「放水」（ex- + aqua「水」）；缝东西的 sewer 是 sew 的派生。两义如实标注分开。\",\"undesirable\":\"un- + desirable「值得要的」构成。desire 源头是拉丁语 desiderare「渴望」。不想要的，就是 undesirable。\",\"humpy\":\"hump 来源不完全确定：可能源自斯堪的纳维亚语或低地德语（与 hump「隆起」的拟形构词有关）；再加 -y。隆起一坨坨的，就是 humpy。如实标注。\",\"tawny\":\"来自盎格鲁-法语 tauné「晒褐的」，源头是法语 tanner「鞣皮」（其根与拉丁语 tannum「栎树皮」一系有关）。皮子鞣出的黄褐，就是 tawny。深层来源如实标注为常见说法。\",\"replica\":\"借自意大利语 replica「复制品」，源头是拉丁语 replicare「折回、重述」：re- + plicare「折」。折回来再做一份的，就是 replica。\",\"splinter\":\"借自中古荷兰语 splinter「碎片」，与 split 同族。木头劈出的尖片，就是 splinter。\",\"headstone\":\"head + stone 构成：立在坟头的石碑，就是 headstone。\",\"slang\":\"词源存疑：18 世纪词，先指贼帮黑话；一说与挪威语 sleng「俚语」一系有关，没有定论。行话黑话，就是 slang；这里不硬编。\",\"rarity\":\"rare 来自拉丁语 rarus「稀疏的、罕见的」；再加 -ity。稀罕的程度与物，就是 rarity。\",\"gobble\":\"（狼吞虎咽义）拟声构词，模仿火鸡的咯咯声与吞食声；火鸡本身也叫 gobbler。注意 gobble 另有纺织等同形词，此处取食义。\",\"herbal\":\"herb 来自拉丁语 herba「草」，经古法语进入英语；再加 -al。用草的，就是 herbal（草药的、草本的）。\",\"omen\":\"直接借自拉丁语 omen「预兆」，其更深来源不确定（有一说与 aus-「耳」或 os「口」有关）。预示吉凶的征兆，就是 omen。深层来源如实标注存疑。\",\"mistaken\":\"mistake 来自古诺斯语 mistaka「拿错」：mis- + taka「拿」。拿错了的，就是 mistaken。\",\"explanatory\":\"explain 来自拉丁语 explanare「铺平、阐明」：ex- + planus「平的」。把皱着的道理铺平给人看，就是 explanatory；与 plain（平坦的、明白的）同根。\",\"parenthood\":\"parent + -hood「状态」构成：为人父母的状态，就是 parenthood。\",\"ignition\":\"ignite 来自拉丁语 ignire「点燃」，源头 ignis「火」；再加 -tion。点火的那一下，就是 ignition；汽车钥匙拧到的正是它。\",\"influential\":\"influence 来自中世纪拉丁语 influentia「流入（的星力）」，源头 influere：in- + fluere「流」。占星家说星辰的力流进人间；能「流」动别人决定的，就是 influential。\",\"annual\":\"来自拉丁语 annualis「每年的」，源头 annus「年」。一年一度就是 annual；anniversary（周年）里的 ann- 也是它。\",\"plucky\":\"pluck 本义「拔、扯」，引申为「胆量」（拔内脏时见勇气一说）；再加 -y。有胆的，就是 plucky。深层引申如实标注为常见说法。\",\"unsuspected\":\"un- + suspected「被怀疑的」构成。suspect 源头是拉丁语 suspicere「斜眼看」。没人斜眼瞧的，就是 unsuspected。\",\"handout\":\"hand + out 构成的短语名词化：伸手递出去的，就是 handout（救济品、讲义）。\",\"pleasurable\":\"pleasure 是 please 加名词后缀：please 源头是拉丁语 placere「使满意」；再加 -able。享受得来的，就是 pleasurable。\",\"scornful\":\"scorn 来自古法语 escorn「轻蔑」，其更深来源有争议（一说与拉丁语 ex- + cornu「角」有关——顶角相向）；再加 -ful。满是轻蔑的，就是 scornful。深层来源如实标注存疑。\",\"judgmental\":\"judge 来自拉丁语 iudicare「宣判」：ius「法」+ dicare「宣告」；再加 -mental。动不动给人下判语的，就是 judgmental。\",\"petty\":\"来自古法语 petit「小的」，其更深来源不确定（可能为拟声的儿语词）。小到不值一提的，就是 petty。深层来源如实标注存疑。\",\"utmost\":\"古英语 ūtemest「最外面的」：ūt「外」+ -mest「最」。最外、最尽的，就是 utmost。\",\"umpire\":\"中古英语 a noumpere 被误切成 an umpire：noumpere 来自古法语 nonper「不平等的（第三人）」：non「不」+ per「平等的」——双方之外的中立人。n 的误切史如实标注。\",\"trump\":\"（王牌义与喇叭义同形异源）王牌 trump 是 triumph 的讹变缩略（牌戏里 triumph 作 trump）；喇叭 trump 是古法语 trompe。两义如实标注分开。\",\"pommel\":\"来自古法语 pomel「小苹果（状物）」，是 pomme「苹果」的指小形式，源头拉丁语 pomum「果」。剑柄与马鞍上苹果状的圆头，就是 pommel。\",\"inestimable\":\"in-「不可」+ estimable「可估价的」（源头拉丁语 aestimare「估价」）构成。估不出价的珍贵，就是 inestimable。\",\"swagger\":\"来源不完全确定：16 世纪词，可能是 swag「摇摆」的反复形式（受斯堪的纳维亚语影响）。大摇大摆的，就是 swagger。如实标注。\",\"rifle\":\"（步枪义）来自 rifle「膛线」：枪管里刻的螺旋纹使子弹旋转。rifle 本义「刻槽」，可能源自古法语 rifler「刮、刻」一系。转义如实标注：此为常见说法。\",\"overshadow\":\"over + shadow 构成的中古英语复合词：影子盖过别人的，就是 overshadow。\",\"stump\":\"中古英语 stumpe「树桩」，源自中古低地德语 stump，与德语 Stumpf 同源。桩子与难题（把人「桩」住），都是 stump。\",\"deletion\":\"delete 来自拉丁语 delere「抹去、销毁」：传说由 de- + linere「涂抹」构成。把字从版面上抹掉，就是 deletion。此构词为传统说法，如实标注。\",\"fastener\":\"fasten 是古英语 fæstnian「使牢固」，源头 fæst「牢固的」。把东西扣牢的小件，就是 fastener；fast 的「快」义是后来从「牢」引申的另一路。\",\"nimble\":\"古英语 numol「能拿取的」，源头 niman「拿」；中古英语拼写受 b 影响（类 thumb）。手快抓得稳的，就是 nimble（敏捷的）。\",\"healthful\":\"health 是古英语 hǣlþ「完整、健康」，源头 hāl「完整的」（即 whole）；再加 -ful。对「完整」有益的，就是 healthful。\",\"acceptability\":\"accept 来自拉丁语 acceptare「接过来」：ad-「向」+ capere「取、抓」；再加 -ability「可…性」。能被接过去，就是可接受。\",\"wretched\":\"wretch 是古英语 wrecca「流亡者、可怜人」，源头 wrecan「驱逐、复仇」。被驱逐的可怜相，就是 wretched；与 wreak（复仇）同根。\",\"nonexistent\":\"non- + existent「存在的」（源头拉丁语 existere「站出来」：ex- + sistere「站」）构成。压根没站出来的，就是 nonexistent。\",\"fragile\":\"来自拉丁语 fragilis「易碎的」，源头 frangere「打破」。一碰就碎的，就是 fragile。\",\"situate\":\"来自中世纪拉丁语 situare「安置」，源头 situs「位置」。把东西安放到位的，就是 situate。\",\"sliver\":\"中古英语 slivere「裂片」，源头 sliven「劈开」，与古英语 slīfan 同族。劈下的一条薄片，就是 sliver。\",\"rustle\":\"拟声构词：模仿叶子与纸的沙沙声，中古英语 rustelen。沙沙响与偷牛，都是 rustle（后者是另一义路的引申）。\",\"instantly\":\"instant 来自拉丁语 instans「站着催逼的、迫在眉睫的」，源头 instare：in- + stare「站」；再加 -ly。站在眼前的那一刻，就是 instantly。\",\"scrape\":\"借自古诺斯语 skrapa「刮擦」：刮出的声响与窘境，都是 scrape。\",\"rabble\":\"来源不完全确定：中古英语 rabel「乌合之众」，可能与 rabble「急促说话」（拟声）同源。吵吵嚷嚷的一群人，就是 rabble。如实标注。\",\"chaperone\":\"借自法语 chaperon「头巾、兜帽」，源头是晚期拉丁语 cappa「斗篷」。陪护的年长女性像兜帽一样「罩」着少女，后来泛指陪护人；与 cap、cape 同族。\",\"reactant\":\"react 是按拉丁语 reagere 造的词：re-「回」+ agere「驱动」；再加 -ant。起反应的物质，就是 reactant。\",\"yowl\":\"拟声构词：模仿猫与狗的长号（中古英语 yollen）。扯着嗓子号的，就是 yowl。\",\"hesitance\":\"hesitate 来自拉丁语 haesitare「黏住、迟疑」，是 haerere「黏着」的反复形式。脚像被粘住迈不开，就是 hesitance；与 adhesive 同根。\",\"neglectful\":\"neglect 来自拉丁语 neglectus「被忽视的」，源头 neglegere：neg-「不」+ legere「拾取、顾及」。眼里没拾起来的，就是 neglectful。\",\"championship\":\"champion 来自晚期拉丁语 campio「角斗士」，源头 campus「战场、平原」。在战场上替人决斗的人成了冠军；champion 的头衔赛就是 championship。\",\"narration\":\"narrate 来自拉丁语 narrare「讲述」，源头 gnarus「知晓的」——讲给人知道。讲述这件事本身，就是 narration；与 know 同族。\",\"vengeful\":\"vengeance 来自古法语 vengeance，源头是拉丁语 vindicare「索偿、报复」；再加 -ful。满心索偿的，就是 vengeful。\",\"silo\":\"借自西班牙语 silo「地窖、粮仓」，其更深来源有一说与拉丁语 sirus（希腊语 siros「储粮坑」）有关。存粮的塔仓与信息孤岛，都是 silo。深层来源如实标注为一说。\",\"presidency\":\"president 来自拉丁语 praesidens「坐镇在前者」，源头 praesidere：prae- + sedere「坐」。坐在前头的那把椅子任期，就是 presidency。\",\"quaver\":\"中古英语 quaveren「颤抖」，是 quake 的反复形式一系（-er 表反复）。声音抖着的，就是 quaver。\",\"inapparent\":\"in-「不」+ apparent「明显的」：apparent 源头是拉丁语 apparere「显现」（ad- + parere「出现」）。看不出来的，就是 inapparent。\",\"suggestive\":\"suggest + -ive：递出暗示的，就是 suggestive。\",\"personable\":\"person + -able 构成的中古英语词：模样讨喜的，就是 personable。person 源头同 persona。\",\"revengeful\":\"revenge 来自古法语 revengier，源头是拉丁语 revindicare 一系：re- + vindicare「索偿、报复」；再加 -ful。满心索偿的，就是 revengeful。\",\"superb\":\"来自拉丁语 superbus「高傲的、华丽的」：super-「在上」。高人一等的好，就是 superb。\",\"elderly\":\"elder 是古英语 eldra「年长的」，是 old 的比较级古形式；再加 -ly。年事已高的，就是 elderly。\",\"topple\":\"top「顶」+ -le 反复后缀构成的中古英语词：从顶上晃着倒的，就是 topple。\",\"ashore\":\"a-「在…上」+ shore「岸」。shore 可能是中古荷兰语或低地德语 schore「切割出的边」，指海陆相切的那条边。人上了那条边，就是 ashore。\",\"scaly\":\"scale「鳞」来源有一路：经古法语 escale 而来，源头是日耳曼语 *skalō「壳、片」；再加 -y。满是鳞片的，就是 scaly。\",\"heading\":\"head（古英语 hēafod）+ -ing 构成：放在顶头的大字，就是 heading；船头的方向也是它。\",\"insanity\":\"in-「不」+ sanity「神志健全」：sanity 源头是拉丁语 sanitas「健康」（sanus「健全的」）。脑子不健全的，就是 insanity。\",\"additive\":\"add 来自拉丁语 addere「加上」：ad- + dare「给」；-itive 表「有…作用的」。加进去改变性质的东西，就是添加剂。\",\"lurch\":\"（突然倾斜义）来源不完全确定：可能由 lurche 一类船语或 lee-lurch 演变；另有 lurch「潜行」是古法语来源的同形词。船身猛地一歪，就是 lurch。如实标注存疑。\",\"uncommon\":\"un- + common「普通的」构成：不普通的，就是 uncommon。\",\"rudiment\":\"来自拉丁语 rudimentum「初步、雏形」，源头 rudis「粗糙的、未加工的」。没加工的开头，就是 rudiment（基础、雏形）。\",\"infinite\":\"来自拉丁语 infinitus「无界的」：in- + finis「边界」。没有边的，就是 infinite。\",\"hocus\":\"hocus-pocus 的缩略：魔术师的咒语 hocus pocus 本身可能是对拉丁语弥撒词 hoc est corpus「这是我的身体」的戏仿（此说流传广但未证实）。变戏法与糊弄，就是 hocus。如实标注。\",\"laughable\":\"laugh 是古英语 hliehhan，带拟声色彩的古老词；再加 -able。好笑到不值一提的，就是 laughable。\",\"faithful\":\"faith 来自古法语 feid，源头是拉丁语 fides「信任、信念」；再加 -ful。信念装满的，就是 faithful；与 fidelity 同根。\",\"cowardice\":\"coward 来自古法语 couard「胆小鬼」，源头可能是拉丁语 cauda「尾巴」——像夹着尾巴逃的狗；再加 -ice。此「尾巴」说为流传最广的解释，如实标注为推测。\",\"spidery\":\"spider 是古英语 spīþra「纺织者」，源头 spinnan「纺」；再加 -y。细长如蛛腿的，就是 spidery。\",\"fodder\":\"古英语 fōdor「饲料」，源头是印欧语 *pa-「喂养」，与 food、feed 同根。喂牲口的料，就是 fodder；cannon fodder 是「炮灰」。\",\"abbey\":\"来自中世纪拉丁语 abbatia「修道院」，源头是 abbas「院长」，再往上是亚拉姆语 abba「父亲」——修道院就是「父亲（院长）管着的地方」，与 abbot（院长）同源。\",\"deservedly\":\"deserve 来自古法语 deservir，源头是拉丁语 deservire「勤勉服侍」：de- + servire「服务」。服侍应得的回报，就是 deserve；deservedly 是「活该地」。\",\"pawn\":\"（棋子义与典当义同形异源）棋子 pawn 源自古法语 paon「步兵」，其根是拉丁语 pedo「步行者」；典当 pawn 源自古法语 pan「抵押物」，其根是日耳曼语 *pand。两义如实标注分开。\",\"migrant\":\"来自拉丁语 migrans「迁徙的」，源头 migrare「迁移、搬家」。搬来搬去的人与鸟，都是 migrant。\",\"obituary\":\"来自中世纪拉丁语 obituarius「死亡记录」，源头 obitus「去世」：ob- + itus「去」（ire「去」）。人「去」了的记录，就是 obituary（讣告）。\",\"unkempt\":\"un- + kempt「梳过的」构成。kempt 是古英语 cemban「梳」的分词古形（今只活在 unkempt 里）。没梳过的乱，就是 unkempt。\",\"infernal\":\"来自拉丁语 infernalis「地下的、阴间的」，源头 infernus「下界」。地狱般的，就是 infernal；与 inferior 同族。\",\"grouchy\":\"grouch 来源不完全确定：可能是 grouse「抱怨」（其源头又有争议）与 crouch 一类词的混合，19 世纪美国词。脾气别扭爱抱怨的，就是 grouchy。如实标注存疑。\",\"canopy\":\"来自希腊语 kōnōpeion「蚊帐」，源头 kōnōps「蚊子」，经拉丁语、古法语进入英语。防蚊的帐子升到空中，就是 canopy；森林树冠也用它。\",\"salty\":\"salt 是古英语 sealt，与拉丁语 sal 同源；再加 -y。咸的、带刺儿的（俚语），就是 salty。\",\"oceanic\":\"ocean 来自希腊语 Ōkeanos：古希腊人以为大地被一条大河环绕，河神就叫俄刻阿诺斯。关乎大海的，就是 oceanic。\",\"treatise\":\"来自盎格鲁-法语 tretis「论述」，源头是拉丁语 tractatus「处理、论述」，其根 trahere「拉」。把问题拉开细论的，就是 treatise（专著）。\",\"refreshment\":\"refresh 来自古法语 refreschir「使重新清凉」：re- + fresche「新鲜的」（日耳曼语来源）；再加 -ment。茶点与提神，都是 refreshment。\",\"forgetful\":\"forget 是古英语 forgietan「忘记」：for-「失去」+ gietan「得到、把握」。没把握住的，就是 forgetful；与 get 同根。\",\"massive\":\"mass 来自拉丁语 massa「面团、块」，源头是希腊语 maza「大麦饼」，经法语进入英语；再加 -ive。大块头的，就是 massive。\",\"leakage\":\"leak 来源不完全确定：中古英语 leken，可能源自古诺斯语 leka「滴漏」或中古荷兰语 leken；再加 -age。漏出来的量，就是 leakage。如实标注。\",\"fraction\":\"来自拉丁语 fractio「破碎」，源头 frangere「打破」。整块打碎后的一份，就是 fraction；与 fracture（骨折）同根。\",\"familiarize\":\"familiar 来自拉丁语 familiaris「家里的、亲近的」，源头 familia「家仆、家庭」，其根 famulus「仆人」。把生客变「家里人」，就是 familiarize。\",\"fretful\":\"fret（烦躁义）是古英语 fretan「啃食、吞噬」：心里像被虫子啃的，就是 fretful。注意 fret 还有琴格、纹章等同形词，各有来源。\",\"gutsy\":\"guts（内脏→胆量）+ -y 构成的口语词。有胆的，就是 gutsy。\",\"merciful\":\"mercy 来自古法语 merci「怜悯、恩惠」，源头是拉丁语 merces「报酬、代价」——从「赎价」转指「宽宥」；再加 -ful。肯宽宥的，就是 merciful。\",\"ruffian\":\"来自古法语 rufian「皮条客、无赖」，源头可能是意大利语 ruffiano，其更深来源有争议（一说与日耳曼语 hruf「粗糙」有关）。粗野的恶棍，就是 ruffian。如实标注存疑。\",\"toddle\":\"来源不完全确定：苏格兰方言词，可能是 totter「蹒跚」与 toddler 一系的变体，带拟声色彩。摇摇晃晃走的，就是 toddle。如实标注。\",\"persuasion\":\"persuade 来自拉丁语 persuadere「劝服」：per- + suadere「劝说」。劝到人心里的，就是 persuasion；与 sweet 的 suad- 同族一说（劝得甜）。深层如实标注。\",\"dumpy\":\"dump「矮胖」一义来源不完全确定，可能源自斯堪的纳维亚语（与丹麦语 dumpe「矮墩」一说）。矮矮胖胖的，就是 dumpy。如实标注。\",\"frigid\":\"来自拉丁语 frigidus「寒冷的」，源头 frigere「冷」，其根 frigus「寒冷」。冷到僵的，就是 frigid；冰箱 refrigerant 的 frig- 同族。\",\"humongous\":\"20 世纪美国学生俚语，由 huge 与 monstrous 混成（押韵造词）。大得离谱的，就是 humongous。\",\"insightful\":\"insight 是中古英语按古诺斯语或荷兰语同类词造的「内眼」：in + sight。往里看得透的，就是 insightful。\",\"saint\":\"来自拉丁语 sanctus「神圣的」，源头 sancire「使神圣、批准」，经古法语进入英语。被封圣的，就是 saint。\",\"sputter\":\"拟声构词：模仿油锅与结巴的噼啪声，可能是 spout、utter 一类词的混成。噼里啪啦的，就是 sputter。\",\"impure\":\"im-「不」+ pure「纯的」：pure 来自拉丁语 purus「干净的」。掺了杂的，就是 impure。\",\"invincible\":\"来自拉丁语 invincibilis「不可征服的」：in- + vincere「战胜」。打不赢的，就是 invincible。\",\"timeworn\":\"time + worn「磨旧的」构成：被岁月磨旧的，就是 timeworn。\",\"bumper\":\"bump（拟声词，模仿重击声）+ -er。先指斟得冒尖的大酒杯，后指汽车上「挨撞」的保险杠；bumper crop 是「撞满仓」的大丰收。\",\"distraught\":\"distract 的中古英语变体过去分词：distrahere「往各方拉」。心被拉到快疯，就是 distraught。\",\"overjoyed\":\"over-「过度」+ joyed「高兴的」构成：高兴过头的，就是 overjoyed。joy 源头是拉丁语 gaudium「喜悦」。\",\"combatant\":\"combat 经法语 combattre 而来，源头是晚期拉丁语 combattere「打斗」：com- + battere「打」。上场打的人，就是 combatant。\",\"inexpensive\":\"in-「不」+ expensive「贵的」：expense 源头是拉丁语 expendere「称出付出」（ex- + pendere「称」）。称不出多少分量的价，就是 inexpensive。\",\"digestive\":\"digest 来自拉丁语 digestus「分开、消化」，源头 digerere：dis- + gerere「携带」。把食物「分开搬运」吸收掉，就是 digestive；与 gesture（搬动身体→姿势）的 ger- 同根。\",\"awakening\":\"awake 是古英语 awacan：ā-（加强）+ wacan「醒来」。从睡里被叫起来，引申为意识的觉醒；与 watch（守夜）的 wak- 同根。\",\"quarterly\":\"quarter 来自拉丁语 quartus「第四」：一年四份，一季一次，就是 quarterly。\",\"departed\":\"depart 来自古法语 departir「分开、离开」，源头是晚期拉丁语 departire：de- + partire「分」（pars「部分」）。「离开」委婉指去世，the departed 就是逝者。\",\"bestrewn\":\"be-「遍」+ strewn（strew「撒」的过去分词，古英语 streowian）。满地撒遍了的，就是 bestrewn with 落叶或鲜花。\",\"smudge\":\"来源不完全确定：中古英语 smogen「弄脏」，可能与 smutch 一系或斯堪的纳维亚语有关。抹花的污迹，就是 smudge。如实标注。\",\"thunderstruck\":\"thunder + struck 构成的复合词：被雷劈中的，就是 thunderstruck（惊呆了的）。thunder 是古英语 þunor。\",\"cockeyed\":\"cock「歪斜、竖起」（源自 cock「公鸡」抬头之姿一说）+ eyed 构成的口语词。眼斜、歪歪扭扭、荒唐，都是 cockeyed。此构成说法较流行，如实标注。\",\"inaccuracy\":\"in-「不」+ accuracy「准确」：accurate 源头是拉丁语 accuratus「精心做成的」（ad- + cura「用心」）。不用心出的错，就是 inaccuracy。\",\"competitive\":\"同 compete：com- + petere「追求、争取」。人人都往同一个目标冲，就是 competitive。\",\"sleazy\":\"来源不完全确定：17 世纪 sleazy 先指织物稀薄，词干 Sleazy 有一说指西里西亚（Silesia）的亚麻布，后转指廉价下流。如实标注：地名说为常见解释。\",\"overreach\":\"over + reach（古英语 rǣcan「伸手」）构成：手伸过头的，就是 overreach。\",\"eventful\":\"event 来自拉丁语 eventus「结果、发生的事」，源头 evenire「发生」：e- + venire「来」；再加 -ful。事一件接一件「来」的，就是 eventful。\",\"overachieve\":\"over-「过度」+ achieve「达成」构成的 20 世纪词。achieve 来自古法语 achever「做完」，源头是短语 à chef「到头」（chef「头」，拉丁语 caput）。做过头的，就是 overachieve。\",\"herbivorous\":\"拉丁语拼合词：herba「草」+ vorare「吞食」。只吃草的，就是 herbivorous。\",\"accusatory\":\"accuse 来自拉丁语 accusare「传唤到案前」：ad- + causa「案件、理由」；-tory 是形容词后缀。语气里带着「提告」的味道，就是 accusatory。\",\"nightmare\":\"night + mare「恶魔」构成：mare 是古英语 mare「压人的夜妖」（与斯拉夫语 mora 同族），不是母马。被夜妖压住的噩梦，就是 nightmare。\",\"seaward\":\"sea + -ward「向…」构成：朝海的，就是 seaward。\",\"commonality\":\"common 来自拉丁语 communis「共同的」：com- + munis「有义务的」（munus「职责、礼物」）；再加 -ality。人人有份的共同点，就是 commonality。\",\"thwart\":\"借自古诺斯语 þvert「横的」，是 þverr 的中性形式：横着挡路的，就是 thwart（阻挠）。\",\"unavoidable\":\"un- + avoidable「可避的」构成。avoid 来自古法语 esvuidier「清空、避开」：es- + vuidier「空」（源头拉丁语 viduus 一系）。避不开的，就是 unavoidable。\",\"yammer\":\"中古英语 yameren「悲叹」，源自古英语 geōmrian「哀伤」，后受拟声影响转指唠叨。没完没了抱怨的，就是 yammer。\",\"twine\":\"古英语 twīn「双股线」，源头 twi-「二」，与 two 同根：两股搓成一股的绳，就是 twine。\",\"affectionate\":\"affection 来自拉丁语 affectio「被触动的状态」，源头 afficere「作用于、感动」：ad- + facere「做」；再加 -ate。心里被对方「做」动了，就是深情。\",\"obscenity\":\"obscene 来自拉丁语 obscenus「不祥的、猥亵的」，其构词有一说为 ob- + caenum「污泥」，未定论。脏得不堪入耳的，就是 obscenity。深层如实标注存疑。\",\"tract\":\"（地块与传单两义同形）地块义来自拉丁语 tractus「拖、伸展的一片」，源头 trahere「拉」；传单义是 tractate「论述」的缩略。同出一根 trahere 的两条路，如实标注。\",\"fidgety\":\"fidget 来源不完全确定：可能源自古诺斯语 fikjask「急切地动」或中古英语 fiken「不安地动」一系。坐不住地扭来扭去，就是 fidgety。如实标注。\",\"reliance\":\"rely 来自古法语 relier「绑回、依靠」，源头是拉丁语 religare：re- + ligare「绑」。把自己绑在他身上的，就是 reliance。\",\"flurry\":\"来源不完全确定：可能由 flurr「惊飞」（拟声）加 -y 构成，或与 hurry 押韵造出。雪片与人心一起乱飞的，就是 flurry。如实标注。\",\"sensual\":\"来自晚期拉丁语 sensualis「感官的」，源头 sensus「感觉」。走感官路线的，就是 sensual。\",\"complication\":\"complicate 来自拉丁语 complicare「折叠到一起」：com- + plicare「折」。事情折来折去缠成团，就是 complication；与 fold、apply 的 plic- 同族。\",\"hobo\":\"词源存疑：19 世纪末美国词，指流浪劳工；一说源自 hoe boy「农场小工」，一说源自铁路招呼语，没有定论。这里不硬编。\",\"excessive\":\"excess 来自拉丁语 excessus「越出」，源头 excedere：ex- + cedere「走」。走过了界的，就是 excessive。\",\"regardless\":\"regard「在意」+ -less「不」构成：不管不顾的，就是 regardless。\",\"namely\":\"name + -ly 构成的中古英语词：把名字点出来的，就是 namely（即、也就是）。\",\"precursory\":\"precursor 来自拉丁语 praecursor「跑在前面的人」：prae- + currere「跑」；再加 -y。先跑到报信的，就是 precursory（先兆的）。\",\"forcible\":\"force 来自古法语 force，源头是通俗拉丁语 *fortia「力量」，其根是拉丁语 fortis「强的」；再加 -ible。靠力气硬来的，就是 forcible。\",\"persistence\":\"persist 来自拉丁语 persistere「站住不走」：per- + sistere「站定」。钉着不走的，就是 persistence。\",\"trite\":\"来自拉丁语 tritus「被磨旧的」，源头 terere「摩擦」。用磨秃了的词，就是 trite（陈腐的）。\",\"vocal\":\"来自拉丁语 vocalis「发声的」，源头 vox「声音」。用嗓的、敢出声的，就是 vocal。\",\"slurp\":\"拟声构词：模仿吸溜汤面的声音（荷兰语 slurpen 是其近亲）。吸溜出声的，就是 slurp。\",\"legendary\":\"legend 来自中世纪拉丁语 legenda「应读之文」，源头 legere「读」——修道院里该读的圣徒传。读成了传奇的，就是 legendary。\",\"trudge\":\"来源不完全确定：16 世纪词，可能与 tread 一系或方言词有关。拖着重步走的，就是 trudge。如实标注存疑。\",\"kink\":\"来自荷兰语 kink「绳索的扭结」，与斯堪的纳维亚语一系同族。绳子打的结与事情的疙瘩，都是 kink。\",\"pictorial\":\"picture 来自拉丁语 pictura「绘画」，源头 pingere「画」；再加 -ial。用图说话的，就是 pictorial；与 pigment（颜料）同根。\",\"tussle\":\"来源不完全确定：可能是 tousle「弄乱」的方言变体（苏格兰语）。扭打成一团的，就是 tussle。如实标注。\",\"overhaul\":\"over + haul「拖」构成的航海词：把船拖上岸大修，引申为全面检修与赶超，就是 overhaul。\",\"storyboard\":\"story + board 构成的 20 世纪电影词：把故事画在板上的分镜，就是 storyboard。\",\"oblong\":\"来自拉丁语 oblongus「长形的」：ob- + longus「长的」。横着长的，就是 oblong（长方形的）。\",\"terrorize\":\"terror 来自拉丁语 terror「恐惧」，源头 terrere「吓」；再加 -ize。用恐惧压人的，就是 terrorize。\",\"fascinate\":\"来自拉丁语 fascinare「施魔咒」，源头 fascinum「护身符、魔咒」。被咒住挪不开眼的，就是 fascinate 的原义。\",\"occasional\":\"occasion 来自拉丁语 occasio「时机」，源头 occidere「落下、临到」：ob- + cadere「落」。机会「落」到头上的，就是 occasion；偶尔落一次的，就是 occasional。\",\"mastery\":\"master 来自拉丁语 magister「主事者、教师」，源头 magis「更」（magnus「大」一族），经古英语、古法语合流；再加 -y。把一门本事握到「更」高处，就是 mastery。\",\"truss\":\"来自古法语 trousse「一捆」，源头 trousser「捆起」，其更深来源有一说与拉丁语 thyrsus 或 tortus 一系有关。捆扎的架与带，就是 truss。深层来源如实标注存疑。\",\"unfounded\":\"un- + founded「有根据的」构成。found（建立义）来自拉丁语 fundare，其根 fundus「底」。没底的指控，就是 unfounded。\",\"overshoot\":\"over + shoot 构成：射过头的，就是 overshoot。\",\"lunacy\":\"luna 是拉丁语「月亮」：古人相信月相能扰动心智（moonstruck）。疯症归给月亮，就是 lunacy；lunatic（疯子）与它同源。此为历史观念，如实标注。\",\"restrictive\":\"restrict 来自拉丁语 restrictus「被拉紧的」，源头 restringere：re- + stringere「拉紧」。管得紧的，就是 restrictive；与 strict 同根。\",\"abbreviation\":\"来自拉丁语 abbreviare「缩短」：ad-「向」+ brevis「短」。把长词写短就是 abbreviation，与 brief（简短的）同根。\",\"temptation\":\"tempt 来自拉丁语 temptare「试探、试手」，经古法语进入英语。试着勾你的，就是 temptation。\",\"calculating\":\"calculate 来自拉丁语 calculare「用小石子算账」，源头 calculus「小石子」（calx「石灰、石子」的指小形式）。古人拿石子计数；心里拨石子的精明，就是 calculating。\",\"fumble\":\"来源带拟声色彩：中古英语 fomelen 一类词，或源自斯堪的纳维亚语 fumla「笨拙地摸」。手忙脚乱摸不稳的，就是 fumble。如实标注：此为常见说法。\",\"frisky\":\"frisk 来源不完全确定：中古英语 frisk「活泼的」，可能源自古法语 frisque「轻快的」，其根或为日耳曼语 frisk「新鲜」。蹦蹦跳跳的，就是 frisky。如实标注。\",\"mistress\":\"来自古法语 maistresse「女主人」，是 master 的阴性形式，源头拉丁语 magister「主事者」。女主人与情妇，两义同出一词，如实标注。\",\"changeability\":\"change 来自古法语 changer，源头是晚期拉丁语 cambiare「交换」，可能出自高卢语；再加 -ability。说变就变的性质，就是 changeability。\",\"optimal\":\"optimum 是拉丁语 optimum「最好的」，是 bonus「好的」的不规则最高级一系（optimus「最佳的」）；再加 -al。好到顶点的，就是 optimal。\",\"perky\":\"perk 来源不完全确定：中古英语 perken「昂首、打扮」，可能与 perch「栖木」有关一说。神气活现的，就是 perky。如实标注。\",\"gulch\":\"美国西部词，来源不完全确定：可能由 gulch「吞咽」（方言动词）转指被水「吞」出的深沟。干涸的深谷，就是 gulch。如实标注存疑。\",\"boundary\":\"bound「边界」+ -ary。bound 经古法语 borne「界石」而来，源头是中世纪拉丁语 bodina「界标」，可能出自高卢语。立着界石的那条线，就是 boundary。\",\"loathe\":\"古英语 lāþian「憎恶」，源头 lāþ「讨厌的、敌意的」，与德语 leid「痛苦」同族。厌恶到骨子里的，就是 loathe。\",\"oomph\":\"拟声构词：模仿使劲时的哼声，20 世纪美国口语。劲头与魅力，就是 oomph。\",\"brawl\":\"中古英语 braulen「吵嚷、叫骂」，可能源自中古荷兰语 brallen「喧哗」，带拟声色彩，未完全定论。先动嘴吵、再动手打，就是 brawl。\",\"manage\":\"来自意大利语 maneggiare「训练（马）、操控」，源头是拉丁语 manus「手」。手把手摆弄出来的，就是 manage；与 manual（手的）同根。\",\"inaccessibility\":\"in-「不」+ accessibility「可达性」：access 源头是拉丁语 accedere「走近」（ad- + cedere「走」）。走近不了的，就是 inaccessibility。\",\"fictionalize\":\"fiction 来自拉丁语 fictio「塑造、虚构」，源头 fingere「捏塑、编造」；再加 -ize。把真事「捏」成小说的，就是 fictionalize；与 figure（捏出的形）同根。\",\"demotion\":\"demote 是 19 世纪按 promote 的反义回构的词：de-「向下」+ mot-（拉丁语 movere「移动」）。职位往下移，就是 demotion。\",\"destructible\":\"destruct 是拉丁语 destructus「被拆毁的」，源头 destruere：de- + struere「堆建」。能被拆掉的，就是 destructible；与 structure（堆建之物）同根。\",\"jumble\":\"来源不完全确定：可能与 jump 的拟声近亲或中古英语 jumbelen「混杂」有关。乱成一堆的，就是 jumble。如实标注存疑。\",\"unforeseen\":\"un- + foreseen「预见的」构成：fore- + seen。事先没看见的，就是 unforeseen。\",\"plenteous\":\"plenty 来自古法语 plenté，源头是拉丁语 plenitas「充满」，其根 plenus「满的」；再加 -ous。多到满的，就是 plenteous。\",\"vast\":\"来自拉丁语 vastus「空旷的、巨大的」，与 vastare「使荒芜」同族。大得空旷的，就是 vast。\",\"idealize\":\"ideal 来自晚期拉丁语 idealis「理念的」，源头是希腊语 idea「形相、理念」（idein「看」）；再加 -ize。按脑中理念美化，就是 idealize。\",\"biweekly\":\"bi-「二、双」（拉丁语 bis「两次」）+ weekly 构成：每两周一次，或每周两次——这个词本身就有歧义，使用时要靠上下文分清。\",\"generosity\":\"generous 来自拉丁语 generosus「出身高贵的」，源头 genus「出身、种类」——贵族就该大方。词义从「高贵」滑向「慷慨」，就是 generosity。\",\"horrendous\":\"来自拉丁语 horrendus「令人毛骨悚然的」，源头 horrere「（毛发）竖立、颤抖」。吓得汗毛倒竖的，就是 horrendous；与 horror 同根。\",\"apiece\":\"中古英语短语 a piece「每件（一个）」：a「每」+ piece。piece 经古法语而来，源头可能是通俗拉丁语 *pettia「碎块」。按件计价，每件多少，就是 apiece。\",\"jackpot\":\"jack + pot 构成的扑克词：pot 是桌上那堆赌注，抽 jack 才能开的累积大注，就是 jackpot（头奖）。\",\"triad\":\"来自希腊语 trias「三人组」，源头 treis「三」，经拉丁语、法语进入英语。三个成一组的，就是 triad。\",\"geezer\":\"来源不完全确定：可能是 guiser「乔装者」（源自 disguise）的方言变体——化装演哑剧的老者。怪老头，就是 geezer。如实标注。\",\"seasoning\":\"season 本义「播种时节」：来自拉丁语 satio「播种」，经古法语进入英语，后专指调味（让食物合时节的引申有一段公案）。给食物添味的，就是 seasoning；词义转折如实标注。\",\"commitment\":\"commit 来自拉丁语 committere「交托、着手」：com- + mittere「送」。把自己「送」进一件事里出不来，就是 commitment。\",\"bumpkin\":\"来源不完全确定：多认为源自荷兰语 boomken「小树、小木桶」一类词，拿木头疙瘩比喻粗笨的乡下人。此说较流行但未成定论，如实标注。\",\"troupe\":\"借自法语 troupe「一队、剧团」，源头是日耳曼语 *þorp「人群、村庄」一说（与 thorp 同族）。一队的演员，就是 troupe。深层来源如实标注为一说。\",\"bottomless\":\"bottom（古英语 botm「底、基」）+ -less「没有」。深不见底的坑、喝不完的畅饮杯，都是 bottomless。\",\"clarification\":\"clarify 来自晚期拉丁语 clarificare「使明亮、阐明」：clarus「明亮的、清楚的」+ facere「做」；再加 -ation。把话说亮，就是 clarification。\",\"guilty\":\"guilt 是古英语 gylt「罪行、债务」，其更深来源不确定；再加 -y。背着罪的，就是 guilty。深层来源如实标注存疑。\",\"sisterhood\":\"sister 是古英语 sweostor，受古诺斯语 systir 影响改形；再加 -hood。姐妹之情与修女会，就是 sisterhood。\",\"platoon\":\"来自法语 peloton「小球、排」，是 pelote「线团」的指小形式，其根与拉丁语 pila「球」有关一说。团成一团的兵，就是 platoon（排）。深层来源如实标注。\",\"combination\":\"combine 来自晚期拉丁语 combinare「两两合并」：com- + bini「成双的」。把东西双双合到一起，就是 combination；与 binary 同根。\",\"mishmash\":\"mash「捣碎」的叠韵重构词（16 世纪）：把东西捣成一锅糊的重复说法，就是 mishmash（大杂烩）。\",\"forerunner\":\"fore- + runner 构成的中古英语复合词：先跑到、报信在前的人，就是 forerunner。\",\"challenging\":\"challenge 来自古法语 chalenge「指控、质疑」，源头是拉丁语 calumnia「诬告」。本义是下战书式的质疑，后转指难啃的任务；与 calumny（诽谤）同根。\",\"afflict\":\"来自拉丁语 affligere「击倒、折磨」：ad- + fligere「打击」。像重击一样落到身上的病痛，就是 afflict 的折磨。\",\"timely\":\"time（古英语 tīma）+ -ly 构成的中古英语词：来得正是时候的，就是 timely。\",\"scorch\":\"来源不完全确定：中古英语 scorchen，可能源自古诺斯语 skorpna「干缩」一系。烧焦表面的，就是 scorch。如实标注。\",\"certifiable\":\"certify 来自拉丁语 certificare「使确定」：certus「确定的」+ facere「做」；再加 -able。能被正式「定下来」的，就是 certifiable；口语里也指疯得可以确诊。\",\"cheapskate\":\"cheap + skate「吝啬鬼」（19 世纪美国俚语，skate 本指破冰鞋、老马，转指不值钱的人）构成。抠门到家的人，就是 cheapskate。skate 的这层俚语来源不完全确定，如实标注。\",\"stargaze\":\"star + gaze「凝视」构成的复合词。gaze 来源不完全确定，可能源自斯堪的纳维亚语。望星空的，就是 stargaze。如实标注。\",\"bloodshed\":\"blood + shed「倾倒、流出」（古英语 scēadan 本义「分开」）构成，16 世纪成词。血被「倒」出来，就是流血事件。\",\"normalize\":\"normal + -ize：拉回角尺标准内的，就是 normalize。\",\"nowadays\":\"中古英语复合词：now + a（介词）+ days，本义「在这些日子里」。如今，就是 nowadays。\",\"slinky\":\"slink 是古英语 slincan「爬行、潜行」，指身子贴地地走；再加 -y。贴地蜿蜒的，就是 slinky（如弹簧玩具 Slinky）。\",\"impracticable\":\"im-「不」+ practicable「可行的」：practice 源头是希腊语 praktikos「实干的」（prassein「做」）。做不成的，就是 impracticable。\",\"disentangle\":\"dis-「解开」+ entangle「缠住」：tangle 来源不完全确定，可能源自斯堪的纳维亚语（与 tång「海藻」一说有关）。把缠成团的解开，就是 disentangle。深层来源如实标注。\",\"toxin\":\"toxic + -in（化学物质后缀）在 19 世纪造出：生物体产的毒，就是 toxin。\",\"misunderstanding\":\"mis- + understanding「理解」构成：understand 是古英语 understandan「站在中间（领会）」。没领会对的，就是 misunderstanding。\",\"abuzz\":\"a-「处于…状态」+ buzz（拟声词，模仿蜜蜂与人群的嗡嗡声）。整个场所嗡嗡作响，就是 abuzz with 消息与议论。\",\"partake\":\"part + take 按拉丁语 participare 的仿译在 16 世纪造出：分一份来「取」，就是 partake（分享、参与）。\",\"parentage\":\"parent 来自拉丁语 parens「父亲/母亲」，源头 parere「生育」；再加 -age。出身的那条线，就是 parentage。\",\"distend\":\"来自拉丁语 distendere「向四周拉伸」：dis- + tendere「拉」。气球被撑开，就是 distend；与 tendon（拉着的筋）同根。\",\"castaway\":\"cast「抛、扔」（源自古诺斯语 kasta）+ away 构成：被海浪「扔」上荒岛的人，就是 castaway。\",\"partial\":\"来自拉丁语 partialis「部分的」，源头 pars「部分」。只占一部分的、偏心的，都是 partial。\",\"trough\":\"古英语 trog「木槽」，与德语 Trog 同源，与 tray 同族一说。喂食的槽与波谷，都是 trough。\",\"electrify\":\"electric 是按希腊语 ēlektron「琥珀」造的：静电最早在摩擦琥珀时发现。再加 -ify「使…」。通上电、使人兴奋，都是 electrify。\",\"pitiless\":\"pity + -less「没有」构成：不留怜悯的，就是 pitiless。\",\"delicacy\":\"delicate 来自拉丁语 delicatus「精美的、娇嫩的」，与 delectare「使愉悦」同族。精致易碎之物与精致的吃食，都是 delicacy。\",\"understatement\":\"under + statement「陈述」构成的 19 世纪词：往轻里说的，就是 understatement（低调陈述）。\",\"rehash\":\"re- + hash「剁碎、重炒」构成的口语词。hash 来自法语 hacher「剁」，源头是日耳曼语斧头一系。把旧料剁碎重炒的，就是 rehash。\",\"rigidity\":\"rigid 来自拉丁语 rigidus「僵硬的」，源头 rigere「僵直」。硬到弯不了的，就是 rigidity。\",\"quench\":\"古英语 cwencan「熄灭」，是 cwincan「消逝」的使动形式：让火与渴「消逝」。解渴与淬火，都是 quench。\",\"indulge\":\"来自拉丁语 indulgere「宽纵、迁就」，其更深来源不确定。由着性子来的，就是 indulge。深层来源如实标注存疑。\",\"forefront\":\"fore-「前」+ front「前面」构成。front 来自拉丁语 frons「额头、前额」。站在额头位置的，就是 forefront。\",\"niche\":\"借自法语 niche「壁龛」，源头是意大利语 nicchia，其根可能与拉丁语 nidus「巢」有关一说。墙上掏的小窝与生态位，都是 niche。深层来源如实标注为一说。\",\"profanity\":\"profane 来自拉丁语 profanus「在神庙之外的、世俗的」：pro- + fanum「神庙」——庙门外的话不忌口。亵渎与脏话，都是 profanity。\",\"chirrup\":\"拟声构词：模仿鸟雀与昆虫连串的啾啾声，是 chirp 的加强形式。连珠炮似的鸣叫，就是 chirrup。\",\"paunch\":\"来自盎格鲁-法语 panche，源头是拉丁语 pantex「肠肚」（panticis）。凸出来的肚子，就是 paunch。\",\"tribute\":\"来自拉丁语 tributum「贡赋」，源头 tribuere「分配、归于」，其根 tribus「部落」——按部落摊派的税。致敬的献礼，就是 tribute。\",\"tassel\":\"来自古法语 tassel「扣子、流苏」，其更深来源有一说与拉丁语 taxillus「小方块」有关。穗子与博士帽的流苏，都是 tassel。深层来源如实标注为一说。\",\"chisel\":\"来自古法语 chisel，源头是通俗拉丁语 *cisellum「凿子」，其根是拉丁语 caedere「砍、切」。能切石头的工具，就是 chisel；与 scissors（剪刀）的 cis- 同根。\",\"prankster\":\"prank 来源不完全确定：16 世纪词，可能与 prance「腾跃」或低地德语 prang 一类词有关；再加 -ster「…的人」。专搞恶作剧的，就是 prankster。如实标注存疑。\",\"span\":\"古英语 spann「拃（张开的手掌量距）」，与德语 Spanne 同源。手掌量出的距与时间的跨度，都是 span。\",\"empower\":\"em-「使有」+ power「权力」构成。power 经古法语 poeir 而来，源头是通俗拉丁语 *potere「能」，其根是拉丁语 potis「有能力的」。把「能」交到人手里，就是 empower。\",\"frilly\":\"frill 来源不完全确定：16 世纪出现，可能与中古英语 frill「起皱」或法语 friper 一类词有关；再加 -y。满是褶边的，就是 frilly。如实标注存疑。\",\"coloration\":\"color 来自拉丁语 color「颜色、肤色」（古拼写 colos）；再加 -ation。生物身上的配色，就是 coloration。\",\"frightful\":\"fright 是古英语 fryhto「恐惧」，其更深来源不确定；再加 -ful。吓人的，就是 frightful。深层来源如实标注存疑。\",\"foolery\":\"fool 来自古法语 fol「傻瓜」，源头是拉丁语 follis「风箱、气囊」——脑袋空得像气囊。再加 -ery「行径」。傻事一箩筐，就是 foolery。\",\"safekeeping\":\"safe + keeping「保管」构成的中古英语复合词：妥善保管，就是 safekeeping。\",\"irritability\":\"irritate 来自拉丁语 irritare「刺激、激怒」，其更深来源不确定；再加 -ability。一点就炸的体质，就是 irritability。深层来源如实标注存疑。\",\"valuable\":\"value 来自拉丁语 valere「值、有力」，经古法语进入英语；再加 -able。值钱的，就是 valuable。\",\"famed\":\"fame 来自拉丁语 fama「传闻、名声」，其根 fari「说」。被人人说起的，就是 famed。\",\"intellectual\":\"intellect 来自拉丁语 intellectus「理解」，源头 intellegere「在之间挑选、领悟」：inter- + legere「选、读」。脑子挑理的活动，就是 intellectual。\",\"tread\":\"古英语 tredan「踩、走」，与德语 treten 同源。踩下去的步与胎面花纹，都是 tread。\",\"plunder\":\"借自德语 plündern「抢掠」，源头 Plunder 本义「家什、破烂」：三十年战争时士兵连破烂都抢。抢来的与抢本身，都是 plunder。\",\"indefinite\":\"in-「不」+ definite「确定的」：definite 源头是拉丁语 definire「划界定清」（de- + finis「边界」）。边界没划清的，就是 indefinite。\",\"disallow\":\"dis-「不」+ allow。allow 有两个来源合流：古法语 alouer「准许」（拉丁语 allaudare「称赞」）与 alouer「分配」（拉丁语 allocare「安置」）。不准，就是 disallow。\",\"inconsiderate\":\"in-「不」+ considerate「体贴的」：consider 源头是拉丁语 considerare「仔细看、考虑」，其构词有一说与 sidus「星辰」有关（观星一说）。不替人多看一眼的，就是 inconsiderate。深层如实标注为一说。\",\"incorrect\":\"in-「不」+ correct「正确的」（源头拉丁语 corrigere「拉直」：com- + regere「使直」）。没拉直的，就是 incorrect。\",\"shrinkage\":\"shrink 是古英语 scrincan「收缩、枯萎」；再加 -age。缩掉的量，就是 shrinkage。\",\"quietude\":\"quiet 来自拉丁语 quietus「安静的」，源头 quies「休息」；再加 -tude（仿拉丁语名词后缀）。静下来的状态，就是 quietude。\",\"miniature\":\"来自意大利语 miniatura「细密画」，源头是拉丁语 miniare「用铅丹（minium）涂红」——手抄本里的小插图。本义与「小」无关，是后人把它与 minor 一族混同才有了「微缩」义，如实标注这段误会史。\",\"deodorize\":\"de-「去除」+ odor（拉丁语 odor「气味」）+ -ize。把气味拿掉，就是 deodorize；除臭剂是 deodorant。\",\"dimple\":\"中古英语 dymple「小凹」，可能源自古英语或斯堪的纳维亚语，与 dip、deep 同族一说。脸颊上的小坑，就是 dimple。深层来源如实标注。\",\"collective\":\"同 collect：col- + legere「拾取」。拾到一堆里的，就是集体的 collective。\",\"screenplay\":\"screen + play 构成的 20 世纪电影词：写给银幕的剧本，就是 screenplay。\",\"portable\":\"来自拉丁语 portare「携带」+ -able：带得走的，就是 portable。\",\"factual\":\"fact 来自拉丁语 factum「做成的事」，源头 facere「做」；再加 -ual。已经「做成」的既成之事，就是 factual 所依的事实。\",\"clomp\":\"拟声构词：模仿重靴子踩地的闷响，可能是 clump 与 stomp 的混合。脚步咚咚地走，就是 clomp。\",\"vertical\":\"来自晚期拉丁语 verticalis「过天顶的」，源头 vertex「旋涡、头顶、极点」，其根 vertere「转」。从头顶垂下的直，就是 vertical。\",\"raffle\":\"来自古法语 rafle「一扫而空（的赌局）」，其更深来源有一说与日耳曼语 raffel 一系有关。抽彩把奖品一扫空，就是 raffle。深层来源如实标注。\",\"postscript\":\"post-「之后」+ script「写的」（拉丁语 scribere「写」）拼合的拉丁式词：正文之后再写的话，就是 postscript（附言，P.S.）。\",\"radiance\":\"radiant 来自拉丁语 radians「发光的」，源头 radiare「放射」，其根 radius「光线、辐条」。光芒四射的，就是 radiance。\",\"dabble\":\"可能源自荷兰语 dabbelen「在泥水里扑腾」，带反复动作的拟声色彩，未完全定论。鸭子在浅水里扑腾觅食的样子，就是 dabble；人浅尝辄止也是它。如实标注。\",\"summarize\":\"summary 来自拉丁语 summarium「概要」，源头 summa「总和、最高」，其根 summus「最高的」；再加 -ize。把总和说出来的，就是 summarize。\",\"finale\":\"借自意大利语 finale「最后的」，源头是拉丁语 finalis，其根 finis「终点」。乐章与剧集的收尾，就是 finale。\",\"honesty\":\"来自古法语 honesté，源头是拉丁语 honestas「荣誉、诚实」，其根 honor「荣誉」。在古罗马，诚实与体面本是一回事：honesty 就是 honestas。\",\"numbing\":\"numb 是古英语 numen「被拿住的」（niman「拿」的过去分词）：冻得像被攥住没知觉。再加 -ing。麻掉的，就是 numbing。\",\"apprentice\":\"来自古法语 aprentis「学徒」，源头是 apprendre「学习」，再往上是拉丁语 apprehendere「抓住」：ad- + prehendere「抓」。学徒就是跟在师傅身边「抓」手艺的人；与 comprehend（抓全→理解）同根。\",\"situation\":\"同 situs：所处的位置与处境，就是 situation。\",\"flashy\":\"flash 来源带拟声与突发感，可能源自中古英语 flasshen「泼溅」一系，未完全定论；再加 -y。一闪一闪抢眼的，就是 flashy。如实标注。\",\"reluctancy\":\"reluctant 来自拉丁语 reluctans「挣扎抗拒的」，源头 reluctari：re- + luctari「摔跤、挣扎」。一百个不情愿，就是 reluctancy。\",\"freedom\":\"free 是古英语 frēo「自由的」，本义「亲爱的、属于自家人的」——与奴隶相对；-dom「状态、领域」。自家人当家的状态，就是 freedom；与 friend 同根。\",\"aggressor\":\"来自拉丁语 aggredi「走上前去（攻击）」：ad- + gradi「行走」。先迈步逼近对方的一方，就是侵略者；与 progress（向前走）的 -gress 同根。\",\"destine\":\"来自拉丁语 destinare「固定、指定」，源头可能是 stare「站立」一族：命数被「钉」在那里，就是 destine；destination 是钉好的终点。\",\"maneuver\":\"经法语 manœuvre 而来，源头是中世纪拉丁语 manuopera「手工活」：manus「手」+ opera「工作」。用手摆弄的活，变成战场上的机动，就是 maneuver。\",\"genius\":\"来自拉丁语 genius「守护神、天赋」，源头 gignere「产生」。罗马人人有自己的守护灵；天生的那股灵气，就是 genius。\",\"devour\":\"来自拉丁语 devorare「吞下」：de- + vorare「吞食」。狼吞虎咽地吞，就是 devour；读起书来「吞」也用它，与 carnivorous 的 vor- 同根。\",\"throttle\":\"来源不完全确定：中古英语 throtlen，可能是 throat 加 -le 反复后缀构成——掐喉咙。油门（掐住进气）与勒杀，都是 throttle。如实标注为常见说法。\",\"totter\":\"中古英语 toteren「摇晃」，来源不完全确定，可能与古荷兰语 touteren 一系有关。晃着要倒的，就是 totter。如实标注。\",\"incubate\":\"来自拉丁语 incubare「躺在（蛋）上」：in- + cubare「躺」。母鸡躺在蛋上捂，就是 incubate（孵化）；病毒在体内「躺」着也是它。\",\"famished\":\"famish 是 famine「饥荒」的动词形式：famine 来自拉丁语 fames「饥饿」，经古法语进入英语。饿到极点的，就是 famished。\",\"mindless\":\"mind + -less「没有」构成：不动脑的，就是 mindless。\",\"engrave\":\"en- + grave「刻」（古英语 grafan「挖、刻」）构成。往硬面上挖字的，就是 engrave；与 grave（坟墓=挖的坑）同根。\",\"disband\":\"dis-「散」+ band「队伍、带子」：band 源头是日耳曼语 *band「束缚、旗帜」。队伍解了带子散伙，就是 disband。\",\"prickly\":\"prick 是古英语 prica「尖点、刺」；再加 -ly。满身刺的，就是 prickly；脾气一点就炸也用它。\",\"bangle\":\"借自印地语 bangrī「玻璃手镯」，19 世纪随英印贸易进入英语。印度女子腕上的环镯，就是 bangle。\",\"portrayal\":\"portray 来自古法语 portraire「画出」，源头是拉丁语 protrahere「拖出、展现」：pro- + trahere「拉」。把人「拉」到画面上的，就是 portrayal；与 portrait 同根。\",\"splurge\":\"词源存疑：19 世纪美国词，可能是 splash 与 surge 的混成，没有定论。大手大脚花钱，就是 splurge；这里不硬编。\",\"marinade\":\"借自法语 marinade「腌汁」，源头是意大利语或西班牙语 marinata，其根与拉丁语 mare「海」有关（腌汁如海水咸）。泡肉的汁，就是 marinade。深层关联如实标注为常见说法。\",\"foreboding\":\"fore-「预先」+ bode「预兆」构成。bode 来源不完全确定，可能与 bid「宣告」同族。事先闻到坏味的，就是 foreboding。如实标注。\",\"searching\":\"search 来自拉丁语 circare「绕着走、搜寻」，源头 circus「圆圈」：绕圈找。经古法语 cerchier 进入英语；再加 -ing。搜得透的（目光、提问），就是 searching。\",\"commercial\":\"commerce 来自拉丁语 commercium「贸易」：com- + merx「货物」。与货物买卖有关的，就是 commercial；与 market、merchant 的 merc- 同根。\",\"hunchback\":\"hunch「隆起」+ back「背」构成的 18 世纪词，取代了旧词 humpback。背隆成峰的，就是 hunchback。\",\"tripod\":\"来自希腊语 tripous「三脚的」：tri- + pous「脚」，经拉丁语进入英语。三条腿的架，就是 tripod。\",\"fleshly\":\"flesh 是古英语 flǣsc「肉」；再加 -ly。关乎肉身的，就是 fleshly（肉欲的、世俗的）。\",\"permissible\":\"permit 来自拉丁语 permittere「放行、允许」：per- + mittere「送」；再加 -ible。放得行的，就是 permissible。\",\"valid\":\"来自拉丁语 validus「强壮的、有效的」，源头 valere「有力」。有力站得住的（论点、证件），就是 valid。\",\"sideshow\":\"side + show 构成的 19 世纪马戏词：正场边上的小节目，就是 sideshow（穿插节目）。\",\"terminate\":\"同 terminare：到终点线为止的，就是 terminate。\",\"triumphant\":\"triumph 来自希腊语 thriambos「凯旋歌舞」，经拉丁语 triumphus、古法语进入英语。唱着凯歌回来的，就是 triumphant。\",\"repletion\":\"replete 来自拉丁语 repletus「被填满的」，源头 replere：re- + plere「满」。吃到满的状态，就是 repletion。\",\"mystical\":\"mystic 同 mystery 一系（希腊语 mystikos「秘密仪式的」）；再加 -al。通神的那股秘劲，就是 mystical。\",\"yacht\":\"借自荷兰语 jacht「快帆船」，是 jagt「追猎」的缩略——追海盗的快船。休闲的帆船，就是 yacht。\",\"expressible\":\"express 来自拉丁语 expressus「压出的、明言的」，源头 exprimere：ex- + premere「压」。能被「压」成话说出来的，就是 expressible。\",\"patriotic\":\"patriot 来自希腊语 patriōtēs「同胞」，源头 patris「祖国」，其根 patēr「父亲」：祖国是父亲之地。爱国的，就是 patriotic。\",\"temporary\":\"来自拉丁语 temporarius「暂时的」，源头 tempus「时间」。只占一时的，就是 temporary。\",\"summit\":\"来自古法语 sommette 一系，源头是拉丁语 summum「最高处」，其根 summus「最高的」。顶峰与峰会，都是 summit。\",\"mournful\":\"mourn 是古英语 murnan「哀悼、忧虑」，其更深来源与「记挂」同族一说；再加 -ful。满是哀的，就是 mournful。如实标注。\",\"bulletin\":\"经法语 bulletin 而来，源头是意大利语 bulletino「小公文」，其根是拉丁语 bulla「印玺、封印的文书」。盖着印的官方小文书，就是 bulletin；bullet（子弹）也是 bulla「小球」的后代。\",\"banquet\":\"借自法语 banquet，源头是意大利语 banchetto「小长凳」，是 banco「长凳」的指小形式。最早指坐在小凳上吃的点心，后来升格成盛宴。\",\"theatrical\":\"theatre 来自希腊语 theatron「观看的场所」，源头 theasthai「看」，经拉丁语、法语进入英语；再加 -ical。演给人看的夸张，就是 theatrical。\",\"rustic\":\"来自拉丁语 rusticus「乡下的」，源头 rus「乡野」。乡土气的，就是 rustic；与 rural 同根。\",\"resentment\":\"resent 来自法语 ressentir「强烈感受到」，源头是拉丁语 resentire：re- + sentire「感觉」。痛感在心里反复的，就是 resentment（怨恨）。\",\"disorient\":\"dis-「失去」+ orient「东方、定向」：orient 是拉丁语 oriens「升起的（太阳）」。找不着太阳升起的方向，就是 disorient（迷失方向）。\",\"mispronounce\":\"mis- + pronounce「发音」构成。pronounce 来自拉丁语 pronuntiare「宣告」：pro- + nuntiare「报告」。读错音的，就是 mispronounce。\",\"mislead\":\"mis- + lead（古英语 lǣdan「带领」）构成的中古英语词。带错路的，就是 mislead。\",\"elegance\":\"来自法语 élégance，源头是拉丁语 elegantia「讲究、品味」，其根 elegans「挑剔的、精致的」，与 eligere「挑选」同族一说。挑出来的精致，就是 elegance。深层关联如实标注为一说。\",\"acidity\":\"acid 来自拉丁语 acidus「酸的」，源头 acere「发酸」；-ity 表性质。酸的程度就是 acidity，与 acrid（辛辣的）同根。\",\"skewer\":\"来源不完全确定：中古英语 skeuwer，可能源自斯堪的纳维亚语（挪威语 skiver 一类？）或荷兰语。穿肉的扦子，就是 skewer。如实标注存疑。\",\"nickname\":\"中古英语 an ekename「附加名」被误切成 a nickname：eke 是古英语 ēac「也、另外」。多出来的那个名字，就是 nickname（绰号）——n 是误切粘上的，如实标注这段历史。\",\"mileage\":\"mile 来自拉丁语 milia「千（步）」，是 mille passus「一千步」的省称，经古英语进入英语；再加 -age。跑出的英里数，就是 mileage。\",\"octagonal\":\"octagon 是希腊语拼合词：oktō「八」+ gōnia「角」，经拉丁语进入英语；再加 -al。八个角的，就是 octagonal。\",\"nearsighted\":\"near + sighted「视力的」构成：只看得清近处的，就是 nearsighted。\",\"shapeless\":\"shape 是古英语 gesceap「创造、形状」，源头 scieppan「创造」；再加 -less。没成形的，就是 shapeless。\",\"continuation\":\"continue 来自拉丁语 continuare「使连绵」，源头 continuus「不断的」：con- + tenere「握住」。手一直握着不断线，就是 continuation。\",\"shady\":\"shade（古英语 sceadu）+ -y：有荫的地与有影子（可疑）的人，都是 shady。\",\"connective\":\"connect 来自拉丁语 connectere「系到一起」：con- + nectere「结、系」。把两头系上的，就是 connective（连接组织、连接词）。\",\"developmental\":\"develop 来自古法语 desveloper「展开、解开包裹」：des-「解开」+ voloper「包裹」（其更深来源不确定）。像卷轴一样展开的过程，就是 development。深层来源如实标注存疑。\",\"gull\":\"（海鸥）古英语一系或凯尔特语来源：威尔士语 gwylan「海鸥」同族一说；另有动词 gull「欺骗」源自古法语 gouler 一类词，两词同形异源。深层来源如实标注。\",\"notification\":\"notify 来自拉丁语 notificare「使知晓」：notus「已知的」+ facere「做」；再加 -ation。把消息做到人知道的，就是 notification。\",\"vegetation\":\"vegetate 来自拉丁语 vegetare「使生长」，源头 vegetus「有活力的」，其根 vegere「活跃」。长着的那一片绿，就是 vegetation。\",\"alphabetical\":\"alphabet 来自希腊语字母表头两个字母 alpha + beta，经晚期拉丁语 alphabetum 进入英语；再加 -ical。按字母表排，就是 alphabetical order。\",\"hilarity\":\"来自拉丁语 hilaritas「欢快」，源头 hilaris「高兴的」，再往上是希腊语 hilaros。笑到停不下来的，就是 hilarity；与 exhilarate 同根。\",\"infringe\":\"来自拉丁语 infringere「打破、违反」：in- + frangere「打破」。把规矩打破踏进去的，就是 infringe。\",\"splash\":\"plash「泼溅」的变体（加 s- 强化拟声）：水花四溅，就是 splash。\",\"fatality\":\"fatal 来自拉丁语 fatalis「命运注定的」，源头 fatum「命运、神谕」，其根 fari「说」——神说出口的，就是命。命里躲不过的死亡，就是 fatality。\",\"boutique\":\"借自法语 boutique「小店」，源头是普罗旺斯语 botica，再往上是拉丁语 apotheca「仓库」，其根是希腊语 apothēkē「存放处」。与 apothecary（药剂师）同源——都是「存货的地方」。\",\"prosperity\":\"prosper 来自拉丁语 prosperus「顺遂的」：pro- + spes「希望」一说构词——顺着希望走。兴旺的状态，就是 prosperity。深层构词如实标注为传统说法。\",\"miniscule\":\"minuscule 的常见误拼：minuscule 来自拉丁语 minusculus「稍小的」，源头 minus「更小」。把 minuscule 写成带 mini 的 miniscule，是受 miniature 影响的大众拼法，如实标注。\",\"inconsistency\":\"in-「不」+ consistency「一致性」：consist 源头是拉丁语 consistere「站定」（con- + sistere「使站」，其根 stare「站」）。前后站不到一块儿的，就是 inconsistency。\",\"humorist\":\"humor 来自拉丁语 humor「液体、体液」，经古法语进入英语：四体液决定脾气，脾气好就是 good humor；再加 -ist。专写逗乐文字的人，就是 humorist。\",\"doting\":\"dote 中古英语 doten「犯糊涂、溺爱」，来源不完全确定，可能源自中古荷兰语 doten「发狂」一说。爱到犯糊涂，就是 doting。如实标注。\",\"asocial\":\"a-「不、非」+ social（拉丁语 socius「伙伴」）。不是反对社会（antisocial），而是不往伙伴堆里凑，就是不合群的 asocial。\",\"rivet\":\"来自古法语 rivet「铆钉」，源头 river「钉牢」，其更深来源不确定。把两块铁钉死的，就是 rivet；目光被钉住也用它。深层来源如实标注存疑。\",\"hasty\":\"haste + -y：匆忙做出的，就是 hasty（草率的）。\",\"microscopic\":\"microscope 是 17 世纪按希腊语造的词：mikros「小的」+ skopein「看」。小到要靠它才看得见的，就是 microscopic。\",\"endangered\":\"endanger：en- + danger「危险」。danger 来自古法语 dangier「权力、危险」，源头是通俗拉丁语 *domniarium「主人的权力」——落在别人权力之下，就是危险。处境危殆的物种，就是 endangered。\",\"retrieve\":\"来自古法语 retrouver「重新找到」：re- + trouver「找到」（其更深来源有一说与拉丁语 turbare 一系或通俗拉丁语 *tropare 有关）。猎犬把猎物找回来叼着的，就是 retrieve。深层来源如实标注存疑。\",\"betrayal\":\"betray 来自古法语 trair「背叛」，源头是拉丁语 tradere「交出、交付」：trans-「过去」+ dare「给」。把自己人「交」到敌人手里，就是背叛；与 traitor、tradition（交付→传统）同根。\",\"specialty\":\"special 来自拉丁语 specialis「关乎种类的」，源头 species「种类、外观」；再加 -ty。专属一类的本事，就是 specialty（专长、特色菜）。\",\"entertainer\":\"entertain 来自古法语 entretenir「维持、招待」：entre「之间」+ tenir「握住」（源头拉丁语 tenere）。把客人「留住」不冷场的人，就是 entertainer。\",\"slumber\":\"中古英语 slumeren，是古英语 slūma「睡眠」的反复形式。打盹，就是 slumber。\",\"percentage\":\"percent 是拉丁语 per centum「每一百」的缩略；再加 -age。每一百里占多少，就是 percentage。\",\"knowledgeable\":\"knowledge 是中古英语 knowleche：know + -leche（表状态的后缀，与 -lock 同源）；再加 -able。肚里有货的，就是 knowledgeable。\",\"flammability\":\"flammable 是为纠正 inflammable 的歧义而造的词：flame 来自拉丁语 flamma「火焰」，源头 flagrare「燃烧」。烧得起来的性质，就是 flammability。\",\"feisty\":\"feist 本是美国南方方言里的小猎犬（fisting hound），源头与古英语 fīst「放屁」一说有关（臭气小狗）；再加 -y。个头小脾气大的，就是 feisty。深层来源如实标注为一说。\",\"silken\":\"silk 来源有一路：古英语 seoloc，源自晚期拉丁语 sericus「丝的」，再往上是希腊语 sērikos，其根是 Sēres「丝国人（中国人）」；再加 -en。丝一般的，就是 silken。\",\"gimmick\":\"词源存疑：20 世纪美国魔术师与推销员行话，指暗藏的机关与噱头；一说由 gimcrack「小玩意」改造而来，没有定论。这里不硬编。\",\"questionnaire\":\"借自法语 questionnaire「问卷」，源头 question「问题」，再往上是拉丁语 quaestio「查问」，其根 quaerere「寻求」。成套待答的问题，就是 questionnaire。\",\"abominable\":\"来自拉丁语 abominari「视为不祥而避开」：ab-「离开」+ omen「预兆」。古人见到坏兆头要躲开，后来词义变成「令人厌恶到想躲」。\",\"revolve\":\"来自拉丁语 revolvere「滚回、旋转」：re- + volvere「滚」。绕着圈滚的，就是 revolve。\",\"edibility\":\"edible 来自晚期拉丁语 edibilis「可吃的」，源头 edere「吃」；再加 -ity。能不能下口，就是 edibility；与 eat 不是同源词（eat 是日耳曼语），但义近。\",\"insistence\":\"insist 来自拉丁语 insistere「站在上面、坚持」：in- + sistere「站定」。脚钉在原地不走的，就是 insistence。\",\"snuffle\":\"snuff「吸鼻子」的反复形式（-le 表反复），带拟声色彩。鼻子呼哧呼哧的，就是 snuffle。\",\"naughty\":\"naught 是古英语 nāwiht「无物」：ne + ā + wiht「一点也没有」；再加 -y。古时指「一无所有的（穷）」，后指「不乖的」——词义滑坡如实标注。\",\"representation\":\"represent 来自拉丁语 repraesentare「重新呈现」：re- + praesentare「呈上」（praesens「在场」）。把不在场的重新摆到眼前的，就是 representation。\",\"narrative\":\"同 narrare：讲出来的故事与叙事手法，就是 narrative。\",\"entwine\":\"en- + twine「缠绕」构成。twine 本义是「双股搓成的绳」，源自古英语 twīn「双股」，与 two、twice 同根。像双股绳一样缠在一起，就是 entwine。\",\"feverish\":\"fever 是古英语 fēfor，源头是拉丁语 febris「发烧」，可能与 fovere「温暖」同族。烧得坐立难安的，就是 feverish。深层关联如实标注为一说。\",\"unbeatable\":\"un- + beatable「可打败的」构成：打不败的，就是 unbeatable。\",\"headline\":\"head + line 构成的报业词：版面顶头的那一行大字，就是 headline。\",\"dislocate\":\"dis- + locate「定位」（源头拉丁语 locus「地点」）按中世纪拉丁语 dislocare 造出。骨头出了位，就是 dislocate。\",\"seize\":\"来自古法语 saisir「占有、抓住」，源头可能是通俗拉丁语 *sacire，其根为日耳曼语 *satjan「安放」一说。一把抓住的，就是 seize。深层来源如实标注为一说。\",\"compassionate\":\"compassion 来自晚期拉丁语 compassio「共同受苦」：com- + pati「承受、受苦」。替别人一起疼，就是 compassionate；与 patient（忍耐/病人）的 pat- 同根。\",\"slogan\":\"借自苏格兰盖尔语 sluagh-ghairm「军队的呐喊」：sluagh「军队」+ ghairm「喊」。战场上齐喊的词，成了广告的 slogan（口号）。\",\"carriage\":\"来自盎格鲁-法语 cariage，动词 carier「运送」源头是晚期拉丁语 carricare「装车」，词干 carrus「车」（高卢语借词）。运货的车，后来专指马车与人的仪态（「承载」自己的方式）。\",\"nugget\":\"来源不完全确定：19 世纪词，可能由 nug「块」（方言）加指小后缀 -et 构成，或受 ingot 影响。天然金块，就是 nugget。如实标注。\",\"stretchability\":\"stretch 是古英语 streccan「拉伸」，与德语 strecken 同源；再加 -ability。拉得开的程度，就是 stretchability。\",\"melodramatic\":\"melodrama 是法语 mélodrame：希腊语 melos「歌」+ drama「剧」——配乐的戏。19 世纪配乐煽情剧的夸张，就是 melodramatic。\",\"rugged\":\"来自古诺斯语 rögg「粗毛、粗糙」加 -ed 一系：地势与面孔粗粝的，就是 rugged。\",\"knuckle\":\"中古英语 knokel「指节」，源自中古低地德语或荷兰语 knökel，是 Knochen「骨头」的指小形式。指头上的骨节，就是 knuckle。\",\"liberality\":\"liberal 来自拉丁语 liberalis「合乎自由人的、大方的」，源头 liber「自由的」。自由人才有的大方，就是 liberality。\",\"sleepless\":\"sleep 是古英语 slǣp，与德语 Schlaf 同源；再加 -less。睡不着的，就是 sleepless。\",\"inexperience\":\"in-「无」+ experience「经验」（源头拉丁语 experiri「试验」）。没试过的生手状态，就是 inexperience。\",\"distressful\":\"distress 来自古法语 destresse「窘迫」，源头是通俗拉丁语 *districtia「紧束」，其根是拉丁语 distringere「拉紧」。被勒得喘不过气的，就是 distressful；与 strict（拉紧的→严格的）同根。\",\"chaos\":\"来自希腊语 khaos「张开的空洞、深渊」，源头 khainein「张开嘴」。宇宙之初那片张着口的空无，就是 chaos；后来才指混乱。\",\"overrate\":\"over- + rate「估价」构成。rate 的来源有一说与拉丁语 rata「算定的（部分）」有关。估过高的，就是 overrate。深层来源如实标注为一说。\",\"ignorance\":\"ignore/ignorant 来自拉丁语 ignorare「不知道」：in-「不」+ gnarus「知晓的」（与希腊语 gignōskein 同根）。不知道的状态，就是 ignorance。\",\"knobby\":\"knob 来源不完全确定：中古英语 knobbe「瘤、节」，可能源自低地德语或斯堪的纳维亚语；再加 -y。满是疙瘩的，就是 knobby。如实标注。\",\"beret\":\"借自法语 béret，源头是加斯科涅方言 berret「帽子」，再往上是晚期拉丁语 birrus「带帽斗篷」。斗篷上的帽料做成的扁圆帽，就是 beret。\",\"invention\":\"invent 来自拉丁语 inventus「被发现的」，源头 invenire「遇上、发现」：in- + venire「来」。先是「撞见」，后是「造出」，就是 invention。\",\"harness\":\"来自古法语 harneis「装备、马具」，其更深来源有争议，一说源自古诺斯语 hernest「军粮」一系。给马套上的装备，就是 harness；引申为利用（套住自然力）。深层来源如实标注存疑。\",\"favorable\":\"favor 来自拉丁语 favor「好意、支持」，源头 favere「支持、偏袒」；再加 -able。风向站在你这边的，就是 favorable。\",\"deem\":\"古英语 dēman「判断、宣判」，是 doom「判决、命运」的动词形式。法官心里下的判，就是 deem；doomsday 是「审判日」。\",\"platform\":\"来自法语 plateforme「平坦的形状」：plat「平的」+ forme「形状」。平平的台子与政党的「纲领台」，都是 platform。\",\"rogue\":\"词源存疑：16 世纪俚语，指流浪汉与无赖；一说源自乞丐黑话 roger 一系，没有定论。捣蛋鬼与脱离群体的（rogue elephant），都是 rogue。这里不硬编。\",\"dapper\":\"来自中古荷兰语或中古低地德语 dapper「勇敢的、强壮的」，与德语 tapfer「勇敢」同源。词义从「壮实」转到「利落体面」，就是 dapper。\",\"rousing\":\"rouse 来源不完全确定（最早见于猎鹰术语）；再加 -ing。把人惊起、振奋起来的，就是 rousing。如实标注：rouse 的深层来源未有定论。\",\"snitch\":\"来源不完全确定：17 世纪俚语，先指「鼻子」，后指告密者，可能与 snatch 一系有关。打小报告的，就是 snitch。如实标注存疑。\",\"homestead\":\"home + stead「地点、位置」（古英语 stede）构成的古英语复合词。安家落户的那块地，就是 homestead。\",\"reservation\":\"reserve 来自拉丁语 reservare「留住、保留」：re- + servare「保持」。留住的座位与保留的意见，都是 reservation。\",\"inappropriate\":\"in-「不」+ appropriate「合适的」：appropriate 本义「据为己有」，源头是拉丁语 appropriare（ad- + proprius「自己的」）。不合时宜的，就是 inappropriate。\",\"fated\":\"fate 同 fatum：被「说」定的结局，就是 fated。\",\"preachy\":\"preach 来自拉丁语 praedicare「宣告、布道」：prae-「预先」+ dicare「宣告」；再加 -y。动不动说教的，就是 preachy。\",\"outrage\":\"来自古法语 outrage「过分、暴行」，源头是通俗拉丁语 *ultraticum，其根是拉丁语 ultra「超过」——过界的暴行。与 out 无关，是 ultra 的后代，如实标注这段常被误读的来源。\",\"coarsen\":\"coarse 来源不完全确定：中古英语作 cors，可能原是 course 的变体（指「寻常的、普通的」织物），未有定论；-en「使…」。使变粗，就是 coarsen。深层来源如实标注存疑。\",\"scrap\":\"借自古诺斯语 skrap「碎屑」，源头 skrapa「刮」。刮剩下的碎片与打架（另一义），就是 scrap。\",\"measurability\":\"measure 来自古法语 mesure，源头是拉丁语 mensura「量度」，其根 metiri「测量」；再加 -ability。量得出的，就是 measurability。\",\"reestablish\":\"re- + establish「建立」构成。establish 来自拉丁语 stabilire「使稳固」，源头 stabilis「稳的」。重新立稳的，就是 reestablish。\",\"memorialize\":\"memorial 来自拉丁语 memorialis「备忘的」，源头 memor「记着的」；再加 -ize。立碑留记的，就是 memorialize。\",\"throaty\":\"throat 是古英语 þrote「喉咙」，其更深来源有一说与「肿起」有关；再加 -y。嗓音从喉咙深处出的，就是 throaty。如实标注。\",\"snatch\":\"中古英语 snacchen「猛抓」，来源不完全确定，可能带拟声色彩或源自斯堪的纳维亚语。一把抢过的，就是 snatch。如实标注。\",\"reassemble\":\"re- + assemble「集合」构成。assemble 源头是通俗拉丁语 *assimulare「聚到一起」。散了再聚的，就是 reassemble。\",\"handicraft\":\"hand + craft「手艺」构成，中古英语作 handcraft，后受 handicraft 中 handy 一系影响改拼。手做的工艺，就是 handicraft；craft 源头是古英语 cræft「力量、技艺」。\",\"sidesplitting\":\"side + splitting「劈开的」构成：笑到两肋（sides）要裂的，就是 sidesplitting。\",\"reproduction\":\"re- + production「生产」构成：再生产出来的，就是 reproduction（复制、繁殖）。\",\"limitation\":\"limit 来自拉丁语 limes「边界、田界」（limitis）；再加 -ation。边界划到哪，事就办到哪，就是 limitation。\",\"trickery\":\"trick 来自古法语 triche「欺骗」，源头 trichier「作弊」，其更深来源有一说与拉丁语 tricari「耍花招」有关；再加 -ery。耍的花招，就是 trickery。深层来源如实标注。\",\"classical\":\"classic 来自拉丁语 classicus「第一等的（公民等级）」，源头 classis「等级、船队」。罗马人按财产分的头等，后来指一流的典范之作，就是 classical。\",\"fizzle\":\"fizz 是拟声词，模仿气泡嘶嘶声；fizzle 先指无声地漏气，后指事情虎头蛇尾地熄火。拟声来源如实标注。\",\"randomize\":\"random 来自古法语 randon「猛冲、随意」，源头 randir「疾驰」，其根是日耳曼语 *rand「边缘、奔跑」一说；再加 -ize。让顺序全凭运气的，就是 randomize。深层来源如实标注。\",\"travail\":\"来自古法语 travail「劳苦、阵痛」，源头有一说与通俗拉丁语 *tripalium「三桩刑具」有关——劳作如受刑。此说流传广，如实标注为常见解释。\",\"adventuresome\":\"adventure 来自拉丁语 adventura「将要发生的事」，源头 advenire「到来」：ad- + venire「来」。专找「将要发生的事」的人，就是爱冒险的；再加 -some「有…倾向的」。\",\"inspection\":\"inspect 来自拉丁语 inspectare「看进、查验」，是 inspicere 的反复形式：in- + specere「看」。往里细看的，就是 inspection。\",\"carcass\":\"经古法语 carcois、盎格鲁-法语 carcas 而来，更深来源不确定，可能与拉丁语 caro「肉」一类词有关。只剩肉与骨的躯壳，就是 carcass。深层来源如实标注存疑。\",\"optional\":\"option 来自拉丁语 optio「选择权」，源头 optare「选择、希望」；再加 -al。可以选的，就是 optional。\",\"haunted\":\"haunt 来自古法语 hanter「常去、出没」，其更深来源有一说与日耳曼语 *haimat「家」有关（回家般地常来）。鬼常来的房子，就是 haunted。深层来源如实标注为一说。\",\"disavow\":\"dis-「否认」+ avow「承认」：avow 来自古法语 avouer，源头是拉丁语 advocare「传唤、作证」。说过的话再收回去否认，就是 disavow；与 advocate（代言人）同根。\",\"clunker\":\"clunk（拟声词，模仿金属闷响）+ -er 构成的美国口语词。开起来哐当响的破车，就是 clunker。\",\"marital\":\"来自拉丁语 maritalis「婚姻的」，源头 maritus「丈夫、已婚的」，其更深来源不确定。关乎婚姻的，就是 marital。深层来源如实标注存疑。\",\"reflective\":\"reflect 来自拉丁语 reflectere「折回、反射」：re- + flectere「弯」。光与心思折回来的，就是 reflective。\",\"demount\":\"de-「向下、卸下」+ mount（源头拉丁语 mons「山」，引申「登上」）构成。从架子上、马上卸下来，就是 demount。\",\"slope\":\"来源不完全确定：中古英语 slope，可能是 aslope「倾斜地」的缩略，其根与 slip 一系有关。斜面与斜坡，就是 slope。如实标注。\",\"dolt\":\"中古英语作 dolt，可能是 dull「迟钝」的变体或与 dol「愚蠢」一类词有关，未完全定论。木头脑袋，就是 dolt。如实标注存疑。\",\"bundled\":\"bundle 是中古英语 bundel「捆」，与 bind「捆绑」同出日耳曼语 *bund-。捆成一包出售，就是 bundled；软件捆绑销售也用它。\",\"gratitude\":\"来自晚期拉丁语 gratitudo「感激」，源头 gratus「令人愉快的、感恩的」。心里记着别人的好，就是 gratitude。\",\"observe\":\"来自拉丁语 observare「守望、留意」：ob- + servare「看守、保留」。守着看、守着规矩，都是 observe。\",\"finance\":\"来自古法语 finance「付款、赎金」，源头是中世纪拉丁语 financia，其根 finire「了结」（finis「终点」）——把账了结。钱的事了结来、了结去，就成了 finance。\",\"refine\":\"re- + fine「精细的」构成（经法语 raffiner 的近亲）：fine 源头是拉丁语 finis「终点」——做到极致的细。提纯与文雅，都是 refine。\",\"perseverance\":\"persevere 来自拉丁语 perseverare「坚持到底」：per- + severus「严肃的、严格的」。严到底的劲，就是 perseverance。\",\"cherish\":\"来自古法语 cherir「珍爱」，词干 cher「亲爱的」，源头是拉丁语 carus「贵的、亲爱的」。当成宝贝疼，就是 cherish；与 charity（爱、施舍）的 car- 同根。\",\"moisturize\":\"moisture 来自古法语 moist「潮湿的」，源头可能是拉丁语 mucidus「发黏的」受 musteus「新酿的」影响，未完全定论；再加 -ize。给皮肤补水的，就是 moisturize。深层来源如实标注。\",\"terrific\":\"来自拉丁语 terrificus「令人恐惧的」：terrere「吓」+ facere「做」。本义是吓人，20 世纪滑向「棒极了」——词义大翻身，如实标注。\",\"grubby\":\"grub 本义「蛆、幼虫」，源头是中古英语 grubben「掘土」（与 groove、grave 的挖根同族）；再加 -y。像在土里爬过一样脏的，就是 grubby。\",\"clumpy\":\"clump 来源不完全确定，可能源自中古低地德语 klumpe「一团」，与 clamp 同族；-y 表性质。一坨一坨的，就是 clumpy。如实标注：此说较可信但未成定论。\",\"ruffle\":\"来源不完全确定：中古英语 ruffelen，可能源自低地德语或斯堪的纳维亚语，指弄皱、起波。衣边的褶与心里的乱，都是 ruffle。如实标注。\",\"promotional\":\"promote 来自拉丁语 promotus「被推向前的」，源头 promovere：pro- + movere「移动」；再加 -al。往前推销的，就是 promotional。\",\"scam\":\"词源存疑：20 世纪美国骗子行话，可能与 scamp「无赖」或 carnival 俚语有关，没有定论。骗局，就是 scam；这里不硬编。\",\"forfeit\":\"来自古法语 forfait「过犯、罚金」，源头是通俗拉丁语 *foris factum「做在（规矩）之外的事」：foris「外面」+ facere「做」。做出了格要付的代价，就是 forfeit。\",\"vibration\":\"vibrate 来自拉丁语 vibrare「抖动、挥舞」。抖个不停的，就是 vibration。\",\"slacker\":\"slack + -er：松劲偷懒的人，就是 slacker（一战时专指逃兵役者）。\",\"fleeting\":\"fleet（动词）是古英语 flēotan「漂浮、飞逝」，与 float 同根。像浮光一样掠过的，就是 fleeting。\",\"meditate\":\"来自拉丁语 meditari「沉思、练习」，源头是印欧语 *med-「度量、考虑」。在心里反复度量的，就是 meditate。\",\"sass\":\"sassy 的回构：sass 来源不完全确定，可能是 sauce「酱汁→无礼」的变体（saucy 一系）。顶嘴与俏皮话，就是 sass。如实标注。\",\"zippy\":\"zip 是拟声词，模仿快速划过的嘶声；再加 -y。利落带劲的，就是 zippy。\",\"nothingness\":\"nothing（no + thing）+ -ness 构成：空无的状态，就是 nothingness。\",\"indestructible\":\"in-「不」+ destructible「可毁的」（源头拉丁语 destruere「拆建」：de- + struere「堆建」）。拆不掉的，就是 indestructible。\",\"deflower\":\"来自晚期拉丁语 deflorare「摘花」：de- + flos「花」（floris）。把花摘掉，就是 deflower；引申义由此而来。\",\"tighten\":\"tight 来源不完全确定：中古英语 thight，借自古诺斯语 þéttr「密的、紧的」一系；再加 -en。勒紧的，就是 tighten。如实标注。\",\"chide\":\"古英语 cīdan「责备、争吵」，来源不完全确定，可能带拟声色彩。开口数落人，就是 chide。如实标注存疑。\",\"senseless\":\"sense 来自拉丁语 sensus「感觉」，源头 sentire「感觉」；再加 -less。没感觉、没道理的，就是 senseless。\",\"complexion\":\"来自拉丁语 complexio「结合、体质」，源头 complecti「环抱、交织」：com- + plectere「编织」。古人认为气色是体液「交织」的结果；面上的织纹，就是 complexion。\",\"numerical\":\"numeric 按拉丁语 numerus「数」造；再加 -al。用数字表示的，就是 numerical。\",\"jolt\":\"来源不完全确定：可能是 joll「猛撞」（中古英语）与 bolt 等词的混合，带拟声色彩。猛地一颠，就是 jolt。如实标注。\",\"privileged\":\"privilege 来自拉丁语 privilegium「针对个人的法律」：privus「私人的」+ lex「法」。法律单给他开的门，就是 privileged（有特权的）。\",\"bleary\":\"blear「使（眼睛）发花」词源存疑：中古英语已有 blere 一词，但它从哪来、与哪种语言的词同源，都没有定论。眼睛被睡意糊住睁不开，就是 bleary-eyed，这里不硬编来源。\",\"locality\":\"local 来自拉丁语 localis「地方的」，源头 locus「地点」；再加 -ity。所在的那一片，就是 locality。\",\"brooch\":\"来自古法语 broche「尖针、烤肉叉」，源头是通俗拉丁语 *brocca「尖物」。能别在胸前的尖针饰物，就是 brooch；与 broccoli（小尖芽）同源。\",\"victorious\":\"victory 来自拉丁语 victoria「胜利」，源头 vincere「征服」；再加 -ous。赢了的，就是 victorious。\",\"thrum\":\"拟声构词：模仿弦乐的嗡嗡拨动声（与德语一系的拟声词同类）。嗡嗡拨弦与织边流苏（另一义），就是 thrum。\",\"abusiveness\":\"abuse 来自拉丁语 abuti「误用、用坏」：ab-「偏离」+ uti「使用」；再加 -ive 与 -ness 构成名词。把东西用错方向，就是滥用与辱骂。\",\"handy\":\"hand + -y 构成的中古英语词：就在手边、顺手的，就是 handy。\",\"chute\":\"借自法语 chute「跌落、滑道」，是 choir「落下」的名词形式，源头是拉丁语 cadere「落」。东西顺着往下掉的道，就是 chute；parachute 是「防跌落」。\",\"ransom\":\"来自古法语 rançon「赎金」，源头是拉丁语 redemptio「赎回」：red- + emere「买」。把人买回来的价，就是 ransom；与 redemption 同根。\",\"ungenerous\":\"un- + generous「慷慨的」构成。generous 源头是拉丁语 generosus「出身高贵的」。不肯给的，就是 ungenerous。\",\"undisciplined\":\"un- + disciplined「受训的」构成。discipline 来自拉丁语 disciplina「训练」，源头 discipulus「学生」，其根 discere「学」。没管教的，就是 undisciplined。\",\"tattle\":\"中古英语 tatelen「叽叽喳喳」，借自中古荷兰语或低地德语，带拟声色彩。嚼舌根告密的，就是 tattle。\",\"tattered\":\"tatter 来源不完全确定：借自古诺斯语 töturr「破布」一系（与 tatterdemalion 同族）；再加 -ed。破成条的，就是 tattered。如实标注。\",\"naysay\":\"nay「不」（源自古诺斯语 nei）+ say 构成的古雅词：张口说不的，就是 naysay（反对）。\",\"shoplift\":\"shop + lift「偷」（lift 的古义「偷窃」，源自古诺斯语 lopt「空气」一系的黑话？此说不确定）构成的 17 世纪词。在店里「顺」东西的，就是 shoplift。lift 的偷窃义来源如实标注存疑。\",\"courteous\":\"courtesy 来自古法语 courtoisie「宫廷礼仪」，源头 court「宫廷」（拉丁语 cohors「庭院、随从」）。在宫廷里练出来的礼貌，就是 courteous。\",\"hemline\":\"hem（古英语 hem「边、镶边」）+ line 构成：裙摆的那条边线，就是 hemline。\",\"provoking\":\"provoke 来自拉丁语 provocare「叫出来挑战」：pro- + vocare「呼喊」。把火喊出来的，就是 provoking。\",\"rebirth\":\"re- + birth 构成的复合词：再活一次的，就是 rebirth。\",\"mistreat\":\"mis- + treat「对待」构成。treat 来自拉丁语 tractare「处理、拖动」，源头 trahere「拉」。待得粗暴的，就是 mistreat。\",\"positional\":\"position 来自拉丁语 positio「位置」，源头 ponere「放」；再加 -al。关乎站位的，就是 positional。\",\"shortfall\":\"short + fall「落下」构成的 19 世纪词：落下不够数的，就是 shortfall（缺口）。\",\"indentation\":\"indent 来自盎格鲁-法语 endenter「刻出锯齿」，源头是拉丁语 in- + dens「牙齿」——合同对折撕开成齿口验真。压出的齿痕与段首空格，都是 indentation。\",\"encircle\":\"en-「使成」+ circle「圆」构成。circle 经古法语而来，源头是拉丁语 circulus「小圆环」（circus「圆圈」的指小形式）。围成一圈，就是 encircle。\",\"possessive\":\"possess 来自拉丁语 possessus「被占有的」，源头 possidere：potis「能、主」+ sedere「坐」——坐稳了当主人。再加 -ive。攥着不放的，就是 possessive。\",\"prototype\":\"来自希腊语 prōtotypon「原始模型」：prōtos「第一的」+ typos「印记、模型」，经法语进入英语。第一个打样的，就是 prototype。\",\"realization\":\"realize 先指「使成真」，源头同 realis；再加 -ation。意识到与实现，都是 realization。\",\"midway\":\"mid + way 构成的古英语复合词：路走到一半的，就是 midway；游乐场大道也借此名。\",\"gingerly\":\"来源不完全确定：可能源自古法语 gensor「更娇嫩的」（gent「优雅的」比较级）一说，指举止轻柔。轻手轻脚地，就是 gingerly；与 ginger（姜）无关。如实标注。\",\"sidelong\":\"side + -long（古副词后缀，如 headlong）构成：斜着来的，就是 sidelong（侧眼的）。\",\"reunite\":\"re- + unite「联合」构成。unite 来自拉丁语 unire「合成一」，源头 unus「一」。散了再合一的，就是 reunite。\",\"spitfire\":\"spit + fire 构成的复合词：脾气像喷火一样的急人，就是 spitfire；二战名机 Spitfire 借此名。\",\"clinch\":\"clench「紧握」的变体（16 世纪起两词分工）：古英语一系的 *clencan 与 clinch 交错。钉子敲弯钉死、双手抱死对手，都是 clinch。\",\"infuriate\":\"按中世纪拉丁语 infuriare 造：in- + furia「狂怒」（furor「疯狂」）。怒到发疯地步地激怒，就是 infuriate；与 fury 同根。\",\"reckoning\":\"reckon 是古英语 gerecenian「讲述、计算」，与德语 rechnen「算」同源。算总账的日子，就是 reckoning。\",\"foreigner\":\"foreign 来自古法语 forain「外来的」，源头是晚期拉丁语 foranus「在外面的」，其根 foris「门外」。门外来的人，就是 foreigner。\",\"breathtaking\":\"breath + taking「夺去的」构成的 19 世纪复合词：美到把人的呼吸都夺走，就是 breathtaking。\",\"implied\":\"imply 来自拉丁语 implicare「卷入、缠绕」：in- + plicare「折」。话「折」在里面的，就是 implied（暗示的）；与 implicit 同根。\",\"classy\":\"class（源头拉丁语 classis「等级」）+ -y 构成的口语词。有档次，就是 classy。\",\"magnificence\":\"magnificent 来自拉丁语 magnificentia「宏伟」，源头 magnificus：magnus「大的」+ facere「做」。大手笔做出来的，就是 magnificence。\",\"suspicious\":\"suspect 来自拉丁语 suspectus「被怀疑的」，源头 suspicere「偷看、不信任」：sub- + specere「看」——从下面斜眼看。起疑的，就是 suspicious。\",\"resign\":\"来自拉丁语 resignare「解封、交还」：re- + signare「盖印」——把印交回去。辞职与认命，都是 resign。\",\"puckish\":\"Puck 是英国民间传说里的顽皮小精灵（古英语 pūca「小妖」）：莎士比亚《仲夏夜之梦》让它出了名。再加 -ish。精灵般顽皮的，就是 puckish。\",\"ladle\":\"古英语 hlædel「舀子」，源头 hladan「汲、舀」（与 load 同族）。舀汤的大勺，就是 ladle。\",\"fabulous\":\"来自拉丁语 fabulosus「传说中的」，源头 fabula「故事、传说」，其根 fari「说」。只在传说里才有的好，就是 fabulous；fable（寓言）与它同根。\",\"stretcher\":\"stretch + -er：把伤员「拉平抬走」的担架与撑鞋器，都是 stretcher。\",\"tropical\":\"tropic 来自希腊语 tropikos「（太阳）回转的」，源头 tropē「转」：太阳回头的那条线。再加 -al。回归线之间的，就是 tropical。\",\"overturn\":\"over + turn 构成的中古英语复合词：翻个底朝天的，就是 overturn。\",\"infrequent\":\"in-「不」+ frequent「频繁的」：frequent 源头是拉丁语 frequens「拥挤的、常来的」。来得稀的，就是 infrequent。\",\"misusage\":\"mis- + usage「用法」构成。usage 源头是拉丁语 usus「使用」。用错了的，就是 misusage。\",\"century\":\"来自拉丁语 centuria「百人队、百年」，源头 centum「一百」。罗马军团的百人队与一百年，共用一个 century。\",\"showery\":\"shower 是古英语 scūr「阵雨」；再加 -y。阵雨连连的，就是 showery。\",\"overstate\":\"over- + state「陈述」构成：说过头的，就是 overstate。\",\"yonder\":\"中古英语 yonder，是古英语 geond「遍、那」的派生（与 yon 同源）。在那边的，就是 yonder。\",\"tasteful\":\"taste 来自古法语 taster「摸、尝」，源头可能是通俗拉丁语 *taxitare（拉丁语 tangere「触摸」的反复形式）；再加 -ful。有品味的，就是 tasteful。深层来源如实标注为常见说法。\",\"snooze\":\"来源不完全确定：18 世纪词，可能与 snore 一系拟声词或方言词有关。打个盹，就是 snooze。如实标注。\",\"bestride\":\"古英语 bestrīdan：be- + strīdan「跨步」。双腿跨在两侧，就是 bestride；莎士比亚笔下「bestride the narrow world like a Colossus」用的正是它。\",\"whittle\":\"whittle 本指「小刀」：中古英语 thwitel，源头古英语 þwītan「切」。拿小刀削的，就是 whittle；削减开支也用它。\",\"grave\":\"（坟墓）古英语 græf「挖出的坑、坟」，源头 grafan「挖」。注意形容词 grave「严肃的」源自拉丁语 gravis「重的」，是同形异源——两条线在 grave 里相遇。\",\"alight\":\"古英语 ālīhtan「（从马上）下来」，由 līhtan「使轻、卸下」加前缀构成。轻身落地就是 alight；鸟落枝头、人下车，都用它。\",\"filth\":\"古英语 fȳlþ「污秽」，源头 fūl「腐臭的」（即 foul）。烂透了的脏，就是 filth。\",\"sheriff\":\"古英语 scīrgerēfa「郡长」：scīr「郡」+ gerēfa「长官」（即 shire + reeve）。郡里的长官，就是 sheriff。\",\"correspondent\":\"correspond 来自中世纪拉丁语 correspondere「相互应和」：cor- + respondere「回答」（re- + spondere「许诺」）。远在异地、靠书信「应和」本报的人，就是 correspondent（记者）。\",\"disastrous\":\"disaster 经法语、意大利语 disastro 而来：dis-「坏」+ astro「星」（拉丁语 astrum）——星象不吉。灾星当头的，就是 disastrous。\",\"misbehavior\":\"mis-「坏」+ behavior「行为」构成。behavior 是 behave 加 -ior（仿名词后缀）：behave 源头是 be- + have「持有、表现」。行止失当的，就是 misbehavior。\",\"reckless\":\"reck 是古英语 reccan「在意、顾及」，与德语 geruhen 同族；再加 -less「没有」。什么都不顾的，就是 reckless。\",\"mischievous\":\"mischief 来自古法语 meschef「不幸」，源头 meschever「遭遇不测」：mes-「坏」+ chever「临头」（chef「头」，拉丁语 caput）。祸临头的，后转指专惹祸的，就是 mischievous。\",\"broadside\":\"broad「宽」+ side「舷侧」构成：战舰一侧所有火炮同时开火叫 broadside；印刷上指大幅单面传单；引申为猛烈的言语齐射。\",\"distinguished\":\"distinguish 来自拉丁语 distinguere「分开、标出」：dis- + stinguere「刺、点」。在一堆人里被「点」出来的出众，就是 distinguished；与 distinct 同根。\",\"sidekick\":\"side + kick 构成的美国俚语：kick 先指裤子侧兜，后转指贴身伙伴——来源有一段黑话史。跟在身边的搭档，就是 sidekick。如实标注：kick 的伙伴义来历为俚语说法。\",\"millionaire\":\"借自法语 millionnaire：million 源头是意大利语 milione「大千」，是 mille「千」（拉丁语）的放大形式。有一百万的人，就是 millionaire。\",\"preservative\":\"preserve 来自晚期拉丁语 praeservare「预先守住」：prae- + servare「保持」。让食物守得久的，就是 preservative（防腐剂）。\",\"trifling\":\"trifle 来自古法语 trufle「小玩意、谎话」，其更深来源不确定；再加 -ing。不值一提的，就是 trifling。深层来源如实标注存疑。\",\"flowery\":\"flower 来自拉丁语 flos「花」，经古法语 flour 进入英语；再加 -y。辞藻开花的，就是 flowery；flour（面粉）与它同源——曾是谷物的「花」。\",\"horrific\":\"horror（拉丁语 horror「毛发竖立、战栗」）+ -fic「致使…的」。使人发抖的，就是 horrific。\",\"passionate\":\"passion 来自拉丁语 passio「承受、受难」，源头 pati「承受、受苦」。受苦般强烈的感情，就是 passionate；与 passive（被承受的）同根。\",\"captivation\":\"captivate 先是「俘获」（拉丁语 captivare，源头 captivus「俘虏」，再往上 capere「抓」），17 世纪后转指迷住人心。被美貌「抓」住，就是 captivation。\",\"argumentative\":\"argument 来自拉丁语 argumentum「论据」，源头 arguere「阐明、证明」；再加 -ative「爱…的」。总想把道理辩个明白，就是好争辩的。\",\"gifted\":\"gift 源自古诺斯语 gift「礼物、运气」，与 give 同根；再加 -ed「有…的」。天生被「送」了本事的，就是 gifted。\",\"objection\":\"object 来自拉丁语 obiectus「被扔到面前的」，源头 obicere：ob-「对着」+ iacere「投掷」；再加 -tion。把话扔回去顶着的，就是 objection。\",\"passive\":\"来自拉丁语 passivus「能承受的、被动的」，源头 pati「承受」。只受不动的，就是 passive。\",\"grungy\":\"词源存疑：20 世纪美国俚语，可能是 grunt、grunge 一类词的混成，或与 grimy + dingy 的押韵造词有关。脏兮兮邋遢的，就是 grungy；这里不硬编。\",\"inability\":\"in-「不」+ ability「能力」：ability 来自拉丁语 habilitas，其根 habere「有、能处理」。办不到，就是 inability。\",\"beauteous\":\"beauty 来自古法语 beauté，源头是通俗拉丁语 *bellitatem，其根是拉丁语 bellus「美的、可爱的」；-eous 是形容词后缀。诗体里把 beauty 拉长，就是 beauteous。\",\"thistle\":\"古英语 þistel「蓟」，与德语 Distel 同源，其更深来源不确定。苏格兰国花，就是 thistle。深层来源如实标注存疑。\",\"upstage\":\"up + stage「舞台」构成的剧场词：舞台后部（地势高）抢镜，就是 upstage（抢风头）。\",\"midwife\":\"古英语 midwif「接生妇」：mid「与…一起」（古义，源自古英语 mid「伴随」）+ wif「女人」。陪着产妇的女人，就是 midwife——mid 在这里不是「中间」。\",\"hollow\":\"古英语 holh「洞、凹处」，是 hol「空的」的名词形式，与 hole 同根。里面空的，就是 hollow。\",\"reappearance\":\"re-「再」+ appearance「出现」构成。appearance 来自拉丁语 apparere「显现」。再次露面的，就是 reappearance。\",\"ballad\":\"来自古法语 balade，源头是普罗旺斯语 balada「舞曲」，动词 balar「跳舞」再往上是晚期拉丁语 ballare「跳舞」。本是配着舞唱的歌，后来才专指叙事民谣；ball（舞会）与它同源。\",\"slight\":\"（轻微义与轻视义同源）中古英语 slight「平滑的、轻微的」，借自古诺斯语 sléttr「平的」或中古荷兰语 slicht「平的」。分量轻到可忽视的，就是 slight。\",\"gigantic\":\"giant 来自希腊语 gigas「巨人」（Gigantes 是神话里与诸神作战的巨人族），经拉丁语、法语进入英语；再加 -ic。大得像巨人的，就是 gigantic。\",\"gadget\":\"词源存疑：19 世纪水手俚语，指记不住名字的小装置；一说源自法语 gâchette「机件扣」，没有定论。小玩意儿，就是 gadget；这里不硬编。\",\"precondition\":\"pre- + condition「条件」构成：摆在前面的条件，就是 precondition。\",\"slithery\":\"slither 来源不完全确定：中古英语 slitheren，可能是 slide 的变体（带 -ther 反复后缀）。滑着爬的，就是 slithery。如实标注。\",\"sarcastic\":\"sarcasm 来自希腊语 sarkasmos「冷嘲」，源头 sarkazein「撕肉」：sark-「肉」——话像撕肉一样疼。带刺的，就是 sarcastic。\",\"toothy\":\"tooth 是古英语 tōþ，与拉丁语 dens 同出印欧语 *dent-；再加 -y。露着牙笑的，就是 toothy。\",\"impolite\":\"im-「不」+ polite「有礼的」：polite 来自拉丁语 politus「磨光的」，源头 polire「打磨」。没打磨过的粗糙言行，就是 impolite。\",\"soloist\":\"solo 借自意大利语 solo「独自的」，源头是拉丁语 solus「单独的」；再加 -ist。一个人唱/奏的，就是 soloist。\",\"repression\":\"repress 来自拉丁语 repressus「被压回的」，源头 reprimere：re- + premere「压」。压回心底的，就是 repression。\",\"invitation\":\"invite 来自拉丁语 invitare「邀请」，其更深来源不确定（有一说与 vocare 一族有关）。请人来的帖子与话，就是 invitation。深层来源如实标注存疑。\",\"talented\":\"talent 来自希腊语 talanton「天平、重量单位（塔兰特）」，经拉丁语、法语进入英语：本是钱币重量，《圣经》塔兰特寓言让它转指天赋。再加 -ed。天赋史如实标注。\",\"downfall\":\"down + fall 构成的中古英语复合词：从高处落到底，就是 downfall（垮台、暴雨倾盆）。\",\"logical\":\"logic 来自希腊语 logikē「推理（术）」，源头 logos「言说、理性」，经拉丁语、法语进入英语。合乎 logos 的，就是 logical。\",\"malfunction\":\"mal-「坏」（源头拉丁语 male「坏地」）+ function「功能」（源头拉丁语 fungi「履行」）拼合的 20 世纪词。功能坏了，就是 malfunction。\",\"defective\":\"defect 来自拉丁语 defectus「缺失、不足」，源头 deficere「缺乏」：de- + facere「做」。没「做」到位的，就是 defective。\",\"inescapable\":\"in-「无处」+ escapable「可逃的」：escape 源头是通俗拉丁语 *excappare「脱下斗篷逃走」（ex- + cappa「斗篷」一说）——追兵只抓住一件空斗篷。逃不掉的，就是 inescapable。深层如实标注为一说。\",\"scooter\":\"scoot 来源不完全确定：19 世纪词，可能源自斯堪的纳维亚语（与 shoot 同族一说）；再加 -er。滑着走的，就是 scooter。如实标注。\",\"disadvantageous\":\"disadvantage 经法语 désavantage 而来：dés-「反」+ avantage「优势」（源头 avant「在前」，拉丁语 abante）。处在别人后面的，就是 disadvantageous。\",\"jaunt\":\"来源不完全确定：16 世纪词，可能与法语或方言 jaunce「（使马）颠跑」有关。短途溜达一趟，就是 jaunt。如实标注存疑。\",\"smuggle\":\"借自低地德语 smuggeln 或荷兰语 smokkelen「偷运」，其更深来源与「钻、溜」一系词有关一说。偷着运的，就是 smuggle。深层来源如实标注。\",\"ravel\":\"借自荷兰语 ravelen「缠乱、拆开」，其更深来源不确定。线缠成团与拆线，ravel 两义兼有（与 unravel 几乎同义），如实标注这对奇特的同义反义词。\",\"regretful\":\"regret 来自古法语 regretter「哀悼、后悔」，其更深来源不完全确定（可能与斯堪的纳维亚语 grata「哭」同族一说）；再加 -ful。满是懊悔的，就是 regretful。深层来源如实标注。\",\"foamy\":\"foam 是古英语 fām「泡沫」，与拉丁语 spuma 同族；再加 -y。满是泡沫的，就是 foamy。\",\"squeamish\":\"中古英语 squeamous，是 Anglo-French escoymos 的变体，其更深来源不确定。胃浅易吐、过分讲究的，就是 squeamish。如实标注存疑。\",\"slaphappy\":\"slap + happy 构成的美国俚语：先指拳击手被打得晕乎发笑，后指乐呵呵没心没肺的，就是 slaphappy。\",\"infertile\":\"in-「不」+ fertile「肥沃的」（源头拉丁语 fertilis，其根 ferre「承载、生育」）。结不出果的，就是 infertile。\",\"departure\":\"同 depart：分开、启程，就是 departure；航班时刻表上的 departure 由此而来。\",\"frenzied\":\"frenzy 来自希腊语 phrenitis「脑炎、谵妄」，源头 phrēn「横膈膜、心智」，经拉丁语、法语进入英语。古人以为心智住在横膈膜；烧坏了的疯狂，就是 frenzied。\",\"idiotic\":\"idiot 来自希腊语 idiōtēs「平民、不任公职者」，源头 idios「自己的」：只顾自家事、不懂公共事务的人，后滑向「白痴」。idiotic 的这条词义滑坡如实标注。\",\"lyrical\":\"lyric 来自希腊语 lyrikos「用里拉琴唱的」，源头 lyra「里拉琴」，经拉丁语、法语进入英语；再加 -al。抒情如琴歌的，就是 lyrical。\",\"hostess\":\"host（源头拉丁语 hospes「主人/客人」，经古法语进入英语）+ -ess 表女性。招待客人的女主人，就是 hostess。\",\"scramble\":\"来源不完全确定：可能是 scamble「攀爬、争夺」的变体，与 scrap、grab 一系的拟形构词有关。爬抢成一团的，就是 scramble。如实标注。\",\"soft-spoken\":\"soft + spoken 构成的复合词：说话轻声的，就是 soft-spoken。\",\"stouthearted\":\"stout「结实的、勇敢的」（源自古法语 estout，其根为日耳曼语）+ hearted「有心的」构成。心够硬的，就是 stouthearted。\",\"recognizable\":\"recognize 来自拉丁语 recognoscere「重新认出」：re- + cognoscere「知道」；再加 -able。一眼认得出的，就是 recognizable。\",\"dosage\":\"dose 来自希腊语 dosis「给予的量」，源头 didonai「给」，经晚期拉丁语、法语进入英语；再加 -age。一次「给」多少，就是 dosage。\",\"basis\":\"来自希腊语 basis「底座、立足点」，经拉丁语进入英语，源头 bainein「行走、站立」。脚站住的那块地方，就是一切的基础；base 与它同源。\",\"entrust\":\"en- + trust「信任」构成。trust 源自古诺斯语 traust「信任、倚靠」，与 true 同族。把要紧事交到信得过的人手里，就是 entrust。\",\"timid\":\"来自拉丁语 timidus「害怕的」，源头 timere「怕」。怕生的，就是 timid。\",\"stagnant\":\"stagnate 来自拉丁语 stagnare「积水不流」，源头 stagnum「死水塘」。水不流的，就是 stagnant（停滞的）。\",\"panicky\":\"panic 来自希腊语 panikos「属于牧神潘的」：潘神的喊声能让羊群与军队无端惊恐。再加 -y。惊成一团的，就是 panicky。\",\"inhumane\":\"in-「不」+ humane「人道的」（源头拉丁语 humanus「人的」）构成。不把人当人的，就是 inhumane。\",\"misguidance\":\"mis- + guidance「引导」构成：被带错路的，就是 misguidance。\",\"dungeon\":\"来自古法语 donjon「主塔、地牢」，源头可能是通俗拉丁语 *domnionem「主人的（塔）」，其根是拉丁语 dominus「主人」。领主主塔底下的黑牢，就是 dungeon。\",\"unkindly\":\"un- + kindly「亲切地」构成：不亲切地，就是 unkindly。\",\"excitability\":\"excite 来自拉丁语 excitare「唤起、激起」：ex- + citare「催动」（ciere「使动」）；再加 -ability。一点就着的体质，就是 excitability。\",\"dreary\":\"古英语 drēorig「血淋淋的、悲伤的」，源头 drēor「血」，与 drēosan「落下」同族：本指血往下滴的惨状，后转指阴郁乏味。\",\"unpredictable\":\"un- + predictable「可预测的」构成。predict 源头是拉丁语 praedicere「预言」。说不准的，就是 unpredictable。\",\"godless\":\"god（古英语 god）+ -less「没有」构成。不认神的，就是 godless。\",\"straggle\":\"来源不完全确定：中古英语 stragelen，可能是 stray 的反复形式变体。掉队散漫的，就是 straggle。如实标注。\",\"screwy\":\"screw 来源有一路：经古法语 escroue 而来，源头是拉丁语 scrofa「母猪」一说（螺纹如猪尾？此说有争议）；再加 -y。脑子像螺丝松了的，就是 screwy。深层来源如实标注存疑。\",\"maximize\":\"maximum 是拉丁语 maximum「最大量」，是 magnus「大」的最高级中性形式；再加 -ize。推到最大的，就是 maximize。\",\"charmed\":\"charm 来自拉丁语 carmen「歌、咒语」，经古法语 charme 进入英语。被咒语迷住的，就是 charmed；charmed life 是「有符护身的命」。\",\"snuggle\":\"snug 来源不完全确定：先指船「收拾利落」，可能源自斯堪的纳维亚语；再加 -le 反复后缀。偎紧取暖的，就是 snuggle。如实标注。\",\"haze\":\"来源不完全确定：可能源自水手词 hawse 或由 hare 一类词演变，17 世纪出现。薄雾与懵懂，都是 haze。如实标注存疑。\",\"radiology\":\"radio-「辐射」（源头拉丁语 radius「射线」）+ -logy「学问」拼合的 20 世纪学科词。用射线看病的，就是 radiology。\",\"misinterpret\":\"mis- + interpret「解释」构成。interpret 来自拉丁语 interpretari「解说」，源头 interpres「中间人、译者」。解错了的，就是 misinterpret。\",\"disintegration\":\"dis-「散」+ integration「整合」：integer 是拉丁语「完整未动的」（in- + tangere「触摸」一说构词）。整块散成碎片，就是 disintegration。深层构词如实标注为传统说法。\",\"scenery\":\"scene 来自希腊语 skēnē「帐篷、舞台布景」，经拉丁语 scaena 进入英语；再加 -ery。布景连成的风景，就是 scenery。\",\"strategic\":\"strategy 来自希腊语 stratēgia「将军之职」，源头 stratēgos「将军」：stratos「军队」+ agein「带领」。带兵的学问，就是 strategic（战略的）。\",\"heap\":\"古英语 hēap「一堆、人群」，与德语 Haufen 同源。堆成堆的，就是 heap。\",\"dreadful\":\"dread 是古英语 ondrǣdan「畏惧」的后代，其更深来源不确定；-ful「充满」。让人心里发毛的，就是 dreadful。深层来源如实标注存疑。\",\"midterm\":\"mid-「中间」+ term「期限、学期」构成：学期过半的考试，就是 midterm。term 源头是拉丁语 terminus「界限」。\",\"retort\":\"来自拉丁语 retortus「被扭回的」，源头 retorquere：re- + torquere「扭」——把话扭回去。回嘴与蒸馏瓶（扭颈瓶），都是 retort。\",\"headmaster\":\"head + master 构成：学校里坐在头把交椅的人，就是 headmaster（校长）。\",\"giggle\":\"拟声构词：模仿压不住的咯咯笑声，中古英语 gigelen。笑出声的，就是 giggle。\",\"centerpiece\":\"center（源自希腊语 kentron「尖点、圆心」，经拉丁语、法语进入英语）+ piece 构成：摆在桌子正中央的那件，就是 centerpiece。\",\"sanitize\":\"sanitary 来自拉丁语 sanitas「健康」，源头 sanus「健全的」；再加 -ize。消毒与「净化」文本，都是 sanitize。\",\"responsibility\":\"responsible 来自拉丁语 responsus「被回答的」，源头 respondere：re- + spondere「许诺」；再加 -ibility。许诺要答的，就是 responsibility。\",\"installation\":\"install 来自中世纪拉丁语 installare「安放到席位上」：in- + stallum「席位」（日耳曼语借词）。把人、设备安放到位，就是 installation。\",\"antisocial\":\"anti-「反对」+ social。social 来自拉丁语 socius「伙伴、同盟者」。躲着伙伴、跟社会对着干，就是 antisocial。\",\"brotherhood\":\"brother + -hood（古英语 -hād「状态、身份」）。同胞之情与结社身份，都是 brotherhood；hood 在这里不是帽子，是「状态」。\",\"zany\":\"借自意大利语 zanni「丑角」，是威尼斯方言对 Giovanni（约翰）的昵称——即兴喜剧里的仆人丑角专名。疯癫搞笑的，就是 zany。\",\"majority\":\"major 是拉丁语 maior「更大的」（magnus 的比较级）；再加 -ity。更大的一半，就是 majority。\",\"blabbermouth\":\"blabber（中古英语 blaberen「含糊地咕哝」，拟声色彩浓）+ mouth 构成的美国口语词。嘴像关不住的水龙头，就是 blabbermouth。\",\"enthrone\":\"en-「使上」+ throne「王座」构成。throne 来自希腊语 thronos「高座」，经拉丁语、古法语进入英语。扶上高座，就是 enthrone。\",\"tailgate\":\"tail「尾」+ gate「门」构成的美国词：卡车后挡板放下野餐，就是 tailgate（车尾派对）；贴尾行驶也是它。\",\"shameless\":\"shame + -less「没有」构成：不知羞的，就是 shameless。\",\"contaminant\":\"contaminate 来自拉丁语 contaminare「弄脏」，可能与 tangere「接触」同族（*con-tag- 一说）：碰上脏东西就被带坏。污染物就是 contaminant。此关联为学界常见说法，如实标注。\",\"thorny\":\"thorn 是古英语 þorn「刺」，与德语 Dorn 同源；再加 -y。满是刺的，就是 thorny（棘手的）。\",\"profitable\":\"profit 来自拉丁语 profectus「进展、收益」，源头 proficere：pro- + facere「做」；再加 -able。做得出收益的，就是 profitable。\",\"tranquil\":\"来自拉丁语 tranquillus「平静的」，其构词有一说为 trans- + quies「安静」一系，未定论。静下来的，就是 tranquil。深层如实标注存疑。\",\"formerly\":\"former（古英语 forma「第一、在先」的后代）+ -ly。从前排在前面的时光，就是 formerly。\",\"unanswerable\":\"un- + answerable「可答的」构成。answer 是古英语 andswaru「回应」：and-「相对」+ swaru「宣誓」。驳不倒的，就是 unanswerable。\",\"hogwash\":\"hog「猪」+ wash「洗」构成：wash 在这里是「泔水」义（洗锅水喂猪）。喂猪的泔水，引申为废话，就是 hogwash。\",\"deportation\":\"deport 来自拉丁语 deportare「搬走、流放」：de- + portare「携带」。把人「搬」出国境，就是 deportation。\",\"template\":\"templet 的变体，受 plate 影响改拼：templet 来自法语 templet「织机横杆、模板」，是 temple 一词的指小形式，其根源与拉丁语 templum 一系有关一说。照着切的板，就是 template。深层来源如实标注。\",\"reduplicate\":\"来自拉丁语 reduplicare「双倍重复」：re- + duplicare「对折」（duo「二」+ plicare「折」）。叠着来的，就是 reduplicate。\",\"splendid\":\"来自拉丁语 splendidus「灿烂的」，源头 splendere「发光」。亮得耀眼的好，就是 splendid。\",\"serene\":\"来自拉丁语 serenus「晴朗的、平静的」。天晴了的人心，就是 serene。\",\"compressed\":\"compress 来自拉丁语 compressus「压紧」，源头 comprimere：com- + premere「压」。把体积压小，就是 compressed；与 press 同根。\",\"uneventful\":\"un- + eventful「多事的」构成：没事发生的，就是 uneventful（平淡的）。\",\"affectation\":\"来自拉丁语 affectare「刻意追求、装作」，是 afficere「影响」的反复形式：ad- + facere「做」。刻意「做」出某种样子，就是做作。\",\"absurd\":\"来自拉丁语 absurdus，原义「走调的、刺耳的」：ab-「偏离」+ surdus「聋的、发闷的」。声音不合调，引申为道理不合逻辑。\",\"typical\":\"type 来自希腊语 typos「印记、模子」，源头 typtein「打」，经晚期拉丁语进入英语；再加 -ical。合模子的，就是 typical。\",\"referral\":\"refer + -al（名词后缀）：被「带」到专家那里的转诊，就是 referral。\",\"seldom\":\"古英语 seldan「稀罕地」，源头 seld「稀奇的」，与德语 selten 同源。本就是稀罕的事：很少，就是 seldom。\",\"compensation\":\"compensate 来自拉丁语 compensare「抵平、称平」：com- + pensare「称量」（pendere 的反复形式）。这边亏的在那边称平，就是 compensation。\",\"shrill\":\"中古英语 shrille「尖锐的（声音）」，带拟声色彩，可能源自古英语 scralletan 一类拟声词。刺耳的尖声，就是 shrill。\",\"faceless\":\"face（源头拉丁语 facies「面容」）+ -less「没有」构成。没脸可认的，就是 faceless（匿名的、无个性的）。\",\"coating\":\"coat 经古法语 cote 而来，源头可能是日耳曼语 *kotta「粗布衣」；-ing 表覆盖层。裹在外面的一层，就是 coating。\",\"readiness\":\"ready 是古英语 gerǣde「备好的」，源头 gerād「装备齐全」；再加 -ness。备好的状态，就是 readiness。\",\"dependable\":\"depend 来自拉丁语 dependere「垂挂于、依靠」：de- + pendere「悬挂」。整个人「挂」在他身上不会掉的，就是 dependable；pendant（吊坠）与它同根。\",\"attest\":\"来自拉丁语 attestari「作证」：ad- + testari「作证」，词干 testis「证人」。站出来当证人，就是 attest；testament（遗嘱）、testify 都是 testis 的一家。\",\"maniac\":\"mania 来自希腊语 mania「疯狂」，经晚期拉丁语进入英语；再加 -ac。疯魔了的人，就是 maniac。\",\"inconsequent\":\"in-「不」+ consequent「随之而来的」（源头拉丁语 consequi「跟随」：con- + sequi）。跟不上逻辑的，就是 inconsequent。\",\"haul\":\"来自中古英语 halen「拖、拉」，源头是古法语 haler，其根是日耳曼语 *halon「召唤、取来」。使劲拖的，就是 haul；与 hale 同源。\",\"chamber\":\"来自古法语 chambre，源头是拉丁语 camera「拱顶房间」，再往上是希腊语 kamara「拱顶」。有拱顶的屋子，就是 chamber；camera（相机）的「暗箱」也是它。\",\"textual\":\"text 来自拉丁语 textus「织物、文本」，源头 texere「织」：话是织出来的。关乎原文的，就是 textual。\",\"indication\":\"indicate 来自拉丁语 indicare「指出」：in- + dicare「宣告」，与 dicere「说」同族。手指点出来的征兆，就是 indication。\",\"outpouring\":\"out + pouring「倾倒」构成的复合词：感情与人群倾泻而出的，就是 outpouring。\",\"fragmentary\":\"fragment 来自拉丁语 fragmentum「碎片」，源头 frangere「打破」。只剩碎片的，就是 fragmentary。\",\"seeming\":\"seem 来源不完全确定：中古英语 semen，借自古诺斯语 sœma「适合、像样」一系；再加 -ing。表面看来的，就是 seeming。如实标注。\",\"companionable\":\"companion 来自古法语 compaignon「同伴」，源头是通俗拉丁语 *companio「一起吃面包的人」：com- + panis「面包」。分吃同一块面包的人，好处伴就是 companionable。\",\"agitation\":\"来自拉丁语 agitare「反复驱赶、摇动」，是 agere「做、驱动」的反复形式。心里被反复摇晃，就是激动与骚动。\",\"undeniable\":\"un- + deniable「可否认的」构成。deny 来自拉丁语 denegare「否认」：de- + negare「说不」。赖不掉的，就是 undeniable。\",\"enthusiastic\":\"enthusiasm 来自希腊语 enthousiasmos「神灵附体」，源头 entheos「神在体内」：en- + theos「神」。古人把狂热当神附身；热忱满格的，就是 enthusiastic。\",\"starvation\":\"starve 是古英语 steorfan「死」，本指一切死亡，饥饿义是后窄化的；再加 -ation。饿死的，就是 starvation；德语 sterben（死）与它同源。\",\"sermon\":\"来自拉丁语 sermo「谈话、布道」，其构成有一说为 ser-「连接」（serere）一系——把话串起来讲。讲道，就是 sermon。深层如实标注为一说。\",\"concussive\":\"concussion 来自拉丁语 concussio「剧烈摇晃」，源头 concutere：con- + quatere「摇、打」。脑子被摇坏，就是 concussive 的冲击；与 quash（摇碎→撤销）同根。\",\"slimy\":\"slime 是古英语 slīm「黏液」，与拉丁语 limus「泥」同族一说；再加 -y。黏糊糊的，就是 slimy。深层关联如实标注。\",\"snowball\":\"snow + ball 构成的中古英语复合词：越滚越大的，就是 snowball（滚雪球效应）。\",\"overcast\":\"over + cast「投、覆」构成的中古英语词：云把天全「覆」住的，就是 overcast（阴天的）。\",\"homey\":\"home + -y 构成的口语词：像家一样舒服的，就是 homey。\",\"frailty\":\"frail 来自古法语 fraile，源头是拉丁语 fragilis「易碎的」。人像薄瓷一样易碎的弱点，就是 frailty。\",\"prearrange\":\"pre-「预先」+ arrange「安排」构成。arrange 来自古法语 arangier：a- + rangier「排列」（rang「行列」，日耳曼语来源）。事先排好的，就是 prearrange。\",\"voyage\":\"来自古法语 voiage，源头是拉丁语 viaticum「旅费、路粮」，其根 via「路」。备好路粮上路的远行，就是 voyage。\",\"hyperactive\":\"hyper-「过度」（希腊语 hyper「在上、过」）+ active（源头拉丁语 agere「驱动」）拼合。劲大得停不下来的，就是 hyperactive。\",\"jagged\":\"jag 来源不完全确定：中古英语 jagge「锯齿、尖突」，可能与扎、刺的拟形构词有关；再加 -ed。边缘全是齿的，就是 jagged。如实标注。\",\"sidle\":\"由 sideling「侧着的」回构：side + -ling。侧着身子蹭过去的，就是 sidle。\",\"overhang\":\"over + hang（古英语 hangian）构成：悬在外面的，就是 overhang。\",\"peaceable\":\"peace 来自拉丁语 pax「和平」，经古法语 pais 进入英语；再加 -able。性子主和的，就是 peaceable。\",\"blubber\":\"中古英语 bluber「泡沫、海沫」，是拟声构词，与 bubble 同族，本指鲸脂翻滚如泡的样子。后来既指鲸脂，也指哭得抽抽搭搭。\",\"stubby\":\"stub 是古英语 stybb「树桩」，借自古诺斯语 stubbi；再加 -y。短粗如桩的，就是 stubby。\",\"scrapbook\":\"scrap + book 构成的 19 世纪词：贴碎片（剪报、照片）的本子，就是 scrapbook。\",\"taxation\":\"tax 来自拉丁语 taxare「估量、征税」，源头 tangere「触摸」一系（摸一摸估个价）；再加 -ation。估价收钱的，就是 taxation；与 task 同源。\",\"feathery\":\"feather 是古英语 feþer，与德语 Feder 同源，源头是印欧语 *pet-「飞」；再加 -y。轻得像羽毛的，就是 feathery；与翼的希腊语 pteron 同族。\",\"demolition\":\"demolish 来自拉丁语 demoliri「拆毁」：de- + moliri「建造、费力地堆」（moles「大堆、巨石」）。把费力堆起来的再费力拆掉，就是 demolition。\",\"capability\":\"capable 来自晚期拉丁语 capabilis「能容纳的、能干的」，源头 capere「抓、容纳」；再加 -ity。能「抓得住」事情，就是 capability。\",\"protective\":\"protect 来自拉丁语 protectus「被遮盖的」，源头 protegere：pro- + tegere「遮盖」。盖在前面护着的，就是 protective；与 detect（揭盖→查出）同根。\",\"towering\":\"tower 来自拉丁语 turris「塔」，经古英语 torr 进入英语；再加 -ing。高耸入云的，就是 towering。\",\"shadowy\":\"shadow 是古英语 sceadu「影子、荫」；再加 -y。影影绰绰的，就是 shadowy。\",\"congratulatory\":\"congratulate 来自拉丁语 congratulari「同喜」：con- + gratulari「庆幸」（gratus「令人高兴的」）。陪着一起高兴的话，就是 congratulatory。\",\"fragrance\":\"来自拉丁语 fragrantia「芳香」，源头 fragrare「散发香气」。花与香水飘出的，就是 fragrance。\",\"nosh\":\"借自意第绪语 nashn「吃零食」，源头是德语 naschen「偷嘴、吃点心」。垫肚子的小食与动作，就是 nosh。\",\"functional\":\"function 来自拉丁语 functio「执行、职责」，源头 fungi「履行」。能履行职责的，就是 functional。\",\"harmless\":\"harm 是古英语 hearm「伤害、悲伤」；再加 -less「没有」。伤不着人的，就是 harmless。\",\"skimpy\":\"skimp 来源不完全确定：18 世纪词，可能与 scrimp「吝啬、缩减」同族或为其变体。缩水省料的，就是 skimpy。如实标注。\",\"inhabited\":\"inhabit 来自拉丁语 inhabitare「住在里面」：in- + habitare「居住」。有人住着的，就是 inhabited。\",\"sheepish\":\"sheep（古英语 scēap）+ -ish「…似的」：像绵羊一样怯生生的，就是 sheepish（难为情的）。\",\"cooperative\":\"cooperate 是按拉丁语 cooperari 造的词：co-「共同」+ operari「工作」（opus「工作」）。一起干活的，就是 cooperative；opera（歌剧=作品）与它同根。\",\"ornamental\":\"ornament 来自拉丁语 ornamentum「装备、装饰」，源头 ornare「装备、美化」；再加 -al。起装饰作用的，就是 ornamental。\",\"gargle\":\"来自古法语 gargouille「喉咙」，带拟声色彩（水在喉咙里咕噜响），源头可能与拉丁语 gurgulio「气管」同族。漱口的那串咕噜声，就是 gargle。\",\"misfortune\":\"mis- + fortune「命运」构成。fortune 来自拉丁语 fortuna「运气、命运女神」。运气砸了的，就是 misfortune。\",\"displeasure\":\"dis-「不」+ pleasure「愉快」：pleasure 源头是拉丁语 placere「使满意」。心里不满意，就是 displeasure；与 please 同根。\",\"baggage\":\"来自古法语 bagage「行李」，词干 bagues 可能源自古诺斯语 baggi「包裹」。士兵背着的包裹，后来泛指一切行李；也引申为心理包袱。\",\"captivity\":\"captive 来自拉丁语 captivus「被抓的」，源头 capere「抓、夺」。被抓去关着的状态，就是 captivity；与 capture 同根。\",\"everlasting\":\"ever + lasting（last「持续」源自古英语 læstan「跟随到底、持续」）构成的中古英语复合词。持续到永远的，就是 everlasting。\",\"enduring\":\"endure 来自古法语 endurer，源头是拉丁语 indurare「使变硬、忍受」：in- + durus「硬的」。硬着扛到底的，就是 enduring；与 durable 同根。\",\"enfold\":\"en- + fold（古英语 fealdan「折叠」）构成。把东西折进怀里包住，就是 enfold。\",\"overcome\":\"古英语 ofercuman「战胜、压倒」：ofer「越过」+ cuman「来」。跨过难关来的，就是 overcome。\",\"quarrelsome\":\"quarrel 来自古法语 querele「抱怨、争执」，源头是拉丁语 querela「投诉」，其根 queri「抱怨」；再加 -some。动不动投诉开吵的，就是 quarrelsome。\",\"disposable\":\"dispose 来自古法语 disposer，源头是拉丁语 disponere「摆放、处置」：dis- + ponere「放」。用完可「处置」掉的，就是 disposable。\",\"punishable\":\"punish 来自拉丁语 punire「惩罚」，源头 poena「罚金、刑罚」；再加 -able。该罚的，就是 punishable。\",\"barrette\":\"借自法语 barrette「小杠、发夹」，是 barre「杠、条」的指小形式；barre 再往上是通俗拉丁语 *barra「横木」。夹住头发的小横杠，就是 barrette。\",\"frothy\":\"froth 源自古诺斯语 froða「泡沫」；再加 -y。泡沫满溢的，就是 frothy；内容轻飘的也用它。\",\"impressive\":\"impress + -ive：在心上压出深印的，就是 impressive。\",\"marina\":\"借自意大利语、西班牙语 marina「海滨（区）」，是拉丁语 marinus「海的」（mare「海」）的阴性形式。停游艇的海滨港，就是 marina。\",\"guise\":\"来自古法语 guise「方式、装束」，源头是日耳曼语 *wīsa「样子、方式」，与 wise（方式义，如 likewise）同根。外在的样子与幌子，就是 guise。\",\"reversible\":\"reverse 来自拉丁语 reversus「被转回的」，源头 revertere：re- + vertere「转」；再加 -ible。转得回来的，就是 reversible（可逆的、双面可穿的）。\",\"popularity\":\"popular 来自拉丁语 popularis「人民的」，源头 populus「人民」；再加 -ity。人人都爱的程度，就是 popularity。\",\"oath\":\"古英语 āþ「誓言」，与德语 Eid 同源，其更深来源不确定。对神说下的话，就是 oath。深层来源如实标注存疑。\",\"oversee\":\"古英语 ofersēon「俯瞰、监督」：从上面看的，就是 oversee；与监督者 overseer 同源。注意与 overlook（看漏）义近形近而义别。\",\"cavity\":\"来自晚期拉丁语 cavitas「空洞」，源头 cavus「中空的」。牙上的洞、体腔，都是 cavity。\",\"dinghy\":\"借自印地语 ḍiṅgī「小船」，孟加拉语 ḍiṅi。印度河上的小划子，成了救生艇的名字 dinghy。\",\"silencer\":\"silence 来自拉丁语 silentium「寂静」，源头 silere「安静」；再加 -er。让枪声安静的装置，就是 silencer。\",\"hassle\":\"来源不完全确定：19–20 世纪美国词，可能是 haggle「纠缠」与 hustle、tussle 的混成。麻烦事与纠缠，都是 hassle。如实标注存疑。\",\"truce\":\"中古英语 trewes「休战协定」，是 true「忠诚、约定」的复数形式古义：双方以信相约停手。停战，就是 truce；与 true 同根。\",\"glint\":\"源自斯堪的纳维亚语（古诺斯语 glitra「闪光」一系），中古英语作 glenten「滑开、闪光」。一闪而过的光，就是 glint。\",\"fashionable\":\"fashion 来自古法语 façon「做法、样式」，源头是拉丁语 factio「制作」，其根 facere「做」。跟着当下「做法」走的，就是 fashionable；与 faction（做法不同→派系）同根。\",\"spiteful\":\"spite 是 despite 的缩略：despite 来自拉丁语 despectus「俯视、轻蔑」，源头 despicere「往下看」；再加 -ful。存心气人的，就是 spiteful。\",\"population\":\"来自晚期拉丁语 populatio「人口」，源头 populus「人民」。一片地上的人，就是 population。\",\"referable\":\"refer 来自拉丁语 referre「带回、归因」：re- + ferre「携带」；再加 -able。可归到某处的，就是 referable。\",\"sniffy\":\"sniff 是拟声词，模仿抽鼻子声；再加 -y。鼻子一抽、瞧不起人的，就是 sniffy。\",\"fixedly\":\"fixed（拉丁语 fixus「钉住的」）+ -ly。眼都不眨地盯着，就是 fixedly。\",\"ablaze\":\"a-「处于…状态」+ blaze（古英语 blæse「火把、火焰」）。字面就是「在火里」，引申为光芒四射、情绪燃烧。\",\"inconclusive\":\"in-「不」+ conclusive「定论的」：conclude 源头是拉丁语 concludere「关住、收束」（con- + claudere「关」）。收不住尾、下不了结论的，就是 inconclusive。\",\"scenic\":\"scene + -ic：如画的，就是 scenic。\",\"unwritten\":\"un- + written「写成的」构成：没写下来的（规则、法律），就是 unwritten。\",\"derail\":\"de-「脱离」+ rail「铁轨」构成的 19 世纪铁路词。rail 经古法语而来，源头是拉丁语 regula「直棍、规则」。车出了轨，就是 derail；谈话跑题也用它。\",\"vacate\":\"来自拉丁语 vacare「空着」，源头 vacuus「空的」。把位子空出来的，就是 vacate。\",\"scavenge\":\"scavenger 来自盎格鲁-法语 scawager「收税查货的官员」，源头 scawage 一系与古英语 sceawian「看」有关：从「查货官」到「清道夫」再到「食腐者」，词义三级跳，如实标注。\",\"jabber\":\"拟声构词：模仿急促含糊的说话声（jab 一类音节的反复）。叽里呱啦的，就是 jabber。\",\"blister\":\"来自古法语 blestre「肿块、水泡」，可能源自日耳曼语，与 blow「吹起」同族：皮肤像被吹起一个包，就是 blister。此关联较可信但非定论。\",\"ceaseless\":\"cease 来自拉丁语 cessare「停下、止息」（cedere「让开」的反复形式）；-less「没有」。永不停下的，就是 ceaseless。\",\"gutless\":\"gut（古英语 guttas「内脏」）+ -less「没有」构成。gut 引申为「胆量」：没内脏、没胆的，就是 gutless。\",\"unimaginable\":\"un- + imaginable「可想象的」构成。imagine 来自拉丁语 imaginari，其根 imago「像」。想不出的，就是 unimaginable。\",\"barcode\":\"bar「条」+ code 构成的 20 世纪词。code 源头是拉丁语 codex「木板书、法典」。一排粗细不一的条，就是给法典式规则读的 barcode。\",\"footing\":\"foot（古英语 fōt）+ -ing 构成：脚站住的位置，就是 footing；立足点与基础都用它。\",\"tambourine\":\"经法语 tambourin 而来，源头是普罗旺斯语 tamborin，其根与阿拉伯语 ṭanbūr「弦乐器」或 ṭabl「鼓」一系有关。铃鼓，就是 tambourine。深层来源如实标注为常见说法。\",\"shrubbery\":\"shrub 来源不完全确定：古英语 scrybb「灌木」，可能借自斯堪的纳维亚语；再加 -ery。成片的灌木，就是 shrubbery。如实标注。\",\"playwright\":\"play + wright「工匠」（古英语 wyrhta「做工者」）构成：注意不是 write——写戏的是「做」戏的匠人，就是 playwright。\",\"twiddle\":\"来源不完全确定：可能是 twirl 与 fiddle 的混成，或拟声造词。指尖转着玩的，就是 twiddle。如实标注。\",\"quirk\":\"来源不完全确定：16 世纪词，可能与德语 quer「横、斜」或本土方言词有关。怪癖与话锋一转，就是 quirk。如实标注存疑。\",\"satisfactory\":\"satisfy 来自拉丁语 satisfacere「使满足」：satis「足够」+ facere「做」；再加 -ory。做得够好的，就是 satisfactory。\",\"thrasher\":\"thrash 是 thresh「打谷」的变体：古英语 þrescan「打、踩」；再加 -er。打谷般扑腾的鸟（褐弯嘴嘲鸫）与人，就是 thrasher。\",\"inoperable\":\"in-「不可」+ operable「可手术的」：operate 源头是拉丁语 operari「工作」（opus「工作」）。动不了刀的，就是 inoperable。\",\"scald\":\"来自盎格鲁-法语 escalder，源头是晚期拉丁语 excaldare「用热水洗」：ex- + caldus「热的」（calidus）。烫伤与热奶的那层皮，都是 scald。\",\"setback\":\"set + back 构成的复合词：被顶回去的，就是 setback（挫折）。\",\"conference\":\"来自中世纪拉丁语 conferentia「聚议」，源头 conferre「带到一起」：con- + ferre「携带」。把意见带到一张桌子上，就是 conference；与 transfer 的 fer- 同根。\",\"unforgettable\":\"un- + forgettable「可忘的」构成：忘不掉的，就是 unforgettable。forget 是古英语 forgietan。\",\"disagreeable\":\"dis-「不」+ agreeable。agree 来自古法语 agreer「合意」，源头是拉丁语 ad gratum「合乎心意」（gratus「令人愉快的」）。不合心意的，就是 disagreeable。\",\"bodily\":\"body（古英语 bodig，本义可能是「桶、躯干」）+ -ly。关乎整个躯干的，就是 bodily；bodily harm 就是人身伤害。\",\"vigil\":\"来自拉丁语 vigilia「守夜、警醒」，源头 vigil「醒着的」。彻夜醒着守的，就是 vigil。\",\"forgiveness\":\"forgive 是古英语 forgiefan「宽免」：for- + giefan「给」。把债与罪一笔「给」出去，就是 forgiveness。\",\"birthmark\":\"birth「出生」+ mark「记号」构成的复合词：生下来就带着的记号，就是胎记。\",\"hindmost\":\"hind「后面的」（古英语 hindan「在后」）+ -most「最」构成：排在最末尾的，就是 hindmost。俗语 the devil take the hindmost 说的正是它。\",\"signify\":\"来自拉丁语 significare「表明、意味」：signum「记号」+ facere「做」。做记号表意的，就是 signify。\",\"wheeze\":\"中古英语 whesen「喘」，借自古诺斯语 hvæsa「嘶嘶喘」，是拟声词。喉咙拉风箱的，就是 wheeze。\",\"insignificance\":\"in-「不」+ significance「重要性」：significant 源头是拉丁语 significare「表明」（signum「记号」+ facere「做」）。做不出记号、激不起浪的，就是 insignificance。\",\"terrace\":\"来自古法语 terrasse「土台」，源头是通俗拉丁语 *terracea，其根是拉丁语 terra「土」。堆土成的台与梯田，就是 terrace。\",\"discouragement\":\"discourage 来自古法语 descorager：des-「去掉」+ corage「勇气」（源头通俗拉丁语 *coraticum，其根是拉丁语 cor「心」）。把心气抽走，就是 discouragement。\",\"particular\":\"来自拉丁语 particularis「关乎小部分的」，源头 particula「微粒」，是 pars「部分」的指小形式。细到微粒的讲究，就是 particular。\",\"hatchet\":\"来自古法语 hachette「小斧」，是 hache「斧」的指小形式，源头是日耳曼语 *hapja 一类词。小手斧，就是 hatchet；bury the hatchet 是印第安议和仪式。\",\"adhesive\":\"adhere 来自拉丁语 adhaerere「粘住」：ad-「向」+ haerere「黏着」。能把东西粘到一起的，就是 adhesive；与 hesitate（黏住迈不开步→犹豫）同根。\",\"slosh\":\"拟声构词：模仿液体晃荡泼溅声，可能是 slush 与 slop 的混合。晃着泼的，就是 slosh。\",\"shameful\":\"shame 是古英语 scamu「羞耻」，其更深来源有一说与「遮盖」有关（羞得遮脸）；再加 -ful。丢人的，就是 shameful。深层如实标注为一说。\",\"consumable\":\"consume 来自拉丁语 consumere「全部取用、耗尽」：con-「完全」+ sumere「拿取」。用一次就没了的，就是 consumable。\",\"preoccupation\":\"preoccupy 来自拉丁语 praeoccupare「抢先占住」：prae- + occupare「占据」。心先被占满的，就是 preoccupation。\",\"bushel\":\"来自古法语 boissel「量器」，源头可能是高卢语，与拉丁语 buxis「盒子」（希腊语 pyxis）一说有关，未完全定论。量谷物的一大斗，就是 bushel；俗语 hide under a bushel 指藏着本事不露。深层来源如实标注。\",\"stutter\":\"中古英语 stutteren，是 stut「停顿」的反复形式，与德语 stottern 同族，带拟声色彩。话卡壳的，就是 stutter（口吃）。\",\"goodwill\":\"good + will「意愿」构成的古英语复合词（godwill）：心向着你的善意，就是 goodwill；商誉也是它。\",\"regiment\":\"来自晚期拉丁语 regimentum「统治、团」，源头 regere「统治、使直」。被管成团的兵，就是 regiment（团）；作动词指严格管束。\",\"coauthor\":\"co-「共同」（拉丁语 com- 的变体）+ author。author 来自拉丁语 auctor「创始者」，源头 augere「增加、创造」。两个人一起「创」一本书，就是 coauthor。\",\"impossibility\":\"im-「不」+ possibility「可能性」：possible 来自拉丁语 possibilis，其根 posse「能够」。做不到的事，就是 impossibility。\",\"trickster\":\"trick + -ster「…者」：耍花招的人与神话里的骗子神，就是 trickster。\",\"midriff\":\"古英语 midhrif「中腹」：mid「中间」+ hrif「腹部、子宫」。横膈膜与腰腹一带，就是 midriff。\",\"feeble\":\"来自古法语 feble（现代法语 faible），源头是拉丁语 flebilis「可悲的、该哭的」，其根 flere「哭泣」。弱得让人想哭的，就是 feeble。\",\"nifty\":\"词源存疑：19 世纪美国俚语，可能由 magnificent 的戏谑缩略或方言词演变而来，没有定论。俏皮出色的，就是 nifty；这里不硬编。\",\"transitional\":\"transition 来自拉丁语 transitio「过渡」，源头 transire：trans- + ire「去」；再加 -al。正在过去的，就是 transitional。\",\"intensity\":\"intense 来自拉丁语 intensus「拉紧的」，源头 intendere：in- + tendere「拉」。弦拉到最紧的程度，就是 intensity。\",\"impoverish\":\"来自古法语 empovrir「使变穷」：en- + povre「穷的」（源头拉丁语 pauper）。把人弄穷的，就是 impoverish；pauper（贫民）与它同根。\",\"ridiculous\":\"来自拉丁语 ridiculus「可笑的」，源头 ridere「笑」。笑到荒谬的，就是 ridiculous；与 deride（嘲笑）同根。\",\"loom\":\"（织机）古英语 gelōma「工具、器具」，后专指织布机；动词 loom「隐现」是另一来源（水手词，可能源自低地德语）。此处取织机本义，如实标注两义异源。\",\"clownish\":\"clown 来源不完全确定：可能源自低地德语或斯堪的纳维亚语，指笨拙的乡下人（与 clod 一说同族）。再加 -ish。像乡巴佬小丑一样的，就是 clownish。深层来源如实标注存疑。\",\"revision\":\"revise 来自拉丁语 revisere「再看」：re- + visere「看」（videre 的反复形式）。再看一遍改的，就是 revision。\",\"afloat\":\"a-「在…上」+ float（古英语 flotian「漂浮」）。漂在水面上不沉，就是 afloat；公司「还漂着」就是还没破产。\",\"reputation\":\"来自拉丁语 reputatio「估量」，源头 reputare：re- + putare「思考、估量」。众人估出来的价，就是 reputation（名声）。\",\"token\":\"古英语 tācen「记号、证据」，与德语 Zeichen 同源，与 teach 同根（让人「认出」的东西）。凭证与象征，就是 token。\",\"premeditation\":\"premeditate 来自拉丁语 praemeditari「预先沉思」：prae- + meditari「想」。事先想好的，就是 premeditation（预谋）。\",\"backlash\":\"back「回」+ lash「猛抽、鞭打」构成的复合词，本义是机械部件松动时的反冲。像鞭子抽回来打到自己，就是舆论与局势的 backlash。\",\"comfortable\":\"comfort 来自古法语 conforter「使强壮、安慰」，源头是晚期拉丁语 confortare：com- + fortis「强的」。本义是「给人力气」，后转指舒适；与 fort（要塞）的 fort- 同根。\",\"recreate\":\"（消遣义与再造义同源分岔）recreate 来自拉丁语 recreare「重新造、使恢复」：re- + creare「创造」。再造出新精神的活动，就是 recreate（娱乐）。\",\"worrisome\":\"worry 是古英语 wyrgan「掐死、勒」，本指狗咬喉撕咬，后转指揪心；再加 -some。揪心的，就是 worrisome。词义滑坡如实标注。\",\"observation\":\"同 observare：守着看的记录与结论，就是 observation。\",\"spineless\":\"spine 来自拉丁语 spina「刺、脊骨」；再加 -less。没脊梁的，就是 spineless（无骨气的）。\",\"personalize\":\"personal（源头拉丁语 persona「面具、个人」）+ -ize 构成：做成合个人口味的，就是 personalize。\",\"scatter\":\"中古英语 scateren，可能是 shatter「打碎」的变体，受斯堪的纳维亚语影响。撒得到处都是的，就是 scatter。\",\"deformity\":\"deform 来自拉丁语 deformare「使变形」：de- + forma「形状」。形状被弄歪的状态，就是 deformity。\",\"twaddle\":\"来源不完全确定：可能是 twattle「闲聊」的变体，带拟声色彩。废话连篇，就是 twaddle。如实标注存疑。\",\"savory\":\"同 sapor：有滋味的、开胃的，就是 savory。\",\"merit\":\"来自拉丁语 meritum「功绩、应得」，源头 merere「挣得、服役挣薪」。挣来的功，就是 merit。\",\"recording\":\"record 来自拉丁语 recordari「记在心里」：re- + cor「心」；再加 -ing。录下来的，就是 recording。\",\"practicability\":\"practicable 是按拉丁语 practicabilis 造的词，源头希腊语 praktikos「实干的」；再加 -ity。做得成的程度，就是 practicability。\",\"immortal\":\"im-「不」+ mortal「会死的」：mortal 来自拉丁语 mortalis，其根 mors「死亡」。死不了的，就是 immortal。\",\"facet\":\"借自法语 facette「小面」，是 face 的指小形式。宝石切出的每个小面，就是 facet；事情的一面也用它。\",\"probability\":\"probable 来自拉丁语 probabilis「可证实的、可能的」，源头 probare「检验、证实」。验得出几分准的，就是 probability。\",\"skim\":\"来源不完全确定：中古英语 skimmen，可能是 scum「浮沫」的变体，或源自古法语 escumer「撇沫」。撇着面走的，就是 skim。深层来源如实标注。\",\"savor\":\"来自古法语 savor「滋味」，源头是拉丁语 sapor「味道」，其根 sapere「品尝、有味」——sapere 也是「有智慧」的词：会品的，才有智慧。细品的，就是 savor。\",\"flunk\":\"美国口语词，来源不完全确定：可能是 funk「恐惧、退缩」与 flunk 自身拟声的结合，19 世纪大学俚语。考砸了，就是 flunk。如实标注存疑。\",\"rebuff\":\"来自古法语 rebuffer「顶回」，其构成有一说为 re- + buffe「一击」（拟声）。迎面顶回去的拒绝，就是 rebuff。如实标注。\",\"knurl\":\"knur 是中古英语 knorre「节、瘤」的变体（与 knar 同族）；再加 -le。滚花加工出的小棱纹，就是 knurl。\",\"provincial\":\"province 来自拉丁语 provincia「行省、职掌」，其更深来源不确定；再加 -al。外省的、见识窄的，就是 provincial。深层来源如实标注存疑。\",\"fixation\":\"fix 来自拉丁语 fixus「钉住的」，源头 figere「钉、固定」；再加 -ation。目光与心思被钉死在一处，就是 fixation。\",\"incompletion\":\"in-「未」+ completion「完成」：complete 来自拉丁语 completus「填满的」，源头 complere：com- + plere「满」。没填满的，就是 incompletion。\",\"misconception\":\"mis- + conception「概念」构成。conception 源头是拉丁语 concipere「怀上、构想」（con- + capere「取」）。脑子里「怀」错了的，就是 misconception。\",\"morsel\":\"来自古法语 morsel「一小口」，源头是拉丁语 morsus「咬」，其根 mordere「咬」。咬得下的一口，就是 morsel。\",\"shackle\":\"古英语 sceacul「镣铐」，与德语一系同族，其更深来源不确定。扣住手脚的，就是 shackle。深层来源如实标注存疑。\",\"confusion\":\"confuse 来自拉丁语 confusus「混杂的」，源头 confundere「倒到一起」。脑子成了一锅粥，就是 confusion。\",\"nameless\":\"name（古英语 nama）+ -less「没有」构成：没名可叫的，就是 nameless。\",\"lousy\":\"louse 是古英语 lūs「虱子」；再加 -y。长满虱子的，引申为糟透了的，就是 lousy。\",\"thoroughbred\":\"thorough「彻底的」+ bred「培育的」构成的 18 世纪赛马词：血统纯到底的，就是 thoroughbred（纯种的）。\",\"pipsqueak\":\"pip「小籽、星」+ squeak「吱吱叫」构成的 20 世纪戏谑词：小得只配吱吱叫的人，就是 pipsqueak。\",\"reorganization\":\"re- + organization「组织」构成。organize 源头是希腊语 organon「工具、器官」。重新编排的，就是 reorganization。\",\"impending\":\"impend 来自拉丁语 impendere「悬在头顶」：in- + pendere「悬挂」。悬在头上随时落下的，就是 impending（迫近的）。\",\"dazzling\":\"dazzle 是 daze「使眩晕」的反复形式（-le 表反复）：daze 源自古诺斯语 dasa「疲惫发懵」。光强得让人发懵，就是 dazzling。\",\"fain\":\"古英语 fægen「高兴的、乐意的」，与古诺斯语 feginn 同源。古语里「乐意地」就是 fain，如今只在诗文里露脸。\",\"grudge\":\"来自古法语 groucier「抱怨、嘟囔」，带拟声色彩，其更深来源不确定。把怨气含在嘴里嘟囔多年，就是 grudge。如实标注。\",\"shrunken\":\"shrink 的古过去分词：缩了水的，就是 shrunken。\",\"saucy\":\"sauce 来自拉丁语 salsa「盐水、咸汁」，源头 sal「盐」；再加 -y。话里带「盐」的冲劲，就是 saucy（俏皮无礼的）。\",\"flavorful\":\"flavor 来自古法语 flaor「气味」，其更深来源不确定，可能与拉丁语 flare「吹」或 foetor「臭气」有关；再加 -ful。味道满满的，就是 flavorful。深层来源如实标注存疑。\",\"unfortunate\":\"un- + fortunate「幸运的」构成。fortunate 来自拉丁语 fortunatus，其根 fortuna「命运」。运气不站这边的，就是 unfortunate。\",\"cleanliness\":\"cleanly（古英语 clǣne「干净的」）+ -ness。俗语说 cleanliness is next to godliness——干净仅次于虔诚。\",\"exclamatory\":\"exclaim 来自拉丁语 exclamare「大声喊出」：ex- + clamare「喊」。喊出来的句子，就是 exclamatory（感叹的）。\",\"persona\":\"直接借自拉丁语 persona「面具、角色」，其更深来源有一说与伊特鲁里亚语 phersu「面具」有关。示人的那张面具，就是 persona。深层来源如实标注为一说。\",\"originality\":\"origin 来自拉丁语 origo「起源、出身」，源头 oriri「升起、出生」；再加 -ality。从源头长出新意的，就是 originality。\",\"nourishment\":\"nourish 来自古法语 norrir，源头是拉丁语 nutrire「喂养」。喂大的养分，就是 nourishment；与 nurse（乳母）同根。\",\"shivery\":\"shiver 来源不完全确定：中古英语 chiveren，可能与 shave「碎片」一系或斯堪的纳维亚语有关；再加 -y。冷得直抖的，就是 shivery。如实标注。\",\"cosmetic\":\"来自希腊语 kosmētikos「善于装扮的」，源头 kosmos「秩序、装饰」——宇宙与化妆品在希腊人那里共用一个词：把脸整理出秩序，就是 cosmetic。\",\"neigh\":\"古英语 hnǣgan「马嘶」，是拟声词。马的叫声，就是 neigh。\",\"override\":\"古英语 oferrīdan「骑过、压倒」：骑马碾过去的，就是 override（推翻、凌驾）。\",\"enslave\":\"en-「使成」+ slave「奴隶」构成。slave 经古法语、拉丁语 sclavus 而来，本义是「斯拉夫人」——中世纪大量斯拉夫人被掳为奴，族名变成了奴隶的通称。\",\"snoop\":\"借自荷兰语 snoepen「偷吃、偷尝」，转指偷偷摸摸地打探。东闻西嗅的，就是 snoop。\",\"shabby\":\"shab 来源不完全确定：古英语 sceabb「疥疮」，借自古诺斯语 skabb；再加 -y。破旧寒酸的，就是 shabby。如实标注。\",\"injection\":\"inject 来自拉丁语 iniectus「被投进的」，源头 inicere：in- + iacere「投掷」。把药「掷」进血管的，就是 injection。\",\"negotiable\":\"negotiate 来自拉丁语 negotiari「做生意、商议」，源头 negotium「事务」：nec-「不」+ otium「闲暇」——没闲工夫就是忙正事。谈得拢、可转让的，就是 negotiable。\",\"production\":\"produce 来自拉丁语 producere「带出来、引出」：pro- + ducere「带领」。带出来的东西，就是 production。\",\"android\":\"希腊语拼合词：andr-「人、男人」（anēr 的词干）+ -oid「像…的」。长得像人的机器，就是 android；与 anthropology 的 anthropo- 是近亲。\",\"new\":\"古英语 nīewe，与拉丁语 novus、希腊语 neos 同出印欧语 *newos。全新的，就是 new。\",\"merriment\":\"merry 是古英语 myrge「愉快的」，其更深来源有一说与「短」有关（消磨短暂时光一说）；再加 -ment。欢闹的劲，就是 merriment。深层来源如实标注为一说。\",\"parenthesize\":\"parenthesis 来自希腊语 parenthesis「插入」：para- + en + thesis「放置」。把话插进括号的，就是 parenthesize。\",\"secrecy\":\"secret 来自拉丁语 secretus「被分开的、秘密的」，源头 secernere：se- + cernere「筛分」。分开藏着的状态，就是 secrecy。\",\"communal\":\"commune（共同体）来自拉丁语 communis「共同的」；再加 -al。全村、全社共用的，就是 communal。\",\"omission\":\"同 omittere：漏掉的那一笔，就是 omission。\",\"powerhouse\":\"power + house 构成的 19 世纪词：发电的厂房，后比喻实力强劲的人与机构，就是 powerhouse。\",\"scribble\":\"来自中世纪拉丁语 scribillare「潦草地写」，是 scribere「写」的指小反复形式。乱涂的，就是 scribble。\",\"shuffle\":\"来源不完全确定：可能是 scuffle「混战」的变体，或低地德语 schuffeln「拖步」一系。拖着步子走与洗牌，都是 shuffle。如实标注。\",\"podgy\":\"podge 来源不完全确定：可能是 pudge「矮胖」的变体，与 pod「豆荚」一系有关一说。胖墩墩的，就是 podgy。如实标注。\",\"narrow\":\"古英语 nearu「狭窄的、困窘的」，与德语近亲，其更深来源不确定。挤得过的，就是 narrow。深层来源如实标注存疑。\",\"treacherous\":\"treachery 来自古法语 trecherie「欺骗」，源头 trechier「骗」，其更深来源不确定。骗人的险，就是 treacherous。深层来源如实标注存疑。\",\"honorable\":\"honor 来自拉丁语 honor（古拼写 honos）「荣誉、官职」，经古法语进入英语；再加 -able。配得上荣誉的，就是 honorable。\",\"recollection\":\"recollect 来自中世纪拉丁语 recollectus「重新收拢的」，源头 recolligere：re- + colligere「拾集」。把记忆拾回来的，就是 recollection。\",\"unworthy\":\"un- + worthy「值得的」构成。worthy 是古英语 weorþig，源头 weorþ「价值」。配不上的，就是 unworthy。\",\"nominally\":\"nominal 来自拉丁语 nominalis「名义上的」，源头 nomen「名字」；再加 -ly。只有名字、没有实权的，就是 nominally。\",\"animalistic\":\"animal 来自拉丁语 animalis「有气息的」，源头 anima「气息、灵魂」；再加 -istic。只剩下动物本能的那一面，就是 animalistic。\",\"numerable\":\"来自拉丁语 numerabilis「可数的」，源头 numerare「计数」，其根 numerus「数」。数得过来的，就是 numerable。\",\"fluttery\":\"flutter 是古英语 floterian「漂浮、扑动」，是 float 的反复形式。心像被风吹的旗一样扑棱的，就是 fluttery。\",\"inferior\":\"直接借自拉丁语 inferior「更低的」，是 inferus「下面的」比较级。位置在下面的，就是 inferior（低等的、下级的）。\",\"mingle\":\"古英语 mengan「混合」的反复形式（-le 表反复）。掺来掺去的，就是 mingle。\",\"snub\":\"借自古诺斯语 snubba「斥责、截短」，与 snip 一系同族。冷脸截断人的，就是 snub（冷落）。\",\"loot\":\"借自印地语 lūṭ「抢掠、赃物」，19 世纪英印军队带回英语。抢来的东西，就是 loot。\",\"gilding\":\"gild 是古英语 gyldan「镀金」，源头 gold。给东西抹上一层金的，就是 gilding；gild the lily 是「多此一举」。\",\"chariot\":\"来自古法语 chariot「战车」，是 char「车」（源头拉丁语 carrus，高卢语借词）的指小形式。古战场上的双轮车，就是 chariot；car 与它同根。\",\"elapse\":\"来自拉丁语 elapsus「滑走的」，源头 elabi：e- + labi「滑」。时间悄悄滑走，就是 elapse；与 collapse（滑倒→倒塌）同根。\",\"jittery\":\"jitter 来源不完全确定：20 世纪美国词，可能由 jitters（拟声、颤抖感）派生。紧张到发抖的，就是 jittery。如实标注。\",\"raptor\":\"直接借自拉丁语 raptor「抢夺者」，源头 rapere「抓」。用爪抓猎物的猛禽与恐龙，都是 raptor。\",\"cartridge\":\"来自法语 cartouche「纸筒」，源头是意大利语 cartoccio「纸卷」，其根是拉丁语 charta「纸」。卷在纸筒里的火药包，就是 cartridge 的前身；墨盒也是「纸筒」的后代。\",\"desirous\":\"desire 来自拉丁语 desiderare「渴望、想念」，其更深构词有一说与 sidus「星辰」有关（观星等候一说），未成定论；再加 -ous。满心想要的，就是 desirous。深层来源如实标注存疑。\",\"barbed\":\"barb「倒钩」来自拉丁语 barba「胡须」：箭头、铁丝网上的倒刺像一根根须。带刺的话就是 barbed remark；barber（理发师）剪的也是 barba。\",\"woozy\":\"来源不完全确定：19 世纪美国词，可能是 boozy「醉醺醺的」与 dizzy 一类词的混合。晕乎乎的，就是 woozy。如实标注存疑。\",\"nestle\":\"古英语 nestlian「筑巢、偎依」，源头 nest「巢」（拉丁语 nidus 是其印欧同族）。像回巢一样偎着的，就是 nestle。\",\"primarily\":\"primary 来自拉丁语 primarius「首要的」，源头 primus「第一的」；再加 -ly。排第一位的，就是 primarily。\",\"antidote\":\"来自希腊语 antidoton「给来对抗（毒）的东西」：anti-「对抗」+ doton「被给予的」（didonai「给」）。给毒配上的对手，就是解毒剂。\",\"homeward\":\"home + -ward「向…」构成的古英语复合词：朝着家的方向，就是 homeward。\",\"proverb\":\"来自拉丁语 proverbium「谚语」：pro- + verbum「词」。人人嘴边的词，就是 proverb；与 verb（动词）同根。\",\"zesty\":\"zest 来源不完全确定：借自法语 zeste「柑橘皮」，其更深来源不确定。柑橘皮的冲劲与生活的兴致，就是 zesty。如实标注。\",\"inaction\":\"in-「不」+ action「行动」：action 来自拉丁语 actio，其根 agere「驱动、做」。不动的状态，就是 inaction。\",\"heartbroken\":\"heart + broken 构成的复合词：心碎成两半的，就是 heartbroken。heart 是古英语 heorte。\",\"visibility\":\"visible 来自拉丁语 visibilis「可见的」，源头 videre「看」；再加 -ity。看得见多远，就是 visibility（能见度）。\",\"practitioner\":\"practise/practice 加 -itioner（仿 parishioner 的词尾）：开业行医、执业的人，就是 practitioner。\",\"simplify\":\"simple + -ify：把多层的折成一层的，就是 simplify。\",\"wariness\":\"wary 是古英语 wær「小心的」，与 aware 同源；再加 -ness。留着心的，就是 wariness。\",\"heritage\":\"来自古法语 heritage「继承物」，源头是晚期拉丁语 hereditare「继承」，其根 heres「继承人」。祖辈传下来的，就是 heritage；与 inherit 同根。\",\"perfectibility\":\"perfect 来自拉丁语 perfectus「做成的」：per-「彻底」+ facere「做」；再加 -ibility。能被做到完美的，就是 perfectibility。\",\"stingy\":\"来源不完全确定：方言词 stingy 可能是 sting「刺」的派生（吝啬如被刺般小气？），或与 stinge 一系有关。小气到家的，就是 stingy。如实标注存疑。\",\"monumental\":\"monument 来自拉丁语 monumentum「纪念物」，源头 monere「提醒」。提醒后人记住的，就是 monumental（丰碑般的、巨大的）。\",\"fey\":\"古英语 fǣge「注定要死的、不祥的」，与苏格兰语 fey 同源，源头是古诺斯语 feigr「将死的」。带点异界气、出神的，就是 fey。\",\"ordinarily\":\"ordinary 来自拉丁语 ordinarius「按序的、平常的」，源头 ordo「行列、秩序」；再加 -ly。按日常秩序的，就是 ordinarily。\",\"totality\":\"total 来自中世纪拉丁语 totalis「全部的」，源头 totus「整个的」；再加 -ity。整个儿的，就是 totality（日全食的全食阶段也用它）。\",\"interchangeable\":\"inter-「互相」+ changeable「可换的」（源头晚期拉丁语 cambiare「交换」）构成。彼此可换的，就是 interchangeable。\",\"twittery\":\"twitter 是拟声词，模仿鸟的啁啾与人的碎语；再加 -y。紧张碎念的，就是 twittery。\",\"undergarment\":\"under + garment「衣物」构成：穿在里面的，就是 undergarment。\",\"forbidden\":\"forbid 是古英语 forbēodan「禁止」：for-「反、阻」+ bēodan「吩咐」。被明令挡下的，就是 forbidden。\",\"leaflet\":\"leaf「叶、页」+ -let「小」构成：薄薄一片的，就是 leaflet（传单、小叶）。\",\"introduction\":\"introduce 来自拉丁语 introducere「领进去」：intro-「向内」+ ducere「带领」。把人、话题领进门的，就是 introduction。\",\"inexpressible\":\"in-「不可」+ expressible「可表达的」（源头拉丁语 exprimere「压出」：ex- + premere「压」）。压不成话的，就是 inexpressible。\",\"genuine\":\"来自拉丁语 genuinus「天生的、真正的」，源头 gignere「产生」一说（与 genus 同族）；另有与 genu「膝」相关的古说法（婴儿放膝上认亲）。天生如此、非仿造的，就是 genuine。深层如实标注为一说。\",\"harden\":\"hard（古英语 heard「硬的、坚固的」）+ -en「使…」构成。变硬、变心硬，都是 harden。\",\"reprise\":\"借自法语 reprise「重演、再取」，是 reprendre「重新拿起」的名词形式，源头拉丁语 reprehendere：re- + prehendere「抓」。乐段再抓一遍的，就是 reprise。\",\"scathe\":\"古英语 sceaþian「伤害」，源自古诺斯语 skaða，与德语 schaden 同源。灼伤与痛斥，就是 scathe（多见于 unscathed「毫发无损」）。\",\"visualize\":\"visual 来自晚期拉丁语 visualis「视觉的」，源头 visus「看」；再加 -ize。在脑里看成画的，就是 visualize。\",\"medallion\":\"经法语 médaillon 而来，源头是意大利语 medaglione「大奖章」，是 medaglia「奖章」的放大形式，其根与拉丁语 metallum「金属」有关一说。大号的章与盘饰，就是 medallion。深层来源如实标注为一说。\",\"sprinkling\":\"sprinkle 是古英语 sprencan「喷洒」的反复形式一系（-le 表反复），与德语 sprenkeln 同源。零星洒下的，就是 sprinkling。\",\"vouch\":\"来自古法语 vocher「传唤、作证」，源头是拉丁语 vocare「呼喊」。喊出来作保的，就是 vouch（担保）。\",\"archenemy\":\"arch-「首要的」（希腊语 arkhos「首领」）+ enemy。enemy 来自拉丁语 inimicus「非朋友」：in-「不」+ amicus「朋友」。头号「非朋友」，就是大敌。\",\"commute\":\"来自拉丁语 commutare「交换」：com- + mutare「改变」。先指把刑期「换」轻、把车票换成月票，后专指每天两地往返——用时间换距离，就是 commute。\",\"arousal\":\"arouse 是 a- + rouse 构成。rouse 词源存疑：最早见于猎鹰术语（惊起猎物），可能与古法语 ruser 一类词有关，但没有定论，这里不硬编。由它派生的 arousal 就是「被惊起、被唤起」的状态。\",\"organize\":\"organ 本指「乐器、器官」：来自希腊语 organon「工具」，经拉丁语进入英语。把零件装成能运转的「器官」，就是 organize。\",\"recline\":\"来自拉丁语 reclinare「往后靠」：re- + clinare「倾斜」。身子往后斜躺的，就是 recline。\",\"abound\":\"来自拉丁语 abundare「溢出、泛滥」：ab- + unda「波浪」。像水波一样漫出来，就是多到溢出；与 abundant 同源。\",\"minority\":\"minor 是拉丁语 minor「更小的」；再加 -ity。更小的一群，就是 minority。\",\"reverie\":\"借自法语 rêverie「白日梦」，源头 rêver「做梦」，其更深来源有一说与拉丁语 *exvagari「漫游」有关。心漫游出去的，就是 reverie。深层来源如实标注存疑。\",\"problematic\":\"problem 来自希腊语 problēma「抛到面前的问题」：pro- + ballein「投掷」，经拉丁语、法语进入英语；再加 -ic。问题成堆的，就是 problematic。\",\"futuristic\":\"future 来自拉丁语 futurus「将来的」，是 esse「是、在」的将来分词；再加 -istic。长着未来模样的，就是 futuristic。\",\"prideful\":\"pride 是古英语 prȳde「骄傲」，源头 prūd「高傲的」（源自古法语 prud「勇敢的」，再往上是拉丁语 prodesse「有益」一说）；再加 -ful。傲气满满的，就是 prideful。深层来源如实标注为一说。\",\"formality\":\"formal 来自拉丁语 formalis「合形式的」，源头 forma「形状、模子」；再加 -ity。按模子走的过场，就是 formality。\",\"tankard\":\"来源不完全确定：中古英语 tankard「大罐」，可能与古法语 tanquart 或中古荷兰语 tanckaert 有关。带盖大酒杯，就是 tankard。如实标注存疑。\",\"quake\":\"古英语 cwacian「颤抖」，带拟声色彩，与德语一系同族。地与人一起抖的，就是 quake。\",\"inseparable\":\"来自拉丁语 inseparabilis「分不开的」：in- + separare「分开」（se- + parare「准备」一说构词）。拆不散的，就是 inseparable。深层构词如实标注为一说。\",\"plunger\":\"plunge 来自古法语 plongier，源头是通俗拉丁语 *plumbicare「用铅垂测深」，其根是拉丁语 plumbum「铅」。往下扎的工具与人，就是 plunger；与 plumb（铅垂线）同根。\",\"pockmark\":\"pock 是古英语 pocc「脓疱、痘」，与德语 Pocke 同源；再加 mark「记号」。痘留下的坑，就是 pockmark。\",\"choosy\":\"choose（古英语 cēosan「挑选」）+ -y 构成的口语词。挑个没完，就是 choosy。\",\"oodles\":\"词源存疑：19 世纪美国词，指「大量」；一说与 boodle、caboodle 一族有关，没有定论。满坑满谷的，就是 oodles；这里不硬编。\",\"outermost\":\"outer（out 的比较级古形式）+ -most「最」构成：最靠外的，就是 outermost。\",\"flail\":\"来自古法语 flael，源头是拉丁语 flagellum「鞭子、连枷」，其根 flagrum「鞭」。农具连枷与乱挥的手臂，都是 flail；与 flagellate（鞭打）同根。\",\"damper\":\"damp 本指「窒息的蒸汽」（矿井毒气），源自中古低地德语 damp「蒸汽」；damper 是让火、声、情绪「闷下去」的装置。put a damper on 就是泼冷水。\",\"remarkable\":\"remark 来自法语 remarquer「注意到」：re- + marquer「做记号」（日耳曼语来源）；再加 -able。值得做记号的，就是 remarkable。\",\"makeshift\":\"make + shift「办法、轮换」构成的短语名词化：临时凑出的办法，就是 makeshift。shift 源头是古英语 sciftan「安排、分开」。\",\"serenade\":\"经法语 sérénade、意大利语 serenata 而来，源头是意大利语 sereno「晴朗的夜空」，其根是拉丁语 serenus「晴朗的」——晴夜里唱的歌。窗下小夜曲，就是 serenade。\",\"comprehensible\":\"comprehend 来自拉丁语 comprehendere「一把抓住」：com-「完全」+ prehendere「抓」。脑子能一把抓全的，就是 comprehensible。\",\"rakish\":\"rake「浪子」来源有一段公案：是 rakehell「地狱耙子」的缩略——能把地狱耙个遍的浪子。再加 -ish。潇洒不羁的，就是 rakish。深层如实标注为常见说法。\",\"revelation\":\"reveal 来自拉丁语 revelare「揭开面纱」：re- + velum「面纱」。把纱掀开的，就是 revelation（揭示、启示）。\",\"unsettled\":\"un- + settled「安定的」构成。settle 是古英语 setlan「使坐下」，源头 setel「座位」。坐不稳的，就是 unsettled。\",\"migration\":\"同 migrare：成群地搬，就是 migration。\",\"postmark\":\"post「邮政」+ mark「记号」构成：盖在信封上的邮戳，就是 postmark。post 源头是拉丁语 positus「被放好的（驿站）」。\",\"cheerless\":\"cheer 本义是「脸、表情」：经古法语 chiere 而来，源头是晚期拉丁语 cara「脸」，再往上是希腊语 kara「头」。脸上没光，就是 cheerless。\",\"mechanical\":\"mechanic 来自希腊语 mēkhanikos「器械的」，源头 mēkhanē「机械、装置」，经拉丁语进入英语；再加 -al。靠装置运转的，就是 mechanical；与 machine 同根。\",\"scientific\":\"science 来自拉丁语 scientia「知识」，源头 scire「知道」；再加 -fic。按知识规矩来的，就是 scientific。\",\"squeaky\":\"squeak 是拟声词，模仿吱吱声（与瑞典语 skväka 同类）；再加 -y。吱吱响的，就是 squeaky。\",\"roomy\":\"room 是古英语 rūm「空间、宽敞」，本义就是「宽」；再加 -y。宽敞的，就是 roomy。\",\"bistro\":\"借自法语 bistrot「小酒馆」，词源未有定论。流传最广的说法是 1815 年俄军占领巴黎时士兵催酒喊俄语 bystro「快点」，但语言学家多把它视为民间词源，证据不足，这里如实标注存疑。\",\"adjoin\":\"来自古法语 ajoindre，源头是拉丁语 adiungere「连接上」：ad- + iungere「结合」。两块地肩并肩接上，就是毗连；与 join 同源。\",\"clergy\":\"来自古法语 clergie「教士（群体）」，源头是晚期拉丁语 clericus「教士」，再往上是希腊语 klērikos「抽签分得的」，其根 klēros「签、份地」——教士被视为「神的那一份人」。\",\"spunky\":\"spunk 来源不完全确定：先指「火绒、引火物」，借自苏格兰盖尔语 spong「海绵、火绒」一说，后转指胆气。再加 -y。有劲有胆的，就是 spunky。如实标注。\",\"participant\":\"participate 来自拉丁语 participare「分享」：pars「部分」+ capere「取」。来取一份的人，就是 participant。\",\"phenomenal\":\"phenomenon 来自希腊语 phainomenon「显现之物」，源头 phainein「显示」，经晚期拉丁语进入英语；再加 -al。显现得惊人的，就是 phenomenal。\",\"oddity\":\"odd 借自古诺斯语 oddi「角、奇数」，与 odda-「单」有关：三人里多出的那个角。再加 -ity。单出来怪着的，就是 oddity。\",\"colossal\":\"colossus 来自希腊语 kolossos「巨像」，经拉丁语进入英语，其更深来源不确定（可能为前希腊语借词）。罗德岛太阳神巨像就是 Colossus；像巨像一样大的，就是 colossal。深层来源如实标注。\",\"breathable\":\"breathe + -able。breath 是古英语 brǣþ「气息、蒸汽、气味」。能透气的面料，就是 breathable。\",\"dethrone\":\"de-「拉下」+ throne「王座」构成。throne 来自希腊语 thronos「座椅」，经拉丁语、法语进入英语。把人从座上拉下来，就是 dethrone。\",\"tutorial\":\"tutor 来自拉丁语 tutor「监护人」，源头 tueri「看守、注视」；再加 -ial。监护人式的小班课，就是 tutorial。\",\"matron\":\"来自拉丁语 matrona「主妇」，源头 mater「母亲」。端庄的主妇与医院的护士长，都是 matron。\",\"raffish\":\"raff 来源不完全确定：18 世纪词 riff-raff「乌合之众」的 raff，或德语 raffen「抓取」一系；再加 -ish。略带痞气的时髦，就是 raffish。如实标注。\",\"ordeal\":\"古英语 ordāl「神判法」：把手伸进沸水、以伤验罪的神判。熬过神判般的折磨，就是 ordeal；与德语 Urteil（判决）同源。\",\"sludge\":\"来源不完全确定：中古英语 slutch「泥」，可能与 slush 同族。沉底的烂泥，就是 sludge。\",\"energize\":\"energy 来自希腊语 energeia「活动、作用」：en- + ergon「工作」；再加 -ize。给系统注入「做功」的劲，就是 energize；与 work 的 erg- 同族。\",\"identification\":\"identify 是按中世纪拉丁语 identificare 造的词：idem「同一」+ facere「做」——把人与档案「做成同一个」。其过程就是 identification。\",\"hurrah\":\"欢呼拟声词，与德语 hurra、俄语 ura 同类，可能源自中古高地德语 hurren「快速移动」的喊声一说。庆祝的喊声，就是 hurrah。如实标注：拟声来源为常见说法。\",\"humidity\":\"humid 来自拉丁语 humidus「潮湿的」，源头 humere「湿」。空气里水的含量，就是 humidity。\",\"acreage\":\"acre（古英语 æcer「田地」，与拉丁语 ager 同源）+ -age「总量」。手里有多少英亩地，就是 acreage。\",\"spoilage\":\"spoil 来自拉丁语 spoliare「剥、抢」，源头 spolium「剥下的皮、战利品」；再加 -age。烂掉的损耗，就是 spoilage。\",\"refinish\":\"re- + finish「完成、上漆」构成。finish 来自拉丁语 finire「结束」，源头 finis「终点」。重新上漆收尾的，就是 refinish。\",\"cancellation\":\"cancel 来自拉丁语 cancellare「画格子叉掉」，源头 cancelli「格栅」。在文书上画满格子叉号，就是取消；与 chancel（教堂格栅）同源。\",\"infirmity\":\"infirm 来自拉丁语 infirmus「不坚固的」：in- + firmus「坚固的」。身子不牢靠的毛病，就是 infirmity。\",\"pliable\":\"ply 来自法语 plier「折叠」，源头是拉丁语 plicare「折」；再加 -able。折得动的，就是 pliable（柔韧的、易说动的）。\",\"laboratory\":\"来自中世纪拉丁语 laboratorium「工场」，源头 laborare「劳动」（labor「劳作」）。干活做实验的地方，就是 laboratory，缩略为 lab。\",\"niggling\":\"niggle 来源不完全确定：可能源自斯堪的纳维亚语（挪威语 nigla「忙于琐事」一说）。为小事纠缠的，就是 niggling。如实标注。\",\"serum\":\"直接借自拉丁语 serum「乳清、液体」，与希腊语 oros 同族一说。血清与乳清，都是 serum。\",\"conditional\":\"condition 来自拉丁语 condicio「约定、条件」，源头 condicere「共同商定」：con- + dicere「说」。说好了前提才成立的，就是 conditional。\",\"adrift\":\"a-「处于…状态」+ drift「漂流」（古诺斯语 drift，源头是 drifa「驱赶、漂」）。锚断了随水漂，就是 adrift；与 drive 同根。\",\"nab\":\"来源不完全确定：17 世纪俚语，可能源自斯堪的纳维亚语 nappe「抓」或方言 nab「逮」。一把抓获的，就是 nab。如实标注。\",\"tourism\":\"tour 来自拉丁语 tornus「车床、圆」，经法语 tour「转一圈」进入英语：转一圈回来的旅行；再加 -ism。旅游业，就是 tourism。\",\"quaint\":\"来自古法语 cointe「精巧的、讲究的」，源头是拉丁语 cognitus「已知的」一说——由「精通」转「精巧」再转「古雅」。别致古雅的，就是 quaint。深层关联如实标注为一说。\",\"nomination\":\"nominate 来自拉丁语 nominare「命名、提名」，源头 nomen「名字」。把名字报上去的，就是 nomination。\",\"divisive\":\"divide 来自拉丁语 dividere「分开」：di- + videre 一说为「分」之古根；再加 -ive。把人群劈成两半的，就是 divisive。构词深层如实标注为一说。\",\"immensity\":\"immense 来自拉丁语 immensus「不可测量的」：in- + mensus「量过的」（metiri「量」）。大到量不完的，就是 immensity。\",\"grenade\":\"借自法语 grenade「石榴、手榴弹」，源头是拉丁语 pomum granatum「多籽的苹果（石榴）」：手榴弹形如石榴、弹片如籽四溅。pomegranate（石榴）与它同源。\",\"mismanage\":\"mis- + manage「经营」构成：手（manus）摆弄砸了的，就是 mismanage。\",\"nook\":\"中古英语 nōk「角落」，来源不完全确定，可能源自斯堪的纳维亚语。屋里的旮旯，就是 nook。如实标注。\",\"belle\":\"借自法语 belle「美人」，是拉丁语 bella 的后代，源头 bellus「美的」。选美场上的 belle，就是全场最美的女子。\",\"namesake\":\"name + sake「缘由」构成的 17 世纪词：for the name's sake 的省称——为同一个名字而名的，就是 namesake（同名者）。\",\"mischance\":\"mis- + chance「运气」构成。chance 来自古法语 cheance「落点」，源头是拉丁语 cadere「落」——骰子落哪儿是哪儿。落错点的，就是 mischance（厄运）。\",\"foreword\":\"fore- + word 构成，是德语 Vorwort 的译借词（19 世纪）：放在正文前面的话，就是 foreword，与 preface（拉丁语来源）相对的本土说法。\",\"immeasurable\":\"im-「不」+ measurable「可测量的」：measure 源头是拉丁语 mensura「量度」（metiri「量」）。量不到边的，就是 immeasurable。\",\"publicity\":\"public 来自拉丁语 publicus「人民的、公共的」，源头 populus「人民」一系；再加 -ity。闹到人人知道的，就是 publicity。\",\"retroactive\":\"retro-「向后」（拉丁语 retro）+ active「生效的」拼合的 19 世纪法律词。效力往前追的，就是 retroactive（溯及既往的）。\",\"damsel\":\"来自古法语 damisele「年轻小姐」，是 dame「夫人」的指小形式，源头是拉丁语 domina「女主人」。damsel in distress 就是等着骑士救的少女。\",\"learned\":\"learn 是古英语 leornian「学习」，与 lore「学识」同族；learned 的 -ed 读作两音节，特指博学的。\",\"smart\":\"古英语 smeart「刺痛的、剧痛的」：先指疼，后指穿着利落、脑子利落——三义同出一词的滑坡，如实标注。\",\"hospitalization\":\"hospital 来自拉丁语 hospitale「客房」，源头 hospes「客人/主人」；再经 -ize、-ation 派生。把人当「客人」收进院的，就是 hospitalization。\",\"markedly\":\"marked「显著的」（mark 源头是古英语 mearc「记号」）+ -ly。显著地，就是 markedly。\",\"disruptive\":\"disrupt 来自拉丁语 disruptus「被打破的」，源头 disrumpere：dis- + rumpere「打破」。把秩序打破的，就是 disruptive；与 rupture 同根。\",\"infectious\":\"infect 来自拉丁语 infectus「被浸染的」，源头 inficere：in- + facere「做」——本指染色。病「染」上身的，就是 infectious。\",\"scrawny\":\"来源不完全确定：方言词 scranny「瘦的」变体，可能源自斯堪的纳维亚语。瘦得皮包骨的，就是 scrawny。如实标注。\",\"perspire\":\"来自拉丁语 perspirare「透过呼吸、蒸发」：per- + spirare「呼吸」。汗从毛孔「呼」出来的，就是 perspire（礼貌版 sweat）。\",\"semisweet\":\"semi- + sweet 构成的 20 世纪食品词：半甜的，就是 semisweet（巧克力）。\",\"competence\":\"compete 来自拉丁语 competere「一同争取、相合」：com- + petere「追求」。与人同场争取所需的本事，就是 competence；与 petition（请愿）的 pet- 同根。\",\"turnkey\":\"turn + key 构成：监狱里转钥匙的人，就是 turnkey（狱卒）；交钥匙即入住的（turnkey 房）由此来。\",\"timber\":\"古英语 timber「建材、木料」，本义「建造（的材料）」，源头 timbrian「建造」。盖房的木头，就是 timber；伐木工的喊声 Timber! 是警告树要倒了。\",\"ramble\":\"来源不完全确定：可能是 roam 的反复形式变体，或源自中古荷兰语 rammelen「（动物）发情乱窜」一说。漫无目的地走与说，就是 ramble。如实标注。\",\"failure\":\"fail 来自古法语 faillir，源头是拉丁语 fallere「欺骗、使落空」。指望落了空，就是 failure；与 false（骗人的）同根。\",\"heroics\":\"hero 来自希腊语 hērōs「英雄、半神」，经拉丁语进入英语；再加 -ics。英雄式的举动与夸张姿态，都是 heroics。\",\"blackout\":\"black + out 构成的 20 世纪复合词，先指剧场熄灯、二战灯火管制，再引申为停电与短暂失忆。全黑、全断，就是 blackout。\",\"snivel\":\"古英语 snyflan「流鼻涕、抽泣」，源头与 snuff、sniff 一系同族（鼻子主题）。哭哭啼啼的，就是 snivel。\",\"scrawl\":\"来源不完全确定：可能是 sprawl「 sprawl 蔓延」的缩略变体，或与 crawl 有关。潦草乱写的，就是 scrawl。如实标注存疑。\",\"limitless\":\"limit + -less「没有」构成：没边的，就是 limitless。\",\"gloomy\":\"gloom 来源不完全确定：中古英语 gloumen「阴沉、皱眉」，可能源自古英语 glūmian 一类词。阴云压顶的心情，就是 gloomy。如实标注。\",\"permanency\":\"permanent 来自拉丁语 permanens「持续到底的」，源头 permanere：per- + manere「停留」。留得住的状态，就是 permanency。\",\"heartfelt\":\"heart + felt「感受到的」构成：从心底感受到的，就是 heartfelt。\",\"premature\":\"来自拉丁语 praematurus「过早成熟的」：prae-「过早」+ maturus「熟的」。瓜没熟就落的，就是 premature。\",\"imprint\":\"im- + print「印」构成的中古英语词：print 经古法语 preinte 而来，源头是拉丁语 premere「压」。压出来的印，就是 imprint。\",\"clammy\":\"clam 是古英语 clam「黏土、泥泞」，与 clay 同族；-y 表性质。又冷又黏的手，就是 clammy。\",\"periodically\":\"period 来自希腊语 periodos「绕行一圈」：peri-「环绕」+ hodos「路」，经拉丁语进入英语；再加 -ically。绕着圈回来的，就是 periodically。\",\"motto\":\"借自意大利语 motto「话语、格言」，源头是拉丁语 muttum「低语、词」，可能带拟声色彩。挂在嘴边的一句，就是 motto。\",\"descriptive\":\"describe 来自拉丁语 describere「写下、描摹」：de- + scribere「写」。把样子写下来的，就是 descriptive；与 scribe（抄写员）同根。\",\"keepsake\":\"keep + sake「缘由」构成的 18 世纪词：为留念而「keep」着的小物，就是 keepsake。sake 源头是古英语 sacu「事情、缘由」。\",\"closure\":\"来自古法语 closure「关闭、围栏」，源头是晚期拉丁语 clausura，其根是 claudere「关」。关上的动作与心理上的「了结」，都是 closure；与 clause（关闭一段→条款）同根。\",\"lifestyle\":\"life + style 构成的 20 世纪词（由德语 Lebensstil 译借推动）：style 源头是拉丁语 stilus「尖笔」。过日子的「笔法」，就是 lifestyle。\",\"insincerity\":\"in-「不」+ sincerity「真诚」：sincere 的来源有一段公案，传统说法是拉丁语 sine cera「无蜡」（不掺蜡的蜂蜜），学界多存疑；sincerus 本义「纯正」。此处如实标注：sincere 的深层构词未定论。\",\"harsh\":\"中古英语 harsk「粗糙的」，源自斯堪的纳维亚语或中古低地德语，与德语 harsch 同族。粗得扎手、严得刺耳的，就是 harsh。\",\"discontented\":\"dis-「不」+ content「满足的」：content 来自拉丁语 contentus「被装住的、心满意足的」，源头 continere「容纳」。装不满的心，就是 discontented。\",\"advisable\":\"advise 源自古法语短语 ce m'est avis「在我看来」，avis 来自拉丁语 visum「所见」（videre「看」）；-able 表「值得…的」。看下来值得做的，就是明智可取的。\",\"sinkage\":\"sink 是古英语 sincan「下沉」；再加 -age。沉下去的量，就是 sinkage。\",\"icicle\":\"ice + icle 构成的中古英语词：icle 是古英语 gicel「冰柱」的后代。屋檐下挂着的冰锥，就是 icicle。\",\"witchery\":\"witch 是古英语 wicca（男巫）/wicce（女巫），其更深来源不确定；再加 -ery。巫术与迷人的魔力，就是 witchery。深层来源如实标注存疑。\",\"humorless\":\"humor + -less「没有」构成：一点幽默细胞都没有的，就是 humorless。\",\"severally\":\"several 本义「各自的、分开的」：来自拉丁语 separalis 一系（separ「分开的」）；再加 -ly。各管各的，就是 severally。注意 several 的「几个」义是后起的。\",\"confidence\":\"来自拉丁语 confidentia「确信」，源头 confidere：con- + fidere「信任」。全心信得过，就是 confidence；与 fidelity（忠诚）的 fid- 同根。\",\"phony\":\"词源存疑：20 世纪美国词，一说源自爱尔兰骗术 fawney（假戒指骗局，源自爱尔兰语 fáinne「戒指」），没有确证。假冒的，就是 phony；这里如实标注。\",\"insecurity\":\"in-「不」+ security「安全」：secure 源头是拉丁语 securus「无忧虑的」（se-「无」+ cura「忧虑」）。忧虑拿不掉的，就是 insecurity。\",\"mutant\":\"来自拉丁语 mutans「变化着的」，源头 mutare「改变」。变了种的，就是 mutant。\",\"poverty\":\"来自古法语 poverté，源头是拉丁语 paupertas「贫穷」，其根 pauper「穷的」。穷的状态，就是 poverty。\",\"repellent\":\"repel 来自拉丁语 repellere「击退」：re- + pellere「驱赶」；再加 -ent。把虫与人赶跑的，就是 repellent。\",\"majestic\":\"majesty 来自拉丁语 maiestas「伟大、威严」，源头 maius（magnus「大」的比较级一系）；再加 -ic。大得有威严的，就是 majestic。\",\"occupation\":\"occupy 来自拉丁语 occupare「占住」：ob- + capere「抓」。手抓着不放的营生与地盘，都是 occupation。\",\"hostage\":\"来自古法语 hostage「人质、抵押」，其构成有一说为 hospes「客人」加 -age——客人被扣下成了抵押。此说较流行，如实标注为人质词源的常见解释。\",\"resemblance\":\"resemble 来自古法语 resembler，源头是拉丁语 resimilare 一系：re- + similare「使像」（similis「相似的」）。像的程度，就是 resemblance。\",\"antlered\":\"antler（鹿角）词源未完全定论：一说源自通俗拉丁语 *anteocularis「长在眼前的」，因鹿角生在双眼上方得名。此说流传最广，但没有确证，这里如实标注存疑。\",\"banner\":\"来自古法语 baniere「旗帜」，源头是通俗拉丁语 *bandaria，其根是哥特语 bandwa「标记、信号」。战场上认旗不认人，标记竖起来就是 banner；与 band（带子）同族。\",\"jockey\":\"Jock 是苏格兰语对 John 的昵称，指马夫小伙；再加指小后缀 -ey。骑在马背上的人，就是 jockey；引申为谋取（jockey for position）。\",\"seam\":\"古英语 sēam「缝、接缝」，源头 sēowian「缝」，与德语 Saum 同源。两片布接上的线，就是 seam。\",\"graffiti\":\"借自意大利语 graffiti「涂鸦」，是 graffito「刻画」的复数，源头 graffiare「抓、刻」，再往上是希腊语 graphein「写、刻」。墙上的刻写，就是 graffiti。\",\"inefficient\":\"in-「不」+ efficient「有效率的」：efficient 源头是拉丁语 efficere「做成」（ex- + facere「做」）。做不成事的，就是 inefficient。\",\"thoughtless\":\"thought 是古英语 þōht「思想」，源头 þencan「想」；再加 -less。没过脑的，就是 thoughtless。\",\"indecisive\":\"in-「不」+ decisive「果断的」：decide 源头是拉丁语 decidere「砍下定论」：de- + caedere「砍」。砍不下决心的，就是 indecisive。\",\"hive\":\"古英语 hȳf「蜂箱」，其更深来源不确定，可能与拉丁语 cupa「桶」同族一说。人造的蜂房，就是 hive。深层来源如实标注。\",\"ruddy\":\"rud 是古英语 rudu「红色、红颜料」一系，与 red 同族；再加 -dy。红扑扑的，就是 ruddy。\",\"hopeless\":\"hope（古英语 hopa）+ -less「没有」构成：指望全无的，就是 hopeless。\",\"suffix\":\"来自拉丁语 suffixus「被钉在下面的」，源头 suffigere：sub- + figere「钉」。钉在词尾的，就是 suffix（后缀）。\",\"fuddle\":\"来源不完全确定：可能与德语方言或 fuddle「灌醉」的拟声、混杂构词有关。脑子被酒搅糊的，就是 fuddle。如实标注存疑。\",\"scamp\":\"来源不完全确定：16 世纪指「抢路贼」，动词 scamp 可能源自中古荷兰语 schampen「逃走」一系。顽童与无赖，就是 scamp。如实标注。\",\"pettish\":\"pet「小脾气」义来源不完全确定：pet 本指「宠儿、宠坏的孩子」，闹脾气由此来；再加 -ish。动不动闹小性的，就是 pettish。如实标注。\",\"heavyset\":\"heavy + set「长成的」构成的 20 世纪词：身板厚实壮硕的，就是 heavyset。\",\"exceptional\":\"exception 来自拉丁语 exceptio「例外」，源头 excipere「取出」：ex- + capere「取」。从一堆里被单独取出来的，就是 exceptional。\",\"dashing\":\"dash「猛冲、泼溅」来源带拟声色彩，可能源自斯堪的纳维亚语；-ing 表样子。冲劲十足又潇洒的，就是 dashing。如实标注：dash 的深层来源未完全定论。\",\"swimmingly\":\"swimming（swim 的分词，比喻「顺流」）+ -ly：顺得像游泳的，就是 swimmingly（顺顺利利地）。swim 是古英语 swimman。\",\"blouse\":\"借自法语 blouse「罩衫」，词源未有定论：一说与拉丁语 pelusia（埃及佩鲁西翁产的衣物）有关，但证据不足，这里如实标注存疑。\",\"glaring\":\"glare 来源不完全确定：中古英语 glaren「闪耀、怒视」，可能源自中古荷兰语或与 glass 同族。刺眼的、怒目而视的，都是 glaring。如实标注。\",\"balm\":\"来自古法语 basme，源头是拉丁语 balsamum「香脂」，再往上是希腊语 balsamon，其根源在闪米特语。能涂抹疗伤的香脂，就是 balm；也比喻安慰。\",\"possibility\":\"possible 来自拉丁语 possibilis「可能的」，源头 posse「能够」：pot-「能」+ esse「是」。能成的事，就是 possibility。\",\"relation\":\"来自拉丁语 relatio「带回、关系」，源头 referre「带回」：re- + ferre「携带」。事物之间「带」出的联系，就是 relation。\",\"bothersome\":\"bother + -some。bother 词源存疑：可能源自盎格鲁-爱尔兰语，与爱尔兰语 bodhar「聋的、吵人的」有关，但没有定论，这里如实标注。缠人惹烦的，就是 bothersome。\",\"blockage\":\"block + -age「结果、状态」：木块堵在道上形成的状态，就是 blockage。\",\"gladsome\":\"glad 是古英语 glæd「明亮的、高兴的」，本义是「光滑发亮」；-some「有…倾向的」。亮堂堂乐呵呵的，就是 gladsome（古雅词）。\",\"revulsion\":\"来自拉丁语 revulsio「猛拉回」，源头 revellere：re- + vellere「拔、拉」。胃猛地往回抽的，就是 revulsion（厌恶、反胃）。\",\"dwarfish\":\"dwarf 是古英语 dweorg，其更深来源不确定（与德语 Zwerg 同源）；再加 -ish。矮小如侏儒的，就是 dwarfish。深层来源如实标注存疑。\",\"shaky\":\"shake 是古英语 sceacan「摇动」；再加 -y。摇个不停的，就是 shaky。\",\"consequent\":\"来自拉丁语 consequens「随之而来的」，源头 consequi：con- + sequi「跟随」。跟在后面发生的，就是 consequent；与 sequence 同根。\",\"bloodline\":\"blood + line「线」构成的复合词：血顺着一条线往下传，就是血统线。\",\"ravishing\":\"ravish 来自古法语 ravir「抢走、迷住」，源头是拉丁语 rapere「夺」。美到把魂「夺」走的，就是 ravishing。\",\"twinge\":\"古英语 twengan「掐、刺痛」，与德语 zwängen「挤压」同族。猛地一掐的痛，就是 twinge。\",\"shtick\":\"借自意第绪语 shtik「小把戏、段子」，源头是德语 Stück「一件、一段」。演员的招牌段子，就是 shtick。\",\"teeming\":\"teem「涌现」是古英语 tēman「生育、生产」，源头 tēam「后代、队伍」。多到往外涌的，就是 teeming；与 team 同根。\",\"childish\":\"child（古英语 cild）+ -ish「…似的」。像孩子的，多带贬义指幼稚；childlike 则是褒义的孩子气。\",\"visitant\":\"visit 来自拉丁语 visitare「去看」，是 visere「看」的反复形式；再加 -ant。来访者（尤指超自然的），就是 visitant。\",\"snooty\":\"snoot 是苏格兰语「鼻子、嘴脸」（snout 的变体）；再加 -y。鼻孔朝天的，就是 snooty（势利的）。\",\"realist\":\"real 来自晚期拉丁语 realis「关乎实物的」，源头 res「事物」；再加 -ist。只认实物的人，就是 realist。\",\"insulting\":\"insult 来自拉丁语 insultare「跳到（人身上）踩」，是 insilire「跳上」的反复形式：in- + salire「跳」。跳起来踩脸的话，就是 insulting；与 result（跳回→结果）的 sal- 同根。\",\"obsessive\":\"obsess 来自拉丁语 obsessus「被围困的」，源头 obsidere：ob- + sedere「坐」——敌军坐在城外围着。心被一个念头围困的，就是 obsessive。\",\"essential\":\"essence 来自拉丁语 essentia「本质」，是为对应希腊语 ousia「存在」造的词，源头 esse「是、在」。一个东西「是其所是」的部分，就是 essential。\",\"faithless\":\"faith + -less「没有」构成：信念与忠诚都缺席的，就是 faithless。\",\"grimy\":\"grime 来源不完全确定：中古英语 grim，可能源自中古低地德语或与古英语 grima「面具、污渍」有关；再加 -y。糊满污垢的，就是 grimy。如实标注。\",\"immediately\":\"immediate + -ly：不隔时间的，就是 immediately。\",\"moralistic\":\"moral 来自拉丁语 moralis「关乎风俗的」，源头 mos「习俗」（moris）；再加 -istic。拿着风俗尺子说教的，就是 moralistic。\",\"infuse\":\"来自拉丁语 infundere「倒进」：in- + fundere「倒」。把茶味、思想倒进去，就是 infuse。\",\"stunning\":\"stun 来源不完全确定：中古英语 stonen，可能是古法语 estoner「震晕」的缩略（源头拉丁语 ex- + tonare「打雷」一说）。震到晕的好，就是 stunning。如实标注。\",\"merciless\":\"mercy + -less「没有」构成：不留情的，就是 merciless。\",\"chieftain\":\"来自古法语 chevetain「首领」，源头是晚期拉丁语 capitaneus「为首的」，其根是 caput「头」。坐头把交椅的人，就是 chieftain；与 captain 同根。\",\"maddening\":\"mad 是古英语 gemǣded「被弄疯的」，源头 gemād「疯的」，其更深来源不确定；再加 -ing。气得人发疯的，就是 maddening。深层来源如实标注存疑。\",\"qualification\":\"qualify 来自中世纪拉丁语 qualificare「赋予性质」：qualis「怎样的」+ facere「做」；再加 -ation。配得上某种「性质」的证明，就是 qualification。\",\"overtime\":\"over + time 构成的 19 世纪词：工时之外的，就是 overtime（加班）。\",\"cliché\":\"借自法语 cliché，本是印刷术语「铅版」，是 clicher「浇铸铅版」的过去分词，带拟声（模具合上的咔哒声一说）。翻来覆去印的话，就是陈词滥调。此拟声来源为常见说法，如实标注。\",\"sorrowful\":\"sorrow 是古英语 sorh「悲伤、忧虑」，与德语 Sorge 同源；再加 -ful。满是悲的，就是 sorrowful。\",\"tingle\":\"来源不完全确定：中古英语 tinglen，可能是 tinkle「叮当」受 sting 影响的变体，带拟声色彩。麻酥酥的，就是 tingle。如实标注。\",\"sheared\":\"shear 是古英语 sceran「剪、切」：剪过毛的，就是 sheared。\",\"convenience\":\"convenient 来自拉丁语 conveniens「相合的、方便的」，源头 convenire「聚到一起、适合」：con- + venire「来」。万事凑到手边合用，就是 convenience。\",\"shimmy\":\"来源不完全确定：19–20 世纪词，一说由 chemise「衬衫」经黑人英语发音演变（舞蹈时肩带抖动），一说是拟声造词。抖肩的舞与车轮的摆振，都是 shimmy。如实标注存疑。\",\"corruptive\":\"corrupt 来自拉丁语 corruptus「败坏的」，源头 corrumpere：com-「彻底」+ rumpere「打破」。从内部被打破烂掉，就是 corruptive；与 rupture（破裂）同根。\",\"figurine\":\"借自法语 figurine，是 figure 的指小形式。小小的人像，就是 figurine。\",\"league\":\"（联盟义）来自古法语 ligue，源头是意大利语 liga，其根是拉丁语 ligare「捆绑」。绑在一起的，就是 league；注意里格（距离单位 league）是另一词，源自高卢语 leuca。\",\"detour\":\"借自法语 détour「绕行」，源头 détourner「转向」：dé- + tourner「转」（源头拉丁语 tornare「车削」）。绕开正路的一转，就是 detour。\",\"heartless\":\"heart + -less「没有」构成：没心的，就是 heartless。\",\"burdensome\":\"burden 是古英语 byrthen「重担」，由 beran「承载」加名词后缀构成；-some「有…倾向的」。压在肩上让人难担的，就是 burdensome；与 bear（熊/承载）的 ber- 同根。\",\"slicker\":\"slick 来源不完全确定：中古英语 slike「光滑的」，可能源自古英语 slician 或斯堪的纳维亚语；再加 -er。防水的油布雨衣，就是 slicker。如实标注。\",\"sacred\":\"来自拉丁语 sacer「神圣的、被献给神的」，经古法语 sacrer「祝圣」进入英语。献给神的，就是 sacred。\",\"preparedness\":\"prepare 来自拉丁语 praeparare「预先备好」：prae- + parare「准备」；再加 -ness。备好的状态，就是 preparedness。\",\"unfamiliar\":\"un- + familiar「熟悉的」构成。familiar 源头是拉丁语 familiaris「家里的」。不像家里人的，就是 unfamiliar。\",\"humanism\":\"human 来自拉丁语 humanus「人的」，源头 homo「人」；再加 -ism。文艺复兴把目光从神拉回「人」，就是 humanism。\",\"maternity\":\"来自中世纪拉丁语 maternitas「母性」，源头 maternus「母亲的」，其根 mater「母亲」。当母亲的状态与产科，都是 maternity。\",\"commanding\":\"command 来自古法语 comander，源头是晚期拉丁语 commandare「托付、命令」：com- + mandare「交托」（manus「手」+ dare「给」）。把事交到手上吩咐下去，就是 command；气势压人的也是它。\",\"aimless\":\"aim 经古法语 esmer 而来，源头是拉丁语 aestimare「估量」——瞄准前要先估准距离；-less「没有」。没有估准的目标，就是漫无目的。\",\"dignified\":\"dignify 源头是拉丁语 dignus「配得上的、有尊严的」+ facere「做」。端起配得上身份的样子，就是 dignified；与 dignity 同根。\",\"tournament\":\"来自古法语 torneiement「比武」，源头 torneier「绕场骑行」，再往上是拉丁语 tornare「车削、旋转」——骑士绕场打转。锦标赛，就是 tournament。\",\"hijack\":\"词源存疑：20 世纪美国词，一说源自劫匪让司机举手时喊的 high, Jack!，没有确证。劫机、劫车的，就是 hijack；这里如实标注，不把传说当定论。\",\"summons\":\"来自古法语 somonce「传唤」，源头是拉丁语 summonere「悄悄提醒、传唤」：sub- + monere「提醒」。法院的传票，就是 summons。\",\"pearly\":\"pearl 来源不完全确定：经古法语 perle 而来，源头可能是晚期拉丁语 perla，其更深来源有争议（一说与 perna「火腿、贝」有关）；再加 -y。珍珠般的，就是 pearly。深层来源如实标注存疑。\",\"untouchable\":\"un- + touchable「可触的」构成。touch 来自古法语 touchier，其更深来源带拟声色彩。碰不得的（贱民阶层义由此），就是 untouchable。深层来源如实标注。\",\"directional\":\"direction 来自拉丁语 directio「对直」，源头 dirigere「使直、指引」：di- + regere「使直」。指着方向走的，就是 directional。\",\"irresponsible\":\"ir-「不」+ responsible「负责的」：responsible 源头是拉丁语 respondere「回答、担责」（re- + spondere「许诺」）。担不起责的，就是 irresponsible。\",\"tendency\":\"来自中世纪拉丁语 tendentia「倾向」，源头 tendere「伸展、趋向」。往哪边伸的势头，就是 tendency。\",\"snazzy\":\"词源存疑：20 世纪美国俚语，可能是 snappy 与 jazzy 的混成，没有定论。时髦亮眼的，就是 snazzy；这里不硬编。\",\"shimmery\":\"shimmer 是古英语 scimerian「闪烁」，与德语 schimmern 同源；再加 -y。微光闪闪的，就是 shimmery。\",\"corrective\":\"correct 来自拉丁语 correctus「改正了的」，源头 corrigere：com- + regere「使直、统治」。把歪的拉直，就是 corrective；与 direct、regulate 的 reg- 同根。\",\"sightless\":\"sight 是古英语 gesiht「看见」，源头 sēon「看」；再加 -less。看不见的，就是 sightless。\",\"despairing\":\"despair 来自古法语 desperer，源头是拉丁语 desperare「绝望」：de-「失去」+ sperare「希望」（spes「希望」）。希望没了，就是 despairing；与 prosper（顺着希望→繁荣）同根。\",\"inflict\":\"来自拉丁语 infligere「打上、施加」：in- + fligere「打击」。把痛苦一拳打到别人身上的，就是 inflict；与 afflict 同根。\",\"gyp\":\"词源存疑：19 世纪美国俚语「骗」，一说源自 gypsy「吉卜赛人」的缩略（带歧视色彩的旧观念），没有确证。这里如实标注，不把偏见当词源定论。\",\"thousandfold\":\"thousand 是古英语 þūsend；再加 -fold「倍」（古英语 -feald）。千倍的，就是 thousandfold。\",\"elector\":\"elect 来自拉丁语 electus「被选出的」，源头 eligere：e- + legere「挑选」。有挑选资格的人，就是 elector；选帝侯也是它。\",\"reservoir\":\"借自法语 réservoir「蓄水池」，源头 réserver「保留」，再往上是拉丁语 reservare。把水留住的大池，就是 reservoir。\",\"squelch\":\"拟声构词：模仿踩烂泥的咕唧声，可能是 squash 与 elch 一类词的混成。踩灭、压制的，就是 squelch。\",\"glimmer\":\"中古英语 glimeren「微光闪烁」，源自斯堪的纳维亚语或中古低地德语，与 gleam 同族。暗处的一线光，就是 glimmer。\",\"mightily\":\"might 是古英语 miht「力量」，源头 magan「能够」，与德语 Macht 同源；再加 -ly。大力地，就是 mightily。\",\"coinage\":\"coin 经古法语 coing「楔子、印模」而来，源头是拉丁语 cuneus「楔子」——钱币是用楔形模压出来的。再加 -age。新造的词，也叫 coinage（像新铸的币）。\",\"unreasonable\":\"un- + reasonable「讲理的」构成。reason 来自拉丁语 ratio「计算、理性」。不讲理的，就是 unreasonable。\",\"scaffold\":\"来自古法语 eschafaut「台架」，源头是通俗拉丁语 *catafalicum 一系（与 catafalque「灵柩台」同源，其更深来源有争议）。搭起来的台：脚手架与绞刑台，都是 scaffold。深层来源如实标注。\",\"predictability\":\"predict 来自拉丁语 praedicere「预言」：prae- + dicere「说」；再加 -ability。事先说得准的程度，就是 predictability。\",\"scalpel\":\"直接借自拉丁语 scalpellum「小刀」，是 scalprum「刻刀」的指小形式，源头 scalpere「刻、切」。手术刀，就是 scalpel。\",\"tarry\":\"来源不完全确定：中古英语 tarien「拖延、逗留」，可能与古英语 tergan「拖」或拉丁语 tardus 一系的影响有关。磨蹭逗留的，就是 tarry。如实标注存疑。\",\"illustration\":\"illustrate 来自拉丁语 illustrare「照亮、阐明」：in- + lustrare「照亮」。给文字配上「光」的，就是 illustration（插图）。\",\"defuse\":\"de-「去除」+ fuse「引线、导火索」（源头是意大利语 fuso「纺锤」，因形得名）。把引线拆掉，就是 defuse；局面降温也用它。\",\"opinionated\":\"opinion 来自拉丁语 opinio「看法」，源头 opinari「认为」；再加 -ated。看法抱得死死的，就是 opinionated（固执己见的）。\",\"sampler\":\"sample 来自古法语 essample，源头是拉丁语 exemplum「样本、例子」；再加 -er。各样来一点的拼盘与刺绣样布，都是 sampler。\",\"preferable\":\"prefer 来自拉丁语 praeferre「放在前面、更爱」：prae- + ferre「携带」；再加 -able。愿意摆在前面的，就是 preferable。\",\"cashmere\":\"地名借词：克什米尔（Kashmir）产的山羊绒。地名经贸易路线进入英语，羊绒围巾就是 cashmere。\",\"geometric\":\"geometry 来自希腊语 geōmetria「土地测量」：gē「大地」+ metron「测量」。尼罗河泛滥后重丈土地的学问，就是 geometry；其形容词是 geometric。\",\"physique\":\"借自法语 physique「体格」，源头是拉丁语 physica「自然之学」，其根是希腊语 physis「自然」。天生的那副身板，就是 physique。\",\"becoming\":\"become 是古英语 becuman「到来、发生」：be- + cuman「来」。由「变成某人」引申出「与之相配」：becoming 的衣服，就是穿在身上正合适的。\",\"shallow\":\"古英语 sceald「浅的」，与 shoal「浅滩」同源，其更深来源不确定。水浅与见识浅，都是 shallow。深层来源如实标注存疑。\",\"ambitious\":\"来自拉丁语 ambitio，原义「四处走动拉票」：ambire「绕着走」（ambi- + ire「走」）。罗马候选人挨家挨户绕着拜票，这股劲后来就叫野心。\",\"scant\":\"借自古诺斯语 skamt「短的、少的」，是 skammr 的中性形式。少得不够分的，就是 scant。\",\"footwork\":\"foot + work 构成的复合词：拳台与舞池上脚的活儿，就是 footwork。\",\"taunt\":\"来源不完全确定：16 世纪词，可能源自法语 tenter「试探、引诱」的影响，或本土拟声构词。挑衅奚落的，就是 taunt。如实标注存疑。\",\"shocker\":\"shock 来源分两路合流：法语 choc「撞击」与德语 Schock 一系，带拟声色彩；再加 -er。吓人一跳的消息，就是 shocker。如实标注。\",\"counterfeit\":\"来自古法语 contrefait「仿造的」，源头是拉丁语 contrafacere「对着做、模仿」：contra- + facere「做」。照着真品「做」出来的，就是 counterfeit（赝品、伪钞）。\",\"presentable\":\"present 来自拉丁语 praesentare「呈上、展示」，源头 praesens「在场的」；再加 -able。拿得出手见人的，就是 presentable。\",\"icebreaker\":\"ice + breaker 构成：既指破开冰面的船，也指聚会上「破冰」的话题——两义共用一个复合词。\",\"ingratitude\":\"in-「无」+ gratitude「感激」（源头拉丁语 gratus「令人愉快的」）构成。不记好的，就是 ingratitude。\",\"forecast\":\"fore-「预先」+ cast「投、算」构成的中古英语词。cast 源自古诺斯语 kasta「投掷」。提前把骰子「投」出去算天气的，就是 forecast。\",\"admissible\":\"admit 来自拉丁语 admittere「放进来」：ad- + mittere「送」；-ible 表「可…的」。法庭肯「放进来」的证据，就是 admissible。\",\"likelihood\":\"likely 是中古英语按古诺斯语 líkligr 造的词：like「像」+ -ly；再加 -hood「状态」。像真的一样的程度，就是 likelihood。\",\"totalize\":\"total + -ize：加总到一的，就是 totalize。\",\"caboose\":\"来自荷兰语 kabuis「船上厨房」，经美国英语转指火车守车；其更深来源不确定，可能与德语 Kabüse 有关。深层来源如实标注存疑。\",\"taboo\":\"借自汤加语 tabu「神圣不可触的」，经库克船长航海记进入英语（1777）。碰不得的禁忌，就是 taboo。\",\"recurve\":\"re-「回」+ curve「弯」构成。curve 来自拉丁语 curvus「弯曲的」。往回弯的，就是 recurve（如反曲弓）。\",\"remainder\":\"remain 来自拉丁语 remanere「留下来」：re- + manere「停留」；再加 -der（仿法语 -dre 词尾）。剩下来的，就是 remainder。\",\"serial\":\"series 来自拉丁语 series「链、行列」，源头 serere「连接」；再加 -al。连成串出的，就是 serial（连载的、连续的）。\",\"swanky\":\"swank 来源不完全确定：方言词，可能与德语 schwanken「摇摆」或 swanky「苗条」一系有关；再加 -y。时髦气派的，就是 swanky。如实标注存疑。\",\"baffling\":\"baffle 词源存疑：16 世纪出现，先指「使丢脸」，后指「使困惑」；一说与法语 bafouer「嘲弄、愚弄」有关，一说源自苏格兰语 bauchle，都没有确证，这里如实标注。让人彻底摸不着头脑，就是 baffling。\",\"dumbfound\":\"dumb「哑的、说不出话的」（古英语 dumb）+ confound「弄糊涂」（拉丁语 confundere）拼合的 18 世纪词。惊得哑口无言，就是 dumbfound。\",\"immovable\":\"im-「不」+ movable「可移动的」（源头拉丁语 movere「移动」）构成。推不动的，就是 immovable。\",\"acknowledgment\":\"acknowledge 是中古英语 aknowlechen：由古英语 oncnawan「认出、承认」加上与 knowledge 相近的词尾构成。先「认出」事实，再公开认下，就是承认与致谢。\",\"thwack\":\"拟声构词：模仿重击的啪嗒声（16 世纪）。一记猛击，就是 thwack。\",\"rubbish\":\"来自盎格鲁-法语 rubbous 一系，其更深来源不确定（可能与 rubble「碎石」同族）。碎烂没用的，就是 rubbish。如实标注。\",\"tabloid\":\"商标成词：Tabloid 本是 1884 年注册的药片商标（tablet + -oid「像片剂一样浓缩」），后转指浓缩版小报。词源如实标注：由商标泛化而来。\",\"polygon\":\"来自希腊语 polygōnon「多角的」：poly- + gōnia「角」，经晚期拉丁语进入英语。多边形，就是 polygon。\",\"faddish\":\"fad 词源存疑：19 世纪出现，可能由 fiddle-faddle「无聊琐事」缩略而来，没有定论；再加 -ish。一阵风似的时髦，就是 faddish。深层来源如实标注存疑。\",\"heighten\":\"height（古英语 hēah「高」加名词后缀）+ -en「使…」构成。把高度与程度往上抬，就是 heighten。\",\"cinematic\":\"cinema 是 cinematograph 的缩略：希腊语 kinēma「运动」（kinein「动」）+ graphein「记录」。会动的记录，就是电影的 cinematic。\",\"mysterious\":\"mystery 来自希腊语 mystērion「秘密仪式」，源头 mystēs「入会者」，其根 myein「闭（眼、唇）」，经拉丁语、法语进入英语。闭着嘴不说的，就是 mysterious。\",\"membership\":\"member 来自拉丁语 membrum「肢体、成员」；再加 -ship「身份」。肢体归属身体的身份，就是 membership。\",\"spindle\":\"古英语 spinel「纺锤」，源头 spinnan「纺织」。纺线的细杆与细长的腿，都是 spindle。\",\"landfall\":\"land + fall 构成的航海词：船员望见陆地「落」入眼帘，就是 landfall；台风登陆也用它。\",\"angst\":\"借自德语 Angst「焦虑」，与拉丁语 angustia「狭窄、窘迫」同源，源头是印欧语 *angh-「窄、勒紧」。焦虑像被挤在窄缝里喘不过气，anguish（痛苦）也是这条根。\",\"lethal\":\"来自拉丁语 letalis「致死的」，源头 letum「死亡」。一下致命的，就是 lethal；与 Lethe（冥界忘川）的拼写相近但来源有别，如实标注。\",\"finalize\":\"final（源头拉丁语 finis「终点」）+ -ize「使…」构成的 20 世纪词。把事情推到终点的，就是 finalize。\",\"apolitical\":\"a-「不、非」+ political。political 来自希腊语 politikos「城邦的」，源头 polis「城邦」。对城邦事务不沾边，就是不问政治的。\",\"screechy\":\"screech 是 shriek 的变体（受斯堪的纳维亚语影响），拟声词；再加 -y。尖叫刺耳的，就是 screechy。\",\"knapsack\":\"来自荷兰语 knapzak「干粮袋」：knappen「吃、咬」+ zak「袋」。背着干粮的袋，就是 knapsack。\",\"clarity\":\"来自拉丁语 claritas「明亮、清晰」，源头 clarus「亮的」。光透过去的程度，就是 clarity；clear 与它同根。\",\"glorious\":\"glory（拉丁语 gloria）+ -ous「充满」。满是荣光的，就是 glorious。\",\"needless\":\"need（古英语 nēod「必需、迫切」）+ -less「没有」构成：用不着的，就是 needless。\",\"graceful\":\"grace 来自拉丁语 gratia「恩惠、优美」，源头 gratus「令人愉快的」；再加 -ful。举止如受恩宠般好看的，就是 graceful。\",\"treasury\":\"treasure 来自希腊语 thēsauros「宝库」，经拉丁语、古法语进入英语；再加 -y。存宝的地方，就是 treasury（国库）。\",\"noiseless\":\"noise 来自古法语 noise「喧闹、争吵」，其来源有一说与拉丁语 nausea「晕船、恶心」有关，未成定论；再加 -less。没动静的，就是 noiseless。深层来源如实标注存疑。\",\"rivalry\":\"rival 来自拉丁语 rivalis「共用一条溪的人」，源头 rivus「小溪」：同饮一溪的两家，最容易成对头。再加 -ry。对头之间的较劲，就是 rivalry。\",\"flounder\":\"（动词）来源不完全确定：可能是 founder「沉没」与 blunder「踉跄」的混合。挣扎着扑腾的，就是 flounder。如实标注：此混合说为常见解释。\",\"ultramodern\":\"ultra-「极端、超」（拉丁语 ultra「超过」）+ modern「现代的」拼合。现代过头的，就是 ultramodern。\",\"dandy\":\"词源存疑：18 世纪末出现，指讲究穿戴的男子；一说源自法语 dandin「傻瓜、摇晃的人」，一说与人名 Andrew 有关，没有定论。这里不硬编。\",\"quash\":\"来自古法语 quasser「撤销、粉碎」，源头是拉丁语 quassare「猛摇碎」，是 quatere「摇」的反复形式。把判决摇碎作废的，就是 quash。\",\"aboard\":\"a-「在…上」+ board（古英语 bord「木板、船舷」）。登船就是踩上船舷那块板；all aboard「全体上船」至今还是列车员的喊声。\",\"absorbent\":\"absorb 来自拉丁语 absorbere「吞下、吸入」：ab- + sorbere「啜、吞」。海绵把水「吞」进去，就是 absorbent。\",\"shard\":\"古英语 sceard「碎片、缺口」，源头 sceran「剪切」。陶与玻璃的碎片，就是 shard；与 share（剪下的一份）同根。\",\"contour\":\"经法语 contour 而来，源头是意大利语 contorno「轮廓」，其根可能是拉丁语 contornare「绕着转一圈」（tornare「车削、转」）。绕物体转一圈描下的线，就是 contour。\",\"maturity\":\"mature 来自拉丁语 maturus「成熟的、适时的」，其更深来源有一说与 manus 或 matutinus 一族有关，未定论。瓜熟蒂落的状态，就是 maturity。深层来源如实标注。\",\"savage\":\"来自古法语 sauvage「野生的」，源头是拉丁语 silvaticus「林子里的」，其根 silva「森林」。林子里没开化的，就是 savage。\",\"replacement\":\"replace 是 re- + place 构成：place 来自拉丁语 platea「广场、空地」（希腊语 plateia）。顶上空位的，就是 replacement。\",\"raggedy\":\"ragged 是古诺斯语 rögg「粗毛」加 -ed 构成一说；再加 -y。破破烂烂毛糙的，就是 raggedy。如实标注：此为常见说法。\",\"sizable\":\"size 来源有一路：中古英语 syse，是 assize「定规、法庭」的缩略，源头是拉丁语 assidere「坐着裁定」——尺寸是「裁定」下来的。再加 -able。够大的，就是 sizable。深层来源如实标注为常见说法。\",\"accessory\":\"来自中世纪拉丁语 accessorius「附加的」，源头是 accedere「走近、附上」。本不是主体、只是「附上来」的东西，就是配件；法律上指从犯。\",\"dainty\":\"来自古法语 daintié「珍品、美味」，源头是拉丁语 dignitas「价值、尊贵」。值得珍视的小而美之物，就是 dainty；与 dignity 同根。\",\"desolation\":\"desolate 来自拉丁语 desolatus「被遗弃的」，源头 desolare：de- + solus「单独的」。只剩一个人（或空无一人）的荒凉，就是 desolation。\",\"peaceful\":\"peace + -ful「充满」构成：满是和平的，就是 peaceful。\",\"disgraceful\":\"disgrace 经法语 disgrazia 而来，源头是意大利语 disgrazia：dis- + grazia「恩宠」（拉丁语 gratia）。从恩宠里掉出来的丢脸，就是 disgraceful。\",\"seniority\":\"senior 是拉丁语 senior「更年长的」，是 senex「老人」的比较级；再加 -ity。年长排出的次序，就是 seniority（资历）。\",\"serious\":\"来自拉丁语 serius「沉重的、认真的」，经古法语进入英语，其更深来源不确定。沉下脸的，就是 serious。深层来源如实标注存疑。\",\"insertion\":\"insert 来自拉丁语 insertus「被插入的」，源头 inserere：in- + serere「连接、编排」。插进去的动作与物，就是 insertion；与 series（编排成串）同根。\",\"whirlwind\":\"whirl（借自古诺斯语 hvirfla「旋转」）+ wind 构成的中古英语复合词。转着的风，就是 whirlwind（旋风）。\",\"trample\":\"tramp「重步走」+ -le 反复后缀构成的中古英语词。tramp 借自中古低地德语 trampen「跺」。反复踩踏的，就是 trample。\",\"plantation\":\"plant 来自拉丁语 planta「苗、脚掌」，plantare「栽种」；再加 -ation。成片栽下去的园子，就是 plantation（种植园）。\",\"jumbo\":\"词源有一段公案：19 世纪伦敦动物园名象 Jumbo 把词带火；象名本身可能源自斯瓦希里语 jambo「你好」或 jumbe「酋长」，未定论。特大号的，就是 jumbo。如实标注。\",\"reevaluate\":\"re- + evaluate「评估」构成。evaluate 是法语 évaluer 的英语化：é- + value「价值」（源头拉丁语 valere「有力、值」）。重新估值的，就是 reevaluate。\",\"plasticity\":\"plastic 来自希腊语 plastikos「可塑的」，源头 plassein「捏塑」。能捏成形的，就是 plasticity。\",\"kindliness\":\"kindly 是古英语 gecyndelic「合乎天性的、亲切的」，源头 gecynd「种类、天性」；再加 -ness。kind 的本义是「同类」：把人当同类待的温和，就是 kindliness。\",\"sightseeing\":\"sight + seeing 构成的 19 世纪旅游词：专程去「看」的，就是 sightseeing。\",\"mythical\":\"myth 来自希腊语 mythos「话语、故事」，经晚期拉丁语 mythus 进入英语；再加 -ical。只在故事里的，就是 mythical。\",\"improvement\":\"improve 的来源有一段公案：源自盎格鲁-法语 emprower「使有利」，其词干 prou「利益」源头是晚期拉丁语 prode「有益」；与 proof 无关。变得更有益，就是 improvement。\",\"separation\":\"separate 来自拉丁语 separare「分开」：se-「分开」+ parare「准备」一说构词。分开的动作与状态，就是 separation。深层构词如实标注为传统说法。\",\"handful\":\"hand（古英语 hand）+ -ful「一满…的量」构成的古英语复合词。一把抓满的量，就是 handful；引申为难管的人。\",\"testimonial\":\"testimony 来自拉丁语 testimonium「证词」，源头 testis「证人」；再加 -al。作证的话与感谢信，就是 testimonial。\",\"layover\":\"lay + over 构成的美国铁路、航空词：在中途「躺」一晚的，就是 layover（中途停留）。\",\"cocky\":\"cock「公鸡」+ -y：像公鸡一样昂首翘尾、神气活现，就是 cocky。\",\"cocoon\":\"经法语 cocon 而来，源头是普罗旺斯语 coucoun，可能与 coque「壳」同族（拉丁语 coccum「浆果、壳」一说）。蚕给自己裹的壳，就是 cocoon。深层来源如实标注。\",\"raunchy\":\"词源存疑：20 世纪美国空军俚语，先指邋遢，后指粗俗下流；确切来源未有定论。这里不硬编。\",\"hinge\":\"中古英语 henge「铰链」，与 hang「悬挂」同族：门挂在它上面转。成败所系的枢纽，也是 hinge。\",\"preserver\":\"preserve + -er：守住东西的人与物（救生圈 life preserver），就是 preserver。\",\"harpoon\":\"来自荷兰语 harpoen 或法语 harpon「钩子」，源头是古法语 harpe「爪、钩」，其根可能与拉丁语 harpe（希腊语 harpē「镰刀」）有关。带倒钩的鱼叉，就是 harpoon。深层来源如实标注。\",\"stubborn\":\"来源不完全确定：中古英语 stiborn，可能与 stub「树桩」有关——硬得像树桩。此说流传广但未证实，如实标注。\",\"antsy\":\"ant（蚂蚁，古英语 æmete）+ -sy 构成的美国口语词，19 世纪出现。像身上爬了蚂蚁一样坐不住，就是 antsy；俗语 ants in one's pants 说的正是它。\",\"thievery\":\"thief 是古英语 þēof，其更深来源不确定；再加 -ery「行径」。偷的行当，就是 thievery。深层来源如实标注存疑。\",\"inexplicable\":\"in-「不可」+ explicable「可解释的」：explain 源头是拉丁语 explanare「铺平」（ex- + planus「平」）。铺不平、说不通的，就是 inexplicable。\",\"shuddery\":\"shudder 来源不完全确定：中古英语 shodderen，可能源自中古荷兰语 schuderen「摇晃」一系；再加 -y。让人打寒战的，就是 shuddery。如实标注。\",\"sleigh\":\"借自荷兰语 slee「雪橇」，是 sled 的近亲（源头是印欧语 *sleidh-「滑」）。滑雪上跑的，就是 sleigh；与 slide 同族。\",\"immoral\":\"im-「不」+ moral「道德的」：moral 来自拉丁语 moralis，其根 mos「习俗」（mor- 是 mores「风俗」的词干）。不合风俗规矩的，就是 immoral。\",\"collision\":\"来自拉丁语 collisio「撞击」，源头 collidere：col- + laedere「伤害、撞击」。两物迎头撞伤，就是 collision；与 lesion（损伤）同根。\",\"substitute\":\"来自拉丁语 substitutus「被放来顶替的」，源头 substituere：sub- + statuere「竖立」。立在原位上的替身，就是 substitute。\",\"absentee\":\"absent（缺席的）+ -ee「…的人」。absent 来自拉丁语 absens：ab-「离开」+ esse「在、存在」——人不在场，就是 absentee。\",\"segmental\":\"segment 来自拉丁语 segmentum「切下的一段」，源头 secare「切」；再加 -al。分段的，就是 segmental。\",\"comparative\":\"compare 来自拉丁语 comparare「配对、比较」：com- + par「相等的」。把两个「等量齐观」地摆在一起，就是 compare；其形容词是 comparative。\",\"inkling\":\"来源不完全确定：中古英语 inkling「暗示」，可能与古英语 inca「怀疑、迹象」有关。心里的一点影儿，就是 inkling。如实标注。\",\"session\":\"来自拉丁语 sessio「坐、会期」，源头 sedere「坐」。大家坐下来开会的那一坐，就是 session。\",\"confection\":\"来自拉丁语 confectio「制成之物」，源头 conficere「做成」：con- + facere「做」。糖做出来的东西，就是 confection（糖果糕点）。\",\"collectible\":\"collect 来自拉丁语 collectus「聚集起的」，源头 colligere：col- + legere「拾、选」。值得拾起来藏着的，就是 collectible；与 college、legible 的 leg- 同根。\",\"tangle\":\"来源不完全确定：中古英语 tanglen，可能源自斯堪的纳维亚语（与瑞典语 taggla 一系或 tang「海藻」有关）。缠成团的，就是 tangle。如实标注。\",\"rebellious\":\"rebel 来自拉丁语 rebellare「重新开战、反叛」：re- + bellare「作战」（bellum「战争」）。不服管的，就是 rebellious；与 bellicose（好战的）同根。\",\"spare\":\"古英语 sparian「留、省、宽恕」，源头 spær「节俭的」。省下来的，就是 spare（备用的、清瘦的、多余的）。\",\"freckled\":\"freckle 来源不完全确定：中古英语 freken，可能源自古诺斯语 freknur「雀斑」（复数）。星星点点长在脸上的，就是 freckled。如实标注。\",\"abductor\":\"来自拉丁语 abducere「带走、领开」：ab-「离开」+ ducere「带领」。绑架就是把人从原地「领走」，与 conduct（引导）的 -duct 同根。\",\"mythology\":\"希腊语拼合词：mythos「故事」+ -logia「言说、学问」。成套的神话与研究它们的学问，都是 mythology。\",\"revamp\":\"re- + vamp「鞋面、补缀」构成的美国词：vamp 源自古法语 avantpié「鞋的前部」。给旧东西换新鞋面的，就是 revamp（翻新）。\",\"excellency\":\"excellent 来自拉丁语 excellens「高出众人的」，源头 excellere：ex- + cellere「高耸」一说。阁下（Your Excellency）的称呼由此而来。深层构词如实标注为一说。\",\"rubberneck\":\"rubber「橡胶」+ neck「脖子」构成的美国俚语：脖子像橡胶一样伸长看热闹，就是 rubberneck（围观）。\",\"romance\":\"来自古法语 romanz「罗曼语（写的故事）」，源头是拉丁语 romanice「用罗马俗语（写）」：用老百姓的罗曼语写骑士故事，就是 romance 的来历；言情义由此生。\",\"arrogance\":\"来自拉丁语 arrogare「自以为是地索取」：ad-「给自己」+ rogare「要求、请求」。把不属于自己的荣誉也「要求」过来，就是傲慢；与 interrogate（盘问）的 -rog- 同根。\",\"preferment\":\"prefer + -ment：被摆到前面去，就是 preferment（晋升）。\",\"bystander\":\"by「在旁」+ stander「站立者」构成：站在旁边看着的人，就是旁观者。\",\"receivable\":\"receive 来自拉丁语 recipere「取回、接收」：re- + capere「取」；再加 -able。应收的，就是 receivable。\",\"underway\":\"under + way 构成的航海词（借荷兰语 onderweg 的说法）：船已在路上的，就是 underway（进行中的）。\",\"disgusting\":\"disgust 来自古法语 desgouster「反胃」：des- + gouster「品尝」（源头拉丁语 gustare「尝」）。尝一口就想吐的，就是 disgusting；与 gusto（兴致勃勃地尝）同根。\",\"mindful\":\"mind 是古英语 gemynd「记忆、心思」，源头是印欧语 *men-「想」；再加 -ful。心里装着的，就是 mindful；与 memory 的 mem-、mental 同族。\",\"impatience\":\"im-「不」+ patience「耐心」：patience 来自拉丁语 patientia「忍耐」，源头 pati「承受」。受不了等的，就是 impatience。\",\"sappy\":\"sap 是古英语 sæp「树液」；再加 -y。汁水多的、多愁善感到腻的，就是 sappy。\",\"incremental\":\"increment 来自拉丁语 incrementum「增长」，源头 increscere：in- + crescere「生长」。一格一格长上去的，就是 incremental；与 increase 同根。\",\"pamper\":\"中古英语 pamperen「喂饱、纵容」，可能源自中古荷兰语或低地德语，与 pamp「粥、糊」一类词有关，未完全定论。喂得太好的，就是 pamper（溺爱）。如实标注。\",\"pamphlet\":\"来自古法语 Pamphilet：12 世纪拉丁语爱情诗 Pamphilus 的昵称——薄薄一本小册子借了诗名。没装订的小册子，就是 pamphlet。\",\"profession\":\"profess 来自拉丁语 professus「公开宣称的」，源头 profiteri：pro- + fateri「承认」。公开宣称要干的行当，就是 profession；与 confess（承认）同根。\",\"overthrow\":\"over + throw 构成的中古英语词：掀翻在地的，就是 overthrow（推翻）。\",\"peachy\":\"peach 来自拉丁语 persicum「波斯的（果）」——桃子经波斯传入罗马。再加 -y。好得像桃子一样的，就是 peachy（口语）。\",\"perfectionist\":\"perfection + -ist：凡事要做到 perfectus 的人，就是 perfectionist。\",\"supervision\":\"supervise 来自中世纪拉丁语 supervisus「被俯瞰的」，源头 supervidere：super-「在上」+ videre「看」。从上面看着的，就是 supervision。\",\"translation\":\"translate 来自拉丁语 translatus「被搬过去的」，源头 transferre「搬运」。把意思搬过语言的，就是 translation。\",\"restraint\":\"restrain 来自古法语 restraindre，源头是拉丁语 restringere「拉紧、约束」：re- + stringere「拉紧」。把缰绳拉住的，就是 restraint。\",\"overemphasize\":\"over- + emphasize「强调」构成。emphasis 来自希腊语 emphasis「显现、强调」，源头 emphainein「显示」。强调过头的，就是 overemphasize。\",\"squeegee\":\"squeegee 是 squeeze 的方言变体戏谑造词（19 世纪）：刮水板。squeeze 本身来源带拟声色彩。刮玻璃水的，就是 squeegee。\",\"whimsy\":\"来源不完全确定：17 世纪词 whim，先指「怪念头」，可能由 whim-wham「小玩意」缩略而来。再加 -y。心血来潮的怪趣，就是 whimsy。如实标注存疑。\",\"mishap\":\"mis- + hap「运气」构成。hap 借自古诺斯语 happ「好运」。运气出岔子的，就是 mishap（小事故）。\",\"veto\":\"直接借自拉丁语 veto「我禁止」，是 vetare「禁止」的第一人称——罗马护民官的一句话。否决权，就是 veto。\",\"exaggerate\":\"来自拉丁语 exaggerare「堆高、夸大」，源头 agger「土堆」：ex- + aggerare「堆土」。把土堆越堆越高的说法，就是 exaggerate。\",\"memorize\":\"memory 来自拉丁语 memoria「记忆」，源头 memor「记着的」；再加 -ize。装进记忆的，就是 memorize。\",\"rebound\":\"来自古法语 rebondir「弹回」：re- + bondir「跳跃」，其更深来源有一说与拉丁语 bombus「嗡嗡声」有关（弹跳带响）。弹回来的，就是 rebound。深层如实标注为一说。\",\"muzzle\":\"来自古法语 musel「口鼻部」，源头是中世纪拉丁语 musus「口鼻」，其更深来源不确定。套住口鼻的与枪口，都是 muzzle。深层来源如实标注存疑。\",\"predetermine\":\"pre- + determine「决定」（源头拉丁语 determinare「划界」）构成：事先划定的，就是 predetermine。\",\"trance\":\"来自古法语 transe「昏迷、恐惧」，源头是拉丁语 transire「跨过去」：trans- + ire「去」——魂跨到另一边。恍惚状态，就是 trance。\",\"sate\":\"satiate 的变体：satiate 来自拉丁语 satiare「喂饱」，源头 satis「足够」。喂到够的，就是 sate（餍足）。\",\"textural\":\"texture 来自拉丁语 textura「织法、质地」，源头 texere「织」；再加 -al。织出来的手感，就是 textural。\",\"abort\":\"来自拉丁语 aboriri「流产、夭折」：ab-「偏离」+ oriri「出生、升起」。没能正常「升起」来到世上，就是中止；与 origin（起源）的 or- 同根。\",\"zinger\":\"zing 是拟声词，模仿子弹与妙语嗖地飞过声；再加 -er。一句到位的妙语与打击，就是 zinger。\",\"blossom\":\"古英语 blōstm「花」，与 bloom 同源，源头是印欧语 *bhel-「开花、膨胀」。同根的还有 flower 与 flour——面粉曾是谷物「开花」的精华部分。\",\"bloat\":\"多认为源自古诺斯语 blautr「泡软的、湿的」。泡发了、肿胀了，就是 bloat；此说较可信但未完全定论，如实标注。\",\"proportional\":\"proportion 来自拉丁语 proportio「比例、均衡」：pro- + portio「份额」。份额对得上的，就是 proportional。\",\"undertake\":\"中古英语 undertaken「着手、承接」：under- 在此为古义「接受、担起」（非「在下」）。担起来的，就是 undertake。\",\"diminutive\":\"来自晚期拉丁语 diminutivus「缩小的」，源头 deminuere：de- + minuere「使小」（minus「更小」）。小到带昵称后缀的，就是 diminutive；与 minute（微小的）同根。\",\"predicament\":\"同 praedicare：中世纪逻辑学里「可断言的范畴」转指人的处境——被归到难堪一类的境地，就是 predicament（困境）。词义转折如实标注。\",\"alarmist\":\"alarm 来自意大利语号令 allarme「拿起武器！」（alle arme），经法语进入英语；-ist 表「…的人」。动不动就喊「拿起武器」的人，就是危言耸听者。\",\"normalcy\":\"normal 来自拉丁语 normalis「合尺的」，源头 norma「木工角尺」；-cy 是受 normalcy 造词之争的产物（19 世纪按 democracy 类推造出）。合尺的状态，就是 normalcy。\",\"shatter\":\"中古英语 schateren「打散」，可能是 scatter 的变体，受斯堪的纳维亚语影响。碎成渣的，就是 shatter。\",\"controversial\":\"controversy 来自拉丁语 controversia「争论」：contro-（contra「反对」）+ vertere「转」。各执一面转来转去的，就是 controversial。\",\"tapestry\":\"来自古法语 tapisserie「挂毯」，源头 tapis「地毯」，再往上是希腊语 tapēs「毯」，其更深来源可能为波斯语。织着故事的毯，就是 tapestry。深层来源如实标注。\",\"hoodlum\":\"词源存疑：19 世纪旧金山报纸词，一说由德语方言 hudelum「邋遢、乌合之众」演变，一说是记者把 muldoon 倒拼的戏作，没有定论。小流氓，就是 hoodlum；这里不硬编。\",\"tenant\":\"来自古法语 tenant「持有者」，是 tenir「握住」的分词形式，源头拉丁语 tenere。握着租约的人，就是 tenant。\",\"irk\":\"中古英语 irken「厌烦」，来源不完全确定，可能源自古诺斯语 yrkja「做、作」一系。惹人烦的，就是 irk。如实标注。\",\"occurrence\":\"occur 来自拉丁语 occurrere「跑来迎面、发生」：ob- + currere「跑」。迎面跑来的事，就是 occurrence。\",\"duplicate\":\"来自拉丁语 duplicare「对折、加倍」：duo「二」+ plicare「折」。折出两份来的，就是 duplicate。\",\"drowsy\":\"古英语 drūsian「迟钝、欲睡」的后代，与古诺斯语 drus- 一类词同族，深层来源不完全确定。眼皮直往下沉，就是 drowsy。如实标注。\",\"slobber\":\"中古英语 slobberen，带拟声色彩，可能源自中古荷兰语 slobberen「在泥里趟」。口水直流的，就是 slobber。\",\"purvey\":\"来自古法语 porveoir「供给」，源头是拉丁语 providere「预先备置」：pro- + videre「看」。事先看好备齐货的，就是 purvey（供应）；与 provision 同根。\",\"migraine\":\"经法语 migraine 而来，源头是希腊语 hēmikrania「半边头（痛）」：hēmi-「半」+ kranion「头颅」。只痛半边脑袋的，就是 migraine。\",\"splatter\":\"splat（拟声，湿物拍地声）+ -er 反复后缀。溅得到处都是的，就是 splatter。\",\"daft\":\"古英语 gedæfte「温和的、驯服的」，中古英语作 daft「愚钝的」：词义从「温顺」滑向「迟钝、发疯」。与 deft（灵巧）本是同一个词的两条支流。\",\"excruciating\":\"excruciate 来自拉丁语 excruciare「钉上十字架折磨」：ex- + cruciare「施以十字刑」（crux「十字」）。疼得像上刑的，就是 excruciating；与 crucial（十字路口→关键的）同根。\",\"summation\":\"同 summa：加总与总结陈词，就是 summation。\",\"catching\":\"catch 经盎格鲁-法语 cachier 而来，源头是通俗拉丁语 *captiare「追捕」，其根是拉丁语 capere「抓」。抓得住别人的病，就是传染的 catching；抓得住眼球也是它。\",\"predecease\":\"pre-「在…之前」+ decease「去世」构成的法律词。decease 来自拉丁语 decessus「离去」，源头 decedere：de- + cedere「走」。先走一步的，就是 predecease。\",\"satchel\":\"来自古法语 sachel「小袋子」，源头是拉丁语 saccellus，是 saccus「大袋」的指小形式。学生的小书包，就是 satchel。\",\"punctuality\":\"punctual 来自中世纪拉丁语 punctualis「关乎一点的」，源头 punctum「点」。准到点上的，就是 punctuality。\",\"derelict\":\"来自拉丁语 derelictus「被抛弃的」，源头 derelinquere：de- + relinquere「留下」（re- + linquere「离开」）。被主人扔下不管的，就是 derelict；与 relinquish（放弃）同根。\",\"submission\":\"submit 来自拉丁语 submittere「放低、提交」：sub- + mittere「送」。把头低下送上的，就是 submission。\",\"reconstruction\":\"re- + construction「建造」构成。construction 源头是拉丁语 construere「堆建」。重建（美国史上的 Reconstruction 特指南北战争后重建），就是 reconstruction。\",\"secrete\":\"（分泌义与藏匿义同源）由 secret 回构：拉丁语 secernere「分开」——腺体把物质「分」出来，人把东西「分」开藏。两义同出一根，如实标注。\",\"waddle\":\"来源不完全确定：可能是 wade「蹚水走」的反复形式变体（-le 表反复）。摇摇摆摆走的，就是 waddle。如实标注。\",\"simultaneous\":\"来自中世纪拉丁语 simultaneus「同时的」，源头 simul「一起」，可能受 instans 等词影响造出。同一刻发生的，就是 simultaneous。\",\"shepherd\":\"古英语 scēaphyrde「牧羊人」：scēap「羊」+ hyrde「看守者」。看羊的人，就是 shepherd。\",\"desperado\":\"借自西班牙语 desperado「绝望的人」，是 desesperado 受 desperate 影响的变体，源头同拉丁语 desperare「绝望」。亡命之徒，就是 desperado。\",\"equidistant\":\"equi-「相等」（拉丁语 aequus）+ distant「遥远的」（源头 distare「相隔」：dis- + stare「站」）拼合。站得一样远的，就是 equidistant。\",\"riven\":\"rive 是古英语 rīfan「撕裂」的后代（源自古诺斯语 rīfa）：被撕开的，就是 riven（诗体词）。\",\"hasten\":\"haste 来自古法语 haste，源头是日耳曼语 *haistiz「激烈、匆忙」；再加 -en。赶着来的，就是 hasten。\",\"secretive\":\"secret + -ive：嘴紧的，就是 secretive。\",\"envision\":\"en- + vision「看见」构成的 19 世纪词。vision 来自拉丁语 visio，源头 videre「看」。在心里先「看」见未来，就是 envision。\",\"tendril\":\"来自法语 tendrillon「嫩枝」，是 tendre「嫩的」的指小形式，源头拉丁语 tener「柔嫩的」。植物的嫩卷须，就是 tendril。\",\"stupefy\":\"来自拉丁语 stupefacere「使发呆」：stupere「发愣」+ facere「做」。吓呆、麻呆的，就是 stupefy。\",\"overlay\":\"over + lay「放」构成的古英语复合词：覆在上面一层的，就是 overlay。\",\"protégé\":\"借自法语 protégé「被保护者」，是 protéger「保护」的过去分词，源头拉丁语 protegere「遮护」。被大人物罩着的门生，就是 protégé。\",\"deviant\":\"deviate 来自晚期拉丁语 deviare「偏离道路」：de- + via「路」。走出正路的人与行为，就是 deviant。\",\"hysterical\":\"hysteria 按希腊语 hystera「子宫」造：古希腊医学认为歇斯底里是子宫游走所致（此说已过时，但词留了下来）。情绪失控的，就是 hysterical。\",\"scraggly\":\"scrag 来源不完全确定：可能与斯堪的纳维亚语 skragg 一系或 scrawny 同族，指瘦骨嶙峋。参差嶙峋的，就是 scraggly。如实标注。\",\"annul\":\"来自拉丁语 annullare「使归于无」：ad- + nullus「无、没有」。把婚约、法令按回「无」，就是宣布无效；与 null（空）同源。\",\"intersect\":\"来自拉丁语 intersectus「被切开的」，源头 intersecare：inter- + secare「切」。两线互相切过的，就是 intersect；与 section（切分）同根。\",\"grandeur\":\"借自法语 grandeur「宏伟」，源头 grand「大的」，再往上是拉丁语 grandis「巨大的」。大得有气势，就是 grandeur。\",\"collaborative\":\"collaborate 是 19 世纪按拉丁语 collaborare 造的词：col-「共同」+ laborare「劳动」（labor「劳作」）。一起干活的，就是 collaborative。\",\"nutritional\":\"nutrition 来自拉丁语 nutritio「喂养」，源头 nutrire；再加 -al。关乎喂养的，就是 nutritional。\",\"sundry\":\"古英语 syndrig「分开的、各自的」，源头 sundor「分开」。各色各样的，就是 sundry。\",\"solvability\":\"solve 来自拉丁语 solvere「松开、解开」：se- + luere「松」；再加 -ability。解得开的，就是 solvability。\",\"legalize\":\"legal 来自拉丁语 legalis「法律的」，源头 lex「法」；再加 -ize。把禁的变合法的，就是 legalize。\",\"dysfunctional\":\"dys-「坏的、异常的」（希腊语 dys-）+ functional（源头拉丁语 functio「执行」）。功能坏了的，就是 dysfunctional。\",\"fallacy\":\"来自拉丁语 fallacia「欺骗、谬误」，源头 fallax「骗人的」，其根 fallere「欺骗」。听起来对、其实骗人的推理，就是 fallacy。\",\"attainable\":\"attain 来自古法语 ateindre，源头是拉丁语 attingere「触及」：ad- + tangere「触摸」；-able 表「可…的」。伸手能碰到的目标，就是 attainable；与 tangent（相切）的 tang- 同根。\",\"kilter\":\"来源不完全确定：方言词，可能由 kelter「良好状态」（17 世纪）变来，其更深来源不明。out of kilter 就是状态不对、失调。如实标注存疑。\",\"spiel\":\"借自德语 Spiel「游戏、表演」或意第绪语 shpil：推销员的连珠炮说辞，就是 spiel。\",\"theorem\":\"来自希腊语 theōrēma「所见之物、定理」，源头 theōrein「看、思考」。看透了的真理，就是 theorem。\",\"nationwide\":\"nation + wide 构成的 20 世纪复合词：宽到全国的，就是 nationwide。\",\"paltry\":\"来源不完全确定：可能源自低地德语 paltrig「破烂的」一系（与 palter「讨价、敷衍」同族一说）。少得寒碜的，就是 paltry。如实标注。\",\"genetics\":\"按希腊语 genesis「起源、诞生」（gignesthai「生成」）在 20 世纪初造出的学科名。管出生与遗传的学问，就是 genetics。\",\"demilitarize\":\"de-「去除」+ military（源头拉丁语 miles「士兵」）+ -ize。把军队撤干净的地区，就是 demilitarized zone（非军事区）。\",\"conspiratorial\":\"conspire 来自拉丁语 conspirare「同呼吸、密谋」：con- + spirare「呼吸」。凑在一起压低呼吸商量坏事，就是 conspiratorial；与 spirit（呼吸→精神）同根。\",\"scabbard\":\"来自盎格鲁-法语 escauberc「剑鞘」，其构成有一说为日耳曼语 *skar-berg「护刃者」（保护刀刃的套子）。装剑的套，就是 scabbard。深层构词如实标注为常见说法。\",\"contextual\":\"context 来自拉丁语 contextus「编织在一起的」，源头 contexere：con- + texere「织」。话是织在上下文这块布里的，离了布就变味——contextual 说的正是这层关系；与 text（文本=织物）同根。\",\"gazebo\":\"词源存疑：18 世纪造的戏谑词，可能是 gaze「眺望」加拉丁语将来时词尾 -bo「我将」拼成的「我将眺望（亭）」，也可能受东方亭名影响。没有定论，这里不硬编。\",\"polarity\":\"polar 来自中世纪拉丁语 polaris「极的」，源头 polus「极」，再往上是希腊语 polos「轴、枢」。两极相对的性质，就是 polarity。\",\"heady\":\"head + -y：酒劲直冲头顶的，就是 heady；令人陶醉的成功也用它。\",\"iconic\":\"icon 来自希腊语 eikōn「像、图像」，经拉丁语 icon 进入英语；再加 -ic。成了时代「图像」符号的，就是 iconic。\",\"tedium\":\"来自拉丁语 taedium「厌倦」，源头 taedere「厌烦」。闷到厌的，就是 tedium。\",\"confinement\":\"confine 来自拉丁语 confinis「接界的」：con- + finis「边界」；再加 -ment。把人圈在边界之内，就是 confinement；与 final 的 fin- 同根。\",\"taupe\":\"借自法语 taupe「鼹鼠」，源头是拉丁语 talpa「鼹鼠」。鼹鼠毛的灰褐色，就是 taupe。\",\"stabilizer\":\"stable 来自拉丁语 stabilis「稳固的」，源头 stare「站」；再加 -izer。让东西站稳的，就是 stabilizer（稳定剂、安定翼）。\",\"saloon\":\"salon 的变体：salon 借自法语 salon「大厅」，源头是意大利语 salone，其根是日耳曼语 sal「大厅」。西部的大厅酒吧，就是 saloon。\",\"bristle\":\"古英语 byrst「刚毛」，与德语 Borste 同源，源头是印欧语 *bhars-「尖、突起」。猪鬃般根根竖起，就是 bristle；人被激怒「竖毛」也用它。\",\"maritime\":\"来自拉丁语 maritimus「近海的」：mare「海」+ -timus（最高级式后缀）。靠海的、航海的，就是 maritime。\",\"discrepant\":\"来自拉丁语 discrepans「不一致的」，源头 discrepare「发出不同声响」：dis- + crepare「作响」。说法对不上的，就是 discrepant。\",\"dominion\":\"来自拉丁语 dominio「主权」，源头 dominus「主人、主」，其根 domus「家」——家里的主人，引申为统治者。统治的疆域，就是 dominion。\",\"columnist\":\"column 来自拉丁语 columna「柱子」：报纸版面排成一根根「柱子」，专栏由此得名；再加 -ist。守着一根柱子写的人，就是 columnist。\",\"natter\":\"来源不完全确定：苏格兰方言词，可能源自古诺斯语 gnadd「抱怨」或带拟声色彩。没完没了地唠叨，就是 natter。如实标注。\",\"essayist\":\"essay 来自法语 essai「尝试」，源头是晚期拉丁语 exagium「称量」，其根 exigere「称出、考查」。蒙田把自己的随笔叫「尝试」；写这种尝试的人，就是 essayist。\",\"galley\":\"来自古法语 galie，源头是中世纪希腊语 galea「桨帆船」，其更深来源不确定。靠人划的大船与厨房（船上厨房义后发展），都是 galley。深层来源如实标注。\",\"centennial\":\"拉丁语拼合词：centum「百」+ annus「年」。一百年一遇的纪念，就是 centennial；与 century 同根。\",\"misbegotten\":\"mis-「坏地」+ begotten「所生的」（beget 源头是古英语 begietan「得到、生育」）构成。来路不正、生得不该的，就是 misbegotten。\",\"personnel\":\"借自法语 personnel「人员（全体）」，是 personne「人」的集合名词化。全体员工，就是 personnel；与 personal（个人的）分工不同。\",\"gargoyle\":\"来自古法语 gargouille「喉咙、滴水怪兽」：雨水从怪兽的「喉咙」里喷出。gargle 与它同源，都是喉咙里的咕噜声。\",\"multitude\":\"来自拉丁语 multitudo「众多」，源头 multus「多的」。多到成群的，就是 multitude。\",\"hospice\":\"来自古法语 hospice「收容所」，源头是拉丁语 hospitium「待客、客房」，其根 hospes「主人/客人」。朝圣路上收留旅人的地方，就是 hospice 的前身；与 hospital、hotel 同根。\",\"brigade\":\"经法语 brigade 而来，源头是意大利语 brigata「一队人」，其词根 briga「争执、队伍」的来源有凯尔特语与日耳曼语两说，未定论。一队士兵编成旅，就是 brigade；深层来源如实标注存疑。\",\"maraud\":\"借自法语 maraud「流浪汉、劫掠者」，其更深来源不确定。成群窜扰劫掠，就是 maraud。如实标注存疑。\",\"fabrication\":\"fabricate 来自拉丁语 fabricari「制造」，源头 fabrica「工场、制品」，其根 faber「工匠」。工场里做得出的，既可以是产品，也可以是编造的谎——fabrication 两义由此分岔。\",\"fertility\":\"fertile 来自拉丁语 fertilis「多产的」，源头 ferre「生育、承载」。能结出果实的，就是 fertility；与 bear（承载/生育）义通。\",\"acrophobia\":\"希腊语拼合词：akros「最高处」+ phobia「恐惧」（phobos）。站在高处就发病的恐惧，就是恐高症；acro- 也在 acrobat（高空杂技）里。\",\"inexactitude\":\"in-「不」+ exactitude「精确」：exact 源头是拉丁语 exigere「索求到底」（ex- + agere「驱动」）。求不准的，就是 inexactitude（法语借词色彩浓）。\",\"bottleneck\":\"bottle「瓶子」+ neck「脖子」构成的比喻词：再宽的瓶身也要从细脖子过，堵点就在那里。bottle 本身经古法语而来，源头是晚期拉丁语 buttis「桶」。\",\"mannered\":\"manner 来自古法语 maniere「方式」，源头是拉丁语 manuaria「用手的（方法）」，其根 manus「手」；再加 -ed。做派刻意、手法外露的，就是 mannered。\",\"vortex\":\"直接借自拉丁语 vortex「旋涡」，是 vertex 的变体，源头 vertere「转」。转着往下吸的，就是 vortex。\",\"outlandish\":\"古英语 ūtlendisc「外国的」：ūtland「外地」+ -isc。外地来的怪模样，就是 outlandish（古怪的）。\",\"traipse\":\"来源不完全确定：16 世纪词，可能与 trapse 一类方言词或法语 trapper 有关。拖着步子闲逛的，就是 traipse。如实标注存疑。\",\"chalice\":\"来自拉丁语 calix「杯子」（经古法语 chalice 进入英语），与希腊语 kalyx「花萼、壳」同源。圣餐里的大杯，就是 chalice。\",\"mockery\":\"mock 来源不完全确定：中古英语 mokken，可能源自古法语 mocquer「嘲笑」，其更深来源有争议；再加 -ery。嘲弄与拙劣仿品，都是 mockery。如实标注。\",\"foyer\":\"借自法语 foyer「炉边、休息厅」，源头是拉丁语 focus「炉灶、焦点」。观众围着取暖休息的大厅，就是 foyer；focus 与它同根。\",\"manufacture\":\"来自中世纪拉丁语 manufactura「手工制作」：manus「手」+ factura「制作」。本义全是手作，后来进了工厂，就是 manufacture。\",\"postern\":\"来自古法语 posterne「后门」，源头是晚期拉丁语 posterula，其根 posterus「后面的」：城墙背面的小门，就是 postern。\",\"durable\":\"来自拉丁语 durabilis「持久的」，源头 durare「变硬、持续」，其根 durus「硬的」。硬得住时间的，就是 durable；与 during（持续期间）同根。\",\"snorkel\":\"借自德语 Schnorchel「通气管」，二战时指潜艇的呼吸管，源头 schnorcheln 与鼻息声有关一说。浮潜的管子，就是 snorkel。如实标注。\",\"guild\":\"中古英语 gilde「行会」，源自古诺斯语 gildi「会费、宴会」或古英语 gield「付款、祭献」：会员凑份子交钱的组织，就是 guild。\",\"determinate\":\"determine 来自拉丁语 determinare「划定边界」：de- + terminare「限定」（terminus「终点」）。边界划清了的，就是 determinate。\",\"imperishable\":\"im-「不」+ perish「灭亡」：perish 来自拉丁语 perire「消亡」：per- + ire「去」。去不掉、烂不了的，就是 imperishable。\",\"relentless\":\"relent 来自拉丁语 relentare「变缓」一系（lentus「慢、黏」）；再加 -less。不松劲的，就是 relentless。\",\"telepathy\":\"tele-「远」+ -pathy「感受」（希腊语 patheia）由英国学者 F. W. H. Myers 在 1882 年造出。远距离感应的，就是 telepathy（心灵感应）。\",\"blarney\":\"来自爱尔兰科克郡的布拉尼城堡（Blarney Castle）：传说亲吻城堡的巧言石（Blarney Stone）就能获得花言巧语。地名本身源自爱尔兰语 An Bhlarna「小牧场」。\",\"soporiferous\":\"sopor 是拉丁语「沉睡」；-ferous「带来的」（ferre「携带」）拼合。带来睡意的，就是 soporiferous（催眠的，老派词）。\",\"annular\":\"来自拉丁语 anulus「小戒指、环」（anus「环」的指小形式）+ -ar。环状的年轮、环形日食，都用 annular。\",\"antipodes\":\"来自希腊语 antipodes「脚对脚的人」：anti-「相对」+ podes「脚」（pous 的复数）。古人想象地球对面的人与我们脚底对脚底；与 podium（脚台）的 pod- 同根。\",\"recantation\":\"recant 来自拉丁语 recantare「唱回、收回」：re- + cantare「唱」。当众把话唱回去的，就是 recantation（公开收回前言）。\",\"surfeit\":\"来自古法语 surfait「过度」，源头是拉丁语 superfactus 一系构词：super-「过」+ facere「做」——做过了头。吃到吐的过量，就是 surfeit。\",\"parvenu\":\"借自法语 parvenu「暴发户」，是 parvenir「到达、出人头地」的过去分词，源头是拉丁语 pervenire：per- + venire「来」。刚「到」上流社会的人，就是 parvenu。\",\"saponification\":\"saponify 按拉丁语 sapo「肥皂」（saponis）+ facere「做」造：油脂变肥皂的过程，就是 saponification（皂化）。sapo 本身是日耳曼语借进拉丁语的词，如实标注。\",\"joviality\":\"jovial 来自拉丁语 iovialis「属于朱庇特的」：Jove（Iuppiter）主喜乐，占星家说生于木星之下的人天性快活。乐天派的样子，就是 joviality。\",\"baneful\":\"bane 是古英语 bana「杀手、祸根、毒药」；-ful「充满」。古英语史诗里 bana 专指杀人者；带着杀机的，就是 baneful。\",\"impertinence\":\"im-「不合」+ pertinence「切题」：pertinent 源头是拉丁语 pertinere「关乎」（per- + tenere「握住」）。抓不住分寸的无礼，就是 impertinence。\",\"exasperation\":\"exasperate 来自拉丁语 exasperare「使粗糙、激怒」：ex- + asper「粗糙的」。脾气被磨粗了、耐心磨没了，就是 exasperation。\",\"conterminous\":\"con-「共同」+ terminus「终点、边界」（拉丁语）。边界贴在一起、范围重合的，就是 conterminous；与 terminal 同根。\",\"ligature\":\"来自晚期拉丁语 ligatura「捆扎」，源头 ligare「绑」。手术里扎血管的线与乐谱的连音线，都是 ligature。\",\"pinnate\":\"来自拉丁语 pinnatus「有羽的」，源头 pinna「羽毛、鳍」。羽状分开的叶，就是 pinnate。\",\"scabrous\":\"来自拉丁语 scabrosus「粗糙的」，源头 scaber「糙、长疥的」，其根 scabere「抓挠」。粗糙扎手的与下流的，都是 scabrous。\",\"usurer\":\"usury 来自中世纪拉丁语 usuria「利息」，源头 usura「使用（钱）」，其根 uti「用」。放高利贷的，就是 usurer。\",\"comestible\":\"借自法语 comestible，源头是中世纪拉丁语 comestibilis「可吃的」，其根是 comedere「吃掉」：com- + edere「吃」。能吃的东西，就是 comestibles；与 edible 同根。\",\"lackey\":\"经法语 laquais 而来，其更深来源有争议（一说与加泰罗尼亚语 alacay、阿拉伯语 al-qā'id 一系有关）。替人跑腿的仆从，就是 lackey；引申为走狗。如实标注存疑。\",\"carrion\":\"来自盎格鲁-法语 carogne，源头是通俗拉丁语 *caronia「腐肉」，其根是拉丁语 caro「肉」。烂掉的肉，就是 carrion；乌鸦的盘中餐。\",\"effloresce\":\"来自拉丁语 efflorescere「开花」：ex- + florescere「开花」（flos「花」）。盐霜像花一样在墙上开出来，就是 effloresce；与 flower 同根。\",\"coruscate\":\"来自拉丁语 coruscare「闪烁、颤动发光」。光一闪一闪地跳，就是 coruscate；文学词，日常少见。\",\"septennial\":\"拉丁语拼合词：septem「七」+ annus「年」。七年一次的，就是 septennial。\",\"schism\":\"来自希腊语 skhisma「裂缝」，源头 skhizein「劈开」，经拉丁语、古法语进入英语。教派与组织劈开的那条缝，就是 schism；与 scissor（剪）的 skh- 同族。\",\"omniscience\":\"omni-「全」（拉丁语 omnis「一切」）+ science「知识」（源头 scire「知道」）拼合的中世纪词。什么都知道，就是 omniscience。\",\"chimera\":\"来自希腊语 khimaira「母山羊」，是吕基亚一只狮头、羊身、蛇尾怪物的名字，经拉丁语进入英语。拼凑出来的怪物，后指妄想，就是 chimera。\",\"besot\":\"be-「使…透」+ sot「醉鬼、傻瓜」。sot 来自古法语 sot，其更深来源不确定。被酒泡透了神志，就是 besot；besotted 就是痴迷到糊涂。\",\"anticlimactic\":\"climax 来自希腊语 klimax「梯子」，指层层爬高；anti-「反」。爬到一半反着滑下来，就是虎头蛇尾的 anticlimactic。\",\"sanctimony\":\"来自拉丁语 sanctimonia「神圣、虔诚」，源头 sanctus「神圣的」。虔诚过了头成假的，就是 sanctimony（假道学）。\",\"dipsomania\":\"希腊语拼合词：dipsa「渴」+ mania「狂热」。渴酒如命的狂，就是 dipsomania（嗜酒狂）。\",\"necrologist\":\"necrology 是按希腊语造的词：nekros「尸体、死」+ -logia「记录」。写讣告、记死者的，就是 necrologist。\",\"xenophobe\":\"xeno-「外来的」（希腊语 xenos「陌生人、客人」）+ -phobe「恐惧者」拼合的 20 世纪词。怕外人的，就是 xenophobe（排外者）。\",\"clangorous\":\"clang 是拟声词，模仿金属撞击声，可能经拉丁语 clangor「号声、铿锵」强化；再加 -ous。铿锵作响的，就是 clangorous。\",\"sociality\":\"social 来自拉丁语 socialis「结伴的」，源头 socius「伙伴」；再加 -ity。爱结伴的性子，就是 sociality。\",\"happenstance\":\"happening 与 circumstance 的混成词（19 世纪美国造词）：偶然凑到一起的事，就是 happenstance。\",\"bulwark\":\"来自中古荷兰语或中古低地德语 bolwerc「木板工事」：bole「木板」+ werc「工事」。木板垒成的防御墙，就是 bulwark；巴黎的 boulevard（林荫大道）原也是拆掉的这类城防工事。\",\"volatile\":\"来自拉丁语 volatilis「会飞的、易挥发的」，源头 volare「飞」。一放就飞的（液体、脾气、行情），就是 volatile。\",\"ponderable\":\"ponder 来自拉丁语 ponderare「称量」，源头 pondus「重量」。称得出分量、值得掂量的，就是 ponderable；与 pound（磅）同根。\",\"statuary\":\"statue 来自拉丁语 statua「立像」，源头 statuere「竖立」，其根 stare「站」；再加 -ary。立着的像群，就是 statuary。\",\"corrigible\":\"来自晚期拉丁语 corrigibilis「可纠正的」，源头 corrigere「拉直、改正」。毛病还能拉直的孩子，就是 corrigible；incorrigible 则是无可救药。\",\"incommensurate\":\"in-「不」+ commensurate「相称的」：commensurate 是晚期拉丁语 commensuratus「同尺度量过的」（com- + mensura「量度」）。量不到一块儿的，就是 incommensurate。\",\"evanescence\":\"evanescent 来自拉丁语 evanescere「逐渐消失」：e- + vanescere「化为乌有」（vanus「空的」）。像雾一样淡到没有的，就是 evanescence；与 vain（空虚的）同根。\",\"inculpable\":\"in-「无」+ culpable「有罪的」：culpable 源头是拉丁语 culpabilis，其根 culpa「过错」。怪不到头上的，就是 inculpable。\",\"chancery\":\"来自古法语 chancellerie「大法官衙门」，chancelier 源头是晚期拉丁语 cancellarius「掌文书的官员」，其根是 cancelli「格栅」——官员坐在格栅后面办公。与 cancel（画格栅叉掉）同源。\",\"maleficence\":\"按拉丁语 maleficentia「作恶」造：male + facere「做」；再加 -ence。害人的行径与巫术，都是 maleficence。\",\"glomerate\":\"来自拉丁语 glomerare「卷成团」，源头 glomus「线团、球」。卷成一团的，就是 glomerate（团聚的）；与 globe 不是同源，但形近。\",\"rostrum\":\"直接借自拉丁语 rostrum「鸟喙、船头撞角」，源头 rodere「啃」。罗马广场用缴获的船头装饰讲坛，讲坛就叫了 rostrum。\",\"dilatation\":\"dilate 来自拉丁语 dilatare「展宽」：di- + latus「宽的」。瞳孔、血管张宽，就是 dilatation；与 latitude（宽度→纬度）同根。\",\"imprudent\":\"im-「不」+ prudent「谨慎的」：prudent 是拉丁语 prudens 的后代，而 prudens 是 providens「有远见的」的缩略。看不远的，就是 imprudent。\",\"variegate\":\"来自拉丁语 variegare「使斑驳」：varius「多样的」+ agere「做」。做出杂色的，就是 variegate。\",\"enigmatical\":\"enigma 来自希腊语 ainigma「谜语」，源头 ainissesthai「暗示着说」，经拉丁语进入英语。像谜一样难猜的，就是 enigmatical。\",\"amplification\":\"来自拉丁语 amplificare「做大」：amplus「宽大的」+ facere「做」。把声音做大，就是放大；与 ample（充足的）同源。\",\"indemnity\":\"来自中世纪拉丁语 indemnitas「免于损失」，源头 indemnis：in-「无」+ damnum「损失」。把损失填平的，就是 indemnity（赔偿、保障）。\",\"tenable\":\"借自法语 tenable「守得住的」，源头 tenir「握住、守住」，再往上是拉丁语 tenere「握住」。守得住的论点与阵地，就是 tenable。\",\"charter\":\"来自古法语 chartre，源头是拉丁语 chartula「小文件」，其根是 charta「纸」。写在纸上、盖了印的特许状，就是 charter。\",\"exclusivity\":\"exclusive 来自中世纪拉丁语 exclusivus「排外的」，源头 excludere「关在外面」：ex- + claudere「关」。把多数人关在门外的，就是 exclusivity。\",\"lucubration\":\"来自拉丁语 lucubratio「挑灯夜作」，源头 lucubrare「借灯光工作」，其根 lux「光」。挑灯写出的苦心之作，就是 lucubration。\",\"nodulose\":\"nodulose 同 nodulus 一系：满是小结的，就是 nodulose（老派生物词）。\",\"teratology\":\"terato-「怪物」（希腊语 teras「怪胎、征兆」）+ -logy「学问」拼合的 19 世纪医学词。研究畸形的，就是 teratology。\",\"pedate\":\"来自拉丁语 pedatus「有脚的」，源头 pes「脚」（pedis）。长着脚状分叉的（叶），就是 pedate。\",\"aleatoric\":\"来自拉丁语 aleatorius「赌博的」，源头 alea「骰子」。凯撒渡卢比孔河时说的 alea iacta est「骰子已经掷下」，说的就是这个 alea；靠掷骰子般的偶然，就是 aleatoric。\",\"bate\":\"bate 是 abate 的省音形式：abate 来自古法语 abatre「打落、减弱」，源头是拉丁语 battere「击打」。bated breath「屏住的呼吸」就是把呼吸「打落、压低」。\",\"binary\":\"来自拉丁语 binarius「成双的」，源头 bini「两个一组」，其根是 bis「两次」。0 和 1 两个数码，就是 binary 的世界。\",\"discussant\":\"discuss 来自拉丁语 discutere「打散、研讨」：dis- + quatere「摇打」；再加 -ant「…的人」。把问题打散了细究的人，就是 discussant。\",\"legation\":\"来自拉丁语 legatio「使团、使职」，源头 legare「派遣」。派出去的小使团与使馆，就是 legation。\",\"tunicate\":\"来自拉丁语 tunicatus「穿外衣的」，源头 tunica「束腰外衣」。有被膜包着的（生物），就是 tunicate。\",\"ethnocentrism\":\"ethno-「民族」（希腊语 ethnos）+ centrism「中心主义」（源头 kentron「中心」）拼合的 20 世纪学术词。拿自己民族当世界中心的，就是 ethnocentrism。\",\"denomination\":\"denominate 来自拉丁语 denominare「命名」：de- + nominare「叫名」（nomen「名字」）。按名字分出的类：教派、面额，都是 denomination。\",\"halitosis\":\"按拉丁语 halitus「呼吸、气息」+ 希腊语 -osis「病症」在 19 世纪造的医学词：口气的病，就是 halitosis。\",\"lucent\":\"来自拉丁语 lucens「发光的」，源头 lucere「发光」，其根 lux「光」。透着光的，就是 lucent；与 lucid（清亮的）同根。\",\"ophthalmic\":\"来自希腊语 ophthalmikos「眼的」，源头 ophthalmos「眼睛」。关乎眼睛的，就是 ophthalmic（眼科的）。\",\"disjunctive\":\"disjunct 来自拉丁语 disiunctus「分开的」，源头 disiungere：dis- + iungere「连接」。把选项分开「二选一」的，就是 disjunctive。\",\"effectually\":\"effect 来自拉丁语 effectus「做成、结果」，源头 efficere：ex- + facere「做」；再加 -ly。真能做成事的，就是 effectually。\",\"capacitate\":\"capacity 来自拉丁语 capacitas「容量」，源头 capax「能装的」（capere「容纳」）。使法律上「有资格装下权利」，就是 capacitate；与 capable 同根。\",\"insurrection\":\"来自拉丁语 insurrectio「起而反抗」，源头 insurgere：in- + surgere「升起」。从下面升起来反的，就是 insurrection；与 surge（涌起）同根。\",\"chastisement\":\"chastise 来自古法语 chastier，源头是拉丁语 castigare「惩戒、纠正」：castus「纯洁的」+ agere「驱动」。打是为了把人「纠回纯洁」，就是 chastisement；与 chaste 同根。\",\"sudoriferous\":\"sudor 是拉丁语「汗」；-ferous「带来的」（ferre「携带」）拼合的老派医学词。催汗的，就是 sudoriferous。\",\"sabbatical\":\"来自希腊语 sabbatikos「安息日的」，源头 sabbaton「安息日」，再往上是希伯来语 shabbāth「休息」。七年一休的长假，就是 sabbatical（学术休假）。\",\"extirpate\":\"来自拉丁语 exstirpare「连根拔除」：ex- + stirps「树干、根」。把根都刨了，就是 extirpate。\",\"comity\":\"来自拉丁语 comitas「友善、礼让」，源头 comis「和蔼的」。国家、机构之间的礼让，就是 comity。\",\"ambulatory\":\"来自拉丁语 ambulare「行走、散步」。能走动的病人叫 ambulatory patient；ambulance（救护车）本义是「流动医院」，也是这个词根。\",\"tumulus\":\"直接借自拉丁语 tumulus「坟丘」，源头 tumere「隆起」。隆起的土坟，就是 tumulus。\",\"refutable\":\"refute 来自拉丁语 refutare「驳回、反驳」，其更深来源有一说与 fundere 一族有关，未定论；再加 -able。驳得倒的，就是 refutable。深层来源如实标注存疑。\",\"unregenerate\":\"un- + regenerate「再生的」构成。regenerate 来自拉丁语 regenerare：re- + generare「产生」。死不悔改的，就是 unregenerate。\",\"pacifist\":\"pacific 来自拉丁语 pacificus「缔造和平的」：pax「和平」+ facere「做」；再加 -ist。主和的人，就是 pacifist。\",\"scrumptious\":\"词源存疑：19 世纪美国词，可能是 sumptuous「奢华的」戏谑改造（scrum- 仿 scrumptious 的音），没有定论。好吃到家的，就是 scrumptious；这里不硬编。\",\"automaton\":\"来自希腊语 automaton「自动之物」：autos「自己」+词根 ma-「动、意欲」。不用人推、自己会动的，就是自动机；automatic 也是它。\",\"nouveau\":\"借自法语 nouveau「新的」，源头是拉丁语 novellus「新近的」，其根 novus「新」。nouveau riche 是「新富」；新派的，就是 nouveau。\",\"anonymity\":\"来自希腊语 anōnymos「无名的」：an-「无」+ onyma「名字」；-ity 表状态。没有名字可查，就是匿名状态；与 synonym（同名→同义词）的 -onym 同根。\",\"discommode\":\"dis- + commode「方便的」（法语，源头拉丁语 commodus「合宜的」：com- + modus「尺度」）。给人添不方便，就是 discommode。\",\"usurpation\":\"usurp 来自拉丁语 usurpare「擅用、篡夺」，其构词有一说为 usu-「使用」+ rapere「抢」。抢来用的王位，就是 usurpation。深层构词如实标注为一说。\",\"pretermit\":\"来自拉丁语 praetermittere「放过、略过」：praeter-「越过」+ mittere「送」。送过去不管的，就是 pretermit（忽略、搁置）。\",\"precautionary\":\"precaution 经法语 précaution 而来，源头是晚期拉丁语 praecautio「预先提防」：prae- + cavere「小心」。先提防着的，就是 precautionary。\",\"villainous\":\"villain 来自古法语 vilain「农奴、粗人」，源头是通俗拉丁语 *villanus「庄园佃户」，其根是拉丁语 villa「庄园」——词义从「庄园农」一路滑到「恶棍」，如实标注这段滑坡。\",\"plague\":\"来自拉丁语 plaga「打击、创伤」，经古英语 plāga 与古法语 plague 合流。像重击一样落下的疫病，就是 plague；与 plaint（哀诉）的 plag- 同族一说。\",\"graceless\":\"grace + -less「没有」构成：没恩宠、没美感的，就是 graceless。\",\"undercurrent\":\"under + current「流」构成的复合词：水面下的流与暗涌的情绪，就是 undercurrent。\",\"soprano\":\"借自意大利语 soprano「最高的（声部）」，源头是拉丁语 superanus 一系，其根 supra「在上」。女高音，就是 soprano。\",\"ruinous\":\"ruin 来自拉丁语 ruina「倒塌」，源头 ruere「倒塌、猛冲」；再加 -ous。招致倒塌的，就是 ruinous。\",\"domesticate\":\"domestic 来自拉丁语 domesticus「家里的」，源头 domus「房子」。把野生动物领进「家」，就是 domesticate；与 dome（穹顶=房）同根。\",\"forsaken\":\"forsake 是古英语 forsacan「拒绝、放弃」：for- + sacan「争执、主张」。被彻底放手的，就是 forsaken。\",\"royalist\":\"royal 来自古法语 royal，源头是拉丁语 regalis「王的」，其根 rex「国王」；再加 -ist。保王的人，就是 royalist。\",\"kindling\":\"kindle「点燃」来源不完全确定：中古英语 kindelen，可能源自古诺斯语 kynda「点燃」一系。引火的小柴，就是 kindling。如实标注。\",\"underrate\":\"under- + rate「估价」构成：估低了的，就是 underrate。\",\"hankering\":\"hanker 来源不完全确定：可能源自荷兰语方言 hankeren「渴望」，与 hang「悬」同族一说——心悬着够不着。馋得心痒的，就是 hankering。如实标注。\",\"florist\":\"按拉丁语 flos「花」（floris）+ -ist 造出的词：与花打交道的人，就是 florist；与 flower 同根。\",\"scholarly\":\"scholar 来自拉丁语 scholaris「学校的」，源头 schola「学校、学派」，再往上是希腊语 skholē「闲暇」——闲暇才做得成学问。再加 -ly。有学问气的，就是 scholarly。\",\"unsanitary\":\"un- + sanitary「卫生的」构成。sanitary 源头是拉丁语 sanitas「健康」。不卫生的，就是 unsanitary。\",\"depressant\":\"depress 来自拉丁语 depressus「压下的」，源头 deprimere：de- + premere「压」。把神经活动压低的药，就是 depressant；与 press 同根。\",\"pallor\":\"直接借自拉丁语 pallor「苍白」，源头 pallere「发白」。病容的白，就是 pallor；与 pale 同根。\",\"sophisticate\":\"sophisticated 先指「掺假的、被 sophist 式诡辩扭曲的」，后转指老练世故——词义大翻身，如实标注。源头同 sophist（希腊语 sophos「聪明」）。\",\"semiconscious\":\"semi- + conscious「有意识的」拼合。conscious 来自拉丁语 conscius「自知、同谋」：con- + scire「知道」。半醒半昏的，就是 semiconscious。\",\"tribune\":\"同 tribunus：罗马护民官，后指讲坛与报纸名（如 Tribune）。护民的官，就是 tribune。\",\"descendant\":\"descend 来自拉丁语 descendere「爬下来」：de- + scandere「攀登」。家族树上往下「爬」的一代代，就是 descendant；与 scan（攀读→扫描）的 scand- 同根。\",\"incapable\":\"in-「不」+ capable「能干的」（源头拉丁语 capere「抓、容纳」）构成。抓不住事的，就是 incapable。\",\"pulverize\":\"来自晚期拉丁语 pulverizare「研成粉」，源头 pulvis「灰尘、粉末」。碾成粉的，就是 pulverize；与 powder（粉）同根。\",\"faculty\":\"来自拉丁语 facultas「能力、机会」，源头 facilis「容易的」。能轻松做事的本事，就是 faculty；大学的一个「系」是本事的集合，教师全体也是它。\",\"queue\":\"借自法语 queue「尾巴」，源头是拉丁语 cauda「尾巴」。排成一条尾巴的，就是 queue。\",\"vanity\":\"来自拉丁语 vanitas「空虚、虚荣」，源头 vanus「空的」。空心里的浮华，就是 vanity；与 vain 同根。\",\"centralization\":\"central 是拉丁语 centralis「居中的」（centrum「中心」）；再经 -ize、-ation 派生。把权力往中心收，就是 centralization。\",\"miscellaneous\":\"来自拉丁语 miscellaneus「混杂的」，源头 miscere「混合」。什么都掺一点的，就是 miscellaneous。\",\"atheism\":\"经法语 athéisme 而来，源头是希腊语 atheos「无神的」：a-「无」+ theos「神」。不认有神，就是 atheism；theology（神学）里的 the- 也是它。\",\"keel\":\"来自古诺斯语 kjölr「龙骨」，与德语 Kiel 同源。船底那条脊梁，就是 keel；even keel 是「平稳」。\",\"temporal\":\"来自拉丁语 temporalis「时间的、暂时的」，源头 tempus「时间」。属时间的与属世俗的，都是 temporal。\",\"haunch\":\"来自古法语 hanche「臀部」，源头是日耳曼语 *hanka「髋」。兽与人的臀腿部，就是 haunch。\",\"intermingle\":\"inter-「互相」+ mingle「混合」构成。mingle 是古英语 mengan「混合」的反复形式。掺到分不清的，就是 intermingle。\",\"fiscal\":\"来自拉丁语 fiscalis「国库的」，源头 fiscus「钱筐、国库」。装钱的筐归谁管，就是 fiscal（财政的）。\",\"presumption\":\"presume 来自拉丁语 praesumere「预先拿取、擅自假定」：prae- + sumere「取」。先自作主张的，就是 presumption（推测、放肆）。\",\"regression\":\"regress 来自拉丁语 regressus「退回」，源头 regredi：re- + gradi「行走」。往回走的，就是 regression（退化、回归）。\",\"nondescript\":\"non-「不」+ descript「被描述的」（拉丁语 describere「写下」）在 18 世纪造的词：描不出特征的，就是 nondescript。\",\"imposition\":\"impose 来自拉丁语 imponere「放上、施加」：in- + ponere「放」。把负担放到别人肩上的，就是 imposition。\",\"spindly\":\"spindle + -y：细得像纺锤的，就是 spindly。\",\"evade\":\"来自拉丁语 evadere「逃脱」：e-「出」+ vadere「行走」。走着走着溜掉，就是 evade；与 wade（蹚水走）的 vad- 同族。\",\"unadulterated\":\"un- + adulterated「掺假的」构成。adulterate 来自拉丁语 adulterare「掺杂、通奸」，其更深来源不确定。没掺假的纯的，就是 unadulterated。深层来源如实标注存疑。\",\"vitality\":\"vital 来自拉丁语 vitalis「生命的」，源头 vita「生命」；再加 -ity。命气的旺，就是 vitality。\",\"preconception\":\"pre- + conception「概念」构成：事先怀好的想法，就是 preconception（成见）。\",\"venture\":\"adventure 的缩略：adventure 来自拉丁语 adventura「将要发生的事」。押上运气试一把的，就是 venture（冒险、创业）。\",\"technological\":\"technology 是按希腊语 tekhnologia「技艺的系统论述」造的 17 世纪词。关乎技艺体系的，就是 technological。\",\"personification\":\"personify 是 persona + facere「做」的拼合：把抽象事物「做」成人，就是 personification（拟人）。\",\"smolder\":\"中古英语 smolderen「闷烧」，与古英语 smorian「窒息」同族一说。没明火地阴燃，就是 smolder；怒气闷烧也用它。如实标注。\",\"bittersweet\":\"bitter（古英语 biter「苦的、刺痛的」）+ sweet（古英语 swēte「甜的」）构成的复合词，最早是植物名「苦甜茄」，后用来形容苦乐交织的滋味。\",\"lubber\":\"中古英语 lobbe「笨汉」一系，来源不完全确定，可能与 lob「笨重下垂」同族。笨手笨脚的人，就是 lubber；landlubber 是旱鸭子水手。如实标注。\",\"cohesion\":\"cohere 来自拉丁语 cohaerere「粘在一起」：co- + haerere「黏着」。分子之间黏得紧，就是 cohesion；与 adhesive 的 haer- 同根。\",\"nullification\":\"nullify 按拉丁语 nullus「无」+ facere「做」造：把法令「做」成无。nullification 是美国政治史上的「废止论」专名。\",\"impotence\":\"来自拉丁语 impotentia「无力」，源头 impotens：in-「不」+ potens「有力的」（potis「能」）。有心无力的，就是 impotence；与 potent（强效的）同根。\",\"disregard\":\"dis-「不」+ regard「注视、在意」：regard 经古法语 regarder 而来，garder「看守」源头是日耳曼语 *wardon「守望」。眼睛不往那儿看，就是 disregard。\",\"perchance\":\"借自盎格鲁-法语 par chance「凭运气」：par「凭」+ chance「落点」。碰巧，就是 perchance（古雅词）。\",\"refinement\":\"refine + -ment：细到极致的讲究，就是 refinement。\",\"idol\":\"来自希腊语 eidōlon「影像、偶像」，源头 eidos「形相」，经拉丁语、古法语进入英语。被人供着的「像」，就是 idol；与 idea 同族。\",\"alluring\":\"allure 来自古法语 aleurrer「引诱」，词干 leurre「诱饵」源自日耳曼语，本是猎鹰人挥动的假饵。像诱饵一样勾人的，就是 alluring。\",\"instrumental\":\"instrument 来自拉丁语 instrumentum「工具、设备」，源头 instruere「搭建、装备」：in- + struere「堆建」。当工具用的、起关键作用的，都是 instrumental。\",\"prospective\":\"来自晚期拉丁语 prospectivus「前瞻的」，源头 prospicere：pro- + specere「看」。往前看的未来，就是 prospective。\",\"devolution\":\"devolve 来自拉丁语 devolvere「滚下、移交」：de- + volvere「滚动」。权力像球一样往下滚交，就是 devolution；与 revolve 同根。\",\"mangle\":\"来自盎格鲁-法语 mangler，可能与古法语 mangonner「砍剁」或 mahangier「致残」有关，未完全定论。轧布机（mangle）与「碾烂」义由此分岔。如实标注存疑。\",\"decennial\":\"拉丁语拼合词：decem「十」+ annus「年」。十年一度的，就是 decennial；与 decade 同根。\",\"bungalow\":\"借自印地语 banglā「孟加拉式的（房子）」，源头是地名 Bangla（孟加拉）。英属印度时期那种单层带游廊的住宅传回英国，就成了 bungalow。\",\"matinee\":\"借自法语 matinée「上午、午后场」，源头 matin「早晨」，再往上是拉丁语 matutinus「清晨的」。本指白天时段的演出，就是 matinee（日场）。\",\"azure\":\"来自古法语 azur，源头是阿拉伯语 al-lāzaward，再往上是波斯语 lāzhuward「青金石」。这种蓝色宝石的名字一路西传，就成了天蓝色 azure。\",\"knurled\":\"knurl + -ed：表面滚出棱纹、防滑的，就是 knurled（如相机拨轮）。\",\"wanderlust\":\"借自德语 Wanderlust「漫游欲」：wandern「徒步漫游」+ Lust「渴望」。19 世纪末进入英语。想走的瘾，就是 wanderlust。\",\"crone\":\"来自盎格鲁-法语 carogne「老母羊、老太婆」，与 carrion（腐肉）同源，本是骂人话。干瘦的老妇，就是 crone。\",\"sweltering\":\"swelter 是古英语 sweltan「热死、闷坏」的反复形式，与德语 schwelen 同族。热到闷坏的，就是 sweltering。\",\"upholstery\":\"upholster 是 uphold「托住」的变体派生：中古英语 upholder 指卖家具杂货的商人。给家具包面填充的行当，就是 upholstery。词源转折如实标注。\",\"unceremonious\":\"un- + ceremonious「讲礼的」构成。ceremony 来自拉丁语 caerimonia「仪式」，其更深来源不确定。不讲礼数的，就是 unceremonious。深层来源如实标注存疑。\",\"tryst\":\"来自古法语 triste「猎人的埋伏点」，其更深来源有一说与拉丁语 tristis 无关而与斯堪的纳维亚语 traust「信任」有关——约好的相会点。幽会，就是 tryst。如实标注：此说为常见解释之一。\",\"specificity\":\"specific 来自晚期拉丁语 specificus「构成种类的」：species「种类」+ facere「做」；再加 -ity。具体到种的程度，就是 specificity。\",\"alchemist\":\"alchemy 经古法语、阿拉伯语 al-kīmiyā 而来，源头多认为是希腊语 khēmeia「熔炼（金属）的技艺」。阿拉伯语的定冠词 al- 也留在了词头；chemistry 就是它去掉 al- 的后代。\",\"insentient\":\"in-「无」+ sentient「有感觉的」：sentient 源头是拉丁语 sentire「感觉」。没感觉的石头，就是 insentient。\",\"rotary\":\"来自中世纪拉丁语 rotarius「轮转的」，源头 rota「轮子」。绕轮转的，就是 rotary；环岛也叫 rotary。\",\"recitation\":\"同 recitare：出声背诵，就是 recitation。\",\"experiential\":\"experience 来自拉丁语 experientia「试验、经验」，源头 experiri「试」：ex- + periri，与 periculum「危险」同族——经验是从试错与险境里来的。亲历得来的，就是 experiential。\",\"recoil\":\"来自古法语 reculer「后退」，源头是通俗拉丁语 *reculare：re- + culus「臀」一说——往后缩。枪的后坐与人的退缩，都是 recoil。深层构词如实标注为常见说法。\",\"heterosexual\":\"hetero-「异」（希腊语 heteros「另一个」）+ sexual（源头拉丁语 sexus「性别」）拼合的 19 世纪词。被另一性别吸引的，就是 heterosexual。\",\"segregation\":\"segregate 来自拉丁语 segregare「从群里分出」：se- + grex「群」（gregis）。把人从群里拎出去隔开的，就是 segregation。\",\"interference\":\"interfere 经法语 entreferir 而来，本义「互相击打」：entre「之间」+ ferir「打」（源头拉丁语 ferire）。信号互打、好事被搅，都是 interference。\",\"readability\":\"read 是古英语 rǣdan「读、劝告、解释」，本义是「解出意义」；再加 -ability。解得顺的程度，就是 readability。\",\"cobbler\":\"中古英语 cobeler「修鞋匠」，其更深来源不确定，可能与 cobble「胡乱拼凑」同族。修鞋的人与水果馅饼（cobbler）同名不同源的说法并存；深层来源如实标注存疑。\",\"nonsensical\":\"nonsense 是 non- + sense「意义」在 17 世纪拼的词：没意义的话。再加 -ical。胡说八道的，就是 nonsensical。\",\"sprawl\":\"古英语 spreawlian「手脚乱动」，与德语 spreizen 一系同族。四仰八叉地摊开的，就是 sprawl。\",\"oblige\":\"来自拉丁语 obligare「绑住、使有义务」：ob- + ligare「绑」。情分把人绑住的，就是 oblige；承蒙帮忙的 obliged 由此来。\",\"cabaret\":\"借自法语 cabaret「小酒馆」，源头可能是中古荷兰语 camberete 一类词或皮卡第方言，确切来源有争议。有歌舞表演的小馆子，就是 cabaret。深层来源如实标注存疑。\",\"medicinal\":\"medicine 来自拉丁语 medicina「医术、药物」，源头 medicus「医生」；再加 -al。能入药的，就是 medicinal。\",\"impart\":\"来自拉丁语 impartire「分给、授予」：in- + partire「分」（pars「部分」）。把自己的一份分出去（知识、消息），就是 impart。\",\"debility\":\"来自拉丁语 debilitas「虚弱」，源头 debilis「无力的」：de- + habilis「能干的」一说。身体被掏空了力气，就是 debility。如实标注：debilis 的构词有一说如此。\",\"trundle\":\"trundle 本指「小轮」，是 trendle 的变体，与古英语 trendel「圆环、轮」同族。滚着走的床与步子，就是 trundle。\",\"knickers\":\"由人名缩略而来：华盛顿·欧文笔下荷兰裔纽约人 Knickerbocker 成了荷兰移民的代称，他们穿的宽松短裤就叫 knickerbockers，缩略为 knickers。\",\"transpose\":\"经法语 transposer 而来，源头是拉丁语 transponere：trans- + ponere「放」。把两样换位放的，就是 transpose。\",\"piffle\":\"拟声构词：模仿轻蔑的噗声与无聊话，19 世纪词。废话与胡闹，就是 piffle。\",\"defunct\":\"来自拉丁语 defunctus「已卸任的、已故的」，源头 defungi「履行完（职责）」：de- + fungi「执行」。使命完成、人去楼空的机构，就是 defunct；与 function 同根。\",\"armament\":\"来自拉丁语 armamenta「（船的）装备、武装」，源头 armare「武装」，词干 arma「武器」。一国的 arma 储备，就是军备；与 army、armor 同族。\",\"irrelevance\":\"ir-「不」+ relevance「相关」：relevant 源头是拉丁语 relevare「举起、减轻」，法律义转指「切题」。举不到点子上的，就是 irrelevance。深层词义转折如实标注。\",\"originate\":\"同 origo：从源头升起的，就是 originate。\",\"federation\":\"federate 源头是拉丁语 foedus「盟约、条约」。各邦订约合成一体的，就是 federation；与 federal 同根。\",\"inconsumable\":\"in-「不」+ consumable「可消耗的」（源头拉丁语 consumere「耗尽」：con- + sumere「取」）。耗不尽的，就是 inconsumable。\",\"blithesome\":\"blithe 是古英语 blīþe「快乐的、温和的」；-some「有…倾向的」。古英语诗歌里 blīþe 也形容神明的仁慈；满脸轻快，就是 blithesome。\",\"luxurious\":\"luxury 来自拉丁语 luxuria「奢靡、茂盛」，源头 luxus「奢华」；再加 -ous。注意 luxury 与 lust 在古英语里曾有交集，但 lux- 的正源是拉丁语 luxus。华美过盛的，就是 luxurious。\",\"titian\":\"以意大利画家提香（Tiziano Vecellio）的名字命名：他画中标志性的红金发色，就是 titian（红褐色的）。人名成词，如实标注。\",\"accelerator\":\"accelerate 来自拉丁语 accelerare「使加快」：ad- + celer「快速的」；-or 表示做事的装置。油门就是让车「变快」的那只踏板。\",\"indigestible\":\"in-「不」+ digestible「可消化的」：digest 源头是拉丁语 digerere「分开搬运」（dis- + gerere「携带」）。肠胃搬不动的，就是 indigestible。\",\"turmoil\":\"来源不完全确定：16 世纪词，可能由 tire「折磨」与 moil「苦干」拼合，或源自古法语 tremouille 一类词。乱成一团的，就是 turmoil。如实标注存疑。\",\"permissive\":\"permit + -ive：管得松的，就是 permissive。\",\"adoration\":\"adore 来自拉丁语 adorare「祈求、崇拜」：ad- + orare「说话、祈祷」。跪下来开口祈祷，就是崇拜；orare 也在 orator（演说家）里。\",\"infatuate\":\"来自拉丁语 infatuare「使变傻」：in- + fatuus「愚蠢的」。爱到变傻的，就是 infatuate。\",\"slapdash\":\"slap「拍」（拟声）+ dash「猛冲」构成的 17 世纪词：拍上去就冲的干法，就是 slapdash（草率的）。\",\"parsonage\":\"parson 来自中世纪拉丁语 persona「教区牧师」——教区里的「那个人」（拉丁语 persona 本义面具、角色）；再加 -age。牧师的宅子，就是 parsonage。\",\"incompetence\":\"in-「不」+ competence「胜任」：compete 源头是拉丁语 competere「一同争取、相合」（com- + petere「追求」）。争不来、办不成的，就是 incompetence。\",\"urgency\":\"urgent 来自拉丁语 urgens「催逼的」，源头 urgere「压、催」。催得紧的，就是 urgency。\",\"broody\":\"brood 是古英语 brōd「一窝（孵出的雏）」，与 breed 同根；-y 表状态。母鸡趴在窝上不走，就是 broody；人闷闷沉思也用它。\",\"marketability\":\"market 来自拉丁语 mercatus「贸易、市场」，源头 mercari「买卖」（merx「货物」）；再加 -ability。卖得出去的程度，就是 marketability。\",\"ghostly\":\"ghost 是古英语 gāst「灵魂、气息」，与德语 Geist「精神」同源；再加 -ly。像幽灵的，就是 ghostly。\",\"exhilarate\":\"来自拉丁语 exhilarare「使高兴」：ex- + hilarare「使欢乐」（hilaris「欢快的」，源头希腊语 hilaros）。高兴到飞起，就是 exhilarate；hilarious 与它同根。\",\"straight-laced\":\"strait「紧的」（源头拉丁语 strictus「拉紧的」）+ laced「系带的」的原词，被误写成 straight-laced：紧身系带→拘谨古板。原形是 strait-laced，如实标注这段误写史。\",\"terminable\":\"terminate 来自拉丁语 terminare「划界、结束」，源头 terminus「终点」；再加 -able。可终止的，就是 terminable。\",\"remembrance\":\"remember 来自古法语 remembrer，源头是晚期拉丁语 rememorari「重新记起」：re- + memor「记着的」。记在心里的，就是 remembrance。\",\"foremost\":\"古英语 formest「最先的」，本是 forma「第一」加最高级 -mest，后受 most 影响改了拼写。排在最最前面的，就是 foremost。\",\"singularity\":\"singular 来自拉丁语 singularis「单个的、独特的」，源头 singulus「单个的」；再加 -ity。独一个的怪与奇点，就是 singularity。\",\"foxed\":\"fox（古英语 fox）+ -ed：旧书页上那些狐毛色的褐斑叫 foxing，像被狐狸踩过。受潮发霉的纸面，就是 foxed。此得名为常见说法，如实标注。\",\"forthcoming\":\"forth + coming 构成的中古英语复合词：从前面走着来的，就是 forthcoming（即将到来的；乐意提供的）。\",\"vandalism\":\"Vandal 是日耳曼部落汪达尔人的族名：455 年他们洗劫罗马，族名从此与破坏绑定（此词 18 世纪在法国造出）。故意毁坏公物的，就是 vandalism。族名绑定史如实标注。\",\"embitter\":\"em-「使…」+ bitter（古英语 biter「苦的、刺痛的」，与 bite「咬」同根）构成。使心里发苦的，就是 embitter。\",\"horticulture\":\"拉丁语拼合词：hortus「园子」+ cultura「耕作」。园子里的耕作学，就是 horticulture；与 agriculture（田地耕作）是姐妹词。\",\"expendability\":\"expend 来自拉丁语 expendere「称出、付出」：ex- + pendere「称量」。称着银子付出去、可以耗掉的，就是 expendable；expendability 是「可消耗性」。\",\"seafarer\":\"sea + farer「行者」构成的中古英语复合词：farer 源头是古英语 faran「行走、航行」。在海上讨生活的人，就是 seafarer。\",\"rebuke\":\"来自盎格鲁-法语 rebuker「斥责」，其构成不完全确定，可能为 re- + buker「打」一系。严厉指责，就是 rebuke。如实标注存疑。\",\"ovation\":\"来自拉丁语 ovatio「小凯旋式」，源头 ovare「欢呼」。罗马的小凯旋，后成全场起立的欢呼，就是 ovation。\",\"gable\":\"来自古诺斯语 gafl「山墙」，与德语 Gabel「叉」同族一说。屋顶两坡夹出的三角墙，就是 gable。深层关联如实标注为一说。\",\"paranoia\":\"来自希腊语 paranoia「心智错乱」：para-「偏离」+ nous「心智」。心智偏到被害妄想的，就是 paranoia。\",\"pizzazz\":\"词源存疑：20 世纪美国俚语（哈莱姆一带），可能是 jazz、pizazz 的押韵造词，没有定论。活力与炫劲，就是 pizzazz；这里不硬编。\",\"dignitary\":\"dignity 来自拉丁语 dignitas「尊严、要职」，源头 dignus「配得上的」；再加 -ary「…的人」。配坐在高位上的人，就是 dignitary。\",\"engrossing\":\"engross 本指「用大字体缮写（法律文件）」：en- + gross「大的」（源头晚期拉丁语 grossus「粗大的」）。后来转指心神被「大字」占满——吸引人的，就是 engrossing。\",\"diagnostic\":\"来自希腊语 diagnōstikos「能分辨的」，源头 diagignōskein「辨别」：dia-「透彻」+ gignōskein「知道」。看透病因的，就是 diagnostic；与 know 的 gno- 同族。\",\"discourteous\":\"dis-「无」+ courteous「有宫廷礼的」（源头 court「宫廷」）。没礼数的，就是 discourteous。\",\"disengage\":\"dis-「脱开」+ engage「啮合、订婚」：engage 经法语 engager 而来，gage「抵押品」源头是日耳曼语 *wadi「保证」。从啮合里退出来，就是 disengage。\",\"transfigure\":\"来自拉丁语 transfigurare「改变形状」：trans- + figura「形状」。形变到发光的，就是 transfigure（耶稣变容即 Transfiguration）。\",\"boarder\":\"board + -er。board 是古英语 bord「木板」，引申出「餐桌」再到「膳食」：在别人家搭伙吃饭的人，就是 boarder；寄宿生也是它。\",\"managerial\":\"manager（manage + -er）+ -ial「…的」。当管家（手）的那一套，就是 managerial。\",\"fluted\":\"flute 来自古法语 flaute，其更深来源不确定，可能带拟声色彩；乐器笛子与建筑凹槽（fluting）共用此名。带凹槽纹的，就是 fluted。深层来源如实标注存疑。\",\"despicable\":\"despise 来自拉丁语 despicere「俯视、轻视」：de- + specere「看」。从上往下看不起的，就是 despicable；与 inspect（往里看）的 spec- 同根。\",\"berth\":\"来源不完全确定：多认为由 bear「承载」的词干加名词后缀 -th 构成，指船在码头「被安放」的位置，后引申为卧铺。此说较可信但未成定论，如实标注。\",\"linear\":\"来自拉丁语 linearis「线的」，源头 linea「亚麻线」。成一条线的，就是 linear。\",\"credibility\":\"credible 来自拉丁语 credibilis「可信的」，源头 credere「相信」；再加 -ity。信得过的程度，就是 credibility；与 credit、creed 同根。\",\"recourse\":\"来自拉丁语 recursus「跑回」，源头 recurrere：re- + currere「跑」。没路时跑回去求的那条路，就是 recourse（求助、追索权）。\",\"darksome\":\"dark（古英语 deorc）+ -some「有…倾向的」构成的诗体词。阴沉沉的，就是 darksome。\",\"sincerity\":\"sincere 来自拉丁语 sincerus「纯正的、真诚的」，其构词有一段公案：传统说法 sine cera「无蜡」并不可靠，sincerus 的确切构成未有定论。如实标注存疑，不拿传说当定论。\",\"quietus\":\"中世纪拉丁语 quietus「清账、了结」：账清了，人安息——哈姆雷特的 make his quietus 指「了结自己」。了断与死亡，就是 quietus。\",\"expansible\":\"expand 来自拉丁语 expandere「展开」：ex- + pandere「铺开」。能铺展开的，就是 expansible；与 pace（步幅）的 pand- 同族。\",\"elude\":\"来自拉丁语 eludere「躲开、戏弄」：e- + ludere「玩耍」。像捉迷藏一样滑掉，就是 elude；与 illusion 同根。\",\"necrosis\":\"来自希腊语 nekrōsis「坏死」，源头 nekros「尸体」。组织死掉，就是 necrosis。\",\"gall\":\"（胆量、厚脸皮义）gall 本义「胆汁」（古英语 gealla）：古人认为胆汁主怒。胆汁涨上来的厚脸皮，就是 gall；胆囊义与它同源。\",\"cardiovascular\":\"希腊语 kardia「心」+ 拉丁语 vasculum「小管道」（vas「器皿」的指小形式）拼合的心血管医学词。心脏加血管，就是 cardiovascular。\",\"methodical\":\"method 来自希腊语 methodos「（沿）路（追寻）」：meta- + hodos「路」，经拉丁语进入英语；再加 -ical。按路数走的，就是 methodical。\",\"tipsy\":\"来源不完全确定：可能由 tip「倾斜、翻倒」派生——醉得站不稳要倒。再加 -y。微醺的，就是 tipsy。如实标注为常见说法。\",\"decommission\":\"de-「解除」+ commission「委任、服役状态」（源头拉丁语 committere「交托」）构成的 20 世纪词。把舰船、核电站「撤下岗」，就是 decommission。\",\"hearth\":\"古英语 heorþ「炉床、灶」，与德语 Herd 同源。家的中心那团火，就是 hearth；引申为家庭。\",\"enliven\":\"en-「使…」+ liven「使活泼」（life + -en）构成的 17 世纪词。把场子弄活，就是 enliven。\",\"complimentary\":\"compliment 经法语、意大利语 complimento 而来，源头是拉丁语 complere「完成、做满」：com- + plere「满」。把礼数「做满」，就是恭维；免费赠送也是「补满」人情。\",\"scowl\":\"来源不完全确定：中古英语 scoulen，可能源自斯堪的纳维亚语（丹麦语 skule「阴沉地看」一说）。眉头拧成一团的，就是 scowl。如实标注。\",\"truncheon\":\"来自古法语 tronçon「断块、残段」，源头是通俗拉丁语 *truncionem，其根是拉丁语 truncus「树干」。截短的棍，就是 truncheon（警棍）。\",\"resurface\":\"re- + surface「表面」构成的 20 世纪词。surface 是法语 surface：sur-「上」+ face「面」。重新浮上来的，就是 resurface。\",\"airlift\":\"air + lift（源自古诺斯语 lyfta「举起」，与 loft「阁楼」同源）组成的 20 世纪复合词：用飞机把物资「举」过封锁线，就是空运。\",\"inquest\":\"来自古法语 enqueste「调查」，源头是通俗拉丁语 *inquaesta，其根是拉丁语 inquirere「查问」：in- + quaerere「寻求」。官府查问死因的，就是 inquest；与 question 同根。\",\"brutality\":\"brutal 经法语而来，源头是拉丁语 brutus「迟钝的、未开化的」；再加 -ity。像没开化的野兽一样行事，就是 brutality；brute（畜生）与它同源。\",\"martyr\":\"来自希腊语 martys「证人」（martyr- 是其词干），经拉丁语、古英语进入英语：为信仰「作证」而死的人。见证到死的，就是 martyr；与 witness 义通。\",\"cancerous\":\"cancer 来自拉丁语 cancer「螃蟹」，是希腊语 karkinos 的翻译：古希腊医生希波克拉底看肿瘤的血管像蟹腿。巨蟹座也是这只螃蟹。\",\"mellow\":\"来源不完全确定：中古英语 melwe，可能与古英语 melu「面粉」同族（软如粉、熟透的果子），也可能受 meal 影响。熟软香甜的，就是 mellow。如实标注。\",\"plumage\":\"借自法语 plumage「羽毛（全体）」，源头 plume「羽毛」，再往上是拉丁语 pluma。一身的羽，就是 plumage。\",\"tumultuous\":\"tumult 来自拉丁语 tumultus「骚动」，源头 tumere「膨胀」一系——人群胀起来的乱。喧闹混乱的，就是 tumultuous。\",\"accession\":\"来自拉丁语 accessio「走近、增加」，动词 accedere：ad- + cedere「走」。走近王位就是即位，走近组织就是加入；与 access 同源。\",\"consolatory\":\"console 来自拉丁语 consolari「安慰」：con- + solari「抚慰」。能把人劝回来的话，就是 consolatory；solace（慰藉）与它同源。\",\"soubrette\":\"借自法语 soubrette「俏皮女仆（角色）」，源头是普罗旺斯语 soubreto，其更深来源不确定。歌剧里机灵的女仆，就是 soubrette。如实标注。\",\"imprecate\":\"来自拉丁语 imprecari「诅咒、祈祸」：in- + precari「祈祷」。把祈祷反着用、求祸降临，就是 imprecate；与 pray 同根。\",\"cacophonous\":\"希腊语拼合词：kakos「坏的」+ phōnē「声音」。好声音是 euphony，坏声音就是 cacophony——刺耳杂音。\",\"translucence\":\"translucent 来自拉丁语 translucens「透光的」：trans- + lucere「发光」。光过得去、人看不透的，就是 translucence。\",\"resurgence\":\"resurge 来自拉丁语 resurgere「重新升起」：re- + surgere「涌起」。沉下去又涌起的，就是 resurgence。\",\"distrait\":\"借自法语 distrait「心不在焉的」，是 distraire「使分心」的过去分词，源头是拉丁语 distrahere「拉向各方」。心被拉散了，就是 distrait。\",\"sophistry\":\"sophist + -ry：诡辩的那套把戏，就是 sophistry。\",\"biddable\":\"bid + -able。bid 在古英语里合流了两个词：biddan「请求」和 bēodan「吩咐、命令」；biddable 取的是后者——听吩咐、好使唤。\",\"ambiance\":\"借自法语 ambiance「氛围」，源头 ambiant「环绕着的」，再往上是拉丁语 ambire「绕着走」：ambi-「两边、周围」+ ire「走」。绕着你转的那圈空气，就是氛围。\",\"noxious\":\"来自拉丁语 noxius「有害的」，源头 noxa「伤害」，其根 nocere「伤害」。毒得伤人的，就是 noxious；与 innocent（不害人）同根。\",\"recalcitrance\":\"recalcitrant 来自拉丁语 recalcitrare「踢回、尥蹶子」：re- + calx「脚跟」（calcis）——马用后脚跟踢人。死活不从的，就是 recalcitrance。\",\"expenditure\":\"同 expend：称量着花出去的钱，就是 expenditure；与 expense 同根。\",\"poignancy\":\"poignant 来自古法语 poignant「刺痛的」，是 poindre「刺」的分词形式，源头拉丁语 pungere「刺」。刺到心口的，就是 poignancy；与 point（刺尖）同根。\",\"drubbing\":\"drub 来源不完全确定：可能经爱尔兰或阿拉伯语渠道进入（阿拉伯语 ḍarb「击打」一说），17 世纪出现。一顿痛打，就是 drubbing。如实标注存疑。\",\"abstention\":\"abstain 来自拉丁语 abstinere「克制不沾」：abs-「离开」+ tenere「握住」。手不伸出去碰，就是弃权、戒绝。\",\"differential\":\"different 来自拉丁语 differens「有区别的」，源头 differre：dis- + ferre「携带」——被带向不同方向。再加 -ial。拉开差距的，就是 differential。\",\"stoicism\":\"Stoic 来自希腊语 stōikos「属于柱廊的」：芝诺在雅典的彩绘柱廊（stoa poikilē）讲学。柱廊派的忍耐，就是 stoicism（坚忍）。\",\"esculent\":\"来自拉丁语 esculentus「可吃的」，源头 esca「食物」，其根是 edere「吃」。能吃的植物，就是 esculent；老派词，日常少见。\",\"stridency\":\"strident 来自拉丁语 stridens「发出刺耳声的」，源头 stridere「嘎吱作响」（拟声）。刺耳强硬的，就是 stridency。\",\"intrepid\":\"来自拉丁语 intrepidus「毫不发抖的」：in- + trepidus「慌张发抖的」。枪林里腿不抖的，就是 intrepid。\",\"solstitial\":\"solstice 来自拉丁语 solstitium「太阳停住」：sol「太阳」+ sistere「站定」；再加 -al。太阳「站住」的日子（至日）的，就是 solstitial。\",\"oxymoron\":\"来自希腊语 oxymōron「尖锐的愚蠢」：oxys「尖、锐」+ mōros「愚钝」——聪明的矛盾。甜蜜的痛苦这类，就是 oxymoron（矛盾修辞）。\",\"vertiginous\":\"vertigo 来自拉丁语 vertigo「旋转、眩晕」，源头 vertere「转」。转得人晕的，就是 vertiginous。\",\"aqueous\":\"来自中世纪拉丁语 aqueus「水的」，源头 aqua「水」+ -eous「…质的」。水溶液就是 aqueous solution；aquarium（水族馆）也是 aqua 的一家。\",\"epitomize\":\"epitome 来自希腊语 epitomē「删节、概要」，源头 epitemnein「切短」：epi- + temnein「切」。把长篇切成精华的，就是 epitome；浓缩成人形典范，就是 epitomize。\",\"reticence\":\"来自拉丁语 reticentia「沉默」，源头 reticere：re- + tacere「沉默」。话到嘴边收住的，就是 reticence。\",\"compendium\":\"来自拉丁语 compendium「节省、概要」，本义「一起称量」：com- + pendere「称、挂」。把厚书称出分量、浓缩成册，就是 compendium。\",\"gasconade\":\"借自法语 gasconnade「吹牛」，源头是地名 Gascony（加斯科涅）——法国人笑话加斯科涅人爱吹牛，就像地名梗。大话连篇，就是 gasconade。\",\"cosmopolite\":\"来自希腊语 kosmopolitēs「世界公民」：kosmos「世界」+ politēs「公民」。犬儒学派第欧根尼自称是它；四海为家的人，就是 cosmopolite。\",\"recumbency\":\"recumbent 来自拉丁语 recumbens「躺着的」，源头 recumbere：re- + cubare「躺」一系。躺平的状态，就是 recumbency。\",\"reparation\":\"repair（修复义）来自拉丁语 reparare「重新备好」：re- + parare「准备」。备好补回的，就是 reparation（赔偿、修复）。\",\"tantara\":\"拟声构词：模仿喇叭的嘹亮声（拉丁语 taratantara 是其古例）。号声大作，就是 tantara（老派词）。\",\"narcolepsy\":\"按希腊语造的医学词：narkē「麻木」+ lēpsis「发作、抓取」（lambanein「抓」）。睡魔「抓」住不放的病，就是 narcolepsy（发作性睡病）。\",\"potentate\":\"来自晚期拉丁语 potentatus「权力、君主」，源头 potens「有力的」，其根 posse「能够」。大权在握的人，就是 potentate。\",\"peptic\":\"来自希腊语 peptikos「助消化的」，源头 peptein「煮、消化」。关乎消化的，就是 peptic（如 peptic ulcer 消化性溃疡）。\",\"veracious\":\"来自拉丁语 verax「说真话的」，源头 verus「真的」；再加 -ious。句句实的，就是 veracious。\",\"slaughterous\":\"slaughter 借自古诺斯语 slátr「屠宰」，与 slay 同族；再加 -ous。杀气腾腾的，就是 slaughterous（老派词）。\",\"repugnant\":\"来自拉丁语 repugnans「反抗的、相抵触的」，源头 repugnare：re- + pugnare「打」（pugnus「拳头」）。拳头相向般抵触的，就是 repugnant（令人厌恶的）。\",\"gallantry\":\"经法语 galanterie 而来：galant「殷勤的」，是 galer「寻欢」的现在分词，其更深来源有争议。对女士殷勤与战场勇敢，都是 gallantry。深层来源如实标注存疑。\",\"orbicular\":\"来自拉丁语 orbicularis「圆盘状的」，源头 orbis「圆圈、圆盘」。圆成盘的，就是 orbicular。\",\"foliaceous\":\"来自拉丁语 foliaceus「叶状的」，源头 folium「叶子」。薄得像叶子的，就是 foliaceous；与 foliage 同根。\",\"sanative\":\"来自晚期拉丁语 sanativus「能治愈的」，源头 sanare「治愈」，其根 sanus「健康的」。养病的，就是 sanative（疗养的，老派词）。\",\"deanery\":\"dean 来自晚期拉丁语 decanus「十人长」，源头 decem「十」——修道院里管十个修士的人；再加 -ery。主任牧师的辖区与住宅，就是 deanery。\",\"recessional\":\"recession（退场义）来自拉丁语 recessio「退回」，源头 recedere：re- + cedere「走」；再加 -al。散会时唱的退场赞美诗，就是 recessional。\",\"exigent\":\"来自拉丁语 exigens「迫切要求的」，源头 exigere「驱出、索求」：ex- + agere「驱动」。催得紧、等不得的，就是 exigent；与 exact（索求到底→精确）同根。\",\"lecherous\":\"lecher 来自古法语 lecheor「好色之徒」，源头 lechier「舔、纵欲」，其根是日耳曼语 *likkon「舔」。纵欲无度的，就是 lecherous；与 lick 同根。\",\"extraneous\":\"来自拉丁语 extraneus「外来的」，源头 extra「在外」。从外面多出来的，就是 extraneous；与 strange（外来的→陌生的）同根。\",\"demimonde\":\"借自法语 demi-monde「半个世界」：demi「半」（源头拉丁语 dimidius）+ monde「世界」。游走在正经社会边缘的交际圈，就是 demimonde；出自小仲马的剧作名。\",\"meteoric\":\"meteor 来自希腊语 meteōron「空中之物」：meta- + aeirein「升起」，经中世纪拉丁语进入英语；再加 -ic。像流星一样蹿升（也速落）的，就是 meteoric。\",\"tillage\":\"till 是古英语 tilian「耕作、致力」，其更深来源与「目标」一系有关一说；再加 -age。耕地这件事，就是 tillage。深层来源如实标注。\",\"jetsam\":\"jettison 的缩略变体：jettison 来自古法语 getaison「抛弃」，源头是拉丁语 iactare「投掷」。为保船抛下海的货，就是 jetsam；与 flotsam（漂浮残骸）相对。\",\"defoliate\":\"按拉丁语构词造出：de-「去除」+ folium「叶子」+ -ate。把叶子打光的落叶剂，就是 defoliate 的工具；与 foliage（枝叶）同根。\",\"estimable\":\"esteem 来自拉丁语 aestimare「估价」，经古法语 estimer 进入英语；再加 -able。在心里估出高价、值得敬重的，就是 estimable。\",\"assuredly\":\"assure 经古法语 assurer 而来，源头是通俗拉丁语 *assecurare「使安心」：ad- + securus「无忧虑的」（se-「无」+ cura「忧虑」）；再加 -ly。把忧虑拿掉，就是肯定无疑；secure 也是这条根。\",\"cuboid\":\"cube 来自希腊语 kybos「立方体、骰子」，经拉丁语 cubus 进入英语；-oid「像…的」。长得像立方体的骨头与形状，就是 cuboid。\",\"keynote\":\"key「调」（音乐）+ note「音」构成：定调的那个主音，就是 keynote；大会的基调演讲由此得名。\",\"egomaniac\":\"ego 是拉丁语「我」；mania 是希腊语「狂热」。「我」字发了狂，就是 egomaniac（自大狂）。\",\"cairn\":\"借自苏格兰盖尔语 càrn「石堆」，与威尔士语 carn 同源。山顶上人垒人加的指路石堆，就是 cairn。\",\"proprietary\":\"proprietor 来自晚期拉丁语 proprietarius「业主」，源头 proprietas「所有权」，其根 proprius「自己的」。自家独有的，就是 proprietary。\",\"usurious\":\"usury + -ous：利滚利吃人的，就是 usurious。\",\"superlative\":\"来自拉丁语 superlativus「夸大的、最高级的」，源头 superlatus「被抬过头的」。抬到顶点的，就是 superlative（最高级的、最棒的）。\",\"disapprobation\":\"dis- + approbation「赞同」：approve 经古法语 aprover 而来，源头是拉丁语 approbare「证实为好」：ad- + probare「检验」（probus「正直的」）。公开说不好，就是 disapprobation。\",\"colloquialism\":\"colloquial 来自拉丁语 colloquium「谈话」：col- + loqui「说」。日常说话里用的词，就是 colloquialism；与 loquacious（健谈的）同根。\",\"stalactite\":\"按希腊语 stalaktos「滴下的」造的 17 世纪词：stalassein「滴」。一滴滴挂下来的，就是 stalactite（钟乳石）。\",\"occultation\":\"occult 来自拉丁语 occultus「藏起的」，源头 occulere：ob- + celare「藏」。天体被挡住藏起来的，就是 occultation（掩星）。\",\"congregation\":\"congregate 来自拉丁语 congregare「聚成群」：con- + gregare「成群」（grex「兽群、人群」）。聚成群做礼拜的人，就是 congregation；与 gregarious（爱社交的）同根。\",\"consonance\":\"来自拉丁语 consonantia「音响和谐」，源头 consonare「一同发声」：con- + sonare「发声」。声音合到一起好听，就是 consonance；与 sound 的 son- 同族。\",\"tenebrous\":\"来自拉丁语 tenebrosus「黑暗的」，源头 tenebrae「黑暗」。阴森幽暗的，就是 tenebrous（老派文学词）。\",\"parsimony\":\"来自拉丁语 parsimonia「节俭」，源头 parcere「节省、宽恕」。省到抠的，就是 parsimony。\",\"offertory\":\"来自中世纪拉丁语 offertorium「奉献（环节）」，源头 offerre「献上」：ob- + ferre「携带」。弥撒里献礼的那一段，就是 offertory。\",\"mutineer\":\"mutiny 来自法语 mutin「叛乱的」，源头是拉丁语 movere「移动」一族（movere 的通俗拉丁后代 mouv-）——兵动起来反上，就是 mutiny；再加 -eer。深层关联如实标注为常见说法。\",\"valediction\":\"拉丁语拼合词：vale「再见」（valere「安康」的命令式）+ dictio「说」——说再见。告别辞，就是 valediction。\",\"inundation\":\"inundate 来自拉丁语 inundare「泛滥」：in- + unda「波浪」。水漫上来的，就是 inundation；与 abound 的 unda 同根。\",\"habitable\":\"habit（居住义）来自拉丁语 habitare「居住」，是 habere「拥有、保持」的反复形式；再加 -able。住得人的，就是 habitable；habitat 与它同根。\",\"indiscrete\":\"in-「未」+ discrete「分开的、独立的」：discrete 源头是拉丁语 discernere 的近亲 discernere/discretus「分开的」（dis- + cernere「筛分」）。没分开、成坨的，就是 indiscrete（数学义）。注意与 indiscreet「不谨慎」同音异源。\",\"degeneracy\":\"degenerate 来自拉丁语 degenerare「退化、败落」：de- + genus「种族、种类」。一代不如一代、离了本种的样子，就是 degeneracy。\",\"placket\":\"来源不完全确定：可能是 placard「贴片」或 plaque 一类法语词的变体，16 世纪指裙子的开衩与口袋。衣服的开襟，就是 placket。如实标注存疑。\",\"bracken\":\"词源存疑：中古英语作 braken，可能源自斯堪的纳维亚语，也可能与 brake「灌木丛」同族，没有定论。这种高大蕨类遍布荒原，来源却查不清，这里如实标注。\",\"demurrer\":\"来自盎格鲁-法语 demurrer「迟延」，源头是拉丁语 demorari「耽搁」：de- + morari「拖延」（mora「延误」）。法律上以「就算属实也不构成诉由」拖住对方的抗辩，就是 demurrer。\",\"accelerando\":\"直接借自意大利语 accelerando「加速着」，源头是拉丁语 accelerare：ad- + celer「快的」。乐谱上标它，就是让音乐像 accelerator 一样踩下油门。\",\"somatic\":\"来自希腊语 sōmatikos「身体的」，源头 sōma「身体」。关乎躯体的，就是 somatic（躯体的、心身的）。\",\"spatiality\":\"spatial 来自拉丁语 spatium「空间、距离」；再加 -ity。空间的性质，就是 spatiality。\",\"suavity\":\"suave 来自拉丁语 suavis「甜的、宜人的」，经法语进入英语；再加 -ity。圆滑得宜人的，就是 suavity；与 sweet 同族。\",\"verbiage\":\"借自法语 verbiage「废话连篇」，源头是拉丁语 verbum「词」。词多到成灾的，就是 verbiage。\",\"manorial\":\"manor 来自古法语 manoir「宅邸」，源头是拉丁语 manere「停留、居住」；再加 -al。领主宅邸与庄园的，就是 manorial；与 mansion（停留处）同根。\",\"provenance\":\"借自法语 provenance「来源」，源头 provenir「来自」，再往上是拉丁语 provenire：pro- + venire「来」。艺术品从哪「来」的履历，就是 provenance。\",\"nocturne\":\"借自法语 nocturne「夜的」，源头是拉丁语 nocturnus「夜间的」，其根 nox「夜」。为夜而作的曲子，就是 nocturne（夜曲）。\",\"capitulation\":\"来自中世纪拉丁语 capitulare「按条目拟定」，源头 capitulum「小标题、条款」（caput「头」的指小形式）。按一条条条款谈下来的投降，就是 capitulation；与 chapter（章节）同根。\",\"pluralism\":\"plural 来自拉丁语 pluralis「多于一的」，源头 plus「更多」；再加 -ism。多元共存的主张，就是 pluralism。\",\"permutation\":\"permute 来自拉丁语 permutare「彻底改变」：per- + mutare「改变」。元素换位的全套排法，就是 permutation（排列）。\",\"periphrasis\":\"来自希腊语 periphrasis「绕着说」：peri- + phrasis「说法」。绕圈子说话，就是 periphrasis（迂说法）。\",\"thane\":\"古英语 þegn「仆从、武士」，与德语 Degen 同族。盎格鲁-撒克逊的领主武士，就是 thane（莎士比亚《麦克白》用之）。\",\"feckless\":\"苏格兰词：feck 是 effect 的方言缩略（「效力、价值」），加上 -less「没有」。没效力、没出息的，就是 feckless。\",\"domineering\":\"domineer 借自荷兰语 domineren 或法语 dominer，源头是拉丁语 dominari「作主宰」，其根 dominus「主人」。一副主人压人的派头，就是 domineering。\",\"indisposed\":\"in-「不」+ disposed「乐意的、布置好的」：dispose 源头是拉丁语 disponere「摆放」（dis- + ponere「放」）。身子没「摆」舒服的，就是 indisposed（微恙、不乐意）。\",\"collegiate\":\"college 来自拉丁语 collegium「同僚团体」，源头 collega「同事」：col- + legare「选派」。被选到一起的人组成的，就是 college；其形容词是 collegiate。\",\"modular\":\"module 来自拉丁语 modulus「小尺度、模数」，是 modus「尺度」的指小形式；再加 -ar。按模数拼装的，就是 modular。\",\"evacuee\":\"evacuate 来自拉丁语 evacuare「抽空」：e- + vacuus「空的」；再加 -ee「被…的人」。被从空城里撤出来的人，就是 evacuee。\",\"sober\":\"来自拉丁语 sobrius「清醒的、不醉的」，其构词有一说为 se-「无」+ ebrius「醉的」。没醉、没浮夸的，就是 sober。深层构词如实标注为传统说法。\",\"underpin\":\"under + pin「钉住」构成的建筑词：从下面托住地基的，就是 underpin（支撑、佐证）。\",\"untoward\":\"un- + toward「顺着的（古义：顺从的、吉利的）」构成：不顺的、别扭的，就是 untoward。toward 的古义如实标注。\",\"gunlock\":\"gun + lock 构成：火枪上击发的那套机括，就是 gunlock。lock 本义「锁、扣件」。\",\"haven\":\"古英语 hæfen「港湾」，源自古诺斯语 höfn，与德语 Hafen 同源。船能躲风的港，就是 haven；避风港的比喻由此来。\",\"kiosk\":\"经法语 kiosque、土耳其语 köşk 而来，源头是波斯语 kūshk「宫殿、凉亭」。宫殿缩小成街边亭，就是 kiosk。\",\"glitch\":\"词源存疑：20 世纪航天与电子行话，一说源自意第绪语 glitsh「滑溜处」，再往上是德语 glitschen「滑」；没有定论。小故障，就是 glitch；这里如实标注。\",\"disaffection\":\"dis-「失去」+ affection（拉丁语 affectio「情感」）。情分没了，就是 disaffection（不满、离心）。\",\"presupposition\":\"pre- + supposition「假定」构成。suppose 来自拉丁语 supponere「放在下面」：sub- + ponere「放」。垫在下面的前提，就是 presupposition。\",\"skeletal\":\"skeleton 来自希腊语 skeleton「干尸」，源头 skeletos「干透的」（skellein「弄干」）。只剩干架子的，就是 skeletal。\",\"superable\":\"来自拉丁语 superabilis「可克服的」，源头 superare「越过」，其根 super「在上」。越得过去的，就是 superable（老派词）。\",\"disinclination\":\"dis-「不」+ inclination「倾向」：incline 源头是拉丁语 inclinare「倾斜」（clinare「弯」）。身子不往那边斜，就是 disinclination。\",\"guesswork\":\"guess + work 构成的复合词。guess 来源不完全确定，可能源自斯堪的纳维亚语（与 get 同族一说）。靠猜干的活，就是 guesswork。如实标注。\",\"emblazon\":\"em- + blazon「纹章」（源头古法语 blason，其深层来源不确定）构成。用纹章与金字把盾面装饰得耀眼，就是 emblazon。\",\"oversight\":\"over + sight「看」构成：看漏的那一下，就是 oversight（疏忽；另一义为监督，与 oversee 同源分岔，如实标注）。\",\"winsome\":\"古英语 wynsum「令人愉悦的」：wynn「喜悦」+ -sum。讨喜的笑，就是 winsome。wynn 是如尼字母 ƿ 的名字，如实标注。\",\"impersonality\":\"im-「非」+ personality「个性」：person 来自拉丁语 persona「面具、角色」。不带个人面具色彩的，就是 impersonality。\",\"disheveled\":\"来自古法语 deschevelé「头发散乱的」：des- + chevel「头发」（源头拉丁语 capillus「头发」，其根 caput「头」）。头发乱成一团的样子，就是 disheveled。\",\"regulatory\":\"regulate 来自拉丁语 regulare「按尺规正」，源头 regula「直尺、规则」，其根 regere「使直」。管束的，就是 regulatory。\",\"scaffolding\":\"scaffold + -ing：搭满楼外的架子，就是 scaffolding。\",\"populous\":\"来自拉丁语 populosus「人多的」，源头 populus。人挤人的，就是 populous。\",\"inanimate\":\"来自晚期拉丁语 inanimatus「无生命的」：in-「无」+ anima「气息、灵魂」。没气息的，就是 inanimate（无生命的）。\",\"pressurize\":\"pressure 来自拉丁语 pressura「压」，源头 premere「压」；再加 -ize。给舱里加压的，就是 pressurize。\",\"gradation\":\"grade 来自拉丁语 gradus「步、级」，源头 gradi「行走」；再加 -ation。一级一级的过渡，就是 gradation。\",\"scrunch\":\"crunch 的变体（受 squash 等词影响的首字母 s-）：拟声构词。嚼碎与揉团的声响，就是 scrunch。\",\"transparency\":\"transparent 来自中世纪拉丁语 transparens「透显的」：trans- + parere「显现」。看得透的，就是 transparency。\",\"antiquity\":\"来自拉丁语 antiquitas「古老」，源头 antiquus「旧的、在先的」，与 ante「在前」同族。时间上排在前面的远古，就是 antiquity。\",\"intolerable\":\"来自拉丁语 intolerabilis「忍受不了的」：in- + tolerare「背负、忍受」。背不动的，就是 intolerable。\",\"intricacy\":\"intricate 来自拉丁语 intricatus「缠乱的」，源头 intricare：in- + tricae「琐事、纠缠」。缠成死结的精细，就是 intricacy。\",\"opine\":\"来自拉丁语 opinari「认为、推测」，经古法语 opiner 进入英语。发表「我认为」的，就是 opine。\",\"crotchety\":\"crotchet 本指「小钩子」，引申为「怪念头」：经古法语 crochet「小钩」而来，源头是斯堪的纳维亚语 krok「钩」一说；再加 -y。脑子里挂着怪钩子、动不动发脾气的，就是 crotchety。深层来源如实标注。\",\"odometer\":\"按希腊语造的词：hodos「路」+ metron「测量」——量路的表。美国拼法 odometer 源头仍是 hodos，如实标注。\",\"adversity\":\"来自拉丁语 adversus「迎面相对的」：ad-「朝向」+ vertere「转」。命运转过脸来正对着你，就是逆境；与 adverse 同源。\",\"infiltration\":\"infiltrate 是 19 世纪按法语 infiltrer 造的词：in- + filter「过滤」（源头中世纪拉丁语 filtrum「毛毡滤器」）。像水渗过毛毡一样潜入，就是 infiltration。\",\"perverse\":\"来自拉丁语 perversus「被扭歪的」，源头 pervertere：per- + vertere「转」。故意转错方向的，就是 perverse（任性的、反常的）。\",\"theoretical\":\"theory 来自希腊语 theōria「观看、思索」：本是派人去「看」神谕的使团之行。只在看与想层面的，就是 theoretical。\",\"rejuvenate\":\"re- + juvenile「年轻的」拼造：juvenile 来自拉丁语 iuvenilis，其根 iuvenis「青年」。重新变年轻的，就是 rejuvenate。\",\"ejaculate\":\"来自拉丁语 eiaculari「猛掷出」：e-「出」+ iaculari「投掷」（iaculum「标枪」）。突然脱口而出的话、喷射，都是 ejaculate；与 inject（往里掷）同根。\",\"fetching\":\"fetch 是古英语 feccan「取来」，与 fetian 同源。能把目光「取」过来的，就是 fetching（迷人的）。\",\"sagacious\":\"来自拉丁语 sagax「嗅觉灵敏的、精明的」，源头 sagire「敏锐察觉」。鼻子灵、脑子更灵的，就是 sagacious（睿智的）。\",\"prohibitive\":\"prohibit 来自拉丁语 prohibere「挡在前面、不许」：pro- + habere「持有」。贵到「不许」人买的，就是 prohibitive。\",\"delicatessen\":\"借自德语 Delikatessen「精美食品」，源头是法语 délicatesse「精致」，再往上是拉丁语 delicatus「精美的」。卖精美熟食的店，就是 delicatessen，简称 deli。\",\"oblivious\":\"来自拉丁语 oblivio「遗忘」，源头 oblivisci「忘记」，其更深构词不确定。忘到没察觉的，就是 oblivious。深层来源如实标注存疑。\",\"flimsy\":\"词源存疑：17 世纪出现，可能由 film「薄膜」加 -sy 构成，指薄得像膜一样不结实。此说较流行但未成定论，如实标注。\",\"unisex\":\"uni-「一」（拉丁语 unus）+ sex「性别」在 20 世纪 60 年代拼出的词：男女共用一个样式的，就是 unisex。\",\"surveillance\":\"借自法语 surveillance「监视」，源头 surveiller「看守」：sur-「在上」+ veiller「守夜」（源头拉丁语 vigilare）。从上面盯着看的，就是 surveillance。\",\"polychrome\":\"poly-「多」（希腊语 polys）+ chrōma「颜色」拼合的 19 世纪词：多色的，就是 polychrome。\",\"tyrannical\":\"tyrant 来自希腊语 tyrannos「僭主、专制者」（其更深来源可能为前希腊语借词），经拉丁语、法语进入英语；再加 -ical。暴君式的，就是 tyrannical。深层来源如实标注。\",\"gorge\":\"（狼吞虎咽义与峡谷义同源）来自古法语 gorge「喉咙」，源头可能是通俗拉丁语 *gurga「漩涡、喉咙」，与拉丁语 gurges「深渊」同族。喉咙是窄口：峡谷是山的喉咙，狼吞是往喉咙里塞。\",\"surreal\":\"sur-「超」（法语 sur「在上」，源头拉丁语 super）+ real「真实的」由布勒东（André Breton）等人在 1920 年代造出（法语 surréalisme）。比真实还真的，就是 surreal。\",\"partition\":\"来自拉丁语 partitio「划分」，源头 partire「分」，其根 pars「部分」。分开的墙与瓜分，都是 partition。\",\"cavort\":\"词源不完全确定：多认为是 curvet「（马）腾跃」的美国变体，curvet 源自意大利语 corvetta「小跳跃」（corvo「弯曲」一说）。蹦蹦跳跳地闹，就是 cavort。如实标注：此说较流行但未成定论。\",\"minstrel\":\"来自古法语 menestrel「艺人、仆从」，源头是晚期拉丁语 ministerialis「宫廷仆役」，其根 minister「仆人」。在宫廷伺候兼卖艺的人，就是 minstrel（吟游诗人）。\",\"parasitic\":\"parasite 来自希腊语 parasitos「同桌吃饭的人」：para-「在旁」+ sitos「食物」——本是食客，后指寄生者。靠宿主吃饭的，就是 parasitic。\",\"objectionable\":\"objection + -able：招人顶回去的，就是 objectionable（令人反感的）。\",\"venturesome\":\"venture + -some「有…倾向的」：爱押运气的，就是 venturesome。\",\"blockade\":\"block（经古法语 bloc 而来，源头是中古荷兰语 blok「木块、木墩」）+ -ade「行为」（法语式后缀）。用木墩般的工事把港口堵死，就是 blockade。\",\"machete\":\"借自西班牙语 machete，是 macho「锤、壮汉」的指小形式，其更深来源有一说与拉丁语 marculus「小锤」有关。砍甘蔗的大刀，就是 machete。深层来源如实标注为一说。\",\"stupendous\":\"来自拉丁语 stupendus「令人惊叹的」，源头 stupere「发愣」。大到让人发呆的，就是 stupendous。\",\"gauge\":\"来自古法语 jauge「量杆、标准量器」，其更深来源不确定，可能与拉丁语 gallica 一类词有关。量厚度与雨量的器具，就是 gauge。深层来源如实标注存疑。\",\"reverence\":\"来自拉丁语 reverentia「敬畏」，源头 revereri：re- + vereri「惧怕、敬畏」。敬里带畏的，就是 reverence。\",\"disputable\":\"dispute 来自拉丁语 disputare「推算、争论」：dis- + putare「思考、估量」。算不清、可争的，就是 disputable；与 compute（一起算）同根。\",\"guidance\":\"guide 来自古法语 guider，源头是日耳曼语 *wītan「看、引路」，与 wise、witness 同族。带着看路的，就是 guidance。\",\"sinus\":\"直接借自拉丁语 sinus「弯曲、凹处、口袋」：衣褶的兜，引申为鼻窦与窦性组织。弯进去的腔，就是 sinus。\",\"ruckus\":\"词源存疑：19 世纪美国词，可能是 ruction「骚乱」与 rumpus「喧闹」的混成，没有定论。闹哄哄的，就是 ruckus；这里不硬编。\",\"brash\":\"词源存疑：18 世纪末在美国英语中出现，先指「碎屑、断枝」，后转指莽撞冒失；确切来源未有定论，这里不硬编。\",\"mannerism\":\"manner + -ism：个人标志性的小动作与风格，就是 mannerism；艺术史上的「矫饰主义」也是它。\",\"hectic\":\"来自希腊语 hektikos「习惯性的（发热）」，源头 hexis「状态」，经拉丁语、法语进入英语：本指肺结核的潮热。忙到发热般团团转的，就是 hectic。\",\"torturous\":\"torture 来自拉丁语 tortura「扭、绞」，源头 torquere「扭」。绞着疼的，就是 torturous；注意与 tortuous（弯曲的）同根但分工不同。\",\"sullen\":\"来自古法语 solain「孤独的」，源头是拉丁语 solus「单独的」一系：孤僻转阴沉。闷闷不乐的，就是 sullen。\",\"zilch\":\"词源存疑：20 世纪美国俚语「零」，可能源自一个虚构人物 Joe Zilch 的名字，没有定论。这里不硬编。\",\"cumulative\":\"来自拉丁语 cumulare「堆积」，源头 cumulus「堆」。一层压一层往上堆的，就是 cumulative；与 accumulation 同根。\",\"feline\":\"来自拉丁语 felinus「猫的」，源头 feles「猫」。猫科的优雅与神秘，就是 feline。\",\"strenuous\":\"来自拉丁语 strenuus「活跃的、用力的」，其更深来源不确定。用足劲的，就是 strenuous。深层来源如实标注存疑。\",\"helm\":\"古英语 helma「舵柄、船舵」，与德语 Helm 同族。掌舵的位置，就是 helm；at the helm 是掌权。\",\"heartily\":\"hearty（heart + -y「满心的」）+ -ly。满心满意地，就是 heartily。\",\"suggestible\":\"suggest 来自拉丁语 suggestus「被提示的」，源头 suggerere：sub- + gerere「携带」——从下面递上来的想法；再加 -ible。容易被递进想法的，就是 suggestible。\",\"forge\":\"（动词，锻造）来自古法语 forgier，源头是拉丁语 fabricare「制造」（fabrica「工场」）。铁匠炉前打出来的，就是 forge；伪造义是「造」义的阴暗面。注意 forge ahead 的 forge 是另一词。\",\"sentry\":\"来源不完全确定：可能是 sentinel 的缩略。sentinel 经法语 sentinelle 而来，源头是意大利语 sentinella，其根与拉丁语 sentire「感觉、察觉」有关一说。站岗察觉的人，就是 sentry。如实标注。\",\"affix\":\"来自拉丁语 affigere「钉上、系上」：ad- + figere「固定」。词缀就是「钉」在词根前后的小钉子，前缀后缀都叫 affix。\",\"inhibition\":\"inhibit 来自拉丁语 inhibere「拦住」：in- + habere「持有、把持」。心里那只拦着的手，就是 inhibition。\",\"hearty\":\"heart + -y 构成的中古英语词：出自真心的、量大的，都是 hearty。\",\"combustibility\":\"combust 是拉丁语 combustus「烧尽的」，源头 comburere：com-「彻底」+ urere「烧」。烧得起来的性质，就是 combustibility。\",\"intercept\":\"来自拉丁语 interceptus「中途截住的」，源头 intercipere：inter-「中间」+ capere「抓」。半道抓下来的，就是 intercept。\",\"palpitate\":\"来自拉丁语 palpitare「急跳」，是 palpare「轻触」的反复形式。心怦怦乱跳的，就是 palpitate；与 palpable（摸得着的）同根。\",\"regionalism\":\"region 来自拉丁语 regio「区域、界线」，源头 regere「划界、统治」；再加 -ism。地方味与地方本位，就是 regionalism。\",\"cabana\":\"借自西班牙语 cabaña「小屋」，源头是晚期拉丁语 capanna「棚屋」，与 cabin 同源。海滩边的更衣小屋，就是 cabana。\",\"medicate\":\"来自拉丁语 medicare「医治」，源头 medicus「医生」，其根 mederi「治疗」。下药治的，就是 medicate；与 meditate 同出一根（med-「度量、照料」）的说法常见，如实标注。\",\"exhaustibility\":\"exhaust 来自拉丁语 exhaustus「被抽干的」，源头 exhaurire：ex- + haurire「汲水」。井水能被抽干的性质，就是 exhaustibility。\",\"henpeck\":\"hen「母鸡」+ peck「啄」构成的 17 世纪词：像母鸡啄食一样没完没了地数落丈夫，就是 henpeck。\",\"dilapidation\":\"dilapidate 来自拉丁语 dilapidare「拆散石头、挥霍」：di- + lapidare「投石」（lapis「石头」）。房子像被拆了石头一样破败，就是 dilapidation。\",\"pollutant\":\"pollute 来自拉丁语 pollutus「被弄脏的」，源头 polluere，其更深构词不确定；再加 -ant。弄脏环境的东西，就是 pollutant。深层来源如实标注存疑。\",\"toxicology\":\"toxico-「毒」+ -logy「学问」拼合的 19 世纪学科词。研究毒的，就是 toxicology。\",\"detachment\":\"detach 经法语 détacher 而来：dés-「解开」+ attacher「系上」（源头可能是日耳曼语 stake「桩」一说）。把系着的解开派出去，就是 detachment（分遣队、超然）。深层来源如实标注。\",\"dispossession\":\"dispossess 是盎格鲁-法语词：dis-「剥夺」+ possess「占有」（源头拉丁语 possidere「坐拥」：potis「能」+ sedere「坐」）。把人从「坐着的地盘」上赶走，就是 dispossession。\",\"sufficiency\":\"sufficient 来自拉丁语 sufficiens「够用的」，源头 sufficere：sub- + facere「做」——在下面托够。够用的程度，就是 sufficiency。\",\"personage\":\"person + -age（仿法语 personnage）构成：戏里的人物与现实里的大人物，都是 personage。\",\"clientele\":\"借自法语 clientèle，源头是拉丁语 clientela「受保护人（群体）」，其根 cliens「依附者、门客」。罗马贵族门下那一群人，现在成了商店的 clientele。\",\"nominee\":\"nominate + -ee「被…的人」：名字被报上去的人，就是 nominee。\",\"colic\":\"来自晚期拉丁语 colicus「结肠的」，源头是希腊语 kolikos，其根 kolon「结肠」。肠子绞痛，就是 colic；婴儿肠绞痛也用它。\",\"nutriment\":\"来自拉丁语 nutrimentum「养分」，源头 nutrire「喂养」。喂养身体的，就是 nutriment。\",\"confounded\":\"confound 来自古法语 confondre，源头是拉丁语 confundere「混到一起、弄糊涂」：con- + fundere「倒」。把一切倒成一锅粥，就是 confounded；与 found（铸造，倒金属液）同根。\",\"hardy\":\"来自古法语 hardi「大胆的、耐劳的」，源头是日耳曼语 *hard「硬」。硬朗经得住折腾的，就是 hardy。\",\"immediacy\":\"immediate 来自晚期拉丁语 immediatus「无中介的」：in-「无」+ mediatus「居中的」（medius「中间」）。中间不隔东西的，就是 immediacy（即时、直接）。\",\"supremacy\":\"supreme 来自拉丁语 supremus「最高的」，是 superus 的最高级；再加 -cy。最高的状态，就是 supremacy。\",\"reproof\":\"reprove 来自古法语 reprover，源头是拉丁语 reprobare「驳回、责备」：re- + probare「检验」。验出毛病说出口的，就是 reproof（责备）。\",\"salve\":\"古英语 sealf「油膏」，与德语 Salbe 同源。抹伤口的膏与安慰的话，都是 salve。\",\"sectional\":\"section 来自拉丁语 sectio「切分」，源头 secare「切」；再加 -al。切成段的、地方性的，就是 sectional。\",\"artful\":\"art（拉丁语 ars「技艺、技巧」）+ -ful「充满」。手里全是技巧，就是巧妙的；artful 也可指狡黠——技巧用过了头。\",\"jangle\":\"中古英语 janglen「喋喋争吵」，来自古法语 jangler「饶舌」，带拟声色彩。金属乱响与人心烦躁，都是 jangle。\",\"heartsore\":\"heart + sore「疼痛的」构成的古雅复合词。心口疼的，就是 heartsore。\",\"persecution\":\"persecute 来自拉丁语 persecutus「被追逼的」，源头 persequi：per- + sequi「跟随」——追着不放。追打式的迫害，就是 persecution。\",\"overture\":\"来自古法语 overture「开启」，源头是拉丁语 apertura「打开」，其根 aperire「开」。乐曲的开场与交涉的开场白，都是 overture。\",\"reconstituted\":\"re-「重新」+ constituted「构成的」拼合。constitute 源头是拉丁语 constituere「设立」（con- + statuere「竖立」）。冲水还原的，就是 reconstituted。\",\"presentment\":\"present + -ment：呈上的东西，法律上指大陪审团的呈报，就是 presentment。\",\"prevalence\":\"prevail 来自拉丁语 praevalere「力量占上风」：prae- + valere「有力」。占上风到遍地的，就是 prevalence（流行程度）。\",\"cavernous\":\"cavern 来自拉丁语 caverna「洞穴」，源头 cavus「空的」。深得像洞穴的，就是 cavernous；cave 与它同源。\",\"tumefy\":\"来自拉丁语 tumefacere「使肿」：tumere「肿」+ facere「做」。肿起来的，就是 tumefy。\",\"coronation\":\"coronate 源头是拉丁语 coronare「戴冠」，词干 corona「花冠、王冠」。把王冠戴到头上的仪式，就是 coronation；与 crown 同源。\",\"perishable\":\"perish 来自拉丁语 perire「消亡、烂掉」：per- + ire「去」；再加 -able。放着会烂的，就是 perishable。\",\"claptrap\":\"clap + trap 构成的 18 世纪舞台词：专为博取掌声（clap）设的「套路」（trap）。华而不实的噱头，就是 claptrap。\",\"negligible\":\"negligence 同 neglegere 一系：小到不值得「拾」的，就是 negligible。\",\"honorary\":\"honor + -ary「…的」：名誉性质的（学位、会员），就是 honorary。\",\"inflection\":\"inflect 来自拉丁语 inflectere「弯曲」：in- + flectere「弯」。声调与词尾的弯折，就是 inflection；与 flexible 同根。\",\"decrepit\":\"来自拉丁语 decrepitus「年迈衰朽的」：de- + crepare「作响、爆裂」一说——老得骨头咯吱响。此构词说为常见解释，如实标注。\",\"comradeship\":\"comrade 经西班牙语 camarada「同室战友」而来，源头是拉丁语 camera「房间」；再加 -ship「关系」。同住一个营房的情分，就是 comradeship。\",\"offender\":\"offend 来自拉丁语 offendere「撞上、冒犯」：ob- + fendere「击打」。撞了规矩的人，就是 offender。\",\"bylaw\":\"by-「地方的」（源自古诺斯语 býr「村镇」，与 borough 同族）+ law 构成：城镇自己定的规矩，就是地方法规、章程。\",\"maxim\":\"来自拉丁语 maxima「最大的（命题）」，是 maxima propositio 的省称，源头 maximus「最大的」。最大的道理压成一句，就是 maxim（格言）。\",\"figurative\":\"同 figure：不按字面、按「捏出的像」来理解的，就是 figurative（比喻的）。\",\"bedaub\":\"be-「遍、满」+ daub「涂抹」。daub 来自古法语 dauber「涂灰泥」，源头是拉丁语 dealbare「刷白」（albus「白」）。满墙乱涂，就是 bedaub。\",\"levitate\":\"由 levity 回构：levity 来自拉丁语 levitas「轻」，源头 levis「轻的」。轻得飘起来的，就是 levitate。\",\"inclination\":\"incline 来自拉丁语 inclinare「倾斜」：in- + clinare「弯、斜」。身子往哪边斜，心就往哪边偏，就是 inclination。\",\"grueling\":\"gruel 本义「稀粥」，俚语 get one's gruel 指「挨收拾」；grueling 由此而来——累得像被罚的苦役。此俚语来源为常见说法，如实标注。\",\"arcanum\":\"来自拉丁语 arcanus「秘密的、封起的」，源头 arca「箱子、柜」。锁在箱子里不给人看的，就是秘方、奥秘；ark（方舟）与它同源，都是「能装东西的箱子」。\",\"eviction\":\"evict 来自拉丁语 evictus「被依法夺回的」，源头 evincere「彻底战胜」：e- + vincere「征服」。官司打赢把房收回、把人请走，就是 eviction；与 victory 的 vinc- 同根。\",\"superiority\":\"superior 是拉丁语 superior「更高的」，是 superus「在上的」比较级；再加 -ity。高一截的状态，就是 superiority。\",\"gulp\":\"拟声构词：模仿吞咽时喉咙的咕咚声，中古英语 gulpen。大口一吞，就是 gulp。\",\"demobilize\":\"de-「解除」+ mobilize「动员」：mobile 源头是拉丁语 mobilis「可移动的」（movere「移动」）。让军队从「可调动」状态退下来，就是 demobilize（复员）。\",\"redouble\":\"re- + double「加倍」构成（经法语 redoubler）：double 源头是拉丁语 duplus「两倍的」。劲再翻一番的，就是 redouble。\",\"slavish\":\"slave 经古法语、拉丁语 sclavus 而来，本义「斯拉夫人」；再加 -ish。奴才相的，就是 slavish。\",\"dimensional\":\"dimension 来自拉丁语 dimensio「量度」，源头 dimetiri「量尽」：di- + metiri「测量」。量出来的长宽高，就是 dimension；与 meter 同根。\",\"optical\":\"optic 来自希腊语 optikos「视觉的」，源头 opsis「看、视力」，经拉丁语进入英语；再加 -al。关乎看的，就是 optical。\",\"perceptibility\":\"perceive 来自拉丁语 percipere「彻底抓住、察觉」：per- + capere「取」；再加 -ibility。察觉得出的，就是 perceptibility。\",\"foolhardy\":\"来自古法语 folhardi「傻大胆」：fol「傻的」+ hardi「大胆的」（源头日耳曼语 hard「硬」）。傻与胆拼出的鲁莽，就是 foolhardy。\",\"underutilize\":\"under- + utilize「利用」构成。utilize 经法语 utiliser 而来，源头是拉丁语 utilis「有用的」。没用够的，就是 underutilize。\",\"nationalist\":\"nation 来自拉丁语 natio「出生、民族」，源头 nasci「出生」；再加 -ist。以本民族为念的人，就是 nationalist；与 native（天生的）同根。\",\"dredge\":\"来源不完全确定：可能与中古英语 dragge「拖网」或苏格兰语 dreg「拖」有关。把河底泥沙拖上来的，就是 dredge。如实标注存疑。\",\"conniption\":\"词源存疑：19 世纪美国俚语，可能由 corruption、captious 一类词戏谑改造而成，没有定论。气到发疯的大发作，就是 conniption fit；这里如实标注存疑。\",\"commandment\":\"command + -ment「结果」：吩咐下来的成文条目，就是 commandment；十诫是 Ten Commandments。\",\"impermanence\":\"im-「不」+ permanence「恒常」：permanent 源头是拉丁语 permanere「持续到底」：per- + manere「停留」。留不住的，就是 impermanence（无常）。\",\"unveil\":\"un-「揭」+ veil「面纱」构成。veil 来自拉丁语 velum「布、纱」。掀纱亮相的，就是 unveil。\",\"temporize\":\"经法语 temporiser 而来，源头是中世纪拉丁语 temporizare「拖延」：tempus「时间」。拖时间看风向的，就是 temporize。\",\"downy\":\"down「绒毛」源自古诺斯语 dūnn「羽绒」；-y 表性质。软得像绒毛的，就是 downy。\",\"ghoul\":\"借自阿拉伯语 ghūl「食尸鬼」，源头 ghāla「抓取」。阿拉伯传说里在墓地抓尸体吃的妖怪，就是 ghoul。\",\"polytheism\":\"poly-「多」+ theism「有神论」（源头希腊语 theos「神」）拼合的 17 世纪词。拜许多神的，就是 polytheism。\",\"disqualify\":\"dis-「取消」+ qualify「使合格」：qualify 源头是拉丁语 qualis「怎样的」+ facere「做」。把资格拿掉，就是 disqualify。\",\"contemplative\":\"contemplate 来自拉丁语 contemplari「凝视、沉思」，源头 templum「（观鸟占卜的）神圣区域」。在神域里静静看，就是 contemplative；与 temple（神庙）同根。\",\"citizenry\":\"citizen 经盎格鲁-法语 citezein 而来，源头是拉丁语 civis「公民」、civitas「城市共同体」；-ry 表群体。全体市民，就是 citizenry。\",\"navigable\":\"navigate 来自拉丁语 navigare「航行」：navis「船」+ agere「驱动」；再加 -able。船开得过去的，就是 navigable。\",\"commissioner\":\"commission 来自拉丁语 commissio「托付」，源头 committere：com- + mittere「送、派」。被派去托付专责的人，就是 commissioner。\",\"nutshell\":\"nut + shell 构成的中古英语复合词：小得能装进坚果壳的，就是 in a nutshell（简而言之）。\",\"bootleg\":\"boot「靴子」+ leg「腿」构成的美国词：禁酒时期私酒贩把扁酒瓶塞进靴筒里偷带，bootleg 由此得名，后泛指一切非法盗版。\",\"manipulate\":\"由 manipulation 回构：manipulation 源头是拉丁语 manipulus「一把、（军团的）小队」：manus「手」+ plere「满」——手抓满的一把。用手摆布人，就是 manipulate。\",\"forlorn\":\"古英语 forloren「彻底失去的」，是 forlēosan「失去」的过去分词（与 lose 同根）。被丢下、没了指望的，就是 forlorn。\",\"tribunal\":\"来自拉丁语 tribunal「审判台」，源头 tribunus「护民官」。官坐的台，就是 tribunal（法庭）。\",\"smarmy\":\"smarm 来源不完全确定：方言词 smalm「抹、谄媚」一系，可能与 smear 有关。油腻谄媚的，就是 smarmy。如实标注存疑。\",\"deviltry\":\"devil 是古英语 dēofol，源头是希腊语 diabolos「诽谤者」：dia- + ballein「投掷」——把话「扔」到中间挑拨的人。再加 -try「行径」。恶作剧与巫术，都是 deviltry。\",\"predation\":\"predator 来自拉丁语 praedator「掠夺者」，源头 praedari「抢掠」，其根 praeda「猎物、赃物」。吃与被吃的关系，就是 predation。\",\"blather\":\"来自古诺斯语 blaþra「喋喋不休、胡说」，带拟声色彩。北欧人带来的词，专管没完没了的废话；bladder（膀胱）与它同根，都是「鼓起来的东西」。\",\"lunate\":\"来自拉丁语 lunatus「月牙形的」，源头 luna「月亮」。弯成月牙的，就是 lunate。\",\"sage\":\"（智者义与鼠尾草义同形异源）智者 sage 来自拉丁语 sapius 一系（sapere「有智慧」），经古法语进入英语；草药 sage 来自拉丁语 salvia「治愈草」。两义如实标注分开。\",\"somersault\":\"经法语、普罗旺斯语 sobresaut 而来，源头是拉丁语 supra「在上」+ saltus「跳」——从上面翻过去的一跳。跟头，就是 somersault。\",\"dramatics\":\"drama 来自希腊语 drama「演出、行动」，源头 dran「做、行动」，经拉丁语进入英语。做出来的夸张举动，就是 dramatics。\",\"damnation\":\"damn 来自拉丁语 damnare「判罪、定罪」，源头 damnum「损失、罚金」，经古法语 damner 进入英语。被判下地狱，就是 damnation。\",\"opportune\":\"来自拉丁语 opportunus「合时宜的」，本义「（风）吹向港口的」：ob- + portus「港口」一说构词——顺风进港的时机。来得正好的，就是 opportune。深层构词如实标注为传统说法。\",\"hatchery\":\"hatch「孵化」来源不完全确定：中古英语 hacchen，可能与中古低地德语 hecken「繁殖」同族；再加 -ery「场所」。孵鱼孵鸡的场，就是 hatchery。如实标注。\",\"robust\":\"来自拉丁语 robustus「橡木般结实的」，源头 robur「橡木、硬木」。壮得像橡木的，就是 robust。\",\"stereotyped\":\"stereotype 本是印刷术语「铅版」：希腊语 stereos「坚固的」+ typos「印记」。翻来覆去印的，就是 stereotyped（刻板化的）。\",\"buccaneer\":\"来自法语 boucanier「在烤架上熏肉的人」，boucan 是加勒比图皮语 mukém「烤肉架」经法语转入。17 世纪在架上烤肉的猎人后来下海为盗，就成了 buccaneer。\",\"marriageability\":\"marriage 来自古法语 mariage，源头 marier「嫁娶」，再往上是拉丁语 maritare「成婚」（maritus「丈夫」）；再加 -ability。适婚的程度，就是 marriageability。\",\"equalizer\":\"equalize（equal 源头拉丁语 aequalis「相等的」）+ -er。把比分拉平的那一球，就是 equalizer（扳平球）。\",\"pessimism\":\"pessimist 按拉丁语 pessimus「最坏的」造：凡事往最坏处想，就是 pessimism；与 optimum（最好的）相对。\",\"drudgery\":\"drudge 中古英语 druggen「干苦活」，来源不确定，可能与 drag「拖」同族。拖着身子干的苦活，就是 drudgery。如实标注。\",\"duality\":\"dual 来自拉丁语 dualis「二的」，源头 duo「二」；再加 -ity。一体两面的性质，就是 duality。\",\"imperfect\":\"im-「不」+ perfect「完美的」：perfect 来自拉丁语 perfectus「做成的」，源头 perficere：per-「彻底」+ facere「做」。没彻底做好的，就是 imperfect。\",\"demoniacal\":\"demon 来自希腊语 daimōn「神灵、精灵」，经拉丁语、古法语进入英语，本无贬义，基督教语境里才变成恶魔；再加 -iacal。像恶魔附体的，就是 demoniacal。\",\"derivation\":\"derive 来自拉丁语 derivare「引水、引申」：de- + rivus「小溪」。把词义像水一样从源头引出来，就是 derivation；river 与 rivus 同族。\",\"spinster\":\"spin「纺织」+ -ster（本为女性从业者后缀）：纺线女工，后成法律词指未婚女子——词义史如实标注，今含贬义色彩，使用需谨慎。\",\"roughhouse\":\"rough + house 构成的美国口语词：在屋里闹翻天的，就是 roughhouse（打闹）。\",\"promenade\":\"借自法语 promenade「散步（处）」，源头 promener「带出去走」，再往上是拉丁语 prominare「向前驱赶」：pro- + minare「赶」。散步的大道，就是 promenade。深层关联如实标注为常见说法。\",\"triathlon\":\"tri-「三」+ athlon「竞赛」（希腊语 athlos）按 pentathlon 类推在 20 世纪造出。三项全能，就是 triathlon。\",\"unbeknownst\":\"un- + be- + known「已知的」加方言后缀 -st 构成的 19 世纪词。在人不知道的情况下，就是 unbeknownst。\",\"accumulation\":\"来自拉丁语 accumulare「堆起来」：ad- + cumulus「土堆、堆」。一层层往堆上加，就是积累；cumulus 也是「积云」的名字。\",\"inebriate\":\"来自拉丁语 inebriare「灌醉」：in- + ebrius「醉的」。酒把人灌透的，就是 inebriate。\",\"scoundrelly\":\"scoundrel 词源存疑：16 世纪词，可能源自盎格鲁-法语 escoundre「躲藏」一系，没有定论。无赖的，就是 scoundrelly；这里不硬编。\",\"foreshadow\":\"fore- + shadow「影子」构成的 16 世纪词：事情还没到，影子先投过来的，就是 foreshadow。\",\"conjuror\":\"conjure 来自古法语 conjurer，源头是拉丁语 coniurare「共同发誓、密谋」：con- + iurare「发誓」。念着誓言般咒语变戏法的人，就是 conjuror；与 jury（发誓判定）的 jur- 同根。\",\"raucous\":\"来自拉丁语 raucus「嘶哑的」。嗓子喊劈了的粗哑与喧闹，就是 raucous。\",\"educative\":\"educate 来自拉丁语 educare「养育、培养」，与 educere「引出」同族（e- + ducere「带领」）。能把人「带」出来的，就是 educative。\",\"immobilize\":\"im-「不」+ mobilize「使动员、移动」：mobile 源头是拉丁语 mobilis「可移动的」（movere「移动」）。让它动不了的，就是 immobilize。\",\"puncture\":\"来自晚期拉丁语 punctura「刺孔」，源头 pungere「刺」。刺出的洞，就是 puncture。\",\"gentleman\":\"gentle（源头拉丁语 gentilis「同族的、出身好的」，其根 gens「氏族」）+ man 构成的中古英语复合词。出身好、举止文雅的男子，就是 gentleman。\",\"beltway\":\"belt「带子」+ way「路」构成的美国英语复合词，20 世纪指环绕城市的环线公路。像腰带一样绕城一圈，就是 beltway。\",\"lieutenant\":\"借自法语 lieutenant「副职、代理」：lieu「位置」（源头拉丁语 locus）+ tenant「占据者」。替长官占着位置的人，就是 lieutenant（中尉）。\",\"regality\":\"regal 来自拉丁语 regalis「王的」，源头 rex「国王」（regis）；再加 -ity。王者的气派，就是 regality。\",\"forthright\":\"forth「直前」+ right「直」构成的古英语复合词：说话直着往前的，就是 forthright。\",\"harrowing\":\"harrow 本是农具「耙」：古英语 *hearwa。harrowing 先指耙地般的折磨，名句 the Harrowing of Hell 指基督下地狱救灵魂。心像被耙过的，就是 harrowing。\",\"transect\":\"trans-「横过」+ -sect「切」（拉丁语 secare「切」）拼造的科技术语。横切一条线的，就是 transect（样带）。\",\"impressible\":\"impress 来自拉丁语 impressus「压入的」，源头 imprimere：in- + premere「压」；再加 -ible。心上容易被压出印的，就是 impressible（易感的）。\",\"bejewel\":\"be-「缀满」+ jewel。jewel 经古法语 jouel 而来，源头多认为是通俗拉丁语 *jocale「小玩物」，其根是拉丁语 iocus「玩笑、游戏」。把「玩物」缀满全身，就是 bejewel。\",\"liberate\":\"来自拉丁语 liberare「释放」，源头 liber「自由的」。把人放自由的，就是 liberate。\",\"dirk\":\"苏格兰匕首名，来源不确定：一说与人名 Dirk（德语 Dietrich 的昵称）有关，17 世纪出现。如实标注存疑：短剑 dirk 的得名没有定论。\",\"disrobe\":\"dis-「脱去」+ robe「长袍」构成。robe 经古法语而来，源头是日耳曼语 *rauba「掠来的衣物」一说。宽衣解带的，就是 disrobe。深层来源如实标注。\",\"demeanor\":\"demean（举止义）来自古法语 demener「引导、表现」：de- + mener「带领」（源头拉丁语 minare「驱赶」）。一个人把自己「带」出来的样子，就是 demeanor。\",\"valiancy\":\"valiant 来自古法语 vaillant「勇敢的」，是 valoir「有价值」的分词形式，源头拉丁语 valere「有力、值」。有力有价的勇，就是 valiancy。\",\"incorruptible\":\"in-「不」+ corruptible「可败坏的」：corrupt 源头是拉丁语 corrumpere「彻底打破」（com- + rumpere「打破」）。打不烂、买不动的，就是 incorruptible。\",\"scathing\":\"scathe + -ing：话如灼伤般狠的，就是 scathing。\",\"coltish\":\"colt 是古英语 colt「小马驹」，其更深来源不确定；-ish「…似的」。像没驯的小马一样蹦跶，就是 coltish。如实标注存疑（深层）。\",\"nicker\":\"（马嘶义）拟声构词，模仿马的短嘶；注意 nicker 另有英镑俚语义，来源不同。马轻轻嘶的，就是 nicker。\",\"psychopath\":\"psychopathy 的回构词：psychopathy 是按希腊语造的：psychē「心灵」+ patheia「感受、疾苦」（pathos）。心智有疾、冷酷无情的人，就是 psychopath。\",\"etcetera\":\"直接借自拉丁语短语 et cetera「以及其余的」：et「和」+ cetera「其余的」。清单列不完时，就用 etcetera 收尾，缩写 etc.。\",\"deportee\":\"deport + -ee「被…的人」：被驱逐出境者，就是 deportee。\",\"jounce\":\"中古英语 jouncen「颠簸」，可能是 jolt 与 bounce 一类词的混合或拟声构词。一路颠着走的，就是 jounce。如实标注。\",\"sheathe\":\"sheath 是古英语 scēaþ「鞘」，与德语 Scheide 同源；再加动词后缀。把剑收回鞘的，就是 sheathe。\",\"opposable\":\"oppose 来自拉丁语 opponere「放在对面」：ob- + ponere「放」；再加 -able。能转到对面与四指相对的拇指，就是 opposable thumb。\",\"onslaught\":\"借自荷兰语 aanslag「攻击」，源头 aan「上」+ slag「打击」，可能受 on + slaughter 影响改拼。猛扑过来的攻势，就是 onslaught。\",\"extravaganza\":\"借自意大利语 stravaganza「 extravagance、奇举」，源头是拉丁语 extravagari「漫游出界」：extra-「在外」+ vagari「游荡」。出格出到华丽的大制作，就是 extravaganza；与 vague（游荡不定的→模糊的）同根。\",\"oceanaut\":\"ocean（源头希腊语 ōkeanos「大海」）+ -naut「航行者」（希腊语 nautēs）拼合的 20 世纪词：深海里的宇航员，就是 oceanaut。\",\"waif\":\"来自盎格鲁-法语 waif「无主之物」，其更深来源有一说与古诺斯语 veif「飘摇之物」有关。无人认领的孩子与动物，就是 waif。深层来源如实标注存疑。\",\"trajectory\":\"来自中世纪拉丁语 trajectoria「抛出的路径」，源头 traicere：trans-「横过」+ iacere「投掷」。掷出去的弧线，就是 trajectory。\",\"behemoth\":\"来自希伯来语 bəhēmōth，是 bəhēmāh「牲畜、野兽」的强调复数形式，《约伯记》里指力大无穷的巨兽。词义后来泛指一切庞然大物。\",\"liable\":\"来自古法语 lier「捆绑」的派生构词：lier 源头是拉丁语 ligare「绑」。被责任「绑」住的，就是 liable。\",\"fanciful\":\"fancy 是 fantasy 的缩略变体：fantasy 来自希腊语 phantasia「想象、幻象」，源头 phantazein「使显现」（phainein「显示」）。满脑子幻象的，就是 fanciful；与 phenomenon（显现之物）同根。\",\"prostrate\":\"来自拉丁语 prostratus「被放倒的」，源头 prosternere：pro- + sternere「铺、放倒」。整个人铺在地上的，就是 prostrate（俯伏的、精疲力竭的）。\",\"humanize\":\"human + -ize「使…化」构成：使有人的温度的，就是 humanize。\",\"pennant\":\"pennon 的变体：pennon 来自古法语 pennon「小旗」，源头是拉丁语 penna「羽毛、鳍」——旗形如羽。长三角旗，就是 pennant。\",\"drawl\":\"来源不完全确定：可能源自低地德语或弗里斯兰语 dralen「拖延、磨蹭」一说。把尾音拖得老长地说话，就是 drawl。如实标注。\",\"repayable\":\"repay 来自古法语 repaier「偿还」：re- + paier「付」（源头拉丁语 pacare「使满意」，其根 pax「和平」——付清即和平）；再加 -able。还得起的，就是 repayable。\",\"precognition\":\"pre-「预先」+ cognition「认知」（源头拉丁语 cognoscere「得知」）拼合的 19 世纪词。事先就「知道」的，就是 precognition（预知）。\",\"residency\":\"reside 来自拉丁语 residere「坐下定居」：re- + sedere「坐」；再加 -cy。坐下来住的状态，就是 residency（住院医师期、居留）。\",\"infantry\":\"经法语 infanterie、意大利语 infanteria 而来，源头是 infante「青年、步兵」，其根是拉丁语 infans「婴儿、不会说话的」：in- + fans「说着的」（fari「说」）。不会骑马的年轻兵，就是步兵的由来。\",\"reminisce\":\"由 reminiscence 回构：reminiscence 来自拉丁语 reminiscentia「回忆」，源头 reminisci「记起」：re- + mens「心智」一系。翻旧账式地怀旧，就是 reminisce。\",\"cilia\":\"直接借自拉丁语 cilia，是 cilium「眼睑、睫毛」的复数。细胞表面那些小睫毛状的毛，就是 cilia。\",\"equable\":\"来自拉丁语 aequabilis「均匀的」，源头 aequare「使平」（aequus「平等的」）。天气、脾气都平稳不波动的，就是 equable；与 equal 同根。\",\"restaurateur\":\"借自法语 restaurateur「餐馆主」，源头 restaurer「恢复」，再往上是拉丁语 restaurare「重建」。注意词尾是 -teur 不是 -nt：restaurant 是其分词派生，两词拼写常被混淆，如实标注。\",\"semiaquatic\":\"semi-「半」（拉丁语 semi-）+ aquatic「水生的」（源头 aqua「水」）拼合。半水栖的，就是 semiaquatic。\",\"orifice\":\"来自晚期拉丁语 orificium「开口」：os「嘴」（oris）+ facere「做」——做出来的嘴。身体的孔口，就是 orifice。\",\"syllabic\":\"syllable 来自希腊语 syllabē「合到一起（的音）」：syn- + lambanein「抓」——把音抓成一团。经拉丁语、法语进入英语；再加 -ic。按音节的，就是 syllabic。\",\"recurrence\":\"recur 来自拉丁语 recurrere「跑回来」：re- + currere「跑」。跑回来再犯的，就是 recurrence。\",\"resumption\":\"resume 来自拉丁语 resumere「重新拿起」：re- + sumere「取」。停下又拿起的，就是 resumption。\",\"underwhelm\":\"由 overwhelm 反造的 20 世纪戏谑词：whelm 本指「淹没」。压不到人的，就是 underwhelm（让人提不起劲）。\",\"remount\":\"re- + mount「登上、镶嵌」构成：重新上马、重新装裱，都是 remount。\",\"reclamation\":\"reclaim 来自拉丁语 reclamare「大声喊回」：re- + clamare「喊」。喊回来的地与物，就是 reclamation（开垦、回收）。\",\"stationary\":\"station 来自拉丁语 statio「岗位、站立」，源头 stare「站」；再加 -ary。站着不动的，就是 stationary；与 stationery（文具，原指书商的固定摊位）同源异写，如实标注。\",\"shrapnel\":\"以英国军官 Henry Shrapnel 之名命名：他发明的开花炮弹（1784）碎片四射。人名成词，弹片就是 shrapnel。\",\"entangle\":\"en- + tangle「缠结」构成。tangle 来源不完全确定，可能源自斯堪的纳维亚语。缠成一团解不开，就是 entangle。如实标注。\",\"foray\":\"来自古法语 forayer「劫掠」，其词干与 fodder 同根（古法语 fuerre「草料」，源头日耳曼语 *fōdar）——出兵本是去抢草料的。突袭与初次尝试，都是 foray。\",\"roundel\":\"来自古法语 rondel「小圆」，是 rond「圆的」的指小形式，源头拉丁语 rotundus「轮状的」。小圆徽与回旋诗，都是 roundel。\",\"juncture\":\"来自拉丁语 iunctura「接合点」，源头 iungere「连接」。两段路接上的点，就是 juncture（关头）。\",\"inconvenient\":\"in-「不」+ convenient「方便的」（源头拉丁语 convenire「聚到一起、适合」：con- + venire「来」）。凑不到手边的，就是 inconvenient。\",\"oblique\":\"来自拉丁语 obliquus「倾斜的」，其构词有一说为 ob- + liquis（斜）一古词，未定论。斜着来的，就是 oblique；拐弯抹角的话也用它。深层如实标注。\",\"provisionally\":\"provision 来自拉丁语 provisio「预先备置」，源头 providere：pro- + videre「看」；再加 -ally。先备着用的，就是 provisionally（临时地）。\",\"sect\":\"来自拉丁语 secta「派别、追随之道」，源头 sequi「跟随」一说（另说与 secare「切分」有关）。跟同一条道的，就是 sect（教派）。两说并存，如实标注。\",\"pediatric\":\"paediatrics 是按希腊语造的词：pais「孩子」（paidos）+ iatros「医生」。给孩子看病的，就是 pediatric（儿科的）。\",\"scrubby\":\"scrub「灌木丛、矮树」借自斯堪的纳维亚语（与 shrub 同族一说）；再加 -y。矮小杂乱的，就是 scrubby。如实标注。\",\"emporium\":\"来自拉丁语 emporium「贸易站、市场」，源头是希腊语 emporion，其根 emporos「商人、旅客」：en- + poros「通道」。商旅汇聚的大市场，就是 emporium。\",\"suffocate\":\"来自拉丁语 suffocare「扼住喉咙」：sub- + fauces「喉咙」。喘不上气的，就是 suffocate。\",\"ebony\":\"经拉丁语 ebenus、古法语 ebene 而来，源头是希腊语 ebenos「乌木」，再往上可能是埃及语 hbny。黑得发亮的硬木，就是 ebony。\",\"beggary\":\"beggar + -y「状态」。其中 beg 词源存疑：一说与中世纪托钵修女 Beguine 有关，一说是古英语 bedecian「乞讨」的后代，没有定论，这里如实标注。\",\"seraph\":\"来自希伯来语 śārāph「燃烧者」，复数 seraphim：六翼天使炽天使。单数的 seraph 是从复数回构的，如实标注。\",\"protraction\":\"protract 来自拉丁语 protrahere「拖出来、延长」：pro- + trahere「拉」。把时间拖长的，就是 protraction。\",\"standardize\":\"standard 来源分两路合流：古法语 estendart「军旗」，源头是拉丁语 extendere「展开」——旗下集合处即标准；再加 -ize。拉齐到旗下的，就是 standardize。深层如实标注为常见说法。\",\"abide\":\"古英语 ābīdan：ā-（加强语气）+ bīdan「等待、停留」。本义是「守着等下去」，所以 abide by 就是守着规矩不走。\",\"indefensible\":\"in-「不」+ defensible「可辩护的」：defend 源头是拉丁语 defendere「挡开」（de- + fendere「击打」）。挡不住、辩不了的，就是 indefensible。\",\"omissible\":\"omit 来自拉丁语 omittere「放过、省略」：ob- + mittere「送」一说构词；再加 -ible。放得过去的，就是 omissible。深层构词如实标注为一说。\",\"notarize\":\"notary 来自拉丁语 notarius「速记员、公证人」，源头 nota「记号」；再加 -ize。让公证人盖章记号的，就是 notarize。\",\"slacken\":\"slack 是古英语 slæc「松懈的」，与拉丁语 laxus「松的」同族一说；再加 -en。松下来的，就是 slacken。深层关联如实标注为一说。\",\"splice\":\"借自荷兰语 splissen「绞接（绳索）」，其更深来源与 split 同族一说。两绳绞到一起的，就是 splice。深层来源如实标注。\",\"dismal\":\"来自中世纪拉丁语 dies mali「凶日」：盎格鲁-法语 dis mal 指历书上标出的倒霉日子。凶日般阴沉的，就是 dismal。\",\"contraction\":\"contract 来自拉丁语 contractus「拉紧、缔结」，源头 contrahere：con- + trahere「拉」。肌肉拉紧变短、词语缩到一起，都是 contraction；与 tractor（拖拉机）的 tract- 同根。\",\"intermediate\":\"来自中世纪拉丁语 intermediatus「居中的」：inter- + medius「中间的」。站在中间的，就是 intermediate。\",\"candor\":\"来自拉丁语 candor「洁白、纯正」，源头 candere「发白、发光」。心里白得透亮、说话不藏着，就是 candor；candid、candle 都是这条「白光」根。\",\"memorabilia\":\"直接借自拉丁语 memorabilia「值得纪念之物」，是 memorabilis「值得记住的」的中性复数，源头 memor「记着的」。值得留着记着的，就是 memorabilia。\",\"coextensive\":\"co-「共同」+ extensive。extend 来自拉丁语 extendere「伸展」：ex- + tendere「拉」。伸展到同一范围的，就是 coextensive。\",\"noteworthy\":\"note + worthy 构成的中古英语复合词：值得记下来的，就是 noteworthy。\",\"figuration\":\"figure 来自拉丁语 figura「形状」，源头 fingere「捏塑」。捏出的形状与修辞的比喻，都是 figuration 的地盘。\",\"relevancy\":\"relevant 来自拉丁语 relevans「举起的、切题的」，源头 relevare「举起」：法律义「举到案上」转指切题。再加 -cy。切题的程度，就是 relevancy。深层词义如实标注。\",\"decadent\":\"经法语 décadent 而来，源头是中世纪拉丁语 decadentia「衰落」，其根是拉丁语 cadere「落下」。往下掉的世道，就是 decadent；与 decay 同根。\",\"slipshod\":\"slip + shod「穿鞋的」构成：拖着没提上鞋后跟的，就是 slipshod（马虎的）。shod 是 shoe 的过去分词古形。\",\"disclosure\":\"disclose 是中古英语按古法语 desclore 造的：des-「打开」+ clore「关闭」（拉丁语 claudere）。把关着的打开，就是 disclosure。\",\"cagey\":\"cage「笼子」+ -y 构成的美国口语词：像笼中兽一样警觉、不肯轻易开口，就是 cagey。其构成说法较可信。\",\"meditative\":\"meditate + -ive：沉入思考样子的，就是 meditative。\",\"blueprint\":\"blue + print 构成：19 世纪的蓝晒法（cyanotype）把图纸晒成蓝底白线，blueprint 由此得名，后来泛指一切规划蓝图。\",\"malefactor\":\"来自拉丁语 malefactor「作恶者」：male「坏地」+ factor「做者」（facere「做」）。专做坏事的人，就是 malefactor。\",\"vaporous\":\"vapor + -ous：雾气般的，就是 vaporous。\",\"testament\":\"来自拉丁语 testamentum「遗嘱」，源头 testari「作证」，其根 testis「证人」。立证留下的，就是 testament（遗嘱、圣约）。\",\"reiterate\":\"来自拉丁语 reiterare「重复」：re- + iterare「再做」（iterum「再次」）。一遍遍说的，就是 reiterate。\",\"hindsight\":\"hind「后」+ sight「看见」构成的 19 世纪词：事后才看清的，就是 hindsight；20/20 hindsight 是「事后全看清」。\",\"tabular\":\"table 来自拉丁语 tabula「木板、表格」；再加 -ar。排成表格的，就是 tabular。\",\"careworn\":\"care（古英语 caru「忧虑、悲伤」）+ worn（wear「磨穿」的过去分词）构成：被忧虑磨旧了的脸，就是 careworn。\",\"freight\":\"来自中古荷兰语或中古低地德语 vrecht「运费」，是 fracht 的变体，与德语 Fracht 同源。船与火车拉的货，就是 freight。\",\"flirtatious\":\"flirt 来源不完全确定：可能源自法语 fleureter「调情」（本义「在花间飞」，fleur「花」）的缩略，或本土拟声词。眉来眼去的，就是 flirtatious。如实标注存疑。\",\"turgid\":\"来自拉丁语 turgidus「肿胀的」，源头 turgere「肿」。肿胀的与浮夸的文风，都是 turgid。\",\"seclusive\":\"seclude 来自拉丁语 secludere「关起来隔绝」：se-「分开」+ claudere「关」；再加 -ive。爱把自己关起来的，就是 seclusive。\",\"redemption\":\"redeem 来自拉丁语 redimere「买回」：red-「回」+ emere「买」；再加 -tion。赎回来的，就是 redemption。\",\"rectify\":\"来自晚期拉丁语 rectificare「弄直、纠正」：rectus「直的」+ facere「做」。把歪的做直的，就是 rectify。\",\"serpentine\":\"serpent 来自拉丁语 serpens「爬行动物、蛇」，源头 serpere「爬行」；再加 -ine。蛇一样弯的，就是 serpentine。\",\"traction\":\"来自拉丁语 tractio「拉」，源头 trahere。拉着走的力，就是 traction（牵引力）。\",\"appertain\":\"来自古法语 apartenir，源头是晚期拉丁语 appertinere「属于」：ad- + pertinere「伸展到、关乎」（per- + tenere「握住」）。归属到某人名下，就是 appertain to。\",\"repulsion\":\"repel 来自拉丁语 repellere「击退」：re- + pellere「驱赶」；再加 -sion。被推开的劲，就是 repulsion（排斥、厌恶）。\",\"reactionary\":\"reaction 经法语 réaction 而来（政治义出自法国大革命）：对革命「反着动」的，就是 reactionary（反动的）。\",\"deliverance\":\"deliver 来自古法语 delivrer「释放」，源头是晚期拉丁语 deliberare：de- + liberare「使自由」（liber「自由的」）。从困境里被「放自由」，就是 deliverance。\",\"pronouncement\":\"pronounce 来自拉丁语 pronuntiare「公开宣告」：pro- + nuntiare「报告」（nuntius「信使」）；再加 -ment。郑重说出口的，就是 pronouncement。\",\"repine\":\"re- + pine「消瘦、渴慕」构成的古雅词：pine 源头是拉丁语 poena「痛苦」一系（经古英语 pinian「受苦」）。闷闷不乐地抱怨，就是 repine。深层来源如实标注为常见说法。\",\"agricultural\":\"agriculture 来自拉丁语 agricultura：ager「田地」+ cultura「耕作」（colere「耕种」）。与田地耕作有关的一切，就是 agricultural。\",\"initiative\":\"initiate 来自拉丁语 initiare「起始、入会」，源头 initium「开端」：in- + ire「去」。带头迈出第一步的，就是 initiative。\",\"simpleton\":\"simple 来自拉丁语 simplex「单一的」：sem-「一」+ plicare「折」——只折一层的单纯；再加 -ton（仿人名后缀）。单纯到傻的人，就是 simpleton。\",\"inharmonious\":\"in-「不」+ harmonious「和谐的」（源头希腊语 harmonia「拼合、和声」）构成。拼不到一块儿的音，就是 inharmonious。\",\"unabridged\":\"un-「未」+ abridged「删节的」构成。abridge 来自古法语 abregier，源头是拉丁语 abbreviare「缩短」。一字未删的，就是 unabridged。\",\"technicality\":\"technical 按希腊语 tekhnikos「技艺的」造：tekhnē「技艺」；再加 -ality。技术上的细节与抠字眼，就是 technicality。\",\"retrench\":\"来自古法语 retrenchier「砍掉」：re- + trenchier「切」（其更深来源有一说与拉丁语 truncare「截断」有关）。砍掉开支的，就是 retrench（紧缩）。深层来源如实标注为一说。\",\"dandle\":\"来源不完全确定：可能源自意大利语 dondolare「摇晃」，带拟声色彩。把孩子放在膝头一颠一颠地逗，就是 dandle。如实标注存疑。\",\"undertaker\":\"undertake 的派生：先泛指承包人，17 世纪后专指承办葬礼者——词义窄化如实标注。\",\"ultimatum\":\"直接借自拉丁语 ultimatum「最后的（话）」，源头 ultimus「最后的」。最后通牒，就是 ultimatum。\",\"guzzle\":\"来源不完全确定：可能源自古法语 gosier「喉咙」的变体，或本土拟声。大口灌的，就是 guzzle。如实标注存疑。\",\"percolate\":\"来自拉丁语 percolares 一系构词 percolari「滤过」：per- + colare「过滤」（colum「滤器」）。水慢慢滤过咖啡粉的，就是 percolate。\",\"baton\":\"借自法语 bâton「棍、杖」，源头是通俗拉丁语 *basto，晚期拉丁语作 bastum「手杖」。指挥家的小杖、接力赛的棒、警察的警棍，都是 baton。\",\"legitimacy\":\"legitimate 来自中世纪拉丁语 legitimatus「被立为合法的」，源头 legitimare，其根是拉丁语 lex「法」（legis）。合乎法的出身与地位，就是 legitimacy。\",\"sonant\":\"来自拉丁语 sonans「发声的」，源头 sonare「发声」。浊音的、发声的，就是 sonant（语音学术语）。\",\"hemorrhage\":\"来自希腊语 haimorrhagia「大出血」：haima「血」+ rhēgnynai「破裂涌出」，经拉丁语进入英语。血冲破血管的，就是 hemorrhage。\",\"enrage\":\"借自古法语 enrager「使狂怒」：en- + rage「狂怒」（源头拉丁语 rabies「疯狂」）。怒到发狂，就是 enrage；rabies（狂犬病）与它同根。\",\"receptionist\":\"reception 来自拉丁语 receptio「接收」，源头 recipere「接收」；再加 -ist。坐在接收台的人，就是 receptionist。\",\"paralegal\":\"para-「辅助的」（希腊语 para「在旁」）+ legal「法律的」拼合的 20 世纪词：在律师旁边打下手的，就是 paralegal。\",\"oddment\":\"odd + -ment 构成的 19 世纪词：剩下的零碎，就是 oddment。\",\"seminary\":\"来自拉丁语 seminarium「苗圃」，源头 semen「种子」：育苗的地方，后专指神学院。种子的词根与 seminar（研讨班）同源。\",\"venomous\":\"venom 来自拉丁语 venenum「毒药、药剂」，经古法语进入英语；再加 -ous。带毒的，就是 venomous。\",\"formulaic\":\"formula 是拉丁语 formula「小规则、程式」，是 forma「模子」的指小形式。按小模子批量产出的，就是 formulaic。\",\"granular\":\"granule 是拉丁语 granulum「小粒」，是 granum「谷粒」的指小形式；再加 -ar。一粒一粒的，就是 granular；与 grain 同根。\",\"acoustic\":\"来自希腊语 akoustikos「听觉的」，源头 akouein「听」。声音怎么被听见，就是声学；音乐厅的 acoustics 说的就是听感。\",\"ineptitude\":\"inept 来自拉丁语 ineptus「不合宜的」：in- + aptus「合适的」；再加 -itude。笨拙到家，就是 ineptitude；与 aptitude（合宜的天赋）同根。\",\"complexity\":\"complex 来自拉丁语 complexus「交织在一起的」：com- + plectere「编」。线都编到一块儿解不开，就是 complexity。\",\"abreast\":\"a-「处于」+ breast「胸膛」：并排走时胸膛齐平，就是 abreast；keep abreast of 则是「胸膛贴着最新进展一起走」。\",\"indeterminate\":\"in-「未」+ determinate「已定的」（源头拉丁语 determinare「划界」）。还没划清的，就是 indeterminate。\",\"obstruction\":\"obstruct 来自拉丁语 obstructus「被堵的」，源头 obstruere：ob- + struere「堆建」。堆起东西挡道的，就是 obstruction。\",\"harmonize\":\"harmony 来自希腊语 harmonia「接合、和声」，源头 harmozein「拼合」，经拉丁语、法语进入英语；再加 -ize。本义是木工把板「拼合」严丝合缝，引申为音与人的和谐。\",\"procedural\":\"procedure 经法语 procédure 而来，源头是拉丁语 procedere「向前走」：pro- + cedere「走」；再加 -al。按步子走的，就是 procedural。\",\"divination\":\"divine（占卜义）来自拉丁语 divinare「预言」，源头 divinus「神的、属神的」。借神意看未来的，就是 divination。\",\"disclaimer\":\"disclaim 来自盎格鲁-法语 disclaimer「放弃权利主张」：dis- + claim（源头拉丁语 clamare「喊叫」）。公开喊明「不归我管」，就是 disclaimer。\",\"cockpit\":\"cock「公鸡」+ pit「坑」构成：本指斗鸡的围坑，后指飞机驾驶舱与赛车座舱。\",\"notability\":\"notable 来自拉丁语 notabilis「值得注意的」，源头 notare「做记号」，其根 nota「记号」；再加 -ity。值得记一笔的人与事，就是 notability。\",\"vexation\":\"vex 来自拉丁语 vexare「摇晃、折磨」，源头 vehere「运送」的反复形式一说。被摇得心烦的，就是 vexation。深层关联如实标注为一说。\",\"horizontal\":\"horizon 来自希腊语 horizōn「界定（视野）的（圈）」，源头 horizein「设界」，经拉丁语、法语进入英语；再加 -al。与地平线平行的，就是 horizontal。\",\"monetary\":\"money 来自古法语 moneie，源头是拉丁语 moneta「造币厂、钱」——罗马人在朱诺·莫内塔神庙里铸币；再加 -ary。与钱有关的，就是 monetary。\",\"sternum\":\"来自希腊语 sternon「胸膛」，经新拉丁语进入解剖学。胸前的那块骨，就是 sternum（胸骨）。\",\"inheritable\":\"inherit 来自古法语 enheriter，源头是晚期拉丁语 inhereditare，其根 heres「继承人」。传得下去的，就是 inheritable。\",\"quadrant\":\"来自拉丁语 quadrans「四分之一」，源头 quattuor「四」。圆的四分之一，就是 quadrant。\",\"baron\":\"来自古法语 baron「勇士、领主」，源头多认为是日耳曼语 *baro「自由人、战士」。中世纪能打仗的自由人，后来成了最低一等贵族爵位。\",\"legacy\":\"来自拉丁语 legatum「遗赠」，源头 legare「派遣、遗赠」。人走了、东西留下来的，就是 legacy；与 legate（使节）同根。\",\"predicable\":\"predicate 来自拉丁语 praedicare「宣告、断言」：prae- + dicare「宣告」；再加 -able。能断言于主语的，就是 predicable。\",\"undaunted\":\"un- + daunted「被吓退的」构成。daunt 来自拉丁语 domitare「驯服」，是 domare 的反复形式。驯不服的，就是 undaunted（无所畏惧的）。\",\"preordain\":\"pre- + ordain「注定、任命」构成。ordain 来自拉丁语 ordinare「排列、命定」，源头 ordo「秩序」。命数早排好的，就是 preordain。\",\"spectacular\":\"spectacle + -ar：场面惊人的，就是 spectacular。\",\"unreliable\":\"un- + reliable「可靠的」构成。rely 源头是拉丁语 religare「绑回」。绑不住的，就是 unreliable。\",\"glorify\":\"glory 来自拉丁语 gloria「荣耀、名望」，经古法语进入英语；再加 -ify「使…」。把荣耀归给谁，就是 glorify。\",\"gobbet\":\"来自古法语 gobet「一小块」，是 gobe「一口」的指小形式，其更深来源可能与凯尔特语 gob「嘴」有关。一小块肉、一小段文字，都是 gobbet。深层来源如实标注。\",\"precancerous\":\"pre-「在…之前」+ cancerous「癌的」（源头拉丁语 cancer「螃蟹」）拼合的医学词。还没成癌的病变，就是 precancerous。\",\"implosive\":\"implode 是按 explode 反造的 19 世纪词：im-「向内」+ -plode（拉丁语 plaudere「鼓掌、爆响」）。向里塌的，就是 implosive。\",\"superabundant\":\"super-「超过」+ abundant「丰富的」（源头拉丁语 abundare「溢出」：ab- + unda「波浪」）拼合。多到溢出还多的，就是 superabundant。\",\"replication\":\"同 replicare：实验再做一遍，就是 replication。\",\"supportable\":\"support 来自拉丁语 supportare「运来、支撑」：sub- + portare「携带」；再加 -able。撑得住、忍得下的，就是 supportable。\",\"cleavage\":\"cleave「劈开」（古英语 clēofan）+ -age。劈出来的那道缝，就是 cleavage；既指矿物解理，也指领口的沟。注意 cleave 还有「黏着」义（古英语 cleofian），是同形异源的两词合流。\",\"nodular\":\"nodule 是拉丁语 nodulus「小结」，是 nodus「结、节」的指小形式；再加 -ar。长小结的，就是 nodular；与 node 同根。\",\"formative\":\"form + -ative：form 源头是拉丁语 forma「模子」。性格被「模子」浇铸的年纪，就是 formative years。\",\"spontaneous\":\"来自晚期拉丁语 spontaneus「自发的」，源头 sponte「出于自愿」，其更深来源不确定。自己冒出来的，就是 spontaneous。深层来源如实标注存疑。\",\"commentate\":\"由 comment 回构（back-formation）而成：comment 来自拉丁语 commentum「阐释」，源头 comminisci「想出」。坐在解说席上边看边讲，就是 commentate。\",\"trammel\":\"来自古法语 tramail「三层渔网」，源头是晚期拉丁语 tremaculum：tre-「三」+ macula「网眼」。网住手脚的，就是 trammel（束缚）。\",\"rove\":\"来源不完全确定：可能源自中古荷兰语或斯堪的纳维亚语的海盗、漫游一系词汇。漫游漂泊，就是 rove。如实标注存疑。\",\"equivalency\":\"equivalent 来自晚期拉丁语 aequivalens「等值的」：aequus「相等的」+ valere「有价值、有力」。值一样多的，就是 equivalency；与 value 的 val- 同根。\",\"timberline\":\"timber + line 构成的美国词：树长到此为止的界线，就是 timberline（林木线）。\",\"titular\":\"来自拉丁语 titulus「头衔、标题」+ -ar：只有头衔的，就是 titular。\",\"international\":\"inter-「之间」+ national「国家的」在 18 世纪末由边沁造出（Bentham 造 international 一词是史实）。国与国之间的，就是 international。\",\"airborne\":\"air + borne（bear「承载」的过去分词）：由空气承载着的，就是空运的、空降的；灰尘 airborne 就是飘在空中被风「背着走」。\",\"innumerable\":\"来自拉丁语 innumerabilis「数不清的」：in- + numerus「数」。数到手软的，就是 innumerable。\",\"publicize\":\"public + -ize：把事推到公众面前的，就是 publicize。\",\"gamesome\":\"game（古英语 gamen「游戏、欢乐」）+ -some「有…倾向的」构成的古雅词。爱玩爱闹的，就是 gamesome。\",\"fiendish\":\"fiend 是古英语 fēond「敌人、魔鬼」，本是 fehan「恨」的分词形式——「恨着的那个」。魔鬼般狠毒的，就是 fiendish；与 friend（爱着的那个）恰成镜像。\",\"appease\":\"来自古法语 apaisier「使平静」：a- + pais「和平」，源头是拉丁语 pax「和平」。把怒气按回和平状态，就是安抚；与 peace 同源。\",\"invaluable\":\"in-「不可」+ valuable「可估价的」构成：价高到估不出的，就是 invaluable——注意它与「无价值」正相反。\",\"toxicity\":\"toxic 来自希腊语 toxikon「箭毒」，源头 toxon「弓」——毒是抹在箭上的。经拉丁语进入英语；再加 -ity。毒的程度，就是 toxicity。\",\"rouge\":\"借自法语 rouge「红的」，源头是拉丁语 rubeus「红色的」。抹脸的红粉，就是 rouge。\",\"scandalous\":\"scandal 来自希腊语 skandalon「陷阱、绊脚石」，经晚期拉丁语 scandalum 进入英语：本是让人跌倒的东西。丑得跌份的，就是 scandalous。\",\"discontinuance\":\"dis- + continuance：continue 源头是拉丁语 continuare「使连绵」（continuus「不断的」）。把连绵掐断，就是 discontinuance。\",\"interrogate\":\"来自拉丁语 interrogare「盘问」：inter- + rogare「问、要求」。一条条追着问的，就是 interrogate。\",\"gurgle\":\"拟声构词，源头可能与拉丁语 gurgulio「气管、喉咙」同族（经意大利语 gorgogliare 一说）。水在喉咙与瓶口咕噜作响，就是 gurgle。\",\"scummy\":\"scum 来源不完全确定：中古英语 scum，可能源自中古荷兰语 schum「泡沫」，与德语 Schaum 同源。浮渣般下作的，就是 scummy。如实标注。\",\"individualize\":\"individual 来自中世纪拉丁语 individualis「不可再分的」，源头 individuus：in-「不」+ dividuus「可分的」。把不可分的人再按个性对待，就是 individualize。\",\"adjournment\":\"adjourn 来自古法语 ajourner「定到某日」：a- + jour「日子」（源头拉丁语 diurnus「每日的」）。把会「推到另一天」，就是休会。\",\"inexhaustible\":\"in-「不」+ exhaustible「可抽干的」（源头拉丁语 exhaurire「汲尽」：ex- + haurire「汲水」）。抽不干的，就是 inexhaustible。\",\"pestilence\":\"来自拉丁语 pestilentia「瘟疫」，源头 pestis「疫病、祸害」。成片倒下的疫，就是 pestilence。\",\"creed\":\"来自拉丁语 credo「我相信」，是《信经》的开头第一个词。开头两字成了信条本身的名字，就是 creed。\",\"civic\":\"来自拉丁语 civicus「公民的、城市的」，源头 civis「公民」。皇冠曾叫 corona civica「公民冠」；与城市公民有关的，就是 civic。\",\"necessitate\":\"necessity 来自拉丁语 necessitas「必然」，源头 necesse「不可避免的」：ne-「不」+ cedere「让步」一说构词——不让步的必然。使成为必需的，就是 necessitate。深层构词如实标注为传统说法。\",\"documentation\":\"document 来自拉丁语 documentum「例证、教训」，源头 docere「教」。能「教」人认清事实的纸，就是 documentation；与 doctor（教师）同根。\",\"popularize\":\"popular + -ize：把深的变人人懂的，就是 popularize。\",\"foreclosure\":\"foreclose 来自古法语 forclore「关在外面」：fors「外面」（源头拉丁语 foris）+ clore「关闭」。被关在门外、赎回权被断的，就是 foreclosure。\",\"signalize\":\"signal 来自拉丁语 signalis「记号的」，源头 signum「标记」；再加 -ize。以显著行动表彰、标出的，就是 signalize（老派词）。\",\"dog-ear\":\"dog「狗」+ ear「耳朵」构成：把书页角折得像耷拉的狗耳朵，就是 dog-ear。\",\"posterior\":\"直接借自拉丁语 posterior「更在后的」，是 posterus「后面的」比较级。位置在后的，就是 posterior（臀部是其委婉义）。\",\"anarchy\":\"来自希腊语 anarkhia「无统治者状态」：an-「无」+ arkhos「统治者」。没人坐在统治者的位子上，就是无政府状态；与 monarch（君主）的 -arch 同根。\",\"internalize\":\"internal 来自拉丁语 internus「内部的」；再加 -ize。把规则装进心里的，就是 internalize。\",\"remediable\":\"remedy 来自拉丁语 remedium「药、补救」：re- + mederi「治疗」；再加 -able。治得好的，就是 remediable。\",\"overwrought\":\"over- + wrought「做成的」（work 的古过去分词）：做工过度的，就是 overwrought（过度紧张、过分修饰的）。\",\"accrual\":\"accrue 来自古法语 acreue，源头是拉丁语 accrescere「渐渐长大」：ad- + crescere「生长」。利息像庄稼一样慢慢长出来，就是应计累积；与 increase 同根。\",\"industrial\":\"industry 来自拉丁语 industria「勤勉」，其构词有一说为 indu-「在内」+ struere「建」；再加 -al。勤勉建厂的时代，就是 industrial。深层构词如实标注为一说。\",\"caravan\":\"借自法语 caravane，源头是波斯语 kārvān「骆驼商队」。丝绸之路上连成串的驼队，就是 caravan；后来也指大篷车队。\",\"merchandise\":\"来自古法语 marchandise「货物」，源头 marchant「商人」，再往上是拉丁语 mercans「买卖者」（mercari「贸易」）。货架上待卖的，就是 merchandise。\",\"urbanite\":\"urban 来自拉丁语 urbanus「城里的」，源头 urbs「城」；再加 -ite「居民」。城里人，就是 urbanite。\",\"serviceable\":\"service 来自拉丁语 servitium「奴役、服务」，源头 servus「奴隶」；再加 -able。用得上的，就是 serviceable。\",\"preemption\":\"preempt 是按拉丁语 praeemptus 回构的词：prae- + emere「买」——抢先买下。优先购买与先发制人，都是 preemption。\",\"incitement\":\"incite 来自拉丁语 incitare「催动、煽动」：in- + citare「催促」（ciere「使动」）。把火煽起来的，就是 incitement。\",\"incivility\":\"in-「无」+ civility「礼貌」：civil 来自拉丁语 civilis「公民的」，其根 civis「公民」。不像个公民样子的粗鲁，就是 incivility。\",\"garment\":\"来自古法语 garnement「装备、衣物」，源头 garnir「装备、防护」，其根是日耳曼语 *warnjan「防备」。穿在身上的「装备」，就是 garment；与 garnish（装饰）同根。\",\"evidential\":\"evidence 来自拉丁语 evidentia「显明」，源头 evidens：e- + videre「看」。看得见、拿得出手的，就是 evidential。\",\"smattering\":\"smatter 来源不完全确定：中古英语 smateren「闲聊、略知」，可能带拟声色彩或源自斯堪的纳维亚语。一知半解的一点点，就是 smattering。如实标注。\",\"hack\":\"（乱砍义）古英语 haccian「砍碎」，带拟声色彩，与德语 hacken 同源。hack 的「黑客、窍门」等义是这条「砍」义的后世引申。\",\"emote\":\"由 emotion 回构（back-formation）而成：emotion 经法语而来，源头是拉丁语 emovere「激动」：e- + movere「移动」。把情绪「演」出来，就是 emote。\",\"decriminalize\":\"de-「去除」+ criminal（源头拉丁语 crimen「罪行、指控」）+ -ize。把某行为从罪名册上划掉，就是 decriminalize。\",\"transmissible\":\"transmit 来自拉丁语 transmittere「送过去」：trans- + mittere「送」；再加 -ible。送得过去（病、信号）的，就是 transmissible。\",\"lubricant\":\"lubricate 来自拉丁语 lubricare「使滑」，源头 lubricus「滑溜的」。让摩擦面滑起来的，就是 lubricant。\",\"unawares\":\"un- + aware「察觉的」加副词后缀 -s 构成（中古英语 -s 状语格）。没察觉地，就是 unawares（at unawares 猝不及防）。\",\"revolutionary\":\"revolution 来自晚期拉丁语 revolutio「旋转」，源头 revolvere：re- + volvere「滚动」。天体转一圈的词，被用来指政权翻个个儿，就是 revolutionary 的来历。\",\"governess\":\"govern 来自拉丁语 gubernare「掌舵、统治」，源头是希腊语 kybernan「驾驶」；-ess 表女性。旧时在宅子里「掌舵」孩子教育的女教师，就是 governess；与 cybernetics（控制论）的 kyber- 同根。\",\"unitary\":\"unit 来自拉丁语 unitas「统一」，源头 unus「一」；再加 -ary。合而为一的，就是 unitary。\",\"carnivorous\":\"拉丁语拼合词：carnivorus「吃肉的」，caro「肉」+ vorare「吞食」。与 carnival（告别肉食→狂欢节）的 carn- 同根。\",\"milestone\":\"mile + stone 构成：罗马人在大道旁每千步立的石碑，就是 milestone；引申为里程碑事件。\",\"pavilion\":\"来自古法语 paveillon「帐篷」，源头是拉丁语 papilio「蝴蝶」——帐篷张开像蝶翼。展馆与凉亭，就是 pavilion。\",\"interdependent\":\"inter-「互相」+ dependent「依赖的」（源头拉丁语 dependere「垂挂」）构成。你挂着我、我挂着你的，就是 interdependent。\",\"exploratory\":\"explore 来自拉丁语 explorare「探查、喊着搜寻」：ex- + plorare「呼喊」一说——猎人喊着惊出猎物。此关联为传统说法，如实标注。摸着路探的，就是 exploratory。\",\"bestiality\":\"bestial 来自晚期拉丁语 bestialis「野兽的」，源头 bestia「野兽」；再加 -ity。beast 也是 bestia 的后代；兽性行为就是 bestiality。\",\"lingual\":\"来自拉丁语 lingua「舌头、语言」+ -al。与舌头和语言有关的，就是 lingual；language 与它同根。\",\"titan\":\"来自希腊语 Titān「提坦」：神话里推翻乌拉诺斯的巨神族。巨人般的人与物，就是 titan。\",\"recital\":\"recite 来自拉丁语 recitare「朗读、背诵」：re- + citare「引用、催动」；再加 -al。背出来的演出，就是 recital（独奏会、朗诵会）。\",\"forestation\":\"forest 来自古法语 forest「王室猎苑」，源头是中世纪拉丁语 forestis「（王室的）林地」，其更深来源有一说与拉丁语 foris「外面」有关（城外之地）。成片造林，就是 forestation。深层来源如实标注为一说。\",\"endearment\":\"endear：en-「使…」+ dear「亲爱的、珍贵的」（古英语 dēore）构成。让人更亲昵的话语，就是 endearment。\",\"subhuman\":\"sub-「低于」+ human「人的」拼合：低于人标准的，就是 subhuman。\",\"disburden\":\"dis-「卸下」+ burden（古英语 byrthen「重担」）构成。把担子卸了，就是 disburden。\",\"hydrology\":\"hydro-「水」（希腊语 hydōr）+ -logy「学问」（logos「言说」）拼合的 18 世纪学科词。研究水的学问，就是 hydrology。\",\"utilize\":\"经法语 utiliser 而来，源头是意大利语 utilizzare，其根是拉丁语 utilis「有用的」，再往上是 uti「使用」。用起来的，就是 utilize。\",\"suburbanite\":\"suburb 来自拉丁语 suburbium「城下之地」：sub- + urbs「城」；再加 -ite「居民」。住城边的人，就是 suburbanite。\",\"deferment\":\"defer 来自拉丁语 differre「推迟、不同」：dis- + ferre「携带」。把事情往后「带」，就是 deferment（缓期）；与 different 本是同一个动词的两副面孔。\",\"disbursement\":\"disburse 来自古法语 desbourser「掏钱」：des- + bourse「钱包」（源头晚期拉丁语 bursa「皮包」）。从钱包往外掏的款，就是 disbursement；与 bursar（财务）同根。\",\"synopsis\":\"来自希腊语 synopsis「总览」：syn-「共同」+ opsis「看」。一眼看全的，就是 synopsis（梗概）。\",\"pageant\":\"来自中世纪拉丁语 pagina「舞台台架」，其更深来源与拉丁语 pangere「钉、固定」同族一说。搭台演出的巡游盛典，就是 pageant。深层来源如实标注为一说。\",\"hellish\":\"hell 是古英语 hell「冥界」，源头是印欧语 *kel-「遮盖」——被盖住的地下世界；再加 -ish。地狱般的，就是 hellish。\",\"scratchy\":\"scratch 来源不完全确定：中古英语 scracchen，可能是 scart 与 cratch 一类词的混合，带拟声色彩；再加 -y。扎人、沙哑的，就是 scratchy。如实标注。\",\"tolerable\":\"tolerate 来自拉丁语 tolerare「背负、忍受」，源头 tollere「举起」一系；再加 -able。忍得下的，就是 tolerable。\",\"cartel\":\"经法语、德语 Kartell 而来，源头是意大利语 cartello「告示、小纸片」，其根是拉丁语 charta「纸」。本义是写在纸上的挑战书、协定，后转指企业联盟与贩毒集团。\",\"contamination\":\"同 contaminate：沾上不洁之物，就是 contamination。\",\"slander\":\"来自古法语 esclandre「丑闻、诽谤」，源头是拉丁语 scandalum「绊脚石、丑闻」，再往上是希腊语 skandalon。让人跌跟头的坏话，就是 slander。\",\"rapport\":\"借自法语 rapport「关系、融洽」，源头 rapporter「带回、报告」：re- + apporter「带来」（源头拉丁语 apportare）。心意带得通的，就是 rapport（融洽关系）。\",\"hangar\":\"借自法语 hangar「棚屋、机库」，其更深来源有争议，一说与日耳曼语 *haimgard「家园围栏」有关。停飞机的大棚，就是 hangar；与 anger 无关。深层来源如实标注存疑。\",\"irritation\":\"同 irritate：皮肤与脾气被「刺激」的反应，就是 irritation。\",\"subversive\":\"subvert 来自拉丁语 subvertere「从下面翻倒」：sub- + vertere「转」；再加 -ive。从根上掀的，就是 subversive。\",\"subjoin\":\"来自拉丁语 subiungere「附在下面」：sub- + iungere「连接」。在末尾附上的，就是 subjoin（老派词）。\",\"artificiality\":\"artificial 来自拉丁语 artificialis「人工做成的」：ars「技艺」+ facere「做」；再加 -ity。人手「做」出来的非天然感，就是 artificiality。\",\"janitorial\":\"janitor 来自拉丁语 ianitor「守门人」，源头 ianua「门」。守门看楼的人，就是 janitor；其形容词是 janitorial。\",\"gaiety\":\"gaiety 是法语 gaieté 的英语化：gai「欢快的」，源头可能是日耳曼语或普罗旺斯语，未完全定论。满场的欢快，就是 gaiety。深层来源如实标注。\",\"chivalrous\":\"chivalry 来自古法语 chevalerie「骑士（群体）」，源头 chevalier「骑士」，再往上是晚期拉丁语 caballarius「骑手」，词干 caballus「马」。骑马人的规矩，就是骑士风度。\",\"overcapitalize\":\"over- + capitalize「资本化」构成。capital 来自拉丁语 capitalis「关乎头（本金）的」，其根 caput「头」。本金报过头的，就是 overcapitalize。\",\"balderdash\":\"词源存疑：16 世纪末出现时指乱掺的酒水饮料，后来转指胡言乱语；到底由哪两个词拼成、与哪种语言有关，都没有定论，这里不硬编。\",\"lavatory\":\"来自晚期拉丁语 lavatorium「洗涤处」，源头 lavare「洗」。先指修道院的洗手处，后成厕所的委婉名；与 laundry 同根。\",\"deface\":\"来自古法语 defacier「毁容」：des-「去掉」+ face「脸」（源头拉丁语 facies）。把脸刮花的，就是 deface；涂鸦毁损公物用的正是它。\",\"finagle\":\"词源存疑：19 世纪美国方言词，可能由 fainaigue 一类牌戏作弊词或德语方言演变而来，没有定论。耍滑头弄到手的，就是 finagle。如实标注存疑。\",\"pleasantry\":\"pleasant 来自古法语 plaisant「令人愉快的」，是 plaisir「取悦」的分词形式，源头拉丁语 placere「使满意」；再加 -ry。逗乐的客套话，就是 pleasantry。\",\"brilliancy\":\"brilliant 经法语 brillant 而来，其词干一说源自拉丁语 bēryllus「绿柱石」——像宝石一样发亮；再加 -ancy 表状态。此关联流传广但属推测，如实标注。\",\"marginal\":\"margin 来自拉丁语 margo「边缘」（marginis）；再加 -al。站在页边与主流边缘的，就是 marginal。\",\"senatorial\":\"senate 来自拉丁语 senatus「元老院」，源头 senex「老人」；再加 -orial。老人院（元老院）的，就是 senatorial。\",\"previsional\":\"prevision 是按拉丁语 praevisio「预见」造的词：prae- + videre「看」；再加 -al。预先看见的，就是 previsional。\",\"prominent\":\"来自拉丁语 prominens「向前突出的」，源头 prominere：pro- + minere「伸出」。探出众人一头的，就是 prominent。\",\"rumpus\":\"词源存疑：18 世纪词，可能由 romp「喧闹」一类词戏谑造出，没有定论。喧闹骚动，就是 rumpus；这里不硬编。\",\"passivity\":\"passive + -ity：被动的状态，就是 passivity。\",\"geyser\":\"借自冰岛语 Geysir，是冰岛一处间歇泉的专名，源头 geysa「喷涌」。专名变成了通名：会喷的泉都叫 geyser。\",\"irreclaimable\":\"ir-「不可」+ reclaimable「可收回、可改造的」：reclaim 源头是拉丁语 reclamare「喊回」（re- + clamare「喊」）。喊不回来的，就是 irreclaimable。\",\"scrimmage\":\"skirmish 的变体：skirmish 来自古法语 eskirmir「交锋」，源头是日耳曼语 *skirmjan「护卫」。橄榄球的混战线，就是 scrimmage。\",\"politicize\":\"politic 来自希腊语 politikos「城邦的」，源头 polis「城邦」，经拉丁语、法语进入英语；再加 -ize。把事拉进政治的，就是 politicize。\",\"astride\":\"a-「处于…状态」+ stride（古英语 stridan「大步跨」）。双腿跨在马背两侧，就是 astride。\",\"kayak\":\"借自因纽特语 qajaq「猎手的小船」：格陵兰因纽特人的皮划艇原名。一个人钻进去划的，就是 kayak。\",\"evocative\":\"evoke 来自拉丁语 evocare「唤出」：e- + vocare「呼喊」。一声把记忆喊出来的，就是 evocative；与 voice 的 voc- 同根。\",\"fathom\":\"古英语 fæðm「张开的双臂」，既是动作也是长度单位：双臂展开约六英尺为一 fathom。先用胳膊量水深，再引申为「测透」道理。\",\"gradient\":\"同 gradus：坡的「步级」陡缓，就是 gradient（坡度、梯度）。\",\"squab\":\"（幼鸽义）来源不完全确定：可能借自斯堪的纳维亚语（瑞典语 skvabb「松软的肉」一说）。胖乎乎的幼鸽与矮沙发，都是 squab。如实标注。\",\"bemused\":\"be- + muse「沉思、出神」。muse 经古法语 muser「发呆、闲逛」而来，更深来源不确定，可能与中世纪拉丁语 musum「口鼻、愣住的脸」有关，此处如实标注存疑。被想得发懵，就是 bemused。\",\"lineage\":\"来自古法语 lignage「世系」，源头是拉丁语 linea「线」。家族像一条线往下传，就是 lineage；与 line 同根。\",\"penal\":\"来自拉丁语 penalis「刑罚的」，源头 poena「惩罚」，再往上是希腊语 poinē「赎罪金」。关乎刑罚的，就是 penal。\",\"sardonic\":\"来自希腊语 sardonios「苦笑的」：传说撒丁岛（Sardinia）有毒草，吃了面部抽搐如笑。冷笑，就是 sardonic；地名关联为古代说法，如实标注。\",\"strategist\":\"strategy + -ist：谋兵的人，就是 strategist。\",\"oppressive\":\"oppress 来自拉丁语 oppressus「被压倒的」，源头 opprimere：ob- + premere「压」。压得人喘不过气的，就是 oppressive。\",\"productivity\":\"productive（源头 producere「带出」）+ -ity：带得出成果的效率，就是 productivity。\",\"observable\":\"observe 来自拉丁语 observare「守望、遵守」：ob- + servare「保持、看守」；再加 -able。看得见的，就是 observable。\",\"gibberish\":\"来源不完全确定：可能由 gibber「胡言乱语」（拟声）加 -ish（仿 language 类词尾）构成，也有一说与炼金术士 Geber 之名有关。听不懂的胡话，就是 gibberish。如实标注。\",\"bailiff\":\"来自古法语 baillif「管家、地方官」，源头是拉丁语 baiulus「搬运人、看管者」。替领主或法庭看管执行事务的人，就是 bailiff。\",\"lanyard\":\"来自中古法语 laniere「皮条」，受 yard「码」影响改拼：laniere 源头可能是拉丁语 lanium 一系或日耳曼语，未完全定论。挂哨子、证件的绳，就是 lanyard。深层来源如实标注。\",\"ethical\":\"ethic 来自希腊语 ēthikos「关乎品性的」，源头 ēthos「习惯、品格」，经拉丁语、法语进入英语。合乎品格规矩的，就是 ethical。\",\"vaporize\":\"vapor 来自拉丁语 vapor「蒸汽、热气」；再加 -ize。化成汽的，就是 vaporize。\",\"rotisserie\":\"借自法语 rôtisserie「烤肉店」，源头 rôtir「烤」，再往上是日耳曼语 *raustjan「烤」一系。转着烤的，就是 rotisserie。深层来源如实标注为常见说法。\",\"bloodless\":\"blood（古英语 blōd）+ -less「没有」。没流血的政变、没血色的脸，都是 bloodless。\",\"malady\":\"来自古法语 maladie「疾病」，源头 malade「病的」，再往上是拉丁语 male habitus「状态不佳」：male「坏地」+ habitus「状态」。身上「状态坏了」，就是 malady。\",\"vicinity\":\"来自拉丁语 vicinitas「邻近」，源头 vicinus「邻居」，其根 vicus「村、街区」。左邻右舍那一片，就是 vicinity。\",\"peculiarity\":\"peculiar 来自拉丁语 peculiaris「私有的、特别的」，源头 peculium「私产」，其根 pecus「牲畜」——私产先是牛羊。属于自己的那份怪，就是 peculiarity。\",\"spectacle\":\"来自拉丁语 spectaculum「演出、景象」，源头 spectare「看」，其根 specere「看」。看的大场面，就是 spectacle；眼镜（spectacles）也是「看的工具」。\",\"oafish\":\"oaf 本指被精灵换走的「换子」，源头与 elf 同出一词（古诺斯语 alfr）：换来的孩子痴痴呆呆。再加 -ish。呆头呆脑的，就是 oafish。\",\"palmistry\":\"palm「手掌」+ -istry（仿 artistry 造）：palm 来自拉丁语 palma「手掌、棕榈」。看手掌纹断命的，就是 palmistry（手相术）。\",\"revitalized\":\"re- + vitalize「赋予生命」：vital 源头是拉丁语 vita「生命」。重新有命气的，就是 revitalized。\",\"unsophisticated\":\"un- + sophisticated「老练的、掺假的」构成：本义是「没被 sophist 式手法污染的」——天真未凿。源头同希腊语 sophos「聪明」。\",\"invalid\":\"（病人义与无效义同形异源）病人义的 invalid 是 in-「不」+ valid「强健的」（拉丁语 validus，其根 valere「有力」）——没力气的人；法律义的 invalid 则是「无（效）力」。两义共用一个拼写，如实标注。\",\"splay\":\"display 的缩略变体：display 来自拉丁语 displicare「展开」：dis- + plicare「折」。张开外撇的，就是 splay。\",\"ferocious\":\"来自拉丁语 ferox「凶猛的」，源头 ferus「野生的」。野性没驯掉的，就是 ferocious；与 fierce（经法语的 ferus 后代）同根。\",\"strangulate\":\"来自拉丁语 strangulare「勒死」，源头是希腊语 strangalos「绞索」一系。勒到缺血的，就是 strangulate（绞窄）。\",\"triplicate\":\"来自拉丁语 triplicare「三倍化」：tri-「三」+ plicare「折」。折出三份的，就是 triplicate（一式三份）。\",\"scarcely\":\"scarce 来自古法语 scars「吝啬的、稀少的」，源头可能是晚期拉丁语 *excarpsus 一系（carpere「摘取」——摘剩下的）；再加 -ly。几乎不的，就是 scarcely。深层来源如实标注为一说。\",\"prosecution\":\"prosecute 来自拉丁语 prosecutus「被追随到底的」，源头 prosequi：pro- + sequi「跟随」——法律追着不放。起诉与检控，就是 prosecution。\",\"substantial\":\"substance 来自拉丁语 substantia「实体、底层」，源头 substare：sub- + stare「站」——站在下面撑着的东西。够分量的，就是 substantial。\",\"schema\":\"直接借自希腊语 skhēma「形状、图式」，源头 ekhein「持有、处于」。脑子里的大框架，就是 schema。\",\"cerebral\":\"来自拉丁语 cerebrum「脑」+ -al。关乎大脑的，就是 cerebral；也引申为「理智型的」。\",\"misdemeanor\":\"mis- + demeanor「举止」构成的法律词：举止失当，罪名上就是 misdemeanor（轻罪）。\",\"churl\":\"古英语 ceorl「自由民农民」，与德语 Kerl「家伙」同源，本无贬义。中世纪后农民地位下降，词义跟着跌成「粗人、吝啬鬼」。\",\"murmurous\":\"murmur 是拉丁语 murmur「低语、潺潺」的拟声词，经古法语进入英语；再加 -ous。水声人声低低的，就是 murmurous。\",\"paraplegic\":\"paraplegia 是按希腊语造的医学词：para- + plēgē「打击」——脊髓一击，下身瘫痪。截瘫的，就是 paraplegic。\",\"solitude\":\"来自拉丁语 solitudo「孤独」，源头 solus「单独的」。一个人的境地，就是 solitude。\",\"recapitulation\":\"recapitulate 来自晚期拉丁语 recapitulare「按标题重述」：re- + capitulum「小标题」（caput「头」的指小）。按头目再过一遍的，就是 recapitulation。\",\"unsubstantial\":\"un- + substantial「实质的」构成。substantial 源头是拉丁语 substantia「底层实体」。没底子的，就是 unsubstantial。\",\"shrewd\":\"shrew 本指「鼩鼱」，中古英语里转指恶人：shrewd 先是「恶毒的」，后滑向「精明」——词义从骂人变夸人。shrew 的更深来源不确定，如实标注这段滑坡。\",\"reconnoiter\":\"借自法语 reconnoître 的旧拼写「侦察」，源头是拉丁语 recognoscere「认出」：先去「认」清地形的，就是 reconnoiter。\",\"jeopardize\":\"jeopardy 来自古法语 jeu parti「均势的博弈」：jeu「游戏」（源头拉丁语 iocus「玩笑」）+ parti「分开的」——胜负未分的险局。再加 -ize。把人放进险局的，就是 jeopardize。\",\"tourniquet\":\"借自法语 tourniquet「止血带」，源头 tourner「转」：拧着收紧的带子，就是 tourniquet。\",\"debouch\":\"借自法语 déboucher「涌出、开口」：dé-「出」+ bouche「嘴」（源头拉丁语 bucca「脸颊、嘴」）。河流、军队从窄口「嘴」里涌出来，就是 debouch。\",\"redaction\":\"redact 来自拉丁语 redactus「被带回、编定的」，源头 redigere：red- + agere「驱动」。编定的删节本，就是 redaction。\",\"tumescence\":\"tumescent 来自拉丁语 tumescens「正在肿起的」，源头 tumescere，其根 tumere「肿」。肿胀，就是 tumescence。\",\"atrophy\":\"来自希腊语 atrophia「缺乏营养」：a-「无」+ trophē「营养」（trephein「喂养」）。长期吃不到营养的肌肉，就是萎缩；trophy（奖杯）与它同根但走的是另一条词义路。\",\"behest\":\"古英语 behǣs「命令、许诺」，由 be- + hǣs「吩咐」构成，与 hātan「命令」同源。at the behest of 就是「奉…之命」。\",\"imperforate\":\"im-「无」+ perforate「穿孔的」：perforate 源头是拉丁语 perforare「钻透」：per- + forare「钻」。天生没孔的，就是 imperforate。\",\"objurgate\":\"来自拉丁语 obiurgare「责骂」：ob- + iurgare「争吵、诉讼」（ius「法」一族）。劈头盖脸训的，就是 objurgate。\",\"insusceptible\":\"in-「不」+ susceptible「易受影响的」：susceptible 源头是拉丁语 suscipere「接住、承受」（sub- + capere「取」）。接不住影响的，就是 insusceptible。\",\"firmament\":\"来自拉丁语 firmamentum「支撑物、天空」，源头 firmare「使稳固」（firmus「坚固的」）。古人以为天是钉牢的穹顶，就是 firmament。\",\"impetuosity\":\"impetuous 来自晚期拉丁语 impetuosus「猛烈的」，源头 impetus「冲力」：in- + petere「冲向」。冲劲收不住的，就是 impetuosity。\",\"frangible\":\"来自拉丁语 frangere「打破」+ -ible「可…的」。设计上可被打断的（如易碎密封），就是 frangible。\",\"delusory\":\"delude 来自拉丁语 deludere「愚弄、欺骗」：de- + ludere「玩耍、戏弄」。被人当猴耍的假象，就是 delusory；与 illusion（in- + ludere）同根。\",\"labyrinthine\":\"labyrinth 来自希腊语 labyrinthos「迷宫」，其更深来源不确定（可能为前希腊语借词，克里特神话的牛头怪迷宫即此）。弯弯绕绕如迷宫的，就是 labyrinthine。深层来源如实标注存疑。\",\"rapacity\":\"rapacious 来自拉丁语 rapax「攫取的」，源头 rapere「抢夺」。见什么抓什么的贪，就是 rapacity；与 rapid（抢走般的快）同根。\",\"moiety\":\"来自古法语 moitié「一半」，源头是拉丁语 medietas「中点、一半」，其根 medius「中间的」。法律与化学里的一半，就是 moiety。\",\"raconteur\":\"借自法语 raconteur「讲故事的人」，源头 raconter「讲述」：re- + aconter「算、讲」（源头拉丁语 computare「计算」）。会讲故事的人，就是 raconteur；与 recount（复述/ recount 数）同根。\",\"crucible\":\"来自中世纪拉丁语 crucibulum「熔锅、夜灯」，其更深来源不确定，一说与 crux「十字」有关。烧得通红的熔锅，后比喻严峻考验，就是 crucible。深层来源如实标注存疑。\",\"excursive\":\"excursion 来自拉丁语 excursio「跑出、远足」，源头 excurrere：ex- + currere「跑」。话跑出主题之外的，就是 excursive；与 current（跑着的水→洋流）的 curr- 同根。\",\"fermentation\":\"ferment 来自拉丁语 fermentum「酵母、发酵」，源头 fervere「沸腾」。古人看面团冒泡如沸；沸腾般的酝酿与骚动，就是 fermentation。\",\"methodology\":\"method（希腊语 methodos「路数」）+ -logy「学问」拼合的 19 世纪词。研究路数的学问，就是 methodology。\",\"carious\":\"来自拉丁语 caries「腐烂、龋坏」+ -ous。牙被蛀烂，就是 carious；caries 本身就是龋齿的学名。\",\"embankment\":\"embank：em-「使进入」+ bank「岸、堤」（源自斯堪的纳维亚语 banki「土埂」一说）；再加 -ment。堆土成堤，就是 embankment。深层来源如实标注。\",\"caseous\":\"来自拉丁语 caseus「奶酪」+ -ous。病灶变得像干酪一样，就是 caseous；casein（酪蛋白）与它同源。\",\"sobriety\":\"sober + -ity（经法语 sobriété）：清醒与节制，就是 sobriety。\",\"collocate\":\"来自拉丁语 collocare「安置在一起」：col- + locare「放置」（locus「地点」）。词与词总爱挨着放，就是 collocate（搭配）。\",\"surrogate\":\"来自拉丁语 surrogatus「被选来顶替的」，源头 surrogare：sub- + rogare「提议、要求」。顶替上场的人与物，就是 surrogate（代理、代孕）。\",\"incumbency\":\"incumbent 来自拉丁语 incumbens「压在上面的」，源头 incumbere：in- + cubare「躺」——职务「躺」在谁身上，谁就是现任。incumbency 就是在任状态。\",\"issuance\":\"issue 来自古法语 issue「出口」，源头是通俗拉丁语 *exuta，其根是拉丁语 exire「出去」；再加 -ance。从官方「出去」的，就是 issuance（发行）。\",\"nictitate\":\"来自拉丁语 nictitare「眨眼」，是 nictare「眨」的反复形式，源头 nicere「示意」一说。眨眼这个动作，学名就是 nictitate。深层如实标注。\",\"stringency\":\"stringent 来自拉丁语 stringens「拉紧的」，源头 stringere「拉紧、束缚」。绳子拉到最紧的，就是 stringency（严格、紧缩）。\",\"perfidy\":\"来自拉丁语 perfidia「背信」，源头 perfidus「不忠的」：per-「过头」+ fides「信任」一说构词。信义毁尽的，就是 perfidy。深层构词如实标注为传统说法。\",\"consignment\":\"consign 来自拉丁语 consignare「盖印交付」：con- + signare「做记号」（signum「印记」）。盖了印交出去的货，就是 consignment（托运、寄售）。\",\"impasse\":\"借自法语 impasse「死胡同」：in-「不」+ passe「通道」（源头拉丁语 passus「步」）。走不通的局，就是 impasse。\",\"natation\":\"来自拉丁语 natatio「游泳」，源头 natare「游泳」，是 nare 的反复形式。在水里游这件事，就是 natation（老派词）。\",\"sophism\":\"sophist 来自希腊语 sophistēs「智者、诡辩家」，源头 sophos「聪明的」，经拉丁语进入英语。智者派的把戏：貌似聪明的谬论，就是 sophism。\",\"malapropos\":\"借自法语 mal à propos「不合时宜」：mal「坏地」（拉丁语 male）+ à propos「切题」（源头拉丁语 propositum「提出的」）。来得不是时候的，就是 malapropos。\",\"parotid\":\"来自希腊语 parōtis「耳旁的（腺）」：para-「在旁」+ ōtos「耳的」（ous「耳」）。长在耳边的腮腺，就是 parotid。\",\"styptic\":\"来自希腊语 styptikos「收敛的」，源头 styphein「收缩」。能止血收口的，就是 styptic（如 styptic pencil 止血笔）。\",\"apothegm\":\"来自希腊语 apophthegma「精辟的断语」：apo-「出自」+ phthengesthai「发声、说出」。一出口就成格言的短句，就是 apothegm，也拼作 apophthegm。\",\"bobble\":\"bob「上下摆动」（中古英语 bobben，可能源自拟声）+ -le「反复」后缀。小球在头顶一颠一颠，就是 bobble；手忙脚乱接不住球也叫 bobble。\",\"telekinesis\":\"tele-「远」（希腊语 tēle）+ kinesis「运动」（kinein「动」）拼合的 19 世纪词。隔空移物的，就是 telekinesis（心灵致动）。\",\"catechism\":\"来自晚期拉丁语 catechismus，源头是希腊语 katēkhizein「口头教导」，本义「在耳边出声教」：kata- + ēkhein「发声」（ēkhō「回声」）。问答式教义手册，就是 catechism；echo 与它同根。\",\"salvageable\":\"salvage 来自法语 salvage「救助费」，源头是拉丁语 salvare「拯救」；再加 -able。捞得回来的，就是 salvageable。\",\"editorial\":\"editor 由拉丁语 edere「出版、给出」：e-「出」+ dare「给」派生（editor 本义「出版人」）；再加 -ial。代表报社立场的文章，就是 editorial。\",\"porosity\":\"porous 来自拉丁语 porus「小孔」，源头是希腊语 poros「通道」；再加 -ity。孔多的程度，就是 porosity。\",\"deportment\":\"deport 的旧义「举止」来自法语 se déporter「表现、行止」，源头 deportare 本义「携带」——一个人「携带」自己的方式，就是 deportment。与 deportation 是同一动词的两条义路。\",\"parlance\":\"来自古法语 parlance「说法」，源头 parler「说话」，再往上是晚期拉丁语 parabolare「讲比喻、说话」，其根是希腊语 parabolē「比喻」。行话与说法，就是 parlance；与 parable（寓言）同根。\",\"vituperation\":\"vituperate 来自拉丁语 vituperare「责备」：vitium「缺点」+ parare「备」一说构词——备好一堆缺点开骂。恶骂，就是 vituperation。深层构词如实标注为传统说法。\",\"coquet\":\"借自法语 coquet「像小公鸡般卖俏」，是 coq「公鸡」的指小形式。像小公鸡一样抖羽毛引人注意，就是 coquet（卖弄风情）。\",\"nasalize\":\"nasal 来自拉丁语 nasus「鼻子」；再加 -ize。发音往鼻子里走的，就是 nasalize。\",\"verdancy\":\"verdant 来自古法语 verdoyant「变绿的」，源头是拉丁语 viridis「绿的」一系（经通俗拉丁语 *virdiare）。青翠，就是 verdancy。\",\"sectarianism\":\"sect + -arian + -ism：只认本派的，就是 sectarianism（宗派主义）。\",\"improvisational\":\"improvise 经法语、意大利语 improvvisare 而来，源头是拉丁语 improvisus「未预见的」：in- + provisus「预先看好的」。没稿子现场来的，就是 improvisational。\",\"devitalize\":\"de-「抽走」+ vital「生命的」（拉丁语 vita「生命」）+ -ize。把命气抽掉的，就是 devitalize。\",\"comportment\":\"comport 来自古法语 comporter，源头是拉丁语 comportare「聚到一起、忍受」：com- + portare「携带」。一个人「携带」自己的方式，就是 comportment（举止）。\",\"gesticulate\":\"来自拉丁语 gesticulari「做手势」，是 gestus「姿态」的指小形式，源头 gerere「携带、做出」。说话时手舞足蹈地比划，就是 gesticulate。\",\"tractable\":\"来自拉丁语 tractabilis「可处理的」，源头 tractare「处理、拖动」。手里摆弄得动的，就是 tractable（驯服的、易处理的）。\",\"pilotage\":\"pilot 来自中世纪希腊语 pēdōtēs「舵手」一说（pēdon「舵桨」），经意大利语、法语进入英语；再加 -age。领航这件事与领航费，就是 pilotage。深层来源如实标注为一说。\",\"pasteurize\":\"以法国科学家巴斯德（Louis Pasteur）之名命名：低温杀菌法是他为葡萄酒与啤酒找到的。人名成词，就是 pasteurize（巴氏消毒）。\",\"truculence\":\"truculent 来自拉丁语 truculentus「凶野的」，源头 trux「野蛮的」（trucis）。野得好斗的，就是 truculence。\",\"subcutaneous\":\"sub-「在下」+ cutaneous「皮肤的」（源头拉丁语 cutis「皮」）拼合的医学词。皮下的，就是 subcutaneous。\",\"ubiquity\":\"ubiquitous 是按拉丁语 ubique「到处」造的词：ubi「在哪里」+ -que。哪儿都有的，就是 ubiquity（无处不在）。\",\"blazonry\":\"blazon 来自古法语 blason「盾牌、纹章」，其更深来源不确定，可能与日耳曼语有关。纹章学里满盾的图案与华丽陈列，就是 blazonry；此处对深层来源如实标注存疑。\",\"vociferate\":\"来自拉丁语 vociferari「大喊」：vox「声音」+ ferre「携带」——把声音甩出去。叫嚷，就是 vociferate。\",\"plumose\":\"来自拉丁语 plumosus「多羽的」，源头 pluma「羽毛」。羽茸茸的，就是 plumose。\",\"impecuniosity\":\"im-「无」+ pecunious「有钱的」派生：pecuniary 源头是拉丁语 pecunia「钱财」，其根 pecus「牲畜」——罗马人的财富先是牛羊。身无分文，就是 impecuniosity。\",\"eminence\":\"来自拉丁语 eminentia「突出、卓越」，源头 eminere「探出、突出」：e- + minere「伸出」。高高探出众人的一块，就是 eminence；与 imminent（探过来→迫近）同根。\",\"sinistral\":\"来自拉丁语 sinister「左边的」+ -al。左边在拉丁文化里主不祥（sinister 今义「阴险」由此来）；左向的，就是 sinistral。\",\"unbosom\":\"un-「解开」+ bosom「胸怀」构成的动词：把胸怀打开说心里话，就是 unbosom。bosom 是古英语 bōsm。\",\"liquidate\":\"来自中世纪拉丁语 liquidare「使液化、清结」，源头 liquidus「流动的」。把资产变成「流动」的钱、把账清掉，就是 liquidate。\",\"necessitous\":\"necessity + -ous：被必然压着的，就是 necessitous（贫困的、急需的）。\",\"improvidence\":\"im-「无」+ providence「远见、预备」：providence 来自拉丁语 providentia「预见」，源头 providere：pro-「预先」+ videre「看」。事先不看路的，就是 improvidence（无远见、挥霍）。\",\"bravura\":\"借自意大利语 bravura「勇敢、精湛技艺」，词干 bravo「出色的」，其更深来源有争议（一说与拉丁语 barbarus「野蛮」或 pravus「歪」有关）。乐曲里大胆炫技的段落，就是 bravura passage；深层来源如实标注存疑。\",\"mephitic\":\"来自拉丁语 mephitis「恶臭蒸汽」，是罗马人给毒气之神的名字（Mephitis）。臭气熏天的，就是 mephitic；其更深来源不确定，如实标注。\",\"oligarchical\":\"oligarchy 来自希腊语 oligarkhia「少数人统治」：oligoi「少数」+ arkhos「统治者」；再加 -ical。少数人说了算的，就是 oligarchical。\",\"coercion\":\"coerce 来自拉丁语 coercere「围住、约束」：co- + arcere「关住、拦挡」。把人圈起来逼着就范，就是 coercion；与 ark（箱、柜）的 arc- 同族。\",\"contravention\":\"contravene 来自晚期拉丁语 contravenire「违反」：contra-「反对」+ venire「来」。迎着规定走过去，就是 contravention。\",\"schlocky\":\"借自意第绪语 shlak「次品、廉价货」，其更深来源有一说与德语 Schlag「打击」或 shlogn「打」有关。粗制滥造的，就是 schlocky。如实标注。\",\"obscurant\":\"obscure 来自拉丁语 obscurus「昏暗的、难懂的」；再加 -ant「…者」。故意把知识弄暗的人，就是 obscurant（蒙昧主义者）。\",\"defamatory\":\"defame 来自拉丁语 diffamare「散布坏名声」：dis- + fama「名声」。专门坏人名声的话，就是 defamatory；fame 与它同根。\",\"tractile\":\"来自拉丁语 tractilis「可拉伸的」，源头 trahere「拉」。拉得长的，就是 tractile。\",\"lambent\":\"来自拉丁语 lambens「舔着的」，源头 lambere「舔」。火光像舌头一样轻轻舔过表面的，就是 lambent。\",\"assemblage\":\"借自法语 assemblage「集合、装配」，动词 assembler 源头是通俗拉丁语 *assimulare「聚到一起」：ad- + simul「同时、一起」。一堆东西聚到一起，就是 assemblage；与 assemble、similar 同族。\",\"cuckold\":\"来自古法语 cucuault「戴绿帽的丈夫」，源头是 cuckoo「布谷鸟」——布谷鸟把蛋下在别人巢里。妻子出轨的丈夫，英语借了布谷鸟的名。\",\"naturalize\":\"natural 来自拉丁语 naturalis「天生的」，源头 natura「天性」，其根 nasci「出生」；再加 -ize。让外来的「生」成本地的，就是 naturalize（入籍、引种）。\",\"chivvy\":\"来源不完全确定：多认为源自苏格兰边境歌谣《Chevy Chase》中的 chevy「追猎、追赶」，地名 Cheviot 是其来源。一催再催地撵人，就是 chivvy。如实标注：此说流传广但未成定论。\",\"scofflaw\":\"scoff「嘲笑」+ law 在 1924 年禁酒令时期的造词比赛中拼出：公然笑法律的人，就是 scofflaw。scoff 本身来源不完全确定，如实标注。\",\"inviolable\":\"来自拉丁语 inviolabilis「不可侵犯的」：in- + violare「侵犯、亵渎」。碰不得的，就是 inviolable。\",\"belfry\":\"中古英语 belfrey 本与 bell（钟）无关：来自古法语 berfrei「攻城塔、瞭望塔」，源头是日耳曼语「庇护之塔」。后来塔里挂了钟，拼写才被 bell 拉了过去。\",\"anagram\":\"来自希腊语 anagramma「字母重排」：ana-「重新、回」+ gramma「字母」。listen 重排成 silent，就是最经典的 anagram。\"}");
